--
-- Name: pos_terminals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pos_terminals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    branch_id uuid NOT NULL,
    fiscal_location_id uuid,
    code text NOT NULL,
    name text NOT NULL,
    external_identifier text,
    status text DEFAULT 'draft'::text NOT NULL,
    provider_code text,
    device_identifier text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_seen_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    warehouse_id uuid,
    receipt_template text DEFAULT 'corporate'::text NOT NULL,
    payment_methods jsonb DEFAULT '["cash", "card", "bank", "other", "customer_credit"]'::jsonb NOT NULL,
    cashier_shift_required boolean DEFAULT false NOT NULL,
    allow_negative_stock boolean DEFAULT false NOT NULL,
    offline_policy jsonb DEFAULT '{}'::jsonb NOT NULL,
    configuration_version integer DEFAULT 1 NOT NULL,
    fiscal_provider_config_id uuid,
    CONSTRAINT pos_terminals_configuration_version_check CHECK ((configuration_version > 0)),
    CONSTRAINT pos_terminals_offline_policy_check CHECK ((jsonb_typeof(offline_policy) = 'object'::text)),
    CONSTRAINT pos_terminals_payment_methods_check CHECK ((jsonb_typeof(payment_methods) = 'array'::text)),
    CONSTRAINT pos_terminals_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'inactive'::text, 'pending_registration'::text])))
);


--
-- Name: assert_cashier_shift_access(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assert_cashier_shift_access(p_company_id uuid, p_terminal_id uuid) RETURNS public.pos_terminals
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare terminal_row public.pos_terminals;
begin
  if not (select private.is_company_member(p_company_id)) then
    raise exception 'You do not have access to this company' using errcode = '42501';
  end if;
  terminal_row := private.resolve_pos_terminal(p_company_id, p_terminal_id);
  if terminal_row.status <> 'active' then
    raise exception 'An active POS terminal is required' using errcode = '23514';
  end if;
  return terminal_row;
end $$;


--
-- Name: assert_posted_journal_integrity(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assert_posted_journal_integrity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  line_count integer;
  debit_total numeric(20,4);
  credit_total numeric(20,4);
  period_status text;
begin
  if new.status = 'posted' then
    if new.period_id is null then
      raise exception 'A posted journal must belong to an accounting period'
        using errcode = '23514';
    end if;

    select status into period_status
    from public.accounting_periods
    where id = new.period_id and company_id = new.company_id;
    if period_status is null then
      raise exception 'A posted journal period must belong to the same company'
        using errcode = '23514';
    end if;
    if period_status not in ('open', 'soft_closed') then
      raise exception 'A journal cannot be posted into a closed or locked period'
        using errcode = '55000';
    end if;

    select count(*), coalesce(sum(debit), 0), coalesce(sum(credit), 0)
    into line_count, debit_total, credit_total
    from public.journal_entry_lines
    where journal_entry_id = new.id;
    if line_count < 2 or debit_total <= 0 or debit_total <> credit_total then
      raise exception 'Posted journal is not balanced (debits %, credits %)', debit_total, credit_total
        using errcode = '23514';
    end if;
  end if;
  return new;
end
$$;


--
-- Name: assign_sales_book_period(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assign_sales_book_period() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  old_locked boolean := false;
  target_date date;
  resolved_period public.sales_book_periods;
begin
  if tg_op = 'DELETE' then
    old_locked := private.sales_book_period_is_locked(old.sales_book_period_id);
    if old_locked and coalesce(current_setting('app.sales_book_workflow', true), '') not in ('amendment', 'migration') then
      raise exception 'Declared Sales Book invoices cannot be deleted; use an amendment or corrective document'
        using errcode = '55000';
    end if;
    return old;
  end if;

  old_locked := private.sales_book_period_is_locked(old.sales_book_period_id);
  if tg_op = 'UPDATE' and old_locked and coalesce(current_setting('app.sales_book_workflow', true), '') not in ('amendment', 'migration') then
    raise exception 'Declared Sales Book invoices cannot be edited; use an amendment or corrective document'
      using errcode = '55000';
  end if;

  if new.company_id is null then
    new.sales_book_period_id := null;
    return new;
  end if;

  target_date := coalesce(new.issue_date, new.posting_date, (timezone('Europe/Belgrade', clock_timestamp()))::date);
  resolved_period := private.ensure_sales_book_period(new.company_id, target_date, (select auth.uid()));
  if resolved_period.id is null then
    new.sales_book_period_id := null;
    return new;
  end if;
  if resolved_period.status in ('DECLARED', 'AMENDED')
     and coalesce(current_setting('app.sales_book_workflow', true), '') not in ('amendment', 'migration') then
    raise exception 'This invoice date belongs to a declared Sales Book period; use an amendment or corrective document'
      using errcode = '55000';
  end if;
  new.sales_book_period_id := resolved_period.id;
  return new;
end
$$;


--
-- Name: audit_invoice_customer_signature(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.audit_invoice_customer_signature() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT'
     and not coalesce(new.customer_signature_requested, false)
     and new.buyer_signature_url is null then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and old.customer_signature_requested is not distinct from new.customer_signature_requested
     and old.customer_signature_status is not distinct from new.customer_signature_status
     and old.customer_signature_name is not distinct from new.customer_signature_name
     and old.customer_signed_at is not distinct from new.customer_signed_at
     and old.buyer_signature_url is not distinct from new.buyer_signature_url then
    return new;
  end if;

  insert into public.audit_events (
    company_id,
    actor_user_id,
    action,
    entity_type,
    entity_id,
    entity_key,
    previous_values,
    new_values,
    reason
  ) values (
    new.company_id,
    (select auth.uid()),
    case when tg_op = 'INSERT' then 'customer_signature_requested' else 'customer_signature_updated' end,
    'invoices',
    new.id,
    new.invoice_number,
    case when tg_op = 'UPDATE' then jsonb_build_object(
      'requested', old.customer_signature_requested,
      'status', old.customer_signature_status,
      'name', old.customer_signature_name,
      'signed_at', old.customer_signed_at,
      'has_signature', old.buyer_signature_url is not null
    ) else null end,
    jsonb_build_object(
      'requested', new.customer_signature_requested,
      'status', new.customer_signature_status,
      'name', new.customer_signature_name,
      'signed_at', new.customer_signed_at,
      'has_signature', new.buyer_signature_url is not null
    ),
    'Customer acceptance captured during invoice creation'
  );
  return new;
end
$$;


--
-- Name: audit_request_ip(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.audit_request_ip() RETURNS inet
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  headers jsonb;
  candidate text;
begin
  headers := nullif(current_setting('request.headers', true), '')::jsonb;
  candidate := split_part(
    coalesce(headers ->> 'x-forwarded-for', headers ->> 'x-real-ip', ''),
    ',',
    1
  );
  if trim(candidate) = '' then
    return null;
  end if;
  return trim(candidate)::inet;
exception when others then
  return null;
end
$$;


--
-- Name: audit_table_change(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.audit_table_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  old_payload jsonb;
  new_payload jsonb;
  context_payload jsonb;
  resolved_company_id uuid;
  resolved_branch_id uuid;
  resolved_terminal_id uuid;
  resolved_entity_id uuid;
  headers jsonb;
  jwt_claims jsonb;
begin
  old_payload := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end;
  new_payload := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end;
  context_payload := coalesce(new_payload, old_payload, '{}'::jsonb);

  resolved_entity_id := nullif(context_payload ->> 'id', '')::uuid;
  resolved_company_id := case
    when tg_table_name = 'companies' then resolved_entity_id
    else nullif(context_payload ->> 'company_id', '')::uuid
  end;
  resolved_branch_id := case
    when tg_table_name = 'branches' then resolved_entity_id
    else nullif(context_payload ->> 'branch_id', '')::uuid
  end;
  resolved_terminal_id := case
    when tg_table_name = 'pos_terminals' then resolved_entity_id
    else nullif(context_payload ->> 'terminal_id', '')::uuid
  end;

  if tg_table_name = 'compliance_config_versions' then
    select config_set.company_id
    into resolved_company_id
    from public.compliance_config_sets config_set
    where config_set.id = nullif(context_payload ->> 'config_set_id', '')::uuid;
  elsif tg_table_name = 'membership_role_assignments' then
    select membership.company_id
    into resolved_company_id
    from public.memberships membership
    where membership.id = nullif(context_payload ->> 'membership_id', '')::uuid;
  elsif tg_table_name = 'app_role_permissions' then
    select role.company_id
    into resolved_company_id
    from public.app_roles role
    where role.id = nullif(context_payload ->> 'role_id', '')::uuid;
  end if;

  headers := coalesce(nullif(current_setting('request.headers', true), '')::jsonb, '{}'::jsonb);
  jwt_claims := coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);

  insert into public.audit_events (
    company_id,
    branch_id,
    terminal_id,
    actor_user_id,
    action,
    entity_type,
    entity_id,
    entity_key,
    previous_values,
    new_values,
    ip_address,
    session_identifier,
    device_identifier,
    reason,
    request_id
  )
  values (
    resolved_company_id,
    resolved_branch_id,
    resolved_terminal_id,
    (select auth.uid()),
    lower(tg_op),
    tg_table_name,
    resolved_entity_id,
    coalesce(context_payload ->> 'code', context_payload ->> 'name'),
    private.redact_audit_payload(old_payload),
    private.redact_audit_payload(new_payload),
    private.audit_request_ip(),
    coalesce(jwt_claims ->> 'session_id', jwt_claims ->> 'sid'),
    coalesce(headers ->> 'x-device-id', headers ->> 'user-agent'),
    nullif(current_setting('app.change_reason', true), ''),
    coalesce(headers ->> 'x-request-id', headers ->> 'cf-ray')
  );

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
exception
  when invalid_text_representation then
    raise exception 'Audit context contains an invalid UUID'
      using errcode = '22023';
end
$$;


--
-- Name: booking_assignment_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.booking_assignment_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- Service-role webhook/payment reconciliation is an internal operation and
  -- has no end-user JWT. Authenticated updates must remain within assignment
  -- scope even when a future command updates additional booking fields.
  if (select auth.uid()) is not null then
    if old.company_id is distinct from new.company_id then
      raise exception 'A booking organization cannot be changed' using errcode = '42501';
    end if;
    if old.staff_id is distinct from new.staff_id
       and not coalesce(private.has_company_permission(new.company_id, 'booking.scope_all'), false) then
      raise exception 'You do not have permission to reassign this booking' using errcode = '42501';
    end if;
    if not private.booking_user_can_access_staff(new.company_id, new.staff_id) then
      raise exception 'You do not have permission to manage this booking' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: booking_membership_restore_on_cancel(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.booking_membership_restore_on_cancel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status = 'cancelled' and old.status is distinct from new.status and new.membership_id is not null and coalesce(new.cancellation_fee, 0) = 0 then perform private.booking_restore_membership_credit(new.company_id, new.id); end if;
  return new;
end;
$$;


--
-- Name: booking_offer_waitlist_after_cancel(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.booking_offer_waitlist_after_cancel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status = 'cancelled' and old.status is distinct from new.status then
    perform private.booking_waitlist_offer_slot(new.company_id, new.id);
  elsif new.status <> 'cancelled'
    and old.status <> 'cancelled'
    and (old.starts_at is distinct from new.starts_at or old.ends_at is distinct from new.ends_at) then
    perform private.booking_waitlist_offer_freed_slot(
      new.company_id,
      new.id,
      old.service_id,
      old.location_id,
      old.staff_id,
      old.resource_id,
      old.starts_at,
      old.ends_at,
      old.timezone,
      old.participant_count
    );
  end if;
  return new;
end;
$$;


--
-- Name: booking_touch_updated_at(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.booking_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: booking_waitlist_offer_slot(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.booking_waitlist_offer_slot(p_company_id uuid, p_booking_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  booking_row public.bookings;
begin
  select * into booking_row
  from public.bookings booking
  where booking.company_id = p_company_id and booking.id = p_booking_id;
  if not found or booking_row.status <> 'cancelled' then return 0; end if;
  return private.booking_waitlist_offer_freed_slot(
    booking_row.company_id,
    booking_row.id,
    booking_row.service_id,
    booking_row.location_id,
    booking_row.staff_id,
    booking_row.resource_id,
    booking_row.starts_at,
    booking_row.ends_at,
    booking_row.timezone,
    booking_row.participant_count
  );
end;
$$;


--
-- Name: can_access_company_bank_account(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_access_company_bank_account(p_bank_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (select auth.uid()) is not null
    and exists (
      select 1
      from public.company_bank_accounts account
      where account.id = p_bank_account_id
        and (
          private.has_company_permission(account.company_id, 'settings.bank')
          or exists (
            select 1
            from public.company_bank_account_shares share
            where share.company_bank_account_id = account.id
              and share.is_active
              and private.has_company_permission(share.shared_company_id, 'settings.bank')
          )
        )
    );
$$;


--
-- Name: can_grant_permission(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_grant_permission(p_role_id uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select false;
$$;


--
-- Name: can_grant_role(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_grant_role(p_membership_id uuid, p_role_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.memberships target
    join public.companies company on company.id = target.company_id
    join public.app_roles role on role.id = p_role_id
    where target.id = p_membership_id
      and target.user_id <> (select auth.uid())
      and target.user_id <> company.owner_id
      and role.company_id is null
      and role.code in ('company_administrator','manager','employee')
      and private.rbac_is_tenant_admin(target.company_id)
  );
$$;


--
-- Name: can_manage_role(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_manage_role(p_role_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.app_roles role
    where role.id = p_role_id
      and role.company_id is not null
      and (select private.has_company_permission(role.company_id, 'roles.manage'))
  );
$$;


--
-- Name: can_view_fund_account(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_view_fund_account(p_fund_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.company_fund_accounts fund
    where fund.id = p_fund_account_id
      and (
        private.has_company_permission(fund.company_id, 'payment.view')
        or private.has_company_permission(fund.company_id, 'settings.bank')
        or (
          fund.company_bank_account_id is not null
          and private.can_access_company_bank_account(fund.company_bank_account_id)
        )
      )
  );
$$;


--
-- Name: capture_commercial_document_event(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.capture_commercial_document_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.company_id is null then
    return new;
  end if;

  if tg_op = 'INSERT' then
    perform private.insert_commercial_document_event(
      new.company_id, new.id, 'created', null, new.commercial_status,
      jsonb_build_object('document_number', new.invoice_number, 'document_type', new.commercial_document_type),
      new.created_at, new.user_id
    );
  elsif old.commercial_status is distinct from new.commercial_status then
    perform private.insert_commercial_document_event(
      new.company_id, new.id, 'status_changed', old.commercial_status, new.commercial_status,
      jsonb_build_object('document_number', new.invoice_number, 'document_type', new.commercial_document_type),
      clock_timestamp(), (select auth.uid())
    );
  end if;
  return new;
end
$$;


--
-- Name: carry_commercial_advance_payment_links(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.carry_commercial_advance_payment_links() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  source_link record;
begin
  if new.commercial_document_type = 'ADVANCE_INVOICE'
     and new.source_document_type = 'commercial_document'
     and new.source_document_id is not null then
    for source_link in
      select link.payment_id, link.amount, link.metadata
      from public.commercial_document_payment_links link
      where link.document_id = new.source_document_id
        and link.status = 'active'
    loop
      insert into public.document_source_links (
        company_id, source_type, source_id, target_type, target_id, link_type,
        amount, metadata, created_by
      ) values (
        new.company_id, 'payment', source_link.payment_id, 'commercial_document', new.id,
        'payment_to_advance', source_link.amount,
        coalesce(source_link.metadata, '{}'::jsonb)
          || jsonb_build_object('carried_from_document_id', new.source_document_id),
        (select auth.uid())
      ) on conflict do nothing;
    end loop;
  end if;
  return new;
end
$$;


--
-- Name: commercial_document_received_amount(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.commercial_document_received_amount(p_invoice_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with recursive document_chain(id) as (
    select p_invoice_id
    union
    select source.source_document_id
    from public.invoices source
    join document_chain chain on chain.id = source.id
    where source.source_document_type = 'commercial_document'
      and source.source_document_id is not null
  ), payment_totals as (
    select allocation.payment_id, sum(allocation.allocated_amount) as amount
    from public.payment_allocations allocation
    where allocation.invoice_id in (select id from document_chain)
      and allocation.status = 'active'
    group by allocation.payment_id
    union all
    select link.payment_id, sum(link.amount) as amount
    from public.commercial_document_payment_links link
    where link.document_id in (select id from document_chain)
      and link.status = 'active'
    group by link.payment_id
  )
  select round(coalesce(sum(payment_totals.amount), 0), 4)
  from payment_totals
$$;


--
-- Name: company_is_active(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.company_is_active(p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with recursive company_chain(id, parent_company_id, archived_at) as (
    select company.id, company.parent_company_id, company.archived_at
    from public.companies company
    where company.id = p_company_id
    union
    select parent.id, parent.parent_company_id, parent.archived_at
    from public.companies parent
    join company_chain child on child.parent_company_id = parent.id
  )
  select exists (select 1 from company_chain where id = p_company_id)
    and not exists (select 1 from company_chain where archived_at is not null);
$$;


--
-- Name: company_is_in_scope(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.company_is_in_scope(p_grant_company_id uuid, p_target_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with recursive ancestors(id) as (
    select p_target_company_id
    union
    select company.parent_company_id
    from public.companies company
    join ancestors child on child.id = company.id
    where company.parent_company_id is not null
  )
  select p_grant_company_id is not null
    and p_target_company_id is not null
    and exists (
      select 1
      from ancestors
      where ancestors.id = p_grant_company_id
    );
$$;


--
-- Name: complete_pos_sale_core(uuid, uuid, uuid, jsonb, jsonb, text, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.complete_pos_sale_core(p_company_id uuid, p_terminal_id uuid, p_customer_id uuid, p_items jsonb, p_payments jsonb, p_invoice_type text DEFAULT 'invoice'::text, p_notes text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid, p_occurred_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  terminal_row public.pos_terminals;
  invoice_row public.invoices;
  pos_order_row public.pos_orders;
  payment_row public.payments;
  item_record record;
  payment_record record;
  product_row public.products;
  resolved_customer_id uuid;
  settlement_account_id uuid;
  item_net numeric(20,4);
  item_tax numeric(20,4);
  item_gross numeric(20,4);
  subtotal_value numeric(20,4) := 0;
  tax_value numeric(20,4) := 0;
  total_value numeric(20,4) := 0;
  allocation_total numeric(20,4) := 0;
  received_total numeric(20,4) := 0;
  cash_tendered numeric(20,4) := 0;
  cash_change numeric(20,4) := 0;
  customer_outstanding numeric(20,4) := 0;
  line_number integer := 0;
  payment_index integer := 0;
  credit_payment_count integer := 0;
  price_override boolean;
  document_number text;
  payment_method_value text;
begin
  if p_company_id is null or p_idempotency_key is null then
    raise exception 'Company and idempotency key are required for POS completion' using errcode = '23514';
  end if;
  if not (select private.is_company_member(p_company_id))
    or not (select private.has_company_permission(p_company_id, 'pos.complete')) then
    raise exception 'Insufficient permission to complete POS sales' using errcode = '42501';
  end if;
  if p_invoice_type <> 'invoice' then
    raise exception 'Only an Invoice can be completed in POS; quotations, pro forma documents, and orders remain drafts' using errcode = '23514';
  end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'At least one POS item is required' using errcode = '23514';
  end if;
  if jsonb_typeof(p_payments) <> 'array' or jsonb_array_length(p_payments) = 0 then
    raise exception 'At least one POS payment is required' using errcode = '23514';
  end if;

  -- Idempotency is locked at aggregate level, so browser retries return the
  -- original canonical result without creating new invoices or payments.
  select * into pos_order_row
  from public.pos_orders
  where company_id = p_company_id and idempotency_key = p_idempotency_key
  for update;
  if found then
    if pos_order_row.status = 'completed' then
      return jsonb_build_object('order_id', pos_order_row.id, 'invoice_id', pos_order_row.invoice_id, 'order_number', pos_order_row.order_number, 'idempotent', true);
    end if;
    raise exception 'This POS completion key is already in progress' using errcode = '55P03';
  end if;

  terminal_row := private.resolve_pos_terminal(p_company_id, p_terminal_id);
  if terminal_row.branch_id is null then
    raise exception 'POS terminal must belong to a branch' using errcode = '23514';
  end if;
  resolved_customer_id := coalesce(p_customer_id, private.ensure_pos_walk_in_customer(p_company_id));
  if not exists (select 1 from public.clients where id = resolved_customer_id and company_id = p_company_id and account_status = 'active' and not sales_blocked) then
    raise exception 'The selected POS customer is not eligible for sales' using errcode = '23514';
  end if;

  for item_record in select * from jsonb_to_recordset(p_items) as item(product_id uuid, quantity numeric, unit_price numeric, discount_percent numeric)
  loop
    if item_record.product_id is null or coalesce(item_record.quantity, 0) <= 0 or coalesce(item_record.unit_price, -1) < 0 then
      raise exception 'POS items require product, positive quantity, and a non-negative unit price' using errcode = '23514';
    end if;
    select * into product_row from public.products where id = item_record.product_id and company_id = p_company_id for share;
    if not found then
      raise exception 'POS product is invalid for this company' using errcode = '23514';
    end if;
    if product_row.track_stock then
      raise exception 'Stock-tracked POS sales require the Phase D inventory posting service; this sale was blocked to protect stock and COGS integrity' using errcode = '55000';
    end if;
    price_override := round(coalesce(item_record.unit_price, 0), 4) <> round(coalesce(product_row.unit_price, 0), 4);
    if price_override and not (select private.has_company_permission(p_company_id, 'prices.override')) then
      raise exception 'Changing a POS product price requires price-override permission' using errcode = '42501';
    end if;
    if coalesce(item_record.discount_percent, 0) > 0 and not (select private.has_company_permission(p_company_id, 'discounts.override')) then
      raise exception 'Applying a POS discount requires discount permission' using errcode = '42501';
    end if;
    item_gross := round(item_record.quantity * item_record.unit_price * (1 - least(100, greatest(0, coalesce(item_record.discount_percent, 0))) / 100), 2);
    if coalesce(product_row.tax_included, false) then
      item_net := round(item_gross / (1 + coalesce(product_row.tax_rate, 0) / 100), 2);
      item_tax := round(item_net * coalesce(product_row.tax_rate, 0) / 100, 2);
      item_gross := round(item_net + item_tax, 2);
    else
      item_net := item_gross;
      item_tax := round(item_net * coalesce(product_row.tax_rate, 0) / 100, 2);
      item_gross := round(item_net + item_tax, 2);
    end if;
    subtotal_value := round(subtotal_value + item_net, 2);
    tax_value := round(tax_value + item_tax, 2);
    total_value := round(total_value + item_gross, 2);
  end loop;
  total_value := round(total_value, 2);
  if total_value <= 0 then
    raise exception 'POS total must be greater than zero' using errcode = '23514';
  end if;

  for payment_record in select * from jsonb_to_recordset(p_payments) as payment(method text, amount numeric, tendered_amount numeric, reference text, settlement_account_id uuid)
  loop
    payment_method_value := lower(coalesce(payment_record.method, ''));
    if payment_method_value not in ('cash','card','bank','other','customer_credit') then
      raise exception 'Unsupported POS payment method: %', payment_method_value using errcode = '23514';
    end if;
    if not (terminal_row.payment_methods ? payment_method_value) then
      raise exception 'The selected payment method is disabled for this terminal' using errcode = '23514';
    end if;
    if coalesce(payment_record.amount, 0) <= 0 then
      raise exception 'Each POS payment amount must be greater than zero' using errcode = '23514';
    end if;
    if payment_method_value = 'customer_credit' then
      credit_payment_count := credit_payment_count + 1;
      if p_customer_id is null then
        raise exception 'A named customer is required for a debt sale' using errcode = '23514';
      end if;
      if jsonb_array_length(p_payments) <> 1 then
        raise exception 'Debt sales cannot be combined with other payment methods' using errcode = '23514';
      end if;
      if coalesce(payment_record.tendered_amount, payment_record.amount) <> payment_record.amount then
        raise exception 'Debt sales cannot include cash change' using errcode = '23514';
      end if;
    elsif payment_method_value <> 'cash' and coalesce(payment_record.tendered_amount, payment_record.amount) <> payment_record.amount then
      raise exception 'Only cash payments may include change' using errcode = '23514';
    end if;
    if payment_method_value = 'cash' then
      if coalesce(payment_record.tendered_amount, payment_record.amount) < payment_record.amount then
        raise exception 'Cash tendered amount cannot be less than the allocated payment' using errcode = '23514';
      end if;
      cash_tendered := cash_tendered + coalesce(payment_record.tendered_amount, payment_record.amount);
    end if;
    allocation_total := round(allocation_total + round(payment_record.amount, 2), 2);
  end loop;
  if round(allocation_total, 2) <> total_value then
    raise exception 'POS payment allocations must equal the amount due' using errcode = '23514';
  end if;
  if credit_payment_count > 0 then
    select coalesce(sum(open_item.outstanding_amount), 0)
    into customer_outstanding
    from public.customer_receivable_open_items open_item
    where open_item.company_id = p_company_id
      and open_item.client_id = resolved_customer_id;
    if exists (
      select 1
      from public.clients customer
      where customer.id = resolved_customer_id
        and customer.company_id = p_company_id
        and customer.credit_limit > 0
        and customer_outstanding + total_value > customer.credit_limit
    ) then
      raise exception 'Debt sale exceeds the customer credit limit' using errcode = '23514';
    end if;
  end if;
  cash_change := round(greatest(0, cash_tendered - coalesce((select sum((payment ->> 'amount')::numeric) from jsonb_array_elements(p_payments) payment where lower(payment ->> 'method') = 'cash'), 0)), 2);
  received_total := round(allocation_total - case when credit_payment_count > 0 then total_value else 0 end, 2);

  document_number := private.next_financial_document_number(p_company_id, terminal_row.branch_id, 'pos_invoice', 'POS-', p_occurred_at::date);
  insert into public.invoices (
    user_id, company_id, branch_id, client_id, invoice_number, issue_date, due_date,
    status, approval_status, accounting_state, posting_date, currency, exchange_rate,
    discount_amount, discount_percent, tax_amount, total_amount, notes, template_id,
    type, subtype, payment_method, amount_received, change_amount, paper_size
  ) values (
    (select auth.uid()), p_company_id, terminal_row.branch_id, resolved_customer_id,
    document_number, p_occurred_at::date, p_occurred_at::date,
    'draft', 'not_required', 'legacy', p_occurred_at::date, 'EUR', 1,
    0, 0, tax_value, total_value, nullif(trim(p_notes), ''), 'corporate',
    'invoice', 'regular', 'pos', received_total, cash_change, 'A4'
  ) returning * into invoice_row;

  insert into public.pos_orders (
    company_id, branch_id, terminal_id, fiscal_location_id, warehouse_id, customer_id,
    invoice_id, order_number, status, currency, subtotal, discount_amount, tax_amount,
    total_amount, cash_received, change_amount, notes, idempotency_key, source, occurred_at,
    created_by, updated_by
  ) values (
    p_company_id, terminal_row.branch_id, terminal_row.id, terminal_row.fiscal_location_id,
    terminal_row.warehouse_id, resolved_customer_id, invoice_row.id, document_number,
    'pending_payment', 'EUR', subtotal_value, 0, tax_value, total_value, cash_tendered,
    cash_change, nullif(trim(p_notes), ''), p_idempotency_key, 'web', p_occurred_at,
    (select auth.uid()), (select auth.uid())
  ) returning * into pos_order_row;

  for item_record in select * from jsonb_to_recordset(p_items) as item(product_id uuid, quantity numeric, unit_price numeric, discount_percent numeric)
  loop
    select * into product_row from public.products where id = item_record.product_id and company_id = p_company_id;
    item_gross := round(item_record.quantity * item_record.unit_price * (1 - least(100, greatest(0, coalesce(item_record.discount_percent, 0))) / 100), 2);
    if coalesce(product_row.tax_included, false) then
      item_net := round(item_gross / (1 + coalesce(product_row.tax_rate, 0) / 100), 2);
      item_tax := round(item_net * coalesce(product_row.tax_rate, 0) / 100, 2);
      item_gross := round(item_net + item_tax, 2);
    else
      item_net := item_gross;
      item_tax := round(item_net * coalesce(product_row.tax_rate, 0) / 100, 2);
      item_gross := round(item_net + item_tax, 2);
    end if;
    line_number := line_number + 1;
    insert into public.invoice_items (invoice_id, product_id, description, quantity, unit_price, tax_rate, discount, amount, unit, sku)
    values (invoice_row.id, product_row.id, product_row.name, item_record.quantity,
      round(item_net / item_record.quantity, 4), product_row.tax_rate,
      least(100, greatest(0, coalesce(item_record.discount_percent, 0))), item_net, product_row.unit, coalesce(product_row.sku, product_row.barcode));
    insert into public.pos_order_lines (pos_order_id, company_id, product_id, line_number, description, sku, unit, quantity, unit_price, discount_percent, net_amount, tax_rate, tax_amount, gross_amount, original_unit_price, override_reason, created_by)
    values (pos_order_row.id, p_company_id, product_row.id, line_number, product_row.name,
      coalesce(product_row.sku, product_row.barcode), product_row.unit, item_record.quantity,
      item_record.unit_price, least(100, greatest(0, coalesce(item_record.discount_percent, 0))),
      item_net, product_row.tax_rate, item_tax, item_gross, product_row.unit_price,
      case when round(item_record.unit_price,4) <> round(product_row.unit_price,4) then 'POS price override' end,
      (select auth.uid()));
  end loop;

  invoice_row := public.prepare_sales_invoice_for_posting(invoice_row.id, 'POS sale completion');
  invoice_row := public.post_sales_invoice(invoice_row.id, p_idempotency_key, 'POS sale completion');

  for payment_record in select * from jsonb_to_recordset(p_payments) as payment(method text, amount numeric, tendered_amount numeric, reference text, settlement_account_id uuid)
  loop
    payment_index := payment_index + 1;
    if lower(payment_record.method) = 'customer_credit' then
      insert into public.pos_payments (pos_order_id, company_id, payment_method, allocated_amount, tendered_amount, change_amount, reference, created_by)
      values (pos_order_row.id, p_company_id, 'customer_credit', round(payment_record.amount,2),
        round(coalesce(payment_record.tendered_amount, payment_record.amount),2), 0,
        payment_record.reference, (select auth.uid()));
    else
      settlement_account_id := private.pos_default_settlement_account(p_company_id, p_occurred_at::date, payment_record.settlement_account_id);
      payment_row := public.record_customer_payment(
        p_company_id, resolved_customer_id, p_occurred_at::date, round(payment_record.amount,4),
        lower(payment_record.method), settlement_account_id, coalesce(payment_record.reference, document_number),
        'POS payment for ' || document_number, terminal_row.branch_id, 'EUR', null
      );
      perform public.allocate_customer_payment(payment_row.id, invoice_row.id, round(payment_record.amount,2), p_occurred_at::date);
      insert into public.pos_payments (pos_order_id, company_id, payment_id, payment_method, allocated_amount, tendered_amount, change_amount, settlement_account_id, reference, created_by)
      values (pos_order_row.id, p_company_id, payment_row.id, lower(payment_record.method), round(payment_record.amount,2),
        round(coalesce(payment_record.tendered_amount, payment_record.amount),2),
        case when lower(payment_record.method) = 'cash' then round(coalesce(payment_record.tendered_amount, payment_record.amount) - payment_record.amount,2) else 0 end,
        settlement_account_id, payment_record.reference, (select auth.uid()));
    end if;
  end loop;

  perform set_config('app.pos_workflow', 'authorized', true);
  update public.pos_orders
  set status = 'completed', completed_at = clock_timestamp(), completed_by = (select auth.uid()), updated_by = (select auth.uid())
  where id = pos_order_row.id
  returning * into pos_order_row;
  perform set_config('app.pos_workflow', '', true);
  insert into public.pos_order_events (pos_order_id, company_id, event_type, payload, actor_id)
  values (pos_order_row.id, p_company_id, 'completed', jsonb_build_object('invoice_id', invoice_row.id, 'invoice_number', invoice_row.invoice_number, 'total', total_value), (select auth.uid()));
  insert into public.receipt_render_snapshots (company_id, pos_order_id, invoice_id, receipt_data, template_code, created_by)
  values (p_company_id, pos_order_row.id, invoice_row.id,
    jsonb_build_object('version', 1, 'order_id', pos_order_row.id, 'order_number', document_number,
      'invoice_id', invoice_row.id, 'terminal_id', terminal_row.id, 'branch_id', terminal_row.branch_id,
      'customer_id', resolved_customer_id, 'currency', 'EUR', 'subtotal', subtotal_value,
      'tax_amount', tax_value, 'total_amount', total_value, 'cash_received', cash_tendered,
      'change_amount', cash_change, 'fiscal_status', 'not_configured', 'occurred_at', p_occurred_at),
    terminal_row.receipt_template, (select auth.uid()));
  perform private.emit_domain_outbox_event(p_company_id, terminal_row.branch_id, 'pos_order', pos_order_row.id,
    'pos_order.completed', jsonb_build_object('invoice_id', invoice_row.id, 'total_amount', total_value, 'terminal_id', terminal_row.id),
    'pos_order.completed:' || pos_order_row.id::text);
  return jsonb_build_object('order_id', pos_order_row.id, 'invoice_id', invoice_row.id, 'invoice_number', invoice_row.invoice_number, 'order_number', pos_order_row.order_number, 'total_amount', total_value, 'change_amount', cash_change, 'idempotent', false);
end
$$;


--
-- Name: control_permission_app_key(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.control_permission_app_key(p_permission text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_permission is null then null
    when p_permission like 'booking.%' or p_permission in ('calendar.manage', 'calendar.read') then 'booking'
    when p_permission like 'desk.%' or p_permission like 'workspace.%' or p_permission like 'floor.%' or p_permission like 'resource.%' or p_permission like 'reservation.%' then 'desk'
    when p_permission like 'hr.%' or p_permission like 'payroll.%' or p_permission like 'employee%' or p_permission in ('attendance.manage', 'attendance.view', 'leave.approve', 'leave.request', 'leave.types.manage', 'leave.view', 'offboarding.manage', 'offboarding.view', 'onboarding.manage', 'onboarding.view', 'performance.manage', 'performance.view', 'recruitment.manage', 'recruitment.view') then 'hr'
    when p_permission like 'support.%' then 'support'
    when p_permission like 'crm.%' then 'crm'
    when p_permission like 'invoice.%' or p_permission like 'sales_%' or p_permission like 'financial_%' or p_permission like 'accounting_%' or p_permission like 'tax_%' or p_permission like 'supplier_%' or p_permission like 'customer_%' or p_permission like 'payment%' or p_permission like 'pos.%' or p_permission in ('accounts.manage', 'asset.depreciation.post', 'asset.manage', 'asset.view', 'bank_account.view', 'bank_reconciliation.complete', 'bank_reconciliation.reopen', 'bank_statement.import', 'bank.reconcile', 'cash_account.view', 'cash_transaction.post', 'cashier_shift.close', 'compliance.manage', 'compliance.read', 'costs.view', 'discounts.override', 'document.archive.create', 'document.archive.view', 'expense.post', 'fiscal_configuration.manage', 'inventory.manage', 'inventory.view', 'journal.create', 'journal.post', 'journal.reverse', 'opening_balance.post', 'posting_rules.manage', 'prices.override', 'products.manage', 'report.read', 'reports.view', 'supplier_payment.record', 'supplier_payment.reverse', 'withholding.manage') then 'invoice'
    else null
  end;
$$;


--
-- Name: journal_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.journal_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    branch_id uuid,
    period_id uuid,
    entry_number text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    entry_type text DEFAULT 'manual'::text NOT NULL,
    posting_date date NOT NULL,
    document_date date NOT NULL,
    description text NOT NULL,
    reference text,
    source_type text,
    source_id uuid,
    source_key text,
    currency text DEFAULT 'EUR'::text NOT NULL,
    exchange_rate numeric(20,10) DEFAULT 1 NOT NULL,
    attachments jsonb DEFAULT '[]'::jsonb NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    reversal_of_id uuid,
    reversed_by_id uuid,
    posted_at timestamp with time zone,
    posted_by uuid,
    reversal_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT journal_entries_attachments_check CHECK ((jsonb_typeof(attachments) = 'array'::text)),
    CONSTRAINT journal_entries_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT journal_entries_entry_type_check CHECK ((entry_type = ANY (ARRAY['manual'::text, 'automatic'::text, 'opening'::text, 'closing'::text, 'adjustment'::text, 'reversal'::text, 'recurring'::text]))),
    CONSTRAINT journal_entries_exchange_rate_check CHECK ((exchange_rate > (0)::numeric)),
    CONSTRAINT journal_entries_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT journal_entries_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'posted'::text, 'reversed'::text])))
);


--
-- Name: create_expense_payment_journal(uuid, text, uuid, text, date, date, text, numeric, text, uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.create_expense_payment_journal(p_company_id uuid, p_source_type text, p_source_id uuid, p_source_key text, p_posting_date date, p_document_date date, p_description text, p_amount numeric, p_currency text, p_branch_id uuid, p_payment_method text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS public.journal_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  method text := lower(trim(coalesce(p_payment_method, 'bank')));
  gross numeric(20,4) := round(coalesce(p_amount, 0), 4);
  tax_total numeric(20,4);
  recoverable_vat numeric(20,4);
  nonrecoverable_vat numeric(20,4);
  expense_amount numeric(20,4);
  selected_bank_account_id uuid;
  selected_bank_account_id_for_gl uuid;
  expense_account uuid;
  input_vat_account uuid;
  settlement_account uuid;
  entry_row public.journal_entries;
  source_expense_id uuid;
  expense_description text := coalesce(nullif(trim(p_description), ''), nullif(trim(p_metadata ->> 'article'), ''), 'Expense');
  line_number integer := 0;
begin
  if method not in ('cash', 'bank') then
    raise exception 'Expense payment method must be cash or bank' using errcode = '23514';
  end if;
  if gross <= 0 then
    raise exception 'Expense amount must be greater than zero' using errcode = '23514';
  end if;

  expense_description := concat_ws(
    ' · ',
    expense_description,
    nullif(trim(p_metadata ->> 'vendor_name'), ''),
    case
      when nullif(trim(p_metadata ->> 'invoice_number'), '') is not null
        then 'Vendor invoice #' || trim(p_metadata ->> 'invoice_number')
      else null
    end
  );

  source_expense_id := coalesce(
    nullif(p_metadata ->> 'expense_id', '')::uuid,
    p_source_id
  );
  select
    round(greatest(coalesce(e.tax_amount, 0), 0), 4),
    round(greatest(coalesce(e.tax_recoverable_amount, e.tax_amount, 0), 0), 4)
  into tax_total, recoverable_vat
  from public.expenses e
  where e.id = source_expense_id;

  tax_total := round(greatest(coalesce(nullif(p_metadata ->> 'tax_amount', '')::numeric, tax_total, 0), 0), 4);
  recoverable_vat := round(greatest(coalesce(nullif(p_metadata ->> 'tax_recoverable_amount', '')::numeric, recoverable_vat, tax_total), 0), 4);
  if tax_total > gross or recoverable_vat > tax_total then
    raise exception 'Expense VAT amounts are invalid' using errcode = '23514';
  end if;
  nonrecoverable_vat := round(tax_total - recoverable_vat, 4);
  expense_amount := round(gross - recoverable_vat, 4);

  selected_bank_account_id := nullif(
    coalesce(
      nullif(p_metadata ->> 'company_bank_account_id', ''),
      nullif(current_setting('app.expense_bank_account_id', true), '')
    ),
    ''
  )::uuid;
  if method = 'bank' and selected_bank_account_id is not null then
    select account_id
      into selected_bank_account_id_for_gl
      from public.company_bank_accounts account
     where account.id = selected_bank_account_id
       and account.is_active
       and (
         account.company_id = p_company_id
         or exists (
           select 1
             from public.company_bank_account_shares share
            where share.company_bank_account_id = account.id
              and share.shared_company_id = p_company_id
              and share.is_active
         )
       );
    if not found then
      raise exception 'The selected bank account is not available for this company' using errcode = '23503';
    end if;
  end if;

  select id into expense_account
    from public.chart_of_accounts
   where company_id = p_company_id and code = '6010' and active and posting_allowed;
  if expense_account is null then
    raise exception 'General operating expense account 6010 is not configured' using errcode = '23514';
  end if;

  if recoverable_vat > 0 then
    select id into input_vat_account
      from public.chart_of_accounts
     where company_id = p_company_id and code = '1300' and active and posting_allowed;
    if input_vat_account is null then
      raise exception 'Input VAT account 1300 is not configured' using errcode = '23514';
    end if;
  end if;

  if method = 'bank' and selected_bank_account_id_for_gl is not null then
    select id into settlement_account
      from public.chart_of_accounts
     where id = selected_bank_account_id_for_gl
       and company_id = p_company_id
       and active and posting_allowed;
    if settlement_account is null then
      raise exception 'The selected bank account is not mapped to an active accounting account' using errcode = '23514';
    end if;
  else
    select id into settlement_account
      from public.chart_of_accounts
     where company_id = p_company_id
       and code = case when method = 'cash' then '1010' else '1020' end
       and active and posting_allowed;
  end if;
  if settlement_account is null then
    raise exception 'The selected cash or bank account is not configured' using errcode = '23514';
  end if;

  entry_row := public.create_journal_entry(
    p_company_id,
    p_posting_date,
    p_document_date,
    expense_description,
    p_source_key,
    upper(coalesce(nullif(trim(p_currency), ''), 'EUR')),
    1,
    p_branch_id,
    'automatic'
  );

  update public.journal_entries
     set source_type = p_source_type,
         source_id = p_source_id,
         source_key = p_source_key,
         metadata = coalesce(p_metadata, '{}'::jsonb)
           || jsonb_build_object(
                'payment_method', method,
                'net_amount', expense_amount,
                'tax_amount', tax_total,
                'tax_recoverable_amount', recoverable_vat,
                'tax_nonrecoverable_amount', nonrecoverable_vat
              ),
         updated_by = (select auth.uid())
   where id = entry_row.id
   returning * into entry_row;

  if expense_amount > 0 then
    line_number := line_number + 1;
    insert into public.journal_entry_lines (
      journal_entry_id, company_id, line_number, account_id, description,
      debit, credit, transaction_currency, transaction_amount, exchange_rate,
      branch_id, created_by
    ) values (
      entry_row.id, p_company_id, line_number, expense_account,
      expense_description,
      expense_amount, 0, upper(coalesce(nullif(trim(p_currency), ''), 'EUR')),
      expense_amount, 1, p_branch_id, (select auth.uid())
    );
  end if;
  if recoverable_vat > 0 then
    line_number := line_number + 1;
    insert into public.journal_entry_lines (
      journal_entry_id, company_id, line_number, account_id, description,
      debit, credit, transaction_currency, transaction_amount, exchange_rate,
      branch_id, tax_code, tax_amount, created_by
    ) values (
      entry_row.id, p_company_id, line_number, input_vat_account, 'Recoverable input VAT · ' || expense_description,
      recoverable_vat, 0, upper(coalesce(nullif(trim(p_currency), ''), 'EUR')),
      recoverable_vat, 1, p_branch_id,
      coalesce(nullif(p_metadata ->> 'tax_code', ''), 'domestic_purchase'),
      recoverable_vat, (select auth.uid())
    );
  end if;

  line_number := line_number + 1;
  insert into public.journal_entry_lines (
    journal_entry_id, company_id, line_number, account_id, description,
    debit, credit, transaction_currency, transaction_amount, exchange_rate,
    branch_id, created_by
  ) values (
    entry_row.id, p_company_id, line_number, settlement_account,
    case when method = 'cash' then 'Cash expense payment · ' else 'Bank expense payment · ' end || expense_description,
    0, gross, upper(coalesce(nullif(trim(p_currency), ''), 'EUR')),
    gross, 1, p_branch_id, (select auth.uid())
  );

  return public.post_journal_entry(entry_row.id, 'Expense posted');
end;
$$;


--
-- Name: create_pos_fiscal_aggregate(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.create_pos_fiscal_aggregate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  provider_config public.fiscal_provider_configs;
  payload jsonb;
  checksum text;
  fiscal_row public.fiscal_transactions;
begin
  if new.status not in ('completed','fiscal_pending')
     or old.status in ('completed','fiscal_pending','fiscal_submitted','fiscalized') then
    return new;
  end if;

  select config.*
  into provider_config
  from public.pos_terminals terminal
  join public.fiscal_provider_configs config
    on config.id = terminal.fiscal_provider_config_id
   and config.company_id = terminal.company_id
  where terminal.id = new.terminal_id
    and config.effective_from <= new.occurred_at
    and (config.effective_until is null or config.effective_until > new.occurred_at)
  limit 1;

  payload := jsonb_build_object(
    'schema_version', 1,
    'local_order_id', new.id,
    'idempotency_key', new.idempotency_key,
    'company_id', new.company_id,
    'branch_id', new.branch_id,
    'fiscal_location_id', new.fiscal_location_id,
    'terminal_id', new.terminal_id,
    'cashier_id', new.completed_by,
    'order_number', new.order_number,
    'occurred_at', new.occurred_at,
    'customer_id', new.customer_id,
    'transaction_kind', 'sale',
    'currency', new.currency,
    'subtotal', new.subtotal,
    'discount_amount', new.discount_amount,
    'vat_amount', new.tax_amount,
    'total_amount', new.total_amount,
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'line_id', line.id,
        'product_id', line.product_id,
        'sku', line.sku,
        'description', line.description,
        'quantity', line.quantity,
        'unit', line.unit,
        'unit_price', line.unit_price,
        'discount_percent', line.discount_percent,
        'net_amount', line.net_amount,
        'vat_rate', line.tax_rate,
        'vat_amount', line.tax_amount,
        'gross_amount', line.gross_amount
      ) order by line.line_number)
      from public.pos_order_lines line
      where line.pos_order_id = new.id
    ), '[]'::jsonb),
    'payments', coalesce((
      select jsonb_agg(jsonb_build_object(
        'payment_method', payment.payment_method,
        'amount', payment.allocated_amount,
        'tendered_amount', payment.tendered_amount,
        'change_amount', payment.change_amount,
        'reference', payment.reference
      ) order by payment.created_at, payment.id)
      from public.pos_payments payment
      where payment.pos_order_id = new.id
    ), '[]'::jsonb)
  );
  checksum := encode(extensions.digest(convert_to(payload::text, 'utf8'), 'sha256'), 'hex');

  insert into public.fiscal_transactions (
    company_id, branch_id, terminal_id, fiscal_location_id, pos_order_id,
    provider_config_id, provider_code, provider_configuration_version,
    payload_version, status, canonical_payload, request_checksum, occurred_at,
    created_by, updated_by
  )
  values (
    new.company_id, new.branch_id, new.terminal_id, new.fiscal_location_id, new.id,
    provider_config.id, coalesce(provider_config.provider_code, 'disabled'),
    provider_config.configuration_version, provider_config.payload_version,
    case when coalesce(provider_config.enabled, false) then 'pending_validation' else 'draft' end,
    payload, checksum, new.occurred_at, new.completed_by, new.completed_by
  )
  on conflict (pos_order_id) do nothing
  returning * into fiscal_row;

  if fiscal_row.id is not null then
    insert into public.fiscal_reconciliation_events (
      company_id, fiscal_transaction_id, event_type, new_status, details, actor_id
    )
    values (
      new.company_id, fiscal_row.id, 'aggregate_created', fiscal_row.status,
      jsonb_build_object(
        'provider_code', fiscal_row.provider_code,
        'configuration_version', fiscal_row.provider_configuration_version
      ),
      new.completed_by
    );

    perform private.emit_domain_outbox_event(
      new.company_id, new.branch_id, 'fiscal_transaction', fiscal_row.id,
      'fiscal_transaction.created',
      jsonb_build_object(
        'pos_order_id', new.id,
        'provider_code', fiscal_row.provider_code,
        'status', fiscal_row.status
      ),
      'fiscal_transaction.created:' || fiscal_row.id::text
    );
  end if;
  return new;
end
$$;


--
-- Name: derive_fiscal_installation_status(text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.derive_fiscal_installation_status(p_taxpayer_identifier text, p_business_unit_number text, p_pos_number text, p_software_solution_code text, p_fiscalization_number text, p_unique_fiscalization_code text, p_certificate_reference text, p_signing_key_reference text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when nullif(trim(coalesce(p_taxpayer_identifier, '')), '') is null
      or nullif(trim(coalesce(p_business_unit_number, '')), '') is null
      or nullif(trim(coalesce(p_pos_number, '')), '') is null
      then 'not_configured'
    when nullif(trim(coalesce(p_software_solution_code, '')), '') is null
      or nullif(trim(coalesce(p_fiscalization_number, '')), '') is null
      or nullif(trim(coalesce(p_unique_fiscalization_code, '')), '') is null
      then 'waiting_for_taxpayer'
    when nullif(trim(coalesce(p_certificate_reference, '')), '') is null
      or nullif(trim(coalesce(p_signing_key_reference, '')), '') is null
      then 'configured'
    else 'validated'
  end;
$$;


--
-- Name: desk_user_matches_auth(integer, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.desk_user_matches_auth(p_user_id integer, p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.users desk_user
    where desk_user.id = p_user_id
      and desk_user.supabase_user_id = (select auth.uid())::text
      and desk_user.company_id = p_company_id::text
  );
$$;


--
-- Name: domain_outbox_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.domain_outbox_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    branch_id uuid,
    aggregate_type text NOT NULL,
    aggregate_id uuid NOT NULL,
    event_type text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    idempotency_key text NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    published_at timestamp with time zone,
    publish_attempts integer DEFAULT 0 NOT NULL,
    last_error text,
    CONSTRAINT domain_outbox_events_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT domain_outbox_events_publish_attempts_check CHECK ((publish_attempts >= 0))
);


--
-- Name: emit_domain_outbox_event(uuid, uuid, text, uuid, text, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.emit_domain_outbox_event(p_company_id uuid, p_branch_id uuid, p_aggregate_type text, p_aggregate_id uuid, p_event_type text, p_payload jsonb, p_idempotency_key text) RETURNS public.domain_outbox_events
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  event_row public.domain_outbox_events;
begin
  insert into public.domain_outbox_events (
    company_id, branch_id, aggregate_type, aggregate_id, event_type,
    payload, idempotency_key, created_by
  )
  values (
    p_company_id, p_branch_id, p_aggregate_type, p_aggregate_id, p_event_type,
    coalesce(p_payload, '{}'::jsonb), p_idempotency_key, (select auth.uid())
  )
  on conflict (company_id, event_type, idempotency_key) do nothing
  returning * into event_row;

  if event_row.id is null then
    select *
    into event_row
    from public.domain_outbox_events
    where company_id = p_company_id
      and event_type = p_event_type
      and idempotency_key = p_idempotency_key;
  end if;
  return event_row;
end
$$;


--
-- Name: enforce_booking_public_subscription(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_booking_public_subscription() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.operix_product_access(new.company_id, 'booking') then
    raise exception 'An active OperiX Booking entitlement is required for public booking.' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_customer_cash_payment_limit(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_customer_cash_payment_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if lower(trim(coalesce(new.payment_method, ''))) = 'cash'
     and round(coalesce(new.amount, 0), 2) >= 300 then
    raise exception 'Cash payments are available only below 300.' using errcode = '23514';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_invoice_entitlement(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_invoice_entitlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target_company_id uuid;
  action text := 'canCreateInvoice';
  row_data jsonb;
begin
  if private.operix_privileged_request() or private.rbac_is_platform_admin() then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  row_data := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  if tg_table_name = 'invoice_items' then
    select invoice.company_id into target_company_id from public.invoices invoice where invoice.id = nullif(row_data ->> 'invoice_id', '')::uuid;
  elsif tg_table_name = 'companies' then
    if tg_op = 'UPDATE' and (to_jsonb(old) ->> 'archived_at') is not null and (to_jsonb(new) ->> 'archived_at') is null then
      target_company_id := new.id; action := 'canCreateTenant';
    elsif tg_op = 'INSERT' then
      target_company_id := coalesce(new.parent_company_id, new.id); action := 'canCreateTenant';
      if new.parent_company_id is null and not exists (select 1 from public.subscription_accounts where company_id = new.id) then return new; end if;
    else
      if tg_op = 'DELETE' then return old; end if;
      return new;
    end if;
  elsif tg_table_name in ('memberships', 'company_invitations', 'invitations') then
    if tg_op = 'DELETE' then return old; end if;
    if tg_table_name = 'memberships'
      and tg_op = 'UPDATE'
      and lower(coalesce(old.status, 'active')) = 'active'
      and lower(coalesce(new.status, 'active')) = 'active' then
      return new;
    end if;
    if lower(coalesce(row_data ->> 'status', 'active')) <> 'active' and tg_table_name = 'memberships' then return new; end if;
    target_company_id := nullif(row_data ->> 'company_id', '')::uuid; action := case when tg_table_name = 'memberships' then 'canInviteUser' else 'canInviteUser' end;
  else
    target_company_id := nullif(row_data ->> 'company_id', '')::uuid;
  end if;
  if target_company_id is not null then perform private.invoice_require_entitlement(target_company_id, action); end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


--
-- Name: enforce_operix_product_entitlement(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_operix_product_entitlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  row_data jsonb;
  target_company_id uuid;
  required_product text;
begin
  if private.operix_privileged_request() or private.rbac_is_platform_admin() then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  row_data := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  target_company_id := nullif(row_data ->> 'company_id', '')::uuid;
  required_product := private.product_required_for_table(tg_table_name);
  if required_product = 'any' then
    perform private.invoice_require_entitlement(target_company_id, 'canCreateTenant');
  elsif required_product = 'booking' then
    if not private.operix_product_access(target_company_id, 'booking') then raise exception 'An active OperiX Booking entitlement is required for this action.' using errcode = '42501'; end if;
  elsif required_product = 'hr' then
    if not private.operix_product_access(target_company_id, 'hr') then raise exception 'An active OperiX HR enterprise entitlement is required for this action.' using errcode = '42501'; end if;
  elsif required_product = 'desk' then
    if not private.operix_product_access(target_company_id, 'desk') then raise exception 'An active OperiX Desk enterprise entitlement is required for this action.' using errcode = '42501'; end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


