--
-- Name: subscription_trials; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.subscription_trials (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    product_or_plan text NOT NULL,
    started_at timestamp with time zone NOT NULL,
    ends_at timestamp with time zone NOT NULL,
    status text DEFAULT 'trialing'::text NOT NULL,
    consumed boolean DEFAULT false NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT subscription_trials_product_or_plan_check CHECK ((product_or_plan = ANY (ARRAY['invoice'::text, 'booking'::text, 'suite'::text]))),
    CONSTRAINT subscription_trials_status_check CHECK ((status = ANY (ARRAY['trialing'::text, 'completed'::text, 'expired'::text, 'canceled'::text])))
);


--
-- Name: ensure_operix_product_trial(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ensure_operix_product_trial(p_company_id uuid, p_plan text) RETURNS public.subscription_trials
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  root_company_id uuid;
  trial_row public.subscription_trials;
  linked_trial public.subscription_trials;
  linked_status text;
  start_time timestamptz := now();
  end_time timestamptz := now() + interval '14 days';
begin
  root_company_id := private.invoice_billing_root_company_id(p_company_id);
  if p_plan not in ('invoice', 'booking', 'suite') then
    raise exception 'Unsupported trial plan' using errcode = '22023';
  end if;

  select * into trial_row
  from public.subscription_trials
  where company_id = root_company_id and product_or_plan = p_plan
  for update;

  if trial_row.id is null then
    -- Suite is one shared trial clock. If an organization has already begun
    -- an Invoice or Booking trial (including the legacy Invoice trial seeded
    -- at workspace creation), expose the same clock to Suite instead of
    -- granting a second 14-day window. The inverse also applies when a
    -- product is opened after a Suite trial.
    if p_plan = 'suite' then
      select * into linked_trial
      from public.subscription_trials
      where company_id = root_company_id
        and product_or_plan in ('invoice', 'booking')
      order by ends_at asc, started_at asc
      limit 1;
    else
      select * into linked_trial
      from public.subscription_trials
      where company_id = root_company_id
        and product_or_plan = 'suite'
      limit 1;
    end if;

    if linked_trial.id is not null then
      linked_status := case
        when linked_trial.status = 'trialing' and linked_trial.ends_at <= now() then 'expired'
        else linked_trial.status
      end;
      insert into public.subscription_trials(
        company_id, product_or_plan, started_at, ends_at, status, consumed, metadata
      ) values (
        root_company_id,
        p_plan,
        linked_trial.started_at,
        linked_trial.ends_at,
        linked_status,
        linked_trial.consumed,
        linked_trial.metadata || jsonb_build_object('linked_trial', linked_trial.product_or_plan)
      ) on conflict (company_id, product_or_plan) do nothing
      returning * into trial_row;

      if trial_row.id is null then
        select * into trial_row
        from public.subscription_trials
        where company_id = root_company_id and product_or_plan = p_plan
        for update;
      end if;

      insert into public.subscription_accounts(
        company_id, product, status, trial_started_at, trial_ends_at, source
      ) values (
        root_company_id, p_plan, linked_status, linked_trial.started_at, linked_trial.ends_at, 'trial'
      ) on conflict (company_id, product) do nothing;
    else
      insert into public.subscription_trials(company_id, product_or_plan, started_at, ends_at, status, consumed)
      values (root_company_id, p_plan, start_time, end_time, 'trialing', false)
      on conflict (company_id, product_or_plan) do nothing
      returning * into trial_row;

      -- Two first-time summary reads can arrive concurrently. The unique
      -- constraint prevents duplication; reload the winner so both callers
      -- receive the same durable trial clock instead of a transient conflict.
      if trial_row.id is null then
        select * into trial_row
        from public.subscription_trials
        where company_id = root_company_id and product_or_plan = p_plan
        for update;
      end if;

      insert into public.subscription_accounts(
        company_id, product, status, trial_started_at, trial_ends_at, source
      ) values (
        root_company_id, p_plan, 'trialing', start_time, end_time, 'trial'
      ) on conflict (company_id, product) do nothing;
    end if;
  end if;

  return trial_row;
end;
$$;


--
-- Name: ensure_pos_walk_in_customer(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ensure_pos_walk_in_customer(p_company_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  customer_id uuid;
begin
  select id into customer_id
  from public.clients
  where company_id = p_company_id and pos_walk_in_customer
  limit 1;
  if customer_id is null then
    insert into public.clients (user_id, company_id, name, pos_walk_in_customer, account_status, sales_blocked)
    values ((select auth.uid()), p_company_id, 'Citizen', true, 'active', false)
    returning id into customer_id;
  end if;
  return customer_id;
end
$$;


--
-- Name: sales_book_periods; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sales_book_periods (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    accounting_period_id uuid,
    period_start date NOT NULL,
    period_end date NOT NULL,
    reporting_frequency text DEFAULT 'monthly'::text NOT NULL,
    status text DEFAULT 'OPEN'::text NOT NULL,
    declaration_deadline date NOT NULL,
    tax_timezone text DEFAULT 'Europe/Belgrade'::text NOT NULL,
    declared_at timestamp with time zone,
    declared_by uuid,
    declaration_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    amended_at timestamp with time zone,
    amended_by uuid,
    amendment_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT sales_book_periods_check CHECK ((period_end >= period_start)),
    CONSTRAINT sales_book_periods_check1 CHECK ((declaration_deadline > period_end)),
    CONSTRAINT sales_book_periods_reporting_frequency_check CHECK ((reporting_frequency = ANY (ARRAY['monthly'::text, 'quarterly'::text, 'annual'::text]))),
    CONSTRAINT sales_book_periods_status_check CHECK ((status = ANY (ARRAY['OPEN'::text, 'READY_FOR_DECLARATION'::text, 'DECLARED'::text, 'AMENDED'::text])))
);


--
-- Name: ensure_sales_book_period(uuid, date, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ensure_sales_book_period(p_company_id uuid, p_transaction_date date, p_actor_id uuid DEFAULT NULL::uuid) RETURNS public.sales_book_periods
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  frequency text;
  dates record;
  period_row public.sales_book_periods;
  accounting_period_id uuid;
  as_of_date date := coalesce(p_transaction_date, (timezone('Europe/Belgrade', clock_timestamp()))::date);
begin
  frequency := private.sales_book_company_frequency(p_company_id);
  if frequency is null then
    return null;
  end if;

  select * into dates from private.sales_book_period_dates(as_of_date, frequency);
  select id into accounting_period_id
  from public.accounting_periods
  where company_id = p_company_id
    and start_date = dates.period_start
    and end_date = dates.period_end
  limit 1;

  insert into public.sales_book_periods (
    company_id, accounting_period_id, period_start, period_end,
    reporting_frequency, status, declaration_deadline, tax_timezone,
    created_by, updated_by
  ) values (
    p_company_id, accounting_period_id, dates.period_start, dates.period_end,
    frequency, 'OPEN', dates.declaration_deadline, 'Europe/Belgrade',
    coalesce(p_actor_id, (select auth.uid())), coalesce(p_actor_id, (select auth.uid()))
  )
  on conflict (company_id, period_start, period_end)
  do update set
    accounting_period_id = coalesce(public.sales_book_periods.accounting_period_id, excluded.accounting_period_id),
    reporting_frequency = excluded.reporting_frequency,
    declaration_deadline = excluded.declaration_deadline,
    updated_at = clock_timestamp(),
    updated_by = coalesce(p_actor_id, (select auth.uid()))
  returning * into period_row;

  -- Month rollover is automatic, but it is intentionally only a transition to
  -- READY_FOR_DECLARATION. Declaration remains an explicit, audited action.
  perform set_config('app.sales_book_period_workflow', 'system', true);
  update public.sales_book_periods
  set status = 'READY_FOR_DECLARATION',
      updated_at = clock_timestamp(),
      updated_by = coalesce(p_actor_id, (select auth.uid()))
  where company_id = p_company_id
    and period_end < as_of_date
    and status = 'OPEN';
  perform set_config('app.sales_book_period_workflow', '', true);

  insert into public.tax_calendar_events (
    company_id, tax_type, period_start, period_end, due_date, title,
    source_reference, created_by
  ) values (
    p_company_id, 'vat', dates.period_start, dates.period_end,
    dates.declaration_deadline, 'VAT Sales Book declaration',
    'sales_book_period:' || period_row.id::text,
    coalesce(p_actor_id, (select auth.uid()))
  )
  on conflict (company_id, tax_type, period_start, period_end)
  do update set due_date = excluded.due_date;

  select * into period_row from public.sales_book_periods where id = period_row.id;
  return period_row;
end
$$;


--
-- Name: ensure_stripe_fund_account(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ensure_stripe_fund_account(p_stripe_store_id uuid, p_currency text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  store_row public.stripe_stores;
  fund_id uuid;
  normalized_currency text := upper(coalesce(nullif(trim(p_currency), ''), 'EUR'));
begin
  select * into store_row
  from public.stripe_stores
  where id = p_stripe_store_id
    and status in ('connected', 'pending')
  for update;
  if not found then
    raise exception 'Stripe store not found' using errcode = 'P0002';
  end if;
  if normalized_currency !~ '^[A-Z]{3}$' then
    raise exception 'Stripe currency is invalid' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_stripe_store_id::text || ':' || normalized_currency, 0));
  select id into fund_id
  from public.company_fund_accounts
  where stripe_store_id = p_stripe_store_id
    and currency = normalized_currency
  for update;

  if fund_id is null then
    insert into public.company_fund_accounts (
      company_id, fund_type, stripe_store_id, name, currency,
      created_by, updated_by
    ) values (
      store_row.company_id, 'bank', store_row.id,
      'Stripe · ' || store_row.store_name || ' (' || normalized_currency || ')',
      normalized_currency, store_row.created_by, store_row.created_by
    ) returning id into fund_id;
  else
    update public.company_fund_accounts
    set company_id = store_row.company_id,
        name = 'Stripe · ' || store_row.store_name || ' (' || normalized_currency || ')',
        is_active = true,
        updated_at = now()
    where id = fund_id;
  end if;
  return fund_id;
end;
$_$;


--
-- Name: expense_before_write(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.expense_before_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  vat numeric(20,4);
begin
  if new.company_id is not null and new.expense_number is null then
    new.expense_number := private.next_financial_document_number(new.company_id,new.branch_id,'expense','EXP-' || to_char(coalesce(new.date,current_date),'YYYY') || '-',coalesce(new.date,current_date));
  end if;
  new.category_code := coalesce(nullif(trim(new.category_code),''), case when lower(coalesce(new.category,'')) like '%fuel%' or lower(coalesce(new.article,'')) in ('diesel','petrol') then 'fuel' when lower(coalesce(new.category,'')) like '%rent%' then 'rent' when lower(coalesce(new.category,'')) like '%market%' then 'advertising_marketing' when lower(coalesce(new.category,'')) like '%software%' then 'software_subscriptions' when lower(coalesce(new.category,'')) like '%transport%' or lower(coalesce(new.category,'')) like '%travel%' then 'transport' when lower(coalesce(new.category,'')) like '%material%' or lower(coalesce(new.category,'')) like '%suppl%' then 'consumable_materials' else 'other_expenses' end);
  new.issue_date := coalesce(new.issue_date,new.date,current_date);
  -- Legacy correction RPCs still write `amount`; mirror that value when the
  -- expanded gross column was not explicitly supplied by the caller.
  if tg_op = 'UPDATE' and new.amount is distinct from old.amount and new.gross_amount is not distinct from old.gross_amount then
    new.gross_amount := new.amount;
  end if;
  new.gross_amount := round(coalesce(new.gross_amount,new.amount,0),4);
  new.vat_amount := round(coalesce(new.vat_amount,new.tax_amount,0),4);
  new.tax_amount := new.vat_amount;
  -- Legacy tax_recoverable_amount is retained for compatibility, but input
  -- VAT is only claimable from the separate VAT treatment calculation.
  if coalesce(current_setting('app.financial_workflow',true),'') <> 'authorized' then
    new.tax_recoverable_amount := round(coalesce(new.vat_deductible_amount,0),4);
  end if;
  new.net_amount := round(new.gross_amount - new.vat_amount,4);
  new.amount := new.gross_amount;
  new.outstanding_amount := greatest(round(new.gross_amount - coalesce(new.paid_amount,0),4),0);
  new.payment_status := case when coalesce(new.paid_amount,0) >= new.gross_amount then 'paid' when coalesce(new.paid_amount,0)>0 then 'partially_paid' when new.due_date is not null and new.due_date < current_date then 'overdue' else 'unpaid' end;
  new.updated_at := clock_timestamp();
  new.updated_by := coalesce(new.updated_by,(select auth.uid()));
  return new;
end $$;


