--
-- Name: guard_advance_aware_invoice_posting(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_advance_aware_invoice_posting() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.accounting_state = 'posted'
     and new.commercial_document_type in ('ADVANCE_INVOICE', 'FINAL_INVOICE')
     and coalesce(current_setting('app.commercial_advance_posting', true), '') <> 'authorized' then
    raise exception 'Advance and final invoices require the controlled commercial advance posting workflow'
      using errcode = '55000';
  end if;
  return new;
end
$$;


--
-- Name: has_company_permission(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.has_company_permission(p_company_id uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with requested as (
    select lower(trim(coalesce(p_permission, ''))) as permission_code,
      private.rbac_canonical_permission(p_permission) as canonical_code
  ),
  access as (
    select private.company_is_active(p_company_id) as company_active,
      private.rbac_is_platform_admin() as platform_admin,
      private.rbac_role_code(p_company_id) as actor_role,
      private.rbac_actor_membership(p_company_id) as membership_id
  ),
  role_access as (
    select access.*,
      exists (
        select 1
        from public.membership_permission_overrides override
        where override.membership_id = access.membership_id
          and override.permission_code = requested.canonical_code
          and override.enabled = false
      ) as explicitly_denied,
      exists (
        select 1
        from public.membership_permission_overrides override
        where override.membership_id = access.membership_id
          and override.permission_code = requested.canonical_code
          and override.enabled = true
      ) as explicitly_enabled,
      exists (
        select 1
        from public.membership_role_assignments assignment
        join public.app_role_permissions role_permission on role_permission.role_id = assignment.role_id
        where assignment.membership_id = access.membership_id
          and role_permission.permission_code = requested.canonical_code
      ) as role_grant
    from access cross join requested
  ),
  app_gate as (
    select private.control_permission_app_key(p_permission) as app_key
  ),
  product_gate as (
    select private.operix_product_for_permission(requested.canonical_code) as required_product
    from requested
  )
  select coalesce(role_access.company_active, false)
    and (
      role_access.platform_admin
      or (
        not private.rbac_is_platform_permission(requested.permission_code)
        and (
          role_access.actor_role = 'company_administrator'
          or (
            not role_access.explicitly_denied
            and (role_access.explicitly_enabled or role_access.role_grant)
          )
        )
      )
    )
    and (
      app_gate.app_key is null
      or role_access.platform_admin
      or (
        exists (
          select 1 from public.company_app_entitlements entitlement
          where entitlement.company_id = p_company_id
            and entitlement.app_key = app_gate.app_key
            and entitlement.enabled
        )
        and (
          role_access.actor_role = 'company_administrator'
          or exists (
            select 1 from public.memberships membership
            where membership.id = role_access.membership_id
              and coalesce(membership.status, 'active') = 'active'
              and not exists (
                select 1 from public.membership_app_access access
                where access.membership_id = membership.id
                  and access.app_key = app_gate.app_key
                  and access.enabled = false
              )
          )
        )
      )
    )
    and (
      product_gate.required_product is null
      or private.operix_product_access(p_company_id, product_gate.required_product)
    )
  from role_access
  cross join requested
  cross join app_gate
  cross join product_gate;
$$;


--
-- Name: has_unscoped_permission(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.has_unscoped_permission(p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.companies company
    where private.company_is_active(company.id)
      and private.has_company_permission(company.id, p_permission)
  );
$$;


--
-- Name: initialize_company_accounting_after_owner_membership(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.initialize_company_accounting_after_owner_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.role = 'owner'
     and new.status = 'active'
     and (select auth.uid()) is not null then
    perform public.initialize_company_accounting(
      new.company_id,
      date_trunc('year', current_date)::date,
      'xk-operix-base-v1'
    );
  end if;
  return new;
end
$$;


--
-- Name: initialize_invoice_subscription_account(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.initialize_invoice_subscription_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  root_company_id uuid;
begin
  root_company_id := coalesce(new.parent_company_id, new.id);
  perform private.ensure_operix_product_trial(root_company_id, 'invoice');
  perform private.refresh_invoice_subscription_usage(root_company_id);
  return new;
end;
$$;


--
-- Name: commercial_document_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commercial_document_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    document_id uuid NOT NULL,
    event_type text NOT NULL,
    from_status text,
    to_status text,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    actor_id uuid,
    CONSTRAINT commercial_document_events_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text))
);


--
-- Name: insert_commercial_document_event(uuid, uuid, text, text, text, jsonb, timestamp with time zone, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.insert_commercial_document_event(p_company_id uuid, p_document_id uuid, p_event_type text, p_from_status text DEFAULT NULL::text, p_to_status text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb, p_occurred_at timestamp with time zone DEFAULT now(), p_actor_id uuid DEFAULT NULL::uuid) RETURNS public.commercial_document_events
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  event_row public.commercial_document_events;
begin
  insert into public.commercial_document_events (
    company_id, document_id, event_type, from_status, to_status, payload, occurred_at, actor_id
  ) values (
    p_company_id, p_document_id, p_event_type, p_from_status, p_to_status,
    coalesce(p_payload, '{}'::jsonb), coalesce(p_occurred_at, clock_timestamp()),
    coalesce(p_actor_id, (select auth.uid()))
  ) returning * into event_row;
  return event_row;
end
$$;


--
-- Name: inventory_account(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.inventory_account(p_company_id uuid, p_code text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result uuid;
begin
  select id into result from public.chart_of_accounts where company_id=p_company_id and code=p_code and active and posting_allowed limit 1;
  if result is null then raise exception 'Inventory account % is not mapped',p_code using errcode='P0002'; end if;
  return result;
end
$$;


--
-- Name: invoice_billable_user_count(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.invoice_billable_user_count(p_root_company_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with eligible_members as (
    select distinct membership.user_id
    from public.memberships membership
    join auth.users auth_user on auth_user.id = membership.user_id
    where lower(coalesce(membership.status, 'active')) in ('active', 'suspended')
      and private.invoice_company_is_in_root(p_root_company_id, membership.company_id)
      and not exists (
        select 1 from public.user_access_operations removal
        where removal.operation_type = 'remove'
          and removal.target_membership_id = membership.id
          and removal.status in ('pending_billing', 'billing_succeeded')
          and removal.expires_at > now()
      )
      and not exists (
        select 1
        from public.membership_role_assignments assignment
        join public.app_roles assigned_role on assigned_role.id = assignment.role_id
        where assignment.membership_id = membership.id
          and lower(assigned_role.code) in ('super_admin','super_administrator','platform_owner','platform_admin','service','service_account','automation','system','internal')
      )
      and lower(coalesce(membership.role, 'employee')) not in ('super_admin','super_administrator','platform_owner','platform_admin','service','service_account','automation','system','internal')
      and not exists (
        select 1 from public.control_platform_admins platform_admin
        where platform_admin.user_id = membership.user_id and platform_admin.revoked_at is null
      )
      and lower(coalesce(auth_user.raw_app_meta_data ->> 'account_type', '')) not in ('service','service_account','automation','system','internal','platform_admin','platform_owner','super_admin','super_administrator')
      and lower(coalesce(auth_user.raw_app_meta_data ->> 'user_type', '')) not in ('service','service_account','automation','system','internal','platform_admin','platform_owner','super_admin','super_administrator')
      and lower(coalesce(auth_user.raw_app_meta_data ->> 'is_service_account', 'false')) not in ('true','1','yes')
      and lower(coalesce(auth_user.raw_app_meta_data ->> 'is_internal', 'false')) not in ('true','1','yes')
  ),
  pending_memberships as (
    select distinct membership.user_id
    from public.memberships membership
    where lower(coalesce(membership.status, 'active')) = 'pending'
      and private.invoice_company_is_in_root(p_root_company_id, membership.company_id)
      and exists (
        select 1 from public.user_access_operations operation
        where operation.operation_type = 'invite'
          and operation.target_membership_id = membership.id
          and operation.status = 'invite_pending'
          and operation.expires_at > now()
      )
  ),
  virtual_seats as (
    select operation.id
    from public.user_access_operations operation
    where operation.root_company_id = p_root_company_id
      and operation.operation_type = 'invite'
      and operation.target_membership_id is null
      and operation.status in ('pending_billing','billing_succeeded','invite_pending')
      and operation.expires_at > now()
  )
  select (select count(*) from eligible_members)
       + (select count(*) from pending_memberships)
       + (select count(*) from virtual_seats)::integer;
$$;


--
-- Name: invoice_billing_root_company_id(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.invoice_billing_root_company_id(p_company_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  root_company_id uuid;
begin
  with recursive company_chain(id, parent_company_id) as (
    select company.id, company.parent_company_id
    from public.companies company
    where company.id = p_company_id
    union all
    select parent.id, parent.parent_company_id
    from public.companies parent
    join company_chain child on child.parent_company_id = parent.id
  )
  select chain.id
    into root_company_id
  from company_chain chain
  where chain.parent_company_id is null
  limit 1;

  return coalesce(root_company_id, p_company_id);
end;
$$;


--
-- Name: invoice_company_is_in_root(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.invoice_company_is_in_root(p_root_company_id uuid, p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with recursive descendants(id) as (
    select p_root_company_id
    union all
    select company.id
    from public.companies company
    join descendants parent on company.parent_company_id = parent.id
  )
  select exists (select 1 from descendants where id = p_company_id);
$$;


--
-- Name: invoice_effective_status(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.invoice_effective_status(p_company_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  root_company_id uuid := private.invoice_billing_root_company_id(p_company_id);
  account_row public.subscription_accounts;
begin
  select * into account_row
  from public.subscription_accounts
  where company_id = root_company_id;

  if account_row.id is null then
    return 'expired';
  end if;
  if account_row.manual_override_status is not null
     and (account_row.manual_override_expires_at is null or account_row.manual_override_expires_at > now()) then
    return account_row.manual_override_status;
  end if;
  if account_row.status = 'trialing' and account_row.trial_ends_at <= now() then
    return 'expired';
  end if;
  if account_row.status = 'canceled'
     and (account_row.current_period_end is null or account_row.current_period_end <= now()) then
    return 'expired';
  end if;
  return account_row.status;
end;
$$;


--
-- Name: invoice_entitlement_allowed(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.invoice_entitlement_allowed(p_company_id uuid, p_action text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when p_action in ('canView', 'canExport', 'canManageBilling') then true
    else private.invoice_has_full_access(p_company_id)
  end;
$$;


--
-- Name: invoice_has_full_access(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.invoice_has_full_access(p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with account as (
    select subscription.*
    from public.subscription_accounts subscription
    where subscription.company_id = private.invoice_billing_root_company_id(p_company_id)
  )
  select private.invoice_manual_grant_active(private.invoice_billing_root_company_id(p_company_id))
    or exists (
      select 1
      from account
      where (account.status = 'trialing' and account.trial_ends_at > now())
         or account.status = 'active'
         or (account.status = 'canceled' and account.current_period_end > now())
         or (account.status = 'past_due' and account.grace_period_ends_at > now())
         or (
           account.manual_override_status is not null
           and (account.manual_override_expires_at is null or account.manual_override_expires_at > now())
         )
    );
$$;


--
-- Name: invoice_manual_grant_active(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.invoice_manual_grant_active(p_root_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.subscription_manual_grants grant_row
    where grant_row.company_id = p_root_company_id
      and grant_row.revoked_at is null
      and (grant_row.expires_at is null or grant_row.expires_at > now())
  );
$$;


--
-- Name: invoice_platform_admin_usage_change_trigger(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.invoice_platform_admin_usage_change_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  affected_user_id uuid;
  company_row record;
begin
  if tg_op <> 'INSERT' then
    affected_user_id := old.user_id;
    for company_row in
      select distinct membership.company_id
      from public.memberships membership
      where membership.user_id = affected_user_id
        and membership.company_id is not null
    loop
      perform private.refresh_invoice_subscription_usage(company_row.company_id);
    end loop;
  end if;
  if tg_op <> 'DELETE' then
    affected_user_id := new.user_id;
    for company_row in
      select distinct membership.company_id
      from public.memberships membership
      where membership.user_id = affected_user_id
        and membership.company_id is not null
    loop
      perform private.refresh_invoice_subscription_usage(company_row.company_id);
    end loop;
  end if;
  return coalesce(new, old);
end;
$$;


--
-- Name: invoice_require_entitlement(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.invoice_require_entitlement(p_company_id uuid, p_action text DEFAULT 'canCreateInvoice'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  required_product text := 'invoice';
begin
  if private.operix_privileged_request() or private.rbac_is_platform_admin() then return; end if;
  if p_action in ('canCreateTenant', 'canInviteUser') then
    if not private.operix_any_product_access(p_company_id) then
      raise exception 'An active OperiX product subscription is required for this action.' using errcode = '42501';
    end if;
    perform private.operix_enforce_enterprise_limits(p_company_id, p_action);
    return;
  end if;
  if not private.operix_product_access(p_company_id, required_product) then
    raise exception 'An active OperiX Invoice entitlement is required for this action.' using errcode = '42501';
  end if;
end;
$$;


--
-- Name: invoice_usage_change_trigger(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.invoice_usage_change_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  changed_company_id uuid;
begin
  if tg_table_name = 'companies' then
    changed_company_id := case when tg_op = 'DELETE' then old.id else new.id end;
    if changed_company_id is not null then
      perform private.refresh_invoice_subscription_usage(changed_company_id);
    end if;
    if tg_op = 'UPDATE' and old.parent_company_id is distinct from new.parent_company_id then
      perform private.refresh_invoice_subscription_usage(coalesce(old.parent_company_id, old.id));
      perform private.refresh_invoice_subscription_usage(coalesce(new.parent_company_id, new.id));
    end if;
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  elsif tg_table_name = 'membership_role_assignments' then
    if tg_op = 'DELETE' then
      select membership.company_id into changed_company_id
      from public.memberships membership
      where membership.id = old.membership_id;
    else
      select membership.company_id into changed_company_id
      from public.memberships membership
      where membership.id = new.membership_id;
    end if;
  else
    if tg_op = 'DELETE' then
      changed_company_id := nullif(to_jsonb(old) ->> 'company_id', '')::uuid;
    else
      changed_company_id := nullif(to_jsonb(new) ->> 'company_id', '')::uuid;
    end if;
  end if;
  if changed_company_id is not null then
    perform private.refresh_invoice_subscription_usage(changed_company_id);
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: is_company_member(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_company_member(p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.can_access_company(p_company_id);
$$;


--
-- Name: next_financial_document_number(uuid, uuid, text, text, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.next_financial_document_number(p_company_id uuid, p_branch_id uuid, p_document_type text, p_default_prefix text, p_document_date date) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  sequence_row public.document_sequences;
  period_key text;
  next_number text;
begin
  if p_company_id is null or nullif(trim(p_document_type), '') is null then
    raise exception 'Company and document type are required for document numbering'
      using errcode = '22023';
  end if;

  period_key := to_char(coalesce(p_document_date, current_date), 'YYYY');

  insert into public.document_sequences (
    company_id, branch_id, document_type, prefix, suffix, next_value,
    padding, reset_rule, current_period_key, is_active, created_by, updated_by
  )
  values (
    p_company_id, p_branch_id, p_document_type, coalesce(p_default_prefix, ''),
    '', 1, 6, 'fiscal_year', period_key, true, (select auth.uid()), (select auth.uid())
  )
  on conflict do nothing;

  select *
  into sequence_row
  from public.document_sequences
  where company_id = p_company_id
    and branch_id is not distinct from p_branch_id
    and document_type = p_document_type
    and is_active
  order by updated_at desc
  limit 1
  for update;

  if not found then
    raise exception 'No active document sequence configured for %', p_document_type
      using errcode = 'P0002';
  end if;

  if sequence_row.reset_rule = 'fiscal_year'
    and sequence_row.current_period_key is distinct from period_key then
    update public.document_sequences
    set next_value = 2,
        current_period_key = period_key,
        updated_at = clock_timestamp(),
        updated_by = (select auth.uid())
    where id = sequence_row.id;
    next_number := coalesce(sequence_row.prefix, '') || lpad('1', sequence_row.padding, '0') || coalesce(sequence_row.suffix, '');
  else
    update public.document_sequences
    set next_value = next_value + 1,
        updated_at = clock_timestamp(),
        updated_by = (select auth.uid())
    where id = sequence_row.id;
    next_number := coalesce(sequence_row.prefix, '')
      || lpad(sequence_row.next_value::text, sequence_row.padding, '0')
      || coalesce(sequence_row.suffix, '');
  end if;

  return next_number;
end
$$;


--
-- Name: next_journal_number(uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.next_journal_number(p_company_id uuid, p_posting_date date) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  next_number bigint;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text || ':journal:' || extract(year from p_posting_date)::text, 0));
  select coalesce(max(
    nullif(regexp_replace(entry_number, '^JE-[0-9]{4}-', ''), '')::bigint
  ), 0) + 1
  into next_number
  from public.journal_entries
  where company_id = p_company_id
    and entry_number like 'JE-' || extract(year from p_posting_date)::text || '-%'
    and entry_number ~ '^JE-[0-9]{4}-[0-9]+$';
  return 'JE-' || extract(year from p_posting_date)::text || '-' || lpad(next_number::text, 6, '0');
end
$_$;


--
-- Name: normalize_commercial_document_identity(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.normalize_commercial_document_identity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  legacy_type text := lower(coalesce(new.type, 'invoice'));
  legacy_subtype text := lower(coalesce(new.subtype, 'regular'));
begin
  -- A compatibility insert that only supplies type/subtype must still receive
  -- a canonical identity. An explicit non-INVOICE identity always wins.
  if new.commercial_document_type is null
     or (new.commercial_document_type = 'INVOICE' and (legacy_type <> 'invoice' or legacy_subtype <> 'regular')) then
    new.commercial_document_type := case
      when legacy_subtype = 'offer' or (legacy_type = 'offer' and legacy_subtype = 'regular') then 'QUOTE'
      when legacy_subtype in ('pro_invoice', 'proforma') or legacy_type = 'proforma' then 'PROFORMA'
      when legacy_subtype = 'order' then 'SALES_ORDER'
      when legacy_subtype = 'delivery_note' then 'DELIVERY_NOTE'
      when legacy_subtype = 'advance_invoice' then 'ADVANCE_INVOICE'
      when legacy_subtype = 'final_invoice' then 'FINAL_INVOICE'
      when legacy_subtype = 'credit_note' then 'CREDIT_NOTE'
      when legacy_subtype = 'debit_note' then 'DEBIT_NOTE'
      when legacy_subtype = 'simplified_invoice' then 'SIMPLIFIED_INVOICE'
      when legacy_subtype = 'fiscal_receipt' then 'FISCAL_RECEIPT'
      when legacy_subtype = 'bad_debt_invoice' then 'BAD_DEBT_INVOICE'
      else 'INVOICE'
    end;
  end if;
  new.commercial_status := coalesce(new.commercial_status, 'DRAFT');
  return new;
end
$$;


--
-- Name: normalize_commercial_line_quantities(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.normalize_commercial_line_quantities() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  document_type text;
begin
  select commercial_document_type into document_type from public.invoices where id = new.invoice_id;
  if document_type = 'SALES_ORDER' then
    new.ordered_quantity := case when coalesce(new.ordered_quantity, 0) = 0 then coalesce(new.quantity, 0) else new.ordered_quantity end;
    new.remaining_quantity := greatest(0, new.ordered_quantity - coalesce(new.delivered_quantity, 0));
  elsif document_type = 'DELIVERY_NOTE' then
    new.delivered_quantity := case when coalesce(new.delivered_quantity, 0) = 0 then coalesce(new.quantity, 0) else new.delivered_quantity end;
  end if;
  return new;
end
$$;


--
-- Name: normalize_invoice_item_tax_representation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.normalize_invoice_item_tax_representation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  product_row public.products;
  gross_after_discount numeric;
  discount_factor numeric;
begin
  if new.product_id is null or coalesce(new.tax_included, false) then
    return new;
  end if;

  select * into product_row
  from public.products
  where id = new.product_id;
  if not found or not coalesce(product_row.tax_included, false) then
    return new;
  end if;

  discount_factor := 1 - least(100, greatest(0, coalesce(new.discount, 0))) / 100;
  if coalesce(new.quantity, 0) > 0 and discount_factor > 0 then
    gross_after_discount := coalesce(new.amount, 0) *
      (1 + coalesce(new.tax_rate, product_row.tax_rate, 0) / 100);
    new.unit_price := round(gross_after_discount / new.quantity / discount_factor, 4);
  end if;
  new.tax_included := true;
  return new;
end
$$;


--
-- Name: operix_any_product_access(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.operix_any_product_access(p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.operix_product_access(p_company_id, 'invoice')
      or private.operix_product_access(p_company_id, 'booking')
      or private.operix_product_access(p_company_id, 'hr')
      or private.operix_product_access(p_company_id, 'desk');
$$;


--
-- Name: operix_company_uuid(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.operix_company_uuid(p_value text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if p_value is null or p_value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    return null;
  end if;
  return p_value::uuid;
exception when invalid_text_representation then
  return null;
end;
$_$;


--
-- Name: operix_effective_status(text, timestamp with time zone, timestamp with time zone, timestamp with time zone, text, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.operix_effective_status(p_status text, p_trial_ends_at timestamp with time zone, p_period_end timestamp with time zone, p_grace_ends_at timestamp with time zone, p_manual_status text DEFAULT NULL::text, p_manual_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when p_manual_status is not null
      and (p_manual_expires_at is null or p_manual_expires_at > now()) then p_manual_status
    when p_status = 'trialing' and (p_trial_ends_at is null or p_trial_ends_at <= now()) then 'expired'
    when p_status = 'canceled' and (p_period_end is null or p_period_end <= now()) then 'expired'
    else coalesce(p_status, 'expired')
  end;
$$;


--
-- Name: operix_enforce_enterprise_limits(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.operix_enforce_enterprise_limits(p_company_id uuid, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  root_company_id uuid;
  active_tenants integer;
  active_users integer;
  limit_row record;
begin
  root_company_id := private.invoice_billing_root_company_id(p_company_id);

  select count(*)::integer
    into active_tenants
  from public.companies company
  where private.invoice_company_is_in_root(root_company_id, company.id)
    and company.archived_at is null
    and lower(coalesce(company.settings ->> 'status', 'active')) not in ('archived', 'deleted', 'suspended', 'disabled', 'inactive')
    and lower(coalesce(company.settings ->> 'is_internal', 'false')) not in ('true', '1', 'yes')
    and lower(coalesce(company.settings ->> 'is_demo', 'false')) not in ('true', '1', 'yes')
    and nullif(company.settings ->> 'deleted_at', '') is null
    and nullif(company.settings ->> 'suspended_at', '') is null;

  active_users := private.invoice_billable_user_count(root_company_id);

  for limit_row in
    select contract.tenant_limit, contract.seat_limit
    from public.enterprise_contracts contract
    where contract.company_id = root_company_id
      and contract.status in ('trialing', 'active')
      and contract.starts_at <= now()
      and (contract.ends_at is null or contract.ends_at > now())
      and (contract.trial_ends_at is null or contract.trial_ends_at > now() or contract.status = 'active')
  loop
    if p_action = 'canCreateTenant'
      and limit_row.tenant_limit is not null
      and active_tenants >= limit_row.tenant_limit then
      raise exception 'The enterprise tenant limit has been reached.' using errcode = '42501';
    end if;
    if p_action = 'canInviteUser'
      and limit_row.seat_limit is not null
      and active_users >= limit_row.seat_limit then
      raise exception 'The enterprise seat limit has been reached.' using errcode = '42501';
    end if;
  end loop;
end;
$$;


--
-- Name: operix_hr_audit_event(text, text); Type: FUNCTION; Schema: private; Owner: -
