    'hr'
  );
$$;


--
-- Name: operix_plan_value(text, text, integer, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.operix_plan_value(p_plan text, p_interval text, p_billable_tenants integer, p_billable_users integer) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  select case when p_interval = 'annual' then
    case p_plan when 'invoice' then 29.99 when 'booking' then 49.99 when 'suite' then 49.99 else 0 end
      + coalesce(p_billable_tenants, 0) * 19.99
      + coalesce(p_billable_users, 0) * 9.99
  else
    case p_plan when 'invoice' then 2.99 when 'booking' then 4.99 when 'suite' then 4.99 else 0 end
      + coalesce(p_billable_tenants, 0) * 1.99
      + coalesce(p_billable_users, 0) * 0.99
  end;
$$;


--
-- Name: operix_privileged_request(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.operix_privileged_request() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
