    or coalesce(current_setting('request.jwt.claim.role', true), '') in ('service_role', 'supabase_admin');
$$;


--
-- Name: operix_product_access(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.operix_product_access(p_company_id uuid, p_product text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with requested as (
    select lower(trim(coalesce(p_product, ''))) as product
  ),
  root as (
    select private.invoice_billing_root_company_id(p_company_id) as company_id
  )
  select exists (
    select 1
    from public.organization_product_entitlements entitlement
    join root on root.company_id = entitlement.company_id
    cross join requested
    where entitlement.product = requested.product
      and entitlement.enabled
      and entitlement.starts_at <= now()
      and (entitlement.ends_at is null or entitlement.ends_at > now())
      and (
        requested.product not in ('hr', 'desk')
        or entitlement.source in ('enterprise_contract', 'manual_grant', 'internal')
      )
  )
  or exists (
    select 1
    from public.subscription_accounts account
    join root on root.company_id = account.company_id
    cross join requested
    where requested.product not in ('hr', 'desk')
      and (
        account.product = requested.product
        or (account.product = 'suite' and requested.product in ('invoice', 'booking'))
      )
      and private.operix_status_has_access(
        account.status,
        account.trial_ends_at,
        account.current_period_end,
        account.grace_period_ends_at,
        account.manual_override_status,
        account.manual_override_expires_at
      )
  )
  or exists (
    select 1
    from public.enterprise_contract_products contract_product
    join public.enterprise_contracts contract on contract.id = contract_product.contract_id
    join root on root.company_id = contract.company_id
    cross join requested
    where contract_product.product = requested.product
      and requested.product in ('hr', 'desk')
      and contract_product.enabled
      and contract.status in ('trialing', 'active')
      and contract.starts_at <= now()
      and (contract.ends_at is null or contract.ends_at > now())
      and (contract.trial_ends_at is null or contract.trial_ends_at > now() or contract.status = 'active')
  )
  or exists (
    select 1
    from public.subscription_manual_grants grant_row
    join root on root.company_id = grant_row.company_id
    cross join requested
    where grant_row.product = requested.product
      and requested.product in ('hr', 'desk')
      and coalesce(grant_row.override_status, 'active') in ('active', 'trialing')
      and grant_row.revoked_at is null
      and (grant_row.expires_at is null or grant_row.expires_at > now())
  )
  or exists (
    select 1
    from public.subscription_manual_grants grant_row
    join root on root.company_id = grant_row.company_id
    cross join requested
    where grant_row.product = 'suite'
      and requested.product in ('invoice', 'booking', 'suite')
      and coalesce(grant_row.override_status, 'active') in ('active', 'trialing')
      and grant_row.revoked_at is null
      and (grant_row.expires_at is null or grant_row.expires_at > now())
  );
$$;


--
-- Name: operix_product_for_permission(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.operix_product_for_permission(p_permission text) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when lower(trim(coalesce(p_permission, ''))) like any (array[
      'hr.%', 'payroll.%', 'employees.%', 'attendance.%', 'leave.%',
      'recruitment.%', 'performance.%', 'onboarding.%', 'offboarding.%'
    ]) then 'hr'
    when lower(trim(coalesce(p_permission, ''))) like any (array[
      'desk.%', 'reservation.%', 'floor.%', 'resource.%', 'team.%'
    ]) then 'desk'
    else null
  end;
$$;


--
-- Name: operix_server_request(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.operix_server_request() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(nullif(current_setting('request.jwt.claim.role', true), ''),
                  nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role')
         in ('service_role', 'supabase_admin');
$$;


--
-- Name: operix_status_has_access(text, timestamp with time zone, timestamp with time zone, timestamp with time zone, text, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.operix_status_has_access(p_status text, p_trial_ends_at timestamp with time zone, p_period_end timestamp with time zone, p_grace_ends_at timestamp with time zone, p_manual_status text DEFAULT NULL::text, p_manual_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when p_manual_status is not null
      and (p_manual_expires_at is null or p_manual_expires_at > now())
      and p_manual_status in ('active', 'trialing') then true
    when p_status = 'trialing' then p_trial_ends_at > now()
    when p_status = 'active' then true
    when p_status = 'canceled' then p_period_end > now()
    when p_status = 'past_due' then p_grace_ends_at > now()
    else false
  end;
$$;


