-- Name: payroll_feature_enabled(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.payroll_feature_enabled(p_company_id uuid, p_flag text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select enabled from public.company_feature_flags
    where company_id=p_company_id and flag=p_flag
  ),false)
$$;


--
-- Name: payroll_mapping_account(uuid, text, date, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.payroll_mapping_account(p_company_id uuid, p_code text, p_posting_date date, p_branch_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result uuid;
begin
  select account_id into result from public.payroll_posting_mappings
  where company_id=p_company_id and mapping_code=p_code and active
    and effective_from<=p_posting_date and (effective_until is null or effective_until>=p_posting_date)
    and (branch_id is null or branch_id=p_branch_id)
  order by (branch_id is not null) desc,effective_from desc limit 1;
  if result is null then raise exception 'Missing effective payroll posting mapping: %',p_code using errcode='P0002'; end if;
  return result;
end $$;


--
-- Name: payroll_table_company_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.payroll_table_company_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare employee_company uuid;
begin
  if new.employee_id is not null then
    select company_id into employee_company from public.employees where id=new.employee_id;
    if employee_company is distinct from new.company_id then
      raise exception 'Payroll employee must belong to the same company' using errcode='23514';
    end if;
  end if;
  return new;
end $$;


--
-- Name: pos_default_settlement_account(uuid, date, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.pos_default_settlement_account(p_company_id uuid, p_payment_date date, p_requested_account_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  resolved_account_id uuid;
begin
  if p_requested_account_id is not null then
    select account.id into resolved_account_id
    from public.chart_of_accounts account
    where account.id = p_requested_account_id
      and account.company_id = p_company_id
      and account.active and account.posting_allowed;
  else
    select line.account_id into resolved_account_id
    from public.posting_rule_sets rule_set
    join public.posting_rule_lines line on line.rule_set_id = rule_set.id
    join public.chart_of_accounts account on account.id = line.account_id
    where rule_set.company_id = p_company_id
      and rule_set.event_type = 'customer_payment'
      and rule_set.active
      and rule_set.effective_from <= p_payment_date
      and (rule_set.effective_until is null or rule_set.effective_until >= p_payment_date)
      and line.side = 'debit'
      and line.amount_component = 'gross'
      and account.active and account.posting_allowed
    order by rule_set.version desc, rule_set.effective_from desc, line.line_number
    limit 1;
  end if;
  if resolved_account_id is null then
    raise exception 'No active settlement account is mapped for POS customer payments' using errcode = '23514';
  end if;
  return resolved_account_id;
end
$$;


--
-- Name: prevent_active_company_hijack(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_active_company_hijack() RETURNS trigger
    LANGUAGE plpgsql
