--
-- Name: prevent_cashier_shift_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_cashier_shift_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_table_name in ('cashier_shift_movements', 'cashier_shift_events') then
    raise exception '% records are append-only', tg_table_name using errcode = '55000';
  end if;

  if tg_op = 'DELETE' then
    raise exception 'Cashier shifts cannot be deleted' using errcode = '55000';
  end if;

  if old.status = 'closed'
     and coalesce(current_setting('app.cashier_shift_workflow', true), '') <> 'authorized' then
    raise exception 'Closed cashier shifts are immutable; use the authorized reopen workflow'
      using errcode = '55000';
  end if;

  return new;
end
$$;


--
-- Name: prevent_commercial_document_event_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_commercial_document_event_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if coalesce(current_setting('app.commercial_document_events_workflow', true), '') <> 'authorized' then
    raise exception 'Commercial document events are immutable' using errcode = '55000';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end
$$;


--
-- Name: prevent_company_hierarchy_cycle(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_company_hierarchy_cycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  cycle_found boolean;
begin
  if new.parent_company_id is null then
    return new;
  end if;

  if new.parent_company_id = new.id then
    raise exception 'A company cannot be its own subdivision parent'
      using errcode = '23514';
  end if;

  with recursive ancestors(id) as (
    select new.parent_company_id
    union
    select company.parent_company_id
    from public.companies company
    join ancestors child on child.id = company.id
    where company.parent_company_id is not null
  )
  select exists (
    select 1
    from ancestors
    where ancestors.id = new.id
  )
  into cycle_found;

  if cycle_found then
    raise exception 'Moving this company would create a hierarchy cycle'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


--
-- Name: prevent_company_owner_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_company_owner_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.owner_id is distinct from old.owner_id
     and (
       coalesce(current_setting('app.company_owner_transfer', true), '') <> 'authorized'
       or old.owner_id is distinct from (select auth.uid())
     ) then
    raise exception 'Use the authorized owner-transfer workflow'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: prevent_completed_pos_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_completed_pos_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  linked_status text;
begin
  if tg_table_name = 'pos_orders' then
    if old.status in ('completed','partially_refunded','refunded','fiscalized','reversed')
      and current_setting('app.pos_workflow', true) is distinct from 'authorized' then
      raise exception 'Completed POS orders are immutable; use a return, refund, or correction workflow'
        using errcode = '55000';
    end if;
  else
    select status into linked_status from public.pos_orders where id = coalesce(old.pos_order_id, new.pos_order_id);
    if linked_status in ('completed','partially_refunded','refunded','fiscalized','reversed')
      and current_setting('app.pos_workflow', true) is distinct from 'authorized' then
      raise exception 'Completed POS order details are immutable' using errcode = '55000';
    end if;
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end
$$;


--
-- Name: prevent_declared_sales_book_customer_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_declared_sales_book_customer_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1
    from public.invoices invoice
    where invoice.client_id = case when tg_op = 'DELETE' then old.id else new.id end
      and private.sales_book_period_is_locked(invoice.sales_book_period_id)
  ) and coalesce(current_setting('app.sales_book_workflow', true), '') not in ('amendment', 'migration') then
    raise exception 'Customer data used by a declared Sales Book cannot be changed directly; use an amendment'
      using errcode = '55000';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end
$$;


--
-- Name: prevent_declared_sales_book_item_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_declared_sales_book_item_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  invoice_id uuid := case when tg_op = 'DELETE' then old.invoice_id else new.invoice_id end;
  period_id uuid;
begin
  select invoice.sales_book_period_id into period_id from public.invoices invoice where invoice.id = invoice_id;
  if private.sales_book_period_is_locked(period_id)
     and coalesce(current_setting('app.sales_book_workflow', true), '') not in ('amendment', 'migration') then
    raise exception 'Declared Sales Book invoice lines cannot be changed; use an amendment or corrective document'
      using errcode = '55000';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end
$$;


