--
-- Name: prevent_employee_invoice_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_employee_invoice_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  old_status text := upper(coalesce(old.commercial_status, old.status::text, 'DRAFT'));
begin
  if old.company_id is not null
     and public.get_my_company_role(old.company_id) = 'employee'
     and coalesce(current_setting('app.document_create_workflow', true), '') <> 'authorized'
     and coalesce(current_setting('app.invoice_auxiliary_workflow', true), '') <> 'authorized'
     and coalesce(current_setting('app.financial_workflow', true), '') <> 'authorized'
     and (
       old_status not in ('DRAFT', 'SENT', 'VIEWED')
       or not private.rbac_can_read_resource(
         old.company_id, 'invoice', old.user_id, old.assigned_user_id, 'invoice.edit'
       )
     ) then
    raise exception 'Employees may edit only invoices in their permitted draft scope'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: prevent_fiscal_record_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_fiscal_record_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_table_name in ('fiscal_submission_attempts','fiscal_reconciliation_events') then
    raise exception '% records are append-only', tg_table_name using errcode = '55000';
  end if;
  if tg_op = 'DELETE' then
    raise exception 'Fiscal transactions cannot be deleted' using errcode = '55000';
  end if;
  if coalesce(current_setting('app.fiscal_workflow', true), '') <> 'authorized' then
    raise exception 'Fiscal transactions may only change through the fiscal workflow'
      using errcode = '55000';
  end if;
  return new;
end
$$;


--
-- Name: prevent_locked_expense_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_locked_expense_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare period_status text; book_status text; workflow_authorized boolean := coalesce(current_setting('app.financial_workflow',true),'')='authorized';
begin
  if tg_op='UPDATE' and not workflow_authorized and new.company_id is not null then
    if (new.tax_treatment is distinct from old.tax_treatment or new.tax_deductible_percentage is distinct from old.tax_deductible_percentage or new.tax_deductible_amount is distinct from old.tax_deductible_amount or new.tax_override_reason is distinct from old.tax_override_reason) and not private.has_company_permission(new.company_id,'expense.tax.override') then
      raise exception 'Tax treatment changes require the expense tax override permission' using errcode='42501';
    end if;
    if (new.vat_treatment is distinct from old.vat_treatment or new.vat_deductible_percentage is distinct from old.vat_deductible_percentage or new.vat_deductible_amount is distinct from old.vat_deductible_amount or new.vat_override_reason is distinct from old.vat_override_reason) and not private.has_company_permission(new.company_id,'expense.vat.override') then
      raise exception 'VAT treatment changes require the expense VAT override permission' using errcode='42501';
    end if;
  end if;
  select status into period_status from public.accounting_periods where id=coalesce(new.accounting_period_id,old.accounting_period_id);
  select status into book_status from public.sales_book_periods where id=coalesce(new.sales_book_period_id,old.sales_book_period_id);
  if not workflow_authorized and not private.has_company_permission(coalesce(new.company_id,old.company_id),'expense.period.reopen') and (period_status in ('closed','locked') or book_status in ('DECLARED','LOCKED')) then
    raise exception 'This expense belongs to a closed accounting or Purchase Book period' using errcode='55000';
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $$;


--
-- Name: prevent_non_admin_invoice_delete(); Type: FUNCTION; Schema: private; Owner: -
