     or not coalesce(private.has_company_permission(old.company_id, 'sales_invoice.delete'), false) then
    raise exception 'Only company administrators can delete invoices'
      using errcode = '42501';
  end if;
  return old;
end;
$$;


--
-- Name: prevent_offline_record_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_offline_record_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'POS device and offline synchronization history cannot be deleted'
      using errcode = '55000';
  end if;
  if coalesce(current_setting('app.offline_sync_workflow', true), '') <> 'authorized' then
    raise exception 'POS device and offline synchronization records may only change through authorized commands'
      using errcode = '55000';
  end if;
  return new;
end
$$;


--
-- Name: prevent_overlapping_compliance_versions(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_overlapping_compliance_versions() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.status = 'active' and exists (
    select 1
    from public.compliance_config_versions existing
    where existing.config_set_id = new.config_set_id
      and existing.status = 'active'
      and existing.id <> new.id
      and daterange(
        existing.effective_from,
        coalesce(existing.effective_until + 1, 'infinity'::date),
        '[)'
      ) && daterange(
        new.effective_from,
        coalesce(new.effective_until + 1, 'infinity'::date),
        '[)'
      )
  ) then
    raise exception 'Active compliance configuration periods cannot overlap'
      using errcode = '23P01';
  end if;
  return new;
end
$$;


--
-- Name: prevent_posted_financial_document_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_posted_financial_document_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  workflow_authorized boolean := coalesce(current_setting('app.financial_workflow', true), '') = 'authorized';
  auxiliary_workflow_authorized boolean := tg_table_name = 'invoices'
    and coalesce(current_setting('app.invoice_auxiliary_workflow', true), '') = 'authorized';
  prior_state text;
begin
  if tg_table_name = 'invoice_items' then
    select invoice.accounting_state
    into prior_state
    from public.invoices invoice
    where invoice.id = old.invoice_id;
  elsif tg_table_name = 'supplier_bill_items' then
    select bill.accounting_state
    into prior_state
    from public.supplier_bills bill
    where bill.id = old.bill_id;
  else
    prior_state := to_jsonb(old) ->> 'accounting_state';
  end if;

  prior_state := coalesce(prior_state, 'legacy');
  if prior_state in ('posted', 'reversed', 'opening_balance')
     and not workflow_authorized
     and not auxiliary_workflow_authorized then
    raise exception 'Posted financial records are immutable; use a correction or reversal workflow'
      using errcode = '55000';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


--
-- Name: prevent_profile_company_hijack(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_profile_company_hijack() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
