--
-- Name: prevent_stock_invoice_item_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_stock_invoice_item_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target_invoice_id uuid;
begin
  target_invoice_id := case when tg_op = 'DELETE' then old.invoice_id else new.invoice_id end;
  if exists (
    select 1
    from public.inventory_stock_movements movement
    where movement.invoice_id = target_invoice_id
  )
  and coalesce(current_setting('app.invoice_delete_workflow', true), '') <> 'authorized'
  and coalesce(current_setting('app.product_delete_workflow', true), '') <> 'authorized' then
    raise exception 'Stock-tracked invoice lines cannot be edited after checkout'
      using errcode = '55000';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


--
-- Name: prevent_terminal_held_order_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_terminal_held_order_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'Held-order history cannot be deleted' using errcode = '55000';
  end if;
  if old.status <> 'held'
     and coalesce(current_setting('app.held_order_workflow', true), '') <> 'authorized' then
    raise exception 'Finalized held orders are immutable' using errcode = '55000';
  end if;
  if new.version <> old.version + 1 then
    raise exception 'Held-order version must increment exactly once' using errcode = '40001';
  end if;
  return new;
end
$$;


--
-- Name: prevent_unsafe_role_assignment(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_unsafe_role_assignment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is null
     or coalesce(current_setting('app.membership_role_workflow', true), '') = 'authorized' then
    return new;
  end if;

  if not private.can_grant_role(new.membership_id, new.role_id) then
    raise exception 'You cannot grant this organization role'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: product_required_for_table(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.product_required_for_table(p_table_name text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
begin
  if p_table_name in ('companies', 'memberships', 'company_invitations', 'invitations', 'membership_role_assignments') then
    return 'any';
  end if;
  if p_table_name in ('booking_services', 'booking_service_categories', 'booking_locations', 'booking_resources', 'booking_staff', 'booking_staff_services', 'booking_resource_services', 'booking_working_hours', 'booking_availability_exceptions', 'booking_blocked_times', 'booking_settings', 'booking_recurring_series', 'bookings', 'booking_participants', 'booking_status_history', 'booking_payments', 'booking_waitlist', 'booking_reminders', 'booking_notification_log', 'booking_audit_log', 'booking_public_attempts') then
    return 'booking';
  end if;
  if p_table_name like 'hr_%' or p_table_name like 'payroll_%' or p_table_name like 'leave_%' or p_table_name like 'employee%' or p_table_name like 'attendance%' or p_table_name like 'payslip%' or p_table_name = 'payrolls' then
    return 'hr';
  end if;
  if p_table_name like 'desk_%' or p_table_name like 'support_%' then
    return 'desk';
  end if;
  return 'invoice';
end;
$$;


--
-- Name: protect_accounting_period_status(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.protect_accounting_period_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.status is distinct from old.status
    and current_setting('app.accounting_period_workflow', true) <> 'authorized' then
    raise exception 'Accounting period status changes must use the controlled workflow'
      using errcode = '55000';
  end if;
  return new;
end
$$;


--
-- Name: protect_effective_compliance_version(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.protect_effective_compliance_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.status = 'retired' then
    raise exception 'Retired compliance configuration versions are immutable'
      using errcode = '55000';
  end if;

  if old.status = 'active' and (
    new.config_set_id is distinct from old.config_set_id
    or new.version is distinct from old.version
    or new.effective_from is distinct from old.effective_from
    or new.configuration is distinct from old.configuration
    or new.status not in ('active', 'retired')
  ) then
    raise exception 'Active compliance configuration values are immutable; create a new version'
      using errcode = '55000';
  end if;

  if old.status = 'active'
    and new.status = 'retired'
    and nullif(trim(coalesce(new.change_reason, '')), '') is null
  then
    raise exception 'A reason is required when retiring a compliance configuration version'
      using errcode = '23514';
  end if;

  return new;
end
$$;


--
-- Name: protect_finalized_payroll(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.protect_finalized_payroll() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare run_status text;
begin
  if tg_table_name='payroll_runs' then
    run_status := old.status;
  elsif tg_table_name in ('payroll_run_employees','payroll_input_snapshots','payroll_approvals','payroll_adjustments') then
    select status into run_status from public.payroll_runs where id=old.payroll_run_id;
  elsif tg_table_name='payroll_calculation_lines' then
    select run.status into run_status
    from public.payroll_run_employees employee_run
    join public.payroll_runs run on run.id=employee_run.payroll_run_id
    where employee_run.id=old.payroll_run_employee_id;
  else
    run_status := 'finalized';
  end if;
  if run_status in ('finalized','payment_pending','partially_paid','paid','reversal_pending','reversed')
     and current_setting('app.payroll_workflow',true) <> 'authorized' then
    raise exception 'Finalized payroll records are immutable; use supplemental, adjustment or reversal workflows'
      using errcode='55000';
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $$;


