-- Name: protect_posted_journal(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.protect_posted_journal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
