      using errcode = '55000';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end
$$;


--
-- Name: protect_sales_book_period_fields(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.protect_sales_book_period_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.status in ('DECLARED', 'AMENDED')
     and coalesce(current_setting('app.sales_book_period_workflow', true), '') not in ('amendment', 'migration')
     and (
       new.company_id is distinct from old.company_id
       or new.accounting_period_id is distinct from old.accounting_period_id
       or new.period_start is distinct from old.period_start
       or new.period_end is distinct from old.period_end
       or new.reporting_frequency is distinct from old.reporting_frequency
       or new.declaration_deadline is distinct from old.declaration_deadline
       or new.tax_timezone is distinct from old.tax_timezone
       or new.declared_at is distinct from old.declared_at
       or new.declared_by is distinct from old.declared_by
       or new.declaration_metadata is distinct from old.declaration_metadata
       or new.amended_at is distinct from old.amended_at
       or new.amended_by is distinct from old.amended_by
       or new.amendment_reason is distinct from old.amendment_reason
       or new.created_at is distinct from old.created_at
       or new.created_by is distinct from old.created_by
     ) then
    raise exception 'Declared Sales Book period metadata is immutable; use an amendment workflow'
      using errcode = '55000';
  end if;
  return new;
end
$$;


--
-- Name: protect_sales_book_period_status(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.protect_sales_book_period_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.status is distinct from old.status
     and coalesce(current_setting('app.sales_book_period_workflow', true), '') not in ('system', 'authorized', 'amendment') then
    raise exception 'Sales Book period status changes must use a controlled workflow' using errcode = '55000';
  end if;
  if old.status = 'OPEN' and new.status not in ('OPEN', 'READY_FOR_DECLARATION') then
    raise exception 'An open Sales Book can only move to READY_FOR_DECLARATION' using errcode = '55000';
  end if;
  if old.status = 'READY_FOR_DECLARATION' and new.status not in ('READY_FOR_DECLARATION', 'DECLARED') then
    raise exception 'A ready Sales Book can only be declared' using errcode = '55000';
  end if;
  if old.status = 'DECLARED' and new.status not in ('DECLARED', 'AMENDED') then
    raise exception 'A declared Sales Book can only move to AMENDED' using errcode = '55000';
  end if;
  if old.status = 'AMENDED' and new.status <> 'AMENDED' then
    raise exception 'An amended Sales Book cannot be reopened' using errcode = '55000';
  end if;
  return new;
end
$$;


--
-- Name: queue_booking_invoice_job(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.queue_booking_invoice_job() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  setting_row public.booking_invoice_automation_settings;
  trigger_name text;
  old_paid numeric := case when tg_op = 'UPDATE' then coalesce(old.paid_amount, 0) else 0 end;
  new_paid numeric := coalesce(new.paid_amount, 0);
begin
  if not private.operix_product_access(new.company_id, 'booking')
     or not private.operix_product_access(new.company_id, 'invoice') then
    return new;
  end if;
  select * into setting_row from public.booking_invoice_automation_settings where company_id = new.company_id;
  if not coalesce(setting_row.enabled, false) then return new; end if;

  if setting_row.trigger_event = 'payment_received' and (new_paid > old_paid or new.payment_status = 'paid') then
    trigger_name := 'payment_received';
  elsif setting_row.trigger_event = 'confirmed' and new.status = 'confirmed' and (tg_op = 'INSERT' or old.status is distinct from new.status) then
    trigger_name := 'confirmed';
  elsif setting_row.trigger_event = 'checked_in' and new.status = 'checked_in' and old.status is distinct from new.status then
    trigger_name := 'checked_in';
  elsif setting_row.trigger_event = 'completed' and new.status = 'completed' and (tg_op = 'INSERT' or old.status is distinct from new.status) then
    trigger_name := 'completed';
  else
    return new;
  end if;

  insert into public.booking_invoice_jobs(company_id, booking_id, trigger_event)
    values (new.company_id, new.id, trigger_name)
    on conflict (company_id, booking_id, trigger_event) do nothing;
  return new;
end;
$$;


--
-- Name: rbac_accounting_period_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_accounting_period_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if coalesce((select auth.jwt() ->> 'role'), '') = 'service_role'
     or private.rbac_is_platform_admin()
     or coalesce(current_setting('app.accounting_period_workflow', true), '') = 'authorized' then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.status is distinct from old.status then
    raise exception 'Accounting period close and reopen operations must use the controlled workflow' using errcode = '55000';
  end if;
  return new;
end;
$$;


--
-- Name: rbac_active_admin_count(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_active_admin_count(p_company_id uuid, p_except_membership_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select count(*)::integer
  from public.memberships membership
  where membership.company_id = p_company_id
    and membership.id is distinct from p_except_membership_id
    and lower(coalesce(membership.status, 'active')) = 'active'
    and private.rbac_member_role_code(membership.id) = 'company_administrator';
$$;


--
-- Name: rbac_actor_membership(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_actor_membership(p_company_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with recursive ancestors(id, depth) as (
    select p_company_id, 0
    union all
    select company.parent_company_id, ancestors.depth + 1
    from public.companies company
    join ancestors on ancestors.id = company.id
    where company.parent_company_id is not null
  )
  select membership.id
  from ancestors
  join public.memberships membership on membership.company_id = ancestors.id
  where membership.user_id = (select auth.uid())
    and coalesce(membership.status, 'active') = 'active'
  order by ancestors.depth, membership.created_at, membership.id
  limit 1;
$$;


--
-- Name: rbac_apply_user_access(uuid, text, jsonb, jsonb, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_apply_user_access(p_membership_id uuid, p_role_code text, p_permissions jsonb, p_scopes jsonb, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  role_value text := case lower(trim(coalesce(p_role_code, '')))
    when 'admin' then 'company_administrator'
    else lower(trim(coalesce(p_role_code, '')))
  end;
  role_id_value uuid;
  permission_entry record;
  scope_entry record;
begin
  perform private.rbac_validate_user_access_payload(role_value, p_permissions, p_scopes);
  role_id_value := private.rbac_user_role_id(role_value);
  if role_id_value is null then
    raise exception 'The selected role is not available' using errcode = '22023';
  end if;

  perform set_config('app.membership_role_workflow', 'authorized', true);
  update public.memberships
  set role = case role_value when 'company_administrator' then 'admin' when 'manager' then 'manager' else 'employee' end,
      status = status
  where id = p_membership_id;
  delete from public.membership_role_assignments where membership_id = p_membership_id;
  insert into public.membership_role_assignments(membership_id, role_id, created_by)
  values (p_membership_id, role_id_value, p_actor_id);
  delete from public.membership_permission_overrides where membership_id = p_membership_id;
  if role_value <> 'company_administrator' then
    for permission_entry in select key, value from jsonb_each(coalesce(p_permissions, '{}'::jsonb)) loop
      insert into public.membership_permission_overrides(membership_id, permission_code, enabled, created_by, updated_by)
      values (p_membership_id, private.rbac_canonical_permission(permission_entry.key), (permission_entry.value #>> '{}')::boolean, p_actor_id, p_actor_id);
    end loop;
  end if;
  delete from public.membership_data_scopes where membership_id = p_membership_id;
  if role_value <> 'company_administrator' then
    for scope_entry in select key, value from jsonb_each_text(coalesce(p_scopes, '{}'::jsonb)) loop
      insert into public.membership_data_scopes(membership_id, resource, scope, updated_by)
      values (p_membership_id, scope_entry.key, upper(scope_entry.value), p_actor_id);
    end loop;
  end if;
  perform set_config('app.membership_role_workflow', '', true);

  return private.rbac_member_access_json(p_membership_id);
exception when others then
  perform set_config('app.membership_role_workflow', '', true);
  raise;
end;
$$;


--
-- Name: rbac_assignment_defaults(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_assignment_defaults() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.assigned_user_id is null then
    new.assigned_user_id := new.user_id;
  end if;
  if coalesce((select auth.jwt() ->> 'role'), '') in ('service_role')
     or private.rbac_is_platform_admin()
     or private.rbac_is_tenant_admin(coalesce(old.company_id, new.company_id)) then
    return new;
  end if;
  if new.assigned_user_id is distinct from (select auth.uid()) then
    raise exception 'Only a tenant Admin can assign a record to another user' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE'
     and (
       old.company_id is distinct from new.company_id
       or old.user_id is distinct from new.user_id
     ) then
    raise exception 'Only a tenant Admin can reassign a record' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: rbac_can_read_resource(uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_can_read_resource(p_company_id uuid, p_resource text, p_owner_user_id uuid, p_assigned_user_id uuid, p_permission text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when private.rbac_is_platform_admin() then true
    when p_company_id is null then p_owner_user_id = (select auth.uid())
    when not private.company_is_active(p_company_id) then false
    when p_permission is not null and not private.has_company_permission(p_company_id, p_permission) then false
    else private.rbac_scope_allows(p_company_id, p_resource, p_owner_user_id, p_assigned_user_id)
  end;
$$;


--
-- Name: rbac_canonical_permission(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_canonical_permission(p_permission text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case lower(trim(coalesce(p_permission, '')))
    when 'sales_invoice.view' then 'invoice.view'
    when 'sales_invoice.create' then 'invoice.create'
    when 'invoice.create' then 'invoice.create'
    when 'sales_invoice.edit' then 'invoice.edit'
    when 'sales_invoice.post' then 'invoice.issue'
    when 'invoice.post' then 'invoice.issue'
    when 'invoice.approve' then 'invoice.issue'
    when 'sales_invoice.approve' then 'invoice.issue'
    when 'sales_invoice.delete' then 'invoice.delete_draft'
    when 'sales_invoice.cancel' then 'invoice.void'
    when 'invoice.cancel' then 'invoice.void'
    when 'sales_invoice.reverse' then 'invoice.void'
    when 'credit_note.issue' then 'invoice.credit'
    when 'debit_note.issue' then 'invoice.debit'
    when 'payments.manage' then 'payment.create'
    when 'payment.manage' then 'payment.create'
    when 'payment.read' then 'payment.view'
    when 'customer_payment.view' then 'payment.view'
    when 'customer_payment.record' then 'payment.create'
    when 'customer_payment.edit' then 'payment.create'
    when 'customer_payment.allocate' then 'payment.create'
    when 'customer_payment.reverse' then 'payment.refund'
    when 'customer_payment.void' then 'payment.refund'
    when 'customer_credit.manage' then 'payment.refund'
    when 'customer_refund.create' then 'payment.refund'
    when 'other_income.view' then 'payment.view'
    when 'other_income.create' then 'payment.create'
    when 'other_income.edit' then 'payment.refund'
    when 'cash_account.view' then 'settings.bank'
    when 'cash_account.manage' then 'settings.bank'
    when 'bank_account.view' then 'settings.bank'
    when 'bank.reconcile' then 'settings.bank'
    when 'journal.create' then 'accounting_period.close'
    when 'journal.post' then 'accounting_period.close'
    when 'journal.reverse' then 'accounting_period.reopen'
    when 'cash_transaction.post' then 'payment.create'
    when 'expense.post' then 'expense.create'
    when 'expense.create' then 'expense.create'
    when 'expense.edit' then 'expense.edit'
    when 'expense.period.reopen' then 'accounting_period.reopen'
    when 'expense.tax.override' then 'settings.tax'
    when 'expense.vat.override' then 'settings.tax'
    when 'supplier_bill.view' then 'expense.view_all'
    when 'supplier_bill.approve' then 'expense.approve'
    when 'supplier_bill.post' then 'expense.manage'
    when 'supplier_payment.view' then 'payment.view'
    when 'supplier_payment.record' then 'payment.create'
    when 'supplier_payment.reverse' then 'payment.refund'
    when 'document.archive.view' then 'audit.view'
    when 'document.archive.create' then 'audit.view'
    when 'financial_document.audit.view' then 'audit.view'
    when 'audit.read' then 'audit.view'
    when 'pos.complete' then 'invoice.issue'
    when 'pos.terminal.use' then 'invoice.issue'
    when 'pos.order.hold' then 'invoice.create'
    when 'pos.order.cancel' then 'invoice.void'
    when 'pos.receipt.reprint' then 'financial.export'
    when 'pos.shift.view' then 'payment.view'
    when 'pos.shift.open' then 'payment.create'
    when 'pos.shift.close' then 'payment.create'
    when 'pos.shift.reopen' then 'payment.refund'
    when 'pos.shift.cash_movement' then 'payment.create'
    when 'products.view' then 'product.view'
    when 'products.manage' then 'product.edit'
    when 'prices.override' then 'product.change_price'
    when 'discounts.override' then 'product.change_price'
    when 'inventory.manage' then 'inventory.adjust'
    when 'sales_customer.manage' then 'customer.edit'
    when 'customer.manage' then 'customer.edit'
    when 'customer.read' then 'customer.view'
    when 'customer.balance.view' then 'customer.view_all'
    when 'customer.view' then 'customer.view'
    when 'customer.view_all' then 'customer.view_all'
    when 'customer.create' then 'customer.create'
    when 'customer.edit' then 'customer.edit'
    when 'customer.delete' then 'customer.delete'
    when 'reports.view' then 'reports.operational'
    when 'report.read' then 'reports.operational'
    when 'financial_reports.view' then 'reports.profit'
    when 'financial_reports.export' then 'financial.export'
    when 'financial_data.export' then 'financial.export'
    when 'accounting.read' then 'accounting_period.view'
    when 'accounts.manage' then 'accounting_period.close'
    when 'accounting_period.manage' then 'accounting_period.close'
    when 'accounting_period.reopen' then 'accounting_period.reopen'
    when 'opening_balance.post' then 'accounting_period.close'
    when 'posting_rules.manage' then 'accounting_period.close'
    when 'tax.book.view' then 'sales_book.view'
    when 'tax.report.view' then 'reports.tax'
    when 'tax_report.submit' then 'settings.tax'
    when 'tax.declaration.prepare' then 'settings.tax'
    when 'tax.calendar.manage' then 'settings.tax'
    when 'fiscal_configuration.manage' then 'settings.tax'
    when 'withholding.manage' then 'settings.tax'
    when 'compliance.manage' then 'settings.tax'
    when 'roles.manage' then 'permissions.manage'
    when 'roles.read' then 'users.view'
    when 'team.manage' then 'users.manage'
    when 'teams.manage' then 'users.manage'
    when 'team.read' then 'users.view'
    when 'teams.read' then 'users.view'
    when 'staff.manage' then 'users.manage'
    when 'employees.manage' then 'users.manage'
    when 'employees.view' then 'users.view'
    when 'users.read' then 'users.view'
    when 'users.manage' then 'users.manage'
    when 'company.manage' then 'settings.company'
    when 'branches.manage' then 'settings.company'
    when 'organization.manage' then 'settings.company'
    when 'organization.read' then 'settings.company'
    when 'organization.view' then 'settings.company'
    when 'workspace.manage' then 'settings.company'
    when 'settings.manage' then 'settings.company'
    when 'settings.read' then 'settings.company'
    when 'security.manage' then 'settings.security'
    when 'security.read' then 'settings.security'
    when 'integrations.manage' then 'settings.integrations'
    when 'integrations.read' then 'settings.integrations'
    when 'api.manage' then 'settings.api'
    when 'api.read' then 'settings.api'
    when 'billing.manage' then 'subscription.manage'
    when 'billing.read' then 'subscription.manage'
    else lower(trim(coalesce(p_permission, '')))
  end;
$$;


--
-- Name: rbac_company_owner_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_company_owner_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.owner_id is distinct from old.owner_id
     and coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role'
     and coalesce(current_setting('app.company_owner_transfer', true), '') <> 'authorized'
     and not private.rbac_is_platform_admin() then
    raise exception 'Company ownership can only change through the protected ownership workflow'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: rbac_customer_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_customer_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE'
     and old.company_id is not null
     and not private.has_company_permission(old.company_id, 'customer.delete') then
    raise exception 'Customer delete permission is required' using errcode = '42501';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


--
-- Name: rbac_expense_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_expense_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if not private.rbac_can_read_resource(old.company_id, 'expense', old.user_id, old.assigned_user_id, 'expense.manage') then
      raise exception 'Expense management permission or data scope is required' using errcode = '42501';
    end if;
    return old;
  end if;
  if new.approval_status is distinct from old.approval_status
     and not private.rbac_can_read_resource(new.company_id, 'expense', old.user_id, old.assigned_user_id, 'expense.approve')
     and not private.rbac_can_read_resource(new.company_id, 'expense', old.user_id, old.assigned_user_id, 'expense.manage') then
    raise exception 'Expense approval permission or data scope is required' using errcode = '42501';
  end if;
  if (new.amount is distinct from old.amount
      or new.category is distinct from old.category
      or new.description is distinct from old.description
      or new.receipt_url is distinct from old.receipt_url)
     and not private.rbac_can_read_resource(new.company_id, 'expense', old.user_id, old.assigned_user_id, 'expense.edit')
     and not private.rbac_can_read_resource(new.company_id, 'expense', old.user_id, old.assigned_user_id, 'expense.manage') then
    raise exception 'Expense edit permission or data scope is required' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: rbac_invitation_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_invitation_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_role text := lower(trim(coalesce(new.role_code, '')));
begin
  if private.operix_server_request()
     or coalesce(current_setting('app.user_access_invitation_workflow', true), '') = 'authorized' then
    if normalized_role not in ('admin', 'company_administrator', 'manager', 'employee') then
      raise exception 'Only Admin, Manager, and Employee roles can be invited' using errcode = '42501';
    end if;
    new.role_code := case normalized_role when 'admin' then 'company_administrator' else normalized_role end;
    return new;
  end if;
  if not private.rbac_is_tenant_admin(new.company_id) then
    raise exception 'Only a tenant Admin can invite company users' using errcode = '42501';
  end if;
  if normalized_role not in ('admin', 'company_administrator', 'manager', 'employee') then
    raise exception 'Only Admin, Manager, and Employee roles can be invited' using errcode = '42501';
  end if;
  new.role_code := case normalized_role when 'admin' then 'company_administrator' else normalized_role end;
  return new;
end;
$$;


--
-- Name: rbac_invoice_delete_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_invoice_delete_guard()
returns trigger
language plpgsql
security definer
set search_path to ''
as $$
begin
  if coalesce((select auth.jwt() ->> 'role'), '') = 'service_role'
     or private.rbac_is_platform_admin() then
    return old;
  end if;
  -- Controlled admin workflow: public.delete_invoice sets this flag after its own permission and safety checks.
  if coalesce(current_setting('app.invoice_delete_workflow', true), '') = 'authorized'
     and old.company_id is not null
     and private.rbac_role_code(old.company_id) = 'company_administrator'
     and coalesce(private.has_company_permission(old.company_id, 'sales_invoice.delete'), false) then
    return old;
  end if;
  if lower(coalesce(old.accounting_state, 'legacy')) not in ('legacy','ready_for_posting')
     or upper(coalesce(old.commercial_status, old.status::text, 'DRAFT')) <> 'DRAFT' then
    raise exception 'Finalized financial documents cannot be deleted; use a correction or reversal workflow' using errcode = '55000';
  end if;
  if not private.rbac_can_read_resource(old.company_id, 'invoice', old.user_id, old.assigned_user_id, 'invoice.delete_draft') then
    raise exception 'Draft-delete permission and data scope are required' using errcode = '42501';
  end if;
  return old;
end;
$$;


--
-- Name: rbac_invoice_discount_dates_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_invoice_discount_dates_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  server_request boolean := coalesce((select auth.jwt() ->> 'role'), '') = 'service_role';
  target_company uuid;
begin
  if server_request or private.rbac_is_platform_admin() then return new; end if;

  if tg_table_name = 'invoice_items' then
    if coalesce(new.discount, 0) > 0 and (tg_op = 'INSERT' or new.discount is distinct from old.discount) then
      select invoice.company_id into target_company from public.invoices invoice where invoice.id = new.invoice_id;
      if target_company is not null and not private.has_company_permission(target_company, 'invoice.apply_discount') then
        raise exception 'Discount permission is required' using errcode = '42501';
      end if;
    end if;
    return new;
  end if;

  if new.company_id is null then return new; end if;

  if (coalesce(new.discount_percent, 0) > 0 or coalesce(new.discount_amount, 0) > 0)
     and (tg_op = 'INSERT'
          or new.discount_percent is distinct from old.discount_percent
          or new.discount_amount is distinct from old.discount_amount)
     and not private.has_company_permission(new.company_id, 'invoice.apply_discount') then
    raise exception 'Discount permission is required' using errcode = '42501';
  end if;

  if tg_op = 'UPDATE'
     and (new.issue_date is distinct from old.issue_date or new.due_date is distinct from old.due_date)
     and not private.has_company_permission(new.company_id, 'invoice.change_dates') then
    raise exception 'Date-change permission is required' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: rbac_invoice_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_invoice_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  document_type text := upper(coalesce(new.commercial_document_type, new.type, 'INVOICE'));
  old_status text := upper(coalesce(old.commercial_status, old.status::text, 'DRAFT'));
  new_status text := upper(coalesce(new.commercial_status, new.status::text, 'DRAFT'));
  server_request boolean := coalesce((select auth.jwt() ->> 'role'), '') = 'service_role';
  actor_permission text;
  create_permission text;
begin
  if server_request or private.rbac_is_platform_admin() then return new; end if;
  if new.company_id is null then return new; end if;

  create_permission := case document_type
    when 'QUOTE' then 'offer.create'
    when 'PROFORMA' then 'proforma.create'
    when 'SALES_ORDER' then 'order.create'
    when 'DELIVERY_NOTE' then 'delivery_note.create'
    when 'CREDIT_NOTE' then 'invoice.credit'
    when 'DEBIT_NOTE' then 'invoice.debit'
    else 'invoice.create'
  end;
  if tg_op = 'INSERT'
     and not private.rbac_can_read_resource(new.company_id, 'invoice', new.user_id, new.assigned_user_id, create_permission) then
    raise exception 'Document create permission or data scope is required' using errcode = '42501';
  end if;

  if document_type in ('CREDIT_NOTE','CREDIT') then
    actor_permission := 'invoice.credit';
  elsif document_type in ('DEBIT_NOTE','DEBIT') then
    actor_permission := 'invoice.debit';
  else
    actor_permission := 'invoice.edit';
  end if;
  if document_type in ('CREDIT_NOTE','CREDIT','DEBIT_NOTE','DEBIT')
     and not private.rbac_can_read_resource(new.company_id, 'invoice', coalesce(old.user_id, new.user_id), coalesce(old.assigned_user_id, new.assigned_user_id), actor_permission) then
    raise exception 'Correction-document permission or data scope is required' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE'
     and new.commercial_status = 'CONVERTED'
     and old.commercial_status is distinct from new.commercial_status
     and not private.rbac_can_read_resource(old.company_id, 'invoice', old.user_id, old.assigned_user_id, 'invoice.edit') then
    raise exception 'Source-document data scope is required for conversion' using errcode = '42501';
  end if;
  if new_status in ('ISSUED','POSTED','FINALIZED','APPROVED')
     and old_status is distinct from new_status
     and not private.rbac_can_read_resource(new.company_id, 'invoice', coalesce(old.user_id, new.user_id), coalesce(old.assigned_user_id, new.assigned_user_id), 'invoice.issue') then
    raise exception 'Invoice issue permission or data scope is required' using errcode = '42501';
  end if;
  if new_status in ('CANCELLED','VOID','VOIDED','REVERSED')
     and old_status is distinct from new_status
     and not private.rbac_can_read_resource(new.company_id, 'invoice', coalesce(old.user_id, new.user_id), coalesce(old.assigned_user_id, new.assigned_user_id), 'invoice.void') then
    raise exception 'Invoice void permission or data scope is required' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: rbac_is_invoice_permission(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_is_invoice_permission(p_permission text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select private.rbac_canonical_permission(p_permission) = any(array[
    'company.read',
    'invoice.view','invoice.view_all','invoice.create','invoice.edit','invoice.apply_discount','invoice.change_dates','invoice.issue','invoice.delete_draft','invoice.void','invoice.credit','invoice.debit',
    'offer.create','offer.manage','proforma.create','proforma.manage','order.create','order.manage','delivery_note.create','delivery_note.manage','contracts.manage',
    'payment.view','payment.create','payment.refund',
    'expense.view_own','expense.view_all','expense.create','expense.edit','expense.approve','expense.manage',
    'customer.view','customer.view_all','customer.create','customer.edit','customer.delete',
    'product.view','product.create','product.edit','product.change_price','product.delete',
    'inventory.view','inventory.adjust',
    'reports.sales','reports.operational','reports.profit','reports.tax','sales_book.view','sales_book.manage',
    'accounting_period.view','accounting_period.close','accounting_period.reopen',
    'users.view','users.manage','permissions.manage','audit.view','financial.export',
    'settings.company','settings.tax','settings.invoice','settings.bank','settings.integrations','settings.api','settings.security',
    'subscription.manage'
  ]::text[]);
$$;


--
-- Name: rbac_is_platform_admin(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_is_platform_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.control_platform_admins admin
    where admin.user_id = (select auth.uid())
      and admin.revoked_at is null
  );
$$;


--
-- Name: rbac_is_platform_permission(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_is_platform_permission(p_permission text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select lower(coalesce(trim(p_permission), '')) like 'control.%'
      or lower(coalesce(trim(p_permission), '')) like 'platform.%'
      or lower(coalesce(trim(p_permission), '')) like 'organization.%'
      or lower(coalesce(trim(p_permission), '')) like 'apps.%'
      or lower(coalesce(trim(p_permission), '')) like 'usage.%'
      or lower(coalesce(trim(p_permission), '')) like 'developer.%'
      or lower(coalesce(trim(p_permission), '')) in ('data.read', 'status.read');
$$;


--
-- Name: rbac_is_tenant_admin(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_is_tenant_admin(p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.rbac_is_platform_admin()
    or (
      private.company_is_active(p_company_id)
      and private.rbac_role_code(p_company_id) = 'company_administrator'
    );
$$;


--
-- Name: rbac_is_user_access_admin(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_is_user_access_admin(p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_company_id is not null
    and private.company_is_active(p_company_id)
    and (
      private.rbac_is_platform_admin()
      or (
        private.rbac_role_code(p_company_id) in ('company_administrator', 'manager')
        and private.has_company_permission(p_company_id, 'users.manage')
      )
    );
$$;


--
-- Name: rbac_last_active_admin_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_last_active_admin_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  old_role text;
  other_admins integer;
begin
  if tg_op = 'INSERT' then
    if lower(coalesce(new.status, 'active')) in ('active', 'suspended')
       and lower(coalesce(new.role, 'employee')) not in ('owner', 'admin', 'company_administrator')
       and not exists (
         select 1 from public.memberships existing
         where existing.company_id = new.company_id
           and lower(coalesce(existing.status, 'active')) = 'active'
           and lower(coalesce(existing.role, 'employee')) in ('owner', 'admin', 'company_administrator')
       ) then
      raise exception 'The company must have at least one active Admin' using errcode = '42501';
    end if;
    return new;
  end if;

  old_role := private.rbac_member_role_code(old.id);
  if old_role = 'company_administrator'
     and lower(coalesce(old.status, 'active')) = 'active'
     and (
       lower(coalesce(new.status, 'active')) <> 'active'
       or lower(coalesce(new.role, 'employee')) not in ('owner', 'admin', 'company_administrator')
     ) then
    select count(*)::integer into other_admins
    from public.memberships existing
    where existing.company_id = old.company_id
      and existing.id <> old.id
      and lower(coalesce(existing.status, 'active')) = 'active'
      and private.rbac_member_role_code(existing.id) = 'company_administrator';
    if other_admins < 1 then
      raise exception 'This company must have at least one active Admin. Assign another Admin before changing your account.' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: rbac_member_access_json(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_member_access_json(p_membership_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with target as (
    select membership.company_id, private.rbac_member_role_code(membership.id) as role_code
    from public.memberships membership
    where membership.id = p_membership_id
  ),
  permissions as (
    select coalesce(jsonb_agg(permission.code order by permission.code), '[]'::jsonb) as value
    from public.app_permissions permission
    cross join target
    where permission.code in (
      'invoice.view','invoice.view_all','invoice.create','invoice.edit','invoice.issue','invoice.delete_draft',
      'invoice.void','invoice.credit','invoice.debit','offer.create','offer.manage','proforma.create',
      'proforma.manage','order.create','order.manage','delivery_note.create','delivery_note.manage','contracts.manage',
      'payment.view','payment.create','payment.refund','expense.view_own','expense.view_all','expense.create',
      'expense.edit','expense.approve','expense.manage','customer.view','customer.view_all','customer.create',
      'customer.edit','customer.delete','product.view','product.create','product.edit','product.change_price',
      'product.delete','inventory.view','inventory.adjust','reports.sales','reports.operational','reports.profit',
      'reports.tax','sales_book.view','sales_book.manage','accounting_period.view','accounting_period.close',
      'accounting_period.reopen','users.view','users.manage','permissions.manage','audit.view','financial.export',
      'settings.company','settings.tax','settings.invoice','settings.bank','settings.integrations','settings.api',
      'settings.security','subscription.manage'
    )
      and private.rbac_member_has_permission(p_membership_id, permission.code)
  ),
  scopes as (
    select coalesce(jsonb_object_agg(resource, private.rbac_member_scope(p_membership_id, resource)), '{}'::jsonb) as value
    from (values
      ('invoice'),('offer'),('proforma'),('order'),('delivery_note'),('customer'),
      ('expense'),('payment'),('product'),('inventory')
    ) as resources(resource)
  ),
  overrides as (
    select coalesce(jsonb_object_agg(permission_code, enabled), '{}'::jsonb) as value
    from public.membership_permission_overrides
    where membership_id = p_membership_id
  )
  select jsonb_build_object(
    'role_code', target.role_code,
    'permissions', permissions.value,
    'scopes', scopes.value,
    'overrides', overrides.value
  )
  from target, permissions, scopes, overrides;
$$;


--
-- Name: rbac_member_has_permission(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_member_has_permission(p_membership_id uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with target as (
    select membership.id, membership.company_id,
      private.rbac_member_role_code(membership.id) as role_code
    from public.memberships membership
    where membership.id = p_membership_id
      and coalesce(membership.status, 'active') = 'active'
  ), requested as (
    select unnest(private.rbac_permission_candidates(p_permission)) as permission_code
  )
  select exists (
    select 1 from target
    where target.role_code = 'company_administrator'
       or (
         not exists (
           select 1
           from public.membership_permission_overrides override
           join requested on requested.permission_code = override.permission_code
           where override.membership_id = target.id
             and override.enabled = false
         )
         and (
           exists (
             select 1
             from public.membership_permission_overrides override
             join requested on requested.permission_code = override.permission_code
             where override.membership_id = target.id
               and override.enabled = true
           )
           or exists (
             select 1
             from public.membership_role_assignments assignment
             join public.app_role_permissions role_permission on role_permission.role_id = assignment.role_id
             join requested on requested.permission_code = role_permission.permission_code
             where assignment.membership_id = target.id
           )
         )
       )
  );
$$;


--
-- Name: rbac_member_role_code(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_member_role_code(p_membership_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (
      select role.code
      from public.membership_role_assignments assignment
      join public.app_roles role on role.id = assignment.role_id
      join public.memberships membership on membership.id = assignment.membership_id
      where assignment.membership_id = p_membership_id
        and role.company_id is null
        and role.code in ('company_administrator', 'manager', 'employee')
      order by case role.code
        when 'company_administrator' then 1
        when 'manager' then 2
        else 3
      end
      limit 1
    ),
    case lower(coalesce((select membership.role from public.memberships membership where membership.id = p_membership_id), 'employee'))
      when 'owner' then 'company_administrator'
      when 'admin' then 'company_administrator'
      when 'company_administrator' then 'company_administrator'
      when 'manager' then 'manager'
      else 'employee'
    end
  );
$$;


--
-- Name: rbac_member_scope(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_member_scope(p_membership_id uuid, p_resource text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when private.rbac_member_role_code(p_membership_id) = 'company_administrator' then 'ALL'
    else coalesce(
      (
        select scope.scope
        from public.membership_data_scopes scope
        where scope.membership_id = p_membership_id and scope.resource = p_resource
      ),
      (
        select role_scope.scope
        from public.membership_role_assignments assignment
        join public.app_role_data_scopes role_scope on role_scope.role_id = assignment.role_id
        where assignment.membership_id = p_membership_id and role_scope.resource = p_resource
        order by case role_scope.scope when 'ALL' then 1 when 'ASSIGNED' then 2 else 3 end
        limit 1
      ),
      'OWN'
    )
  end;
$$;


--
-- Name: rbac_membership_mutation_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_membership_mutation_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if coalesce((select auth.jwt() ->> 'role'), '') = 'service_role'
     or private.rbac_is_platform_admin()
     or coalesce(current_setting('app.membership_role_workflow', true), '') = 'authorized'
     or coalesce(current_setting('app.company_link_workflow', true), '') = 'authorized' then
    return coalesce(new, old);
  end if;
  if tg_op = 'DELETE' then
    if private.rbac_is_tenant_admin(old.company_id) then return old; end if;
  elsif private.rbac_is_tenant_admin(old.company_id) then
    if new.company_id is distinct from old.company_id
       or new.user_id is distinct from old.user_id then
      raise exception 'Membership ownership cannot be changed by a tenant Admin' using errcode = '42501';
    end if;
    return new;
  end if;
  raise exception 'Membership changes require a protected administration workflow' using errcode = '42501';
end;
$$;


--
-- Name: rbac_payment_allocation_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_payment_allocation_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payment_id_value uuid := case when tg_op = 'DELETE' then old.payment_id else new.payment_id end;
  invoice_id_value uuid := case when tg_op = 'DELETE' then old.invoice_id else new.invoice_id end;
  company_id_value uuid := case when tg_op = 'DELETE' then old.company_id else new.company_id end;
  payment_row public.payments;
  invoice_row public.invoices;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') = 'service_role'
     or private.rbac_is_platform_admin() then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  select * into payment_row from public.payments where id = payment_id_value;
  select * into invoice_row from public.invoices where id = invoice_id_value;
  if payment_row.id is null or invoice_row.id is null
     or payment_row.company_id is distinct from invoice_row.company_id
     or payment_row.company_id is distinct from company_id_value then
    raise exception 'Payment allocation parents must belong to the same tenant' using errcode = '42501';
  end if;
  if not private.rbac_can_read_resource(payment_row.company_id, 'payment', payment_row.user_id, payment_row.assigned_user_id, 'payment.create')
     or not private.rbac_can_read_resource(invoice_row.company_id, 'invoice', invoice_row.user_id, invoice_row.assigned_user_id, 'invoice.view') then
    raise exception 'Payment allocation permission or data scope is required' using errcode = '42501';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


--
-- Name: rbac_payment_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_payment_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare payment_row public.payments;
begin
  if tg_op = 'DELETE' then
    if not private.rbac_can_read_resource(old.company_id, 'payment', old.user_id, old.assigned_user_id, 'payment.refund') then
      raise exception 'Payment refund permission or data scope is required' using errcode = '42501';
    end if;
    return old;
  end if;
  if tg_op = 'UPDATE' and old.reversed_at is null and new.reversed_at is not null then
    if not private.rbac_can_read_resource(new.company_id, 'payment', old.user_id, old.assigned_user_id, 'payment.refund') then
      raise exception 'Payment refund permission or data scope is required' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: rbac_permission_assignable(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_permission_assignable(p_role_code text, p_permission text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with role_value as (
    select case lower(trim(coalesce(p_role_code, '')))
      when 'admin' then 'company_administrator'
      else lower(trim(coalesce(p_role_code, '')))
    end as role_code,
    private.rbac_canonical_permission(p_permission) as permission_code
  )
  select case
    when role_value.role_code = 'company_administrator' then
      role_value.permission_code in (
        'invoice.view','invoice.view_all','invoice.create','invoice.edit','invoice.apply_discount','invoice.change_dates','invoice.issue','invoice.delete_draft',
        'invoice.void','invoice.credit','invoice.debit','offer.create','offer.manage','proforma.create',
        'proforma.manage','order.create','order.manage','delivery_note.create','delivery_note.manage','contracts.manage',
        'payment.view','payment.create','payment.refund','expense.view_own','expense.view_all','expense.create',
        'expense.edit','expense.approve','expense.manage','customer.view','customer.view_all','customer.create',
        'customer.edit','customer.delete','product.view','product.create','product.edit','product.change_price',
        'product.delete','inventory.view','inventory.adjust','reports.sales','reports.operational','reports.profit',
        'reports.tax','sales_book.view','sales_book.manage','accounting_period.view','accounting_period.close',
        'accounting_period.reopen','users.view','users.manage','permissions.manage','audit.view','financial.export',
        'settings.company','settings.tax','settings.invoice','settings.bank','settings.integrations','settings.api',
        'settings.security','subscription.manage'
      )
    when role_value.role_code = 'manager' then
      role_value.permission_code in (
        'company.read','invoice.view','invoice.view_all','invoice.create','invoice.edit','invoice.apply_discount','invoice.change_dates','invoice.issue',
        'invoice.delete_draft','invoice.void','invoice.credit','invoice.debit','offer.create','offer.manage',
        'proforma.create','proforma.manage','order.create','order.manage','delivery_note.create','delivery_note.manage','contracts.manage',
        'payment.view','payment.create','payment.refund','expense.view_own','expense.view_all','expense.create',
        'expense.edit','expense.approve','expense.manage','customer.view','customer.view_all','customer.create',
        'customer.edit','customer.delete','product.view','product.create','product.edit','product.change_price',
        'product.delete','inventory.view','inventory.adjust','reports.sales','reports.operational','reports.profit',
        'reports.tax','sales_book.view','accounting_period.view','users.view','users.manage','audit.view',
        'financial.export'
      )
    when role_value.role_code = 'employee' then
      role_value.permission_code in (
        'company.read','invoice.view','invoice.view_all','invoice.create','invoice.edit','invoice.apply_discount','invoice.change_dates','invoice.issue',
        'invoice.delete_draft','offer.create','offer.manage','proforma.create','proforma.manage','order.create',
        'order.manage','delivery_note.create','delivery_note.manage','payment.view','payment.create',
        'expense.view_own','expense.create','expense.edit','customer.view','customer.view_all','customer.create',
        'customer.edit','product.view','product.create','product.edit','inventory.view'
      )
    else false
  end
  from role_value;
$$;


--
-- Name: rbac_permission_candidates(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_permission_candidates(p_permission text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with key_value as (
    select private.rbac_canonical_permission(p_permission) as key
  ), candidates as (
    select key from key_value
    union
    select case key
      when 'invoice.view' then 'invoice.view_all'
      when 'customer.view' then 'customer.view_all'
      when 'expense.view_own' then 'expense.view_all'
      when 'payment.view' then 'payment.view_all'
      else null
    end
    from key_value
  )
  select coalesce(array_agg(key order by key), '{}'::text[])
  from candidates
  where key is not null and key <> '';
$$;


--
-- Name: rbac_permission_override_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_permission_override_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare target_role text;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') = 'service_role'
     or private.rbac_is_platform_admin()
     or not new.enabled then
    return new;
  end if;
  select private.rbac_member_role_code(new.membership_id) into target_role;
  if target_role is null or not private.rbac_permission_assignable(target_role, new.permission_code) then
    raise exception 'The selected permission cannot be granted to this tenant role' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: rbac_posted_state_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_posted_state_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  new_state text := lower(coalesce(to_jsonb(new) ->> 'accounting_state', 'legacy'));
  old_state text := lower(coalesce(to_jsonb(old) ->> 'accounting_state', 'legacy'));
  financial_workflow boolean := coalesce(current_setting('app.financial_workflow', true), '') = 'authorized';
  auxiliary_workflow boolean := tg_table_name = 'invoices'
    and coalesce(current_setting('app.invoice_auxiliary_workflow', true), '') = 'authorized'
    and tg_op = 'UPDATE'
    and old_state = new_state;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') = 'service_role'
     or private.rbac_is_platform_admin()
     or financial_workflow
     or auxiliary_workflow then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  if new_state in ('posted','reversed','opening_balance')
     and (tg_op = 'INSERT' or new_state is distinct from old_state) then
    raise exception 'Posted financial state can only be created by the controlled accounting workflow'
      using errcode = '55000';
  end if;
  return new;
end;
$$;


--
-- Name: rbac_product_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_product_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE'
     and new.company_id is not null
     and (new.unit_price is distinct from old.unit_price
       or new.supplier_unit_price is distinct from old.supplier_unit_price
       or new.supplier_unit_price_after_discount is distinct from old.supplier_unit_price_after_discount)
     and not private.has_company_permission(new.company_id, 'product.change_price') then
    raise exception 'Product price permission is required' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE'
     and new.company_id is not null
     and (new.stock_quantity is distinct from old.stock_quantity
       or new.track_stock is distinct from old.track_stock
       or new.low_stock_threshold is distinct from old.low_stock_threshold)
     and not private.has_company_permission(new.company_id, 'inventory.adjust')
     and not private.has_company_permission(new.company_id, 'invoice.issue') then
    raise exception 'Inventory adjustment permission is required' using errcode = '42501';
  end if;
  if tg_op = 'DELETE'
     and old.company_id is not null
     and not private.has_company_permission(old.company_id, 'product.delete') then
    raise exception 'Product delete permission is required' using errcode = '42501';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


--
-- Name: rbac_profile_authorization_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_profile_authorization_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target_company_id uuid := coalesce(
    new.active_company_id,
    old.active_company_id,
    new.company_id,
    old.company_id,
    (
      select membership.company_id
      from public.memberships membership
      where membership.user_id = (select auth.uid())
        and coalesce(membership.status, 'active') = 'active'
      order by membership.created_at, membership.id
      limit 1
    )
  );
begin
  if coalesce((select auth.jwt() ->> 'role'), '') = 'service_role'
     or coalesce(current_setting('app.company_link_workflow', true), '') = 'authorized'
     or coalesce(current_setting('app.active_company_switch', true), '') = 'authorized'
     or coalesce(current_setting('app.user_access_profile_workflow', true), '') = 'authorized'
     or private.rbac_is_platform_admin() then
    return new;
  end if;

  if new.role is distinct from old.role or new.company_id is distinct from old.company_id then
    raise exception 'Role and company membership are managed by protected workflows' using errcode = '42501';
  end if;
  if new.active_company_id is not null and not public.can_access_company(new.active_company_id) then
    raise exception 'You cannot select a company without an active membership' using errcode = '42501';
  end if;
  if target_company_id is not null
     and (
       new.company_name is distinct from old.company_name
       or new.email is distinct from old.email
       or new.phone is distinct from old.phone
       or new.address is distinct from old.address
       or new.website is distinct from old.website
     )
     and not private.has_company_permission(target_company_id, 'settings.company') then
    raise exception 'Company settings permission is required' using errcode = '42501';
  end if;
  if target_company_id is not null
     and (
       new.tax_rate is distinct from old.tax_rate
       or new.tax_name is distinct from old.tax_name
       or new.tax_id is distinct from old.tax_id
     )
     and not private.has_company_permission(target_company_id, 'settings.tax') then
    raise exception 'Tax settings permission is required' using errcode = '42501';
  end if;
  if target_company_id is not null
     and (
       new.logo_url is distinct from old.logo_url
       or new.signature_url is distinct from old.signature_url
       or new.stamp_url is distinct from old.stamp_url
       or new.template_config is distinct from old.template_config
       or new.primary_color is distinct from old.primary_color
       or new.is_grayscale is distinct from old.is_grayscale
       or new.invoice_language is distinct from old.invoice_language
       or new.terms_conditions is distinct from old.terms_conditions
       or new.default_client_discount is distinct from old.default_client_discount
     )
     and not private.has_company_permission(target_company_id, 'settings.invoice') then
    raise exception 'Invoice document settings permission is required' using errcode = '42501';
  end if;
  if target_company_id is not null
     and (
       new.bank_name is distinct from old.bank_name
       or new.bank_account is distinct from old.bank_account
       or new.bank_iban is distinct from old.bank_iban
       or new.bank_swift is distinct from old.bank_swift
       or new.payment_link_stripe is distinct from old.payment_link_stripe
       or new.payment_link_paypal is distinct from old.payment_link_paypal
     )
     and not private.has_company_permission(target_company_id, 'settings.bank') then
    raise exception 'Bank settings permission is required' using errcode = '42501';
  end if;
  if target_company_id is not null
     and (
       new.stripe_api_key is distinct from old.stripe_api_key
       or new.stripe_account_id is distinct from old.stripe_account_id
       or new.stripe_last_synced is distinct from old.stripe_last_synced
       or new.stripe_access_token is distinct from old.stripe_access_token
       or new.stripe_refresh_token is distinct from old.stripe_refresh_token
       or new.stripe_connected_at is distinct from old.stripe_connected_at
       or new.stripe_livemode is distinct from old.stripe_livemode
     )
     and not private.has_company_permission(target_company_id, 'settings.integrations') then
    raise exception 'Integration settings permission is required' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: rbac_related_record_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_related_record_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  related_company uuid;
  related_user uuid;
  related_assigned uuid;
  product_company uuid;
  invoice_company uuid;
  invoice_user uuid;
  invoice_assigned uuid;
  optional_id uuid;
  period_status text;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') = 'service_role'
     or private.rbac_is_platform_admin() then
    return new;
  end if;

  if tg_table_name = 'invoices' then
    if new.client_id is not null then
      select client.company_id, client.user_id, client.assigned_user_id
        into related_company, related_user, related_assigned
      from public.clients client
      where client.id = new.client_id;
      if not found or related_company is distinct from new.company_id then
        raise exception 'Invoice customer must belong to the same tenant' using errcode = '42501';
      end if;
      if not private.rbac_can_read_resource(new.company_id, 'customer', related_user, related_assigned, 'customer.view') then
        raise exception 'Invoice customer is outside the caller data scope' using errcode = '42501';
      end if;
    end if;
  elsif tg_table_name = 'invoice_items' then
    if new.product_id is not null then
      select product.company_id
        into product_company
      from public.products product
      where product.id = new.product_id;
      if not found then
        raise exception 'Invoice line product is invalid' using errcode = '42501';
      end if;
      select invoice.company_id
        into invoice_company
      from public.invoices invoice
      where invoice.id = new.invoice_id;
      if not found or product_company is distinct from invoice_company then
        raise exception 'Invoice line product must belong to the same tenant as the invoice' using errcode = '42501';
      end if;
      if not private.has_company_permission(invoice_company, 'product.view') then
        raise exception 'Invoice line product permission is required' using errcode = '42501';
      end if;
    end if;
  elsif tg_table_name = 'payments' then
    if new.client_id is not null then
      select client.company_id, client.user_id, client.assigned_user_id
        into related_company, related_user, related_assigned
      from public.clients client
      where client.id = new.client_id;
      if not found or related_company is distinct from new.company_id then
        raise exception 'Payment customer must belong to the same tenant' using errcode = '42501';
      end if;
      if not private.rbac_can_read_resource(new.company_id, 'customer', related_user, related_assigned, 'payment.create') then
        raise exception 'Payment customer is outside the caller data scope' using errcode = '42501';
      end if;
    end if;
    if new.invoice_id is not null then
      select invoice.company_id, invoice.user_id, invoice.assigned_user_id
        into related_company, invoice_user, invoice_assigned
      from public.invoices invoice
      where invoice.id = new.invoice_id;
      if not found or related_company is distinct from new.company_id then
        raise exception 'Payment invoice must belong to the same tenant' using errcode = '42501';
      end if;
      if not private.rbac_can_read_resource(new.company_id, 'invoice', invoice_user, invoice_assigned, 'invoice.view') then
        raise exception 'Payment invoice is outside the caller data scope' using errcode = '42501';
      end if;
    end if;
  elsif tg_table_name = 'expenses' then
    optional_id := nullif(to_jsonb(new) ->> 'vendor_id', '')::uuid;
    if optional_id is not null and to_regclass('public.vendors') is not null then
      related_company := null;
      execute 'select company_id from public.vendors where id = $1'
        into related_company
        using optional_id;
      if related_company is null or (new.company_id is not null and related_company is distinct from new.company_id) then
        raise exception 'Expense vendor must belong to the same tenant' using errcode = '42501';
      end if;
    end if;
    optional_id := nullif(to_jsonb(new) ->> 'accounting_period_id', '')::uuid;
    if optional_id is not null then
      select period.status
        into period_status
      from public.accounting_periods period
      where period.id = optional_id
        and period.company_id = new.company_id;
      if not found then
        raise exception 'Expense accounting period must belong to the same tenant' using errcode = '42501';
      end if;
      if period_status in ('closed', 'locked') then
        raise exception 'Expenses cannot be created or edited in a closed accounting period' using errcode = '55000';
      end if;
    end if;
  end if;

  return new;
end;
$_$;


--
-- Name: rbac_role_code(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_role_code(p_company_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with recursive ancestors(id, depth) as (
    select p_company_id, 0
    union all
    select company.parent_company_id, ancestors.depth + 1
    from public.companies company
    join ancestors on ancestors.id = company.id
    where company.parent_company_id is not null
  )
  select case
    when exists (
      select 1
      from ancestors
      join public.companies company on company.id = ancestors.id
      where company.owner_id = (select auth.uid())
    ) then 'company_administrator'
    when private.rbac_actor_membership(p_company_id) is null then null
    else private.rbac_member_role_code(private.rbac_actor_membership(p_company_id))
  end;
$$;


--
-- Name: rbac_scope_allows(uuid, text, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_scope_allows(p_company_id uuid, p_resource text, p_owner_user_id uuid, p_assigned_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_company_id is not null
    and private.rbac_role_code(p_company_id) is not null
    and case private.rbac_scope_for(p_company_id, p_resource)
      when 'ALL' then true
      when 'ASSIGNED' then p_owner_user_id = (select auth.uid())
        or p_assigned_user_id = (select auth.uid())
      else p_owner_user_id = (select auth.uid())
    end;
$$;


--
-- Name: rbac_scope_for(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_scope_for(p_company_id uuid, p_resource text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when private.rbac_is_platform_admin() then 'ALL'
    when private.rbac_role_code(p_company_id) = 'company_administrator' then 'ALL'
    else coalesce(private.rbac_member_scope(private.rbac_actor_membership(p_company_id), p_resource), 'OWN')
  end;
$$;


--
-- Name: rbac_scope_override_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_scope_override_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target_role text;
  view_all_permission text;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') = 'service_role'
     or private.rbac_is_platform_admin() then
    return new;
  end if;
  if new.resource not in ('invoice','offer','proforma','order','delivery_note','customer','expense','payment','product','inventory') then
    raise exception 'The selected data scope is not valid' using errcode = '22023';
  end if;
  if upper(new.scope) = 'ALL' and new.resource in ('invoice','customer','expense') then
    view_all_permission := case new.resource
      when 'invoice' then 'invoice.view_all'
      when 'customer' then 'customer.view_all'
      else 'expense.view_all'
    end;
    if not private.rbac_member_has_permission(new.membership_id, view_all_permission) then
      raise exception 'ALL scope requires the matching view-all permission' using errcode = '42501';
    end if;
  end if;
  select private.rbac_member_role_code(new.membership_id) into target_role;
  if target_role is null then
    raise exception 'The target membership has no active tenant role' using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: rbac_supplier_related_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_supplier_related_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  vendor_company uuid;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') = 'service_role'
     or private.rbac_is_platform_admin() then
    return new;
  end if;
  if tg_table_name in ('supplier_bills', 'vendor_payments') and new.vendor_id is not null then
    select vendor.company_id into vendor_company
    from public.vendors vendor
    where vendor.id = new.vendor_id;
    if vendor_company is null or vendor_company is distinct from new.company_id then
      raise exception 'Supplier record must belong to the same tenant' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: rbac_user_role_id(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_user_role_id(p_role_code text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select role.id
  from public.app_roles role
  where role.company_id is null
    and role.code = case lower(trim(coalesce(p_role_code, '')))
      when 'admin' then 'company_administrator'
      else lower(trim(coalesce(p_role_code, '')))
    end
    and role.code in ('company_administrator', 'manager', 'employee')
  limit 1;
$$;


--
-- Name: rbac_validate_user_access_payload(text, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_validate_user_access_payload(p_role_code text, p_permissions jsonb, p_scopes jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  role_value text := case lower(trim(coalesce(p_role_code, '')))
    when 'admin' then 'company_administrator'
    else lower(trim(coalesce(p_role_code, '')))
  end;
  permission_entry record;
  scope_entry record;
  view_all_permission text;
begin
  if role_value not in ('company_administrator', 'manager', 'employee') then
    raise exception 'Only Admin, Manager, and Employee roles can be assigned' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_permissions, '{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_scopes, '{}'::jsonb)) <> 'object' then
    raise exception 'Permissions and scopes must be JSON objects' using errcode = '22023';
  end if;
  for permission_entry in select key, value from jsonb_each(coalesce(p_permissions, '{}'::jsonb)) loop
    if not private.rbac_is_invoice_permission(permission_entry.key)
       or jsonb_typeof(permission_entry.value) <> 'boolean' then
      raise exception 'A permission is not valid for Invoice or is not boolean' using errcode = '22023';
    end if;
    if (permission_entry.value #>> '{}')::boolean
       and role_value <> 'company_administrator'
       and not private.rbac_permission_assignable(role_value, permission_entry.key) then
      raise exception 'The selected permission cannot be assigned to this tenant role' using errcode = '42501';
    end if;
  end loop;
  for scope_entry in select key, value from jsonb_each_text(coalesce(p_scopes, '{}'::jsonb)) loop
    if scope_entry.key not in ('invoice','offer','proforma','order','delivery_note','customer','expense','payment','product','inventory')
       or upper(scope_entry.value) not in ('OWN','ASSIGNED','ALL') then
      raise exception 'A data scope is not valid' using errcode = '22023';
    end if;
    if upper(scope_entry.value) = 'ALL' and scope_entry.key in ('invoice','customer','expense') then
      view_all_permission := case scope_entry.key
        when 'invoice' then 'invoice.view_all'
        when 'customer' then 'customer.view_all'
        else 'expense.view_all'
      end;
      if role_value <> 'company_administrator'
         and coalesce((p_permissions ->> view_all_permission)::boolean, false) = false
         and not exists (
           select 1
           from public.app_roles role
           join public.app_role_permissions role_permission on role_permission.role_id = role.id
           where role.company_id is null
             and role.code = role_value
             and role_permission.permission_code = view_all_permission
         ) then
        raise exception 'ALL scope requires the matching view-all permission' using errcode = '42501';
      end if;
    end if;
  end loop;
end;
$$;


--
-- Name: rbac_write_audit(uuid, text, text, uuid, jsonb, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.rbac_write_audit(p_company_id uuid, p_action text, p_entity_type text, p_entity_id uuid, p_previous jsonb, p_new jsonb, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.audit_events(
    company_id, actor_user_id, action, entity_type, entity_id,
    previous_values, new_values, reason
  ) values (
    p_company_id, (select auth.uid()), p_action, p_entity_type, p_entity_id,
    p_previous, p_new, p_reason
  );
end;
$$;


