CREATE FUNCTION private.rbac_write_user_access_audit(p_company_id uuid, p_actor_id uuid, p_action text, p_entity_type text, p_entity_id uuid, p_previous jsonb, p_new jsonb, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  insert into public.audit_events(company_id, actor_user_id, action, entity_type, entity_id, previous_values, new_values, reason)
  values (p_company_id, p_actor_id, p_action, p_entity_type, p_entity_id, p_previous, p_new, p_reason);
$$;


