--
-- Name: redact_audit_payload(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.redact_audit_payload(payload jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when payload is null then null
    else payload
      - 'smtp_pass'
      - 'smtp_password'
      - 'stripe_api_key'
      - 'stripe_access_token'
      - 'stripe_refresh_token'
      - 'payment_link_stripe'
      - 'payment_link_paypal'
      - 'invite_token'
  end;
$$;


--
-- Name: payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    company_id uuid,
    client_id uuid,
    invoice_id uuid,
    payment_number text NOT NULL,
    amount numeric DEFAULT 0 NOT NULL,
    payment_date date DEFAULT CURRENT_DATE,
    payment_method text DEFAULT 'cash'::text,
    bank_reference text,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    branch_id uuid,
    currency text DEFAULT 'EUR'::text NOT NULL,
    exchange_rate numeric(20,10) DEFAULT 1 NOT NULL,
    allocation_status text DEFAULT 'legacy'::text NOT NULL,
    posting_journal_entry_id uuid,
    posted_at timestamp with time zone,
    reversed_at timestamp with time zone,
    reversal_journal_entry_id uuid,
    reversal_reason text,
    idempotency_key uuid,
    accounting_state text DEFAULT 'legacy'::text NOT NULL,
    settlement_account_id uuid,
    company_bank_account_id uuid,
    payer_name text,
    external_reference text,
    fund_account_id uuid,
    attachment_id uuid,
    payment_status text DEFAULT 'posted'::text NOT NULL,
    assigned_user_id uuid,
    CONSTRAINT payments_accounting_state_check CHECK ((accounting_state = ANY (ARRAY['legacy'::text, 'ready_for_posting'::text, 'posted'::text, 'reversed'::text, 'opening_balance'::text, 'excluded'::text]))),
    CONSTRAINT payments_allocation_status_check CHECK ((allocation_status = ANY (ARRAY['legacy'::text, 'unallocated'::text, 'partially_allocated'::text, 'allocated'::text, 'reversed'::text]))),
    CONSTRAINT payments_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT payments_exchange_rate_check CHECK ((exchange_rate > (0)::numeric)),
    CONSTRAINT payments_payment_status_check CHECK ((payment_status = ANY (ARRAY['posted'::text, 'voided'::text, 'reversed'::text])))
);


--
-- Name: refresh_customer_payment_allocation_state(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refresh_customer_payment_allocation_state(p_payment_id uuid) RETURNS public.payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payment_row public.payments;
  allocated_total numeric(20,4);
  next_status text;
begin
  select *
  into payment_row
  from public.payments
  where id = p_payment_id
  for update;

  if not found then
    raise exception 'Payment not found' using errcode = 'P0002';
  end if;

  select round(coalesce(sum(allocated_amount), 0), 4)
  into allocated_total
  from public.payment_allocations
  where payment_id = payment_row.id
    and status = 'active';

  if payment_row.accounting_state = 'reversed' then
    next_status := 'reversed';
  elsif allocated_total = 0 then
    next_status := 'unallocated';
  elsif allocated_total >= round(payment_row.amount, 4) then
    next_status := 'allocated';
  else
    next_status := 'partially_allocated';
  end if;

  perform set_config('app.financial_workflow', 'authorized', true);
  update public.payments
  set allocation_status = next_status
  where id = payment_row.id
  returning * into payment_row;
  perform set_config('app.financial_workflow', '', true);

  return payment_row;
end
$$;


