    fiscalization_status text DEFAULT 'NOT_REQUIRED'::text NOT NULL,
    supply_date date,
    order_date date,
    delivery_date date,
    payment_date date,
    valid_until date,
    customer_po_number text,
    delivery_address text,
    shipping_address text,
    payment_terms text,
    delivery_terms text,
    show_prices_on_delivery_note boolean DEFAULT true NOT NULL,
    correction_reason_code text,
    original_invoice_id uuid,
    advance_applied_amount numeric(20,4) DEFAULT 0 NOT NULL,
    immutable_at timestamp with time zone,
    issued_at timestamp with time zone,
    issued_by uuid,
    advance_applied_tax_amount numeric(20,4) DEFAULT 0 NOT NULL,
    advance_reconciliation_status text DEFAULT 'NOT_APPLICABLE'::text NOT NULL,
    shipping_amount numeric(20,4) DEFAULT 0 NOT NULL,
    shipping_tax_amount numeric(20,4) DEFAULT 0 NOT NULL,
    transport_amount numeric(20,4) DEFAULT 0 NOT NULL,
    transport_tax_amount numeric(20,4) DEFAULT 0 NOT NULL,
    additional_fee_amount numeric(20,4) DEFAULT 0 NOT NULL,
    additional_fee_tax_amount numeric(20,4) DEFAULT 0 NOT NULL,
    show_product_pictures boolean DEFAULT false NOT NULL,
    delivery_method text,
    pickup_branch_id uuid,
    delivery_details text,
    sales_book_period_id uuid,
    stripe_store_id uuid,
    post_cod boolean DEFAULT false NOT NULL,
    assigned_user_id uuid,
    external_reference text,
    CONSTRAINT invoices_accounting_state_check CHECK ((accounting_state = ANY (ARRAY['legacy'::text, 'ready_for_posting'::text, 'posted'::text, 'reversed'::text, 'opening_balance'::text, 'excluded'::text]))),
    CONSTRAINT invoices_additional_fee_amount_check CHECK ((additional_fee_amount >= (0)::numeric)),
    CONSTRAINT invoices_additional_fee_tax_amount_check CHECK ((additional_fee_tax_amount >= (0)::numeric)),
    CONSTRAINT invoices_advance_applied_amount_check CHECK ((advance_applied_amount >= (0)::numeric)),
    CONSTRAINT invoices_advance_applied_tax_amount_check CHECK ((advance_applied_tax_amount >= (0)::numeric)),
    CONSTRAINT invoices_advance_reconciliation_status_check CHECK ((advance_reconciliation_status = ANY (ARRAY['NOT_APPLICABLE'::text, 'PENDING'::text, 'RECONCILED'::text, 'REQUIRES_REVIEW'::text]))),
    CONSTRAINT invoices_approval_status_check CHECK ((approval_status = ANY (ARRAY['not_required'::text, 'pending'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT invoices_buyer_signature_size_check CHECK (((buyer_signature_url IS NULL) OR (length(buyer_signature_url) <= 2000000))),
    CONSTRAINT invoices_commercial_document_type_check CHECK ((commercial_document_type = ANY (ARRAY['QUOTE'::text, 'PROFORMA'::text, 'SALES_ORDER'::text, 'DELIVERY_NOTE'::text, 'INVOICE'::text, 'ADVANCE_INVOICE'::text, 'FINAL_INVOICE'::text, 'CREDIT_NOTE'::text, 'DEBIT_NOTE'::text, 'SIMPLIFIED_INVOICE'::text, 'FISCAL_RECEIPT'::text, 'BAD_DEBT_INVOICE'::text]))),
    CONSTRAINT invoices_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT invoices_customer_signature_status_check CHECK ((((customer_signature_status = 'not_requested'::text) AND (customer_signature_requested = false) AND (buyer_signature_url IS NULL)) OR ((customer_signature_status = 'pending'::text) AND (customer_signature_requested = true) AND (buyer_signature_url IS NULL)) OR ((customer_signature_status = 'signed'::text) AND (customer_signature_requested = true) AND (buyer_signature_url IS NOT NULL)) OR ((customer_signature_status = 'declined'::text) AND (customer_signature_requested = true)))),
    CONSTRAINT invoices_delivery_method_check CHECK (((delivery_method IS NULL) OR (delivery_method = ANY (ARRAY['pickup'::text, 'delivery'::text, 'bus'::text, 'other'::text])))),
    CONSTRAINT invoices_exchange_rate_check CHECK ((exchange_rate > (0)::numeric)),
    CONSTRAINT invoices_shipping_amount_check CHECK ((shipping_amount >= (0)::numeric)),
    CONSTRAINT invoices_shipping_tax_amount_check CHECK ((shipping_tax_amount >= (0)::numeric)),
    CONSTRAINT invoices_tax_reporting_category_check CHECK (((tax_reporting_category IS NULL) OR (tax_reporting_category = ANY (ARRAY['domestic_standard_18'::text, 'domestic_reduced_8'::text, 'exempt_no_credit'::text, 'foreign_services'::text, 'domestic_reverse_charge'::text, 'exempt_with_credit'::text, 'export'::text, 'debit_credit_18'::text, 'debit_credit_8'::text, 'bad_debt_18'::text, 'bad_debt_8'::text, 'vat_adjustment_18'::text, 'vat_adjustment_8'::text, 'reverse_charge_purchase_18'::text, 'international_organization'::text])))),
    CONSTRAINT invoices_transport_amount_check CHECK ((transport_amount >= (0)::numeric)),
    CONSTRAINT invoices_transport_tax_amount_check CHECK ((transport_tax_amount >= (0)::numeric))
);


--
-- Name: refresh_customer_payment_state(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refresh_customer_payment_state(p_invoice_id uuid) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  invoice_row public.invoices;
  allocated_total numeric(20,4);
  next_status public.invoice_status;
begin
  select *
  into invoice_row
  from public.invoices
  where id = p_invoice_id
  for update;

  if not found then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if invoice_row.accounting_state <> 'posted' then
    return invoice_row;
  end if;

  select round(coalesce(sum(allocated_amount), 0), 4)
  into allocated_total
  from public.payment_allocations
  where invoice_id = invoice_row.id
    and status = 'active';

  if allocated_total >= round(invoice_row.total_amount, 4) then
    next_status := 'paid';
  elsif allocated_total > 0 then
    next_status := 'partially_paid';
  elsif invoice_row.due_date < current_date then
    next_status := 'overdue';
  else
    next_status := 'posted';
  end if;

  perform set_config('app.financial_workflow', 'authorized', true);
  update public.invoices
  set status = next_status
  where id = invoice_row.id
  returning * into invoice_row;
  perform set_config('app.financial_workflow', '', true);

  return invoice_row;
end
$$;


--
-- Name: subscription_usage; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.subscription_usage (
    company_id uuid NOT NULL,
    total_tenants integer DEFAULT 0 NOT NULL,
    included_tenants integer DEFAULT 1 NOT NULL,
    billable_tenants integer DEFAULT 0 NOT NULL,
    total_users integer DEFAULT 0 NOT NULL,
    included_users integer DEFAULT 1 NOT NULL,
    billable_users integer DEFAULT 0 NOT NULL,
    last_synced_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT subscription_usage_billable_tenants_check CHECK ((billable_tenants >= 0)),
    CONSTRAINT subscription_usage_billable_users_check CHECK ((billable_users >= 0)),
    CONSTRAINT subscription_usage_included_tenants_check CHECK ((included_tenants = 1)),
    CONSTRAINT subscription_usage_included_users_check CHECK ((included_users = 1)),
    CONSTRAINT subscription_usage_total_tenants_check CHECK ((total_tenants >= 0)),
    CONSTRAINT subscription_usage_total_users_check CHECK ((total_users >= 0))
);


--
-- Name: refresh_invoice_subscription_usage(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refresh_invoice_subscription_usage(p_company_id uuid) RETURNS public.subscription_usage
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  root_company_id uuid;
  tenant_count integer;
  user_count integer;
  usage_row public.subscription_usage;
begin
  select case
    when exists (select 1 from public.subscription_accounts where company_id = p_company_id) then p_company_id
    else private.invoice_billing_root_company_id(p_company_id)
  end into root_company_id;
  if root_company_id is null then raise exception 'Billing account was not found' using errcode = '22023'; end if;

  select count(*)::integer into tenant_count
  from public.companies company
  where private.invoice_company_is_in_root(root_company_id, company.id)
    and company.archived_at is null
    and lower(coalesce(company.settings ->> 'status', 'active')) not in ('archived','deleted','suspended','disabled','inactive')
    and lower(coalesce(company.settings ->> 'is_internal', 'false')) not in ('true','1','yes')
    and lower(coalesce(company.settings ->> 'is_demo', 'false')) not in ('true','1','yes')
    and nullif(company.settings ->> 'deleted_at', '') is null
    and nullif(company.settings ->> 'suspended_at', '') is null;
  user_count := private.invoice_billable_user_count(root_company_id);

  insert into public.subscription_usage(company_id,total_tenants,billable_tenants,total_users,billable_users,updated_at)
  values(root_company_id,tenant_count,greatest(tenant_count - 1,0),user_count,greatest(user_count - 1,0),clock_timestamp())
  on conflict(company_id) do update set
    total_tenants = excluded.total_tenants,
    billable_tenants = excluded.billable_tenants,
    total_users = excluded.total_users,
    billable_users = excluded.billable_users,
    updated_at = excluded.updated_at
  returning * into usage_row;

  insert into public.subscription_sync_queue(company_id,requested_at,status,last_error,updated_at)
  values(root_company_id,clock_timestamp(),'pending',null,clock_timestamp())
  on conflict(company_id) do update set
    requested_at = excluded.requested_at,
    status = case when public.subscription_sync_queue.status = 'processing' then 'processing' else 'pending' end,
    last_error = null,
    updated_at = excluded.updated_at;
  return usage_row;
end;
$$;


