-- Name: reject_fiscal_attempt_secrets(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reject_fiscal_attempt_secrets() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  perform private.reject_efs_secret_json(new.network_metadata, 'fiscal network metadata');
  perform private.reject_efs_secret_json(new.result_payload, 'fiscal provider response');
  return new;
end
$$;


--
-- Name: reject_fiscal_reconciliation_secrets(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reject_fiscal_reconciliation_secrets() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  perform private.reject_efs_secret_json(new.details, 'fiscal reconciliation details');
