--
-- Name: require_operix_product_access(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.require_operix_product_access(p_company_id uuid, p_product text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if lower(trim(coalesce(p_product, ''))) not in ('hr', 'desk') then
    raise exception 'Enterprise product required' using errcode = '42501';
  end if;
  if not private.operix_product_access(p_company_id, lower(trim(p_product))) then
    raise exception 'Enterprise product access is required' using errcode = '42501';
  end if;
end;
$$;


--
-- Name: resolve_pos_terminal(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.resolve_pos_terminal(p_company_id uuid, p_terminal_id uuid DEFAULT NULL::uuid) RETURNS public.pos_terminals
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  terminal_row public.pos_terminals;
begin
  if p_terminal_id is not null then
    select * into terminal_row
    from public.pos_terminals
    where id = p_terminal_id and company_id = p_company_id and status = 'active';
  else
    select * into terminal_row
    from public.pos_terminals
    where company_id = p_company_id and status = 'active'
    order by created_at
    limit 2;
    if found and (select count(*) from public.pos_terminals where company_id = p_company_id and status = 'active') > 1 then
      raise exception 'Select a POS terminal before completing a sale' using errcode = '23514';
    end if;
  end if;
  if not found then
    raise exception 'An active POS terminal is required before completing a sale' using errcode = '23514';
  end if;
  return terminal_row;
end
$$;


--
-- Name: sales_book_company_frequency(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_book_company_frequency(p_company_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  company_row public.companies;
  configured_frequency text;
begin
  select * into company_row from public.companies where id = p_company_id;
  if not found then
    raise exception 'Company not found' using errcode = 'P0002';
  end if;

  configured_frequency := lower(nullif(trim(coalesce(company_row.accounting_period_frequency, '')), ''));
  if configured_frequency is null then
    raise exception 'Sales Book reporting frequency is not configured for this company' using errcode = '55000';
  end if;
  if configured_frequency not in ('monthly', 'quarterly', 'annual') then
    raise exception 'Sales Book reporting frequency is not supported: %', configured_frequency using errcode = '55000';
  end if;
  return configured_frequency;
end
$$;


--
-- Name: sales_book_period_dates(date, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_book_period_dates(p_transaction_date date, p_reporting_frequency text) RETURNS TABLE(period_start date, period_end date, declaration_deadline date)
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  next_month date;
  quarter_month smallint;
begin
  if p_transaction_date is null then
    raise exception 'A transaction date is required for Sales Book assignment' using errcode = '22023';
  end if;

  if lower(coalesce(p_reporting_frequency, '')) = 'monthly' then
    period_start := date_trunc('month', p_transaction_date::timestamp)::date;
    period_end := (period_start + interval '1 month - 1 day')::date;
    next_month := (period_start + interval '1 month')::date;
    declaration_deadline := make_date(extract(year from next_month)::integer, extract(month from next_month)::integer, 20);
    return next;
    return;
  end if;

  if lower(coalesce(p_reporting_frequency, '')) = 'quarterly' then
    quarter_month := (((extract(month from p_transaction_date)::integer - 1) / 3) * 3) + 1;
    period_start := make_date(extract(year from p_transaction_date)::integer, quarter_month, 1);
    period_end := (period_start + interval '3 months - 1 day')::date;
    next_month := (period_end + interval '1 day')::date;
    declaration_deadline := make_date(extract(year from next_month)::integer, extract(month from next_month)::integer, 20);
    return next;
    return;
  end if;

  if lower(coalesce(p_reporting_frequency, '')) = 'annual' then
    period_start := make_date(extract(year from p_transaction_date)::integer, 1, 1);
    period_end := make_date(extract(year from p_transaction_date)::integer, 12, 31);
    declaration_deadline := make_date(extract(year from p_transaction_date)::integer + 1, 3, 31);
    return next;
    return;
  end if;

  raise exception 'Unsupported Sales Book reporting frequency: %', p_reporting_frequency using errcode = '22023';
end
$$;


--
-- Name: sales_book_period_is_locked(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_book_period_is_locked(p_period_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.sales_book_periods
    where id = p_period_id and status in ('DECLARED', 'AMENDED')
  );
$$;


--
-- Name: sales_book_period_snapshot(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_book_period_snapshot(p_period_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'period_id', period.id,
    'company_id', period.company_id,
    'period_start', period.period_start,
    'period_end', period.period_end,
    'declaration_deadline', period.declaration_deadline,
    'transaction_count', coalesce(summary.transaction_count, 0),
    'taxable_amount', coalesce(summary.taxable_amount, 0),
    'vat_amount', coalesce(summary.vat_amount, 0),
    'total_amount', coalesce(summary.total_amount, 0),
    'transactions', coalesce((
      select jsonb_agg(to_jsonb(book) order by book.invoice_date, book.invoice_number, book.invoice_id)
      from public.kosovo_sales_book book
      where book.sales_book_period_id = period.id
    ), '[]'::jsonb),
    'source_checksum', md5(coalesce((
      select string_agg(
        concat_ws(':', book.invoice_id::text, book.taxable_base::text, book.output_vat::text, book.total_amount::text),
        '|' order by book.invoice_id
      )
      from public.kosovo_sales_book book
      where book.sales_book_period_id = period.id
    ), ''))
  )
  from public.sales_book_periods period
  left join public.kosovo_sales_book_period_summary summary on summary.id = period.id
  where period.id = p_period_id;
$$;


--
-- Name: sales_invoice_amounts(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_invoice_amounts(p_invoice_id uuid) RETURNS TABLE(net_amount numeric, tax_amount numeric, gross_amount numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with line_totals as (
    select
      round(coalesce(item.amount, 0)::numeric, 2) as net,
      round(
        round(coalesce(item.amount, 0)::numeric, 2)
        * coalesce(item.tax_rate, 0)::numeric / 100,
        2
      ) as tax
    from public.invoice_items item
    where item.invoice_id = p_invoice_id
  ), invoice_charges as (
    select
      round(coalesce(invoice.shipping_amount, 0) + coalesce(invoice.transport_amount, 0)
        + coalesce(invoice.additional_fee_amount, 0), 2) as net,
      round(coalesce(invoice.shipping_tax_amount, 0) + coalesce(invoice.transport_tax_amount, 0)
        + coalesce(invoice.additional_fee_tax_amount, 0), 2) as tax
    from public.invoices invoice
    where invoice.id = p_invoice_id
  )
  select
    round(coalesce(sum(value.net), 0), 2),
    round(coalesce(sum(value.tax), 0), 2),
    round(coalesce(sum(value.net + value.tax), 0), 2)
  from (
    select net, tax from line_totals
    union all
    select net, tax from invoice_charges
  ) value
$$;


--
-- Name: seed_commercial_document_settings_for_company(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.seed_commercial_document_settings_for_company() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.commercial_document_settings (
    company_id, document_type, show_prices, default_valid_days, created_by, updated_by
  )
  select new.id, seed.document_type, seed.show_prices, seed.default_valid_days,
    (select auth.uid()), (select auth.uid())
  from (
    values
      ('QUOTE', true, 30),
      ('PROFORMA', true, 30),
      ('SALES_ORDER', true, null::integer),
      ('DELIVERY_NOTE', false, null::integer),
      ('INVOICE', true, null::integer),
      ('ADVANCE_INVOICE', true, null::integer),
      ('FINAL_INVOICE', true, null::integer),
      ('CREDIT_NOTE', true, null::integer),
      ('DEBIT_NOTE', true, null::integer),
      ('SIMPLIFIED_INVOICE', true, null::integer),
      ('FISCAL_RECEIPT', true, null::integer),
      ('BAD_DEBT_INVOICE', true, null::integer)
  ) as seed(document_type, show_prices, default_valid_days)
  on conflict (company_id, document_type) do nothing;
  return new;
end
$$;


--
-- Name: seed_default_posting_rules(uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.seed_default_posting_rules(p_company_id uuid, p_effective_from date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.posting_rule_sets (
    company_id, event_type, name, version, effective_from, active, metadata,
    created_by, updated_by
  )
  select p_company_id, seed.event_type, seed.name, 1, p_effective_from, true,
    jsonb_build_object('source', 'xk-operix-base-v1', 'compliance_status', 'requires_professional_review'),
    (select auth.uid()), (select auth.uid())
  from (values
    ('sales_invoice', 'Sales invoice'), ('purchase_invoice', 'Purchase invoice'),
    ('customer_payment', 'Customer payment'), ('supplier_payment', 'Supplier payment'),
    ('cash_sale', 'Cash sale'), ('pos_sale', 'POS sale'),
    ('credit_note', 'Sales credit note'), ('stock_purchase', 'Stock purchase'),
    ('cost_of_goods_sold', 'Cost of goods sold'), ('payroll', 'Payroll'),
    ('tax', 'Tax payment'), ('fixed_asset_depreciation', 'Fixed-asset depreciation'),
    ('bank_fee', 'Bank fee'), ('expense_reimbursement', 'Expense reimbursement')
  ) as seed(event_type, name)
  on conflict (company_id, event_type, version) do update
  set name = excluded.name, updated_at = clock_timestamp(), updated_by = excluded.updated_by;

  insert into public.posting_rule_lines (
    rule_set_id, company_id, line_number, account_id, amount_component, side,
    description_template
  )
  select rule_set.id, p_company_id, seed.line_number, account.id,
    seed.amount_component, seed.side, seed.description
  from (values
    ('sales_invoice',1,'1100','gross','debit','Customer receivable'), ('sales_invoice',2,'4000','net','credit','Sales revenue'), ('sales_invoice',3,'2100','tax','credit','Output VAT'),
    ('purchase_invoice',1,'6010','net','debit','Purchase expense'), ('purchase_invoice',2,'1300','tax','debit','Input VAT'), ('purchase_invoice',3,'2010','gross','credit','Supplier payable'),
    ('customer_payment',1,'1020','gross','debit','Bank receipt'), ('customer_payment',2,'1100','gross','credit','Customer receivable'),
    ('supplier_payment',1,'2010','gross','debit','Supplier payable'), ('supplier_payment',2,'1020','gross','credit','Bank payment'),
    ('cash_sale',1,'1010','gross','debit','Cash receipt'), ('cash_sale',2,'4000','net','credit','Sales revenue'), ('cash_sale',3,'2100','tax','credit','Output VAT'),
    ('pos_sale',1,'1010','gross','debit','POS receipt'), ('pos_sale',2,'4000','net','credit','POS sales revenue'), ('pos_sale',3,'2100','tax','credit','Output VAT'),
    ('credit_note',1,'4900','net','debit','Sales return'), ('credit_note',2,'2100','tax','debit','Output VAT adjustment'), ('credit_note',3,'1100','gross','credit','Customer receivable adjustment'),
    ('stock_purchase',1,'1200','net','debit','Inventory received'), ('stock_purchase',2,'1300','tax','debit','Input VAT'), ('stock_purchase',3,'2010','gross','credit','Supplier payable'),
    ('cost_of_goods_sold',1,'5000','cost','debit','Cost of goods sold'), ('cost_of_goods_sold',2,'1200','cost','credit','Inventory issued'),
    ('payroll',1,'6100','gross','debit','Gross payroll expense'), ('payroll',2,'6110','employer_pension','debit','Employer pension expense'),
    ('payroll',3,'2230','employee_tax','credit','Employee tax payable'), ('payroll',4,'2220','employee_pension','credit','Employee pension payable'),
    ('payroll',5,'2220','employer_pension','credit','Employer pension payable'), ('payroll',6,'2210','net_pay','credit','Net salaries payable'),
    ('tax',1,'2100','gross','debit','Tax liability settled'), ('tax',2,'1020','gross','credit','Tax payment'),
    ('fixed_asset_depreciation',1,'6200','gross','debit','Depreciation expense'), ('fixed_asset_depreciation',2,'1590','gross','credit','Accumulated depreciation'),
    ('bank_fee',1,'6300','gross','debit','Bank fee expense'), ('bank_fee',2,'1020','gross','credit','Bank fee payment'),
    ('expense_reimbursement',1,'6010','gross','debit','Expense reimbursement'), ('expense_reimbursement',2,'1020','gross','credit','Reimbursement payment')
  ) as seed(event_type, line_number, account_code, amount_component, side, description)
  join public.posting_rule_sets rule_set on rule_set.company_id=p_company_id and rule_set.event_type=seed.event_type and rule_set.version=1
  join public.chart_of_accounts account on account.company_id=p_company_id and account.code=seed.account_code
  on conflict (rule_set_id, line_number) do update set
    account_id=excluded.account_id, amount_component=excluded.amount_component,
    side=excluded.side, description_template=excluded.description_template;
end
$$;


--
-- Name: seed_membership_app_access(); Type: FUNCTION; Schema: private; Owner: -
--

