--
-- Name: sync_payment_fund_transaction(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_payment_fund_transaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare target_fund_id uuid;
declare payment_method text := lower(coalesce(new.payment_method, 'cash'));
declare payment_amount numeric(20,4) := round(coalesce(new.amount, 0), 4);
begin
  if tg_op = 'DELETE' then
    update public.company_fund_transactions set status='reversed', reversed_at=clock_timestamp(), reversed_by=(select auth.uid())
    where source_type='customer_payment' and source_id=old.id and status='active';
    return old;
  end if;
  update public.company_fund_transactions set status='reversed', reversed_at=clock_timestamp(), reversed_by=(select auth.uid())
  where source_type='customer_payment' and source_id=new.id and status='active';
  if coalesce(new.accounting_state,'') <> 'posted' or payment_amount <= 0 or coalesce(new.payment_status,'posted') in ('voided','reversed') then return new; end if;
  target_fund_id := new.fund_account_id;
  if target_fund_id is null and payment_method = 'cash' then
    select id into target_fund_id from public.company_fund_accounts where company_id=new.company_id and fund_type='cash' and is_active;
  elsif target_fund_id is null then
    select id into target_fund_id from public.company_fund_accounts
    where company_id=new.company_id and fund_type='bank' and company_bank_account_id=new.company_bank_account_id and is_active;
    if target_fund_id is null then
      select fund.id into target_fund_id from public.company_fund_accounts fund
      join public.company_bank_accounts bank on bank.id=fund.company_bank_account_id
      where fund.company_id=new.company_id and fund.fund_type='bank' and fund.is_active and bank.is_active
      order by bank.is_primary desc, bank.created_at limit 1;
    end if;
  end if;
  if target_fund_id is not null then
    insert into public.company_fund_transactions(company_id,fund_account_id,transaction_type,signed_amount,currency,transaction_date,description,source_type,source_id,created_by,payment_method,reference,counterparty,reconciliation_status)
    values(new.company_id,target_fund_id,'income',payment_amount,upper(coalesce(nullif(new.currency,''),'EUR')),new.payment_date,coalesce(nullif(trim(new.notes),''),nullif(trim(new.external_reference),''),'Customer payment'),'customer_payment',new.id,coalesce((select auth.uid()),new.user_id),new.payment_method,coalesce(new.external_reference,new.bank_reference),coalesce(new.payer_name,(select name from public.clients where id=new.client_id)),'unreconciled');
  end if;
  return new;
end;
$$;


--
-- Name: sync_sales_book_company_setup(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_sales_book_company_setup() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  frequency text;
  first_date date;
  cursor_date date;
  today date := (timezone('Europe/Belgrade', clock_timestamp()))::date;
begin
  if tg_op = 'UPDATE'
     and new.vat_registration_status is not distinct from old.vat_registration_status
     and new.accounting_period_frequency is not distinct from old.accounting_period_frequency
     and new.vat_registration_date is not distinct from old.vat_registration_date then
    return new;
  end if;

  frequency := private.sales_book_company_frequency(new.id);
  first_date := coalesce(
    new.vat_registration_date,
    (select min(invoice.issue_date) from public.invoices invoice where invoice.company_id = new.id),
    today
  );
  cursor_date := first_date;
  perform set_config('app.sales_book_workflow', 'migration', true);
  while cursor_date <= today loop
    perform private.ensure_sales_book_period(new.id, cursor_date, null);
    cursor_date := case frequency
      when 'monthly' then (date_trunc('month', cursor_date::timestamp) + interval '1 month')::date
      when 'quarterly' then (date_trunc('quarter', cursor_date::timestamp) + interval '3 months')::date
      else (date_trunc('year', cursor_date::timestamp) + interval '1 year')::date
    end;
  end loop;
  perform set_config('app.financial_workflow', 'authorized', true);
  update public.invoices invoice
  set sales_book_period_id = period.id
  from public.sales_book_periods period
  where invoice.company_id = new.id
    and coalesce(invoice.issue_date, invoice.posting_date, today) between period.period_start and period.period_end
    and invoice.sales_book_period_id is distinct from period.id;
  perform set_config('app.financial_workflow', '', true);
  perform set_config('app.sales_book_workflow', '', true);
  return new;
exception when others then
  perform set_config('app.financial_workflow', '', true);
  perform set_config('app.sales_book_workflow', '', true);
  raise;
end
$$;


--
-- Name: sync_vendor_payment_fund_transaction(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_vendor_payment_fund_transaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target_fund_id uuid;
  fund_owner_company_id uuid;
  payment_method text := lower(coalesce(new.payment_method, 'bank'));
  payment_amount numeric(20,4) := round(coalesce(new.amount, 0), 4);
begin
  if tg_op = 'DELETE' then
    update public.company_fund_transactions
       set status = 'reversed', reversed_at = clock_timestamp(), reversed_by = (select auth.uid())
     where source_type = 'vendor_payment' and source_id = old.id and status = 'active';
    return old;
  end if;

  update public.company_fund_transactions
     set status = 'reversed', reversed_at = clock_timestamp(), reversed_by = (select auth.uid())
   where source_type = 'vendor_payment' and source_id = new.id and status = 'active';

  if coalesce(new.accounting_state, '') <> 'posted' or payment_amount <= 0 then return new; end if;

  if payment_method = 'cash' then
    select id, company_id into target_fund_id, fund_owner_company_id
      from public.company_fund_accounts
     where company_id = new.company_id and fund_type = 'cash' and is_active;
  elsif payment_method = 'bank' then
    select fund.id, fund.company_id into target_fund_id, fund_owner_company_id
      from public.company_fund_accounts fund
      join public.company_bank_accounts bank on bank.id = fund.company_bank_account_id
     where fund.fund_type = 'bank'
       and fund.company_bank_account_id = new.company_bank_account_id
       and fund.is_active and bank.is_active;

    if target_fund_id is null then
      select fund.id, fund.company_id into target_fund_id, fund_owner_company_id
        from public.company_fund_accounts fund
        join public.company_bank_accounts bank on bank.id = fund.company_bank_account_id
       where fund.company_id = new.company_id and fund.fund_type = 'bank'
         and fund.is_active and bank.is_active
       order by bank.is_primary desc, bank.created_at
       limit 1;
    end if;
  else
    return new;
  end if;

  if target_fund_id is not null then
    insert into public.company_fund_transactions (
      company_id, source_company_id, fund_account_id, transaction_type, signed_amount, currency,
      transaction_date, description, source_type, source_id, created_by
    ) values (
      fund_owner_company_id, new.company_id, target_fund_id, 'expense', -payment_amount,
      upper(coalesce(nullif(new.currency, ''), 'EUR')), new.payment_date,
      coalesce(nullif(trim(new.notes), ''), 'Supplier payment'), 'vendor_payment', new.id,
      coalesce((select auth.uid()), new.user_id)
    );
  end if;
  return new;
end;
$$;


--
-- Name: validate_account_parent(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_account_parent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  parent_company uuid;
begin
  if new.parent_account_id is null then
    return new;
  end if;
  if new.parent_account_id = new.id then
    raise exception 'An account cannot be its own parent' using errcode = '23514';
  end if;
  select company_id into parent_company
  from public.chart_of_accounts
  where id = new.parent_account_id;
  if parent_company is distinct from new.company_id then
    raise exception 'Parent account must belong to the same company' using errcode = '23514';
  end if;
  return new;
end
$$;


--
-- Name: validate_accounting_period(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_accounting_period() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  year_row public.accounting_fiscal_years%rowtype;
begin
  select * into year_row
  from public.accounting_fiscal_years
  where id = new.fiscal_year_id;

  if not found or year_row.company_id <> new.company_id then
    raise exception 'Fiscal year must belong to the same company' using errcode = '23514';
  end if;
  if new.start_date < year_row.start_date or new.end_date > year_row.end_date then
    raise exception 'Accounting period must be inside its fiscal year' using errcode = '23514';
  end if;
  if exists (
    select 1
    from public.accounting_periods period
    where period.company_id = new.company_id
      and period.id <> new.id
      and daterange(period.start_date, period.end_date, '[]')
          && daterange(new.start_date, new.end_date, '[]')
  ) then
    raise exception 'Accounting periods cannot overlap' using errcode = '23P01';
  end if;
  return new;
end
$$;


--
-- Name: validate_commercial_advance_allocation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_commercial_advance_allocation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  advance_row public.invoices;
  final_row public.invoices;
  existing_amount numeric(20,4);
begin
  select * into advance_row from public.invoices where id = new.advance_invoice_id;
  select * into final_row from public.invoices where id = new.final_invoice_id;
  if advance_row.id is null or final_row.id is null then
    raise exception 'Advance or final invoice was not found' using errcode = 'P0002';
  end if;
  if advance_row.commercial_document_type <> 'ADVANCE_INVOICE'
     or final_row.commercial_document_type <> 'FINAL_INVOICE' then
    raise exception 'Advance allocations require an advance invoice and a final invoice' using errcode = '23514';
  end if;
  if advance_row.company_id is distinct from final_row.company_id
     or advance_row.client_id is distinct from final_row.client_id
     or upper(coalesce(advance_row.currency, 'EUR')) <> upper(coalesce(final_row.currency, 'EUR'))
     or advance_row.company_id is distinct from new.company_id then
    raise exception 'Advance and final invoices must belong to the same company, customer, and currency' using errcode = '23514';
  end if;
  if new.status = 'active' then
    select coalesce(sum(allocation.amount), 0)
    into existing_amount
    from public.commercial_document_advance_allocations allocation
    where allocation.final_invoice_id = new.final_invoice_id
      and allocation.status = 'active'
      and allocation.id <> new.id;
    if existing_amount + new.amount > coalesce(final_row.total_amount, 0) then
      raise exception 'Advance allocations exceed the final invoice total' using errcode = '22003';
    end if;
    select round(
      private.commercial_document_received_amount(advance_row.id)
      - coalesce((select sum(allocation.amount) from public.commercial_document_advance_allocations allocation
                  where allocation.advance_invoice_id = advance_row.id and allocation.status = 'active'
                    and allocation.id <> new.id), 0),
      4
    ) into existing_amount;
    if new.amount > existing_amount then
      raise exception 'Advance allocation exceeds the received and unapplied advance amount' using errcode = '22003';
    end if;
  end if;
  return new;
end
$$;


--
-- Name: validate_commercial_credit_line(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_commercial_credit_line() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  document_type text;
  original_quantity numeric(20,4);
  already_credited numeric(20,4);
begin
  select commercial_document_type into document_type from public.invoices where id = new.invoice_id;
  if document_type <> 'CREDIT_NOTE' or new.source_item_id is null then return new; end if;
  select quantity into original_quantity from public.invoice_items where id = new.source_item_id;
  if original_quantity is null then raise exception 'Credit line is not linked to the original invoice line' using errcode = '23514'; end if;
  select coalesce(sum(item.quantity), 0) into already_credited
  from public.invoice_items item
  join public.invoices credit on credit.id = item.invoice_id
  where credit.commercial_document_type = 'CREDIT_NOTE'
    and credit.credit_of_invoice_id = (select credit_of_invoice_id from public.invoices where id = new.invoice_id)
    and item.source_item_id = new.source_item_id
    and item.id <> new.id;
  if already_credited + greatest(0, coalesce(new.quantity, 0)) > original_quantity then
    raise exception 'Credited quantity exceeds the original invoice quantity' using errcode = '22003';
  end if;
  new.credited_quantity := greatest(0, coalesce(new.quantity, 0));
  return new;
end
$$;


--
-- Name: validate_commercial_document_payment_link(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_commercial_document_payment_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  document_row public.invoices;
  payment_row public.payments;
  existing_amount numeric(20,4);
begin
  select * into document_row
  from public.invoices
  where id = new.document_id;
  if not found then
    raise exception 'Commercial document not found' using errcode = 'P0002';
  end if;
  if document_row.commercial_document_type not in ('PROFORMA', 'ADVANCE_INVOICE') then
    raise exception 'Only proformas and advance invoices can receive advance payment links' using errcode = '23514';
  end if;

  select * into payment_row
  from public.payments
  where id = new.payment_id;
  if not found then
    raise exception 'Customer payment not found' using errcode = 'P0002';
  end if;
  if payment_row.company_id is distinct from document_row.company_id
     or payment_row.client_id is distinct from document_row.client_id then
    raise exception 'Payment and commercial document must belong to the same company and customer' using errcode = '23514';
  end if;
  if payment_row.accounting_state <> 'posted' or payment_row.reversed_at is not null then
    raise exception 'Only posted, unreversed customer payments can be linked' using errcode = '55000';
  end if;
  if upper(coalesce(payment_row.currency, 'EUR')) <> upper(coalesce(new.currency, 'EUR')) then
    raise exception 'Payment and commercial document currencies must match' using errcode = '23514';
  end if;
  if new.status = 'active' then
    select coalesce(sum(link.amount), 0)
    into existing_amount
    from public.commercial_document_payment_links link
    where link.document_id = new.document_id
      and link.status = 'active'
      and link.id <> new.id;
    if existing_amount + new.amount > coalesce(document_row.total_amount, 0) then
      raise exception 'Advance payment links exceed the document total' using errcode = '22003';
    end if;
    select round(
      coalesce(payment_row.amount, 0)
      - coalesce((select sum(allocation.allocated_amount) from public.payment_allocations allocation
                  where allocation.payment_id = payment_row.id and allocation.status = 'active'), 0)
      - coalesce((select sum(link.amount) from public.commercial_document_payment_links link
                  where link.payment_id = payment_row.id and link.status = 'active' and link.id <> new.id), 0),
      4
    ) into existing_amount;
    if new.amount > existing_amount then
      raise exception 'Advance payment link exceeds the unallocated payment amount' using errcode = '22003';
    end if;
  end if;
  return new;
end
$$;


--
-- Name: validate_company_owned_relation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_company_owned_relation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  owner_company uuid;
begin
  if tg_table_name = 'recurring_journal_template_lines' then
    select company_id into owner_company from public.recurring_journal_templates where id = new.template_id;
  elsif tg_table_name = 'posting_rule_lines' then
    select company_id into owner_company from public.posting_rule_sets where id = new.rule_set_id;
  end if;
  if owner_company is distinct from new.company_id then
    raise exception 'Related record must belong to the same company' using errcode = '23514';
  end if;
  if exists (
    select 1 from public.chart_of_accounts account
    where account.id = new.account_id
      and account.company_id <> new.company_id
  ) then
    raise exception 'Account must belong to the same company' using errcode = '23514';
  end if;
  return new;
end
$$;


--
-- Name: validate_customer_portal_token(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_customer_portal_token() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.company_id is null or new.client_id is null then
    raise exception 'A portal link must identify a company and customer'
      using errcode = '23514';
  end if;

  if not exists (
    select 1 from public.clients client
    where client.id = new.client_id and client.company_id = new.company_id
  ) then
    raise exception 'Portal customer does not belong to the selected company'
      using errcode = '23514';
  end if;

  if new.invoice_id is not null and not exists (
    select 1 from public.invoices invoice_row
    where invoice_row.id = new.invoice_id
      and invoice_row.company_id = new.company_id
      and invoice_row.client_id = new.client_id
      and invoice_row.status::text <> 'draft'
  ) then
    raise exception 'Portal invoice does not belong to the selected customer'
      using errcode = '23514';
  end if;

  if new.invoice_id is null and new.expires_at is null then
    raise exception 'Customer-wide portal links require an expiry date'
      using errcode = '23514';
  end if;

  if new.expires_at is not null and new.expires_at <= clock_timestamp() then
    raise exception 'Portal link expiry must be in the future'
      using errcode = '23514';
  end if;

  if (select auth.uid()) is not null
     and coalesce(current_setting('app.portal_link_workflow', true), '') <> 'authorized'
     and not public.can_access_company(new.company_id) then
    raise exception 'Insufficient permission for this company portal'
      using errcode = '42501';
  end if;
  return new;
end
$$;


--
-- Name: validate_expense_bank_account(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_expense_bank_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  account_company_id uuid;
  account_active boolean;
  account_shared boolean;
begin
  if new.company_bank_account_id is null then return new; end if;
  if lower(coalesce(new.payment_method, 'bank')) <> 'bank' then
    raise exception 'A bank account can only be selected for a bank-paid expense' using errcode = '23514';
  end if;

  select account.company_id, account.is_active,
         exists (
           select 1 from public.company_bank_account_shares share
            where share.company_bank_account_id = account.id
              and share.shared_company_id = new.company_id
              and share.is_active
         )
    into account_company_id, account_active, account_shared
    from public.company_bank_accounts account
   where account.id = new.company_bank_account_id;

  if account_company_id is null or not coalesce(account_active, false)
     or (account_company_id <> new.company_id and not coalesce(account_shared, false)) then
    raise exception 'The selected bank account is not available for this company' using errcode = '23503';
  end if;
  return new;
end;
$$;


--
-- Name: validate_financial_attachment(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_financial_attachment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.attachment_id is not null and not exists(
    select 1 from public.financial_document_attachments attachment
     where attachment.id=new.attachment_id and attachment.company_id=new.company_id
       and attachment.deleted_at is null
       and attachment.document_type in ('customer_payment','income')
  ) then
    raise exception 'The attachment is not available for this company and document' using errcode='23503';
  end if;
  return new;
end;
$$;


--
-- Name: validate_fiscal_installation_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_fiscal_installation_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  branch_company uuid;
  location_company uuid;
  terminal_company uuid;
begin
  select branch.company_id into branch_company
  from public.branches branch where branch.id = new.branch_id;
  select location.company_id into location_company
  from public.fiscal_locations location where location.id = new.fiscal_location_id;
  select terminal.company_id into terminal_company
  from public.pos_terminals terminal where terminal.id = new.pos_terminal_id;
  if branch_company is distinct from new.company_id
     or terminal_company is distinct from new.company_id
     or (new.fiscal_location_id is not null and location_company is distinct from new.company_id) then
    raise exception 'Fiscal installation resources must belong to the same company'
      using errcode = '23514';
  end if;
  return new;
end
$$;


--
-- Name: validate_fiscal_provider_environment(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_fiscal_provider_environment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.provider_code = 'mock' and new.environment <> 'mock' then
    raise exception 'Mock fiscal provider requires environment = mock' using errcode = '55000';
  end if;
  if new.environment = 'production' and new.provider_code = 'mock' then
    raise exception 'Mock fiscal provider cannot be configured for production' using errcode = '55000';
  end if;
  return new;
end
$$;


--
-- Name: validate_fiscal_transaction_environment(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_fiscal_transaction_environment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.provider_code = 'mock'
     and not exists (
       select 1 from public.fiscal_provider_configs config
       where config.id = new.provider_config_id
         and config.company_id = new.company_id
         and config.environment = 'mock'
     ) then
    raise exception 'Mock fiscal transaction requires a provider configuration in mock environment'
      using errcode = '55000';
  end if;
  return new;
end
$$;


--
-- Name: validate_journal_line(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_journal_line() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  entry_row public.journal_entries%rowtype;
  account_row public.chart_of_accounts%rowtype;
  dimension_company uuid;
begin
  select * into entry_row from public.journal_entries where id = new.journal_entry_id;
  if not found or entry_row.company_id <> new.company_id then
    raise exception 'Journal line company must match its entry' using errcode = '23514';
  end if;
  if entry_row.status <> 'draft' then
    raise exception 'Only draft journal entries may be changed' using errcode = '55000';
  end if;

  select * into account_row from public.chart_of_accounts where id = new.account_id;
  if not found or account_row.company_id <> new.company_id then
    raise exception 'Journal account must belong to the same company' using errcode = '23514';
  end if;
  if not account_row.active or not account_row.posting_allowed then
    raise exception 'Journal account is inactive or does not allow posting' using errcode = '23514';
  end if;

  if new.cost_centre_id is not null then
    select company_id into dimension_company from public.accounting_cost_centres where id = new.cost_centre_id;
    if dimension_company is distinct from new.company_id then
      raise exception 'Cost centre must belong to the same company' using errcode = '23514';
    end if;
  end if;
  if new.project_id is not null then
    select company_id into dimension_company from public.accounting_projects where id = new.project_id;
    if dimension_company is distinct from new.company_id then
      raise exception 'Project must belong to the same company' using errcode = '23514';
    end if;
  end if;
  return new;
end
$$;


