--
-- Name: accept_company_invitation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_company_invitation(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  operation_id_value uuid;
begin
  if actor_id is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  select invitation.user_access_operation_id into operation_id_value
  from public.company_invitations invitation
  where invitation.token_hash = encode(extensions.digest(trim(p_token), 'sha256'), 'hex')
    and invitation.status = 'pending'
    and invitation.expires_at > now()
  for update;
  if operation_id_value is null then raise exception 'This invitation must be recreated from Users & Access before it can be accepted' using errcode = '42501'; end if;
  return public.rbac_accept_user_access_invitation(operation_id_value);
end;
$$;


--
-- Name: access_payroll_payslip(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.access_payroll_payslip(p_payslip_id uuid, p_access_type text DEFAULT 'view'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare target_company_id uuid;
begin
  select payslip.company_id into target_company_id from public.payslip_snapshots payslip where payslip.id = p_payslip_id;
  if target_company_id is null then raise exception 'Payslip not found' using errcode = 'P0002'; end if;
  perform private.require_operix_product_access(target_company_id, 'hr');
  return public.access_payroll_payslip_unchecked_operix(p_payslip_id, p_access_type);
end;
$$;


--
-- Name: access_payroll_payslip_unchecked_operix(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.access_payroll_payslip_unchecked_operix(p_payslip_id uuid, p_access_type text DEFAULT 'view'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payslip public.payslip_snapshots;
  employee_user_id uuid;
begin
  if p_access_type not in ('view','download','email','signed_link') then
    raise exception 'Unsupported payslip access type' using errcode='22023';
  end if;

  select * into payslip
  from public.payslip_snapshots
  where id=p_payslip_id and revoked_at is null;
  if not found then
    raise exception 'Payslip not found' using errcode='P0002';
  end if;

  select user_id into employee_user_id
  from public.employees
  where id=payslip.employee_id and company_id=payslip.company_id;

  if employee_user_id is distinct from (select auth.uid())
     and not (select private.has_company_permission(payslip.company_id,'payroll.payslip.generate'))
     and not (select private.has_company_permission(payslip.company_id,'payroll.dashboard.view')) then
    raise exception 'Insufficient payslip permission' using errcode='42501';
  end if;

  insert into public.payslip_access_logs(
    company_id,payslip_snapshot_id,employee_id,accessed_by,access_type,
    session_identifier,metadata
  ) values (
    payslip.company_id,payslip.id,payslip.employee_id,(select auth.uid()),p_access_type,
    coalesce(nullif(current_setting('request.headers',true),'')::jsonb,'{}'::jsonb)->>'x-client-info',
    jsonb_build_object('source','operix_invoice')
  );

  return jsonb_build_object(
    'id',payslip.id,
    'companyId',payslip.company_id,
    'employeeId',payslip.employee_id,
    'language',payslip.language,
    'verificationReference',payslip.verification_reference,
    'snapshot',payslip.snapshot,
    'snapshotChecksum',payslip.snapshot_checksum,
    'generatedAt',payslip.generated_at
  );
end $$;


--
-- Name: financial_document_attachments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.financial_document_attachments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    branch_id uuid,
    document_type text NOT NULL,
    document_id uuid NOT NULL,
    storage_bucket text NOT NULL,
    storage_path text NOT NULL,
    file_name text NOT NULL,
    content_type text,
    byte_size bigint,
    file_checksum text,
    uploaded_at timestamp with time zone DEFAULT now() NOT NULL,
    uploaded_by uuid,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT financial_document_attachments_byte_size_check CHECK (((byte_size IS NULL) OR (byte_size >= 0))),
    CONSTRAINT financial_document_attachments_document_type_check CHECK ((document_type = ANY (ARRAY['sales_invoice'::text, 'commercial_document'::text, 'supplier_bill'::text, 'expense'::text, 'income'::text, 'customer_payment'::text, 'supplier_payment'::text, 'credit_note'::text]))),
    CONSTRAINT financial_document_attachments_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text))
);


--
-- Name: add_expense_attachment(uuid, text, text, text, text, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_expense_attachment(p_expense_id uuid, p_storage_bucket text, p_storage_path text, p_file_name text, p_content_type text DEFAULT NULL::text, p_byte_size bigint DEFAULT NULL::bigint, p_file_checksum text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS public.financial_document_attachments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  expense_row public.expenses;
  expense_json jsonb;
  result public.financial_document_attachments;
  documentation_status_value text;
begin
  select * into expense_row from public.expenses where id = p_expense_id;
  if not found then raise exception 'Expense not found' using errcode = 'P0002'; end if;
  if not (
    private.rbac_can_read_resource(expense_row.company_id, 'expense', expense_row.user_id, expense_row.assigned_user_id, 'expense.create')
    or private.rbac_can_read_resource(expense_row.company_id, 'expense', expense_row.user_id, expense_row.assigned_user_id, 'expense.edit')
    or private.rbac_can_read_resource(expense_row.company_id, 'expense', expense_row.user_id, expense_row.assigned_user_id, 'expense.manage')
  ) then
    raise exception 'Expense attachment permission or data scope is required' using errcode = '42501';
  end if;
  if p_storage_bucket <> 'operix-expense-documents'
     or split_part(p_storage_path, '/', 1) <> expense_row.company_id::text
     or split_part(p_storage_path, '/', 2) <> 'expenses'
     or split_part(p_storage_path, '/', 3) <> expense_row.id::text then
    raise exception 'Expense attachment must use company/expenses/expense-id private paths' using errcode = '42501';
  end if;

  insert into public.financial_document_attachments(
    company_id, branch_id, document_type, document_id, storage_bucket,
    storage_path, file_name, content_type, byte_size, file_checksum,
    uploaded_by, metadata
  ) values (
    expense_row.company_id, expense_row.branch_id, 'expense', expense_row.id,
    p_storage_bucket, p_storage_path, p_file_name, p_content_type, p_byte_size,
    p_file_checksum, (select auth.uid()), coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict(company_id, document_type, document_id, storage_bucket, storage_path)
  do update set
    deleted_at = null,
    deleted_by = null,
    file_name = excluded.file_name,
    content_type = excluded.content_type,
    byte_size = excluded.byte_size,
    file_checksum = excluded.file_checksum,
    metadata = excluded.metadata,
    uploaded_at = clock_timestamp(),
    uploaded_by = (select auth.uid())
  returning * into result;

  expense_json := to_jsonb(expense_row);
  documentation_status_value := case
    when coalesce(expense_json ->> 'document_type', 'other') <> 'other'
      and coalesce(nullif(expense_json ->> 'document_number', ''), nullif(expense_json ->> 'invoice_number', '')) is not null
      and coalesce(nullif(expense_json ->> 'issue_date', ''), nullif(expense_json ->> 'date', '')) is not null
    then 'complete' else 'missing_information' end;
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'expenses' and column_name = 'documentation_status'
  ) then
    execute 'update public.expenses set documentation_status = $1, updated_by = (select auth.uid()) where id = $2'
      using documentation_status_value, expense_row.id;
  else
    update public.expenses set updated_at = clock_timestamp() where id = expense_row.id;
  end if;
  return result;
end;
$_$;


--
-- Name: inventory_count_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inventory_count_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    count_id uuid NOT NULL,
    product_id uuid,
    expected_quantity numeric(20,4) NOT NULL,
    counted_quantity numeric(20,4) NOT NULL,
    adjustment_movement_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    product_name text,
    CONSTRAINT inventory_count_lines_counted_quantity_check CHECK ((counted_quantity >= (0)::numeric))
);


--
-- Name: add_inventory_count_line(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_inventory_count_line(p_count_id uuid, p_product_id uuid, p_counted_quantity numeric) RETURNS public.inventory_count_lines
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare count_row public.inventory_counts; product_row public.products; result public.inventory_count_lines;
begin
  select * into count_row from public.inventory_counts where id=p_count_id for update;
  if not found then raise exception 'Inventory count not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(count_row.company_id,'inventory.manage')) then raise exception 'Insufficient permission to edit inventory count' using errcode='42501'; end if;
  if count_row.status <> 'draft' then raise exception 'Only draft inventory counts can be edited' using errcode='55000'; end if;
  select * into product_row from public.products where id=p_product_id and company_id=count_row.company_id for update;
  if not found or p_counted_quantity < 0 then raise exception 'Inventory count product or quantity is invalid' using errcode='23514'; end if;
  insert into public.inventory_count_lines(company_id,count_id,product_id,expected_quantity,counted_quantity)
  values(count_row.company_id,count_row.id,p_product_id,coalesce(product_row.stock_quantity,0),p_counted_quantity)
  on conflict(count_id,product_id) do update set counted_quantity=excluded.counted_quantity
  returning * into result;
  return result;
end
$$;


--
-- Name: payroll_adjustments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_adjustments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    payroll_run_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    adjustment_type text NOT NULL,
    amount numeric(20,4) NOT NULL,
    reason text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    source_period_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    approved_at timestamp with time zone,
    approved_by uuid,
    CONSTRAINT payroll_adjustments_check CHECK ((created_by IS DISTINCT FROM approved_by)),
    CONSTRAINT payroll_adjustments_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_approval'::text, 'approved'::text, 'rejected'::text, 'applied'::text, 'reversed'::text])))
);


--
-- Name: add_payroll_adjustment(uuid, uuid, text, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_payroll_adjustment(p_payroll_run_id uuid, p_employee_id uuid, p_adjustment_type text, p_amount numeric, p_reason text, p_source_period_id uuid DEFAULT NULL::uuid) RETURNS public.payroll_adjustments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  run_row public.payroll_runs;
  result public.payroll_adjustments;
begin
  select * into run_row from public.payroll_runs where id=p_payroll_run_id for update;
  if not found then raise exception 'Payroll run not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(run_row.company_id,'payroll.adjustment.create')) then
    raise exception 'Insufficient permission' using errcode='42501';
  end if;
  if run_row.status not in ('draft','collecting_inputs','calculated') then
    raise exception 'Adjustments cannot be added in payroll state %',run_row.status using errcode='55000';
  end if;
  if not exists(select 1 from public.employees where id=p_employee_id and company_id=run_row.company_id) then
    raise exception 'Employee does not belong to payroll company' using errcode='23514';
  end if;
  if p_amount=0 or trim(coalesce(p_reason,''))='' then
    raise exception 'A non-zero amount and reason are required' using errcode='23514';
  end if;
  insert into public.payroll_adjustments(
    company_id,payroll_run_id,employee_id,adjustment_type,amount,reason,status,
    source_period_id,created_by
  ) values (
    run_row.company_id,run_row.id,p_employee_id,p_adjustment_type,p_amount,trim(p_reason),
    'pending_approval',p_source_period_id,(select auth.uid())
  ) returning * into result;
  update public.payroll_runs set status='collecting_inputs',updated_at=now(),updated_by=(select auth.uid()) where id=run_row.id;
  perform private.record_payroll_audit(
    run_row.company_id,run_row.branch_id,'payroll.adjustment.created','payroll_adjustment',
    result.id,null,to_jsonb(result),p_reason
  );
  return result;
end $$;


--
-- Name: commercial_document_advance_allocations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commercial_document_advance_allocations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    advance_invoice_id uuid NOT NULL,
    final_invoice_id uuid NOT NULL,
    amount numeric(20,4) NOT NULL,
    tax_amount numeric(20,4) DEFAULT 0 NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    allocated_at timestamp with time zone DEFAULT now() NOT NULL,
    allocated_by uuid,
    status text DEFAULT 'active'::text NOT NULL,
    reversed_at timestamp with time zone,
    reversed_by uuid,
    reversal_reason text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT commercial_document_advance_allocations_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT commercial_document_advance_allocations_check CHECK ((advance_invoice_id <> final_invoice_id)),
    CONSTRAINT commercial_document_advance_allocations_check1 CHECK ((((status = 'active'::text) AND (reversed_at IS NULL) AND (reversed_by IS NULL) AND (reversal_reason IS NULL)) OR ((status = 'reversed'::text) AND (reversed_at IS NOT NULL) AND (reversed_by IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM reversal_reason), ''::text) IS NOT NULL)))),
    CONSTRAINT commercial_document_advance_allocations_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT commercial_document_advance_allocations_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT commercial_document_advance_allocations_status_check CHECK ((status = ANY (ARRAY['active'::text, 'reversed'::text]))),
    CONSTRAINT commercial_document_advance_allocations_tax_amount_check CHECK ((tax_amount >= (0)::numeric))
);


--
-- Name: allocate_advance_to_final_invoice(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocate_advance_to_final_invoice(p_advance_invoice_id uuid, p_final_invoice_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text) RETURNS public.commercial_document_advance_allocations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  advance_row public.invoices;
  final_row public.invoices;
  allocation_row public.commercial_document_advance_allocations;
  received_amount numeric(20,4);
  already_applied numeric(20,4);
  available_advance numeric(20,4);
  remaining_final numeric(20,4);
  allocation_amount numeric(20,4);
  allocation_tax numeric(20,4);
  next_final_status text;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_amount is null or round(p_amount, 4) <= 0 then
    raise exception 'Advance allocation amount must be greater than zero' using errcode = '23514';
  end if;

  -- Lock both rows in a deterministic order before reading balances. This
  -- prevents two finalization requests from consuming the same advance.
  perform 1
  from public.invoices invoice
  where invoice.id in (p_advance_invoice_id, p_final_invoice_id)
  order by invoice.id
  for update;

  select * into advance_row from public.invoices where id = p_advance_invoice_id;
  select * into final_row from public.invoices where id = p_final_invoice_id;
  if advance_row.id is null or final_row.id is null then
    raise exception 'Advance or final invoice was not found' using errcode = 'P0002';
  end if;
  if not (select private.has_company_permission(advance_row.company_id, 'sales_invoice.edit')) then
    raise exception 'Advance reconciliation requires sales invoice posting permission' using errcode = '42501';
  end if;
  if advance_row.commercial_document_type <> 'ADVANCE_INVOICE'
     or final_row.commercial_document_type <> 'FINAL_INVOICE' then
    raise exception 'Advance reconciliation requires an advance invoice and a final invoice' using errcode = '23514';
  end if;
  if advance_row.company_id is distinct from final_row.company_id
     or advance_row.client_id is distinct from final_row.client_id
     or upper(coalesce(advance_row.currency, 'EUR')) <> upper(coalesce(final_row.currency, 'EUR')) then
    raise exception 'Advance and final invoices must belong to the same company, customer, and currency' using errcode = '23514';
  end if;
  if final_row.accounting_state in ('posted', 'reversed') then
    raise exception 'Posted final invoices require the controlled advance-reconciliation posting workflow' using errcode = '55000';
  end if;

  received_amount := private.commercial_document_received_amount(advance_row.id);
  select round(coalesce(sum(allocation.amount), 0), 4)
  into already_applied
  from public.commercial_document_advance_allocations allocation
  where allocation.advance_invoice_id = advance_row.id
    and allocation.status = 'active';
  available_advance := greatest(0, received_amount - already_applied);
  remaining_final := greatest(0, coalesce(final_row.total_amount, 0) - coalesce(final_row.advance_applied_amount, 0));
  allocation_amount := round(p_amount, 4);

  if allocation_amount > available_advance then
    raise exception 'Advance allocation exceeds the received and unapplied advance amount' using errcode = '23514';
  end if;
  if allocation_amount > remaining_final then
    raise exception 'Advance allocation exceeds the remaining final invoice amount' using errcode = '23514';
  end if;

  allocation_tax := case
    when coalesce(advance_row.total_amount, 0) > 0
      then round(allocation_amount * coalesce(advance_row.tax_amount, 0) / advance_row.total_amount, 4)
    else 0
  end;

  insert into public.commercial_document_advance_allocations (
    company_id, advance_invoice_id, final_invoice_id, amount, tax_amount,
    currency, allocated_by, metadata
  ) values (
    advance_row.company_id, advance_row.id, final_row.id, allocation_amount, allocation_tax,
    upper(coalesce(final_row.currency, 'EUR')), (select auth.uid()),
    jsonb_build_object('reason', nullif(trim(coalesce(p_reason, '')), ''))
  ) returning * into allocation_row;

  next_final_status := case
    when remaining_final - allocation_amount <= 0 then 'RECONCILED'
    else 'PENDING'
  end;
  update public.invoices
  set advance_applied_amount = coalesce(advance_applied_amount, 0) + allocation_amount,
      advance_applied_tax_amount = coalesce(advance_applied_tax_amount, 0) + allocation_tax,
      advance_reconciliation_status = next_final_status,
      payment_status = case
        when remaining_final - allocation_amount <= 0 then 'PAID'
        else 'PARTIALLY_PAID'
      end
  where id = final_row.id;

  insert into public.document_source_links (
    company_id, source_type, source_id, target_type, target_id, link_type,
    amount, metadata, created_by
  ) values (
    advance_row.company_id, 'commercial_document', advance_row.id,
    'commercial_document', final_row.id, 'advance_finalization', allocation_amount,
    jsonb_build_object('advance_allocation_id', allocation_row.id), (select auth.uid())
  ) on conflict do nothing;

  perform private.insert_commercial_document_event(
    final_row.company_id, final_row.id, 'advance_reconciled',
    final_row.commercial_status, final_row.commercial_status,
    jsonb_build_object(
      'advance_invoice_id', advance_row.id,
      'allocation_id', allocation_row.id,
      'amount', allocation_amount,
      'tax_amount', allocation_tax,
      'reconciliation_status', next_final_status
    ),
    clock_timestamp(), (select auth.uid())
  );
  return allocation_row;
end
$$;


