    created_by uuid,
    CONSTRAINT supplier_payment_allocations_allocated_amount_check CHECK ((allocated_amount > (0)::numeric)),
    CONSTRAINT supplier_payment_allocations_status_check CHECK ((status = ANY (ARRAY['active'::text, 'reversed'::text])))
);


--
-- Name: allocate_supplier_payment(uuid, uuid, numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocate_supplier_payment(p_vendor_payment_id uuid, p_supplier_bill_id uuid, p_amount numeric, p_allocation_date date DEFAULT CURRENT_DATE) RETURNS public.supplier_payment_allocations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payment_row public.vendor_payments;
  bill_row public.supplier_bills;
  allocated numeric(20,4);
  existing_row public.supplier_payment_allocations;
  result public.supplier_payment_allocations;
begin
  select * into payment_row from public.vendor_payments where id=p_vendor_payment_id for update;
  if not found then raise exception 'Supplier payment not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(payment_row.company_id,'supplier_payment.record')) then raise exception 'Insufficient permission to allocate supplier payment' using errcode='42501'; end if;
  select * into bill_row from public.supplier_bills where id=p_supplier_bill_id and company_id=payment_row.company_id for update;
  if not found then raise exception 'Supplier bill does not belong to the payment company' using errcode='23503'; end if;
  if bill_row.accounting_state <> 'posted' or payment_row.accounting_state <> 'posted' then raise exception 'Only posted supplier documents can be allocated' using errcode='55000'; end if;
  select * into existing_row from public.supplier_payment_allocations where vendor_payment_id=p_vendor_payment_id and supplier_bill_id=p_supplier_bill_id and status='active' for update;
  if found then return existing_row; end if;
  select coalesce(sum(allocated_amount),0) into allocated from public.supplier_payment_allocations where supplier_bill_id=p_supplier_bill_id and status='active';
  if p_amount is null or p_amount <= 0 or round(p_amount,4) > round(bill_row.total_amount-allocated,4) then raise exception 'Supplier allocation exceeds the open bill amount' using errcode='23514'; end if;
  if round(p_amount,4) > round(payment_row.amount-coalesce((select sum(allocated_amount) from public.supplier_payment_allocations where vendor_payment_id=p_vendor_payment_id and status='active'),0),4) then raise exception 'Supplier allocation exceeds the open payment amount' using errcode='23514'; end if;
  insert into public.supplier_payment_allocations(company_id,vendor_payment_id,supplier_bill_id,allocated_amount,allocation_date,created_by)
  values(payment_row.company_id,p_vendor_payment_id,p_supplier_bill_id,round(p_amount,4),coalesce(p_allocation_date,current_date),(select auth.uid())) returning * into result;
  return result;
end
$$;


--
-- Name: api_check_base_product_access(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_check_base_product_access(p_company_id uuid, p_product text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is null
     or not private.has_company_permission(p_company_id, 'billing.manage')
     or lower(trim(coalesce(p_product, ''))) not in ('invoice', 'booking', 'suite') then
    return false;
  end if;
  return private.operix_product_access(p_company_id, lower(trim(p_product)));
end;
$$;


--
-- Name: api_check_product_access(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_check_product_access(p_company_id uuid, p_product text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.operix_server_request() and private.api_product_access(p_company_id, p_product);
$$;


--
-- Name: api_consume_rate_limit(uuid, uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_consume_rate_limit(p_api_key_id uuid, p_company_id uuid, p_environment text, p_limit integer DEFAULT 120, p_window_seconds integer DEFAULT 60) RETURNS TABLE(allowed boolean, request_count integer, remaining integer, reset_at bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare current_window bigint := floor(extract(epoch from clock_timestamp()) / greatest(p_window_seconds, 1));
declare count_value integer;
begin
  if not private.operix_server_request() then raise exception 'Server-only API function' using errcode = '42501'; end if;
  if not exists (select 1 from public.api_keys key where key.id = p_api_key_id and key.company_id = p_company_id and key.environment = p_environment and key.revoked_at is null) then
    raise exception 'API key scope mismatch' using errcode = '42501';
  end if;
  insert into public.api_rate_limit_windows(api_key_id, company_id, environment, window_start, request_count)
    values (p_api_key_id, p_company_id, p_environment, current_window, 1)
    on conflict (api_key_id, environment, window_start)
    do update set request_count = public.api_rate_limit_windows.request_count + 1, updated_at = now()
    returning public.api_rate_limit_windows.request_count into count_value;
  return query select count_value <= p_limit, count_value, greatest(p_limit - count_value, 0), ((current_window + 1) * greatest(p_window_seconds, 1))::bigint;
end;
$$;


--
-- Name: api_create_key(uuid, text, text, text[], timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_create_key(p_company_id uuid, p_name text, p_environment text, p_scopes text[], p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  secret text := 'opx_' || p_environment || '_' || encode(extensions.gen_random_bytes(32), 'base64');
  clean_secret text := replace(replace(replace(secret, '+', '-'), '/', '_'), '=', '');
  key_row public.api_keys;
begin
  if (select auth.uid()) is null
     or not private.has_company_permission(p_company_id, 'settings.integrations')
     or not private.api_addon_access(p_company_id) then
    raise exception 'API management denied' using errcode = '42501';
  end if;
  if p_environment not in ('test', 'live')
     or p_name is null
     or char_length(trim(p_name)) not between 1 and 120
     or p_scopes is null
     or cardinality(p_scopes) = 0
     or exists (
       select 1 from unnest(p_scopes) requested(scope)
       where requested.scope not in (
         'invoice:read','invoice:write','invoice:finalize','invoice:void',
         'customer:read','customer:write','product:read','product:write',
         'payment:read','payment:write','document:read','document:write',
         'booking:read','booking:write','booking:cancel','availability:read',
         'service:read','service:write','provider:read','provider:write',
         'resource:read','resource:write','location:read','location:write',
         'booking_customer:read','booking_customer:write'
       )
     ) then
    raise exception 'Invalid API key configuration' using errcode = '22023';
  end if;
  insert into public.api_keys(company_id, environment, name, key_prefix, key_hash, created_by, scopes, expires_at)
    values (p_company_id, p_environment, trim(p_name), left(clean_secret, 13) || '…' || right(clean_secret, 4), 'sha256:' || encode(extensions.digest(clean_secret, 'sha256'), 'hex'), (select auth.uid()), p_scopes, p_expires_at)
    returning * into key_row;
  insert into public.api_key_scopes(api_key_id, scope) select key_row.id, unnest(p_scopes);
  return jsonb_build_object('id', key_row.id, 'name', key_row.name, 'environment', key_row.environment, 'key', clean_secret, 'key_prefix', key_row.key_prefix, 'scopes', key_row.scopes, 'created_at', key_row.created_at, 'expires_at', key_row.expires_at);
end;
$$;


--
-- Name: api_entitlement_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_entitlement_summary(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  root_company_id uuid := private.invoice_billing_root_company_id(p_company_id);
  addon_row public.api_addon_subscriptions;
begin
  if (select auth.uid()) is null or not private.has_company_permission(p_company_id, 'settings.integrations') then
    raise exception 'API entitlement access denied' using errcode = '42501';
  end if;

  select * into addon_row
  from public.api_addon_subscriptions
  where company_id = root_company_id;

  return jsonb_build_object(
    'api_addon', private.api_addon_access(p_company_id),
    'invoice', private.api_product_access(p_company_id, 'invoice'),
    'booking', private.api_product_access(p_company_id, 'booking'),
    'status', coalesce(addon_row.status, 'inactive'),
    'period_start', addon_row.current_period_start,
    'period_end', addon_row.current_period_end,
    'grace_period_ends_at', addon_row.grace_period_ends_at,
    'included_requests', 5000,
    'overage_ready', true,
    'automatic_overage_charging', false
  );
end;
$$;


--
-- Name: api_record_webhook_result(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_record_webhook_result(p_endpoint_id uuid, p_delivered boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.operix_server_request() then raise exception 'Server-only API function' using errcode = '42501'; end if;
  update public.api_webhook_endpoints
  set last_delivery_at = now(),
      success_count = success_count + case when p_delivered then 1 else 0 end,
      failure_count = failure_count + case when p_delivered then 0 else 1 end,
      status = case
        when p_delivered then 'active'
        when failure_count + 1 >= 3 then 'failing'
        else status
      end,
      updated_at = now()
  where id = p_endpoint_id and status <> 'deleted';
end;
$$;


--
-- Name: api_revoke_key(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_revoke_key(p_company_id uuid, p_key_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is null or not private.has_company_permission(p_company_id, 'settings.integrations') then raise exception 'API management denied' using errcode = '42501'; end if;
  update public.api_keys set revoked_at = coalesce(revoked_at, now()), updated_at = now() where id = p_key_id and company_id = p_company_id;
end;
$$;


--
-- Name: api_rotate_key(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_rotate_key(p_company_id uuid, p_key_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  secret text := 'opx_live_' || encode(extensions.gen_random_bytes(32), 'base64');
  existing public.api_keys;
  clean_secret text := replace(replace(replace(secret, '+', '-'), '/', '_'), '=', '');
begin
  if (select auth.uid()) is null
     or not private.has_company_permission(p_company_id, 'settings.integrations')
     or not private.api_addon_access(p_company_id) then
    raise exception 'API management denied' using errcode = '42501';
  end if;
  select * into existing from public.api_keys where id = p_key_id and company_id = p_company_id for update;
  if existing.id is null then raise exception 'API key not found' using errcode = '22023'; end if;
  clean_secret := 'opx_' || existing.environment || '_' || substr(clean_secret, 10);
  update public.api_keys
  set key_prefix = left(clean_secret, 13) || '…' || right(clean_secret, 4),
      key_hash = 'sha256:' || encode(extensions.digest(clean_secret, 'sha256'), 'hex'),
      revoked_at = null,
      updated_at = now()
  where id = existing.id;
  return jsonb_build_object('id', existing.id, 'name', existing.name, 'environment', existing.environment, 'key', clean_secret, 'key_prefix', left(clean_secret, 13) || '…' || right(clean_secret, 4), 'scopes', existing.scopes);
end;
$$;


--
-- Name: api_usage_summary(uuid, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_usage_summary(p_company_id uuid, p_environment text, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
  if (select auth.uid()) is null or not private.has_company_permission(p_company_id, 'settings.integrations') then
    raise exception 'API usage access denied' using errcode = '42501';
  end if;
  select jsonb_build_object(
    'requests', count(*)::integer,
    'successful', count(*) filter (where response_status < 400)::integer,
    'failed', count(*) filter (where response_status >= 400)::integer,
    'requests_today', count(*) filter (where occurred_at >= date_trunc('day', now()))::integer,
    'top_endpoints', coalesce((select jsonb_agg(jsonb_build_object('endpoint', endpoint, 'requests', requests) order by requests desc)
      from (select usage.endpoint, count(*)::integer as requests from public.api_usage usage where usage.company_id = p_company_id and usage.environment = p_environment and usage.occurred_at >= p_from and usage.occurred_at < p_to group by usage.endpoint order by requests desc limit 10) top_rows), '[]'::jsonb),
    'by_key', coalesce((select jsonb_agg(jsonb_build_object('key_id', key_id, 'key_prefix', key_prefix, 'requests', requests) order by requests desc)
      from (select usage.api_key_id as key_id, key.key_prefix, count(*)::integer as requests from public.api_usage usage join public.api_keys key on key.id = usage.api_key_id where usage.company_id = p_company_id and usage.environment = p_environment and usage.occurred_at >= p_from and usage.occurred_at < p_to group by usage.api_key_id, key.key_prefix order by requests desc limit 20) key_rows), '[]'::jsonb)
  ) into result
  from public.api_usage usage
  where usage.company_id = p_company_id and usage.environment = p_environment and usage.occurred_at >= p_from and usage.occurred_at < p_to;
  return result;
end;
$$;


--
-- Name: apply_delivery_fulfillment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_delivery_fulfillment(p_delivery_id uuid) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  delivery_row public.invoices;
  order_row public.invoices;
  delivery_item record;
  ordered_amount numeric(20,4);
  already_delivered numeric(20,4);
  next_delivered numeric(20,4);
  has_remaining boolean;
begin
  select * into delivery_row from public.invoices where id = p_delivery_id for update;
  if not found then raise exception 'Delivery note not found' using errcode = 'P0002'; end if;
  if delivery_row.commercial_document_type <> 'DELIVERY_NOTE' then
    raise exception 'Only delivery notes can apply fulfillment' using errcode = '22023';
  end if;
  if not (select private.has_company_permission(delivery_row.company_id, 'sales_invoice.edit')) then
    raise exception 'Insufficient permission to confirm delivery' using errcode = '42501';
  end if;
  if delivery_row.source_document_id is null then
    update public.invoices set commercial_status = 'DELIVERED' where id = delivery_row.id returning * into delivery_row;
    return delivery_row;
  end if;

  select * into order_row from public.invoices
  where id = delivery_row.source_document_id
    and company_id = delivery_row.company_id
    and commercial_document_type = 'SALES_ORDER'
  for update;
  if not found then raise exception 'The delivery note source is not a sales order' using errcode = '23514'; end if;

  for delivery_item in
    select item.* from public.invoice_items item where item.invoice_id = delivery_row.id for update
  loop
    if delivery_item.source_item_id is null then continue; end if;
    select quantity into ordered_amount from public.invoice_items where id = delivery_item.source_item_id and invoice_id = order_row.id for update;
    if ordered_amount is null then raise exception 'Delivery line is not linked to an order line' using errcode = '23514'; end if;
    select coalesce(sum(item.quantity), 0) into already_delivered
    from public.invoice_items item
    join public.invoices delivery on delivery.id = item.invoice_id
    where delivery.company_id = order_row.company_id
      and delivery.commercial_document_type = 'DELIVERY_NOTE'
      and delivery.source_document_id = order_row.id
      and delivery.id <> delivery_row.id
      and item.source_item_id = delivery_item.source_item_id;
    next_delivered := already_delivered + greatest(0, coalesce(delivery_item.quantity, 0));
    if next_delivered > ordered_amount then
      raise exception 'Delivered quantity exceeds ordered quantity for line %', delivery_item.source_item_id using errcode = '22003';
    end if;
    update public.invoice_items
    set ordered_quantity = ordered_amount,
        delivered_quantity = next_delivered,
        remaining_quantity = greatest(0, ordered_amount - next_delivered)
    where id = delivery_item.source_item_id;
    update public.invoice_items
    set ordered_quantity = ordered_amount,
        delivered_quantity = greatest(0, coalesce(delivery_item.quantity, 0)),
        remaining_quantity = greatest(0, ordered_amount - greatest(0, coalesce(delivery_item.quantity, 0)))
    where id = delivery_item.id;
  end loop;

  select exists (
    select 1 from public.invoice_items item
    where item.invoice_id = order_row.id and item.remaining_quantity > 0
  ) into has_remaining;
  update public.invoices
  set commercial_status = case when has_remaining then 'PARTIALLY_FULFILLED' else 'FULFILLED' end
  where id = order_row.id;
  update public.invoices
  set commercial_status = case when has_remaining then 'PARTIALLY_DELIVERED' else 'DELIVERED' end,
      delivery_date = coalesce(delivery_date, current_date)
  where id = delivery_row.id
  returning * into delivery_row;
  return delivery_row;
end
$$;


--
-- Name: apply_sales_book_amendment(uuid, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_sales_book_amendment(p_amendment_id uuid, p_invoice jsonb, p_items jsonb, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  amendment_row public.sales_book_amendments;
  period_row public.sales_book_periods;
  updated_invoice public.invoices;
  after_snapshot_value jsonb;
begin
  select * into amendment_row from public.sales_book_amendments where id = p_amendment_id for update;
  if not found then
    raise exception 'Sales Book amendment not found' using errcode = 'P0002';
  end if;
  select * into period_row from public.sales_book_periods where id = amendment_row.sales_book_period_id for update;
  if not coalesce(private.has_company_permission(period_row.company_id, 'tax.declaration.prepare'), false) then
    raise exception 'Insufficient permission to apply the Sales Book amendment' using errcode = '42501';
  end if;
  if amendment_row.status <> 'PENDING' then
    raise exception 'This Sales Book amendment has already been resolved' using errcode = '55000';
  end if;
  if amendment_row.invoice_id is null then
    raise exception 'A transaction is required to apply an invoice amendment' using errcode = '22023';
  end if;

  perform set_config('app.sales_book_workflow', 'amendment', true);
  begin
    updated_invoice := public.replace_posted_invoice_document(
      p_invoice, p_items, amendment_row.invoice_id, p_idempotency_key
    );
    if updated_invoice.sales_book_period_id is distinct from period_row.id then
      raise exception 'An amendment must keep the corrected invoice in its original Sales Book period'
        using errcode = '55000';
    end if;
  exception when others then
    perform set_config('app.sales_book_workflow', '', true);
    raise;
  end;
  perform set_config('app.sales_book_workflow', '', true);

  after_snapshot_value := jsonb_build_object(
    'invoice', to_jsonb(updated_invoice),
    'period', private.sales_book_period_snapshot(period_row.id)
  );
  perform set_config('app.sales_book_amendment_workflow', 'authorized', true);
  update public.sales_book_amendments
  set status = 'APPLIED', after_snapshot = after_snapshot_value,
      applied_at = clock_timestamp(), applied_by = (select auth.uid())
  where id = amendment_row.id;
  perform set_config('app.sales_book_amendment_workflow', '', true);

  perform set_config('app.sales_book_period_workflow', 'amendment', true);
  perform set_config('app.change_reason', amendment_row.reason, true);
  update public.sales_book_periods
  set status = 'AMENDED', amended_at = clock_timestamp(), amended_by = (select auth.uid()),
      amendment_reason = amendment_row.reason, updated_at = clock_timestamp(), updated_by = (select auth.uid())
  where id = period_row.id;
  perform set_config('app.change_reason', '', true);
  perform set_config('app.sales_book_period_workflow', '', true);
  return updated_invoice;
exception when others then
  perform set_config('app.sales_book_workflow', '', true);
  perform set_config('app.sales_book_amendment_workflow', '', true);
  perform set_config('app.change_reason', '', true);
  perform set_config('app.sales_book_period_workflow', '', true);
  raise;
end
$$;


--
-- Name: approve_cashier_shift_close(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_cashier_shift_close(p_company_id uuid, p_shift_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare shift_row public.cashier_shifts;
begin
  if not (select private.has_company_permission(p_company_id, 'pos.shift.approve')) then raise exception 'Insufficient permission to approve a cashier shift close' using errcode='42501'; end if;
  select * into shift_row from public.cashier_shifts where id=p_shift_id and company_id=p_company_id for update;
  if not found or shift_row.status <> 'closing' then raise exception 'Only a counted cashier shift can be approved' using errcode='55000'; end if;
  update public.cashier_shifts set status='closed',closed_at=clock_timestamp(),closed_by=(select auth.uid()),approved_by=(select auth.uid()),updated_at=clock_timestamp() where id=shift_row.id returning * into shift_row;
  insert into public.cashier_shift_events (company_id,cashier_shift_id,event_type,payload,actor_id) values (p_company_id,shift_row.id,'closed',jsonb_build_object('reason',nullif(trim(p_reason),''),'difference',shift_row.difference_amount),(select auth.uid()));
  return jsonb_build_object('shift_id',shift_row.id,'status',shift_row.status,'expected_cash',shift_row.expected_cash,'counted_cash',shift_row.counted_cash,'difference_amount',shift_row.difference_amount);
end $$;


--
-- Name: approve_payroll_adjustment(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_payroll_adjustment(p_adjustment_id uuid, p_approved boolean, p_reason text) RETURNS public.payroll_adjustments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result public.payroll_adjustments; run_row public.payroll_runs;
begin
  select * into result from public.payroll_adjustments where id=p_adjustment_id for update;
  if not found then raise exception 'Payroll adjustment not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(result.company_id,'payroll.adjustment.approve')) then
    raise exception 'Insufficient permission' using errcode='42501';
  end if;
  if result.created_by=(select auth.uid()) then
    raise exception 'Adjustment creator cannot approve the same adjustment' using errcode='42501';
  end if;
  if result.status<>'pending_approval' then
    raise exception 'Adjustment is not pending approval' using errcode='55000';
  end if;
  if trim(coalesce(p_reason,''))='' then raise exception 'Approval reason is required' using errcode='23514'; end if;
  update public.payroll_adjustments
  set status=case when p_approved then 'approved' else 'rejected' end,
      approved_at=now(),approved_by=(select auth.uid())
  where id=result.id returning * into result;
  select * into run_row from public.payroll_runs where id=result.payroll_run_id;
  perform private.record_payroll_audit(
    result.company_id,run_row.branch_id,
    case when p_approved then 'payroll.adjustment.approved' else 'payroll.adjustment.rejected' end,
    'payroll_adjustment',result.id,null,to_jsonb(result),p_reason
  );
  return result;
end $$;


--
-- Name: payroll_config_sets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_config_sets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    jurisdiction text DEFAULT 'XK'::text NOT NULL,
    version integer NOT NULL,
    effective_from date NOT NULL,
    effective_until date,
    status text DEFAULT 'draft'::text NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    decimal_scale smallint DEFAULT 2 NOT NULL,
    rounding_mode text DEFAULT 'half-up'::text NOT NULL,
    rule_source_reference text,
    approved_at timestamp with time zone,
    approved_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT payroll_config_sets_check CHECK (((effective_until IS NULL) OR (effective_until >= effective_from))),
    CONSTRAINT payroll_config_sets_decimal_scale_check CHECK (((decimal_scale >= 2) AND (decimal_scale <= 4))),
    CONSTRAINT payroll_config_sets_rounding_mode_check CHECK ((rounding_mode = ANY (ARRAY['half-up'::text, 'half-even'::text, 'truncate'::text]))),
    CONSTRAINT payroll_config_sets_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'in_review'::text, 'approved'::text, 'retired'::text])))
);


--
-- Name: approve_payroll_configuration(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_payroll_configuration(p_config_set_id uuid, p_reason text) RETURNS public.payroll_config_sets
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result public.payroll_config_sets;
begin
  select * into result from public.payroll_config_sets where id=p_config_set_id for update;
  if not found then raise exception 'Payroll configuration not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(result.company_id,'payroll.configuration.manage')) then
    raise exception 'Insufficient permission' using errcode='42501';
  end if;
  if trim(coalesce(p_reason,''))='' or result.rule_source_reference is null then
    raise exception 'Approval reason and legal source reference are required' using errcode='23514';
  end if;
  update public.payroll_config_sets
  set status='retired',updated_at=now(),updated_by=(select auth.uid())
  where company_id=result.company_id and status='approved' and id<>result.id;
  update public.payroll_config_sets
  set status='approved',approved_at=now(),approved_by=(select auth.uid()),updated_at=now(),updated_by=(select auth.uid())
  where id=result.id returning * into result;
  perform private.record_payroll_audit(result.company_id,null,'payroll.configuration.approved',
    'payroll_config_set',result.id,null,to_jsonb(result),p_reason);
  return result;
end $$;


--
-- Name: payroll_payment_batches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_payment_batches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    payroll_run_id uuid NOT NULL,
    branch_id uuid,
    company_bank_account_id uuid NOT NULL,
    batch_number text NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    payment_date date NOT NULL,
    total_amount numeric(20,4) DEFAULT 0 NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    approval_state text DEFAULT 'pending'::text NOT NULL,
    reconciliation_state text DEFAULT 'unreconciled'::text NOT NULL,
    idempotency_key text NOT NULL,
    approved_at timestamp with time zone,
    approved_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT payroll_payment_batches_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_approval'::text, 'approved'::text, 'exported'::text, 'partially_paid'::text, 'paid'::text, 'rejected'::text, 'reversed'::text])))
);


--
-- Name: approve_payroll_payment_batch(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_payroll_payment_batch(p_batch_id uuid, p_reason text) RETURNS public.payroll_payment_batches
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result public.payroll_payment_batches;
begin
  select * into result from public.payroll_payment_batches where id=p_batch_id for update;
  if not found then raise exception 'Payroll payment batch not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(result.company_id,'payroll.payment_batch.approve')) then raise exception 'Insufficient permission' using errcode='42501'; end if;
  if result.status<>'draft' then raise exception 'Only draft payment batches may be approved' using errcode='55000'; end if;
  if trim(coalesce(p_reason,''))='' then raise exception 'Approval reason is required' using errcode='23514'; end if;
  update public.payroll_payment_batches set status='approved',approval_state='approved',approved_at=now(),approved_by=(select auth.uid())
  where id=result.id returning * into result;
  perform private.record_payroll_audit(result.company_id,result.branch_id,'payroll.payment_batch.approved','payroll_payment_batch',result.id,null,to_jsonb(result),p_reason);
  return result;
end $$;


--
-- Name: payroll_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    branch_id uuid,
