--
-- Name: approve_payroll_run(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_payroll_run(p_payroll_run_id uuid, p_reason text) RETURNS public.payroll_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result public.payroll_runs;
begin
  select * into result from public.payroll_runs where id=p_payroll_run_id for update;
  if not found then raise exception 'Payroll run not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(result.company_id,'payroll.run.approve')) then raise exception 'Insufficient permission' using errcode='42501'; end if;
  if result.status not in ('under_review','pending_approval') then raise exception 'Payroll is not awaiting approval' using errcode='55000'; end if;
  if trim(coalesce(p_reason,''))='' then raise exception 'Approval reason is required' using errcode='23514'; end if;
  insert into public.payroll_approvals(company_id,payroll_run_id,stage,sequence,status,action_by,action_at,reason)
  values(result.company_id,result.id,'final_authorization',50,'approved',(select auth.uid()),now(),trim(p_reason))
  on conflict(payroll_run_id,stage) do update set status='approved',action_by=(select auth.uid()),action_at=now(),reason=excluded.reason;
  update public.payroll_runs set status='approved',approved_at=now(),approved_by=(select auth.uid()),updated_at=now(),updated_by=(select auth.uid())
  where id=result.id returning * into result;
  perform private.record_payroll_audit(result.company_id,result.branch_id,'payroll.run.approved','payroll_run',result.id,null,to_jsonb(result),p_reason);
  perform private.emit_domain_outbox_event(result.company_id,result.branch_id,'payroll_run',result.id,'payroll.run.approved',
    jsonb_build_object('runNumber',result.run_number),result.idempotency_key||':approved');
  return result;
end $$;


--
-- Name: approve_sales_invoice(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_sales_invoice(p_invoice_id uuid, p_reason text) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  invoice_row public.invoices;
  workflow_row public.approval_workflows;
begin
  if nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'An approval reason is required' using errcode = '22023';
  end if;

  select * into invoice_row from public.invoices where id = p_invoice_id for update;
  if not found then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if not (select private.has_company_permission(invoice_row.company_id, 'sales_invoice.approve')) then
    raise exception 'Insufficient permission to approve sales invoices' using errcode = '42501';
  end if;
  if invoice_row.status <> 'pending_approval' or invoice_row.approval_status <> 'pending' then
    raise exception 'Invoice is not awaiting approval' using errcode = '55000';
  end if;

  select * into workflow_row
  from public.approval_workflows
  where company_id = invoice_row.company_id
    and entity_type = 'sales_invoice'
    and entity_id = invoice_row.id
    and status = 'pending'
  for update;
  if not found then
    raise exception 'No pending approval workflow exists for invoice' using errcode = 'P0002';
  end if;

  update public.approval_workflows
  set status = 'approved', resolved_at = clock_timestamp(), resolved_by = (select auth.uid())
  where id = workflow_row.id;
  insert into public.approval_actions (workflow_id, company_id, action, action_by, reason)
  values (workflow_row.id, invoice_row.company_id, 'approved', (select auth.uid()), p_reason);

  update public.invoices
  set status = 'approved', approval_status = 'approved',
      approved_at = clock_timestamp(), approved_by = (select auth.uid())
  where id = invoice_row.id
  returning * into invoice_row;

  perform private.emit_domain_outbox_event(
    invoice_row.company_id, invoice_row.branch_id, 'sales_invoice', invoice_row.id,
    'sales_invoice.approved',
    jsonb_build_object('invoice_number', invoice_row.invoice_number),
    'sales_invoice.approved:' || invoice_row.id::text
  );
  return invoice_row;
end
$$;


--
-- Name: archive_company(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_company(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  company_row public.companies%rowtype;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if p_company_id is null then
    raise exception 'Company is required' using errcode = '23514';
  end if;

  if not private.has_company_permission(p_company_id, 'company.manage') then
    raise exception 'You do not have permission to remove this company'
      using errcode = '42501';
  end if;

  select *
  into company_row
  from public.companies
  where id = p_company_id
  for update;

  if company_row.id is null then
    raise exception 'Company was not found' using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.companies child
    where child.parent_company_id = p_company_id
      and child.archived_at is null
  ) then
    raise exception 'Remove or move all active subdivisions before removing this company'
      using errcode = '23514';
  end if;

  if company_row.archived_at is null then
    update public.companies
    set archived_at = clock_timestamp(),
        updated_at = clock_timestamp(),
        updated_by = (select auth.uid())
    where id = p_company_id;
  end if;

  -- Do not leave any user pointing at a company that is no longer in the
  -- active workspace list. The authorized setting is required by the
  -- active-company guard trigger. A null preference is safe: the app can
  -- show the remaining accessible companies and the user can choose one.
  perform set_config('app.active_company_switch', 'authorized', true);
  update public.profiles
  set active_company_id = null,
      updated_at = clock_timestamp()
  where active_company_id = p_company_id;
  perform set_config('app.active_company_switch', '', true);

  return jsonb_build_object(
    'id', company_row.id,
    'company_name', company_row.company_name,
    'archived_at', coalesce(company_row.archived_at, clock_timestamp())
  );
end;
$$;


