--
-- Name: archive_expense(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_expense(p_expense_id uuid, p_reason text DEFAULT NULL::text) RETURNS public.expenses
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare expense_row public.expenses;
begin
  select * into expense_row from public.expenses where id=p_expense_id for update;
  if expense_row.id is null then raise exception 'Expense not found' using errcode='P0002'; end if;
  if not (private.has_company_permission(expense_row.company_id,'expense.archive') or private.has_company_permission(expense_row.company_id,'expense.post')) then raise exception 'Insufficient permission to archive expense' using errcode='42501'; end if;
  if expense_row.accounting_period_id is not null and exists(select 1 from public.accounting_periods where id=expense_row.accounting_period_id and status in ('closed','locked')) and not private.has_company_permission(expense_row.company_id,'expense.period.reopen') then raise exception 'Closed accounting periods cannot be archived without an authorized amendment' using errcode='55000'; end if;
  perform set_config('app.change_reason',coalesce(nullif(trim(p_reason),''),'Expense archived'),true);
  update public.expenses set archived_at=clock_timestamp(),archived_by=(select auth.uid()),updated_by=(select auth.uid()) where id=p_expense_id returning * into expense_row;
  perform set_config('app.change_reason','',true);
  return expense_row;
end $$;


--
-- Name: assert_efs_production_ready(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_efs_production_ready(p_company_id uuid, p_installation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  installation_row public.fiscal_installations;
  software_ready boolean := false;
  certificate_ready boolean := false;
  key_ready boolean := false;
  taxpayer_ready boolean := false;
  feature_enabled boolean := false;
begin
  if not private.has_company_permission(p_company_id, 'pos.fiscal.retry') then
    raise exception 'Insufficient permission to fiscalize' using errcode = '42501';
  end if;
  select * into installation_row
  from public.fiscal_installations
  where id = p_installation_id and company_id = p_company_id;
  if not found then
    raise exception 'Fiscal installation not found' using errcode = 'P0002';
  end if;
  software_ready := installation_row.software_solution_code is not null
    and installation_row.fiscalization_number is not null;
  taxpayer_ready := installation_row.taxpayer_identifier is not null
    and installation_row.unique_fiscalization_code is not null;
  key_ready := installation_row.signing_key_reference is not null;
  select exists (
    select 1 from public.fiscal_certificates certificate
    where certificate.installation_id = installation_row.id
      and certificate.company_id = p_company_id
      and certificate.status = 'active'
      and (certificate.valid_from is null or certificate.valid_from <= clock_timestamp())
      and (certificate.valid_until is null or certificate.valid_until > clock_timestamp())
  ) into certificate_ready;
  select coalesce((select enabled from public.company_feature_flags
    where company_id = p_company_id and flag = 'kosovo_efs_enabled'), false)
    and coalesce((select enabled from public.company_feature_flags
    where company_id = p_company_id and flag = 'kosovo_efs_production_enabled'), false)
    into feature_enabled;

  if not (
    false -- software certification is intentionally false until TAK certifies this exact build
    and software_ready
    and taxpayer_ready
    and installation_row.status = 'active'
    and certificate_ready
    and key_ready
    and feature_enabled
  ) then
    raise exception 'Production EFS guard blocked: OperiX is not TAK certified or configured for production'
      using errcode = '55000';
  end if;
  return jsonb_build_object('allowed', true, 'production', true);
end
$$;


--
-- Name: billing_consume_product_trials(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_consume_product_trials(p_company_id uuid, p_plan text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  root_company_id uuid;
  trial_product text;
  products text[];
begin
  if not private.operix_server_request() then
    raise exception 'Server billing path required' using errcode = '42501';
  end if;
  if p_plan not in ('invoice', 'booking', 'suite') then
    raise exception 'Unsupported paid product' using errcode = '22023';
  end if;
  root_company_id := private.invoice_billing_root_company_id(p_company_id);
  products := case when p_plan = 'suite' then array['invoice', 'booking', 'suite']::text[] else array[p_plan]::text[] end;
  foreach trial_product in array products loop
    insert into public.subscription_trials(company_id, product_or_plan, started_at, ends_at, status, consumed, metadata)
    values (root_company_id, trial_product, now(), now(), 'completed', true, jsonb_build_object('consumed_by', p_plan, 'source', 'paid_subscription'))
    on conflict (company_id, product_or_plan) do update
      set status = 'completed', consumed = true, updated_at = now(), metadata = public.subscription_trials.metadata || jsonb_build_object('consumed_by', p_plan, 'source', 'paid_subscription');
  end loop;
end;
$$;


--
-- Name: billing_has_permission(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_has_permission(p_company_id uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.can_access_company(p_company_id)
    and private.has_company_permission(private.invoice_billing_root_company_id(p_company_id), p_permission);
$$;


--
-- Name: billing_refresh_product_entitlements(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_refresh_product_entitlements(p_company_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  root_company_id uuid;
  account_row record;
  trial_row record;
  contract_row record;
  grant_row record;
  target_product text;
begin
  if not (private.operix_server_request() or public.control_is_platform_admin()) then
    raise exception 'Server billing path required' using errcode = '42501';
  end if;

  root_company_id := private.invoice_billing_root_company_id(p_company_id);
  perform pg_advisory_xact_lock(hashtextextended(root_company_id::text, 0));
  delete from public.organization_product_entitlements where company_id = root_company_id;

  for account_row in select * from public.subscription_accounts where company_id = root_company_id loop
    if private.operix_status_has_access(account_row.status, account_row.trial_ends_at, account_row.current_period_end, account_row.grace_period_ends_at, account_row.manual_override_status, account_row.manual_override_expires_at) then
      if account_row.product = 'suite' then
        foreach target_product in array array['invoice', 'booking'] loop
          insert into public.organization_product_entitlements(company_id, product, source, source_id, enabled, starts_at, ends_at, metadata)
          values (root_company_id, target_product, 'subscription', account_row.id, true, coalesce(account_row.current_period_start, account_row.created_at), case when account_row.status = 'canceled' then account_row.current_period_end when account_row.status = 'past_due' then account_row.grace_period_ends_at when account_row.status = 'trialing' then account_row.trial_ends_at else null end, jsonb_build_object('plan', account_row.product, 'subscription_id', account_row.stripe_subscription_id));
        end loop;
      else
        insert into public.organization_product_entitlements(company_id, product, source, source_id, enabled, starts_at, ends_at, metadata)
        values (root_company_id, account_row.product, 'subscription', account_row.id, true, coalesce(account_row.current_period_start, account_row.created_at), case when account_row.status = 'canceled' then account_row.current_period_end when account_row.status = 'past_due' then account_row.grace_period_ends_at when account_row.status = 'trialing' then account_row.trial_ends_at else null end, jsonb_build_object('plan', account_row.product, 'subscription_id', account_row.stripe_subscription_id));
      end if;
    end if;
  end loop;

  for trial_row in select * from public.subscription_trials where company_id = root_company_id and status = 'trialing' and ends_at > now() loop
    if trial_row.product_or_plan = 'suite' then
      foreach target_product in array array['invoice', 'booking'] loop
        insert into public.organization_product_entitlements(company_id, product, source, source_id, enabled, starts_at, ends_at, metadata)
        values (root_company_id, target_product, 'trial', trial_row.id, true, trial_row.started_at, trial_row.ends_at, jsonb_build_object('plan', trial_row.product_or_plan));
      end loop;
    else
      insert into public.organization_product_entitlements(company_id, product, source, source_id, enabled, starts_at, ends_at, metadata)
      values (root_company_id, trial_row.product_or_plan, 'trial', trial_row.id, true, trial_row.started_at, trial_row.ends_at, jsonb_build_object('plan', trial_row.product_or_plan));
    end if;
  end loop;

  for grant_row in select * from public.subscription_manual_grants where company_id = root_company_id and revoked_at is null and coalesce(override_status, 'active') in ('active', 'trialing') and (expires_at is null or expires_at > now()) loop
    if grant_row.product = 'suite' then
      foreach target_product in array array['invoice', 'booking'] loop
        insert into public.organization_product_entitlements(company_id, product, source, source_id, enabled, starts_at, ends_at, metadata)
        values (root_company_id, target_product, 'manual_grant', grant_row.id, true, grant_row.created_at, grant_row.expires_at, jsonb_build_object('grant_type', grant_row.grant_type, 'reason', grant_row.reason));
      end loop;
    else
      insert into public.organization_product_entitlements(company_id, product, source, source_id, enabled, starts_at, ends_at, metadata)
      values (root_company_id, grant_row.product, 'manual_grant', grant_row.id, true, grant_row.created_at, grant_row.expires_at, jsonb_build_object('grant_type', grant_row.grant_type, 'reason', grant_row.reason));
    end if;
  end loop;

  for contract_row in
    select contract.id, contract.company_id, contract.starts_at, contract.ends_at, contract.status, contract.trial_ends_at, product.product
    from public.enterprise_contracts contract
    join public.enterprise_contract_products product on product.contract_id = contract.id
    where contract.company_id = root_company_id
      and product.enabled
      and contract.status in ('trialing', 'active')
      and contract.starts_at <= now()
      and (contract.ends_at is null or contract.ends_at > now())
      and (contract.trial_ends_at is null or contract.trial_ends_at > now() or contract.status = 'active')
  loop
    insert into public.organization_product_entitlements(company_id, product, source, source_id, enabled, starts_at, ends_at, metadata)
    values (root_company_id, contract_row.product, 'enterprise_contract', contract_row.id, true, contract_row.starts_at, case when contract_row.status = 'trialing' then contract_row.trial_ends_at else contract_row.ends_at end, jsonb_build_object('contract_id', contract_row.id, 'trial_ends_at', contract_row.trial_ends_at));
  end loop;
end;
$$;


--
-- Name: booking_invoice_automation_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_invoice_automation_access(p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.operix_server_request()
    and private.operix_product_access(p_company_id, 'booking')
    and private.operix_product_access(p_company_id, 'invoice');
$$;


--
-- Name: booking_invoice_automation_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_invoice_automation_allowed(p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (select auth.uid()) is not null
    and public.can_access_company(p_company_id)
    and private.operix_product_access(p_company_id, 'booking')
    and private.operix_product_access(p_company_id, 'invoice');
$$;


--
-- Name: booking_invoice_claim_jobs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_invoice_claim_jobs(p_limit integer DEFAULT 25) RETURNS TABLE(job_id uuid, company_id uuid, booking_id uuid, trigger_event text, attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.operix_server_request() then raise exception 'Server-only automation function' using errcode = '42501'; end if;
  return query
  with candidates as (
    select job.id
    from public.booking_invoice_jobs job
    where job.status in ('pending', 'failed')
      and job.available_at <= now()
    order by job.created_at
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 25), 100))
  ), claimed as (
    update public.booking_invoice_jobs job
    set status = 'processing', attempts = job.attempts + 1, locked_at = now(), updated_at = now()
    from candidates
    where job.id = candidates.id
    returning job.id, job.company_id, job.booking_id, job.trigger_event, job.attempts
  )
  select claimed.id, claimed.company_id, claimed.booking_id, claimed.trigger_event, claimed.attempts from claimed;
end;
$$;


--
-- Name: calculate_withholding(uuid, text, numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_withholding(p_company_id uuid, p_category text, p_gross_amount numeric, p_payment_date date DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare rule_row public.withholding_tax_rules;
begin
  if not (select private.has_company_permission(p_company_id, 'withholding.manage')) then
    raise exception 'Insufficient permission to calculate withholding' using errcode = '42501';
  end if;
  select * into rule_row from public.withholding_tax_rules
  where company_id = p_company_id and category = lower(trim(p_category))
    and effective_from <= coalesce(p_payment_date, current_date)
    and (effective_until is null or effective_until >= coalesce(p_payment_date, current_date))
  order by effective_from desc limit 1;
  if not found then raise exception 'No effective withholding rule exists for category %', p_category using errcode = 'P0002'; end if;
  if rule_row.requires_legal_review then
    raise exception 'Withholding category % requires legal review before calculation', rule_row.category using errcode = '55000';
  end if;
  return round(greatest(coalesce(p_gross_amount, 0), 0) * rule_row.rate_percent / 100, 2);
end
$$;


--
-- Name: can_access_company(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_company(target_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select target_company_id is not null
    and private.company_is_active(target_company_id)
    and (
      private.rbac_is_platform_admin()
      or exists (
        select 1 from public.companies company
        where company.id = target_company_id
          and company.owner_id = (select auth.uid())
      )
      or exists (
        with recursive ancestors(id) as (
          select target_company_id
          union
          select company.parent_company_id
          from public.companies company
          join ancestors on ancestors.id = company.id
          where company.parent_company_id is not null
        )
        select 1
        from public.memberships membership
        join ancestors on ancestors.id = membership.company_id
        where membership.user_id = (select auth.uid())
          and coalesce(membership.status, 'active') = 'active'
      )
    );
$$;


--
-- Name: held_orders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.held_orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    branch_id uuid NOT NULL,
    terminal_id uuid NOT NULL,
    warehouse_id uuid,
    cashier_id uuid NOT NULL,
    customer_id uuid,
    status text DEFAULT 'held'::text NOT NULL,
    cart_snapshot jsonb NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    expires_at timestamp with time zone,
    resumed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    cancel_reason text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_by uuid,
    CONSTRAINT held_orders_cart_snapshot_check CHECK ((jsonb_typeof(cart_snapshot) = 'object'::text)),
    CONSTRAINT held_orders_status_check CHECK ((status = ANY (ARRAY['held'::text, 'resumed'::text, 'transferred'::text, 'cancelled'::text, 'expired'::text, 'completed'::text]))),
    CONSTRAINT held_orders_version_check CHECK ((version > 0))
);


--
-- Name: cancel_held_pos_order(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_held_pos_order(p_company_id uuid, p_held_order_id uuid, p_expected_version integer, p_reason text) RETURNS public.held_orders
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare held_row public.held_orders;
begin
  if not (select private.has_company_permission(p_company_id, 'pos.order.cancel')) then
    raise exception 'Insufficient permission to cancel held orders' using errcode = '42501';
  end if;
  if nullif(trim(p_reason), '') is null then
    raise exception 'A cancellation reason is required' using errcode = '23514';
  end if;
  select * into held_row
  from public.held_orders
  where id = p_held_order_id and company_id = p_company_id
  for update;
  if not found or held_row.status <> 'held' then
    raise exception 'Held order is unavailable' using errcode = '55000';
  end if;
  if held_row.version <> p_expected_version then
    raise exception 'Held order changed; refresh before cancelling' using errcode = '40001';
  end if;
  update public.held_orders
  set status = 'cancelled', cancel_reason = trim(p_reason),
      cancelled_at = clock_timestamp(), version = version + 1,
      updated_at = clock_timestamp(), updated_by = (select auth.uid())
  where id = held_row.id
  returning * into held_row;
  return held_row;
end
$$;


--
-- Name: subscription_sync_queue; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.subscription_sync_queue (
    company_id uuid NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    locked_at timestamp with time zone,
    processed_at timestamp with time zone,
    last_error text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT subscription_sync_queue_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT subscription_sync_queue_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'succeeded'::text, 'failed'::text])))
);


--
-- Name: claim_invoice_sync_queue(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_invoice_sync_queue(p_limit integer DEFAULT 25) RETURNS SETOF public.subscription_sync_queue
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select * from public.claim_product_sync_queue(p_limit);
$$;


--
-- Name: claim_invoice_webhook_event(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_invoice_webhook_event(p_event_id text, p_event_type text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  event_row public.stripe_webhook_events;
begin
  if nullif(trim(p_event_id), '') is null or nullif(trim(p_event_type), '') is null then
    raise exception 'Stripe event identity is required' using errcode = '22023';
  end if;

  insert into public.stripe_webhook_events(stripe_event_id, event_type)
  values (trim(p_event_id), trim(p_event_type))
  on conflict (stripe_event_id) do nothing;
  if found then return true; end if;

  select * into event_row
  from public.stripe_webhook_events
  where stripe_event_id = trim(p_event_id)
  for update;

  if event_row.processing_status = 'succeeded' then
    return false;
  end if;
  if event_row.processing_status = 'processing'
     and event_row.processing_started_at > now() - interval '10 minutes' then
    return false;
  end if;

  update public.stripe_webhook_events
  set processing_status = 'processing',
      attempts = event_row.attempts + 1,
      processing_started_at = now(),
      error = null,
      updated_at = now()
  where stripe_event_id = trim(p_event_id);
  return true;
end;
$$;


--
-- Name: claim_product_sync_queue(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_product_sync_queue(p_limit integer DEFAULT 25) RETURNS SETOF public.subscription_sync_queue
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.operix_server_request() then
    raise exception 'Server billing path required' using errcode = '42501';
  end if;
  return query
  with claimed as (
    select queue.company_id
    from public.subscription_sync_queue queue
    where (
      queue.status in ('pending', 'failed')
      and queue.requested_at <= now()
    ) or (
      queue.status = 'processing'
      and queue.locked_at < now() - interval '10 minutes'
    )
    order by queue.requested_at
    limit greatest(1, least(coalesce(p_limit, 25), 100))
    for update skip locked
  )
  update public.subscription_sync_queue queue
  set status = 'processing', locked_at = now(), attempts = queue.attempts + 1, updated_at = now()
  from claimed
  where queue.company_id = claimed.company_id
  returning queue.*;
end;
$$;


--
-- Name: claim_scheduled_product_changes(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_scheduled_product_changes(p_limit integer DEFAULT 25) RETURNS TABLE(id uuid, company_id uuid, stripe_subscription_id text, product text, scheduled_plan text, billing_interval text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.operix_server_request() then
    raise exception 'Server billing path required' using errcode = '42501';
  end if;
  return query
  with claimed as (
    select account.id
    from public.subscription_accounts account
    where account.scheduled_plan is not null
      and account.scheduled_change_at <= now()
      and account.stripe_subscription_id is not null
    order by account.scheduled_change_at
    limit greatest(1, least(coalesce(p_limit, 25), 100))
    for update skip locked
  )
  update public.subscription_accounts account
  set updated_at = now()
  from claimed
  where account.id = claimed.id
  returning account.id, account.company_id, account.stripe_subscription_id, account.product, account.scheduled_plan, coalesce(account.scheduled_billing_interval, account.billing_interval);
end;
$$;


--
-- Name: claim_stripe_webhook_event(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_stripe_webhook_event(p_event_id text, p_stripe_store_id uuid, p_event_type text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into private.stripe_webhook_events (event_id, stripe_store_id, event_type)
  values (p_event_id, p_stripe_store_id, p_event_type)
  on conflict (event_id) do nothing;
  if found then return true; end if;
  -- A failed delivery is retryable; a successfully processed event remains
  -- idempotently ignored on all later Stripe retries.
  update private.stripe_webhook_events
  set processed_at = null, error_message = null
  where event_id = p_event_id
    and error_message is not null;
  return found;
end;
$$;


--
-- Name: bank_reconciliations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_reconciliations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    company_bank_account_id uuid NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    opening_balance numeric(20,4) DEFAULT 0 NOT NULL,
    statement_closing_balance numeric(20,4),
    gl_closing_balance numeric(20,4),
    difference numeric(20,4),
    status text DEFAULT 'open'::text NOT NULL,
    completed_at timestamp with time zone,
    completed_by uuid,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT bank_reconciliations_check CHECK ((period_end >= period_start)),
    CONSTRAINT bank_reconciliations_status_check CHECK ((status = ANY (ARRAY['open'::text, 'completed'::text, 'reopened'::text])))
);


--
-- Name: complete_bank_reconciliation(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_bank_reconciliation(p_reconciliation_id uuid, p_statement_closing_balance numeric, p_reason text) RETURNS public.bank_reconciliations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare reconciliation_row public.bank_reconciliations; gl_balance numeric(20,4);
begin
  select * into reconciliation_row from public.bank_reconciliations where id=p_reconciliation_id for update;
  if not found then raise exception 'Bank reconciliation not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(reconciliation_row.company_id,'bank.reconcile')) then raise exception 'Insufficient permission to complete bank reconciliation' using errcode='42501'; end if;
  if trim(coalesce(p_reason,''))='' then raise exception 'Bank reconciliation reason is required' using errcode='23514'; end if;
  select coalesce(sum(line.debit-line.credit),0) into gl_balance
  from public.journal_entries entry join public.journal_entry_lines line on line.journal_entry_id=entry.id
  join public.chart_of_accounts account on account.id=line.account_id
  where entry.company_id=reconciliation_row.company_id and entry.status='posted'
    and (
      account.id=(select bank.account_id from public.company_bank_accounts bank where bank.id=reconciliation_row.company_bank_account_id)
      or ((select bank.account_id from public.company_bank_accounts bank where bank.id=reconciliation_row.company_bank_account_id) is null and account.code='1020')
    )
    and entry.posting_date <= reconciliation_row.period_end;
  update public.bank_reconciliations set statement_closing_balance=round(p_statement_closing_balance,4),gl_closing_balance=round(gl_balance,4),
    difference=round(p_statement_closing_balance-gl_balance,4),status='completed',completed_at=clock_timestamp(),completed_by=(select auth.uid()),notes=coalesce(notes||E'\n','')||p_reason
  where id=reconciliation_row.id returning * into reconciliation_row;
  return reconciliation_row;
end
$$;


--
-- Name: complete_invoice_webhook_event(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_invoice_webhook_event(p_event_id text, p_error_message text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.stripe_webhook_events
  set processing_status = case when p_error_message is null then 'succeeded' else 'failed' end,
      processed_at = case when p_error_message is null then now() else null end,
      error = nullif(left(p_error_message, 1000), ''),
      updated_at = now()
  where stripe_event_id = p_event_id;
$$;


--
-- Name: complete_pos_sale(uuid, uuid, uuid, jsonb, jsonb, text, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_pos_sale(p_company_id uuid, p_terminal_id uuid, p_customer_id uuid, p_items jsonb, p_payments jsonb, p_invoice_type text DEFAULT 'invoice'::text, p_notes text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid, p_occurred_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  reservation public.pos_command_idempotency;
  existing_order public.pos_orders;
  terminal_row public.pos_terminals;
  shift_row public.cashier_shifts;
  result jsonb;
  result_order_id uuid;
  cash_amount numeric(20,4);
begin
  if p_company_id is null or p_idempotency_key is null then
    raise exception 'Company and idempotency key are required for POS completion' using errcode = '23514';
  end if;
  if not (select private.is_company_member(p_company_id))
    or not (select private.has_company_permission(p_company_id, 'pos.complete'))
    or not (select private.has_company_permission(p_company_id, 'pos.terminal.use')) then
    raise exception 'Insufficient permission to complete POS sales on this terminal' using errcode = '42501';
  end if;
  if not coalesce((
    select flag.enabled
    from public.company_feature_flags flag
    where flag.company_id = p_company_id and flag.flag = 'transactional_pos_enabled'
  ), false) then
    raise exception 'Transactional POS is not enabled for this company' using errcode = '55000';
  end if;

  terminal_row := private.resolve_pos_terminal(p_company_id, p_terminal_id);

  -- This insert serializes duplicate browser, network, and offline replay
  -- requests. A failed core transaction rolls the reservation back too.
  insert into public.pos_command_idempotency (company_id, idempotency_key, terminal_id, created_by)
  values (p_company_id, p_idempotency_key, terminal_row.id, (select auth.uid()))
  on conflict (company_id, idempotency_key) do nothing;

  select * into reservation
  from public.pos_command_idempotency
  where company_id = p_company_id and idempotency_key = p_idempotency_key
  for update;

  if reservation.order_id is not null then
    select * into existing_order from public.pos_orders where id = reservation.order_id;
    return jsonb_build_object(
      'order_id', reservation.order_id,
      'invoice_id', reservation.invoice_id,
      'invoice_number', existing_order.order_number,
      'order_number', existing_order.order_number,
      'total_amount', existing_order.total_amount,
      'change_amount', existing_order.change_amount,
      'cashier_shift_id', existing_order.cashier_shift_id,
      'idempotent', true
    );
  end if;

  if terminal_row.cashier_shift_required then
    select *
    into shift_row
    from public.cashier_shifts
    where company_id = p_company_id
      and terminal_id = terminal_row.id
      and cashier_id = (select auth.uid())
      and status in ('open','active','reopened')
    for update;

    if not found then
      raise exception 'Open your cashier shift before completing a sale on this terminal'
        using errcode = '55000';
    end if;
  end if;

  result := private.complete_pos_sale_core(
    p_company_id,
    terminal_row.id,
    p_customer_id,
    p_items,
    p_payments,
    p_invoice_type,
    p_notes,
    p_idempotency_key,
    p_occurred_at
  );
  result_order_id := nullif(result ->> 'order_id', '')::uuid;

  if shift_row.id is not null then
    perform set_config('app.pos_workflow', 'authorized', true);
    update public.pos_orders
    set cashier_shift_id = shift_row.id,
        updated_at = clock_timestamp(),
        updated_by = (select auth.uid())
    where id = result_order_id;

    update public.pos_payments
    set cashier_shift_id = shift_row.id
    where pos_order_id = result_order_id;
    perform set_config('app.pos_workflow', '', true);

    select coalesce(sum(payment.allocated_amount), 0)
    into cash_amount
    from public.pos_payments payment
    where payment.pos_order_id = result_order_id
      and payment.payment_method = 'cash';

    if cash_amount <> 0 then
      update public.cashier_shifts
      set expected_cash = round(expected_cash + cash_amount, 4),
          updated_at = clock_timestamp()
      where id = shift_row.id
      returning * into shift_row;

      insert into public.cashier_shift_movements (
        company_id, cashier_shift_id, terminal_id, movement_type, amount,
        currency, source_type, source_id, reason, created_by
      )
      values (
        p_company_id, shift_row.id, terminal_row.id, 'cash_sale',
        round(cash_amount, 4), 'EUR', 'pos_order', result_order_id,
        'Cash received from completed POS sale', (select auth.uid())
      );
    end if;

    insert into public.cashier_shift_events (
      company_id, cashier_shift_id, event_type, payload, actor_id
    )
    values (
      p_company_id, shift_row.id, 'sale_completed',
      jsonb_build_object(
        'pos_order_id', result_order_id,
        'invoice_id', nullif(result ->> 'invoice_id', '')::uuid,
        'total_amount', result ->> 'total_amount',
        'cash_amount', cash_amount
      ),
      (select auth.uid())
    );

    result := result || jsonb_build_object('cashier_shift_id', shift_row.id);
  end if;

  update public.pos_command_idempotency
  set order_id = result_order_id,
      invoice_id = nullif(result ->> 'invoice_id', '')::uuid,
      status = 'completed',
      completed_at = clock_timestamp()
  where company_id = p_company_id and idempotency_key = p_idempotency_key;

  return result;
end
$$;


--
-- Name: complete_pos_sale_with_signature(uuid, uuid, uuid, jsonb, jsonb, text, text, uuid, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_pos_sale_with_signature(p_company_id uuid, p_terminal_id uuid, p_customer_id uuid, p_items jsonb, p_payments jsonb, p_invoice_type text DEFAULT 'invoice'::text, p_notes text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid, p_occurred_at timestamp with time zone DEFAULT clock_timestamp(), p_customer_signature jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  result jsonb;
begin
  perform set_config('app.customer_signature_context', coalesce(p_customer_signature, '{}'::jsonb)::text, true);
  result := public.complete_pos_sale(
    p_company_id,
    p_terminal_id,
    p_customer_id,
    p_items,
    p_payments,
    p_invoice_type,
    p_notes,
    p_idempotency_key,
    p_occurred_at
  );
  perform set_config('app.customer_signature_context', '', true);
  return result;
exception
  when others then
    perform set_config('app.customer_signature_context', '', true);
    raise;
end
$$;


--
-- Name: complete_signup_onboarding(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_signup_onboarding(p_tenant_name text, p_first_name text, p_last_name text, p_phone text, p_tax_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  current_user_id uuid := (select auth.uid());
  account_email text;
  company_result jsonb;
  new_company_id uuid;
  existing_company_id uuid;
begin
  if current_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if nullif(trim(p_tenant_name), '') is null then
    raise exception 'Tenant name is required' using errcode = '23514';
  end if;

  select email into account_email
  from auth.users
  where id = current_user_id;

  select active_company_id into existing_company_id
  from public.profiles
  where id = current_user_id;

  if existing_company_id is not null and (
    exists (
      select 1
      from public.companies company
      where company.id = existing_company_id
        and company.owner_id = current_user_id
    )
    or exists (
      select 1
      from public.memberships membership
      where membership.user_id = current_user_id
        and membership.company_id = existing_company_id
        and coalesce(membership.status, 'active') = 'active'
    )
  ) then
    select jsonb_build_object('id', company.id, 'company_name', company.company_name)
      into company_result
    from public.companies company
    where company.id = existing_company_id;
  else
    company_result := public.create_company_and_owner(trim(p_tenant_name));
  end if;
  new_company_id := (company_result ->> 'id')::uuid;

  perform set_config('app.company_link_workflow', 'authorized', true);
  perform set_config('app.active_company_switch', 'authorized', true);
  update public.profiles
  set first_name = nullif(trim(p_first_name), ''),
      last_name = nullif(trim(p_last_name), ''),
      phone = nullif(trim(p_phone), ''),
      email = coalesce(nullif(trim(account_email), ''), email),
      company_name = trim(p_tenant_name),
      tax_id = nullif(trim(p_tax_id), ''),
      company_id = new_company_id,
      active_company_id = new_company_id,
      updated_at = clock_timestamp()
  where id = current_user_id;
  perform set_config('app.company_link_workflow', '', true);
  perform set_config('app.active_company_switch', '', true);

  update public.companies
  set email = coalesce(nullif(trim(account_email), ''), email),
      phone = nullif(trim(p_phone), ''),
      tax_id = nullif(trim(p_tax_id), ''),
      updated_at = clock_timestamp()
  where id = new_company_id;

  return company_result || jsonb_build_object(
    'first_name', nullif(trim(p_first_name), ''),
    'last_name', nullif(trim(p_last_name), '')
  );
end
$$;


--
-- Name: complete_stripe_webhook_event(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_stripe_webhook_event(p_event_id text, p_error_message text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update private.stripe_webhook_events
  set processed_at = clock_timestamp(), error_message = p_error_message
  where event_id = p_event_id
$$;


--
-- Name: consume_stripe_oauth_state(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_stripe_oauth_state(p_state_hash text) RETURNS TABLE(stripe_store_id uuid, user_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  state_row private.stripe_oauth_states;
begin
  select * into state_row
  from private.stripe_oauth_states
  where state_hash = p_state_hash
  for update;
  if not found or state_row.consumed_at is not null or state_row.expires_at <= now() then
    return;
  end if;
  update private.stripe_oauth_states
  set consumed_at = clock_timestamp()
  where state_hash = p_state_hash;
  stripe_store_id := state_row.stripe_store_id;
  user_id := state_row.user_id;
  return next;
end;
$$;


