    AS $$
  select private.rbac_is_platform_admin();
$$;


--
-- Name: convert_commercial_document(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convert_commercial_document(p_source_document_id uuid, p_target_document_type text, p_idempotency_key uuid DEFAULT gen_random_uuid()) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  source_row public.invoices;
  target_row public.invoices;
  source_type text;
  target_type text := upper(trim(coalesce(p_target_document_type, '')));
  target_legacy_type text;
  target_subtype text;
  link_type text;
  target_number text;
  target_id uuid;
  source_permission text;
  target_permission text;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  select * into source_row from public.invoices where id = p_source_document_id for update;
  if not found then raise exception 'Source commercial document not found' using errcode = 'P0002'; end if;

  source_type := upper(coalesce(source_row.commercial_document_type, ''));
  if target_type not in ('QUOTE','PROFORMA','SALES_ORDER','DELIVERY_NOTE','INVOICE','ADVANCE_INVOICE','FINAL_INVOICE','CREDIT_NOTE','DEBIT_NOTE','SIMPLIFIED_INVOICE','FISCAL_RECEIPT','BAD_DEBT_INVOICE') then
    raise exception 'Unsupported target commercial document type %', target_type using errcode = '22023';
  end if;
  if not ((source_type = 'QUOTE' and target_type in ('SALES_ORDER','INVOICE'))
       or (source_type = 'PROFORMA' and target_type in ('SALES_ORDER','INVOICE','ADVANCE_INVOICE'))
       or (source_type = 'SALES_ORDER' and target_type in ('DELIVERY_NOTE','INVOICE'))
       or (source_type = 'DELIVERY_NOTE' and target_type = 'INVOICE')
       or (source_type = 'ADVANCE_INVOICE' and target_type = 'FINAL_INVOICE')
       or (source_type in ('INVOICE','FINAL_INVOICE','SIMPLIFIED_INVOICE','FISCAL_RECEIPT','BAD_DEBT_INVOICE') and target_type in ('CREDIT_NOTE','DEBIT_NOTE'))) then
    raise exception 'Conversion from % to % is not supported', source_type, target_type using errcode = '22023';
  end if;

  target_permission := case
    when target_type = 'QUOTE' then 'offer.create'
    when target_type = 'PROFORMA' then 'proforma.create'
    when target_type = 'SALES_ORDER' then 'order.create'
    when target_type = 'DELIVERY_NOTE' then 'delivery_note.create'
    when target_type = 'CREDIT_NOTE' then 'invoice.credit'
    when target_type = 'DEBIT_NOTE' then 'invoice.debit'
    else 'invoice.create'
  end;
  source_permission := case
    when target_type = 'CREDIT_NOTE' then 'invoice.credit'
    when target_type = 'DEBIT_NOTE' then 'invoice.debit'
    else 'invoice.edit'
  end;
  if not private.rbac_can_read_resource(source_row.company_id, 'invoice', source_row.user_id, source_row.assigned_user_id, source_permission)
     or not private.has_company_permission(source_row.company_id, target_permission) then
    raise exception 'Insufficient permission or data scope to convert this document' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(source_row.id::text || ':' || target_type, 0));
  select target.id into target_id
  from public.document_source_links link
  join public.invoices target on target.id = link.target_id
  where link.company_id = source_row.company_id
    and link.source_type = 'commercial_document'
    and link.source_id = source_row.id
    and link.target_type = 'commercial_document'
    and link.metadata ->> 'target_document_type' = target_type
  limit 1;
  if target_id is not null then
    select * into target_row from public.invoices where id = target_id;
    return target_row;
  end if;

  target_number := public.reserve_invoice_number(source_row.company_id, lower(target_type), coalesce(source_row.issue_date, current_date));
  target_legacy_type := case when target_type = 'QUOTE' then 'offer' when target_type = 'PROFORMA' then 'proforma' when target_type = 'SALES_ORDER' then 'offer' else 'invoice' end;
  target_subtype := case target_type
    when 'QUOTE' then 'offer'
    when 'PROFORMA' then 'pro_invoice'
    when 'SALES_ORDER' then 'order'
    when 'DELIVERY_NOTE' then 'delivery_note'
    when 'ADVANCE_INVOICE' then 'advance_invoice'
    when 'FINAL_INVOICE' then 'final_invoice'
    when 'CREDIT_NOTE' then 'credit_note'
    when 'DEBIT_NOTE' then 'debit_note'
    when 'SIMPLIFIED_INVOICE' then 'simplified_invoice'
    when 'FISCAL_RECEIPT' then 'fiscal_receipt'
    when 'BAD_DEBT_INVOICE' then 'bad_debt_invoice'
    else 'regular'
  end;
  link_type := case
    when source_type = 'QUOTE' then 'quotation_conversion'
    when source_type = 'PROFORMA' and target_type = 'ADVANCE_INVOICE' then 'proforma_to_advance'
    when source_type = 'PROFORMA' then 'proforma_conversion'
    when source_type = 'SALES_ORDER' and target_type = 'DELIVERY_NOTE' then 'order_conversion'
    when source_type = 'DELIVERY_NOTE' then 'delivery_to_invoice'
    when source_type = 'ADVANCE_INVOICE' then 'advance_finalization'
    when target_type = 'CREDIT_NOTE' then 'credit_note'
    when target_type = 'DEBIT_NOTE' then 'debit_note'
    else 'adjustment'
  end;

  insert into public.invoices (
    user_id, company_id, client_id, invoice_number, issue_date, due_date, status,
    discount_amount, discount_percent, tax_amount, total_amount, notes, template_id,
    type, subtype, payment_method, amount_received, change_amount, currency, exchange_rate,
    source_document_type, source_document_id, credit_of_invoice_id, original_invoice_id,
    accounting_state, commercial_document_type, commercial_status, accounting_status,
    vat_status, inventory_status, payment_status, fiscalization_status, supply_date,
    order_date, delivery_date, valid_until, customer_po_number, delivery_address,
    shipping_address, payment_terms, delivery_terms, show_prices_on_delivery_note,
    advance_applied_amount, idempotency_key
  ) values (
    coalesce((select auth.uid()), source_row.user_id), source_row.company_id, source_row.client_id,
    target_number, coalesce(source_row.issue_date, current_date), source_row.due_date, 'draft',
    source_row.discount_amount, source_row.discount_percent, source_row.tax_amount, source_row.total_amount,
    source_row.notes, source_row.template_id, target_legacy_type, target_subtype, 'cash', 0, 0,
    source_row.currency, source_row.exchange_rate, source_type, source_row.id,
    case when target_type = 'CREDIT_NOTE' then source_row.id else null end,
    case when target_type in ('DEBIT_NOTE','BAD_DEBT_INVOICE') then source_row.id else null end,
    case when target_type in ('QUOTE','PROFORMA','SALES_ORDER','DELIVERY_NOTE') then 'legacy' else 'ready_for_posting' end,
    target_type, 'DRAFT', case when target_type in ('QUOTE','PROFORMA','SALES_ORDER','DELIVERY_NOTE') then 'NOT_APPLICABLE' else 'READY_TO_POST' end,
    case when target_type in ('QUOTE','PROFORMA','SALES_ORDER','DELIVERY_NOTE') then 'NOT_APPLICABLE' else 'NOT_EVALUATED' end,
    case when target_type in ('SALES_ORDER','DELIVERY_NOTE') then 'POLICY_DEPENDENT' else 'NOT_APPLICABLE' end,
    case when target_type in ('QUOTE','PROFORMA','SALES_ORDER','DELIVERY_NOTE') then 'NOT_APPLICABLE' else 'UNPAID' end,
    'NOT_REQUIRED', source_row.supply_date, source_row.order_date, source_row.delivery_date, source_row.valid_until,
    source_row.customer_po_number, source_row.delivery_address, source_row.shipping_address,
    source_row.payment_terms, source_row.delivery_terms, source_row.show_prices_on_delivery_note,
    0, p_idempotency_key
  ) returning * into target_row;

  insert into public.invoice_items (
    invoice_id, product_id, description, quantity, unit_price, tax_rate, amount, unit,
    revenue_account_id, tax_code, cost_centre_id, project_id, source_item_id, credited_quantity
  )
  select target_row.id, item.product_id, item.description, item.quantity, item.unit_price,
    item.tax_rate, item.amount, item.unit, item.revenue_account_id, item.tax_code,
    item.cost_centre_id, item.project_id, item.id, 0
  from public.invoice_items item
  where item.invoice_id = source_row.id;

  insert into public.document_source_links (
    company_id, source_type, source_id, target_type, target_id, link_type, amount, metadata, created_by
  ) values (
    source_row.company_id, 'commercial_document', source_row.id, 'commercial_document', target_row.id,
    link_type, source_row.total_amount,
    jsonb_build_object('target_document_type', target_type, 'idempotency_key', p_idempotency_key),
    (select auth.uid())
  ) on conflict do nothing;

  perform private.insert_commercial_document_event(
    source_row.company_id, source_row.id, 'converted', source_row.commercial_status,
    'CONVERTED', jsonb_build_object('target_document_id', target_row.id, 'target_document_type', target_type),
    clock_timestamp(), (select auth.uid())
  );
  update public.invoices set commercial_status = 'CONVERTED' where id = source_row.id;
  return target_row;
end;
$$;


--
-- Name: correct_expense(uuid, numeric, text, text, date, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.correct_expense(p_expense_id uuid, p_amount numeric, p_category text, p_description text, p_date date, p_receipt_url text DEFAULT NULL::text, p_type text DEFAULT 'expense'::text, p_correction_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS public.expenses
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  expense_row public.expenses;
  current_journal public.journal_entries;
  correction_journal public.journal_entries;
  correction_id uuid := coalesce(p_correction_id, gen_random_uuid());
  correction_date date := current_date;
  normalized_amount numeric(20,4) := round(coalesce(p_amount, 0), 4);
  normalized_type text := lower(trim(coalesce(p_type, 'expense')));
  correction_reason text := coalesce(nullif(trim(p_reason), ''), 'Expense corrected');
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_expense_id is null then
    raise exception 'Expense id is required' using errcode = '23514';
  end if;
  if normalized_amount <= 0 then
    raise exception 'Expense amount must be greater than zero' using errcode = '23514';
  end if;
  if normalized_type <> 'expense' then
    raise exception 'Only expense records can use the accounting correction workflow' using errcode = '55000';
  end if;

  select *
    into expense_row
    from public.expenses
   where id = p_expense_id
   for update;

  if not found then
    raise exception 'Expense not found' using errcode = 'P0002';
  end if;
  if expense_row.company_id is null
     or not coalesce(private.has_company_permission(expense_row.company_id, 'expense.post'), false)
     or not coalesce(private.has_company_permission(expense_row.company_id, 'journal.post'), false)
     or not coalesce(private.has_company_permission(expense_row.company_id, 'journal.reverse'), false) then
    raise exception 'You do not have permission to correct this expense' using errcode = '42501';
  end if;

  select *
    into correction_journal
    from public.journal_entries
   where company_id = expense_row.company_id
     and source_type = 'expense_correction'
     and source_id = correction_id
     and entry_type = 'automatic';
  if found then
    if correction_journal.metadata ->> 'expense_id' is distinct from expense_row.id::text then
      raise exception 'Correction id is already used for another expense' using errcode = '23505';
    end if;
    return expense_row;
  end if;

  if expense_row.accounting_state <> 'posted' then
    raise exception 'Only posted expenses can be corrected' using errcode = '55000';
  end if;
  if expense_row.posting_journal_entry_id is null then
    raise exception 'The posted expense has no accounting journal' using errcode = '55000';
  end if;

  select *
    into current_journal
    from public.journal_entries
   where id = expense_row.posting_journal_entry_id
   for update;
  if not found or current_journal.status <> 'posted' then
    raise exception 'The current expense journal is not posted' using errcode = '55000';
  end if;
  if current_journal.entry_type <> 'automatic'
     or not (
       (current_journal.source_type = 'expense' and current_journal.source_id = expense_row.id)
       or (
         current_journal.source_type = 'expense_correction'
         and current_journal.metadata ->> 'expense_id' = expense_row.id::text
       )
     ) then
    raise exception 'The expense is linked to an unrelated journal entry' using errcode = '55000';
  end if;

  perform public.reverse_journal_entry(current_journal.id, correction_date, correction_reason);

  -- The reporting views read posted ledger rows. Keep the source journal
  -- posted alongside its posted reversal so the pair nets to zero and the
  -- replacement journal carries the corrected amount. The reversal remains
  -- linked to the source for audit and deletion cleanup.
  perform set_config('app.financial_workflow', 'authorized', true);
  perform set_config('app.change_reason', correction_reason, true);
  update public.journal_entries
     set status = 'posted',
         reversed_by_id = null,
         updated_at = clock_timestamp(),
         updated_by = (select auth.uid())
   where id = current_journal.id;
  perform set_config('app.financial_workflow', '', true);

  perform set_config('app.financial_workflow', 'authorized', true);
  perform set_config('app.change_reason', correction_reason, true);
  update public.expenses
     set amount = normalized_amount,
         category = coalesce(nullif(trim(p_category), ''), 'Other'),
         description = p_description,
         date = coalesce(p_date, expense_row.date, correction_date),
         receipt_url = p_receipt_url,
         type = normalized_type,
         accounting_state = 'ready_for_posting',
         posting_date = correction_date,
         posting_journal_entry_id = null,
         idempotency_key = correction_id
   where id = expense_row.id
   returning * into expense_row;
  perform set_config('app.financial_workflow', '', true);

  correction_journal := public.create_automatic_journal(
    expense_row.company_id,
    'expense_reimbursement',
    'expense_correction',
    correction_id,
    expense_row.id::text || ':' || correction_id::text,
    correction_date,
    coalesce(p_date, expense_row.date, correction_date),
    coalesce(nullif(trim(expense_row.description), ''), 'Expense'),
    jsonb_build_object('gross', normalized_amount),
    expense_row.currency,
    expense_row.branch_id,
    jsonb_build_object(
      'expense_id', expense_row.id,
      'correction_of_journal_id', current_journal.id,
      'category', expense_row.category,
      'tax_code', expense_row.tax_code
    )
  );

  perform set_config('app.financial_workflow', 'authorized', true);
  perform set_config('app.change_reason', correction_reason, true);
  update public.expenses
     set accounting_state = 'posted',
         posting_journal_entry_id = correction_journal.id,
         idempotency_key = correction_id
   where id = expense_row.id
   returning * into expense_row;
  perform set_config('app.change_reason', '', true);
  perform set_config('app.financial_workflow', '', true);

  return expense_row;
end;
$$;


--
-- Name: correct_expense(uuid, numeric, text, text, date, text, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.correct_expense(p_expense_id uuid, p_amount numeric, p_category text, p_description text, p_date date, p_receipt_url text DEFAULT NULL::text, p_type text DEFAULT 'expense'::text, p_correction_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_payment_method text DEFAULT 'bank'::text) RETURNS public.expenses
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  expense_row public.expenses;
  current_journal public.journal_entries;
  correction_journal public.journal_entries;
  correction_id uuid := coalesce(p_correction_id, gen_random_uuid());
  correction_date date := current_date;
  normalized_amount numeric(20,4) := round(coalesce(p_amount, 0), 4);
  normalized_type text := lower(trim(coalesce(p_type, 'expense')));
  normalized_method text := lower(trim(coalesce(p_payment_method, 'bank')));
  correction_reason text := coalesce(nullif(trim(p_reason), ''), 'Expense corrected');
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_expense_id is null then
    raise exception 'Expense id is required' using errcode = '23514';
  end if;
  if normalized_amount <= 0 then
    raise exception 'Expense amount must be greater than zero' using errcode = '23514';
  end if;
  if normalized_type <> 'expense' then
    raise exception 'Only expense records can use the accounting correction workflow' using errcode = '55000';
  end if;
  if normalized_method not in ('cash', 'bank') then
    raise exception 'Expense payment method must be cash or bank' using errcode = '23514';
  end if;

  select * into expense_row from public.expenses where id = p_expense_id for update;
  if not found then
    raise exception 'Expense not found' using errcode = 'P0002';
  end if;
  if expense_row.company_id is null
     or not coalesce(private.has_company_permission(expense_row.company_id, 'expense.post'), false)
     or not coalesce(private.has_company_permission(expense_row.company_id, 'journal.post'), false)
     or not coalesce(private.has_company_permission(expense_row.company_id, 'journal.reverse'), false) then
    raise exception 'You do not have permission to correct this expense' using errcode = '42501';
  end if;

  select * into correction_journal
    from public.journal_entries
   where company_id = expense_row.company_id
     and source_type = 'expense_correction'
     and source_id = correction_id
     and entry_type = 'automatic';
  if found then
    if correction_journal.metadata ->> 'expense_id' is distinct from expense_row.id::text then
      raise exception 'Correction id is already used for another expense' using errcode = '23505';
    end if;
    return expense_row;
  end if;

  if expense_row.accounting_state <> 'posted' then
    raise exception 'Only posted expenses can be corrected' using errcode = '55000';
  end if;
  if expense_row.posting_journal_entry_id is null then
    raise exception 'The posted expense has no accounting journal' using errcode = '55000';
  end if;

  select * into current_journal
    from public.journal_entries
   where id = expense_row.posting_journal_entry_id
   for update;
  if not found or current_journal.status <> 'posted' then
    raise exception 'The current expense journal is not posted' using errcode = '55000';
  end if;
  if current_journal.entry_type <> 'automatic'
     or not (
       (current_journal.source_type = 'expense' and current_journal.source_id = expense_row.id)
       or (current_journal.source_type = 'expense_correction'
           and current_journal.metadata ->> 'expense_id' = expense_row.id::text)
     ) then
    raise exception 'The expense is linked to an unrelated journal entry' using errcode = '55000';
  end if;

  perform public.reverse_journal_entry(current_journal.id, correction_date, correction_reason);

  -- Reports read posted rows. Keeping the source posted alongside its posted
  -- reversal makes the old transaction net to zero while preserving audit data.
  perform set_config('app.financial_workflow', 'authorized', true);
  perform set_config('app.change_reason', correction_reason, true);
  update public.journal_entries
     set status = 'posted', reversed_by_id = null, updated_at = clock_timestamp(), updated_by = actor_id
   where id = current_journal.id;
  perform set_config('app.financial_workflow', '', true);

  perform set_config('app.financial_workflow', 'authorized', true);
  perform set_config('app.change_reason', correction_reason, true);
  update public.expenses
     set amount = normalized_amount,
         category = coalesce(nullif(trim(p_category), ''), 'Other'),
         description = p_description,
         date = coalesce(p_date, expense_row.date, correction_date),
         receipt_url = p_receipt_url,
         type = normalized_type,
         payment_method = normalized_method,
         accounting_state = 'ready_for_posting',
         posting_date = correction_date,
         posting_journal_entry_id = null,
         idempotency_key = correction_id
   where id = expense_row.id
   returning * into expense_row;
  perform set_config('app.financial_workflow', '', true);

  correction_journal := private.create_expense_payment_journal(
    expense_row.company_id, 'expense_correction', correction_id,
    expense_row.id::text || ':' || correction_id::text,
    correction_date, coalesce(p_date, expense_row.date, correction_date),
    coalesce(nullif(trim(expense_row.description), ''), 'Expense'),
    normalized_amount, expense_row.currency, expense_row.branch_id,
    normalized_method, jsonb_build_object(
      'expense_id', expense_row.id,
      'correction_of_journal_id', current_journal.id,
      'category', expense_row.category,
      'tax_code', expense_row.tax_code
    )
  );

  perform set_config('app.financial_workflow', 'authorized', true);
  perform set_config('app.change_reason', correction_reason, true);
  update public.expenses
     set accounting_state = 'posted', posting_journal_entry_id = correction_journal.id,
         idempotency_key = correction_id
   where id = expense_row.id
   returning * into expense_row;
  perform set_config('app.change_reason', '', true);
  perform set_config('app.financial_workflow', '', true);
  return expense_row;
end;
$$;


--
-- Name: correct_expense(uuid, numeric, text, text, date, uuid, text, text, text, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.correct_expense(p_expense_id uuid, p_amount numeric, p_category text, p_description text, p_date date, p_company_bank_account_id uuid, p_vendor_name text, p_invoice_number text, p_receipt_url text DEFAULT NULL::text, p_type text DEFAULT 'expense'::text, p_correction_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_payment_method text DEFAULT 'bank'::text) RETURNS public.expenses
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  expense_row public.expenses;
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  select * into expense_row from public.expenses where id = p_expense_id for update;
  if not found then
    raise exception 'Expense not found' using errcode = 'P0002';
  end if;
  if expense_row.company_id is null
     or not coalesce(private.has_company_permission(expense_row.company_id, 'expense.post'), false)
     or not coalesce(private.has_company_permission(expense_row.company_id, 'journal.post'), false)
     or not coalesce(private.has_company_permission(expense_row.company_id, 'journal.reverse'), false) then
    raise exception 'You do not have permission to correct this expense' using errcode = '42501';
  end if;

  perform set_config('app.financial_workflow', 'authorized', true);
  perform set_config('app.change_reason', coalesce(nullif(trim(p_reason), ''), 'Expense metadata corrected'), true);
  update public.expenses
     set vendor_name = nullif(trim(p_vendor_name), ''),
         invoice_number = nullif(trim(p_invoice_number), ''),
         payment_method = lower(trim(coalesce(p_payment_method, 'bank'))),
         company_bank_account_id = p_company_bank_account_id
   where id = p_expense_id;
  perform set_config('app.change_reason', '', true);
  perform set_config('app.financial_workflow', '', true);

  -- The legacy ten-argument correction function rebuilds the journal through
  -- the private helper but does not receive the new bank-account argument.
  -- Keep the selected bank available for that nested call without changing
  -- the existing RPC signature.
  perform set_config('app.expense_bank_account_id', coalesce(p_company_bank_account_id::text, ''), true);
  expense_row := public.correct_expense(
    p_expense_id,
    p_amount,
    p_category,
    p_description,
    p_date,
    p_receipt_url,
    p_type,
    p_correction_id,
    p_reason,
    p_payment_method
  );
  perform set_config('app.expense_bank_account_id', '', true);
  return expense_row;
end;
$$;


--
-- Name: correct_expense(uuid, numeric, text, text, date, uuid, text, text, text, text, text, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.correct_expense(p_expense_id uuid, p_amount numeric, p_category text, p_description text, p_date date, p_company_bank_account_id uuid, p_vendor_name text, p_invoice_number text, p_bank_reference text, p_notes text, p_receipt_url text DEFAULT NULL::text, p_type text DEFAULT 'expense'::text, p_correction_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_payment_method text DEFAULT 'bank'::text) RETURNS public.expenses
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
