--
-- Name: correct_expense_with_vat(uuid, numeric, text, text, text, date, uuid, uuid, text, text, text, text, numeric, numeric, numeric, text, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.correct_expense_with_vat(p_expense_id uuid, p_amount numeric, p_category text, p_article text, p_description text, p_date date, p_company_bank_account_id uuid, p_vendor_id uuid, p_vendor_name text, p_invoice_number text, p_bank_reference text, p_notes text, p_vat_rate numeric, p_tax_amount numeric, p_tax_recoverable_amount numeric, p_receipt_url text DEFAULT NULL::text, p_type text DEFAULT 'expense'::text, p_correction_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_payment_method text DEFAULT 'bank'::text) RETURNS public.expenses
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  expense_row public.expenses;
  corrected_row public.expenses;
begin
  if actor_id is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if coalesce(p_vat_rate, 0) < 0 or coalesce(p_vat_rate, 0) > 100
     or coalesce(p_tax_amount, 0) < 0
     or coalesce(p_tax_recoverable_amount, 0) < 0
     or coalesce(p_tax_amount, 0) > coalesce(p_amount, 0)
     or coalesce(p_tax_recoverable_amount, 0) > coalesce(p_tax_amount, 0) then
    raise exception 'Expense VAT amounts are invalid' using errcode = '23514';
  end if;

  select * into expense_row from public.expenses where id = p_expense_id for update;
  if not found then raise exception 'Expense not found' using errcode = 'P0002'; end if;
  if not coalesce(private.has_company_permission(expense_row.company_id, 'expense.post'), false)
     or not coalesce(private.has_company_permission(expense_row.company_id, 'journal.post'), false)
     or not coalesce(private.has_company_permission(expense_row.company_id, 'journal.reverse'), false) then
    raise exception 'You do not have permission to correct this expense' using errcode = '42501';
  end if;

  perform set_config('app.financial_workflow', 'authorized', true);
  perform set_config('app.change_reason', coalesce(nullif(trim(p_reason), ''), 'Expense details corrected'), true);
  update public.expenses
     set article = nullif(trim(p_article), ''),
         vendor_id = p_vendor_id,
         vat_rate = round(coalesce(p_vat_rate, 0), 4),
         tax_amount = round(coalesce(p_tax_amount, 0), 4),
         tax_recoverable_amount = round(coalesce(p_tax_recoverable_amount, 0), 4)
   where id = p_expense_id;

  corrected_row := public.correct_expense(
    p_expense_id => p_expense_id,
    p_amount => p_amount,
    p_category => p_category,
    p_description => p_description,
    p_date => p_date,
    p_company_bank_account_id => p_company_bank_account_id,
    p_vendor_name => p_vendor_name,
    p_invoice_number => p_invoice_number,
    p_bank_reference => p_bank_reference,
    p_notes => p_notes,
    p_receipt_url => p_receipt_url,
    p_type => p_type,
    p_correction_id => p_correction_id,
    p_reason => p_reason,
    p_payment_method => p_payment_method
  );
  perform set_config('app.change_reason', '', true);
  perform set_config('app.financial_workflow', '', true);
  return corrected_row;
end;
$$;


--
-- Name: agent_advances; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_advances (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    agent_user_id uuid NOT NULL,
    fund_account_id uuid NOT NULL,
    amount numeric(20,4) NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    advance_date date DEFAULT CURRENT_DATE NOT NULL,
    description text,
    idempotency_key uuid,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    reversed_at timestamp with time zone,
    reversed_by uuid,
    CONSTRAINT agent_advances_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT agent_advances_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT agent_advances_status_check CHECK ((status = ANY (ARRAY['active'::text, 'reversed'::text])))
);


--
-- Name: create_agent_advance(uuid, uuid, uuid, numeric, date, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_agent_advance(p_company_id uuid, p_agent_user_id uuid, p_fund_account_id uuid, p_amount numeric, p_advance_date date DEFAULT CURRENT_DATE, p_description text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.agent_advances
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  fund_row public.company_fund_accounts;
  advance_row public.agent_advances;
  advance_amount numeric(20,4) := round(coalesce(p_amount, 0), 4);
  current_balance numeric(20,4) := 0;
begin
  if actor_id is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if p_company_id is null or not public.can_access_company(p_company_id) then
    raise exception 'The selected tenant is not accessible' using errcode = '42501';
  end if;
  if not coalesce(private.has_company_permission(p_company_id, 'cash_transaction.post'), false) then
    raise exception 'Insufficient permission to record an agent advance' using errcode = '42501';
  end if;
  if not exists (select 1 from public.memberships membership where membership.company_id = p_company_id
    and membership.user_id = p_agent_user_id and coalesce(membership.status, 'active') <> 'revoked') then
    raise exception 'The selected user is not an agent for this tenant' using errcode = '23503';
  end if;
  if advance_amount <= 0 then raise exception 'Advance amount must be greater than zero' using errcode = '23514'; end if;

  select * into fund_row from public.company_fund_accounts
   where id = p_fund_account_id and company_id = p_company_id and is_active for update;
  if not found then raise exception 'The selected cash or bank account is not active' using errcode = '23503'; end if;
  if fund_row.fund_type not in ('cash', 'bank') or fund_row.stripe_store_id is not null then
    raise exception 'Agent advances can only use cash or bank accounts' using errcode = '23514';
  end if;
  if not private.can_view_fund_account(fund_row.id) then raise exception 'The selected cash or bank account is not accessible' using errcode = '42501'; end if;

  if p_idempotency_key is not null then
    select * into advance_row from public.agent_advances where idempotency_key = p_idempotency_key for update;
    if found then return advance_row; end if;
  end if;

  select fund_row.opening_balance + coalesce(sum(transaction.signed_amount), 0)
    into current_balance from public.company_fund_transactions transaction
   where transaction.fund_account_id = fund_row.id and transaction.status = 'active';
  if current_balance < advance_amount then raise exception 'Insufficient funds for this agent advance' using errcode = '23514'; end if;

  insert into public.agent_advances (company_id, agent_user_id, fund_account_id, amount, currency, advance_date, description, idempotency_key, created_by)
  values (p_company_id, p_agent_user_id, fund_row.id, advance_amount, fund_row.currency, coalesce(p_advance_date, current_date), nullif(trim(p_description), ''), p_idempotency_key, actor_id)
  returning * into advance_row;

  insert into public.company_fund_transactions (company_id, source_company_id, fund_account_id, transaction_type, signed_amount, currency, transaction_date, description, source_type, source_id, created_by)
  values (p_company_id, p_company_id, fund_row.id, 'expense', -advance_amount, fund_row.currency, coalesce(p_advance_date, current_date), coalesce(nullif(trim(p_description), ''), 'Agent advance'), 'agent_advance', advance_row.id, actor_id);
  return advance_row;
end;
$$;


--
-- Name: agent_settlements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_settlements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    agent_user_id uuid NOT NULL,
    fund_account_id uuid NOT NULL,
    amount numeric(20,4) NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    settlement_date date DEFAULT CURRENT_DATE NOT NULL,
    description text,
    idempotency_key uuid,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    reversed_at timestamp with time zone,
    reversed_by uuid,
    CONSTRAINT agent_settlements_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT agent_settlements_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT agent_settlements_status_check CHECK ((status = ANY (ARRAY['active'::text, 'reversed'::text])))
);


--
-- Name: create_agent_settlement(uuid, uuid, uuid, numeric, date, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_agent_settlement(p_company_id uuid, p_agent_user_id uuid, p_fund_account_id uuid, p_amount numeric, p_settlement_date date DEFAULT CURRENT_DATE, p_description text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.agent_settlements
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  fund_row public.company_fund_accounts;
  settlement_row public.agent_settlements;
  sales_total numeric(20,4) := 0;
  advance_total numeric(20,4) := 0;
  settled_total numeric(20,4) := 0;
  outstanding_total numeric(20,4) := 0;
  settlement_amount numeric(20,4) := round(coalesce(p_amount, 0), 4);
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_company_id is null or not public.can_access_company(p_company_id) then
    raise exception 'The selected tenant is not accessible' using errcode = '42501';
  end if;
  if not coalesce(private.has_company_permission(p_company_id, 'cash_transaction.post'), false) then
    raise exception 'Insufficient permission to settle an agent balance' using errcode = '42501';
  end if;
  if not exists (
    select 1
      from public.memberships membership
     where membership.company_id = p_company_id
       and membership.user_id = p_agent_user_id
       and coalesce(membership.status, 'active') <> 'revoked'
  ) then
    raise exception 'The selected user is not an agent for this tenant' using errcode = '23503';
  end if;
  if settlement_amount <= 0 then
    raise exception 'Settlement amount must be greater than zero' using errcode = '23514';
  end if;

  -- Keep the selected destination for the internal audit trail, but do not
  -- change its balance because the money is already in the books.
  select * into fund_row
    from public.company_fund_accounts
   where id = p_fund_account_id and is_active
   for update;
  if not found then
    raise exception 'The selected cash or bank account is not active' using errcode = '23503';
  end if;
  if fund_row.fund_type not in ('cash', 'bank') or fund_row.stripe_store_id is not null then
    raise exception 'Agent settlements can only use cash or bank accounts' using errcode = '23514';
  end if;
  if not private.can_view_fund_account(fund_row.id) then
    raise exception 'The selected cash or bank account is not accessible' using errcode = '42501';
  end if;

  if p_idempotency_key is not null then
    select * into settlement_row
      from public.agent_settlements
     where idempotency_key = p_idempotency_key
     for update;
    if found then return settlement_row; end if;
  end if;

  -- Prevent two simultaneous taps from settling more than the agent has sold.
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text || ':' || p_agent_user_id::text, 0));

  select coalesce(sum(invoice.total_amount), 0)::numeric(20,4)
    into sales_total
    from public.invoices invoice
   where invoice.company_id = p_company_id
     and invoice.user_id = p_agent_user_id
     and invoice.accounting_state = 'posted'
     and lower(coalesce(invoice.payment_method, '')) = 'cash'
     and lower(coalesce(invoice.type, '')) in ('invoice', 'final_invoice', 'advance_invoice', 'simplified_invoice')
     and lower(coalesce(invoice.status::text, '')) not in ('cancelled', 'credited', 'reversed');

  select coalesce(sum(settlement.amount), 0)::numeric(20,4)
    into settled_total
    from public.agent_settlements settlement
   where settlement.company_id = p_company_id
     and settlement.agent_user_id = p_agent_user_id
     and settlement.status = 'active';

  select coalesce(sum(advance.amount), 0)::numeric(20,4)
    into advance_total
    from public.agent_advances advance
   where advance.company_id = p_company_id
     and advance.agent_user_id = p_agent_user_id
     and advance.status = 'active';

  outstanding_total := greatest(sales_total + advance_total - settled_total, 0);
  if settlement_amount > outstanding_total + 0.0001 then
    raise exception 'Settlement amount exceeds the agent balance' using errcode = '23514';
  end if;

  insert into public.agent_settlements (
    company_id, agent_user_id, fund_account_id, amount, currency,
    settlement_date, description, idempotency_key, created_by
  ) values (
    p_company_id, p_agent_user_id, fund_row.id, settlement_amount, fund_row.currency,
    coalesce(p_settlement_date, current_date), nullif(trim(p_description), ''),
    p_idempotency_key, actor_id
  ) returning * into settlement_row;

  return settlement_row;
end;
$$;


--
-- Name: create_automatic_journal(uuid, text, text, uuid, text, date, date, text, jsonb, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_automatic_journal(p_company_id uuid, p_event_type text, p_source_type text, p_source_id uuid, p_source_key text, p_posting_date date, p_document_date date, p_description text, p_amounts jsonb, p_currency text DEFAULT 'EUR'::text, p_branch_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS public.journal_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  rule_set public.posting_rule_sets;
  entry_row public.journal_entries;
  rule_line record;
  amount_value numeric(20, 4);
  line_counter integer := 0;
begin
  if not (select private.has_company_permission(p_company_id, 'journal.post')) then
    raise exception 'Insufficient permission to create automatic journals' using errcode = '42501';
  end if;
  if jsonb_typeof(coalesce(p_amounts, '{}'::jsonb)) <> 'object' then
    raise exception 'Posting amounts must be a JSON object' using errcode = '22023';
  end if;

  select * into rule_set
  from public.posting_rule_sets
  where company_id = p_company_id
    and event_type = p_event_type
    and active
    and effective_from <= p_posting_date
    and (effective_until is null or effective_until >= p_posting_date)
  order by version desc, effective_from desc
  limit 1;
  if not found then
    raise exception 'No effective posting rule exists for event %', p_event_type using errcode = 'P0002';
  end if;

  entry_row := public.create_journal_entry(
    p_company_id, p_posting_date, p_document_date, p_description,
    p_source_key, p_currency, 1, p_branch_id, 'automatic'
  );
  update public.journal_entries
  set
    source_type = p_source_type,
    source_id = p_source_id,
    source_key = p_source_key,
    metadata = coalesce(p_metadata, '{}'::jsonb),
    updated_by = (select auth.uid())
  where id = entry_row.id
  returning * into entry_row;

  for rule_line in
    select *
    from public.posting_rule_lines
    where rule_set_id = rule_set.id
    order by line_number
  loop
    amount_value := round(coalesce((p_amounts ->> rule_line.amount_component)::numeric, 0), 4);
    if amount_value <> 0 then
      line_counter := line_counter + 1;
      insert into public.journal_entry_lines (
        journal_entry_id, company_id, line_number, account_id, description,
        debit, credit, transaction_currency, transaction_amount,
        cost_centre_id, project_id, branch_id, metadata, created_by
      )
      values (
        entry_row.id, p_company_id, line_counter, rule_line.account_id,
        coalesce(rule_line.description_template, p_description),
        case when rule_line.side = 'debit' then abs(amount_value) else 0 end,
        case when rule_line.side = 'credit' then abs(amount_value) else 0 end,
        upper(p_currency), amount_value, rule_line.cost_centre_id,
        rule_line.project_id, p_branch_id, rule_line.condition, (select auth.uid())
      );
    end if;
  end loop;
  return public.post_journal_entry(entry_row.id, 'Automatic posting: ' || p_event_type);
exception
  when unique_violation then
    select * into entry_row
    from public.journal_entries
    where company_id = p_company_id
      and source_type = p_source_type
      and source_id = p_source_id
      and entry_type = 'automatic';
    if found then
      return entry_row;
    end if;
    raise;
end
$$;


--
-- Name: create_bank_reconciliation(uuid, date, date, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_bank_reconciliation(p_company_bank_account_id uuid, p_period_start date, p_period_end date, p_opening_balance numeric DEFAULT 0, p_notes text DEFAULT NULL::text) RETURNS public.bank_reconciliations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare account_row public.company_bank_accounts; result public.bank_reconciliations;
begin
  select * into account_row from public.company_bank_accounts where id=p_company_bank_account_id and is_active for update;
  if not found then raise exception 'Bank account not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(account_row.company_id,'bank.reconcile')) then raise exception 'Insufficient permission to reconcile bank account' using errcode='42501'; end if;
  insert into public.bank_reconciliations(company_id,company_bank_account_id,period_start,period_end,opening_balance,notes,created_by)
  values(account_row.company_id,p_company_bank_account_id,p_period_start,p_period_end,round(coalesce(p_opening_balance,0),4),p_notes,(select auth.uid()))
  on conflict(company_bank_account_id,period_start,period_end) do update set status='reopened',notes=excluded.notes
  returning * into result;
  return result;
end
$$;


--
-- Name: create_company_and_owner(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_company_and_owner(p_company_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  new_company_id uuid;
  current_user_id uuid := (select auth.uid());
begin
  if current_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if nullif(trim(p_company_name), '') is null then
    raise exception 'Company name is required' using errcode = '23514';
  end if;

  insert into public.companies (company_name, owner_id)
  values (trim(p_company_name), current_user_id)
  returning id into new_company_id;

  insert into public.memberships (user_id, company_id, role, status)
  values (current_user_id, new_company_id, 'owner', 'active');

  insert into public.company_app_entitlements (
    company_id,
    app_key,
    enabled,
    enabled_at,
    updated_by
  )
  values (new_company_id, 'invoice', true, clock_timestamp(), current_user_id)
  on conflict (company_id, app_key) do update
    set enabled = true,
        enabled_at = excluded.enabled_at,
        disabled_at = null,
        updated_at = clock_timestamp(),
        updated_by = excluded.updated_by;

  perform public.initialize_company_accounting(
    new_company_id,
    date_trunc('year', current_date)::date,
    'xk-operix-base-v1'
  );

  insert into public.profiles (id, email)
  select current_user_id, email
  from auth.users
  where id = current_user_id
  on conflict (id) do nothing;

  perform set_config('app.company_link_workflow', 'authorized', true);
  perform set_config('app.active_company_switch', 'authorized', true);
  update public.profiles
  set company_id = new_company_id,
      active_company_id = new_company_id,
      company_name = trim(p_company_name),
      updated_at = clock_timestamp()
  where id = current_user_id;
  perform set_config('app.company_link_workflow', '', true);
  perform set_config('app.active_company_switch', '', true);

  return jsonb_build_object(
    'id', new_company_id,
    'company_name', trim(p_company_name)
  );
end
$$;


