  raise exception 'Use the billing-aware Users & Access invitation workflow' using errcode = '42501';
end;
$$;


--
-- Name: create_company_subdivision(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_company_subdivision(p_parent_company_id uuid, p_company_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  current_user_id uuid := (select auth.uid());
  new_company_id uuid;
  parent_name text;
begin
  if current_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if p_parent_company_id is null then
    raise exception 'Parent company is required' using errcode = '23514';
  end if;

  if nullif(trim(p_company_name), '') is null then
    raise exception 'Company name is required' using errcode = '23514';
  end if;

  if not private.has_company_permission(p_parent_company_id, 'company.manage') then
    raise exception 'You do not have permission to add a subdivision'
      using errcode = '42501';
  end if;

  select company.company_name
    into parent_name
  from public.companies company
  where company.id = p_parent_company_id;

  if parent_name is null then
    raise exception 'Parent company was not found' using errcode = '22023';
  end if;

  insert into public.companies (company_name, owner_id, parent_company_id)
  values (trim(p_company_name), current_user_id, p_parent_company_id)
  returning id into new_company_id;

  insert into public.memberships (user_id, company_id, role, status)
  values (current_user_id, new_company_id, 'owner', 'active');

  perform public.initialize_company_accounting(
    new_company_id,
    date_trunc('year', current_date)::date,
    'xk-operix-base-v1'
  );

  return jsonb_build_object(
    'id', new_company_id,
    'company_name', trim(p_company_name),
    'parent_company_id', p_parent_company_id,
    'parent_company_name', parent_name
  );
end
$$;


--
-- Name: create_expense_with_posting(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_expense_with_posting(p_expense jsonb, p_idempotency_key uuid) RETURNS public.expenses
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  company_id_value uuid := nullif(p_expense ->> 'company_id', '')::uuid;
  expense_row public.expenses;
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if company_id_value is null or not public.can_access_company(company_id_value) then
    raise exception 'The expense company is not available to this user' using errcode = '42501';
  end if;
  if p_idempotency_key is null then
    raise exception 'Expense idempotency key is required' using errcode = '23514';
  end if;
  if not private.has_company_permission(company_id_value, 'expense.post')
     or not private.has_company_permission(company_id_value, 'journal.post') then
    raise exception 'Insufficient permission to post expenses' using errcode = '42501';
  end if;
  if coalesce((p_expense ->> 'amount')::numeric, 0) <= 0 then
    raise exception 'Expense amount must be greater than zero' using errcode = '23514';
  end if;

  select * into expense_row
  from public.expenses
  where company_id = company_id_value
    and idempotency_key = p_idempotency_key
  for update;
  if found then
    return expense_row;
  end if;

  insert into public.expenses (
    user_id, company_id, vendor_name, category, description, amount,
    currency, date, receipt_url, idempotency_key, accounting_state
  ) values (
    actor_id,
    company_id_value,
    nullif(trim(p_expense ->> 'vendor_name'), ''),
    coalesce(nullif(trim(p_expense ->> 'category'), ''), 'Other'),
    nullif(trim(p_expense ->> 'description'), ''),
    round((p_expense ->> 'amount')::numeric, 4),
    upper(coalesce(nullif(trim(p_expense ->> 'currency'), ''), 'EUR')),
    coalesce(nullif(p_expense ->> 'date', '')::date, current_date),
    nullif(trim(p_expense ->> 'receipt_url'), ''),
    p_idempotency_key,
    'ready_for_posting'
  ) returning * into expense_row;

  return public.post_expense(
    expense_row.id,
    p_idempotency_key,
    'OperiX AI confirmed expense'
  );
end;
$$;


--
-- Name: company_fund_accounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.company_fund_accounts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    fund_type text NOT NULL,
    company_bank_account_id uuid,
    name text NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    opening_balance numeric(20,4) DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    stripe_store_id uuid,
    account_type text DEFAULT 'other'::text NOT NULL,
    notes text,
    CONSTRAINT company_fund_accounts_account_type_check CHECK ((account_type = ANY (ARRAY['cash'::text, 'bank'::text, 'card_clearing'::text, 'online_clearing'::text, 'other'::text]))),
    CONSTRAINT company_fund_accounts_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT company_fund_accounts_fund_type_check CHECK ((fund_type = ANY (ARRAY['cash'::text, 'bank'::text, 'card_clearing'::text, 'online_clearing'::text, 'other'::text]))),
    CONSTRAINT company_fund_accounts_type_relation_check CHECK ((((fund_type = 'cash'::text) AND (company_bank_account_id IS NULL) AND (stripe_store_id IS NULL)) OR ((fund_type = 'bank'::text) AND (((company_bank_account_id IS NOT NULL) AND (stripe_store_id IS NULL)) OR ((company_bank_account_id IS NULL) AND (stripe_store_id IS NOT NULL)))) OR (fund_type = ANY (ARRAY['card_clearing'::text, 'online_clearing'::text, 'other'::text]))))
);


--
-- Name: create_financial_account(uuid, text, text, text, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_financial_account(p_company_id uuid, p_name text, p_account_type text, p_currency text DEFAULT 'EUR'::text, p_company_bank_account_id uuid DEFAULT NULL::uuid, p_opening_balance numeric DEFAULT 0, p_notes text DEFAULT NULL::text) RETURNS public.company_fund_accounts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare account_row public.company_fund_accounts; bank_row public.company_bank_accounts; account_kind text := lower(trim(coalesce(p_account_type,'')));
begin
  if not private.has_company_permission(p_company_id,'cash_account.manage') then raise exception 'Insufficient permission to manage financial accounts' using errcode='42501'; end if;
  if nullif(trim(p_name),'') is null or account_kind not in ('cash','bank','card_clearing','online_clearing','other') then raise exception 'Account name and type are required' using errcode='23514'; end if;
  if p_opening_balance is null or p_opening_balance < 0 then raise exception 'Opening balance must be zero or greater' using errcode='23514'; end if;
  if account_kind='cash' and p_company_bank_account_id is not null then raise exception 'Cash accounts cannot reference a bank account' using errcode='23514'; end if;
  if account_kind='bank' and p_company_bank_account_id is null then raise exception 'Bank accounts require a bank account record' using errcode='23514'; end if;
  if p_company_bank_account_id is not null then
    select * into bank_row from public.company_bank_accounts
     where id=p_company_bank_account_id and is_active
       and (company_id=p_company_id or private.can_access_company_bank_account(id));
    if not found or upper(bank_row.currency) <> upper(coalesce(p_currency,'EUR')) then raise exception 'Bank account is invalid or has a different currency' using errcode='23514'; end if;
  end if;
  perform set_config('app.change_reason',coalesce(nullif(trim(p_notes),''),'Financial account created'),true);
  insert into public.company_fund_accounts(company_id,fund_type,account_type,company_bank_account_id,name,currency,opening_balance,notes,created_by,updated_by)
  values(p_company_id,account_kind,account_kind,p_company_bank_account_id,trim(p_name),upper(coalesce(p_currency,'EUR')),round(p_opening_balance,4),nullif(trim(p_notes),''),(select auth.uid()),(select auth.uid()))
  returning * into account_row;
  perform set_config('app.change_reason','',true);
  return account_row;
end;
$$;


--
-- Name: financial_adjustments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.financial_adjustments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    fund_account_id uuid NOT NULL,
    adjustment_date date NOT NULL,
    amount numeric(20,4) NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    reason text NOT NULL,
    status text DEFAULT 'posted'::text NOT NULL,
    idempotency_key uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT financial_adjustments_amount_check CHECK ((amount <> (0)::numeric)),
    CONSTRAINT financial_adjustments_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT financial_adjustments_status_check CHECK ((status = ANY (ARRAY['posted'::text, 'reversed'::text])))
);


--
-- Name: create_fund_adjustment(uuid, numeric, date, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_fund_adjustment(p_fund_account_id uuid, p_amount numeric, p_adjustment_date date, p_reason text, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.financial_adjustments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare fund_row public.company_fund_accounts; adjustment_row public.financial_adjustments; period_row public.accounting_periods;
begin
  select * into fund_row from public.company_fund_accounts where id=p_fund_account_id and is_active for update;
  if not found then raise exception 'Financial account is not active' using errcode='23503'; end if;
  if not private.has_company_permission(fund_row.company_id,'cash_transaction.post') then raise exception 'Insufficient permission to post financial adjustments' using errcode='42501'; end if;
  if p_amount is null or round(p_amount,4)=0 or nullif(trim(p_reason),'') is null or p_adjustment_date is null then raise exception 'Adjustment date, non-zero amount, and reason are required' using errcode='23514'; end if;
  if p_idempotency_key is not null then select * into adjustment_row from public.financial_adjustments where company_id=fund_row.company_id and idempotency_key=p_idempotency_key for update; if found then return adjustment_row; end if; end if;
  select * into period_row from public.accounting_periods where company_id=fund_row.company_id and p_adjustment_date between start_date and end_date for update;
  if not found or period_row.status <> 'open' then raise exception 'Financial adjustments are not allowed in a closed period' using errcode='55000'; end if;
  perform set_config('app.change_reason',trim(p_reason),true);
  insert into public.financial_adjustments(company_id,fund_account_id,adjustment_date,amount,currency,reason,idempotency_key,created_by)
  values(fund_row.company_id,fund_row.id,p_adjustment_date,round(p_amount,4),fund_row.currency,trim(p_reason),p_idempotency_key,(select auth.uid())) returning * into adjustment_row;
  perform set_config('app.change_reason','',true);
  return adjustment_row;
end;
$$;


--
-- Name: company_fund_transfers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.company_fund_transfers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    source_fund_account_id uuid NOT NULL,
    target_fund_account_id uuid NOT NULL,
    amount numeric(20,4) NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    transfer_date date DEFAULT CURRENT_DATE NOT NULL,
    description text,
    idempotency_key uuid,
    status text DEFAULT 'posted'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT company_fund_transfers_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT company_fund_transfers_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT company_fund_transfers_different_accounts CHECK ((source_fund_account_id <> target_fund_account_id)),
    CONSTRAINT company_fund_transfers_status_check CHECK ((status = ANY (ARRAY['posted'::text, 'reversed'::text])))
);


--
-- Name: create_fund_transfer(uuid, uuid, numeric, date, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_fund_transfer(p_source_fund_account_id uuid, p_target_fund_account_id uuid, p_amount numeric, p_transfer_date date DEFAULT CURRENT_DATE, p_description text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.company_fund_transfers
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  source_fund public.company_fund_accounts;
  target_fund public.company_fund_accounts;
  transfer_row public.company_fund_transfers;
  current_balance numeric(20,4);
  transfer_amount numeric(20,4) := round(coalesce(p_amount, 0), 4);
begin
  if p_idempotency_key is not null then
    select * into transfer_row from public.company_fund_transfers
     where idempotency_key = p_idempotency_key for update;
    if found then return transfer_row; end if;
  end if;

  select * into source_fund from public.company_fund_accounts
   where id = p_source_fund_account_id and is_active for update;
  select * into target_fund from public.company_fund_accounts
   where id = p_target_fund_account_id and is_active for update;
  if not found or source_fund.id is null or target_fund.id is null then
    raise exception 'Both fund accounts must be active' using errcode = '23503';
  end if;
  if source_fund.company_id <> target_fund.company_id then
    raise exception 'Fund accounts must belong to the same company' using errcode = '23514';
  end if;
  if not coalesce(private.has_company_permission(source_fund.company_id, 'cash_transaction.post'), false) then
    raise exception 'Insufficient permission to transfer funds' using errcode = '42501';
  end if;
  if transfer_amount <= 0 then raise exception 'Transfer amount must be greater than zero' using errcode = '23514'; end if;
  if source_fund.currency <> target_fund.currency then raise exception 'Fund currencies must match' using errcode = '23514'; end if;

  select source_fund.opening_balance + coalesce(sum(fund_tx.signed_amount) filter (where fund_tx.status = 'active'), 0)
    into current_balance
    from public.company_fund_transactions fund_tx
   where fund_tx.fund_account_id = source_fund.id;
  if current_balance < transfer_amount then
    raise exception 'The source fund does not have enough money' using errcode = '23514';
  end if;

  insert into public.company_fund_transfers (
    company_id, source_fund_account_id, target_fund_account_id, amount, currency,
    transfer_date, description, idempotency_key, created_by
  ) values (
    source_fund.company_id, source_fund.id, target_fund.id, transfer_amount,
    source_fund.currency, coalesce(p_transfer_date, current_date),
    nullif(trim(p_description), ''), p_idempotency_key, (select auth.uid())
  ) returning * into transfer_row;

  insert into public.company_fund_transactions (
    company_id, source_company_id, fund_account_id, transaction_type, signed_amount,
    currency, transaction_date, description, source_type, source_id, created_by
  ) values
    (source_fund.company_id, source_fund.company_id, source_fund.id, 'transfer_out', -transfer_amount,
     source_fund.currency, transfer_row.transfer_date, transfer_row.description,
     'fund_transfer', transfer_row.id, (select auth.uid())),
    (target_fund.company_id, target_fund.company_id, target_fund.id, 'transfer_in', transfer_amount,
     target_fund.currency, transfer_row.transfer_date, transfer_row.description,
     'fund_transfer', transfer_row.id, (select auth.uid()));
  return transfer_row;
end;
$$;


--
-- Name: inventory_counts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inventory_counts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    location_id uuid,
    count_date date NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    finalized_at timestamp with time zone,
    finalized_by uuid,
    CONSTRAINT inventory_counts_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'finalized'::text, 'cancelled'::text])))
);


--
-- Name: create_inventory_count(uuid, date, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_inventory_count(p_company_id uuid, p_count_date date, p_location_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS public.inventory_counts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result public.inventory_counts;
begin
  if not (select private.has_company_permission(p_company_id,'inventory.manage')) then raise exception 'Insufficient permission to create inventory count' using errcode='42501'; end if;
  insert into public.inventory_counts(company_id,location_id,count_date,notes,created_by)
  values(p_company_id,p_location_id,coalesce(p_count_date,current_date),p_notes,(select auth.uid())) returning * into result;
  return result;
end
$$;


--
-- Name: create_journal_entry(uuid, date, date, text, text, text, numeric, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_journal_entry(p_company_id uuid, p_posting_date date, p_document_date date, p_description text, p_reference text DEFAULT NULL::text, p_currency text DEFAULT 'EUR'::text, p_exchange_rate numeric DEFAULT 1, p_branch_id uuid DEFAULT NULL::uuid, p_entry_type text DEFAULT 'manual'::text) RETURNS public.journal_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  created public.journal_entries;
begin
  if not (select private.has_company_permission(p_company_id, 'journal.create')) then
    raise exception 'Insufficient permission to create journals' using errcode = '42501';
  end if;
  if trim(coalesce(p_description, '')) = '' then
    raise exception 'Journal description is required' using errcode = '23514';
  end if;
  insert into public.journal_entries (
    company_id, branch_id, entry_number, entry_type, posting_date, document_date,
    description, reference, currency, exchange_rate, created_by, updated_by
  )
  values (
    p_company_id, p_branch_id, private.next_journal_number(p_company_id, p_posting_date),
    p_entry_type, p_posting_date, p_document_date, trim(p_description), p_reference,
    upper(p_currency), p_exchange_rate, (select auth.uid()), (select auth.uid())
  )
  returning * into created;
  return created;
end
$$;


--
-- Name: offline_sync_batches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.offline_sync_batches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    device_registration_id uuid NOT NULL,
    terminal_id uuid NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    item_count integer DEFAULT 0 NOT NULL,
    completed_count integer DEFAULT 0 NOT NULL,
    conflict_count integer DEFAULT 0 NOT NULL,
    failed_count integer DEFAULT 0 NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    created_by uuid,
    CONSTRAINT offline_sync_batches_completed_count_check CHECK ((completed_count >= 0)),
    CONSTRAINT offline_sync_batches_conflict_count_check CHECK ((conflict_count >= 0)),
    CONSTRAINT offline_sync_batches_failed_count_check CHECK ((failed_count >= 0)),
    CONSTRAINT offline_sync_batches_item_count_check CHECK ((item_count >= 0)),
    CONSTRAINT offline_sync_batches_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'processing'::text, 'partially_completed'::text, 'completed'::text, 'failed'::text])))
);


--
-- Name: create_offline_sync_batch(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_offline_sync_batch(p_company_id uuid, p_device_registration_id uuid) RETURNS public.offline_sync_batches
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  device_row public.device_registrations;
  batch_row public.offline_sync_batches;
begin
  if not (select private.has_company_permission(p_company_id, 'pos.offline.use')) then
    raise exception 'Insufficient permission to synchronize offline POS sales' using errcode = '42501';
  end if;
  if not coalesce((
    select enabled from public.company_feature_flags
    where company_id = p_company_id and flag = 'offline_pos_enabled'
  ), false) then
    raise exception 'Offline POS is not enabled for this company' using errcode = '55000';
  end if;
  select * into device_row
  from public.device_registrations
  where id = p_device_registration_id and company_id = p_company_id
  for update;
  if not found or device_row.status <> 'active' then
    raise exception 'An active registered POS device is required' using errcode = '42501';
  end if;

  insert into public.offline_sync_batches (
    company_id, device_registration_id, terminal_id, created_by
  )
  values (p_company_id, device_row.id, device_row.terminal_id, (select auth.uid()))
  returning * into batch_row;
  return batch_row;
end
$$;


--
-- Name: other_income_categories; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.other_income_categories (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid,
    category_key text NOT NULL,
    name_en text NOT NULL,
    name_sq text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid
);


--
-- Name: create_other_income_category(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_other_income_category(p_company_id uuid, p_category_key text, p_name_en text, p_name_sq text) RETURNS public.other_income_categories
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare category_row public.other_income_categories;
begin
  if not private.has_company_permission(p_company_id,'other_income.edit') then raise exception 'Insufficient permission to manage income categories' using errcode='42501'; end if;
  if nullif(trim(p_category_key),'') is null or nullif(trim(p_name_en),'') is null or nullif(trim(p_name_sq),'') is null then raise exception 'Category key and names are required' using errcode='23514'; end if;
  insert into public.other_income_categories(company_id,category_key,name_en,name_sq,created_by)
  values(p_company_id,lower(trim(p_category_key)),trim(p_name_en),trim(p_name_sq),(select auth.uid())) returning * into category_row;
  return category_row;
end;
$$;


--
-- Name: create_payroll_payment_batch(uuid, uuid, date, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_payroll_payment_batch(p_payroll_run_id uuid, p_company_bank_account_id uuid, p_payment_date date, p_idempotency_key text, p_employee_ids uuid[] DEFAULT NULL::uuid[]) RETURNS public.payroll_payment_batches
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare run_row public.payroll_runs; result public.payroll_payment_batches; next_number bigint;
begin
  select * into run_row from public.payroll_runs where id=p_payroll_run_id for update;
  if not found then raise exception 'Payroll run not found' using errcode='P0002'; end if;
  if not (select private.payroll_feature_enabled(run_row.company_id,'payroll_bank_exports_enabled'))
     or not (select private.has_company_permission(run_row.company_id,'payroll.payment_batch.create')) then
    raise exception 'Payroll bank exports are disabled or permission is missing' using errcode='42501';
  end if;
  if run_row.status not in ('finalized','payment_pending','partially_paid') then raise exception 'Payroll is not payable' using errcode='55000'; end if;
  if not exists(select 1 from public.company_bank_accounts where id=p_company_bank_account_id and company_id=run_row.company_id and is_active) then
    raise exception 'Company bank account not found' using errcode='P0002';
  end if;
  select * into result from public.payroll_payment_batches where company_id=run_row.company_id and idempotency_key=p_idempotency_key;
  if found then return result; end if;
  perform pg_advisory_xact_lock(hashtextextended(run_row.company_id::text||':payroll-batch:'||extract(year from p_payment_date)::text,0));
  select count(*)+1 into next_number from public.payroll_payment_batches where company_id=run_row.company_id;
  insert into public.payroll_payment_batches(
    company_id,payroll_run_id,branch_id,company_bank_account_id,batch_number,currency,payment_date,idempotency_key,created_by
  ) values (
    run_row.company_id,run_row.id,run_row.branch_id,p_company_bank_account_id,
    'PB-'||extract(year from p_payment_date)::text||'-'||lpad(next_number::text,6,'0'),
    run_row.currency,p_payment_date,p_idempotency_key,(select auth.uid())
  ) returning * into result;
  insert into public.payroll_payment_lines(company_id,payment_batch_id,liability_id,employee_id,employee_bank_account_id,amount)
  select liability.company_id,result.id,liability.id,liability.employee_id,bank.id,liability.amount-liability.paid_amount
  from public.payroll_liabilities liability
  left join lateral (
    select id from public.employee_bank_accounts
    where company_id=liability.company_id and employee_id=liability.employee_id and is_active
    order by is_primary desc,created_at desc limit 1
  ) bank on true
  where liability.payroll_run_id=run_row.id and liability.liability_type='net_salary'
    and liability.status in ('open','partially_paid')
    and (p_employee_ids is null or liability.employee_id=any(p_employee_ids));
  update public.payroll_payment_batches set total_amount=(
    select coalesce(sum(amount),0) from public.payroll_payment_lines where payment_batch_id=result.id
  ) where id=result.id returning * into result;
  if result.total_amount<=0 then raise exception 'No open salary liabilities were selected' using errcode='23514'; end if;
  update public.payroll_runs set status='payment_pending',updated_at=now(),updated_by=(select auth.uid()) where id=run_row.id;
  perform private.emit_domain_outbox_event(result.company_id,result.branch_id,'payroll_payment_batch',result.id,'payroll.payment_batch.created',
    jsonb_build_object('batchNumber',result.batch_number,'total',result.total_amount),p_idempotency_key||':created');
  return result;
end $$;


--
-- Name: payroll_periods; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_periods (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    payroll_group_id uuid,
    code text NOT NULL,
    name text NOT NULL,
    starts_on date NOT NULL,
    ends_on date NOT NULL,
    payment_date date NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT payroll_periods_check CHECK ((ends_on >= starts_on)),
    CONSTRAINT payroll_periods_status_check CHECK ((status = ANY (ARRAY['open'::text, 'processing'::text, 'closed'::text, 'locked'::text, 'reopened'::text])))
);


--
-- Name: create_payroll_period(uuid, text, text, date, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_payroll_period(p_company_id uuid, p_code text, p_name text, p_starts_on date, p_ends_on date, p_payment_date date, p_payroll_group_id uuid DEFAULT NULL::uuid) RETURNS public.payroll_periods
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result public.payroll_periods;
begin
  if not (select private.payroll_feature_enabled(p_company_id,'payroll_enabled'))
     or not (select private.has_company_permission(p_company_id,'payroll.period.manage')) then
    raise exception 'Payroll is disabled or permission is missing' using errcode='42501';
  end if;
  if p_ends_on < p_starts_on then
    raise exception 'Payroll period end must not precede start' using errcode='23514';
  end if;
  insert into public.payroll_periods(
    company_id,payroll_group_id,code,name,starts_on,ends_on,payment_date,created_by,updated_by
  ) values (
    p_company_id,p_payroll_group_id,trim(p_code),trim(p_name),p_starts_on,p_ends_on,p_payment_date,
    (select auth.uid()),(select auth.uid())
  ) returning * into result;
  perform private.record_payroll_audit(p_company_id,null,'payroll.period.created','payroll_period',result.id,null,to_jsonb(result),null);
  return result;
end $$;


--
-- Name: create_payroll_run(uuid, uuid, uuid, text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_payroll_run(p_company_id uuid, p_payroll_period_id uuid, p_config_set_id uuid, p_idempotency_key text, p_branch_id uuid DEFAULT NULL::uuid, p_payroll_group_id uuid DEFAULT NULL::uuid, p_run_type text DEFAULT 'regular'::text, p_original_run_id uuid DEFAULT NULL::uuid) RETURNS public.payroll_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  result public.payroll_runs;
  period_row public.payroll_periods;
  config_row public.payroll_config_sets;
  next_number bigint;
begin
  if not (select private.payroll_feature_enabled(p_company_id,'payroll_enabled'))
     or not (select private.has_company_permission(p_company_id,'payroll.run.create')) then
    raise exception 'Payroll is disabled or permission is missing' using errcode='42501';
  end if;
  if trim(coalesce(p_idempotency_key,''))='' then
    raise exception 'Idempotency key is required' using errcode='23514';
  end if;
  select * into result from public.payroll_runs
  where company_id=p_company_id and idempotency_key=p_idempotency_key;
  if found then return result; end if;
  select * into period_row from public.payroll_periods
  where id=p_payroll_period_id and company_id=p_company_id and status in ('open','processing','reopened')
  for update;
  if not found then raise exception 'Open payroll period not found' using errcode='P0002'; end if;
  select * into config_row from public.payroll_config_sets
  where id=p_config_set_id and company_id=p_company_id and status='approved'
    and effective_from<=period_row.ends_on
    and (effective_until is null or effective_until>=period_row.starts_on);
  if not found then raise exception 'Approved effective payroll configuration not found' using errcode='P0002'; end if;
  if p_run_type<>'regular' and not (select private.payroll_feature_enabled(p_company_id,'supplemental_payroll_enabled')) then
    raise exception 'Supplemental payroll is disabled' using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':payroll-run:'||extract(year from period_row.ends_on)::text,0));
  select coalesce(max(nullif(regexp_replace(run_number,'^PAY-[0-9]{4}-',''),'')::bigint),0)+1
  into next_number from public.payroll_runs
  where company_id=p_company_id and run_number like 'PAY-'||extract(year from period_row.ends_on)::text||'-%';
  insert into public.payroll_runs(
    company_id,branch_id,payroll_period_id,payroll_group_id,config_set_id,run_number,run_type,
    original_run_id,currency,idempotency_key,created_by,updated_by
  ) values (
    p_company_id,p_branch_id,p_payroll_period_id,p_payroll_group_id,p_config_set_id,
    'PAY-'||extract(year from period_row.ends_on)::text||'-'||lpad(next_number::text,6,'0'),
    p_run_type,p_original_run_id,config_row.currency,p_idempotency_key,(select auth.uid()),(select auth.uid())
  ) returning * into result;
  update public.payroll_periods set status='processing',updated_at=now(),updated_by=(select auth.uid())
  where id=p_payroll_period_id and status in ('open','reopened');
  perform private.record_payroll_audit(p_company_id,p_branch_id,'payroll.run.created','payroll_run',result.id,null,to_jsonb(result),null);
  perform private.emit_domain_outbox_event(p_company_id,p_branch_id,'payroll_run',result.id,'payroll.run.created',
    jsonb_build_object('runNumber',result.run_number,'runType',result.run_type),p_idempotency_key||':created');
  return result;
end $$;


--
-- Name: post_cod_settlements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.post_cod_settlements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    fund_account_id uuid NOT NULL,
    amount numeric(20,4) NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    settlement_date date DEFAULT CURRENT_DATE NOT NULL,
    description text,
    idempotency_key uuid,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    reversed_at timestamp with time zone,
    reversed_by uuid,
    CONSTRAINT post_cod_settlements_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT post_cod_settlements_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT post_cod_settlements_status_check CHECK ((status = ANY (ARRAY['active'::text, 'reversed'::text])))
);


--
-- Name: create_post_cod_settlement(uuid, uuid, numeric, date, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_post_cod_settlement(p_company_id uuid, p_fund_account_id uuid, p_amount numeric, p_settlement_date date DEFAULT CURRENT_DATE, p_description text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.post_cod_settlements
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  fund_row public.company_fund_accounts;
  settlement_row public.post_cod_settlements;
  cod_total numeric(20,4) := 0;
  settled_total numeric(20,4) := 0;
  outstanding_total numeric(20,4) := 0;
  settlement_amount numeric(20,4) := round(coalesce(p_amount, 0), 4);
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_company_id is null or not public.can_access_company(p_company_id) then
    raise exception 'The selected tenant is not accessible' using errcode = '42501';
  end if;
  if not coalesce(private.has_company_permission(p_company_id, 'cash_transaction.post'), false) then
    raise exception 'Insufficient permission to settle Post COD' using errcode = '42501';
  end if;
  if settlement_amount <= 0 then
    raise exception 'Settlement amount must be greater than zero' using errcode = '23514';
  end if;

  select * into fund_row
    from public.company_fund_accounts
   where id = p_fund_account_id and is_active
   for update;
  if not found then
    raise exception 'The selected cash or bank account is not active' using errcode = '23503';
  end if;
  if fund_row.fund_type not in ('cash', 'bank') or fund_row.stripe_store_id is not null then
    raise exception 'Post COD settlements can only use cash or bank accounts' using errcode = '23514';
  end if;
  if not private.can_view_fund_account(fund_row.id) then
    raise exception 'The selected cash or bank account is not accessible' using errcode = '42501';
  end if;

  if p_idempotency_key is not null then
    select * into settlement_row
      from public.post_cod_settlements
     where idempotency_key = p_idempotency_key
     for update;
    if found then return settlement_row; end if;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text || ':post_cod', 0));

  select coalesce(sum(invoice.total_amount), 0)::numeric(20,4)
    into cod_total
    from public.invoices invoice
   where invoice.company_id = p_company_id
     and invoice.post_cod = true
     and invoice.accounting_state = 'posted'
     and lower(coalesce(invoice.type, '')) in ('invoice', 'final_invoice', 'advance_invoice', 'simplified_invoice')
     and lower(coalesce(invoice.status::text, '')) not in ('cancelled', 'credited', 'reversed');

  select coalesce(sum(settlement.amount), 0)::numeric(20,4)
    into settled_total
    from public.post_cod_settlements settlement
   where settlement.company_id = p_company_id
     and settlement.status = 'active';

  outstanding_total := greatest(cod_total - settled_total, 0);
  if settlement_amount > outstanding_total + 0.0001 then
    raise exception 'Settlement amount exceeds the Post COD balance' using errcode = '23514';
  end if;

  insert into public.post_cod_settlements (
    company_id, fund_account_id, amount, currency, settlement_date,
    description, idempotency_key, created_by
  ) values (
    p_company_id, fund_row.id, settlement_amount, fund_row.currency,
    coalesce(p_settlement_date, current_date), nullif(trim(p_description), ''),
    p_idempotency_key, actor_id
  ) returning * into settlement_row;

  return settlement_row;
end;
$$;


--
-- Name: sales_book_amendments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sales_book_amendments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    sales_book_period_id uuid NOT NULL,
    invoice_id uuid,
    status text DEFAULT 'PENDING'::text NOT NULL,
    reason text NOT NULL,
    before_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    after_snapshot jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    applied_at timestamp with time zone,
    applied_by uuid,
    CONSTRAINT sales_book_amendments_reason_check CHECK ((length(TRIM(BOTH FROM reason)) > 0)),
    CONSTRAINT sales_book_amendments_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'APPLIED'::text, 'CANCELLED'::text])))
);


--
-- Name: create_sales_book_amendment(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_sales_book_amendment(p_period_id uuid, p_invoice_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS public.sales_book_amendments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  period_row public.sales_book_periods;
  invoice_row public.invoices;
  amendment_row public.sales_book_amendments;
  before_snapshot jsonb;
begin
  if nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'An amendment reason is required' using errcode = '23514';
  end if;
  if p_invoice_id is null then
    raise exception 'An affected Sales Book transaction is required for an amendment' using errcode = '22023';
  end if;
  select * into period_row from public.sales_book_periods where id = p_period_id for update;
  if not found then
    raise exception 'Sales Book period not found' using errcode = 'P0002';
  end if;
  if not coalesce(private.has_company_permission(period_row.company_id, 'tax.declaration.prepare'), false) then
    raise exception 'Insufficient permission to amend the Sales Book' using errcode = '42501';
  end if;
  if period_row.status not in ('DECLARED', 'AMENDED') then
    raise exception 'Only a declared Sales Book period may be amended' using errcode = '55000';
  end if;
  select * into invoice_row from public.invoices where id = p_invoice_id and company_id = period_row.company_id for share;
  if not found then
    raise exception 'The selected invoice is not in this company' using errcode = '22023';
  end if;
  if invoice_row.sales_book_period_id is distinct from period_row.id then
    raise exception 'The selected invoice is not assigned to this Sales Book period' using errcode = '22023';
  end if;
  before_snapshot := jsonb_build_object('invoice', to_jsonb(invoice_row), 'period', private.sales_book_period_snapshot(period_row.id));
  insert into public.sales_book_amendments (
    company_id, sales_book_period_id, invoice_id, reason, before_snapshot, created_by
  ) values (
    period_row.company_id, period_row.id, p_invoice_id, trim(p_reason), before_snapshot, (select auth.uid())
  ) returning * into amendment_row;
  return amendment_row;
end
$$;


--
-- Name: create_stock_tracked_invoice(jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_stock_tracked_invoice(p_invoice jsonb, p_items jsonb, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  current_user_id uuid := (select auth.uid());
  invoice_user_id uuid;
  invoice_company_id uuid;
  invoice_client_id uuid;
  invoice_row public.invoices;
  client_row public.clients;
  product_row public.products;
  item_record record;
  stock_before numeric;
  stock_after numeric;
  required_quantity numeric;
begin
  if current_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if jsonb_typeof(coalesce(p_invoice, '{}'::jsonb)) <> 'object' then
    raise exception 'Invoice payload must be an object' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(p_items, '[]'::jsonb)) = 0 then
    raise exception 'At least one invoice item is required' using errcode = '22023';
  end if;

  invoice_user_id := nullif(p_invoice ->> 'user_id', '')::uuid;
  invoice_company_id := nullif(p_invoice ->> 'company_id', '')::uuid;
  invoice_client_id := nullif(p_invoice ->> 'client_id', '')::uuid;

  if invoice_user_id is null then
    invoice_user_id := current_user_id;
  elsif invoice_user_id <> current_user_id then
    raise exception 'Invoice user does not match the signed-in user' using errcode = '42501';
  end if;

  if invoice_company_id is not null
     and not public.can_access_company(invoice_company_id) then
    raise exception 'You do not have access to this company' using errcode = '42501';
  end if;

  -- A retry after a network timeout returns the original invoice instead of
  -- issuing the same stock twice.
  if p_idempotency_key is not null then
    select *
    into invoice_row
    from public.invoices
    where company_id is not distinct from invoice_company_id
      and idempotency_key = p_idempotency_key
      and (
        user_id = current_user_id
        or public.can_access_company(company_id)
      )
    order by created_at desc
    limit 1
    for update;

    if found then
      return invoice_row;
    end if;
  end if;

  if nullif(trim(coalesce(p_invoice ->> 'invoice_number', '')), '') is null then
    raise exception 'Invoice number is required' using errcode = '22023';
  end if;
  if lower(coalesce(p_invoice ->> 'type', 'invoice')) <> 'invoice' then
    raise exception 'Stock checkout is available for invoices only' using errcode = '22023';
  end if;

  -- Validate every line before changing anything. This also prevents a
  -- negative line from cancelling a positive line for the same product.
  for item_record in
    select *
    from jsonb_to_recordset(p_items) as item(
      product_id uuid,
      description text,
      quantity numeric,
      unit text,
      unit_price numeric,
      tax_rate numeric,
      discount numeric,
      sku text,
      amount numeric
    )
  loop
    if coalesce(item_record.quantity, 0) <= 0 then
      raise exception 'Invoice quantities must be greater than zero' using errcode = '22023';
    end if;
    if item_record.product_id is null
       and nullif(trim(coalesce(item_record.description, '')), '') is null then
      raise exception 'Every invoice line needs a product or description' using errcode = '22023';
    end if;
  end loop;

  if invoice_client_id is not null then
    select *
    into client_row
    from public.clients
    where id = invoice_client_id
      and (
        user_id = current_user_id
        or public.can_access_company(company_id)
      );

    if not found then
      raise exception 'The selected customer is not available in this company' using errcode = '22023';
    end if;
    if invoice_company_id is not null
       and client_row.company_id is not null
       and not private.company_is_in_scope(invoice_company_id, client_row.company_id) then
      raise exception 'The selected customer belongs to another company' using errcode = '22023';
    end if;
  end if;

  -- Lock every referenced product before inserting the invoice. Two devices
  -- attempting to sell the last unit therefore serialize instead of both
  -- succeeding against the same displayed stock value.
  for item_record in
    select item.product_id, sum(item.quantity) as quantity
    from jsonb_to_recordset(p_items) as item(product_id uuid, quantity numeric)
    where item.product_id is not null
    group by item.product_id
  loop
    required_quantity := item_record.quantity;

    select *
    into product_row
    from public.products
    where id = item_record.product_id
    for update;

    if not found then
      raise exception 'One of the selected products no longer exists' using errcode = '22023';
    end if;
    if not (
      product_row.user_id = current_user_id
      or public.can_access_company(product_row.company_id)
    ) then
      raise exception 'You do not have access to one of the selected products' using errcode = '42501';
    end if;
    if invoice_company_id is not null
       and product_row.company_id is not null
       and not private.company_is_in_scope(invoice_company_id, product_row.company_id) then
      raise exception 'A product belongs to another company subdivision' using errcode = '22023';
    end if;

    if coalesce(product_row.track_stock, false)
       and coalesce(product_row.stock_quantity, 0) < required_quantity then
      raise exception 'Not enough stock for "%". Available: %, requested: %',
        product_row.name, coalesce(product_row.stock_quantity, 0), required_quantity
        using errcode = '22003';
    end if;
  end loop;

  begin
    insert into public.invoices (
      user_id, company_id, client_id, invoice_number, issue_date, due_date,
      notes, status, type, subtype, tax_amount, discount_amount,
      discount_percent, total_amount, amount_received, payment_method,
      change_amount, idempotency_key
    ) values (
      invoice_user_id,
      invoice_company_id,
      invoice_client_id,
      trim(p_invoice ->> 'invoice_number'),
      coalesce(nullif(p_invoice ->> 'issue_date', '')::date, current_date),
      nullif(p_invoice ->> 'due_date', '')::date,
      p_invoice ->> 'notes',
      coalesce(nullif(p_invoice ->> 'status', '')::public.invoice_status, 'draft'::public.invoice_status),
      'invoice',
      coalesce(nullif(p_invoice ->> 'subtype', ''), 'regular'),
      coalesce(nullif(p_invoice ->> 'tax_amount', '')::numeric, 0),
      coalesce(nullif(p_invoice ->> 'discount_amount', '')::numeric, 0),
      coalesce(nullif(p_invoice ->> 'discount_percent', '')::numeric, 0),
      coalesce(nullif(p_invoice ->> 'total_amount', '')::numeric, 0),
      coalesce(nullif(p_invoice ->> 'amount_received', '')::numeric, 0),
      coalesce(nullif(p_invoice ->> 'payment_method', ''), 'bank'),
      coalesce(nullif(p_invoice ->> 'change_amount', '')::numeric, 0),
      p_idempotency_key
    )
    returning * into invoice_row;
  exception
    when unique_violation then
      if p_idempotency_key is null then
        raise;
      end if;

      select *
      into invoice_row
      from public.invoices
      where company_id is not distinct from invoice_company_id
        and idempotency_key = p_idempotency_key
        and (
          user_id = current_user_id
          or public.can_access_company(company_id)
        )
      order by created_at desc
      limit 1
      for update;

      if not found then
        raise;
      end if;
      return invoice_row;
  end;

  for item_record in
    select *
    from jsonb_to_recordset(p_items) as item(
      product_id uuid,
      description text,
      quantity numeric,
      unit text,
      unit_price numeric,
      tax_rate numeric,
      discount numeric,
      sku text,
      amount numeric
    )
  loop
    if item_record.product_id is not null then
      select * into product_row
      from public.products
      where id = item_record.product_id;
    else
      product_row := null;
    end if;

    insert into public.invoice_items (
      invoice_id, product_id, description, quantity, unit, unit_price,
      tax_rate, discount, sku, amount
    ) values (
      invoice_row.id,
      item_record.product_id,
      coalesce(nullif(trim(item_record.description), ''), product_row.name),
      item_record.quantity,
      coalesce(nullif(item_record.unit, ''), product_row.unit, 'pcs'),
      coalesce(item_record.unit_price, product_row.unit_price, 0),
      coalesce(item_record.tax_rate, product_row.tax_rate, 0),
      coalesce(item_record.discount, 0),
      coalesce(nullif(item_record.sku, ''), product_row.sku, product_row.barcode, ''),
      coalesce(
        item_record.amount,
        item_record.quantity * coalesce(item_record.unit_price, product_row.unit_price, 0)
          * (1 - coalesce(item_record.discount, 0) / 100)
      )
    );
  end loop;

  -- Only tracked products are decremented. Non-stock products remain valid
  -- invoice lines and do not create a misleading inventory movement.
  for item_record in
    select item.product_id, sum(item.quantity) as quantity
    from jsonb_to_recordset(p_items) as item(product_id uuid, quantity numeric)
    where item.product_id is not null
    group by item.product_id
  loop
    select * into product_row
    from public.products
    where id = item_record.product_id
    for update;

    if product_row.track_stock then
      stock_before := coalesce(product_row.stock_quantity, 0);
      stock_after := stock_before - item_record.quantity;

      update public.products
      set stock_quantity = stock_after
      where id = product_row.id;

      insert into public.inventory_stock_movements (
        company_id, product_id, invoice_id, movement_type, quantity_delta,
        stock_before, stock_after, created_by
      ) values (
        product_row.company_id,
        product_row.id,
        invoice_row.id,
        'invoice_issue',
        -item_record.quantity,
        stock_before,
        stock_after,
        current_user_id
      );
    end if;
  end loop;

  return invoice_row;
end;
$$;


--
-- Name: create_stock_tracked_invoice_with_signature(jsonb, jsonb, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_stock_tracked_invoice_with_signature(p_invoice jsonb, p_items jsonb, p_idempotency_key uuid DEFAULT NULL::uuid, p_customer_signature jsonb DEFAULT NULL::jsonb) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  invoice_row public.invoices;
  requested boolean;
  signature_url text;
  signature_name text;
  signed_at timestamptz;
  desired_status text;
  desired_signature_url text;
  desired_signature_name text;
begin
  invoice_row := public.create_stock_tracked_invoice(p_invoice, p_items, p_idempotency_key);

  if p_customer_signature is null then
    return invoice_row;
  end if;

  requested := coalesce((p_customer_signature ->> 'requested')::boolean, false);
  signature_url := nullif(trim(p_customer_signature ->> 'signature_url'), '');
  signature_name := nullif(trim(p_customer_signature ->> 'name'), '');
  desired_signature_url := case when requested then signature_url else null end;
  desired_signature_name := case when requested then signature_name else null end;
  desired_status := case
    when not requested then 'not_requested'
    when signature_url is not null then 'signed'
    else 'pending'
  end;
  signed_at := case
    when requested and signature_url is not null
      then coalesce(
        nullif(p_customer_signature ->> 'signed_at', '')::timestamptz,
        case when invoice_row.buyer_signature_url is not distinct from signature_url
          then invoice_row.customer_signed_at
          else null
        end,
        clock_timestamp()
      )
    else null
  end;

  if signature_url is not null and length(signature_url) > 2000000 then
    raise exception 'Customer signature is too large' using errcode = '22023';
  end if;

  -- Do not issue a no-op update on an idempotent retry of an already-posted
  -- invoice: posted-document immutability correctly rejects real changes.
  if invoice_row.customer_signature_requested is distinct from requested
     or invoice_row.buyer_signature_url is distinct from desired_signature_url
     or invoice_row.customer_signature_name is distinct from desired_signature_name
     or invoice_row.customer_signed_at is distinct from signed_at
     or invoice_row.customer_signature_status is distinct from desired_status then
    update public.invoices
    set customer_signature_requested = requested,
        customer_signature_status = desired_status,
        customer_signature_name = desired_signature_name,
        customer_signed_at = signed_at,
        buyer_signature_url = desired_signature_url
    where id = invoice_row.id
    returning * into invoice_row;
  end if;

  return invoice_row;
end
$$;


--
-- Name: create_stripe_oauth_state(text, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_stripe_oauth_state(p_state_hash text, p_stripe_store_id uuid, p_user_id uuid, p_expires_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into private.stripe_oauth_states (state_hash, stripe_store_id, user_id, expires_at)
  values (p_state_hash, p_stripe_store_id, p_user_id, p_expires_at);
end;
$$;


--
-- Name: stripe_payout_settlements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.stripe_payout_settlements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    stripe_fund_account_id uuid NOT NULL,
    bank_fund_account_id uuid NOT NULL,
    payout_amount numeric(20,4) NOT NULL,
    bank_fee numeric(20,4) DEFAULT 0 NOT NULL,
    net_received numeric(20,4) GENERATED ALWAYS AS ((payout_amount - bank_fee)) STORED,
    currency text DEFAULT 'EUR'::text NOT NULL,
    settlement_date date DEFAULT CURRENT_DATE NOT NULL,
    description text,
    idempotency_key uuid,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    reversed_at timestamp with time zone,
    reversed_by uuid,
    CONSTRAINT stripe_payout_settlements_bank_fee_check CHECK ((bank_fee >= (0)::numeric)),
    CONSTRAINT stripe_payout_settlements_check CHECK ((bank_fee <= payout_amount)),
    CONSTRAINT stripe_payout_settlements_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT stripe_payout_settlements_payout_amount_check CHECK ((payout_amount > (0)::numeric)),
    CONSTRAINT stripe_payout_settlements_status_check CHECK ((status = ANY (ARRAY['active'::text, 'reversed'::text])))
);


--
-- Name: create_stripe_payout_settlement(uuid, uuid, uuid, numeric, numeric, date, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_stripe_payout_settlement(p_company_id uuid, p_stripe_fund_account_id uuid, p_bank_fund_account_id uuid, p_payout_amount numeric, p_bank_fee numeric DEFAULT 0, p_settlement_date date DEFAULT CURRENT_DATE, p_description text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.stripe_payout_settlements
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  stripe_fund_row public.company_fund_accounts;
  bank_fund_row public.company_fund_accounts;
  settlement_row public.stripe_payout_settlements;
  payout_amount_value numeric(20,4) := round(coalesce(p_payout_amount, 0), 4);
  bank_fee_value numeric(20,4) := round(coalesce(p_bank_fee, 0), 4);
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_company_id is null or not public.can_access_company(p_company_id) then
    raise exception 'The selected tenant is not accessible' using errcode = '42501';
  end if;
  if not coalesce(private.has_company_permission(p_company_id, 'cash_transaction.post'), false) then
    raise exception 'Insufficient permission to reconcile a Stripe payout' using errcode = '42501';
  end if;
  if payout_amount_value <= 0 then
    raise exception 'Payout amount must be greater than zero' using errcode = '23514';
  end if;
  if bank_fee_value < 0 or bank_fee_value > payout_amount_value then
    raise exception 'Bank fee must be between zero and the payout amount' using errcode = '23514';
  end if;

  select * into stripe_fund_row
    from public.company_fund_accounts
   where id = p_stripe_fund_account_id and is_active
   for update;
  if not found or stripe_fund_row.stripe_store_id is null then
    raise exception 'The selected source is not an active Stripe balance' using errcode = '23503';
  end if;
  if not private.can_view_fund_account(stripe_fund_row.id) then
    raise exception 'The selected Stripe balance is not accessible' using errcode = '42501';
  end if;

  select * into bank_fund_row
    from public.company_fund_accounts
   where id = p_bank_fund_account_id and is_active
   for update;
  if not found or bank_fund_row.fund_type not in ('cash', 'bank') or bank_fund_row.stripe_store_id is not null then
    raise exception 'The selected destination must be an active cash or bank account' using errcode = '23503';
  end if;
  if not private.can_view_fund_account(bank_fund_row.id) then
    raise exception 'The selected destination account is not accessible' using errcode = '42501';
  end if;
  if upper(coalesce(stripe_fund_row.currency, 'EUR')) <> upper(coalesce(bank_fund_row.currency, 'EUR')) then
    raise exception 'Stripe and destination accounts must use the same currency' using errcode = '22023';
  end if;

  if p_idempotency_key is not null then
    select * into settlement_row
      from public.stripe_payout_settlements
     where idempotency_key = p_idempotency_key
     for update;
    if found then return settlement_row; end if;
  end if;

  insert into public.stripe_payout_settlements (
    company_id, stripe_fund_account_id, bank_fund_account_id,
    payout_amount, bank_fee, currency, settlement_date,
    description, idempotency_key, created_by
  ) values (
    p_company_id, stripe_fund_row.id, bank_fund_row.id,
    payout_amount_value, bank_fee_value, upper(coalesce(stripe_fund_row.currency, 'EUR')),
    coalesce(p_settlement_date, current_date), nullif(trim(p_description), ''),
    p_idempotency_key, actor_id
  ) returning * into settlement_row;

  return settlement_row;
end;
$$;


--
-- Name: create_stripe_sale_invoice(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_stripe_sale_invoice(p_stripe_transaction_id uuid) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  transaction_row public.stripe_transactions;
  store_row public.stripe_stores;
  company_row public.companies;
  client_row public.clients;
  linked_client_id uuid;
  actor_id uuid;
  invoice_row public.invoices;
  invoice_number text;
  invoice_items jsonb := '[]'::jsonb;
  normalized_item jsonb;
  item_total numeric(20,4) := 0;
  item_quantity numeric(20,4);
  item_price numeric(20,4);
  item_discount numeric(20,4);
  item_tax numeric(20,4);
  item_description text;
begin
  select * into transaction_row
  from public.stripe_transactions
  where id = p_stripe_transaction_id
  for update;
  if not found then
    raise exception 'Stripe transaction not found' using errcode = 'P0002';
  end if;
  if transaction_row.invoice_id is not null then
    select * into invoice_row from public.invoices where id = transaction_row.invoice_id;
    return invoice_row;
  end if;
  if lower(coalesce(transaction_row.type, '')) not in ('charge', 'payment')
     or coalesce(transaction_row.amount, 0) <= 0 then
    return null;
  end if;

  select * into store_row from public.stripe_stores where id = transaction_row.stripe_store_id;
  if not found then
    raise exception 'Stripe store not found' using errcode = 'P0002';
  end if;
  select * into company_row from public.companies where id = store_row.company_id;
  actor_id := coalesce(store_row.created_by, transaction_row.user_id, company_row.owner_id);
  if actor_id is null then
    raise exception 'Stripe store has no invoice owner' using errcode = '42501';
  end if;

  perform set_config('request.jwt.claim.sub', actor_id::text, true);
  if not (
    private.has_company_permission(store_row.company_id, 'sales_invoice.create')
    or private.has_company_permission(store_row.company_id, 'invoice.create')
  ) then
    raise exception 'Stripe store owner cannot create invoices for this company' using errcode = '42501';
  end if;

  if transaction_row.client_id is not null then
    select * into client_row from public.clients where id = transaction_row.client_id;
  end if;

  if client_row.id is null and transaction_row.stripe_customer_id is not null then
    select link.client_id into linked_client_id
    from private.stripe_customer_links link
    where link.stripe_store_id = store_row.id
      and link.stripe_customer_id = transaction_row.stripe_customer_id;
    if linked_client_id is not null then
      select * into client_row from public.clients where id = linked_client_id;
    end if;
  end if;

  if client_row.id is null and nullif(trim(transaction_row.customer_email), '') is not null then
    select * into client_row
    from public.clients candidate
    where candidate.company_id = store_row.company_id
      and lower(trim(candidate.email)) = lower(trim(transaction_row.customer_email))
    order by candidate.created_at
    limit 1;
  end if;

  if client_row.id is null
     and (
       nullif(trim(transaction_row.customer_email), '') is not null
       or nullif(trim(transaction_row.customer_name), '') is not null
       or transaction_row.stripe_customer_id is not null
     ) then
    insert into public.clients (
      user_id, company_id, name, email, phone, address, city, zip_code, country, notes
    ) values (
      actor_id,
      store_row.company_id,
      coalesce(nullif(trim(transaction_row.customer_name), ''), nullif(trim(transaction_row.customer_email), ''), 'Stripe customer'),
      nullif(trim(transaction_row.customer_email), ''),
      nullif(trim(transaction_row.customer_phone), ''),
      nullif(trim(concat_ws(', ',
        transaction_row.customer_address ->> 'line1',
        transaction_row.customer_address ->> 'line2',
        transaction_row.customer_address ->> 'city',
        transaction_row.customer_address ->> 'postal_code'
      )), ''),
      nullif(trim(transaction_row.customer_address ->> 'city'), ''),
      nullif(trim(transaction_row.customer_address ->> 'postal_code'), ''),
      nullif(trim(transaction_row.customer_address ->> 'country'), ''),
      'Created from Stripe online sale'
    ) returning * into client_row;
  end if;

  if transaction_row.stripe_customer_id is not null and client_row.id is not null then
    insert into private.stripe_customer_links (stripe_store_id, stripe_customer_id, client_id)
    values (store_row.id, transaction_row.stripe_customer_id, client_row.id)
    on conflict (stripe_store_id, stripe_customer_id) do update
      set client_id = excluded.client_id, updated_at = now();
  end if;

  -- Normalize Checkout line items. If the source was not a Checkout Session,
  -- or its lines do not reconcile to Stripe's gross amount, use one reliable
  -- summary line instead of creating an invoice with the wrong total.
  if jsonb_typeof(transaction_row.line_items) = 'array' then
    for normalized_item in select value from jsonb_array_elements(transaction_row.line_items)
    loop
      item_quantity := greatest(coalesce(nullif(normalized_item ->> 'quantity', '')::numeric, 1), 0.0001);
      item_price := greatest(coalesce(nullif(normalized_item ->> 'unit_price', '')::numeric, 0), 0);
      item_discount := greatest(least(coalesce(nullif(normalized_item ->> 'discount', '')::numeric, 0), 100), 0);
      item_tax := greatest(least(coalesce(nullif(normalized_item ->> 'tax_rate', '')::numeric, 0), 100), 0);
      item_description := coalesce(nullif(trim(normalized_item ->> 'description'), ''), 'Stripe online sale item');
      invoice_items := invoice_items || jsonb_build_array(jsonb_build_object(
        'description', item_description,
        'quantity', item_quantity,
        'unit', coalesce(nullif(trim(normalized_item ->> 'unit'), ''), 'pcs'),
        'unit_price', item_price,
        'tax_rate', item_tax,
        'discount', item_discount,
        'tax_included', false,
        'sku', coalesce(normalized_item ->> 'sku', ''),
        'amount', item_quantity * item_price * (1 - item_discount / 100)
      ));
      item_total := item_total + round(item_quantity * item_price * (1 - item_discount / 100) * (1 + item_tax / 100), 2);
    end loop;
  end if;

  if jsonb_array_length(invoice_items) = 0
     or abs(item_total - transaction_row.amount) > 0.01 then
    invoice_items := jsonb_build_array(jsonb_build_object(
      'description', coalesce(nullif(trim(transaction_row.description), ''), 'Stripe online sale'),
      'quantity', 1,
      'unit', 'sale',
      'unit_price', transaction_row.amount,
      'tax_rate', 0,
      'discount', 0,
      'tax_included', false,
      'sku', transaction_row.stripe_id,
      'amount', transaction_row.amount
    ));
  end if;

  invoice_number := public.reserve_invoice_number(
    store_row.company_id,
    'invoice',
    coalesce(transaction_row.created_at::date, current_date)
  );

  invoice_row := public.save_invoice_document_unchecked(
    jsonb_build_object(
      'user_id', actor_id,
      'company_id', store_row.company_id,
      'client_id', client_row.id,
      'invoice_number', invoice_number,
      'issue_date', coalesce(transaction_row.created_at::date, current_date),
      'status', 'draft',
      'type', 'invoice',
      'subtype', 'regular',
      'commercial_document_type', 'INVOICE',
      'commercial_status', 'ISSUED',
      'accounting_state', 'ready_for_posting',
      'payment_status', 'PAID',
      'payment_method', 'card',
      'amount_received', transaction_row.amount,
      'currency', upper(coalesce(nullif(transaction_row.currency, ''), 'EUR')),
      'tax_amount', 0,
      'total_amount', transaction_row.amount,
      'notes', 'Stripe transaction: ' || transaction_row.stripe_id,
      'source_document_type', 'stripe_transaction',
      'source_document_id', transaction_row.id,
      'template_id', 'corporate',
      'paper_size', 'A4'
    ),
    invoice_items,
    null,
    true,
    null
  );

  -- The invoice was paid online at the time of the Stripe transaction. The
  -- posting journal is already created by the canonical writer; this only
  -- updates the commercial payment state.
  perform set_config('app.financial_workflow', 'authorized', true);
  update public.invoices
  set status = 'paid', payment_status = 'PAID', amount_received = total_amount,
      payment_method = 'card', payment_date = coalesce(transaction_row.created_at::date, current_date),
      stripe_store_id = store_row.id
  where id = invoice_row.id
  returning * into invoice_row;
  perform set_config('app.financial_workflow', '', true);

  update public.stripe_transactions
  set invoice_id = invoice_row.id,
      client_id = client_row.id
  where id = transaction_row.id;

  return invoice_row;
end;
$$;


--
-- Name: delete_expense(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_expense(p_expense_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin perform public.archive_expense(p_expense_id,'Legacy delete request converted to archive'); end $$;


--
-- Name: delete_invoice(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_invoice(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  invoice_row public.invoices%rowtype;
  journal_row public.journal_entries%rowtype;
  stock_row public.inventory_stock_movements%rowtype;
  payment_id uuid;
  payment_ids uuid[] := '{}';
  stock_before numeric;
  journal_is_draft boolean := false;
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_invoice_id is null then
    raise exception 'Invoice id is required' using errcode = '23514';
  end if;

  select *
  into invoice_row
  from public.invoices
  where id = p_invoice_id
  for update;

  if not found then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if invoice_row.company_id is null
     or not coalesce(private.has_company_permission(invoice_row.company_id, 'sales_invoice.delete'), false) then
    raise exception 'Only company administrators can delete invoices'
      using errcode = '42501';
  end if;
  if lower(coalesce(invoice_row.accounting_state, 'legacy')) = 'opening_balance' then
    raise exception 'Opening-balance invoices cannot be deleted'
      using errcode = '55000';
  end if;
  if exists (
    select 1
    from public.invoices child
    where child.credit_of_invoice_id = invoice_row.id
       or child.original_invoice_id = invoice_row.id
       or child.reversal_of_invoice_id = invoice_row.id
  ) then
    raise exception 'This invoice is referenced by another document and cannot be deleted'
      using errcode = '55000';
  end if;
  if exists (
    select 1
    from public.commercial_document_advance_allocations allocation
    where allocation.advance_invoice_id = invoice_row.id
       or allocation.final_invoice_id = invoice_row.id
  ) then
    raise exception 'Invoices used in an advance reconciliation require a correction workflow'
      using errcode = '55000';
  end if;
  if exists (
    select 1
    from public.pos_orders order_row
    where order_row.invoice_id = invoice_row.id
  ) then
    raise exception 'POS invoices must be reversed through the POS return workflow'
      using errcode = '55000';
  end if;
  if exists (
    select 1
    from public.inventory_movements movement
    where movement.source_id = invoice_row.id
      and movement.source_type in ('sales_invoice', 'pos_invoice')
  ) then
    raise exception 'Inventory-ledger invoices require an inventory reversal workflow'
      using errcode = '55000';
  end if;
  if exists (
    select 1
    from public.withholding_transactions transaction_row
    where transaction_row.source_id = invoice_row.id
  ) then
    raise exception 'Invoices referenced by withholding records require a correction workflow'
      using errcode = '55000';
  end if;

  select array_agg(distinct allocation.payment_id)
  into payment_ids
  from public.payment_allocations allocation
  where allocation.invoice_id = invoice_row.id;

  if invoice_row.posting_journal_entry_id is not null then
    select *
    into journal_row
    from public.journal_entries
    where id = invoice_row.posting_journal_entry_id
    for update;

    if found and journal_row.status = 'posted' then
      perform public.reverse_journal_entry(
        journal_row.id,
        coalesce(invoice_row.posting_date, invoice_row.issue_date, current_date),
        'Invoice deleted from the invoice workflow'
      );
    elsif found and journal_row.status = 'draft' then
      journal_is_draft := true;
    elsif found and journal_row.status not in ('reversed') then
      raise exception 'The invoice posting journal cannot be deleted in its current state'
        using errcode = '55000';
    end if;
  end if;

  -- Restore stock before the invoice foreign key is cleared. The original
  -- stock issue remains as history and the compensating movement has no
  -- invoice reference because the source document is being removed.
  for stock_row in
    select movement.*
    from public.inventory_stock_movements movement
    where movement.invoice_id = invoice_row.id
    order by movement.created_at, movement.id
    for update
  loop
    if stock_row.branch_id is not null then
      select coalesce(stock.stock_quantity, 0) into stock_before
      from public.product_branch_stock stock
      where stock.company_id = invoice_row.company_id and stock.branch_id = stock_row.branch_id and stock.product_id = stock_row.product_id
      for update;
      if found then
        update public.product_branch_stock set stock_quantity = stock_before - stock_row.quantity_delta, updated_by = actor_id, updated_at = now() where company_id = invoice_row.company_id and branch_id = stock_row.branch_id and product_id = stock_row.product_id;
        update public.products set stock_quantity = (select coalesce(sum(stock_quantity), 0) from public.product_branch_stock where company_id = invoice_row.company_id and product_id = stock_row.product_id) where id = stock_row.product_id;
      end if;
    else
      select coalesce(product.stock_quantity, 0) into stock_before from public.products product where product.id = stock_row.product_id for update;
      if found then
        update public.products set stock_quantity = stock_before - stock_row.quantity_delta where id = stock_row.product_id;
      end if;
    end if;

    if found then

      insert into public.inventory_stock_movements (
        company_id, branch_id, product_id, invoice_id, movement_type, quantity_delta,
        stock_before, stock_after, created_by
      ) values (
        invoice_row.company_id, stock_row.branch_id, stock_row.product_id, null, 'invoice_reversal',
        -stock_row.quantity_delta, stock_before, stock_before - stock_row.quantity_delta, actor_id
      );
    end if;
  end loop;

  -- Allocations cannot survive a hard delete because invoice_id is required.
  -- The payment itself remains posted and becomes unallocated/partially
  -- allocated, so the cash/bank book is not silently removed.
  delete from public.payment_allocations
  where invoice_id = invoice_row.id;
  if payment_ids is not null then
    foreach payment_id in array payment_ids loop
      perform private.refresh_customer_payment_allocation_state(payment_id);
    end loop;
  end if;

  delete from public.commercial_document_payment_links
  where document_id = invoice_row.id;

  delete from public.document_source_links
  where source_id = invoice_row.id
     or target_id = invoice_row.id;

  delete from public.approval_actions
  where workflow_id in (
    select workflow.id
    from public.approval_workflows workflow
    where workflow.company_id = invoice_row.company_id
      and workflow.entity_type = 'sales_invoice'
      and workflow.entity_id = invoice_row.id
  );
  delete from public.approval_workflows
  where company_id = invoice_row.company_id
    and entity_type = 'sales_invoice'
    and entity_id = invoice_row.id;

  update public.financial_document_attachments
  set deleted_at = clock_timestamp(), deleted_by = actor_id
  where company_id = invoice_row.company_id
    and document_id = invoice_row.id
    and deleted_at is null;

  update public.document_archive
  set status = 'deleted'
  where company_id = invoice_row.company_id
    and source_id = invoice_row.id
    and status = 'active';

  delete from public.domain_outbox_events
  where company_id = invoice_row.company_id
    and aggregate_id = invoice_row.id
    and aggregate_type in ('sales_invoice', 'commercial_document');

  insert into public.commercial_document_event_archive (
    id, company_id, document_id, event_type, from_status, to_status,
    payload, occurred_at, actor_id, deleted_by
  )
  select event.id, event.company_id, event.document_id, event.event_type,
    event.from_status, event.to_status, event.payload, event.occurred_at,
    event.actor_id, (select auth.uid())
  from public.commercial_document_events event
  where event.document_id = invoice_row.id
  on conflict (id) do nothing;

  perform set_config('app.financial_workflow', 'authorized', true);
  perform set_config('app.invoice_delete_workflow', 'authorized', true);
  perform set_config('app.commercial_document_events_workflow', 'authorized', true);

  delete from public.commercial_document_events
  where document_id = invoice_row.id;

  update public.invoices
  set posting_journal_entry_id = null
  where id = invoice_row.id;

  delete from public.invoice_items
  where invoice_id = invoice_row.id;

  delete from public.invoices
  where id = invoice_row.id;

  if journal_is_draft and journal_row.id is not null then
    delete from public.journal_entries
    where id = journal_row.id;
  end if;

  perform set_config('app.invoice_delete_workflow', '', true);
  perform set_config('app.financial_workflow', '', true);
  perform set_config('app.commercial_document_events_workflow', '', true);
end;
$$;


--
-- Name: delete_my_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_my_account() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  current_user_id uuid := (select auth.uid());
  successor_id uuid;
  deleted_email text;
  owned_company record;
begin
  if current_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  -- Keep company history available. If another active member exists, transfer
  -- ownership; otherwise leave the company ownerless rather than deleting its
  -- invoices, accounting entries, and audit history.
  perform set_config('app.company_owner_transfer', 'authorized', true);
  for owned_company in
    select id
    from public.companies
    where owner_id = current_user_id
  loop
    select membership.user_id
    into successor_id
    from public.memberships membership
    where membership.company_id = owned_company.id
      and membership.user_id <> current_user_id
      and coalesce(membership.status, 'active') = 'active'
    order by membership.created_at, membership.id
    limit 1;

    update public.companies
    set owner_id = successor_id,
        updated_at = clock_timestamp(),
        updated_by = successor_id
    where id = owned_company.id;
  end loop;
  perform set_config('app.company_owner_transfer', '', true);

  delete from public.memberships where user_id = current_user_id;
  delete from public.profiles where id = current_user_id;
  delete from auth.sessions where user_id = current_user_id;

  deleted_email := 'deleted+' || current_user_id::text || '@invalid.operix.local';
  update auth.users
  set email = deleted_email,
      phone = null,
      encrypted_password = null,
      raw_user_meta_data = '{}'::jsonb,
      raw_app_meta_data = '{}'::jsonb,
      confirmation_token = '',
      recovery_token = '',
      email_change = '',
      phone_change = '',
      banned_until = 'infinity'::timestamptz,
      deleted_at = clock_timestamp(),
      updated_at = clock_timestamp()
  where id = current_user_id;

  return jsonb_build_object('deleted', true);
end
$$;


--
-- Name: delete_product(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_product(p_product_id uuid, p_company_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  product_row public.products;
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if p_company_id is null then
    raise exception 'An active company is required to delete a product' using errcode = '22004';
  end if;

  -- The company predicate is intentional: a root-company permission must not
  -- turn a delete request for the root into a delete of a child-tenant row.
  -- Keep the legacy user-owned branch for products created before company
  -- ownership was introduced.
  select * into product_row
  from public.products
  where id = p_product_id
    and (
      company_id = p_company_id
      or (company_id is null and user_id = actor_id)
    )
  for update;

  if not found then
    raise exception 'Product not found in the selected company' using errcode = 'P0002';
  end if;

  if (
    product_row.company_id is not null
    and not coalesce(private.has_company_permission(p_company_id, 'products.manage'), false)
  ) or (
    product_row.company_id is null
    and (
      product_row.user_id <> actor_id
      or not private.has_unscoped_permission('products.manage')
    )
  ) then
    raise exception 'You do not have permission to delete this product' using errcode = '42501';
  end if;

  perform set_config('app.product_delete_workflow', 'authorized', true);
  update public.inventory_stock_movements
  set product_name = coalesce(product_name, product_row.name), product_id = null
  where product_id = p_product_id;
  update public.inventory_movements
  set product_name = coalesce(product_name, product_row.name), product_id = null
  where product_id = p_product_id;
  update public.inventory_count_lines
  set product_name = coalesce(product_name, product_row.name), product_id = null
  where product_id = p_product_id;
  delete from public.products where id = p_product_id;
end;
$$;


