--
-- Name: asset_disposals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.asset_disposals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    asset_id uuid NOT NULL,
    disposal_date date NOT NULL,
    disposal_type text NOT NULL,
    proceeds numeric(20,4) DEFAULT 0 NOT NULL,
    journal_entry_id uuid,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT asset_disposals_disposal_type_check CHECK ((disposal_type = ANY (ARRAY['disposed'::text, 'written_off'::text]))),
    CONSTRAINT asset_disposals_proceeds_check CHECK ((proceeds >= (0)::numeric))
);


--
-- Name: dispose_fixed_asset(uuid, date, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispose_fixed_asset(p_asset_id uuid, p_disposal_date date, p_disposal_type text, p_proceeds numeric DEFAULT 0, p_reason text DEFAULT NULL::text) RETURNS public.asset_disposals
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  asset_row public.fixed_assets;
  result public.asset_disposals;
  journal_row public.journal_entries;
  cash_account_id uuid;
  gain_account_id uuid;
  loss_account_id uuid;
  line_number integer := 0;
  net_book_value numeric(20,4);
  gain numeric(20,4);
  loss numeric(20,4);
begin
  select * into asset_row from public.fixed_assets where id=p_asset_id for update;
  if not found then raise exception 'Fixed asset not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(asset_row.company_id,'asset.manage'))
     or not (select private.has_company_permission(asset_row.company_id,'journal.create'))
     or not (select private.has_company_permission(asset_row.company_id,'journal.post')) then
    raise exception 'Asset disposal requires asset and journal permissions' using errcode='42501';
  end if;
  if asset_row.status <> 'active' then raise exception 'Only active assets can be disposed' using errcode='55000'; end if;
  if p_disposal_type not in ('disposed','written_off') or trim(coalesce(p_reason,''))='' then raise exception 'Disposal type and reason are required' using errcode='23514'; end if;
  net_book_value := greatest(asset_row.acquisition_cost-asset_row.accumulated_book_depreciation,0);
  gain := greatest(round(coalesce(p_proceeds,0)-net_book_value,4),0);
  loss := greatest(round(net_book_value-coalesce(p_proceeds,0),4),0);
  select id into cash_account_id from public.chart_of_accounts where company_id=asset_row.company_id and code='1010' and active and posting_allowed limit 1;
  select id into gain_account_id from public.chart_of_accounts where company_id=asset_row.company_id and code='4100' and active and posting_allowed limit 1;
  select id into loss_account_id from public.chart_of_accounts where company_id=asset_row.company_id and code='6010' and active and posting_allowed limit 1;
  journal_row := public.create_journal_entry(asset_row.company_id,p_disposal_date,p_disposal_date,'Fixed asset disposal: '||asset_row.asset_number,asset_row.asset_number,'EUR',1,null,'automatic');
  update public.journal_entries set source_type='fixed_asset_disposal',source_id=asset_row.id,source_key=asset_row.asset_number where id=journal_row.id;
  if asset_row.accumulated_book_depreciation > 0 then
    line_number:=line_number+1;
    insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,created_by)
    values(journal_row.id,asset_row.company_id,line_number,asset_row.accumulated_depreciation_account_id,'Remove accumulated depreciation',asset_row.accumulated_book_depreciation,0,'EUR',asset_row.accumulated_book_depreciation,(select auth.uid()));
  end if;
  if p_proceeds > 0 then
    if cash_account_id is null then raise exception 'Cash account is not mapped' using errcode='23514'; end if;
    line_number:=line_number+1;
    insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,created_by)
    values(journal_row.id,asset_row.company_id,line_number,cash_account_id,'Disposal proceeds',round(p_proceeds,4),0,'EUR',round(p_proceeds,4),(select auth.uid()));
  end if;
  if loss > 0 then
    line_number:=line_number+1;
    insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,created_by)
    values(journal_row.id,asset_row.company_id,line_number,loss_account_id,'Loss on disposal',loss,0,'EUR',loss,(select auth.uid()));
  end if;
  line_number:=line_number+1;
  insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,created_by)
  values(journal_row.id,asset_row.company_id,line_number,asset_row.asset_account_id,'Remove asset cost',0,asset_row.acquisition_cost,'EUR',asset_row.acquisition_cost,(select auth.uid()));
  if gain > 0 then
    line_number:=line_number+1;
    insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,created_by)
    values(journal_row.id,asset_row.company_id,line_number,gain_account_id,'Gain on disposal',0,gain,'EUR',gain,(select auth.uid()));
  end if;
  journal_row := public.post_journal_entry(journal_row.id,p_reason);
  insert into public.asset_disposals(company_id,asset_id,disposal_date,disposal_type,proceeds,journal_entry_id,reason,created_by)
  values(asset_row.company_id,asset_row.id,p_disposal_date,p_disposal_type,round(coalesce(p_proceeds,0),4),journal_row.id,p_reason,(select auth.uid())) returning * into result;
  update public.fixed_assets set status=p_disposal_type,updated_at=clock_timestamp(),updated_by=(select auth.uid()) where id=asset_row.id;
  return result;
end
$$;


--
-- Name: ensure_pos_ready(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_pos_ready(p_company_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  branch_id_value uuid;
  terminal_id_value uuid;
  company_label text;
begin
  if p_company_id is null
     or not (select private.is_company_member(p_company_id))
     or not (select private.has_company_permission(p_company_id, 'pos.complete')) then
    raise exception 'Insufficient permission to set up POS' using errcode = '42501';
  end if;

  insert into public.company_feature_flags (company_id, flag, enabled, updated_by)
  values (p_company_id, 'transactional_pos_enabled', true, (select auth.uid()))
  on conflict (company_id, flag) do update
    set enabled = true, updated_at = now(), updated_by = excluded.updated_by
    where public.company_feature_flags.enabled = false;

  select id into terminal_id_value
  from public.pos_terminals
  where company_id = p_company_id and status = 'active'
  order by created_at
  limit 1;
  if terminal_id_value is not null then return terminal_id_value; end if;

  select id into branch_id_value
  from public.branches
  where company_id = p_company_id and is_active
  order by is_head_office desc, created_at
  limit 1;

  if branch_id_value is null then
    select coalesce(nullif(trim(company.company_name), ''), 'Main') into company_label
    from public.companies company where company.id = p_company_id;
    insert into public.branches (company_id, code, name, country_code, is_head_office, is_active, created_by)
    values (p_company_id, 'MAIN', coalesce(company_label, 'Main'), 'XK', true, true, (select auth.uid()))
    on conflict do nothing
    returning id into branch_id_value;
    if branch_id_value is null then
      select id into branch_id_value from public.branches where company_id = p_company_id order by created_at limit 1;
    end if;
  end if;

  insert into public.pos_terminals (company_id, branch_id, code, name, status, created_by)
  values (p_company_id, branch_id_value, 'POS-1', 'Main counter', 'active', (select auth.uid()))
  on conflict (company_id, code) do update set status = 'active'
  returning id into terminal_id_value;
  return terminal_id_value;
end;
$$;


--
-- Name: ensure_sales_book_period(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_sales_book_period(p_company_id uuid, p_as_of_date date DEFAULT (timezone('Europe/Belgrade'::text, clock_timestamp()))::date) RETURNS public.sales_book_periods
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  result public.sales_book_periods;
begin
  if not coalesce(private.has_company_permission(p_company_id, 'tax.book.view'), false) then
    raise exception 'Insufficient permission to view the Sales Book' using errcode = '42501';
  end if;
  if p_as_of_date is not null
     and p_as_of_date > (timezone('Europe/Belgrade', clock_timestamp()))::date then
    raise exception 'A Sales Book period cannot be created for a future date' using errcode = '22023';
  end if;
  result := private.ensure_sales_book_period(p_company_id, p_as_of_date, (select auth.uid()));
  return result;
end
$$;


--
-- Name: ensure_stripe_fund_account_for_sync(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_stripe_fund_account_for_sync(p_stripe_store_id uuid, p_currency text DEFAULT 'EUR'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return private.ensure_stripe_fund_account(p_stripe_store_id, p_currency);
end;
$$;


--
-- Name: clients; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.clients (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    company_id uuid,
    name text NOT NULL,
    email text,
    phone text,
    address text,
    city text,
    zip_code text,
    country text,
    tax_id text,
    nui text,
    fiscal_number text,
    vat_number text,
    company_name text,
    discount_percent numeric DEFAULT 0,
    discount_type text DEFAULT 'percentage'::text,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    payment_terms_days integer,
    credit_limit numeric(20,4) DEFAULT 0 NOT NULL,
    default_receivable_account_id uuid,
    default_revenue_account_id uuid,
    default_vat_code text,
    customer_group text,
    account_status text DEFAULT 'active'::text NOT NULL,
    bad_debt_status text DEFAULT 'none'::text NOT NULL,
    sales_blocked boolean DEFAULT false NOT NULL,
    default_currency text DEFAULT 'EUR'::text NOT NULL,
    billing_contacts jsonb DEFAULT '[]'::jsonb NOT NULL,
    attachments jsonb DEFAULT '[]'::jsonb NOT NULL,
    pos_walk_in_customer boolean DEFAULT false NOT NULL,
    customer_classification text DEFAULT 'OTHER'::text NOT NULL,
    billing_address text,
    shipping_address text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    company text,
    assigned_user_id uuid,
    external_reference text,
    marketing_consent boolean DEFAULT false NOT NULL,
    marketing_consent_at timestamp with time zone,
    marketing_unsubscribed_at timestamp with time zone,
    communication_preferences jsonb DEFAULT '{}'::jsonb NOT NULL,
    date_of_birth date,
    CONSTRAINT clients_account_status_check CHECK ((account_status = ANY (ARRAY['active'::text, 'inactive'::text, 'on_hold'::text, 'closed'::text]))),
    CONSTRAINT clients_attachments_check CHECK ((jsonb_typeof(attachments) = 'array'::text)),
    CONSTRAINT clients_bad_debt_status_check CHECK ((bad_debt_status = ANY (ARRAY['none'::text, 'watch'::text, 'provisioned'::text, 'written_off'::text]))),
    CONSTRAINT clients_billing_contacts_check CHECK ((jsonb_typeof(billing_contacts) = 'array'::text)),
    CONSTRAINT clients_credit_limit_check CHECK ((credit_limit >= (0)::numeric)),
    CONSTRAINT clients_customer_classification_check CHECK ((customer_classification = ANY (ARRAY['B2B'::text, 'B2C'::text, 'OTHER'::text]))),
    CONSTRAINT clients_default_currency_check CHECK ((default_currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT clients_payment_terms_days_check CHECK (((payment_terms_days IS NULL) OR ((payment_terms_days >= 0) AND (payment_terms_days <= 3650))))
);


--
-- Name: ensure_walk_in_customer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_walk_in_customer(p_company_id uuid) RETURNS public.clients
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  walk_in_id uuid;
  walk_in_customer public.clients;
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if p_company_id is null or not public.can_access_company(p_company_id) then
    raise exception 'You do not have access to this company' using errcode = '42501';
  end if;

  select client.id
    into walk_in_id
  from public.clients client
  where client.company_id = p_company_id
    and client.pos_walk_in_customer = true
  order by client.created_at
  limit 1;

  if walk_in_id is null then
    walk_in_id := private.ensure_pos_walk_in_customer(p_company_id);
  end if;

  select *
    into walk_in_customer
  from public.clients client
  where client.id = walk_in_id
    and client.company_id = p_company_id;

  if walk_in_customer.id is null then
    raise exception 'Walk-in customer could not be created' using errcode = '23514';
  end if;

  return walk_in_customer;
end;
$$;


--
-- Name: expire_enterprise_entitlements(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_enterprise_entitlements() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  expired_count integer := 0;
  contract_row record;
begin
  if not private.operix_server_request() then raise exception 'Server billing path required' using errcode = '42501'; end if;
  for contract_row in
    update public.enterprise_contracts contract
    set status = 'expired', updated_at = now()
    where contract.status in ('trialing', 'active')
      and ((contract.ends_at is not null and contract.ends_at <= now())
        or (contract.status = 'trialing' and contract.trial_ends_at is not null and contract.trial_ends_at <= now()))
    returning contract.id, contract.company_id
  loop
    expired_count := expired_count + 1;
    perform public.billing_refresh_product_entitlements(contract_row.company_id);
    insert into public.billing_audit_events(company_id, event, source, actor_user_id, metadata)
    values (contract_row.company_id, 'enterprise_entitlement_expired', 'billing_worker', null, jsonb_build_object('contract_id', contract_row.id));
  end loop;
  return expired_count;
end;
$$;


--
-- Name: expire_product_trials(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_product_trials() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  expired_count integer := 0;
  root_company_id uuid;
begin
  if not private.operix_server_request() then
    raise exception 'Server billing path required' using errcode = '42501';
  end if;
  update public.subscription_trials
  set status = 'expired', consumed = true, updated_at = now()
  where status = 'trialing' and ends_at <= now();
  get diagnostics expired_count = row_count;

  update public.subscription_accounts account
  set status = 'expired', updated_at = now()
  where account.status = 'trialing'
    and account.trial_ends_at <= now()
    and account.stripe_subscription_id is null;

  for root_company_id in select distinct company_id from public.subscription_accounts loop
    perform public.billing_refresh_product_entitlements(root_company_id);
  end loop;
  return expired_count;
end;
$$;


--
-- Name: finalize_inventory_count(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_inventory_count(p_count_id uuid, p_reason text) RETURNS public.inventory_counts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare count_row public.inventory_counts; line_row public.inventory_count_lines; movement_row public.inventory_movements;
begin
  select * into count_row from public.inventory_counts where id=p_count_id for update;
  if not found then raise exception 'Inventory count not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(count_row.company_id,'inventory.manage')) then raise exception 'Insufficient permission to finalize inventory count' using errcode='42501'; end if;
  if count_row.status <> 'draft' then raise exception 'Only draft inventory counts can be finalized' using errcode='55000'; end if;
  if trim(coalesce(p_reason,''))='' then raise exception 'Inventory count finalization reason is required' using errcode='23514'; end if;
  for line_row in select * from public.inventory_count_lines where count_id=count_row.id loop
    if line_row.counted_quantity <> line_row.expected_quantity then
      movement_row := public.post_inventory_movement(count_row.company_id,line_row.product_id,'stock_count',line_row.counted_quantity-line_row.expected_quantity,null,count_row.location_id,'inventory_count',line_row.id,gen_random_uuid(),p_reason);
      update public.inventory_count_lines set adjustment_movement_id=movement_row.id where id=line_row.id;
    end if;
  end loop;
  update public.inventory_counts set status='finalized',finalized_at=clock_timestamp(),finalized_by=(select auth.uid()) where id=count_row.id returning * into count_row;
  return count_row;
end
$$;


--
-- Name: finalize_payroll_run(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_payroll_run(p_payroll_run_id uuid, p_idempotency_key text, p_reason text) RETURNS public.payroll_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'pg_catalog'
    AS $$
declare
  result public.payroll_runs;
  period_row public.payroll_periods;
  accounting_period_row public.accounting_periods;
  journal_row public.journal_entries;
  employee_row record;
  line_number integer:=0;
  payment_date date;
begin
  select * into result from public.payroll_runs where id=p_payroll_run_id for update;
  if not found then raise exception 'Payroll run not found' using errcode='P0002'; end if;
  if result.status in ('finalized','payment_pending','partially_paid','paid') then return result; end if;
  if trim(coalesce(p_idempotency_key,''))='' then raise exception 'Finalization idempotency key is required' using errcode='23514'; end if;
  if trim(coalesce(p_reason,''))='' then raise exception 'Finalization reason is required' using errcode='23514'; end if;
  if not (select private.payroll_feature_enabled(result.company_id,'payroll_enabled'))
     or not (select private.payroll_feature_enabled(result.company_id,'payroll_accounting_enabled'))
     or not (select private.has_company_permission(result.company_id,'payroll.run.finalize'))
     or not (select private.has_company_permission(result.company_id,'journal.post')) then
    raise exception 'Payroll accounting is disabled or permission is missing' using errcode='42501';
  end if;
  if result.status<>'approved' then raise exception 'Only approved payroll may be finalized' using errcode='55000'; end if;
  if exists(select 1 from public.payroll_run_employees where payroll_run_id=result.id and jsonb_array_length(errors)>0) then
    raise exception 'Payroll contains blocking calculation errors' using errcode='23514';
  end if;
  if not exists(select 1 from public.payroll_run_employees where payroll_run_id=result.id and status='calculated') then
    raise exception 'Payroll has no calculated employees' using errcode='23514';
  end if;
  select * into period_row from public.payroll_periods where id=result.payroll_period_id;
  payment_date:=period_row.payment_date;
  if not exists(
    select 1
    from public.payroll_config_sets config
    where config.id=result.config_set_id
      and config.company_id=result.company_id
      and config.status='approved'
      and payment_date between config.effective_from and coalesce(config.effective_until,'infinity'::date)
  ) then
    raise exception 'The payroll configuration is not approved or effective for the payment date' using errcode='55000';
  end if;
  select * into accounting_period_row from public.accounting_periods
  where company_id=result.company_id and payment_date between start_date and end_date and status='open'
  for update;
  if not found then raise exception 'Payroll payment date is not in an open accounting period' using errcode='55000'; end if;

  update public.payroll_runs set status='finalizing',updated_at=now(),updated_by=(select auth.uid()) where id=result.id;
  perform set_config('app.payroll_workflow','authorized',true);
  update public.payroll_input_snapshots set status='locked_in_payroll',locked_at=now()
  where payroll_run_id=result.id and status in ('validated','imported');

  select
    coalesce(sum(gross_pay),0),coalesce(sum(employee_pension),0),coalesce(sum(employer_pension),0),
    coalesce(sum(personal_income_tax),0),coalesce(sum(other_deductions),0),coalesce(sum(net_salary),0),
    coalesce(sum(employer_cost),0)
  into result.total_gross,result.total_employee_pension,result.total_employer_pension,
    result.total_tax,result.total_other_deductions,result.total_net,result.total_employer_cost
  from public.payroll_run_employees where payroll_run_id=result.id and status='calculated';

  journal_row:=public.create_journal_entry(
    result.company_id,payment_date,payment_date,'Payroll '||result.run_number,result.run_number,
    result.currency,1,result.branch_id,'automatic'
  );
  update public.journal_entries set source_type='payroll_run',source_id=result.id,source_key=result.run_number,
    metadata=jsonb_build_object('payrollRunId',result.id,'configSetId',result.config_set_id)
  where id=journal_row.id returning * into journal_row;

  line_number:=line_number+1;
  insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,branch_id,created_by)
  values(journal_row.id,result.company_id,line_number,private.payroll_mapping_account(result.company_id,'SALARY_EXPENSE',payment_date,result.branch_id),
    'Gross salaries',result.total_gross,0,result.branch_id,(select auth.uid()));
  if result.total_employer_pension<>0 then
    line_number:=line_number+1;
    insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,branch_id,created_by)
    values(journal_row.id,result.company_id,line_number,private.payroll_mapping_account(result.company_id,'EMPLOYER_PENSION_EXPENSE',payment_date,result.branch_id),
      'Employer pension expense',result.total_employer_pension,0,result.branch_id,(select auth.uid()));
  end if;
  if result.total_employee_pension<>0 then
    line_number:=line_number+1;
    insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,branch_id,created_by)
    values(journal_row.id,result.company_id,line_number,private.payroll_mapping_account(result.company_id,'EMPLOYEE_PENSION_PAYABLE',payment_date,result.branch_id),
      'Employee pension payable',0,result.total_employee_pension,result.branch_id,(select auth.uid()));
  end if;
  if result.total_employer_pension<>0 then
    line_number:=line_number+1;
    insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,branch_id,created_by)
    values(journal_row.id,result.company_id,line_number,private.payroll_mapping_account(result.company_id,'EMPLOYER_PENSION_PAYABLE',payment_date,result.branch_id),
      'Employer pension payable',0,result.total_employer_pension,result.branch_id,(select auth.uid()));
  end if;
  if result.total_tax<>0 then
    line_number:=line_number+1;
    insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,branch_id,created_by)
    values(journal_row.id,result.company_id,line_number,private.payroll_mapping_account(result.company_id,'PERSONAL_INCOME_TAX_PAYABLE',payment_date,result.branch_id),
      'Personal income tax payable',0,result.total_tax,result.branch_id,(select auth.uid()));
  end if;
  if result.total_other_deductions<>0 then
    line_number:=line_number+1;
    insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,branch_id,created_by)
    values(journal_row.id,result.company_id,line_number,private.payroll_mapping_account(result.company_id,'OTHER_DEDUCTION_PAYABLE',payment_date,result.branch_id),
      'Other payroll deductions payable',0,result.total_other_deductions,result.branch_id,(select auth.uid()));
  end if;
  line_number:=line_number+1;
  insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,branch_id,created_by)
  values(journal_row.id,result.company_id,line_number,private.payroll_mapping_account(result.company_id,'NET_SALARY_PAYABLE',payment_date,result.branch_id),
    'Net salary payable',0,result.total_net,result.branch_id,(select auth.uid()));

  journal_row:=public.post_journal_entry(journal_row.id,'Payroll finalization: '||trim(p_reason));

  for employee_row in
    select run_employee.*,employee.first_name,employee.last_name,employee.employee_number,
      employee.job_title,employee.department as employee_department
    from public.payroll_run_employees run_employee
    join public.employees employee on employee.id=run_employee.employee_id
    where run_employee.payroll_run_id=result.id and run_employee.status='calculated'
  loop
    insert into public.payroll_liabilities(
      company_id,payroll_run_id,payroll_run_employee_id,employee_id,liability_type,amount,currency,due_date,journal_entry_id
    ) values (
      result.company_id,result.id,employee_row.id,employee_row.employee_id,'net_salary',employee_row.net_salary,
      result.currency,payment_date,journal_row.id
    );
    insert into public.payslip_snapshots(
      company_id,payroll_run_id,payroll_run_employee_id,employee_id,language,verification_reference,
      snapshot,snapshot_checksum,generated_by
    )
    select
      result.company_id,result.id,employee_row.id,employee_row.employee_id,language_code,
      encode(digest(convert_to(result.id::text||':'||employee_row.employee_id::text||':'||language_code,'UTF8'),'sha256'),'hex'),
      jsonb_build_object(
        'language',language_code,
        'runNumber',result.run_number,'period',jsonb_build_object('name',period_row.name,'startsOn',period_row.starts_on,'endsOn',period_row.ends_on,'paymentDate',payment_date),
        'company',(select jsonb_build_object(
          'legalName',coalesce(company.company_name,company.name),
          'tradeName',company.trade_name,
          'fiscalNumber',company.fiscal_number,
          'uniqueBusinessNumber',company.unique_business_number,
          'vatNumber',company.vat_number,
          'address',coalesce(company.registered_address,company.address),
          'municipality',company.municipality,
          'country',coalesce(company.country_code,company.country),
          'email',company.email,
          'phone',company.phone,
          'logoUrl',company.logo_url
        ) from public.companies company where company.id=result.company_id),
        'employee',jsonb_build_object('id',employee_row.employee_id,'employeeNumber',employee_row.employee_number,'firstName',employee_row.first_name,'lastName',employee_row.last_name,'position',employee_row.job_title,'department',coalesce(employee_row.employee_department,employee_row.department)),
        'currency',result.currency,'grossPay',employee_row.gross_pay,'employeePension',employee_row.employee_pension,
        'employerPension',employee_row.employer_pension,'personalIncomeTax',employee_row.personal_income_tax,
        'otherDeductions',employee_row.other_deductions,'netSalary',employee_row.net_salary,
        'employerCost',employee_row.employer_cost,
        'lines',(select coalesce(jsonb_agg(to_jsonb(line) order by line.line_number),'[]'::jsonb) from public.payroll_calculation_lines line where line.payroll_run_employee_id=employee_row.id),
        'configSetId',result.config_set_id,'finalizedAt',now()
      ),
      encode(digest(convert_to(jsonb_build_object('run',result.id,'employee',employee_row.id,'net',employee_row.net_salary,'language',language_code)::text,'UTF8'),'sha256'),'hex'),
      (select auth.uid())
    from unnest(array['sq'::text,'en'::text]) language_code;
    update public.payroll_run_employees set status='finalized',finalized_at=now() where id=employee_row.id;
  end loop;
  insert into public.payroll_liabilities(company_id,payroll_run_id,liability_type,amount,currency,due_date,journal_entry_id)
  select result.company_id,result.id,kind,amount,result.currency,payment_date,journal_row.id
  from (values
    ('employee_pension'::text,result.total_employee_pension),
    ('employer_pension'::text,result.total_employer_pension),
    ('personal_income_tax'::text,result.total_tax),
    ('other_deduction'::text,result.total_other_deductions)
  ) liability(kind,amount) where amount>0;

  update public.payroll_runs set status='finalized',journal_entry_id=journal_row.id,input_locked_at=now(),
    finalized_at=now(),finalized_by=(select auth.uid()),total_gross=result.total_gross,
    total_employee_pension=result.total_employee_pension,total_employer_pension=result.total_employer_pension,
    total_tax=result.total_tax,total_other_deductions=result.total_other_deductions,total_net=result.total_net,
    total_employer_cost=result.total_employer_cost,updated_at=now(),updated_by=(select auth.uid())
  where id=result.id returning * into result;
  perform private.record_payroll_audit(result.company_id,result.branch_id,'payroll.run.finalized','payroll_run',result.id,null,
    jsonb_build_object('runNumber',result.run_number,'journalEntryId',journal_row.id,'totalNet',result.total_net),p_reason);
  perform private.emit_domain_outbox_event(result.company_id,result.branch_id,'payroll_run',result.id,'payroll.run.finalized',
    jsonb_build_object('runNumber',result.run_number,'journalEntryId',journal_row.id,'totalNet',result.total_net),
    p_idempotency_key||':finalized');
  return result;
end $$;


--
-- Name: generate_company_invite_token(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_company_invite_token(company_uuid uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  new_token text;
begin
  if not exists (
    select 1 from memberships
    where user_id = auth.uid()
      and company_id = company_uuid
      and role in ('owner', 'admin')
  ) then
    raise exception 'Not authorized to generate invite token';
  end if;

  new_token := upper(substring(md5(random()::text || clock_timestamp()::text) from 1 for 8));

  update companies
  set invite_token = new_token
  where id = company_uuid;

  return new_token;
end;
$$;


--
-- Name: generate_company_payroll(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_company_payroll(p_company_id uuid, p_start_date date, p_end_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  employee_row record;
  generated_count integer := 0;
begin
  perform private.require_operix_product_access(p_company_id, 'hr');

  if not exists (
    select 1
    from public.memberships membership
    where membership.company_id = p_company_id
      and membership.user_id = (select auth.uid())
      and membership.role in ('owner', 'admin', 'manager')
      and coalesce(membership.status, 'active') in ('active', 'approved')
  ) then
    raise exception 'Access denied: manager membership is required' using errcode = '42501';
  end if;

  for employee_row in
    select employee.id, employee.base_salary
    from public.employees employee
    where employee.company_id = p_company_id
      and employee.status = 'active'
  loop
    if not exists (
      select 1
      from public.payrolls payroll
      where payroll.employee_id = employee_row.id
        and payroll.period_start = p_start_date
        and payroll.period_end = p_end_date
    ) then
      insert into public.payrolls(
        employee_id,
        company_id,
        period_start,
        period_end,
        base_salary,
        bonus,
        deductions,
        expenses_reimbursed,
        total_payout,
        status
      ) values (
        employee_row.id,
        p_company_id,
        p_start_date,
        p_end_date,
        employee_row.base_salary,
        0,
        0,
        0,
        employee_row.base_salary,
        'draft'
      );
      generated_count := generated_count + 1;
    end if;
  end loop;

  return jsonb_build_object('success', true, 'generated_count', generated_count);
end;
$$;


--
-- Name: generate_kosovo_tax_calendar(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_kosovo_tax_calendar(p_company_id uuid, p_year integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare inserted_count integer := 0; v_period_start date; v_period_end date; v_due_date date;
begin
  if not (select private.has_company_permission(p_company_id, 'tax.calendar.manage')) then
    raise exception 'Insufficient permission to generate tax calendar' using errcode = '42501';
  end if;
  for month_index in 1..12 loop
    v_period_start := make_date(p_year, month_index, 1);
    v_period_end := (v_period_start + interval '1 month - 1 day')::date;
    v_due_date := (v_period_end + interval '1 month')::date;
    if exists(select 1 from public.companies where id=p_company_id and vat_registration_status <> 'not_registered') then
      insert into public.tax_calendar_events(company_id,tax_type,period_start,period_end,due_date,title,source_reference,created_by)
      values(p_company_id,'vat',v_period_start,v_period_end,make_date(extract(year from v_due_date)::integer,extract(month from v_due_date)::integer,20),'VAT declaration',
        'https://www.atk-ks.org/en/portfolio/informata-te-pergjithshme-per-tatimet-ne-kosove/',(select auth.uid()))
      on conflict (company_id,tax_type,period_start,period_end) do update set due_date=excluded.due_date;
      inserted_count := inserted_count + 1;
      insert into public.tax_calendar_events(company_id,tax_type,period_start,period_end,due_date,title,source_reference,created_by)
      values(p_company_id,'sales_book',v_period_start,v_period_end,make_date(extract(year from v_due_date)::integer,extract(month from v_due_date)::integer,20),'Libri i Shitjes',
        'https://www.atk-ks.org/en/librat-e-blerjes-dhe-te-shitjes/',(select auth.uid()))
      on conflict (company_id,tax_type,period_start,period_end) do update set due_date=excluded.due_date;
      insert into public.tax_calendar_events(company_id,tax_type,period_start,period_end,due_date,title,source_reference,created_by)
      values(p_company_id,'purchase_book',v_period_start,v_period_end,make_date(extract(year from v_due_date)::integer,extract(month from v_due_date)::integer,20),'Libri i Blerjes',
        'https://www.atk-ks.org/en/librat-e-blerjes-dhe-te-shitjes/',(select auth.uid()))
      on conflict (company_id,tax_type,period_start,period_end) do update set due_date=excluded.due_date;
    end if;
    if exists(select 1 from public.employees where company_id=p_company_id and status='active') then
      insert into public.tax_calendar_events(company_id,tax_type,period_start,period_end,due_date,title,source_reference,created_by)
      values(p_company_id,'payroll_withholding',v_period_start,v_period_end,make_date(extract(year from v_due_date)::integer,extract(month from v_due_date)::integer,15),'Payroll withholding and pension',
        'https://crmm.atk-ks.org/en/Public/GuideInteractivityAnswers/7a53613a-cb62-4671-2fde-08dba4862e41',(select auth.uid()))
      on conflict (company_id,tax_type,period_start,period_end) do update set due_date=excluded.due_date;
    end if;
  end loop;
  insert into public.tax_calendar_events(company_id,tax_type,period_start,period_end,due_date,title,source_reference,created_by)
  values
    (p_company_id,'personal_income_tax',make_date(p_year,1,1),make_date(p_year,12,31),make_date(p_year+1,3,31),'Annual PIT information',
      'https://www.atk-ks.org/en/portfolio/informata-te-pergjithshme-per-tatimet-ne-kosove/',(select auth.uid())),
    (p_company_id,'corporate_tax',make_date(p_year,1,1),make_date(p_year,12,31),make_date(p_year+1,3,31),'Annual corporate/business tax information',
      'https://www.atk-ks.org/en/portfolio/informata-te-pergjithshme-per-tatimet-ne-kosove/',(select auth.uid()))
  on conflict (company_id,tax_type,period_start,period_end) do update set due_date=excluded.due_date;
  return inserted_count;
end
$$;


--
-- Name: generate_recurring_journal(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_recurring_journal(p_template_id uuid, p_posting_date date DEFAULT CURRENT_DATE) RETURNS public.journal_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  template_row public.recurring_journal_templates;
  entry_row public.journal_entries;
begin
  select * into template_row
  from public.recurring_journal_templates
  where id = p_template_id
  for update;
  if not found or not template_row.active then
    raise exception 'Active recurring journal template not found' using errcode = 'P0002';
  end if;
  if not (select private.has_company_permission(template_row.company_id, 'journal.create')) then
    raise exception 'Insufficient permission to generate journals' using errcode = '42501';
  end if;

  entry_row := public.create_journal_entry(
    template_row.company_id, p_posting_date, p_posting_date,
    template_row.name, template_row.code, template_row.currency, 1, null, 'recurring'
  );
  insert into public.journal_entry_lines (
    journal_entry_id, company_id, line_number, account_id, description,
    debit, credit, cost_centre_id, project_id, created_by
  )
  select
    entry_row.id, line.company_id, line.line_number, line.account_id,
    line.description, line.debit, line.credit, line.cost_centre_id,
    line.project_id, (select auth.uid())
  from public.recurring_journal_template_lines line
  where line.template_id = p_template_id
  order by line.line_number;

  update public.recurring_journal_templates
  set
    next_run_date = case frequency
      when 'weekly' then next_run_date + 7
      when 'monthly' then (next_run_date + interval '1 month')::date
      when 'quarterly' then (next_run_date + interval '3 months')::date
      else (next_run_date + interval '1 year')::date
    end,
    updated_at = clock_timestamp(),
    updated_by = (select auth.uid())
  where id = p_template_id;
  return entry_row;
end
$$;


--
-- Name: get_customer_portal_data(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_portal_data(portal_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  portal customer_portal_tokens%rowtype;
  result jsonb;
begin
  select * into portal
  from customer_portal_tokens
  where token = portal_token
    and (expires_at is null or expires_at > now());
  if not found then
    return jsonb_build_object('error', 'This customer portal link is invalid or expired.');
  end if;

  update customer_portal_tokens set last_used_at = now() where id = portal.id;

  select jsonb_build_object(
    'company', (
      select jsonb_build_object(
        'company_name', company.company_name,
        'name', coalesce(company.name, company.company_name),
        'email', company.email,
        'phone', company.phone,
        'address', company.address,
        'city', company.city,
        'country', company.country,
        'website', company.website,
        'logo_url', company.logo_url,
        'signature_url', company.signature_url,
        'stamp_url', company.stamp_url,
        'tax_id', company.tax_id,
        'bank_name', company.bank_name,
        'bank_iban', company.bank_iban
      ) from companies company where company.id = portal.company_id
    ),
    'client', (
      select jsonb_build_object(
        'id', client.id,
        'name', client.name,
        'email', client.email,
        'phone', client.phone,
        'address', client.address,
        'city', client.city,
        'country', client.country,
        'tax_id', client.tax_id
      ) from clients client where client.id = portal.client_id
    ),
    'invoices', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', invoice_row.id,
        'invoice_number', invoice_row.invoice_number,
        'issue_date', invoice_row.issue_date,
        'due_date', invoice_row.due_date,
        'status', invoice_row.status,
        'total_amount', invoice_row.total_amount,
        'tax_amount', invoice_row.tax_amount,
        'amount_received', coalesce(invoice_row.amount_received, 0),
        'notes', invoice_row.notes,
        'buyer_signature_url', invoice_row.buyer_signature_url,
        'customer_signature_requested', invoice_row.customer_signature_requested,
        'customer_signature_status', invoice_row.customer_signature_status,
        'customer_signature_name', invoice_row.customer_signature_name,
        'customer_signed_at', invoice_row.customer_signed_at,
        'items', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', item.id,
            'description', item.description,
            'quantity', item.quantity,
            'unit_price', item.unit_price,
            'amount', item.amount,
            'tax_rate', item.tax_rate,
            'discount', item.discount,
            'unit', item.unit,
            'sku', item.sku
          ) order by item.id)
          from invoice_items item where item.invoice_id = invoice_row.id
        ), '[]'::jsonb)
      ) order by invoice_row.issue_date desc)
      from invoices invoice_row
      where invoice_row.company_id = portal.company_id
        and invoice_row.client_id = portal.client_id
        and invoice_row.type is distinct from 'offer'
        and invoice_row.status::text not in ('cancelled', 'draft')
        and (portal.invoice_id is null or invoice_row.id = portal.invoice_id)
    ), '[]'::jsonb)
  ) into result;
  return result;
end
$$;


--
-- Name: get_effective_vat_rule(uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_effective_vat_rule(p_company_id uuid, p_code text, p_as_of date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  configuration jsonb;
  result jsonb;
begin
  if not (select private.has_company_permission(p_company_id, 'accounting.read')) then
    raise exception 'Insufficient permission to read VAT configuration' using errcode = '42501';
  end if;

  select version.configuration into configuration
  from public.compliance_config_sets config_set
  join public.compliance_config_versions version on version.config_set_id = config_set.id
  where config_set.company_id = p_company_id
    and config_set.config_type = 'vat_rates'
    and version.status = 'active'
    and version.effective_from <= coalesce(p_as_of, current_date)
    and (version.effective_until is null or version.effective_until >= coalesce(p_as_of, current_date))
  order by version.version desc, version.effective_from desc
  limit 1;

  if configuration is null then
    return null;
  end if;

  select value into result
  from jsonb_array_elements(coalesce(configuration -> 'rates', '[]'::jsonb)) value
  where value ->> 'code' = p_code
  limit 1;
  return result;
end
$$;


--
-- Name: get_efs_readiness(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_efs_readiness(p_company_id uuid, p_installation_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  installation_row public.fiscal_installations;
  certificate_valid boolean := false;
  key_available boolean := false;
  production_flag boolean := false;
  software_configured boolean := false;
  customer_configured boolean := false;
begin
  if not private.has_company_permission(p_company_id, 'pos.fiscal.view') then
    raise exception 'Insufficient permission to view EFS readiness' using errcode = '42501';
  end if;
  select * into installation_row
  from public.fiscal_installations
  where company_id = p_company_id
    and (p_installation_id is null or id = p_installation_id)
  order by updated_at desc
  limit 1;

  if installation_row.id is null then
    return jsonb_build_object(
      'status', 'not_configured',
      'production_enabled', false,
      'certification_status', 'EFS NOT CERTIFIED',
      'checks', jsonb_build_object(
        'taxpayer_configuration', false,
        'business_unit', false,
        'pos', false,
        'software_solution_code', false,
        'fiscalization_number', false,
        'certificate', false,
        'private_key_provider', false,
        'tak_connectivity', false,
        'receipt_renderer', true,
        'qr_validation', false,
        'accounting', true,
        'vat', true
      )
    );
  end if;

  customer_configured := installation_row.taxpayer_identifier is not null
    and installation_row.unique_fiscalization_code is not null;
  software_configured := installation_row.software_solution_code is not null
    and installation_row.fiscalization_number is not null;
  key_available := installation_row.signing_key_reference is not null;
  select exists (
    select 1 from public.fiscal_certificates certificate
    where certificate.installation_id = installation_row.id
      and certificate.company_id = p_company_id
      and certificate.status = 'active'
      and (certificate.valid_from is null or certificate.valid_from <= clock_timestamp())
      and (certificate.valid_until is null or certificate.valid_until > clock_timestamp())
  ) into certificate_valid;
  select coalesce(flag.enabled, false) into production_flag
  from public.company_feature_flags flag
  where flag.company_id = p_company_id
    and flag.flag = 'kosovo_efs_production_enabled';

  return jsonb_build_object(
    'status', installation_row.status,
    'certification_status', 'EFS NOT CERTIFIED',
    'production_enabled', false,
    'checks', jsonb_build_object(
      'taxpayer_configuration', customer_configured,
      'business_unit', installation_row.business_unit_number is not null,
      'pos', installation_row.pos_number is not null,
      'software_solution_code', software_configured,
      'fiscalization_number', installation_row.fiscalization_number is not null,
      'certificate', certificate_valid,
      'private_key_provider', key_available,
      'tak_connectivity', false,
      'receipt_renderer', true,
      'qr_validation', false,
      'accounting', true,
      'vat', true
    ),
    'blockers', jsonb_build_array(
      case when not customer_configured then 'TAK taxpayer Unique Fiscalization Code is not configured.' end,
      case when not software_configured then 'TAK Software Solution Code/Fiscalization Number is not configured.' end,
      case when not certificate_valid then 'A valid TAK certificate is not configured.' end,
      case when not key_available then 'A production-safe signing key provider is not configured.' end,
      'TAK technical contract and certification are pending; production fiscalization is disabled.'
    ),
    'stored_production_flag', production_flag
  );
end
$$;


