CREATE FUNCTION public.get_invoice_billing_summary(p_company_id uuid) RETURNS TABLE(company_id uuid, billing_account_company_id uuid, product text, stripe_customer_id text, stripe_subscription_id text, status text, billing_interval text, trial_started_at timestamp with time zone, trial_ends_at timestamp with time zone, current_period_start timestamp with time zone, current_period_end timestamp with time zone, cancel_at_period_end boolean, grace_period_ends_at timestamp with time zone, total_tenants integer, included_tenants integer, billable_tenants integer, total_users integer, included_users integer, billable_users integer, estimated_monthly_total numeric, estimated_annual_total numeric, restricted boolean, billing_management_allowed boolean, usage_updated_at timestamp with time zone)
