--
-- Name: get_my_product_access(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_product_access(p_product text) RETURNS TABLE(company_id uuid, product text, entitled boolean, role_allowed boolean, allowed boolean, source text, starts_at timestamp with time zone, ends_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  requested_product text := lower(trim(coalesce(p_product, '')));
  selected_company_id uuid;
  root_company_id uuid;
  entitled_now boolean := false;
  role_allowed_now boolean := false;
  entitlement_row record;
begin
  if (select auth.uid()) is null then return; end if;
  if requested_product not in ('invoice', 'booking', 'hr', 'desk') then
    raise exception 'Unsupported product' using errcode = '22023';
  end if;

  select coalesce(profile.active_company_id, profile.company_id)
    into selected_company_id
  from public.profiles profile
  where profile.id = (select auth.uid());
  if selected_company_id is null then
    select membership.company_id into selected_company_id
    from public.memberships membership
    where membership.user_id = (select auth.uid())
      and coalesce(membership.status, 'active') = 'active'
    order by membership.created_at asc
    limit 1;
  end if;
  if selected_company_id is null or not public.can_access_company(selected_company_id) then
    return query select null::uuid, requested_product, false, false, false, null::text, null::timestamptz, null::timestamptz;
    return;
  end if;

  root_company_id := private.invoice_billing_root_company_id(selected_company_id);
  entitled_now := private.operix_product_access(root_company_id, requested_product);
  select entitlement.source, entitlement.starts_at, entitlement.ends_at
    into entitlement_row
  from public.organization_product_entitlements entitlement
  where entitlement.company_id = root_company_id
    and entitlement.product = requested_product
    and entitlement.enabled
    and entitlement.starts_at <= now()
    and (entitlement.ends_at is null or entitlement.ends_at > now())
  order by case when entitlement.source = 'enterprise_contract' then 0 when entitlement.source = 'manual_grant' then 1 else 2 end, entitlement.starts_at desc
  limit 1;

  if requested_product in ('invoice', 'booking') then
    role_allowed_now := true;
  else
    role_allowed_now := exists (
      select 1
      from public.app_permissions permission
      where permission.category = requested_product
        and private.has_company_permission(root_company_id, permission.code)
    );
  end if;

  return query select root_company_id, requested_product, entitled_now, role_allowed_now,
    entitled_now and role_allowed_now, entitlement_row.source, entitlement_row.starts_at, entitlement_row.ends_at;
end;
$$;


--
-- Name: get_product_billing_summary(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_product_billing_summary(p_company_id uuid, p_product text) RETURNS TABLE(company_id uuid, billing_account_company_id uuid, requested_product text, plan text, product text, entitlements jsonb, stripe_customer_id text, stripe_subscription_id text, status text, billing_interval text, trial_started_at timestamp with time zone, trial_ends_at timestamp with time zone, current_period_start timestamp with time zone, current_period_end timestamp with time zone, cancel_at_period_end boolean, grace_period_ends_at timestamp with time zone, scheduled_plan text, scheduled_change_at timestamp with time zone, total_tenants integer, included_tenants integer, billable_tenants integer, total_users integer, included_users integer, billable_users integer, estimated_monthly_total numeric, estimated_annual_total numeric, restricted boolean, billing_management_allowed boolean, usage_updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  root_company_id uuid;
  account_row public.subscription_accounts;
  usage_row public.subscription_usage;
  requested text := lower(trim(coalesce(p_product, '')));
  access boolean;
  plan_value text;
  monthly_value numeric := null;
  annual_value numeric := null;
  entitlement_json jsonb;
  manual_status text;
begin
  if requested not in ('invoice', 'booking', 'suite', 'hr', 'desk') then
    raise exception 'Unsupported OperiX product' using errcode = '22023';
  end if;
  if not public.can_access_company(p_company_id) then
    raise exception 'Company access denied' using errcode = '42501';
  end if;

  root_company_id := private.invoice_billing_root_company_id(p_company_id);
  if requested in ('invoice', 'booking', 'suite') then
    perform private.ensure_operix_product_trial(root_company_id, requested);
    -- Entitlement projection writes belong to the server/webhook path. A
    -- tenant summary read must not become a client-controlled write path.
    if private.operix_server_request() then
      perform public.billing_refresh_product_entitlements(root_company_id);
    end if;
  end if;

  select usage.* into usage_row from public.subscription_usage usage where usage.company_id = root_company_id;
  select account.* into account_row
  from public.subscription_accounts account
  where account.company_id = root_company_id
    and (
      account.product = requested
      or (requested in ('invoice', 'booking') and account.product = 'suite')
    )
  order by case when private.operix_status_has_access(account.status, account.trial_ends_at, account.current_period_end, account.grace_period_ends_at, account.manual_override_status, account.manual_override_expires_at) then 0 else 1 end,
           case when account.product = requested then 0 else 1 end,
           account.updated_at desc
  limit 1;

  select coalesce(jsonb_object_agg(products.product, coalesce(entitlement.enabled, false)), '{}'::jsonb)
    into entitlement_json
  from (values ('invoice'::text), ('booking'::text), ('hr'::text), ('desk'::text)) products(product)
  left join lateral (
    select true as enabled
    from public.organization_product_entitlements entitlement
    where entitlement.company_id = root_company_id
      and entitlement.product = products.product
      and entitlement.enabled
      and entitlement.starts_at <= now()
      and (entitlement.ends_at is null or entitlement.ends_at > now())
    limit 1
  ) entitlement on true;

  access := private.operix_product_access(root_company_id, requested);
  select coalesce(grant_row.override_status, 'active') into manual_status
  from public.subscription_manual_grants grant_row
  where grant_row.company_id = root_company_id
    and (grant_row.product = requested or (grant_row.product = 'suite' and requested in ('invoice', 'booking')))
    and grant_row.revoked_at is null
    and (grant_row.expires_at is null or grant_row.expires_at > now())
    and coalesce(grant_row.override_status, 'active') in ('active', 'trialing')
  order by case when grant_row.product = requested then 0 else 1 end, grant_row.created_at desc
  limit 1;

  plan_value := case
    when manual_status is not null and access and requested = 'suite' then 'suite'
    when account_row.id is not null then account_row.product
    when manual_status is not null and access and requested in ('invoice', 'booking') then requested
    when access and requested in ('hr', 'desk') then 'enterprise'
    else null
  end;

  if plan_value in ('invoice', 'booking', 'suite') then
    monthly_value := private.operix_plan_value(plan_value, 'monthly', coalesce(usage_row.billable_tenants, 0), coalesce(usage_row.billable_users, 0));
    annual_value := private.operix_plan_value(plan_value, 'annual', coalesce(usage_row.billable_tenants, 0), coalesce(usage_row.billable_users, 0));
  end if;

  return query select
    p_company_id,
    root_company_id,
    requested,
    plan_value,
    plan_value,
    entitlement_json,
    case when private.rbac_is_platform_admin() then account_row.stripe_customer_id else null end,
    case when private.rbac_is_platform_admin() then account_row.stripe_subscription_id else null end,
    coalesce(manual_status, private.operix_effective_status(account_row.status, account_row.trial_ends_at, account_row.current_period_end, account_row.grace_period_ends_at, account_row.manual_override_status, account_row.manual_override_expires_at), case when access then 'active' else 'expired' end),
    account_row.billing_interval,
    account_row.trial_started_at,
    account_row.trial_ends_at,
    account_row.current_period_start,
    account_row.current_period_end,
    coalesce(account_row.cancel_at_period_end, false),
    account_row.grace_period_ends_at,
    account_row.scheduled_plan,
    account_row.scheduled_change_at,
    coalesce(usage_row.total_tenants, 0),
    1,
    coalesce(usage_row.billable_tenants, 0),
    coalesce(usage_row.total_users, 0),
    1,
    coalesce(usage_row.billable_users, 0),
    monthly_value,
    annual_value,
    not access,
    private.has_company_permission(root_company_id, 'billing.manage'),
    usage_row.last_synced_at;
end;
$$;


--
-- Name: get_product_entitlements(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_product_entitlements(p_company_id uuid) RETURNS TABLE(product text, enabled boolean, source text, starts_at timestamp with time zone, ends_at timestamp with time zone, metadata jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  root_company_id uuid;
begin
  if not public.can_access_company(p_company_id) then
    raise exception 'Company access denied' using errcode = '42501';
  end if;
  root_company_id := private.invoice_billing_root_company_id(p_company_id);
  return query
  select entitlement.product, entitlement.enabled, entitlement.source, entitlement.starts_at, entitlement.ends_at, entitlement.metadata
  from public.organization_product_entitlements entitlement
  where entitlement.company_id = root_company_id
    and entitlement.enabled
    and entitlement.starts_at <= now()
    and (entitlement.ends_at is null or entitlement.ends_at > now())
  order by entitlement.product, entitlement.starts_at desc;
end;
$$;


--
-- Name: get_stripe_store_secret(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_stripe_store_secret(p_stripe_store_id uuid) RETURNS TABLE(access_token text, refresh_token text, livemode boolean)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select secret.access_token, secret.refresh_token, secret.livemode
  from private.stripe_store_secrets secret
  where secret.stripe_store_id = p_stripe_store_id
$$;


