--
-- Name: hold_pos_order(uuid, uuid, uuid, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hold_pos_order(p_company_id uuid, p_terminal_id uuid, p_customer_id uuid, p_cart_snapshot jsonb, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS public.held_orders
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  terminal_row public.pos_terminals;
  held_row public.held_orders;
begin
  if not (select private.has_company_permission(p_company_id, 'pos.order.hold')) then
    raise exception 'Insufficient permission to hold POS orders' using errcode = '42501';
  end if;
  if not coalesce((
    select flag.enabled
    from public.company_feature_flags flag
    where flag.company_id = p_company_id and flag.flag = 'persisted_held_orders_enabled'
  ), false) then
    raise exception 'Persisted held orders are not enabled for this company' using errcode = '55000';
  end if;
  if jsonb_typeof(p_cart_snapshot) <> 'object'
     or jsonb_typeof(p_cart_snapshot -> 'items') <> 'array'
     or jsonb_array_length(p_cart_snapshot -> 'items') = 0 then
    raise exception 'A held order requires a non-empty item snapshot' using errcode = '23514';
  end if;

  terminal_row := private.assert_cashier_shift_access(p_company_id, p_terminal_id);
  if p_customer_id is not null and not exists (
    select 1 from public.clients
    where id = p_customer_id and company_id = p_company_id
  ) then
    raise exception 'Held-order customer does not belong to this company' using errcode = '23514';
  end if;

  insert into public.held_orders (
    company_id, branch_id, terminal_id, warehouse_id, cashier_id, customer_id,
    cart_snapshot, expires_at, created_by, updated_by
  )
  values (
    p_company_id, terminal_row.branch_id, terminal_row.id, terminal_row.warehouse_id,
    (select auth.uid()), p_customer_id, p_cart_snapshot, p_expires_at,
    (select auth.uid()), (select auth.uid())
  )
  returning * into held_row;

  perform private.emit_domain_outbox_event(
    p_company_id, terminal_row.branch_id, 'held_order', held_row.id,
    'pos_order.held', jsonb_build_object('terminal_id', terminal_row.id),
    'pos_order.held:' || held_row.id::text
  );
  return held_row;
end
$$;


--
-- Name: bank_statement_transactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_statement_transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    reconciliation_id uuid NOT NULL,
    company_bank_account_id uuid NOT NULL,
    external_id text,
    transaction_date date NOT NULL,
    description text,
    reference text,
    amount numeric(20,4) NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    status text DEFAULT 'unmatched'::text NOT NULL,
    matched_journal_entry_id uuid,
    imported_at timestamp with time zone DEFAULT now() NOT NULL,
    imported_by uuid,
    matched_at timestamp with time zone,
    matched_by uuid,
    CONSTRAINT bank_statement_transactions_status_check CHECK ((status = ANY (ARRAY['unmatched'::text, 'matched'::text, 'ignored'::text])))
);


--
-- Name: import_bank_statement_transaction(uuid, text, date, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_bank_statement_transaction(p_reconciliation_id uuid, p_external_id text, p_transaction_date date, p_description text, p_reference text, p_amount numeric, p_currency text DEFAULT 'EUR'::text) RETURNS public.bank_statement_transactions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare reconciliation_row public.bank_reconciliations; result public.bank_statement_transactions;
begin
  select * into reconciliation_row from public.bank_reconciliations where id=p_reconciliation_id for update;
  if not found then raise exception 'Bank reconciliation not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(reconciliation_row.company_id,'bank.reconcile')) then raise exception 'Insufficient permission to import bank statement' using errcode='42501'; end if;
  if reconciliation_row.status='completed' then raise exception 'Completed reconciliation cannot be modified' using errcode='55000'; end if;
  insert into public.bank_statement_transactions(company_id,reconciliation_id,company_bank_account_id,external_id,transaction_date,description,reference,amount,currency,imported_by)
  values(reconciliation_row.company_id,reconciliation_row.id,reconciliation_row.company_bank_account_id,p_external_id,p_transaction_date,p_description,p_reference,round(p_amount,4),upper(coalesce(p_currency,'EUR')),(select auth.uid()))
  on conflict(company_id,company_bank_account_id,external_id) do update set description=excluded.description,reference=excluded.reference,amount=excluded.amount,transaction_date=excluded.transaction_date
  returning * into result;
  return result;
end
$$;


--
-- Name: payroll_input_snapshots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_input_snapshots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    payroll_run_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    input_type text NOT NULL,
    source_application text NOT NULL,
    source_record_ids text[] DEFAULT '{}'::text[] NOT NULL,
    source_approved boolean DEFAULT false NOT NULL,
    source_timestamp timestamp with time zone,
    imported_at timestamp with time zone DEFAULT now() NOT NULL,
    imported_by uuid,
    configuration_version text,
    status text DEFAULT 'pending'::text NOT NULL,
    payload jsonb NOT NULL,
    checksum text NOT NULL,
    locked_at timestamp with time zone,
    CONSTRAINT payroll_input_snapshots_input_type_check CHECK ((input_type = ANY (ARRAY['employee'::text, 'contract'::text, 'compensation'::text, 'tax'::text, 'pension'::text, 'attendance'::text, 'leave'::text, 'overtime'::text, 'earning'::text, 'deduction'::text]))),
    CONSTRAINT payroll_input_snapshots_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT payroll_input_snapshots_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'imported'::text, 'validated'::text, 'rejected'::text, 'superseded'::text, 'locked_in_payroll'::text])))
);


--
-- Name: import_payroll_inputs(uuid, uuid, text, text, text[], boolean, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_payroll_inputs(p_payroll_run_id uuid, p_employee_id uuid, p_input_type text, p_source_application text, p_source_record_ids text[], p_source_approved boolean, p_source_timestamp timestamp with time zone, p_configuration_version text, p_payload jsonb) RETURNS public.payroll_input_snapshots
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions', 'pg_catalog'
    AS $$
declare run_row public.payroll_runs; result public.payroll_input_snapshots; checksum_value text;
begin
  select * into run_row from public.payroll_runs where id=p_payroll_run_id for update;
  if not found then raise exception 'Payroll run not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(run_row.company_id,'payroll.hr_inputs.import')) then
    raise exception 'Insufficient permission to import payroll inputs' using errcode='42501';
  end if;
  if run_row.status not in ('draft','collecting_inputs','calculated','calculation_failed') then
    raise exception 'Payroll inputs cannot be changed in state %',run_row.status using errcode='55000';
  end if;
  if p_source_application<>'operix_invoice' and not (select private.payroll_feature_enabled(run_row.company_id,'payroll_hr_import_enabled')) then
    raise exception 'HR payroll input import is disabled' using errcode='42501';
  end if;
  checksum_value:=encode(digest(convert_to(coalesce(p_payload,'{}'::jsonb)::text,'UTF8'),'sha256'),'hex');
  update public.payroll_input_snapshots set status='superseded'
  where payroll_run_id=p_payroll_run_id and employee_id=p_employee_id and input_type=p_input_type
    and status not in ('superseded','locked_in_payroll');
  insert into public.payroll_input_snapshots(
    company_id,payroll_run_id,employee_id,input_type,source_application,source_record_ids,
    source_approved,source_timestamp,imported_by,configuration_version,status,payload,checksum
  ) values (
    run_row.company_id,p_payroll_run_id,p_employee_id,p_input_type,p_source_application,
    coalesce(p_source_record_ids,'{}'),p_source_approved,p_source_timestamp,(select auth.uid()),
    p_configuration_version,case when p_source_approved then 'validated' else 'imported' end,
    coalesce(p_payload,'{}'::jsonb),checksum_value
  ) returning * into result;
  update public.payroll_runs set status='collecting_inputs',updated_at=now(),updated_by=(select auth.uid())
  where id=p_payroll_run_id;
  perform private.record_payroll_audit(run_row.company_id,run_row.branch_id,'payroll.input.imported','payroll_input_snapshot',result.id,null,
    jsonb_build_object('inputType',p_input_type,'sourceApplication',p_source_application,'checksum',checksum_value),null);
  return result;
end $$;


--
-- Name: initialize_company_accounting(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.initialize_company_accounting(p_company_id uuid, p_fiscal_year_start date DEFAULT (date_trunc('year'::text, (CURRENT_DATE)::timestamp with time zone))::date, p_template_code text DEFAULT 'xk-operix-base-v1'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_template_id uuid;
  v_fiscal_year_id uuid;
  period_start date;
  period_end date;
  v_period_number integer;
  created_accounts integer := 0;
begin
  if not (select private.has_company_permission(p_company_id, 'accounts.manage')) then
    raise exception 'Insufficient permission to initialize accounting' using errcode = '42501';
  end if;
  if p_fiscal_year_start is null then
    raise exception 'Fiscal year start is required' using errcode = '22004';
  end if;

  select id into v_template_id
  from public.accounting_account_templates
  where code = p_template_code and active;
  if v_template_id is null then
    raise exception 'Accounting template not found' using errcode = 'P0002';
  end if;

  insert into public.chart_of_accounts (
    company_id, code, name, account_type, normal_balance, posting_allowed,
    currency, tax_mapping, statement_mapping, template_line_id, created_by, updated_by
  )
  select
    p_company_id, line.account_code, line.account_name, line.account_type,
    line.normal_balance, line.posting_allowed, 'EUR', line.tax_mapping,
    line.statement_mapping, line.id, (select auth.uid()), (select auth.uid())
  from public.accounting_account_template_lines line
  where line.template_id = v_template_id
  on conflict (company_id, code) do nothing;
  get diagnostics created_accounts = row_count;

  update public.chart_of_accounts account
  set parent_account_id = parent.id
  from public.accounting_account_template_lines line
  join public.accounting_account_template_lines parent_line
    on parent_line.template_id = line.template_id
   and parent_line.account_code = line.parent_code
  join public.chart_of_accounts parent
    on parent.company_id = p_company_id
   and parent.code = parent_line.account_code
  where account.company_id = p_company_id
    and account.template_line_id = line.id
    and line.template_id = v_template_id
    and line.parent_code is not null
    and account.parent_account_id is distinct from parent.id;

  insert into public.accounting_fiscal_years (
    company_id, name, start_date, end_date, created_by, updated_by
  )
  values (
    p_company_id,
    extract(year from p_fiscal_year_start)::text,
    p_fiscal_year_start,
    (p_fiscal_year_start + interval '1 year - 1 day')::date,
    (select auth.uid()),
    (select auth.uid())
  )
  on conflict (company_id, start_date, end_date)
  do update set name = excluded.name
  returning id into v_fiscal_year_id;

  for v_period_number in 1..12 loop
    period_start := (p_fiscal_year_start + make_interval(months => v_period_number - 1))::date;
    period_end := (p_fiscal_year_start + make_interval(months => v_period_number) - interval '1 day')::date;
    insert into public.accounting_periods (
      company_id, fiscal_year_id, period_number, name, start_date, end_date,
      created_by, updated_by
    )
    values (
      p_company_id, v_fiscal_year_id, v_period_number,
      to_char(period_start, 'YYYY-MM'), period_start, period_end,
      (select auth.uid()), (select auth.uid())
    )
    on conflict (fiscal_year_id, period_number) do nothing;
  end loop;

  perform private.seed_default_posting_rules(p_company_id, p_fiscal_year_start);

  return jsonb_build_object(
    'template', p_template_code,
    'accounts_created', created_accounts,
    'fiscal_year_id', v_fiscal_year_id
  );
end
$$;


--
-- Name: is_company_manager_or_higher(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_company_manager_or_higher(p_company_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from memberships
    where company_id = p_company_id
      and user_id = auth.uid()
      and role in ('owner', 'admin', 'manager')
  );
$$;


--
-- Name: is_company_owner(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_company_owner(p_company_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.memberships
    where company_id = p_company_id
      and user_id = auth.uid()
      and role in ('owner', 'admin')
      and coalesce(status, 'active') <> 'revoked'
  );
$$;


--
-- Name: join_company(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.join_company(token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target_company_id uuid;
  target_company_name text;
  new_employee_id uuid;
  user_email text;
  user_name text;
  current_user_id uuid := (select auth.uid());
begin
  if current_user_id is null then
    return jsonb_build_object('success', false, 'error', 'Authentication required');
  end if;

  select company.id, coalesce(company.name, company.company_name)
    into target_company_id, target_company_name
  from public.companies company
  where company.invite_token = token;

  if target_company_id is null then
    return jsonb_build_object('success', false, 'error', 'Invalid or expired invitation token');
  end if;

  if exists (
    select 1 from public.memberships membership
    where membership.user_id = current_user_id
      and membership.company_id = target_company_id
  ) then
    return jsonb_build_object('success', false, 'error', 'You are already a member of this team');
  end if;

  select coalesce(profile.email, ''), coalesce(profile.first_name, profile.company_name, 'User')
    into user_email, user_name
  from public.profiles profile
  where profile.id = current_user_id;

  insert into public.employees (
    company_id, user_id, first_name, last_name, email, role, status
  ) values (
    target_company_id, current_user_id, coalesce(user_name, 'New'), 'Employee',
    user_email, 'employee', 'pending'
  ) returning id into new_employee_id;

  insert into public.memberships (company_id, user_id, role, status)
  values (target_company_id, current_user_id, 'employee', 'pending');

  perform set_config('app.company_link_workflow', 'authorized', true);
  perform set_config('app.active_company_switch', 'authorized', true);
  update public.profiles
  set company_id = target_company_id,
      active_company_id = target_company_id
  where id = current_user_id
    and company_id is null;

  return jsonb_build_object(
    'success', true,
    'company_id', target_company_id,
    'company_name', target_company_name,
    'employee_id', new_employee_id,
    'message', 'Your request to join ' || target_company_name || ' has been sent!'
  );
exception when others then
  return jsonb_build_object('success', false, 'error', sqlerrm);
end
$$;


--
-- Name: commercial_document_payment_links; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commercial_document_payment_links (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    document_id uuid NOT NULL,
    payment_id uuid NOT NULL,
    allocation_type text DEFAULT 'ADVANCE'::text NOT NULL,
    amount numeric(20,4) NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    accounting_status text DEFAULT 'PENDING_ADVANCE_TREATMENT'::text NOT NULL,
    vat_status text DEFAULT 'NOT_EVALUATED'::text NOT NULL,
    linked_at timestamp with time zone DEFAULT now() NOT NULL,
    linked_by uuid,
    reversed_at timestamp with time zone,
    reversed_by uuid,
    reversal_reason text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT commercial_document_payment_links_accounting_status_check CHECK ((accounting_status = ANY (ARRAY['PENDING_ADVANCE_TREATMENT'::text, 'POSTED'::text, 'REVERSED'::text]))),
    CONSTRAINT commercial_document_payment_links_allocation_type_check CHECK ((allocation_type = 'ADVANCE'::text)),
    CONSTRAINT commercial_document_payment_links_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT commercial_document_payment_links_check CHECK ((((status = 'active'::text) AND (reversed_at IS NULL) AND (reversed_by IS NULL) AND (reversal_reason IS NULL)) OR ((status = 'reversed'::text) AND (reversed_at IS NOT NULL) AND (reversed_by IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM reversal_reason), ''::text) IS NOT NULL)))),
    CONSTRAINT commercial_document_payment_links_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT commercial_document_payment_links_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT commercial_document_payment_links_status_check CHECK ((status = ANY (ARRAY['active'::text, 'reversed'::text]))),
    CONSTRAINT commercial_document_payment_links_vat_status_check CHECK ((vat_status = ANY (ARRAY['NOT_EVALUATED'::text, 'POSTED'::text, 'REVERSED'::text])))
);


--
-- Name: link_commercial_advance_payment(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_commercial_advance_payment(p_document_id uuid, p_payment_id uuid, p_amount numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text) RETURNS public.commercial_document_payment_links
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  document_row public.invoices;
  payment_row public.payments;
  existing_link public.commercial_document_payment_links;
  link_row public.commercial_document_payment_links;
  available_payment numeric(20,4);
  outstanding_document numeric(20,4);
  link_amount numeric(20,4);
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  select * into payment_row from public.payments where id = p_payment_id for update;
  if not found then
    raise exception 'Customer payment not found' using errcode = 'P0002';
  end if;
  select * into document_row from public.invoices where id = p_document_id for update;
  if not found then
    raise exception 'Commercial document not found' using errcode = 'P0002';
  end if;
  if not (select private.has_company_permission(document_row.company_id, 'customer_payment.allocate'))
     and not (select private.has_company_permission(document_row.company_id, 'sales_invoice.edit')) then
    raise exception 'Insufficient permission to link an advance payment' using errcode = '42501';
  end if;
  if document_row.commercial_document_type not in ('PROFORMA', 'ADVANCE_INVOICE') then
    raise exception 'Only proformas and advance invoices can receive advance payments' using errcode = '23514';
  end if;
  if payment_row.company_id is distinct from document_row.company_id
     or payment_row.client_id is distinct from document_row.client_id then
    raise exception 'Payment and document must belong to the same company and customer' using errcode = '23514';
  end if;
  if payment_row.accounting_state <> 'posted' or payment_row.reversed_at is not null then
    raise exception 'Only posted, unreversed customer payments can be linked' using errcode = '55000';
  end if;
  if upper(coalesce(payment_row.currency, 'EUR')) <> upper(coalesce(document_row.currency, 'EUR')) then
    raise exception 'Payment and document currencies must match' using errcode = '23514';
  end if;

  select * into existing_link
  from public.commercial_document_payment_links
  where payment_id = payment_row.id
    and document_id = document_row.id
    and allocation_type = 'ADVANCE'
    and status = 'active'
  for update;
  if found then
    return existing_link;
  end if;

  select round(
    payment_row.amount
    - coalesce((select sum(allocation.allocated_amount) from public.payment_allocations allocation
               where allocation.payment_id = payment_row.id and allocation.status = 'active'), 0)
    - coalesce((select sum(link.amount) from public.commercial_document_payment_links link
               where link.payment_id = payment_row.id and link.status = 'active'), 0),
    4
  ) into available_payment;
  select round(
    document_row.total_amount
    - coalesce((select sum(link.amount) from public.commercial_document_payment_links link
               where link.document_id = document_row.id and link.status = 'active'), 0),
    4
  ) into outstanding_document;

  link_amount := round(coalesce(p_amount, least(available_payment, outstanding_document)), 4);
  if link_amount <= 0 then
    raise exception 'There is no available payment or document balance to link' using errcode = '23514';
  end if;
  if link_amount > available_payment or link_amount > outstanding_document then
    raise exception 'Advance payment link exceeds the available payment or document balance' using errcode = '23514';
  end if;

  insert into public.commercial_document_payment_links (
    company_id, document_id, payment_id, allocation_type, amount, currency,
    linked_by, metadata
  ) values (
    document_row.company_id, document_row.id, payment_row.id, 'ADVANCE', link_amount,
    upper(coalesce(payment_row.currency, 'EUR')), (select auth.uid()),
    jsonb_build_object('reason', nullif(trim(coalesce(p_reason, '')), ''))
  ) returning * into link_row;

  insert into public.document_source_links (
    company_id, source_type, source_id, target_type, target_id, link_type,
    amount, metadata, created_by
  ) values (
    document_row.company_id, 'payment', payment_row.id, 'commercial_document', document_row.id,
    'payment_to_advance', link_amount,
    jsonb_build_object('allocation_id', link_row.id), (select auth.uid())
  ) on conflict do nothing;

  update public.invoices
  set commercial_status = case
        when outstanding_document - link_amount <= 0 then 'PAID'
        else 'PARTIALLY_PAID'
      end,
      payment_status = case
        when outstanding_document - link_amount <= 0 then 'PAID'
        else 'PARTIALLY_PAID'
      end
  where id = document_row.id;

  perform private.insert_commercial_document_event(
    document_row.company_id, document_row.id, 'advance_payment_linked',
    document_row.commercial_status,
    case when outstanding_document - link_amount <= 0 then 'PAID' else 'PARTIALLY_PAID' end,
    jsonb_build_object(
      'payment_id', payment_row.id,
      'allocation_id', link_row.id,
      'amount', link_amount,
      'accounting_status', link_row.accounting_status,
      'vat_status', link_row.vat_status
    ),
    clock_timestamp(), (select auth.uid())
  );
  return link_row;
end
$$;


--
-- Name: list_company_agents(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_company_agents(p_company_id uuid) RETURNS TABLE(user_id uuid, email text, first_name text, last_name text, membership_role text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  return query
  select
    membership.user_id,
    coalesce(auth_user.email, profile.email)::text,
    profile.first_name::text,
    profile.last_name::text,
    coalesce(membership.role, 'employee')::text
  from public.memberships membership
  left join auth.users auth_user on auth_user.id = membership.user_id
  left join public.profiles profile on profile.id = membership.user_id
  where membership.company_id = p_company_id
    and membership.user_id is not null
    and coalesce(membership.status, 'active') <> 'revoked'
    and (
      private.has_company_permission(p_company_id, 'roles.manage')
      or private.has_company_permission(p_company_id, 'accounting.read')
      or private.has_company_permission(p_company_id, 'sales_invoice.view')
    )
  order by lower(coalesce(auth_user.email, profile.email, ''));
end;
$$;


--
-- Name: list_company_invitations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_company_invitations(p_company_id uuid) RETURNS TABLE(id uuid, email text, role_code text, status text, expires_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if not private.has_company_permission(p_company_id, 'roles.manage') then
    raise exception 'You do not have permission to view company invitations'
      using errcode = '42501';
  end if;

  return query
  select
    invitation.id,
    invitation.email::text,
    invitation.role_code::text,
    invitation.status::text,
    invitation.expires_at,
    invitation.created_at
  from public.company_invitations invitation
  where invitation.company_id = p_company_id
    and invitation.status = 'pending'
    and invitation.expires_at > now()
  order by invitation.created_at desc;
end;
$$;


--
-- Name: list_company_members(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_company_members(p_company_id uuid) RETURNS TABLE(membership_id uuid, user_id uuid, email text, first_name text, last_name text, legacy_role text, status text, role_code text, role_name text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select member.membership_id, member.user_id, member.email, member.first_name,
    member.last_name, membership.role::text, member.status,
    member.role_code, member.role_name
  from public.rbac_list_company_members(p_company_id) member
  join public.memberships membership on membership.id = member.membership_id;
$$;


--
-- Name: list_effective_vat_rules(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_effective_vat_rules(p_company_id uuid, p_as_of date DEFAULT CURRENT_DATE) RETURNS TABLE(code text, name text, rate numeric, category text, deductibility_percentage numeric, requires_compliance_review boolean, effective_from date, effective_until date, official_sources jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  config_row record;
begin
  if not (select private.has_company_permission(p_company_id, 'accounting.read')) then
    raise exception 'Insufficient permission to read VAT configuration' using errcode = '42501';
  end if;

  select version.configuration, version.effective_from, version.effective_until
  into config_row
  from public.compliance_config_sets config_set
  join public.compliance_config_versions version on version.config_set_id = config_set.id
  where config_set.company_id = p_company_id
    and config_set.config_type = 'vat_rates'
    and version.status = 'active'
    and version.effective_from <= coalesce(p_as_of, current_date)
    and (version.effective_until is null or version.effective_until >= coalesce(p_as_of, current_date))
  order by version.version desc, version.effective_from desc
  limit 1;

  if not found then
    return;
  end if;

  return query
  select
    value ->> 'code',
    value ->> 'name',
    (value ->> 'rate')::numeric,
    value ->> 'category',
    (value ->> 'deductibilityPercentage')::numeric,
    coalesce((value ->> 'requiresComplianceReview')::boolean, true),
    config_row.effective_from,
    config_row.effective_until,
    config_row.configuration -> 'officialSources'
  from jsonb_array_elements(coalesce(config_row.configuration -> 'rates', '[]'::jsonb)) value;
end
$$;


--
-- Name: mark_sales_book_declared(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_sales_book_declared(p_period_id uuid, p_confirmation boolean, p_reason text DEFAULT NULL::text) RETURNS public.sales_book_periods
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  period_row public.sales_book_periods;
  snapshot jsonb;
begin
  if not coalesce(p_confirmation, false) then
    raise exception 'Explicit confirmation is required to declare a Sales Book' using errcode = '55000';
  end if;
  select * into period_row from public.sales_book_periods where id = p_period_id for update;
  if not found then
    raise exception 'Sales Book period not found' using errcode = 'P0002';
  end if;
  if not coalesce(private.has_company_permission(period_row.company_id, 'tax.declaration.prepare'), false) then
    raise exception 'Insufficient permission to declare the Sales Book' using errcode = '42501';
  end if;
  if period_row.status <> 'READY_FOR_DECLARATION' then
    raise exception 'Only a ready Sales Book period may be declared' using errcode = '55000';
  end if;
  snapshot := private.sales_book_period_snapshot(period_row.id);
  perform set_config('app.sales_book_period_workflow', 'authorized', true);
  perform set_config('app.change_reason', coalesce(nullif(trim(p_reason), ''), 'Sales Book declared'), true);
  update public.sales_book_periods
  set status = 'DECLARED',
      declared_at = clock_timestamp(),
      declared_by = (select auth.uid()),
      declaration_metadata = snapshot || jsonb_build_object('declared_by', (select auth.uid()), 'declared_at', clock_timestamp()),
      updated_at = clock_timestamp(),
      updated_by = (select auth.uid())
  where id = period_row.id
  returning * into period_row;
  update public.tax_calendar_events
  set status = 'completed', completed_at = clock_timestamp()
  where company_id = period_row.company_id
    and tax_type = 'vat'
    and period_start = period_row.period_start
    and period_end = period_row.period_end;
  perform set_config('app.change_reason', '', true);
  perform set_config('app.sales_book_period_workflow', '', true);
  return period_row;
exception when others then
  perform set_config('app.change_reason', '', true);
  perform set_config('app.sales_book_period_workflow', '', true);
  raise;
end
$$;


--
-- Name: match_bank_statement_transaction(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_bank_statement_transaction(p_statement_transaction_id uuid, p_journal_entry_id uuid) RETURNS public.bank_statement_transactions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare statement_row public.bank_statement_transactions;
begin
  select * into statement_row from public.bank_statement_transactions where id=p_statement_transaction_id for update;
  if not found then raise exception 'Bank statement transaction not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(statement_row.company_id,'bank.reconcile')) then raise exception 'Insufficient permission to match bank statement' using errcode='42501'; end if;
  if not exists (
    select 1 from public.journal_entries
    where id=p_journal_entry_id and company_id=statement_row.company_id and status='posted'
  ) then
    raise exception 'Posted journal entry does not belong to the company' using errcode='23503';
  end if;
  update public.bank_statement_transactions set status='matched',matched_journal_entry_id=p_journal_entry_id,matched_at=clock_timestamp(),matched_by=(select auth.uid()) where id=statement_row.id returning * into statement_row;
  return statement_row;
end
$$;


--
-- Name: normalize_stripe_invoice_note(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_stripe_invoice_note() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.source_document_type = 'stripe_transaction'
     and new.notes like 'Imported from Stripe store %. Stripe transaction: %' then
    new.notes := 'Stripe transaction: ' || split_part(new.notes, '. Stripe transaction: ', 2);
  end if;
  return new;
end;
$$;


--
-- Name: open_cashier_shift(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_cashier_shift(p_company_id uuid, p_terminal_id uuid, p_opening_float numeric DEFAULT 0, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare terminal_row public.pos_terminals; shift_row public.cashier_shifts;
begin
  if not (select private.has_company_permission(p_company_id, 'pos.shift.open')) then
    raise exception 'Insufficient permission to open a cashier shift' using errcode = '42501';
  end if;
  if coalesce(p_opening_float, 0) < 0 then
    raise exception 'Opening float cannot be negative' using errcode = '23514';
  end if;
  terminal_row := private.assert_cashier_shift_access(p_company_id, p_terminal_id);
  if exists (select 1 from public.cashier_shifts where terminal_id = terminal_row.id and status in ('open','active','closing','reopened')) then
    raise exception 'This terminal already has an open cashier shift' using errcode = '23505';
  end if;
  insert into public.cashier_shifts (company_id,branch_id,terminal_id,cashier_id,currency,status,opening_float,expected_cash,opening_notes,opened_by)
  values (p_company_id,terminal_row.branch_id,terminal_row.id,(select auth.uid()),'EUR','active',round(coalesce(p_opening_float,0),4),round(coalesce(p_opening_float,0),4),nullif(trim(p_notes),''),(select auth.uid()))
  returning * into shift_row;
  insert into public.cashier_shift_movements (company_id,cashier_shift_id,terminal_id,movement_type,amount,source_type,reason,created_by)
  values (p_company_id,shift_row.id,terminal_row.id,'opening_float',round(coalesce(p_opening_float,0),4),'cashier_shift',nullif(trim(p_notes),''),(select auth.uid()));
  insert into public.cashier_shift_events (company_id,cashier_shift_id,event_type,payload,actor_id)
  values (p_company_id,shift_row.id,'opened',jsonb_build_object('opening_float',shift_row.opening_float),(select auth.uid()));
  return jsonb_build_object('shift_id',shift_row.id,'status',shift_row.status,'expected_cash',shift_row.expected_cash);
end $$;


--
-- Name: asset_depreciation_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.asset_depreciation_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    frequency text NOT NULL,
    status text DEFAULT 'preview'::text NOT NULL,
    journal_entry_id uuid,
    idempotency_key uuid NOT NULL,
    posted_at timestamp with time zone,
    posted_by uuid,
    reversed_at timestamp with time zone,
    reversed_by uuid,
    reversal_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT asset_depreciation_runs_check CHECK ((period_end >= period_start)),
    CONSTRAINT asset_depreciation_runs_frequency_check CHECK ((frequency = ANY (ARRAY['monthly'::text, 'yearly'::text]))),
    CONSTRAINT asset_depreciation_runs_status_check CHECK ((status = ANY (ARRAY['preview'::text, 'posted'::text, 'reversed'::text])))
);


--
-- Name: post_asset_depreciation(uuid, date, date, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_asset_depreciation(p_company_id uuid, p_period_start date, p_period_end date, p_frequency text, p_idempotency_key uuid, p_reason text) RETURNS public.asset_depreciation_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  result public.asset_depreciation_runs;
  existing_run public.asset_depreciation_runs;
  preview_row record;
  journal_row public.journal_entries;
  depreciation_expense_account_id uuid;
  accumulated_depreciation_account_id uuid;
  total_book numeric(20,4) := 0;
begin
  if not (select private.has_company_permission(p_company_id, 'asset.depreciation.post'))
     or not (select private.has_company_permission(p_company_id, 'journal.create'))
     or not (select private.has_company_permission(p_company_id, 'journal.post')) then
    raise exception 'Depreciation posting requires asset and journal permissions' using errcode = '42501';
  end if;
  if trim(coalesce(p_reason,'')) = '' then raise exception 'Depreciation posting reason is required' using errcode = '23514'; end if;
  select * into existing_run from public.asset_depreciation_runs where company_id=p_company_id and idempotency_key=p_idempotency_key for update;
  if found then return existing_run; end if;
  if exists(select 1 from public.asset_depreciation_runs where company_id=p_company_id and period_start=p_period_start and period_end=p_period_end and frequency=p_frequency and status='posted') then
    raise exception 'Depreciation has already been posted for this period' using errcode = '55000';
  end if;
  insert into public.asset_depreciation_runs(company_id,period_start,period_end,frequency,status,idempotency_key,created_by)
  values(p_company_id,p_period_start,p_period_end,p_frequency,'preview',p_idempotency_key,(select auth.uid())) returning * into result;
  for preview_row in select * from public.preview_asset_depreciation(p_company_id,p_period_start,p_period_end,p_frequency) loop
    insert into public.asset_depreciation_lines(company_id,run_id,asset_id,book_depreciation_amount,tax_depreciation_amount,book_accumulated_after,tax_accumulated_after)
    select p_company_id,result.id,asset.id,preview_row.book_depreciation,preview_row.tax_depreciation,
      asset.accumulated_book_depreciation+preview_row.book_depreciation,asset.accumulated_tax_depreciation+preview_row.tax_depreciation
    from public.fixed_assets asset where asset.id=preview_row.fixed_asset_id;
    total_book := total_book + preview_row.book_depreciation;
  end loop;
  if total_book > 0 then
    select id into depreciation_expense_account_id from public.chart_of_accounts where company_id=p_company_id and code='6200' and active and posting_allowed limit 1;
    select id into accumulated_depreciation_account_id from public.chart_of_accounts where company_id=p_company_id and code='1590' and active and posting_allowed limit 1;
    if depreciation_expense_account_id is null or accumulated_depreciation_account_id is null then raise exception 'Depreciation accounts are not mapped' using errcode='23514'; end if;
    journal_row := public.create_journal_entry(p_company_id,p_period_end,p_period_end,'Depreciation '||p_period_start::text||' to '||p_period_end::text,'AD-'||result.id::text,'EUR',1,null,'automatic');
    update public.journal_entries set source_type='asset_depreciation',source_id=result.id,source_key='AD-'||result.id::text
    where id = journal_row.id;
    insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,created_by)
    values(journal_row.id,p_company_id,1,depreciation_expense_account_id,'Accounting depreciation',round(total_book,4),0,'EUR',round(total_book,4),(select auth.uid()));
    insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,created_by)
    values(journal_row.id,p_company_id,2,accumulated_depreciation_account_id,'Accumulated depreciation',0,round(total_book,4),'EUR',round(total_book,4),(select auth.uid()));
    journal_row := public.post_journal_entry(journal_row.id,p_reason);
  end if;
  for preview_row in select line.asset_id,line.book_depreciation_amount,line.tax_depreciation_amount from public.asset_depreciation_lines line where line.run_id=result.id loop
    update public.fixed_assets asset set accumulated_book_depreciation=asset.accumulated_book_depreciation+preview_row.book_depreciation_amount,
      accumulated_tax_depreciation=asset.accumulated_tax_depreciation+preview_row.tax_depreciation_amount,
      net_book_value=asset.acquisition_cost-(asset.accumulated_book_depreciation+preview_row.book_depreciation_amount),updated_at=clock_timestamp(),updated_by=(select auth.uid())
    where asset.id=preview_row.asset_id;
  end loop;
  update public.asset_depreciation_runs set status='posted',journal_entry_id=journal_row.id,posted_at=clock_timestamp(),posted_by=(select auth.uid()) where id=result.id returning * into result;
  return result;
end
$$;


--
-- Name: post_credit_note(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_credit_note(p_invoice_id uuid, p_idempotency_key uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  invoice_row public.invoices;
  journal_row public.journal_entries;
  net_amount numeric(20,4);
  credit_tax_amount numeric(20,4);
  gross_amount numeric(20,4);
  stock_row record;
  stock_before numeric;
begin
  select * into invoice_row from public.invoices where id = p_invoice_id for update;
  if not found then
    raise exception 'Credit note not found' using errcode = 'P0002';
  end if;
  if not (select private.has_company_permission(invoice_row.company_id, 'sales_invoice.post')) then
    raise exception 'Insufficient permission to post credit notes' using errcode = '42501';
  end if;
  if invoice_row.credit_of_invoice_id is null
    and lower(coalesce(invoice_row.type, '')) <> 'credit_note'
    and lower(coalesce(invoice_row.subtype, '')) <> 'credit_note' then
    raise exception 'The document is not identified as a credit note' using errcode = '23514';
  end if;
  if invoice_row.accounting_state = 'posted' then
    if p_idempotency_key is null or invoice_row.idempotency_key = p_idempotency_key then
      return invoice_row;
    end if;
    raise exception 'Credit note has already been posted' using errcode = '55000';
  end if;
  if invoice_row.accounting_state <> 'ready_for_posting' then
    raise exception 'Credit note must be prepared before posting' using errcode = '55000';
  end if;

  select calculated.net_amount, calculated.tax_amount, calculated.gross_amount
  into net_amount, credit_tax_amount, gross_amount
  from private.sales_invoice_amounts(invoice_row.id) calculated;
  if gross_amount <= 0 then
    raise exception 'Credit note total must be greater than zero' using errcode = '23514';
  end if;

  journal_row := public.create_automatic_journal(
    invoice_row.company_id, 'credit_note', 'credit_note', invoice_row.id,
    invoice_row.invoice_number, coalesce(invoice_row.posting_date, invoice_row.issue_date, current_date),
    coalesce(invoice_row.issue_date, current_date), 'Credit note ' || invoice_row.invoice_number,
    jsonb_build_object('net', net_amount, 'tax', credit_tax_amount, 'gross', gross_amount),
    invoice_row.currency, invoice_row.branch_id,
    jsonb_build_object('invoice_number', invoice_row.invoice_number, 'client_id', invoice_row.client_id,
      'credited_invoice_id', invoice_row.credit_of_invoice_id)
  );

  perform set_config('app.financial_workflow', 'authorized', true);
  perform set_config('app.change_reason', coalesce(nullif(trim(p_reason), ''), 'Credit note posted'), true);
  update public.invoices
  set status = 'posted', accounting_state = 'posted',
      posting_date = coalesce(posting_date, issue_date, current_date),
      fiscal_year_id = (select fiscal_year_id from public.accounting_periods where id = journal_row.period_id),
      posted_at = clock_timestamp(), posted_by = (select auth.uid()),
      posting_journal_entry_id = journal_row.id,
      idempotency_key = coalesce(p_idempotency_key, idempotency_key),
      total_amount = gross_amount, tax_amount = credit_tax_amount
  where id = invoice_row.id
  returning * into invoice_row;
  perform set_config('app.financial_workflow', '', true);
  perform set_config('app.change_reason', '', true);

  -- The conversion copies the returned lines and keeps source_item_id on each
  -- line. Restore only products that were actually issued from stock on the
  -- original sale; non-stock products are intentionally unaffected.
  for stock_row in
    select item.product_id, sum(item.quantity) as quantity
    from public.invoice_items item
    where item.invoice_id = invoice_row.id
      and item.product_id is not null
      and exists (
        select 1
        from public.inventory_stock_movements issued
        where issued.invoice_id = invoice_row.credit_of_invoice_id
          and issued.product_id = item.product_id
          and issued.movement_type = 'invoice_issue'
      )
    group by item.product_id
  loop
    if invoice_row.branch_id is not null then
      select coalesce(stock.stock_quantity, 0) into stock_before
      from public.product_branch_stock stock
      where stock.company_id = invoice_row.company_id and stock.branch_id = invoice_row.branch_id and stock.product_id = stock_row.product_id
      for update;
      if found then
        update public.product_branch_stock set stock_quantity = stock_before + stock_row.quantity, updated_by = (select auth.uid()), updated_at = now() where company_id = invoice_row.company_id and branch_id = invoice_row.branch_id and product_id = stock_row.product_id;
        update public.products set stock_quantity = (select coalesce(sum(stock_quantity), 0) from public.product_branch_stock where company_id = invoice_row.company_id and product_id = stock_row.product_id) where id = stock_row.product_id;
      end if;
    else
      select coalesce(product.stock_quantity, 0) into stock_before from public.products product where product.id = stock_row.product_id for update;
      if found then update public.products set stock_quantity = stock_before + stock_row.quantity where id = stock_row.product_id; end if;
    end if;

    if found then

      insert into public.inventory_stock_movements (
        company_id, branch_id, product_id, invoice_id, movement_type, quantity_delta,
        stock_before, stock_after, created_by
      ) values (
        invoice_row.company_id, invoice_row.branch_id, stock_row.product_id, invoice_row.id, 'invoice_reversal',
        stock_row.quantity, stock_before, stock_before + stock_row.quantity, (select auth.uid())
      );
    end if;
  end loop;

  return invoice_row;
end
$$;


--
-- Name: post_expense(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_expense(p_expense_id uuid, p_idempotency_key uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS public.expenses
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  expense_row public.expenses;
  journal_row public.journal_entries;
begin
  select * into expense_row from public.expenses where id = p_expense_id for update;
  if not found then raise exception 'Expense not found' using errcode = 'P0002'; end if;
  if not (select private.has_company_permission(expense_row.company_id, 'expense.post'))
     or not (select private.has_company_permission(expense_row.company_id, 'journal.post')) then
    raise exception 'Insufficient permission to post expenses' using errcode = '42501';
  end if;
  if expense_row.accounting_state = 'posted' then
    if p_idempotency_key is null or expense_row.idempotency_key = p_idempotency_key then return expense_row; end if;
    raise exception 'Expense has already been posted' using errcode = '55000';
  end if;
  if expense_row.accounting_state not in ('legacy', 'ready_for_posting') then
    raise exception 'Expense is not eligible for posting' using errcode = '55000';
  end if;
  if coalesce(expense_row.amount, 0) <= 0 then
    raise exception 'Expense amount must be greater than zero' using errcode = '23514';
  end if;

  journal_row := private.create_expense_payment_journal(
    expense_row.company_id, 'expense', expense_row.id, expense_row.id::text,
    coalesce(expense_row.posting_date, expense_row.date, current_date),
    coalesce(expense_row.date, current_date),
    coalesce(nullif(trim(expense_row.description), ''), expense_row.article, 'Expense'),
    expense_row.amount, expense_row.currency, expense_row.branch_id,
    expense_row.payment_method,
    jsonb_build_object(
      'category', expense_row.category,
      'article', expense_row.article,
      'vendor_id', expense_row.vendor_id,
      'vendor_name', expense_row.vendor_name,
      'invoice_number', expense_row.invoice_number,
      'tax_code', expense_row.tax_code,
      'vat_rate', expense_row.vat_rate,
      'tax_amount', expense_row.tax_amount,
      'tax_recoverable_amount', expense_row.tax_recoverable_amount,
      'company_bank_account_id', expense_row.company_bank_account_id
    )
  );

  perform set_config('app.financial_workflow', 'authorized', true);
  perform set_config('app.change_reason', coalesce(nullif(trim(p_reason), ''), 'Expense posted'), true);
  update public.expenses
     set accounting_state = 'posted',
         posting_date = coalesce(posting_date, date, current_date),
         posting_journal_entry_id = journal_row.id,
         idempotency_key = coalesce(p_idempotency_key, idempotency_key)
   where id = expense_row.id
   returning * into expense_row;
  perform set_config('app.financial_workflow', '', true);
  perform set_config('app.change_reason', '', true);
  return expense_row;
end;
$$;


--
-- Name: inventory_movements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inventory_movements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    movement_sequence bigint NOT NULL,
    company_id uuid NOT NULL,
    product_id uuid,
    location_id uuid,
    movement_type text NOT NULL,
    quantity_delta numeric(20,4) NOT NULL,
    quantity_before numeric(20,4) NOT NULL,
    quantity_after numeric(20,4) NOT NULL,
    unit_cost numeric(20,4) DEFAULT 0 NOT NULL,
    cost_amount numeric(20,4) DEFAULT 0 NOT NULL,
    average_cost_before numeric(20,4) DEFAULT 0 NOT NULL,
    average_cost_after numeric(20,4) DEFAULT 0 NOT NULL,
    inventory_value_after numeric(20,4) DEFAULT 0 NOT NULL,
    source_type text,
    source_id uuid,
    journal_entry_id uuid,
    idempotency_key uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    product_name text,
    CONSTRAINT inventory_movements_cost_amount_check CHECK ((cost_amount >= (0)::numeric)),
    CONSTRAINT inventory_movements_movement_type_check CHECK ((movement_type = ANY (ARRAY['purchase'::text, 'sale'::text, 'return'::text, 'transfer'::text, 'adjustment'::text, 'opening_stock'::text, 'stock_count'::text, 'write_off'::text]))),
    CONSTRAINT inventory_movements_quantity_after_check CHECK ((quantity_after >= (0)::numeric)),
    CONSTRAINT inventory_movements_unit_cost_check CHECK ((unit_cost >= (0)::numeric))
);


--
-- Name: post_inventory_movement(uuid, uuid, text, numeric, numeric, uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_inventory_movement(p_company_id uuid, p_product_id uuid, p_movement_type text, p_quantity numeric, p_unit_cost numeric DEFAULT NULL::numeric, p_location_id uuid DEFAULT NULL::uuid, p_source_type text DEFAULT NULL::text, p_source_id uuid DEFAULT NULL::uuid, p_idempotency_key uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS public.inventory_movements
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  product_row public.products;
  existing_row public.inventory_movements;
  result public.inventory_movements;
  movement text := lower(trim(p_movement_type));
  delta numeric(20,4);
  before_quantity numeric(20,4);
  after_quantity numeric(20,4);
  before_average numeric(20,4);
  after_average numeric(20,4);
  unit_cost numeric(20,4);
  cost_amount numeric(20,4);
  old_value numeric(20,4);
  new_value numeric(20,4);
  journal_row public.journal_entries;
  debit_account_id uuid;
  credit_account_id uuid;
  currency_code text := 'EUR';
begin
  if not (select private.has_company_permission(p_company_id,'inventory.manage')) then
    raise exception 'Insufficient permission to post inventory' using errcode='42501';
  end if;
  if p_idempotency_key is null then raise exception 'Inventory idempotency key is required' using errcode='23514'; end if;
  select * into existing_row from public.inventory_movements where company_id=p_company_id and idempotency_key=p_idempotency_key for update;
  if found then return existing_row; end if;
  if movement not in ('purchase','sale','return','transfer','adjustment','opening_stock','stock_count','write_off') or coalesce(p_quantity,0)=0 then
    raise exception 'Inventory movement type and non-zero quantity are required' using errcode='23514';
  end if;
  select * into product_row from public.products where id=p_product_id and company_id=p_company_id for update;
  if not found then raise exception 'Product is invalid for this company' using errcode='23514'; end if;
  if p_location_id is not null and not exists(select 1 from public.inventory_locations where id=p_location_id and company_id=p_company_id and status='active') then
    raise exception 'Inventory location is invalid for this company' using errcode='23514';
  end if;
  select movement.quantity_after,movement.average_cost_after,movement.inventory_value_after
  into before_quantity,before_average,old_value
  from public.inventory_movements movement
  where movement.company_id=p_company_id and movement.product_id=p_product_id
  order by movement.movement_sequence desc
  limit 1;
  if not found then
    before_quantity := round(coalesce(product_row.stock_quantity,0),4);
    before_average := round(coalesce(product_row.cost_price,0),4);
    old_value := round(before_quantity*before_average,4);
  end if;
  delta := case
    when movement in ('sale','write_off') then -abs(p_quantity)
    when movement in ('purchase','return','opening_stock') then abs(p_quantity)
    else p_quantity
  end;
  after_quantity := round(before_quantity + delta,4);
  if after_quantity < 0 then raise exception 'Inventory quantity cannot become negative' using errcode='23514'; end if;
  if delta > 0 then
    unit_cost := round(coalesce(p_unit_cost, before_average),4);
    if unit_cost < 0 or (movement in ('purchase','opening_stock','return') and unit_cost = 0 and before_average = 0) then
      raise exception 'A non-zero unit cost is required for incoming inventory' using errcode='23514';
    end if;
    new_value := old_value + delta * unit_cost;
    after_average := case when after_quantity=0 then 0 else round(new_value/after_quantity,4) end;
  else
    unit_cost := case when before_quantity=0 then 0 else round(old_value/before_quantity,4) end;
    cost_amount := case when before_quantity=0 then 0 else round(abs(delta)*old_value/before_quantity,4) end;
    new_value := round(old_value-cost_amount,4);
    after_average := case when after_quantity=0 then 0 else before_average end;
  end if;
  if delta > 0 then cost_amount := round(abs(delta)*unit_cost,4); end if;

  insert into public.inventory_movements(
    company_id,product_id,location_id,movement_type,quantity_delta,quantity_before,quantity_after,unit_cost,cost_amount,
    average_cost_before,average_cost_after,inventory_value_after,source_type,source_id,idempotency_key,created_by
  ) values(
    p_company_id,p_product_id,p_location_id,movement,delta,before_quantity,after_quantity,unit_cost,cost_amount,
    before_average,after_average,new_value,p_source_type,p_source_id,p_idempotency_key,(select auth.uid())
  ) returning * into result;

  if movement <> 'transfer' then
    if delta > 0 then
      debit_account_id := private.inventory_account(p_company_id,'1200');
      credit_account_id := private.inventory_account(p_company_id,case when movement='opening_stock' then '3000' when movement='purchase' then '2010' when movement='return' then '5000' else '6010' end);
    else
      debit_account_id := private.inventory_account(p_company_id,case when movement='sale' then '5000' else '6010' end);
      credit_account_id := private.inventory_account(p_company_id,'1200');
    end if;
    journal_row := public.create_journal_entry(p_company_id,current_date,current_date,'Inventory '||movement||' for '||product_row.name,'INV-'||result.id::text,currency_code,1,null,'automatic');
    update public.journal_entries set source_type='inventory_movement',source_id=result.id,source_key='INV-'||result.id::text where id=journal_row.id;
    insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,created_by)
    values(journal_row.id,p_company_id,1,debit_account_id,'Inventory movement',cost_amount,0,currency_code,cost_amount,(select auth.uid()));
    insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,created_by)
    values(journal_row.id,p_company_id,2,credit_account_id,'Inventory movement',0,cost_amount,currency_code,cost_amount,(select auth.uid()));
    journal_row := public.post_journal_entry(journal_row.id,coalesce(nullif(trim(p_reason),''),'Inventory movement posted'));
    update public.inventory_movements set journal_entry_id=journal_row.id where id=result.id;
  end if;

  perform set_config('app.inventory_workflow','authorized',true);
  update public.products set stock_quantity=after_quantity,cost_price=after_average where id=product_row.id;
  perform set_config('app.inventory_workflow','',true);
  select * into result from public.inventory_movements where id=result.id;
  return result;
end
$$;


--
-- Name: post_journal_entry(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_journal_entry(p_journal_entry_id uuid, p_reason text DEFAULT NULL::text) RETURNS public.journal_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  entry_row public.journal_entries;
  period_row public.accounting_periods;
  debit_total numeric(20, 4);
  credit_total numeric(20, 4);
  line_count integer;
begin
  select * into entry_row
  from public.journal_entries
  where id = p_journal_entry_id
  for update;
  if not found then
    raise exception 'Journal entry not found' using errcode = 'P0002';
  end if;
  if not (select private.has_company_permission(entry_row.company_id, 'journal.post')) then
    raise exception 'Insufficient permission to post journals' using errcode = '42501';
  end if;
  if entry_row.status <> 'draft' then
    raise exception 'Only draft journals may be posted' using errcode = '55000';
  end if;

  select * into period_row
  from public.accounting_periods
  where company_id = entry_row.company_id
    and entry_row.posting_date between start_date and end_date
  order by start_date desc
  limit 1
  for update;
  if not found then
    raise exception 'Posting date is not covered by an accounting period' using errcode = '23514';
  end if;
  if period_row.status in ('closed', 'locked') then
    raise exception 'Posting is not allowed in a closed or locked period' using errcode = '55000';
  end if;
  if period_row.status = 'soft_closed' then
    if not (select private.has_company_permission(entry_row.company_id, 'accounting_period.manage'))
      or nullif(trim(coalesce(p_reason, '')), '') is null then
      raise exception 'Posting into a soft-closed period requires accounting-period permission and a reason'
        using errcode = '55000';
    end if;
  end if;

  select count(*), coalesce(sum(debit), 0), coalesce(sum(credit), 0)
  into line_count, debit_total, credit_total
  from public.journal_entry_lines
  where journal_entry_id = p_journal_entry_id;
  if line_count < 2 then
    raise exception 'A journal entry requires at least two lines' using errcode = '23514';
  end if;
  if debit_total <= 0 or debit_total <> credit_total then
    raise exception 'Journal entry is not balanced (debits %, credits %)', debit_total, credit_total
      using errcode = '23514';
  end if;

  perform set_config('app.financial_workflow', 'authorized', true);
  perform set_config('app.change_reason', coalesce(nullif(trim(coalesce(p_reason, '')), ''), 'Journal posted'), true);
  update public.journal_entries
  set status = 'posted',
      period_id = period_row.id,
      posted_at = clock_timestamp(),
      posted_by = (select auth.uid()),
      updated_at = clock_timestamp(),
      updated_by = (select auth.uid())
  where id = p_journal_entry_id
  returning * into entry_row;
  perform set_config('app.financial_workflow', '', true);
  perform set_config('app.change_reason', '', true);
  return entry_row;
end
$$;


--
-- Name: post_opening_balance(uuid, date, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_opening_balance(p_company_id uuid, p_as_of_date date, p_description text, p_lines jsonb, p_idempotency_key uuid) RETURNS public.journal_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  existing_row public.accounting_opening_balances;
  opening_id uuid := gen_random_uuid();
  entry_row public.journal_entries;
  account_row public.chart_of_accounts;
  line_value jsonb;
  account_id uuid;
  line_debit numeric(20,4);
  line_credit numeric(20,4);
  debit_total numeric(20,4) := 0;
  credit_total numeric(20,4) := 0;
  line_number integer := 0;
begin
  if not (select private.has_company_permission(p_company_id, 'opening_balance.post'))
    or not (select private.has_company_permission(p_company_id, 'journal.create'))
    or not (select private.has_company_permission(p_company_id, 'journal.post')) then
    raise exception 'Opening-balance posting requires accounting permissions' using errcode = '42501';
  end if;
  if p_as_of_date is null then
    raise exception 'Opening-balance date is required' using errcode = '23514';
  end if;
  if nullif(trim(coalesce(p_description, '')), '') is null then
    raise exception 'Opening-balance description is required' using errcode = '23514';
  end if;
  if p_idempotency_key is null then
    raise exception 'Opening-balance idempotency key is required' using errcode = '23514';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' then
    raise exception 'Opening-balance lines must be a JSON array' using errcode = '22023';
  end if;

  select * into existing_row
  from public.accounting_opening_balances
  where company_id = p_company_id and idempotency_key = p_idempotency_key
  for update;
  if found then
    select * into entry_row from public.journal_entries where id = existing_row.journal_entry_id;
    return entry_row;
  end if;

  if jsonb_array_length(p_lines) < 2 then
    raise exception 'An opening balance requires at least two lines' using errcode = '23514';
  end if;

  for line_value in select value from jsonb_array_elements(p_lines) value loop
    account_id := null;
    if nullif(line_value ->> 'account_id', '') is not null then
      account_id := (line_value ->> 'account_id')::uuid;
    elsif nullif(line_value ->> 'account_code', '') is not null then
      select id into account_id
      from public.chart_of_accounts
      where company_id = p_company_id and code = line_value ->> 'account_code';
    end if;
    if account_id is null then
      raise exception 'Every opening-balance line requires a valid account' using errcode = '23514';
    end if;
    select * into account_row
    from public.chart_of_accounts
    where id = account_id and company_id = p_company_id and active and posting_allowed;
    if not found or account_row.id is null then
      raise exception 'Opening-balance account is invalid for this company' using errcode = '23514';
    end if;

    line_debit := round(coalesce(nullif(line_value ->> 'debit', '')::numeric, 0), 4);
    line_credit := round(coalesce(nullif(line_value ->> 'credit', '')::numeric, 0), 4);
    if line_debit < 0 or line_credit < 0 or
       ((line_debit <= 0) and (line_credit <= 0)) or
       (line_debit > 0 and line_credit > 0) then
      raise exception 'Opening-balance lines must contain exactly one positive side' using errcode = '23514';
    end if;
    debit_total := debit_total + line_debit;
    credit_total := credit_total + line_credit;
  end loop;
  if debit_total <= 0 or debit_total <> credit_total then
    raise exception 'Opening balance is not balanced (debits %, credits %)', debit_total, credit_total
      using errcode = '23514';
  end if;

  entry_row := public.create_journal_entry(
    p_company_id, p_as_of_date, p_as_of_date, trim(p_description),
    'OPENING-' || p_idempotency_key::text, 'EUR', 1, null, 'opening'
  );

  insert into public.accounting_opening_balances (
    id, company_id, as_of_date, description, idempotency_key, journal_entry_id,
    lines, created_by
  )
  values (
    opening_id, p_company_id, p_as_of_date, trim(p_description), p_idempotency_key,
    entry_row.id, p_lines, (select auth.uid())
  );

  perform set_config('app.financial_workflow', 'authorized', true);
  update public.journal_entries
  set source_type = 'opening_balance', source_id = opening_id,
      source_key = 'OPENING-' || p_idempotency_key::text,
      metadata = jsonb_build_object('opening_balance_id', opening_id, 'idempotency_key', p_idempotency_key)
  where id = entry_row.id;
  perform set_config('app.financial_workflow', '', true);

  for line_value in select value from jsonb_array_elements(p_lines) value loop
    account_id := null;
    if nullif(line_value ->> 'account_id', '') is not null then
      account_id := (line_value ->> 'account_id')::uuid;
    else
      select id into account_id
      from public.chart_of_accounts
      where company_id = p_company_id and code = line_value ->> 'account_code';
    end if;
    line_debit := round(coalesce(nullif(line_value ->> 'debit', '')::numeric, 0), 4);
    line_credit := round(coalesce(nullif(line_value ->> 'credit', '')::numeric, 0), 4);
    line_number := line_number + 1;
    insert into public.journal_entry_lines (
      journal_entry_id, company_id, line_number, account_id, description,
      debit, credit, transaction_currency, transaction_amount, created_by
    )
    values (
      entry_row.id, p_company_id, line_number, account_id,
      coalesce(nullif(trim(line_value ->> 'description'), ''), trim(p_description)),
      line_debit, line_credit, 'EUR', line_debit + line_credit, (select auth.uid())
    );
  end loop;

  entry_row := public.post_journal_entry(entry_row.id, 'Opening balance posted');
  return entry_row;
end
$$;


--
-- Name: post_pos_invoice(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_pos_invoice(p_invoice_id uuid, p_idempotency_key uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  invoice_row public.invoices;
  journal_row public.journal_entries;
  net_amount numeric(20,4);
  vat_amount numeric(20,4);
  gross_amount numeric(20,4);
begin
  select * into invoice_row from public.invoices where id = p_invoice_id for update;
  if not found then
    raise exception 'POS invoice not found' using errcode = 'P0002';
  end if;
  if not (select private.has_company_permission(invoice_row.company_id, 'sales_invoice.post')) then
    raise exception 'Insufficient permission to post POS invoices' using errcode = '42501';
  end if;
  if invoice_row.accounting_state = 'posted' then
    if p_idempotency_key is null or invoice_row.idempotency_key = p_idempotency_key then
      return invoice_row;
    end if;
    raise exception 'POS invoice has already been posted' using errcode = '55000';
  end if;
  if lower(coalesce(invoice_row.type, 'invoice')) <> 'invoice' then
    raise exception 'POS posting is available for invoices only' using errcode = '22023';
  end if;

  if invoice_row.client_id is not null then
    perform public.prepare_sales_invoice_for_posting(p_invoice_id, coalesce(p_reason, 'POS invoice prepared'));
    return public.post_sales_invoice(p_invoice_id, p_idempotency_key, coalesce(p_reason, 'POS invoice posted'));
  end if;

  select calculated.net_amount, calculated.tax_amount, calculated.gross_amount
  into net_amount, vat_amount, gross_amount
  from private.sales_invoice_amounts(invoice_row.id) calculated;
  if gross_amount <= 0 then
    raise exception 'POS invoice total must be greater than zero' using errcode = '23514';
  end if;

  perform set_config('app.financial_workflow', 'authorized', true);
  update public.invoices
  set accounting_state = 'ready_for_posting', posting_date = coalesce(posting_date, issue_date, current_date)
  where id = invoice_row.id;
  perform set_config('app.financial_workflow', '', true);

  journal_row := public.create_automatic_journal(
    invoice_row.company_id, 'pos_sale', 'pos_invoice', invoice_row.id,
    invoice_row.invoice_number, coalesce(invoice_row.posting_date, invoice_row.issue_date, current_date),
    coalesce(invoice_row.issue_date, current_date), 'POS invoice ' || invoice_row.invoice_number,
    jsonb_build_object('net', net_amount, 'tax', vat_amount, 'gross', gross_amount),
    invoice_row.currency, invoice_row.branch_id,
    jsonb_build_object('invoice_number', invoice_row.invoice_number, 'walk_in_sale', true)
  );

  perform set_config('app.financial_workflow', 'authorized', true);
  update public.invoices
  set status = 'posted', accounting_state = 'posted',
      posting_date = coalesce(posting_date, issue_date, current_date),
      fiscal_year_id = (select fiscal_year_id from public.accounting_periods where id = journal_row.period_id),
      posted_at = clock_timestamp(), posted_by = (select auth.uid()),
      posting_journal_entry_id = journal_row.id,
      idempotency_key = coalesce(p_idempotency_key, idempotency_key),
      total_amount = gross_amount, tax_amount = vat_amount
  where id = invoice_row.id
  returning * into invoice_row;
  perform set_config('app.financial_workflow', '', true);
  return invoice_row;
end
$$;


--
-- Name: post_sales_invoice(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_sales_invoice(p_invoice_id uuid, p_idempotency_key uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  invoice_row public.invoices;
  client_row public.clients;
  period_row public.accounting_periods;
  journal_row public.journal_entries;
  net_amount numeric(20,4);
  vat_amount numeric(20,4);
  gross_amount numeric(20,4);
  item_count integer;
begin
  select * into invoice_row from public.invoices where id = p_invoice_id for update;
  if not found then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if not (select private.has_company_permission(invoice_row.company_id, 'sales_invoice.post')) then
    raise exception 'Insufficient permission to post sales invoices' using errcode = '42501';
  end if;
  if public.get_my_company_role(invoice_row.company_id) = 'employee'
     and invoice_row.user_id is distinct from (select auth.uid()) then
    raise exception 'Employees can only post invoices they created' using errcode = '42501';
  end if;

  if invoice_row.accounting_state = 'posted' then
    if p_idempotency_key is not null and invoice_row.idempotency_key = p_idempotency_key then
      return invoice_row;
    end if;
    raise exception 'Invoice has already been posted' using errcode = '55000';
  end if;
  if invoice_row.accounting_state <> 'ready_for_posting' then
    raise exception 'Invoice must be prepared before posting' using errcode = '55000';
  end if;
  if invoice_row.status not in ('draft', 'approved') then
    raise exception 'Invoice status is not eligible for posting' using errcode = '55000';
  end if;
  if invoice_row.approval_status = 'pending' or invoice_row.approval_status = 'rejected' then
    raise exception 'Invoice approval state is not eligible for posting' using errcode = '55000';
  end if;
  if invoice_row.client_id is null then
    raise exception 'A customer is required before posting a sales invoice' using errcode = '23514';
  end if;

  select * into client_row
  from public.clients
  where id = invoice_row.client_id and company_id = invoice_row.company_id;
  if not found then
    raise exception 'Invoice customer is invalid for this company' using errcode = '23514';
  end if;
  if client_row.sales_blocked or client_row.account_status in ('on_hold', 'closed') then
    raise exception 'Sales are blocked for this customer' using errcode = '55000';
  end if;

  select * into period_row
  from public.accounting_periods
  where company_id = invoice_row.company_id
    and coalesce(invoice_row.posting_date, invoice_row.issue_date, current_date) between start_date and end_date
    and status = 'open'
  order by start_date desc
  limit 1
  for update;
  if not found then
    raise exception 'No open accounting period covers the invoice posting date' using errcode = '55000';
  end if;

  select count(*) into item_count from public.invoice_items where invoice_id = invoice_row.id;
  if item_count = 0 then
    raise exception 'A sales invoice requires at least one line item' using errcode = '23514';
  end if;
  if exists (
    select 1
    from public.invoice_items item
    where item.invoice_id = invoice_row.id
      and (
        coalesce(item.quantity, 0) <= 0
        or coalesce(item.amount, 0) < 0
        or coalesce(item.tax_rate, 0) < 0
        or coalesce(item.tax_rate, 0) > 100
        or coalesce(item.discount, 0) < 0
        or coalesce(item.discount, 0) > 100
      )
  ) then
    raise exception 'Invoice contains invalid quantity, amount, discount, or VAT values' using errcode = '23514';
  end if;

  select calculated.net_amount, calculated.tax_amount, calculated.gross_amount
  into net_amount, vat_amount, gross_amount
  from private.sales_invoice_amounts(invoice_row.id) as calculated;
  if gross_amount <= 0 then
    raise exception 'Invoice total must be greater than zero' using errcode = '23514';
  end if;

  journal_row := public.create_automatic_journal(
    invoice_row.company_id,
    'sales_invoice',
    'sales_invoice',
    invoice_row.id,
    invoice_row.invoice_number,
    coalesce(invoice_row.posting_date, invoice_row.issue_date, current_date),
    coalesce(invoice_row.issue_date, current_date),
    'Sales invoice ' || invoice_row.invoice_number,
    jsonb_build_object('net', net_amount, 'tax', vat_amount, 'gross', gross_amount),
    invoice_row.currency,
    invoice_row.branch_id,
    jsonb_build_object('invoice_number', invoice_row.invoice_number, 'client_id', invoice_row.client_id)
  );

  perform set_config('app.financial_workflow', 'authorized', true);
  perform set_config('app.change_reason', coalesce(nullif(trim(p_reason), ''), 'Sales invoice posted'), true);
  update public.invoices
  set status = 'posted',
      accounting_state = 'posted',
      posting_date = coalesce(posting_date, issue_date, current_date),
      fiscal_year_id = period_row.fiscal_year_id,
      posted_at = clock_timestamp(),
      posted_by = (select auth.uid()),
      posting_journal_entry_id = journal_row.id,
      idempotency_key = coalesce(p_idempotency_key, idempotency_key),
      total_amount = gross_amount,
      tax_amount = vat_amount
  where id = invoice_row.id
  returning * into invoice_row;
  perform set_config('app.financial_workflow', '', true);
  perform set_config('app.change_reason', '', true);

  perform private.emit_domain_outbox_event(
    invoice_row.company_id, invoice_row.branch_id, 'sales_invoice', invoice_row.id,
    'sales_invoice.posted',
    jsonb_build_object('invoice_number', invoice_row.invoice_number, 'journal_entry_id', journal_row.id, 'gross_amount', gross_amount),
    'sales_invoice.posted:' || invoice_row.id::text
  );
  return invoice_row;
end
$$;


--
-- Name: supplier_bills; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.supplier_bills (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    company_id uuid,
    vendor_id uuid NOT NULL,
    bill_number text NOT NULL,
    issue_date date DEFAULT CURRENT_DATE,
    due_date date,
    total_amount numeric DEFAULT 0 NOT NULL,
    tax_amount numeric DEFAULT 0,
    status text DEFAULT 'unpaid'::text,
    notes text,
    document_url text,
    created_at timestamp with time zone DEFAULT now(),
    branch_id uuid,
    fiscal_year_id uuid,
    posting_date date,
    approval_status text DEFAULT 'not_required'::text NOT NULL,
    approved_at timestamp with time zone,
    approved_by uuid,
    posted_at timestamp with time zone,
    posted_by uuid,
    posting_journal_entry_id uuid,
    currency text DEFAULT 'EUR'::text NOT NULL,
    exchange_rate numeric(20,10) DEFAULT 1 NOT NULL,
    idempotency_key uuid,
    source_document_type text,
    source_document_id uuid,
    credit_of_bill_id uuid,
    reversal_of_bill_id uuid,
    cancellation_reason text,
    correction_reason text,
    accounting_state text DEFAULT 'legacy'::text NOT NULL,
    input_vat_recoverable_amount numeric(20,4) DEFAULT 0 NOT NULL,
    input_vat_non_recoverable_amount numeric(20,4) DEFAULT 0 NOT NULL,
    is_import boolean DEFAULT false NOT NULL,
    reverse_charge boolean DEFAULT false NOT NULL,
    tax_reporting_category text DEFAULT 'domestic_purchase'::text NOT NULL,
    customs_document_reference text,
    CONSTRAINT supplier_bills_accounting_state_check CHECK ((accounting_state = ANY (ARRAY['legacy'::text, 'ready_for_posting'::text, 'posted'::text, 'reversed'::text, 'opening_balance'::text, 'excluded'::text]))),
    CONSTRAINT supplier_bills_approval_status_check CHECK ((approval_status = ANY (ARRAY['not_required'::text, 'pending'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT supplier_bills_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT supplier_bills_exchange_rate_check CHECK ((exchange_rate > (0)::numeric)),
    CONSTRAINT supplier_bills_vat_split_check CHECK (((input_vat_recoverable_amount >= (0)::numeric) AND (input_vat_non_recoverable_amount >= (0)::numeric) AND ((input_vat_recoverable_amount + input_vat_non_recoverable_amount) <= (GREATEST(COALESCE(tax_amount, (0)::numeric), (0)::numeric) + 0.0001))))
);


--
-- Name: post_supplier_bill(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_supplier_bill(p_bill_id uuid, p_idempotency_key uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS public.supplier_bills
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  bill_row public.supplier_bills;
  vendor_row public.vendors;
  journal_row public.journal_entries;
  expense_account_id uuid;
  payable_account_id uuid;
  input_vat_account_id uuid;
  gross_amount numeric(20,4);
  bill_tax_amount numeric(20,4);
  recoverable_vat numeric(20,4);
  nonrecoverable_vat numeric(20,4);
  expense_amount numeric(20,4);
  line_number integer := 0;
begin
  select * into bill_row from public.supplier_bills where id = p_bill_id for update;
  if not found then raise exception 'Supplier bill not found' using errcode = 'P0002'; end if;
  if not (select private.has_company_permission(bill_row.company_id, 'supplier_bill.post')) then
    raise exception 'Insufficient permission to post supplier bills' using errcode = '42501';
  end if;
  if bill_row.accounting_state = 'posted' then
    if p_idempotency_key is null or bill_row.idempotency_key = p_idempotency_key then return bill_row; end if;
    raise exception 'Supplier bill has already been posted' using errcode = '55000';
  end if;
  if bill_row.accounting_state <> 'ready_for_posting' then
    raise exception 'Supplier bill must be prepared before posting' using errcode = '55000';
  end if;
  select * into vendor_row from public.vendors where id = bill_row.vendor_id and company_id = bill_row.company_id;
  if not found then raise exception 'Supplier is invalid for this company' using errcode = '23514'; end if;

  gross_amount := round(coalesce(bill_row.total_amount, 0), 4);
  bill_tax_amount := round(greatest(coalesce(bill_row.tax_amount, 0), 0), 4);
  recoverable_vat := round(greatest(coalesce(bill_row.input_vat_recoverable_amount, 0), 0), 4);
  nonrecoverable_vat := round(greatest(coalesce(bill_row.input_vat_non_recoverable_amount, 0), 0), 4);
  -- Existing bills did not capture deductibility. They remain non-recoverable
  -- until a user explicitly classifies the VAT, never silently deductible.
  if recoverable_vat = 0 and nonrecoverable_vat = 0 and bill_tax_amount > 0 then
    nonrecoverable_vat := bill_tax_amount;
  end if;
  if round(recoverable_vat + nonrecoverable_vat, 4) <> bill_tax_amount then
    raise exception 'Purchase VAT must be explicitly split into recoverable and non-recoverable amounts' using errcode = '23514';
  end if;
  expense_amount := round(gross_amount - bill_tax_amount + nonrecoverable_vat, 4);
  if gross_amount <= 0 or expense_amount < 0 then raise exception 'Supplier bill amounts are invalid' using errcode = '23514'; end if;

  if vendor_row.default_expense_account_id is not null then
    select id into expense_account_id from public.chart_of_accounts
    where id = vendor_row.default_expense_account_id and company_id = bill_row.company_id and active and posting_allowed;
  end if;
  if expense_account_id is null then
    select id into expense_account_id from public.chart_of_accounts
    where company_id = bill_row.company_id and code = '6010' and active and posting_allowed limit 1;
  end if;
  if vendor_row.default_payable_account_id is not null then
    select id into payable_account_id from public.chart_of_accounts
    where id = vendor_row.default_payable_account_id and company_id = bill_row.company_id and active and posting_allowed;
  end if;
  if payable_account_id is null then
    select id into payable_account_id from public.chart_of_accounts
    where company_id = bill_row.company_id and code = '2010' and active and posting_allowed limit 1;
  end if;
  select id into input_vat_account_id from public.chart_of_accounts
  where company_id = bill_row.company_id and code = '1300' and active and posting_allowed limit 1;
  if expense_account_id is null or payable_account_id is null or (recoverable_vat > 0 and input_vat_account_id is null) then
    raise exception 'Supplier bill accounts are not mapped' using errcode = '23514';
  end if;

  journal_row := public.create_journal_entry(
    bill_row.company_id, coalesce(bill_row.posting_date, bill_row.issue_date, current_date),
    coalesce(bill_row.issue_date, current_date), 'Supplier bill ' || bill_row.bill_number,
    bill_row.bill_number, bill_row.currency, bill_row.exchange_rate, bill_row.branch_id, 'automatic'
  );
  update public.journal_entries
  set source_type = 'supplier_bill', source_id = bill_row.id, source_key = bill_row.bill_number,
      metadata = jsonb_build_object('netExpense', expense_amount, 'tax', bill_tax_amount,
        'recoverableVat', recoverable_vat, 'nonRecoverableVat', nonrecoverable_vat)
  where id = journal_row.id;
  if expense_amount > 0 then
    line_number := line_number + 1;
    insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,branch_id,created_by)
    values(journal_row.id,bill_row.company_id,line_number,expense_account_id,'Supplier expense',expense_amount,0,bill_row.currency,expense_amount,bill_row.branch_id,(select auth.uid()));
  end if;
  if recoverable_vat > 0 then
    line_number := line_number + 1;
    insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,branch_id,tax_code,tax_amount,created_by)
    values(journal_row.id,bill_row.company_id,line_number,input_vat_account_id,'Recoverable input VAT',recoverable_vat,0,bill_row.currency,recoverable_vat,bill_row.branch_id,bill_row.tax_reporting_category,recoverable_vat,(select auth.uid()));
  end if;
  line_number := line_number + 1;
  insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,branch_id,created_by)
  values(journal_row.id,bill_row.company_id,line_number,payable_account_id,'Supplier payable',0,gross_amount,bill_row.currency,gross_amount,bill_row.branch_id,(select auth.uid()));
  journal_row := public.post_journal_entry(journal_row.id, coalesce(nullif(trim(p_reason), ''), 'Supplier bill posted'));

  perform set_config('app.financial_workflow', 'authorized', true);
  perform set_config('app.change_reason', coalesce(nullif(trim(p_reason), ''), 'Supplier bill posted'), true);
  update public.supplier_bills
  set accounting_state = 'posted', posting_date = coalesce(posting_date, issue_date, current_date),
      fiscal_year_id = (select fiscal_year_id from public.accounting_periods where id = journal_row.period_id),
      posted_at = clock_timestamp(), posted_by = (select auth.uid()), posting_journal_entry_id = journal_row.id,
      idempotency_key = coalesce(p_idempotency_key, idempotency_key), total_amount = gross_amount, tax_amount = bill_tax_amount,
      input_vat_recoverable_amount = recoverable_vat, input_vat_non_recoverable_amount = nonrecoverable_vat
  where id = bill_row.id returning * into bill_row;
  perform set_config('app.financial_workflow', '', true);
  perform set_config('app.change_reason', '', true);
  return bill_row;
end
$$;


--
-- Name: prepare_sales_invoice_for_posting(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_sales_invoice_for_posting(p_invoice_id uuid, p_reason text DEFAULT NULL::text) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  invoice_row public.invoices;
begin
  select *
  into invoice_row
  from public.invoices
  where id = p_invoice_id
  for update;

  if not found then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if not (select private.has_company_permission(invoice_row.company_id, 'sales_invoice.create')) then
    raise exception 'Insufficient permission to prepare sales invoices' using errcode = '42501';
  end if;
  if public.get_my_company_role(invoice_row.company_id) = 'employee'
     and invoice_row.user_id is distinct from (select auth.uid()) then
    raise exception 'Employees can only post invoices they created' using errcode = '42501';
  end if;
  if invoice_row.status not in ('draft', 'approved') then
    raise exception 'Only draft or approved invoices can be prepared for posting' using errcode = '55000';
  end if;
  if invoice_row.accounting_state not in ('legacy', 'ready_for_posting') then
    raise exception 'Invoice is already accounted for or excluded from posting' using errcode = '55000';
  end if;
  if invoice_row.approval_status = 'pending' then
    raise exception 'Invoice approval is still pending' using errcode = '55000';
  end if;

  perform set_config('app.change_reason', coalesce(nullif(trim(p_reason), ''), 'Prepared for posting'), true);
  update public.invoices
  set accounting_state = 'ready_for_posting',
      posting_date = coalesce(posting_date, issue_date, current_date)
  where id = invoice_row.id
  returning * into invoice_row;
  perform set_config('app.change_reason', '', true);

  perform private.emit_domain_outbox_event(
    invoice_row.company_id, invoice_row.branch_id, 'sales_invoice', invoice_row.id,
    'sales_invoice.ready_for_posting',
    jsonb_build_object('invoice_number', invoice_row.invoice_number),
    'sales_invoice.ready_for_posting:' || invoice_row.id::text
  );
  return invoice_row;
end
$$;


--
-- Name: prepare_supplier_bill_for_posting(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_supplier_bill_for_posting(p_bill_id uuid, p_reason text DEFAULT NULL::text) RETURNS public.supplier_bills
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  bill_row public.supplier_bills;
begin
  select * into bill_row from public.supplier_bills where id = p_bill_id for update;
  if not found then
    raise exception 'Supplier bill not found' using errcode = 'P0002';
  end if;
  if not (select private.has_company_permission(bill_row.company_id, 'supplier_bill.post')) then
    raise exception 'Insufficient permission to prepare supplier bills' using errcode = '42501';
  end if;
  if bill_row.accounting_state not in ('legacy', 'ready_for_posting') then
    raise exception 'Supplier bill is already accounted for or excluded from posting' using errcode = '55000';
  end if;
  if bill_row.vendor_id is null then
    raise exception 'A supplier is required before posting a supplier bill' using errcode = '23514';
  end if;
  if coalesce(bill_row.total_amount, 0) <= 0 then
    raise exception 'Supplier bill total must be greater than zero' using errcode = '23514';
  end if;

  perform set_config('app.change_reason', coalesce(nullif(trim(p_reason), ''), 'Prepared supplier bill for posting'), true);
  update public.supplier_bills
  set accounting_state = 'ready_for_posting',
      posting_date = coalesce(posting_date, issue_date, current_date)
  where id = bill_row.id
  returning * into bill_row;
  perform set_config('app.change_reason', '', true);
  return bill_row;
end
$$;


--
-- Name: tax_declarations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_declarations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    declaration_type text NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    source_checksum text,
    exported_at timestamp with time zone,
    submitted_manually_at timestamp with time zone,
    confirmed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT tax_declarations_check CHECK ((period_end >= period_start)),
    CONSTRAINT tax_declarations_declaration_type_check CHECK ((declaration_type = ANY (ARRAY['vat'::text, 'sales_book'::text, 'purchase_book'::text, 'payroll_withholding'::text, 'pension'::text, 'withholding'::text, 'corporate_tax'::text]))),
    CONSTRAINT tax_declarations_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT tax_declarations_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'ready'::text, 'exported'::text, 'submitted_manually'::text, 'confirmed'::text, 'amended'::text])))
);


--
-- Name: prepare_tax_declaration(uuid, text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_tax_declaration(p_company_id uuid, p_declaration_type text, p_period_start date, p_period_end date) RETURNS public.tax_declarations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result public.tax_declarations;
declare payload_value jsonb;
begin
  if not (select private.has_company_permission(p_company_id, 'tax.declaration.prepare')) then
    raise exception 'Insufficient permission to prepare tax declaration' using errcode = '42501';
  end if;
  payload_value := jsonb_build_object(
    'declarationType', lower(trim(p_declaration_type)),
    'periodStart', p_period_start,
    'periodEnd', p_period_end,
    'submittedElectronically', false,
    'salesBook', coalesce((select jsonb_agg(to_jsonb(book) order by book.invoice_date, book.invoice_number)
      from public.kosovo_sales_book book where book.company_id=p_company_id and book.period_start between date_trunc('month',p_period_start)::date and date_trunc('month',p_period_end)::date), '[]'::jsonb),
    'purchaseBook', coalesce((select jsonb_agg(to_jsonb(book) order by book.bill_date, book.bill_number)
      from public.kosovo_purchase_book book where book.company_id=p_company_id and book.period_start between date_trunc('month',p_period_start)::date and date_trunc('month',p_period_end)::date), '[]'::jsonb),
    'withholding', coalesce((select jsonb_agg(to_jsonb(item) order by item.payment_date)
      from public.withholding_transactions item where item.company_id=p_company_id and item.payment_date between p_period_start and p_period_end), '[]'::jsonb)
  );
  insert into public.tax_declarations(company_id,declaration_type,period_start,period_end,status,payload,source_checksum,created_by,updated_by)
  values(p_company_id,lower(trim(p_declaration_type)),p_period_start,p_period_end,'ready',payload_value,
    encode(extensions.digest(convert_to(payload_value::text,'UTF8'),'sha256'),'hex'),(select auth.uid()),(select auth.uid()))
  on conflict (company_id,declaration_type,period_start,period_end) do update set
    payload=excluded.payload, source_checksum=excluded.source_checksum, status=case when public.tax_declarations.status in ('submitted_manually','confirmed') then 'amended' else 'ready' end,
    updated_at=clock_timestamp(), updated_by=(select auth.uid())
  returning * into result;
  return result;
end
$$;


--
-- Name: preview_asset_depreciation(uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_asset_depreciation(p_company_id uuid, p_period_start date, p_period_end date, p_frequency text DEFAULT 'monthly'::text) RETURNS TABLE(fixed_asset_id uuid, asset_number text, asset_name text, book_depreciation numeric, tax_depreciation numeric, book_accumulated_before numeric, tax_accumulated_before numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not (select private.has_company_permission(p_company_id, 'asset.view'))
     and not (select private.has_company_permission(p_company_id, 'asset.depreciation.post')) then
    raise exception 'Insufficient permission to preview depreciation' using errcode = '42501';
  end if;
  if p_frequency not in ('monthly','yearly') or p_period_end < p_period_start then raise exception 'Invalid depreciation period' using errcode = '23514'; end if;
  return query
  select asset.id,asset.asset_number,asset.name,
    least(greatest(round(asset.acquisition_cost / asset.useful_life_months * case when p_frequency='yearly' then 12 else 1 end,4),0),greatest(asset.acquisition_cost-asset.accumulated_book_depreciation,0)),
    least(greatest(round(asset.acquisition_cost * asset.tax_depreciation_rate_percent / 100 * case when p_frequency='yearly' then 1 else 1.0/12 end,4),0),greatest(asset.acquisition_cost-asset.accumulated_tax_depreciation,0)),
    asset.accumulated_book_depreciation,asset.accumulated_tax_depreciation
  from public.fixed_assets asset
  where asset.company_id=p_company_id and asset.status='active' and asset.placed_in_service_date <= p_period_end
    and asset.accumulated_book_depreciation < asset.acquisition_cost;
end
$$;


--
-- Name: process_mock_fiscal_transaction(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_mock_fiscal_transaction(p_fiscal_transaction_id uuid, p_scenario text DEFAULT 'success'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  fiscal_row public.fiscal_transactions;
  attempt_number_value integer;
  next_status text;
  response_code text;
  retryable_value boolean := false;
  correlation_id_value text;
  provider_ids jsonb := '{}'::jsonb;
  qr_value text;
begin
  select *
  into fiscal_row
  from public.fiscal_transactions
  where id = p_fiscal_transaction_id
  for update;

  if not found
     or not (select private.has_company_permission(fiscal_row.company_id, 'pos.fiscal.retry')) then
    raise exception 'Fiscal transaction not found or access denied' using errcode = '42501';
  end if;
  if fiscal_row.provider_code <> 'mock' then
    raise exception 'Only the mock provider can be processed by this command' using errcode = '23514';
  end if;
  if not coalesce((
    select flag.enabled
    from public.company_feature_flags flag
    where flag.company_id = fiscal_row.company_id
      and flag.flag = 'mock_fiscal_provider_enabled'
  ), false) then
    raise exception 'Mock fiscal provider is disabled for this company' using errcode = '55000';
  end if;
  if p_scenario not in (
    'success','validation_failure','network_timeout','provider_rejection',
    'duplicate_transaction','delayed_response','retry_success','retry_failure',
    'reconciliation_success','reconciliation_mismatch'
  ) then
    raise exception 'Unsupported mock fiscal scenario' using errcode = '23514';
  end if;

  attempt_number_value := fiscal_row.attempt_count + 1;
  correlation_id_value := 'mock:' || fiscal_row.local_transaction_id::text || ':' || attempt_number_value::text;

  case p_scenario
    when 'success', 'retry_success', 'reconciliation_success' then
      next_status := case when p_scenario = 'reconciliation_success' then 'reconciled' else 'fiscalized' end;
      response_code := 'MOCK_OK';
      provider_ids := jsonb_build_object(
        'provider_transaction_id', 'MOCK-' || fiscal_row.local_transaction_id::text,
        'verification_code', 'VERIFY-' || left(fiscal_row.local_transaction_id::text, 8)
      );
      qr_value := 'operix-fiscal://mock/' || fiscal_row.local_transaction_id::text;
    when 'validation_failure', 'provider_rejection' then
      next_status := 'rejected';
      response_code := case when p_scenario = 'validation_failure' then 'MOCK_VALIDATION' else 'MOCK_REJECTED' end;
    when 'network_timeout', 'delayed_response', 'retry_failure' then
      next_status := 'retry_scheduled';
      response_code := 'MOCK_RETRYABLE';
      retryable_value := true;
    when 'duplicate_transaction', 'reconciliation_mismatch' then
      next_status := 'reconciliation_required';
      response_code := case when p_scenario = 'duplicate_transaction' then 'MOCK_DUPLICATE' else 'MOCK_MISMATCH' end;
  end case;

  insert into public.fiscal_submission_attempts (
    company_id, fiscal_transaction_id, attempt_number, response_timestamp,
    request_checksum, status, provider_response_code, failure_category,
    retryable, correlation_id, result_payload, created_by
  )
  values (
    fiscal_row.company_id, fiscal_row.id, attempt_number_value, clock_timestamp(),
    fiscal_row.request_checksum, next_status, response_code,
    case when next_status in ('rejected','retry_scheduled','reconciliation_required') then p_scenario end,
    retryable_value, correlation_id_value,
    jsonb_build_object('scenario', p_scenario, 'status', next_status),
    (select auth.uid())
  );

  perform set_config('app.fiscal_workflow', 'authorized', true);
  update public.fiscal_transactions
  set status = next_status,
      provider_identifiers = provider_ids,
      qr_data = qr_value,
      attempt_count = attempt_number_value,
      last_attempt_at = clock_timestamp(),
      next_retry_at = case when retryable_value then clock_timestamp() + make_interval(secs => least(3600, power(2, attempt_number_value)::integer * 15)) end,
      error_category = case when next_status in ('rejected','retry_scheduled','reconciliation_required') then p_scenario end,
      error_message = case when next_status in ('rejected','retry_scheduled','reconciliation_required') then response_code end,
      reconciliation_state = case when next_status in ('reconciliation_required','reconciled') then next_status end,
      updated_at = clock_timestamp(),
      updated_by = (select auth.uid())
  where id = fiscal_row.id
  returning * into fiscal_row;
  perform set_config('app.fiscal_workflow', '', true);

  insert into public.fiscal_reconciliation_events (
    company_id, fiscal_transaction_id, event_type, previous_status, new_status,
    details, actor_id
  )
  values (
    fiscal_row.company_id, fiscal_row.id, 'mock_provider_result',
    case when attempt_number_value = 1 then 'pending_validation' else null end,
    fiscal_row.status,
    jsonb_build_object('scenario', p_scenario, 'response_code', response_code),
    (select auth.uid())
  );

  return jsonb_build_object(
    'fiscal_transaction_id', fiscal_row.id,
    'status', fiscal_row.status,
    'attempt_count', fiscal_row.attempt_count,
    'retryable', retryable_value,
    'response_code', response_code,
    'qr_data', fiscal_row.qr_data
  );
end
$$;


--
-- Name: process_new_user_invite(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_new_user_invite() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  token_value text;
  target_company_id uuid;
  invitation public.company_invitations%rowtype;
  target_role_id uuid;
  legacy_role text;
  membership_id_value uuid;
begin
  select auth_user.raw_user_meta_data ->> 'invite_token'
    into token_value
  from auth.users auth_user
  where auth_user.id = new.id;

  if nullif(trim(token_value), '') is null then
    return new;
  end if;

  select company.id into target_company_id
  from public.companies company
  where lower(company.invite_token) = lower(trim(token_value));

  if target_company_id is not null then
    insert into public.memberships (company_id, user_id, role, status)
    values (target_company_id, new.id, 'employee', 'pending')
    on conflict (company_id, user_id) do nothing;

    update public.profiles
    set company_id = coalesce(company_id, target_company_id),
        active_company_id = coalesce(active_company_id, target_company_id)
    where id = new.id;

    return new;
  end if;

  select * into invitation
  from public.company_invitations
  where token_hash = encode(extensions.digest(trim(token_value), 'sha256'), 'hex')
    and status = 'pending'
    and expires_at > now()
    and lower(email) = lower(new.email)
  for update;

  if invitation.id is null then
    return new;
  end if;

  select role.id into target_role_id
  from public.app_roles role
  where lower(role.code) = lower(invitation.role_code)
    and (role.company_id is null or role.company_id = invitation.company_id)
  order by role.company_id nulls last
  limit 1;

  legacy_role := case
    when invitation.role_code = 'owner' then 'owner'
    when invitation.role_code in ('company_administrator', 'super_administrator') then 'admin'
    else 'worker'
  end;

  insert into public.memberships (company_id, user_id, role, status)
  values (invitation.company_id, new.id, legacy_role, 'active')
  on conflict (company_id, user_id) do update
    set role = excluded.role,
        status = 'active'
  returning id into membership_id_value;

  if target_role_id is not null then
    delete from public.membership_role_assignments
    where membership_id = membership_id_value;

    insert into public.membership_role_assignments (membership_id, role_id, created_by)
    values (membership_id_value, target_role_id, invitation.invited_by);
  end if;

  update public.company_invitations
  set status = 'accepted', accepted_by = new.id, accepted_at = now(), updated_at = now()
  where id = invitation.id;

  update public.profiles
  set company_id = coalesce(company_id, invitation.company_id),
      active_company_id = coalesce(active_company_id, invitation.company_id)
  where id = new.id;

  return new;
end;
$$;


--
-- Name: rbac_accept_user_access_invitation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_accept_user_access_invitation(p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  operation_row public.user_access_operations;
  membership_id_value uuid;
begin
  if actor_id is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  select * into operation_row from public.user_access_operations where id = p_operation_id for update;
  if operation_row.id is null or operation_row.operation_type <> 'invite' then raise exception 'Invitation was not found' using errcode = '22023'; end if;
  if operation_row.target_user_id is distinct from actor_id then raise exception 'This invitation belongs to another OperiX account' using errcode = '42501'; end if;
  if operation_row.status = 'completed' then return jsonb_build_object('operation_id',operation_row.id,'status','completed','membership_id',operation_row.target_membership_id); end if;
  if operation_row.status <> 'invite_pending' or operation_row.expires_at <= now() then raise exception 'This invitation has expired or is not ready' using errcode = '41001'; end if;
  membership_id_value := operation_row.target_membership_id;
  perform set_config('app.membership_role_workflow', 'authorized', true);
  update public.memberships set status = 'active', suspended_at = null, revoked_at = null, last_active_at = now() where id = membership_id_value;
  perform set_config('app.membership_role_workflow', '', true);
  perform set_config('app.user_access_invitation_workflow', 'authorized', true);
  update public.company_invitations set status = 'accepted', accepted_by = actor_id, accepted_at = now(), updated_at = now() where user_access_operation_id = operation_row.id and status = 'pending';
  perform set_config('app.user_access_invitation_workflow', '', true);
  update public.user_access_operations set status = 'completed', completed_at = now(), updated_at = now(), after_state = after_state || jsonb_build_object('status','active') where id = operation_row.id;
  perform private.rbac_write_user_access_audit(operation_row.company_id, actor_id, 'USER_ACTIVATED', 'membership', membership_id_value, jsonb_build_object('status','pending'), jsonb_build_object('status','active','role_code',operation_row.requested_role_code), 'User accepted the OperiX invitation');
  return jsonb_build_object('operation_id',operation_row.id,'status','completed','membership_id',membership_id_value,'company_id',operation_row.company_id);
exception when others then
  perform set_config('app.membership_role_workflow', '', true);
  perform set_config('app.user_access_invitation_workflow', '', true);
  raise;
end;
$$;


--
-- Name: rbac_activate_existing_user_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_activate_existing_user_access(p_operation_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  operation_row public.user_access_operations;
  membership_id_value uuid;
begin
  if not private.operix_server_request() then raise exception 'Server invitation workflow required' using errcode = '42501'; end if;
  select * into operation_row from public.user_access_operations where id = p_operation_id for update;
  if operation_row.id is null or operation_row.operation_type <> 'invite' then raise exception 'Invitation operation was not found' using errcode = '22023'; end if;
  if operation_row.target_user_id is distinct from p_user_id then raise exception 'The existing account does not match the invitation' using errcode = '42501'; end if;
  if operation_row.status = 'completed' then return jsonb_build_object('operation_id', operation_row.id, 'status', 'completed', 'membership_id', operation_row.target_membership_id, 'user_id', p_user_id); end if;
  if operation_row.status <> 'invite_pending' or operation_row.expires_at <= now() then raise exception 'The invitation is not ready for activation' using errcode = '41001'; end if;
  membership_id_value := operation_row.target_membership_id;
  if membership_id_value is null then raise exception 'The tenant membership was not created' using errcode = '22023'; end if;
  perform set_config('app.membership_role_workflow', 'authorized', true);
  update public.memberships set status = 'active', suspended_at = null, revoked_at = null, last_active_at = now() where id = membership_id_value;
  perform set_config('app.membership_role_workflow', '', true);
  perform set_config('app.user_access_invitation_workflow', 'authorized', true);
  update public.company_invitations set status = 'accepted', accepted_by = p_user_id, accepted_at = now(), updated_at = now() where user_access_operation_id = operation_row.id and status = 'pending';
  perform set_config('app.user_access_invitation_workflow', '', true);
  update public.user_access_operations set status = 'completed', completed_at = now(), updated_at = now(), after_state = after_state || jsonb_build_object('status','active','existing_account',true) where id = operation_row.id returning * into operation_row;
  perform private.rbac_write_user_access_audit(operation_row.company_id, operation_row.created_by, 'USER_ACTIVATED', 'membership', membership_id_value, jsonb_build_object('status','pending'), jsonb_build_object('status','active','role_code',operation_row.requested_role_code,'existing_account',true), 'Existing OperiX account linked to the tenant after server-confirmed seat billing');
  return jsonb_build_object('operation_id', operation_row.id, 'status', 'completed', 'membership_id', membership_id_value, 'user_id', p_user_id);
exception when others then
  perform set_config('app.membership_role_workflow', '', true);
  perform set_config('app.user_access_invitation_workflow', '', true);
  raise;
end;
$$;


--
-- Name: rbac_begin_user_access_operation(uuid, text, text, uuid, text, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_begin_user_access_operation(p_company_id uuid, p_operation_key text, p_operation_type text, p_membership_id uuid DEFAULT NULL::uuid, p_email text DEFAULT NULL::text, p_first_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text, p_role_code text DEFAULT 'employee'::text, p_permissions jsonb DEFAULT '{}'::jsonb, p_scopes jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  actor_id uuid := (select auth.uid());
  root_company_id uuid;
  operation_row public.user_access_operations;
  pending_invite public.user_access_operations;
  target_membership public.memberships;
  target_user_id uuid;
  company_owner_id uuid;
  role_value text := case lower(trim(coalesce(p_role_code, '')))
    when 'admin' then 'company_administrator'
    else lower(trim(coalesce(p_role_code, '')))
  end;
  normalized_email text := lower(trim(coalesce(p_email, '')));
  before_access jsonb;
  billing_required_value boolean;
  delta_value integer;
  billing_summary jsonb;
begin
  if actor_id is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if not private.rbac_is_user_access_admin(p_company_id) then
    raise exception 'You do not have permission to manage Users & Access' using errcode = '42501';
  end if;
  if p_operation_key is null or char_length(trim(p_operation_key)) < 16 then
    raise exception 'An idempotency key is required' using errcode = '22023';
  end if;
  if p_operation_type not in ('invite','suspend','reactivate','remove') then
    raise exception 'This user operation is not supported' using errcode = '22023';
  end if;
  root_company_id := private.invoice_billing_root_company_id(p_company_id);
  if root_company_id is null then raise exception 'Billing account was not found' using errcode = '22023'; end if;

  perform pg_advisory_xact_lock(hashtextextended(root_company_id::text, 922337));
  select * into operation_row from public.user_access_operations operation
  where operation.company_id = p_company_id and operation.operation_key = trim(p_operation_key)
  for update;
  if operation_row.id is not null then
    if operation_row.operation_type <> p_operation_type then
      raise exception 'This idempotency key is already used for another user operation' using errcode = '40901';
    end if;
    if operation_row.status in ('failed', 'canceled')
       or (operation_row.status = 'pending_billing' and operation_row.expires_at <= now()) then
      -- A definitive billing failure did not activate a seat. Reopening the
      -- same idempotency key makes a payment-method correction/retry safe
      -- without creating another operation or another reserved seat.
      update public.user_access_operations
      set status = 'pending_billing', failure_code = null, failure_message = null,
          billing_preview = '{}'::jsonb, updated_at = now(), expires_at = now() + interval '20 minutes'
      where id = operation_row.id
      returning * into operation_row;
      billing_summary := public.rbac_get_users_access_billing_summary(p_company_id);
      return jsonb_build_object('operation_id', operation_row.id, 'status', operation_row.status, 'operation_type', operation_row.operation_type, 'billing_required', operation_row.billing_required, 'billable_user_delta', operation_row.billable_user_delta, 'billing_preview', operation_row.billing_preview, 'summary', billing_summary);
    else
      billing_summary := public.rbac_get_users_access_billing_summary(p_company_id);
      return jsonb_build_object('operation_id', operation_row.id, 'status', operation_row.status, 'operation_type', operation_row.operation_type, 'billing_required', operation_row.billing_required, 'billable_user_delta', operation_row.billable_user_delta, 'billing_preview', operation_row.billing_preview, 'summary', billing_summary);
    end if;
  end if;

  if p_operation_type = 'invite' then
    if normalized_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then raise exception 'Enter a valid email address' using errcode = '22023'; end if;
    if char_length(coalesce(p_first_name, '')) > 100 or char_length(coalesce(p_last_name, '')) > 100 then raise exception 'Name is too long' using errcode = '22023'; end if;
    perform private.rbac_validate_user_access_payload(role_value, p_permissions, p_scopes);
    if not private.rbac_is_platform_admin()
       and private.rbac_role_code(p_company_id) <> 'company_administrator'
       and role_value <> 'employee' then
      raise exception 'Only a tenant Admin can assign Admin or Manager roles' using errcode = '42501';
    end if;
    if not private.rbac_is_platform_admin()
       and private.rbac_role_code(p_company_id) <> 'company_administrator'
       and exists (
         select 1 from jsonb_each(coalesce(p_permissions, '{}'::jsonb)) permission
         where (permission.value #>> '{}')::boolean
           and not private.has_company_permission(p_company_id, permission.key)
       ) then
      raise exception 'You cannot grant a permission you do not hold' using errcode = '42501';
    end if;
    update public.user_access_operations expired
    set status = 'canceled', failure_code = 'expired', failure_message = 'The confirmation window expired.', updated_at = now()
    where expired.company_id = p_company_id
      and expired.operation_type = 'invite'
      and lower(expired.email) = normalized_email
      and expired.status in ('pending_billing','billing_succeeded','invite_pending')
      and expired.expires_at <= now();
    if exists (
      select 1 from public.memberships membership join auth.users auth_user on auth_user.id = membership.user_id
      where membership.company_id = p_company_id and lower(auth_user.email) = normalized_email and lower(coalesce(membership.status, 'active')) <> 'revoked'
    ) then raise exception 'This email already has access to the company' using errcode = '23505'; end if;
    if exists (
      select 1 from public.user_access_operations pending
      where pending.company_id = p_company_id and pending.operation_type = 'invite' and lower(pending.email) = normalized_email
        and pending.status in ('pending_billing','billing_succeeded','invite_pending') and pending.expires_at > now()
    ) then raise exception 'An invitation for this email is already pending' using errcode = '23505'; end if;
    billing_required_value := exists (
      select 1 from public.subscription_accounts account
      where account.company_id = root_company_id and account.product in ('invoice', 'suite')
        and lower(coalesce(account.status, 'trialing')) not in ('trialing')
        and account.stripe_subscription_id is not null
    );
    delta_value := 1;
  else
    if p_operation_type = 'remove' and p_membership_id is null then
      if normalized_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then raise exception 'An email is required to remove a pending invitation' using errcode = '22023'; end if;
      select pending.* into pending_invite
      from public.user_access_operations pending
      where pending.company_id = p_company_id
        and pending.operation_type = 'invite'
        and pending.target_membership_id is null
        and pending.email = normalized_email
        and pending.status in ('pending_billing','billing_succeeded','invite_pending','failed')
        and (
          pending.expires_at > now()
          or (pending.status = 'failed' and pending.updated_at > now() - interval '20 minutes')
        )
      order by pending.created_at desc
      limit 1
      for update;
      if pending_invite.id is null then raise exception 'The pending invitation was not found' using errcode = '22023'; end if;
      target_user_id := pending_invite.target_user_id;
      before_access := jsonb_build_object(
        'invite_operation_id', pending_invite.id,
        'email', pending_invite.email,
        'status', pending_invite.status,
        'role_code', pending_invite.requested_role_code,
        'user_id', pending_invite.target_user_id
      );
      billing_required_value := pending_invite.status <> 'failed' and exists (
        select 1 from public.subscription_accounts account where account.company_id = root_company_id and account.product in ('invoice', 'suite') and account.stripe_subscription_id is not null and lower(coalesce(account.status, 'trialing')) not in ('trialing')
      );
      delta_value := case when pending_invite.status = 'failed' then 0 else -1 end;
      role_value := coalesce(pending_invite.requested_role_code, 'employee');
      normalized_email := pending_invite.email;
    else
      select membership.* into target_membership
      from public.memberships membership join public.companies company on company.id = membership.company_id
      where membership.id = p_membership_id and membership.company_id = p_company_id
      for update;
      if target_membership.id is null then raise exception 'Membership was not found' using errcode = '22023'; end if;
      target_user_id := target_membership.user_id;
      select company.owner_id into company_owner_id from public.companies company where company.id = target_membership.company_id;
      if exists (select 1 from public.control_platform_admins platform_admin where platform_admin.user_id = target_membership.user_id and platform_admin.revoked_at is null) then raise exception 'Platform Super Admin accounts are outside tenant user management' using errcode = '42501'; end if;
      if not private.rbac_is_platform_admin()
         and private.rbac_role_code(p_company_id) <> 'company_administrator'
         and p_operation_type in ('remove','suspend','reactivate')
         and private.rbac_member_role_code(target_membership.id) <> 'employee' then
        raise exception 'Only a tenant Admin can manage Admin or Manager accounts' using errcode = '42501';
      end if;
      if p_operation_type in ('remove','suspend') and target_membership.user_id = actor_id and private.rbac_active_admin_count(p_company_id, target_membership.id) < 1 then
        raise exception 'This company must have at least one active Admin. Assign another Admin before changing your account.' using errcode = '42501';
      end if;
      if p_operation_type = 'remove' and target_membership.user_id = company_owner_id then raise exception 'Transfer company ownership before removing the owner' using errcode = '42501'; end if;
      if p_operation_type = 'remove' and lower(coalesce(target_membership.status, 'active')) = 'revoked' then raise exception 'This user has already been removed' using errcode = '40901'; end if;
      if p_operation_type = 'suspend' and lower(coalesce(target_membership.status, 'active')) = 'suspended' then raise exception 'This user is already suspended' using errcode = '40901'; end if;
      if p_operation_type = 'reactivate' and lower(coalesce(target_membership.status, 'active')) <> 'suspended' then raise exception 'This user is not suspended' using errcode = '40901'; end if;
      before_access := jsonb_build_object('status', target_membership.status, 'role_code', private.rbac_member_role_code(target_membership.id), 'access', private.rbac_member_access_json(target_membership.id));
      billing_required_value := p_operation_type = 'remove' and exists (
        select 1 from public.subscription_accounts account where account.company_id = root_company_id and account.product in ('invoice', 'suite') and account.stripe_subscription_id is not null and lower(coalesce(account.status, 'trialing')) not in ('trialing')
      );
      delta_value := case when p_operation_type = 'remove' then -1 else 0 end;
      role_value := private.rbac_member_role_code(target_membership.id);
      normalized_email := (select lower(coalesce(auth_user.email, '')) from auth.users auth_user where auth_user.id = target_membership.user_id);
    end if;
  end if;

  insert into public.user_access_operations(company_id,root_company_id,operation_key,operation_type,target_membership_id,target_user_id,email,first_name,last_name,requested_role_code,requested_permissions,requested_scopes,status,billing_required,billable_user_delta,before_state,created_by)
  values(p_company_id,root_company_id,trim(p_operation_key),p_operation_type,target_membership.id,case when p_operation_type = 'invite' then null else target_user_id end,normalized_email,nullif(trim(p_first_name),''),nullif(trim(p_last_name),''),case when p_operation_type = 'invite' then role_value else null end,coalesce(p_permissions,'{}'::jsonb),coalesce(p_scopes,'{}'::jsonb),'pending_billing',billing_required_value,delta_value,coalesce(before_access,'{}'::jsonb),actor_id)
  returning * into operation_row;
  billing_summary := public.rbac_get_users_access_billing_summary(p_company_id);
  return jsonb_build_object('operation_id', operation_row.id, 'status', operation_row.status, 'operation_type', operation_row.operation_type, 'billing_required', operation_row.billing_required, 'billable_user_delta', operation_row.billable_user_delta, 'billing_preview', billing_summary, 'summary', billing_summary);
end;
$_$;


--
-- Name: rbac_claim_user_access_billing_lock(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_claim_user_access_billing_lock(p_root_company_id uuid, p_operation_id uuid, p_lease_seconds integer DEFAULT 120) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  current_lock public.user_access_billing_locks;
begin
  if not private.operix_server_request() then raise exception 'Server billing workflow required' using errcode = '42501'; end if;
  if p_lease_seconds < 30 or p_lease_seconds > 600 then raise exception 'Invalid billing lock lease' using errcode = '22023'; end if;
  select * into current_lock from public.user_access_billing_locks where root_company_id = p_root_company_id for update;
  if current_lock.root_company_id is not null and current_lock.locked_until > now() and current_lock.operation_id <> p_operation_id then return false; end if;
  insert into public.user_access_billing_locks(root_company_id,operation_id,locked_until,updated_at)
  values(p_root_company_id,p_operation_id,now() + make_interval(secs => p_lease_seconds),now())
  on conflict(root_company_id) do update set operation_id = excluded.operation_id, locked_until = excluded.locked_until, updated_at = excluded.updated_at;
  return true;
end;
$$;


--
-- Name: rbac_finalize_user_access_invite(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_finalize_user_access_invite(p_operation_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  operation_row public.user_access_operations;
  membership_id_value uuid;
  auth_email text;
  access jsonb;
  membership_created boolean := false;
begin
  if not private.operix_server_request() then raise exception 'Server invitation workflow required' using errcode = '42501'; end if;
  select * into operation_row from public.user_access_operations where id = p_operation_id for update;
  if operation_row.id is null or operation_row.operation_type <> 'invite' then raise exception 'Invitation operation was not found' using errcode = '22023'; end if;
  if operation_row.status not in ('billing_succeeded','invite_pending') then raise exception 'Billing must succeed before the user seat is created' using errcode = '40201'; end if;
  select lower(email) into auth_email from auth.users where id = p_user_id;
  if auth_email is null or auth_email <> lower(operation_row.email) then raise exception 'The invited account does not match the requested email' using errcode = '42501'; end if;
  if exists (
    select 1
    from public.control_platform_admins platform_admin
    where platform_admin.user_id = p_user_id
      and platform_admin.revoked_at is null
  ) then
    raise exception 'Platform Super Admin accounts are outside tenant user management' using errcode = '42501';
  end if;

  select membership.id into membership_id_value from public.memberships membership where membership.company_id = operation_row.company_id and membership.user_id = p_user_id for update;
  perform set_config('app.membership_role_workflow', 'authorized', true);
  if membership_id_value is null then
    insert into public.memberships(company_id,user_id,role,status,created_at)
    values(operation_row.company_id,p_user_id,case operation_row.requested_role_code when 'company_administrator' then 'admin' when 'manager' then 'manager' else 'employee' end,'pending',now()) returning id into membership_id_value;
    membership_created := true;
  else
    update public.memberships set role = case operation_row.requested_role_code when 'company_administrator' then 'admin' when 'manager' then 'manager' else 'employee' end, status = 'pending', suspended_at = null, revoked_at = null where id = membership_id_value;
  end if;
  perform set_config('app.membership_role_workflow', '', true);
  update public.user_access_operations set target_membership_id = membership_id_value, target_user_id = p_user_id, status = 'invite_pending', updated_at = now(), after_state = jsonb_build_object('membership_id',membership_id_value,'user_id',p_user_id,'role_code',operation_row.requested_role_code,'status','pending') where id = p_operation_id returning * into operation_row;

  perform private.rbac_apply_user_access(membership_id_value, operation_row.requested_role_code, operation_row.requested_permissions, operation_row.requested_scopes, operation_row.created_by);
  perform set_config('app.user_access_profile_workflow', 'authorized', true);
  update public.profiles set first_name = coalesce(operation_row.first_name, first_name), last_name = coalesce(operation_row.last_name, last_name), updated_at = now() where id = p_user_id;
  perform set_config('app.user_access_profile_workflow', '', true);
  perform set_config('app.user_access_invitation_workflow', 'authorized', true);
  insert into public.company_invitations(company_id,email,role_code,invited_by,token_hash,status,expires_at,user_access_operation_id,first_name,last_name)
  values(operation_row.company_id,lower(operation_row.email),operation_row.requested_role_code,operation_row.created_by,encode(extensions.digest(encode(extensions.gen_random_bytes(32),'hex'),'sha256'),'hex'),'pending',now() + interval '7 days',p_operation_id,operation_row.first_name,operation_row.last_name)
  on conflict (company_id, lower(email)) where status = 'pending' do update set updated_at = now(), user_access_operation_id = excluded.user_access_operation_id, role_code = excluded.role_code, first_name = excluded.first_name, last_name = excluded.last_name;
  access := private.rbac_member_access_json(membership_id_value);
  perform set_config('app.user_access_invitation_workflow', '', true);
  if membership_created then
    perform private.rbac_write_user_access_audit(operation_row.company_id, operation_row.created_by, 'USER_CREATED', 'membership', membership_id_value, '{}'::jsonb, jsonb_build_object('membership_id',membership_id_value,'user_id',p_user_id,'role_code',operation_row.requested_role_code,'status','pending'), 'Tenant membership created after server-confirmed user seat billing');
  end if;
  perform private.rbac_write_user_access_audit(operation_row.company_id, operation_row.created_by, 'USER_INVITED', 'membership', membership_id_value, operation_row.before_state, jsonb_build_object('membership_id',membership_id_value,'user_id',p_user_id,'role_code',operation_row.requested_role_code,'status','pending','access',access), 'User seat billed and invitation created');
  return jsonb_build_object('operation_id',p_operation_id,'membership_id',membership_id_value,'user_id',p_user_id,'status','invite_pending','access',access);
exception when others then
  perform set_config('app.membership_role_workflow', '', true);
  perform set_config('app.user_access_profile_workflow', '', true);
  perform set_config('app.user_access_invitation_workflow', '', true);
  raise;
end;
$$;


--
-- Name: rbac_finalize_user_access_removal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_finalize_user_access_removal(p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  operation_row public.user_access_operations;
  invite_operation public.user_access_operations;
  invite_operation_id uuid;
  previous_access jsonb;
begin
  if not private.operix_server_request() then raise exception 'Server removal workflow required' using errcode = '42501'; end if;
  select * into operation_row from public.user_access_operations where id = p_operation_id for update;
  if operation_row.id is null or operation_row.operation_type <> 'remove' then raise exception 'Removal operation was not found' using errcode = '22023'; end if;
  if operation_row.status = 'completed' then return to_jsonb(operation_row); end if;
  if operation_row.status <> 'billing_succeeded' then raise exception 'Billing must succeed before access is removed' using errcode = '40201'; end if;
  if operation_row.target_membership_id is null then
    invite_operation_id := nullif(operation_row.before_state ->> 'invite_operation_id', '')::uuid;
    select * into invite_operation
    from public.user_access_operations pending_invite
    where pending_invite.id = invite_operation_id
      and pending_invite.company_id = operation_row.company_id
      and pending_invite.operation_type = 'invite'
      and pending_invite.target_membership_id is null
      and pending_invite.status in ('pending_billing','billing_succeeded','invite_pending','failed')
    for update;
    if invite_operation.id is null then raise exception 'The pending invitation was not found' using errcode = '22023'; end if;
    previous_access := operation_row.before_state;
    update public.company_invitations set status = 'revoked', updated_at = now() where user_access_operation_id = invite_operation.id and status = 'pending';
    update public.user_access_operations set status = 'canceled', failure_code = 'removed', failure_message = 'The pending invitation was removed by a company administrator.', updated_at = now(), completed_at = now(), after_state = jsonb_build_object('status','canceled','removed_by_operation_id',operation_row.id) where id = invite_operation.id;
  else
    select private.rbac_member_access_json(membership.id) into previous_access from public.memberships membership where membership.id = operation_row.target_membership_id;
    perform set_config('app.membership_role_workflow', 'authorized', true);
    update public.memberships set status = 'revoked', revoked_at = now(), suspended_at = null where id = operation_row.target_membership_id;
    perform set_config('app.membership_role_workflow', '', true);
    delete from public.membership_permission_overrides where membership_id = operation_row.target_membership_id;
    delete from public.membership_data_scopes where membership_id = operation_row.target_membership_id;
    delete from public.membership_role_assignments where membership_id = operation_row.target_membership_id;
    update public.company_invitations set status = 'revoked', updated_at = now() where user_access_operation_id = operation_row.id and status = 'pending';
  end if;
  update public.user_access_operations set status = 'completed', completed_at = now(), updated_at = now(), before_state = coalesce(operation_row.before_state, previous_access), after_state = jsonb_build_object('status','revoked','membership_id',operation_row.target_membership_id) where id = operation_row.id returning * into operation_row;
  perform private.rbac_write_user_access_audit(operation_row.company_id, operation_row.created_by, 'USER_REMOVED', case when operation_row.target_membership_id is null then 'user_access_operation' else 'membership' end, coalesce(operation_row.target_membership_id, operation_row.id), previous_access, jsonb_build_object('status','revoked','membership_id',operation_row.target_membership_id,'invite_operation_id',invite_operation_id), case when operation_row.target_membership_id is null then 'Pending invitation removed and reserved seat released without creating a tenant membership' else 'Tenant membership removed without deleting historical business records' end);
  return to_jsonb(operation_row);
exception when others then
  perform set_config('app.membership_role_workflow', '', true);
  raise;
end;
$$;


--
-- Name: rbac_get_user_access_operation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_get_user_access_operation(p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  operation_row public.user_access_operations;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  select * into operation_row
  from public.user_access_operations operation
  where operation.id = p_operation_id
    and (
      private.rbac_is_user_access_admin(operation.company_id)
      or operation.target_user_id = (select auth.uid())
    );
  if operation_row.id is null then
    raise exception 'The user access operation was not found' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'operation_id', operation_row.id,
    'company_id', operation_row.company_id,
    'operation_type', operation_row.operation_type,
    'target_membership_id', operation_row.target_membership_id,
    'target_user_id', operation_row.target_user_id,
    'email', operation_row.email,
    'status', operation_row.status,
    'billing_required', operation_row.billing_required,
    'billing_interval', operation_row.billing_interval,
    'billing_preview', coalesce(operation_row.billing_preview, '{}'::jsonb) - 'invoice_id',
    'expires_at', operation_row.expires_at
  );
end;
$$;


--
-- Name: rbac_get_users_access_billing_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_get_users_access_billing_summary(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  root_company_id uuid;
  account_row record;
  usage_row public.subscription_usage;
  plan_value text;
  interval_value text;
  monthly_base numeric;
  annual_base numeric;
  monthly_total numeric;
  annual_total numeric;
begin
  if (select auth.uid()) is null and not private.operix_server_request() then raise exception 'Authentication required' using errcode = '42501'; end if;
  if not private.operix_server_request() and not private.rbac_is_user_access_admin(p_company_id) then
    raise exception 'Users & Access is restricted to authorized company administrators' using errcode = '42501';
  end if;
  root_company_id := private.invoice_billing_root_company_id(p_company_id);
  usage_row := private.refresh_invoice_subscription_usage(root_company_id);
  select * into account_row from public.subscription_accounts account
  where account.company_id = root_company_id and account.product in ('invoice', 'suite')
  order by case when account.product = 'suite' then 0 else 1 end, account.created_at limit 1;
  plan_value := case when account_row.product is null then 'invoice' else account_row.product end;
  interval_value := coalesce(account_row.billing_interval, 'monthly');
  monthly_base := case plan_value when 'suite' then 4.99 else 2.99 end;
  annual_base := case plan_value when 'suite' then 49.99 else 29.99 end;
  monthly_total := monthly_base + (greatest(usage_row.total_tenants - 1, 0) * 1.99) + (greatest(usage_row.total_users - 1, 0) * 0.99);
  annual_total := annual_base + (greatest(usage_row.total_tenants - 1, 0) * 19.99) + (greatest(usage_row.total_users - 1, 0) * 9.99);
  return jsonb_build_object(
    'company_id', p_company_id,
    'billing_account_company_id', root_company_id,
    'plan', plan_value,
    'status', coalesce(account_row.status, 'trialing'),
    'billing_interval', interval_value,
    'stripe_subscription_id', case when private.rbac_is_platform_admin() then account_row.stripe_subscription_id else null end,
    'trial_started_at', account_row.trial_started_at,
    'trial_ends_at', account_row.trial_ends_at,
    'current_period_end', account_row.current_period_end,
    'cancel_at_period_end', coalesce(account_row.cancel_at_period_end, false),
    'total_tenants', usage_row.total_tenants,
    'included_tenants', usage_row.included_tenants,
    'billable_tenants', usage_row.billable_tenants,
    'total_users', usage_row.total_users,
    'included_users', usage_row.included_users,
    'billable_users', usage_row.billable_users,
    'base_monthly', to_char(monthly_base, 'FM999999990.00'),
    'additional_tenant_monthly', '1.99',
    'additional_user_monthly', '0.99',
    'base_annual', to_char(annual_base, 'FM999999990.00'),
    'additional_tenant_annual', '19.99',
    'additional_user_annual', '9.99',
    'estimated_monthly_total', to_char(monthly_total, 'FM999999990.00'),
    'estimated_annual_total', to_char(annual_total, 'FM999999990.00'),
    'usage_updated_at', usage_row.updated_at,
    'trial_days_remaining', case when account_row.trial_ends_at is null then 0 else greatest(0, ceil(extract(epoch from (account_row.trial_ends_at - now())) / 86400))::integer end,
    'billing_management_allowed', true
  );
end;
$$;


--
-- Name: rbac_get_workspace_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_get_workspace_access(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  role_code_value text;
  permission_values jsonb;
  scope_values jsonb;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if not public.can_access_company(p_company_id) then
    raise exception 'Company access denied' using errcode = '42501';
  end if;

  role_code_value := case when public.control_is_platform_admin() then 'super_administrator' else private.rbac_role_code(p_company_id) end;
  select coalesce(jsonb_agg(permission.code order by permission.code), '[]'::jsonb)
    into permission_values
  from public.app_permissions permission
  where permission.code in (
    'invoice.view','invoice.view_all','invoice.create','invoice.edit','invoice.apply_discount','invoice.change_dates','invoice.issue','invoice.delete_draft',
    'invoice.void','invoice.credit','invoice.debit','offer.create','offer.manage','proforma.create',
    'proforma.manage','order.create','order.manage','delivery_note.create','delivery_note.manage','contracts.manage',
    'payment.view','payment.create','payment.refund','expense.view_own','expense.view_all','expense.create',
    'expense.edit','expense.approve','expense.manage','customer.view','customer.view_all','customer.create',
    'customer.edit','customer.delete','product.view','product.create','product.edit','product.change_price',
    'product.delete','inventory.view','inventory.adjust','reports.sales','reports.operational','reports.profit',
    'reports.tax','sales_book.view','sales_book.manage','accounting_period.view','accounting_period.close',
    'accounting_period.reopen','users.view','users.manage','permissions.manage','audit.view','financial.export',
    'settings.company','settings.tax','settings.invoice','settings.bank','settings.integrations','settings.api',
    'settings.security','subscription.manage'
  )
    and private.has_company_permission(p_company_id, permission.code);

  select coalesce(jsonb_object_agg(resource, private.rbac_scope_for(p_company_id, resource)), '{}'::jsonb)
    into scope_values
  from (values
    ('invoice'),('offer'),('proforma'),('order'),('delivery_note'),('customer'),
    ('expense'),('payment'),('product'),('inventory')
  ) as resources(resource);

  return jsonb_build_object(
    'company_id', p_company_id,
    'role_code', role_code_value,
    'platform_admin', public.control_is_platform_admin(),
    'permissions', permission_values,
    'scopes', scope_values
  );
end;
$$;


--
-- Name: rbac_list_company_members(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_list_company_members(p_company_id uuid) RETURNS TABLE(membership_id uuid, user_id uuid, email text, first_name text, last_name text, status text, role_code text, role_name text, is_company_owner boolean, access jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if not private.rbac_is_tenant_admin(p_company_id) then
    raise exception 'Only a tenant Admin can manage permissions' using errcode = '42501';
  end if;
  return query
  select membership.id,
    membership.user_id,
    coalesce(auth_user.email, profile.email)::text,
    profile.first_name::text,
    profile.last_name::text,
    coalesce(membership.status, 'active')::text,
    private.rbac_member_role_code(membership.id)::text,
    case private.rbac_member_role_code(membership.id)
      when 'company_administrator' then 'Admin'
      when 'manager' then 'Manager'
      else 'Employee'
    end::text,
    company.owner_id = membership.user_id,
    private.rbac_member_access_json(membership.id)
  from public.memberships membership
  join public.companies company on company.id = membership.company_id
  left join auth.users auth_user on auth_user.id = membership.user_id
  left join public.profiles profile on profile.id = membership.user_id
  where membership.company_id = p_company_id
    and coalesce(membership.status, 'active') <> 'revoked'
    and not exists (
      select 1 from public.control_platform_admins platform_admin
      where platform_admin.user_id = membership.user_id
        and platform_admin.revoked_at is null
    )
  order by lower(coalesce(auth_user.email, profile.email, '')), membership.id;
end;
$$;


--
-- Name: rbac_list_permission_catalog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_list_permission_catalog() RETURNS TABLE(code text, name text, category text, description text, is_sensitive boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select permission.code, permission.name, permission.category,
    permission.description, permission.is_sensitive
  from public.app_permissions permission
  where permission.code in (
    'invoice.view','invoice.view_all','invoice.create','invoice.edit','invoice.apply_discount','invoice.change_dates','invoice.issue','invoice.delete_draft',
    'invoice.void','invoice.credit','invoice.debit','offer.create','offer.manage','proforma.create',
    'proforma.manage','order.create','order.manage','delivery_note.create','delivery_note.manage','contracts.manage',
    'payment.view','payment.create','payment.refund','expense.view_own','expense.view_all','expense.create',
    'expense.edit','expense.approve','expense.manage','customer.view','customer.view_all','customer.create',
    'customer.edit','customer.delete','product.view','product.create','product.edit','product.change_price',
    'product.delete','inventory.view','inventory.adjust','reports.sales','reports.operational','reports.profit',
    'reports.tax','sales_book.view','sales_book.manage','accounting_period.view','accounting_period.close',
    'accounting_period.reopen','users.view','users.manage','permissions.manage','audit.view','financial.export',
    'settings.company','settings.tax','settings.invoice','settings.bank','settings.integrations','settings.api',
    'settings.security','subscription.manage'
  )
  order by permission.category, permission.code;
$$;


--
-- Name: rbac_list_users_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_list_users_access(p_company_id uuid) RETURNS TABLE(membership_id uuid, user_id uuid, email text, first_name text, last_name text, status text, role_code text, role_name text, data_scopes jsonb, last_active_at timestamp with time zone, date_added timestamp with time zone, billing_status text, is_company_owner boolean, operation_id uuid, access jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is null and not private.operix_server_request() then raise exception 'Authentication required' using errcode = '42501'; end if;
  if not private.operix_server_request() and not private.rbac_is_user_access_admin(p_company_id) then
    raise exception 'Users & Access is restricted to authorized company administrators' using errcode = '42501';
  end if;
  return query
  select membership.id,
    membership.user_id,
    coalesce(auth_user.email, profile.email)::text,
    profile.first_name::text,
    profile.last_name::text,
    case lower(coalesce(membership.status, 'active')) when 'suspended' then 'suspended' when 'pending' then 'invited' else 'active' end::text,
    private.rbac_member_role_code(membership.id)::text,
    case private.rbac_member_role_code(membership.id) when 'company_administrator' then 'Admin' when 'manager' then 'Manager' else 'Employee' end::text,
    coalesce((private.rbac_member_access_json(membership.id) -> 'scopes'), '{}'::jsonb),
    coalesce(membership.last_active_at, auth_user.last_sign_in_at),
    membership.created_at,
    case
      when lower(coalesce(membership.status, 'active')) = 'suspended' then 'seat_active'
      when account.status in ('past_due','unpaid','incomplete') then 'pending_payment'
      when account.status = 'trialing' then 'trial'
      else 'active'
    end::text,
    company.owner_id = membership.user_id,
    linked_operation.id,
    private.rbac_member_access_json(membership.id)
  from public.memberships membership
  join public.companies company on company.id = membership.company_id
  left join auth.users auth_user on auth_user.id = membership.user_id
  left join public.profiles profile on profile.id = membership.user_id
  left join lateral (
    select subscription.status
    from public.subscription_accounts subscription
    where subscription.company_id = private.invoice_billing_root_company_id(p_company_id)
      and subscription.product in ('invoice', 'suite')
    order by case when subscription.product = 'suite' then 0 else 1 end, subscription.created_at
    limit 1
  ) account on true
  left join lateral (
    select operation.id
    from public.user_access_operations operation
    where operation.target_membership_id = membership.id
    order by operation.created_at desc
    limit 1
  ) linked_operation on true
  where membership.company_id = p_company_id
    and lower(coalesce(membership.status, 'active')) <> 'revoked'
    and not exists (
      select 1 from public.control_platform_admins platform_admin
      where platform_admin.user_id = membership.user_id and platform_admin.revoked_at is null
    )
  union all
  select operation.target_membership_id,
    operation.target_user_id,
    operation.email,
    operation.first_name,
    operation.last_name,
    case when operation.status in ('pending_billing', 'failed') then 'pending_payment' else 'invited' end::text,
    coalesce(operation.requested_role_code, 'employee'),
    case coalesce(operation.requested_role_code, 'employee') when 'company_administrator' then 'Admin' when 'manager' then 'Manager' else 'Employee' end::text,
    coalesce(operation.requested_scopes, '{}'::jsonb),
    null::timestamptz,
    operation.created_at,
    case when operation.status in ('pending_billing', 'failed') then 'pending_payment' when account.status = 'trialing' then 'trial' else 'active' end::text,
    false,
    operation.id,
    jsonb_build_object(
      'role_code', coalesce(operation.requested_role_code, 'employee'),
      'permissions', coalesce((select jsonb_agg(permission.key order by permission.key) from jsonb_each_text(operation.requested_permissions) permission where permission.value = 'true'), '[]'::jsonb),
      'scopes', coalesce(operation.requested_scopes, '{}'::jsonb),
      'overrides', coalesce(operation.requested_permissions, '{}'::jsonb)
    )
  from public.user_access_operations operation
  left join lateral (
    select subscription.status
    from public.subscription_accounts subscription
    where subscription.company_id = operation.root_company_id
      and subscription.product in ('invoice', 'suite')
    order by case when subscription.product = 'suite' then 0 else 1 end, subscription.created_at
    limit 1
  ) account on true
  where operation.company_id = p_company_id
    and operation.operation_type = 'invite'
    and operation.status in ('pending_billing','billing_succeeded','invite_pending','failed')
    and (
      operation.expires_at > now()
      or (operation.status = 'failed' and operation.updated_at > now() - interval '20 minutes')
    )
    and operation.target_membership_id is null
  order by 11 desc nulls last, 3;
end;
$$;


--
-- Name: rbac_mark_user_access_billing_failed(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_mark_user_access_billing_failed(p_operation_id uuid, p_failure_code text, p_failure_message text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare operation_row public.user_access_operations;
begin
  if not private.operix_server_request() then raise exception 'Server billing workflow required' using errcode = '42501'; end if;
  select * into operation_row from public.user_access_operations where id = p_operation_id for update;
  if operation_row.id is null then raise exception 'User access operation was not found' using errcode = '22023'; end if;
  if operation_row.status in ('completed','invite_pending','billing_succeeded') then return to_jsonb(operation_row); end if;
  if operation_row.status <> 'pending_billing' then raise exception 'The user access operation cannot be failed in its current state' using errcode = '40901'; end if;
  update public.user_access_operations set status = 'failed', failure_code = left(p_failure_code,100), failure_message = left(p_failure_message,1000), updated_at = now(), expires_at = now() + interval '20 minutes' where id = p_operation_id returning * into operation_row;
  perform private.rbac_write_user_access_audit(operation_row.company_id, operation_row.created_by, 'USER_SEAT_BILLING_FAILED', 'user_access_operation', operation_row.id, operation_row.before_state, jsonb_build_object('status','failed','failure_code',operation_row.failure_code), 'Stripe did not confirm the user seat billing operation; access remains inactive and the operation can be retried safely');
  return to_jsonb(operation_row);
end;
$$;


--
-- Name: rbac_mark_user_access_billing_succeeded(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_mark_user_access_billing_succeeded(p_operation_id uuid, p_billing_interval text, p_stripe_subscription_id text DEFAULT NULL::text, p_stripe_invoice_id text DEFAULT NULL::text, p_billing_preview jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  operation_row public.user_access_operations;
begin
  if not private.operix_server_request() then raise exception 'Server billing workflow required' using errcode = '42501'; end if;
  select * into operation_row from public.user_access_operations where id = p_operation_id for update;
  if operation_row.id is null then raise exception 'User access operation was not found' using errcode = '22023'; end if;
  if operation_row.status in ('completed','invite_pending','billing_succeeded') then return to_jsonb(operation_row); end if;
  if operation_row.status <> 'pending_billing' then raise exception 'The user access operation cannot be billed in its current state' using errcode = '40901'; end if;
  update public.user_access_operations set status = 'billing_succeeded', billing_interval = p_billing_interval, stripe_subscription_id = p_stripe_subscription_id, stripe_invoice_id = p_stripe_invoice_id, billing_preview = coalesce(p_billing_preview,'{}'::jsonb), updated_at = now(), expires_at = now() + interval '7 days' where id = p_operation_id returning * into operation_row;
  perform private.rbac_write_user_access_audit(operation_row.company_id, operation_row.created_by, case when operation_row.operation_type = 'remove' then 'USER_SEAT_REMOVED' else 'USER_SEAT_BILLED' end, 'user_access_operation', operation_row.id, operation_row.before_state, jsonb_build_object('billing_interval',p_billing_interval,'billing_preview',coalesce(p_billing_preview,'{}'::jsonb) - 'invoice_id'), 'Stripe confirmed the user seat billing operation');
  return to_jsonb(operation_row);
end;
$$;


--
-- Name: rbac_release_user_access_billing_lock(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_release_user_access_billing_lock(p_root_company_id uuid, p_operation_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.operix_server_request() then raise exception 'Server billing workflow required' using errcode = '42501'; end if;
  delete from public.user_access_billing_locks where root_company_id = p_root_company_id and operation_id = p_operation_id;
  return true;
end;
$$;


--
-- Name: rbac_set_user_access_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_set_user_access_status(p_membership_id uuid, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  target_company_id uuid;
  target_user_id uuid;
  company_owner_id uuid;
  previous_status text;
  next_status text := lower(trim(coalesce(p_status, '')));
begin
  if actor_id is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if next_status not in ('suspended','active') then raise exception 'Only suspend and reactivate are supported here' using errcode = '22023'; end if;
  select membership.company_id, membership.user_id, membership.status, company.owner_id into target_company_id, target_user_id, previous_status, company_owner_id
  from public.memberships membership join public.companies company on company.id = membership.company_id
  where membership.id = p_membership_id for update;
  if target_company_id is null then raise exception 'Membership was not found' using errcode = '22023'; end if;
  if not private.rbac_is_user_access_admin(target_company_id) then raise exception 'You do not have permission to manage Users & Access' using errcode = '42501'; end if;
  if target_user_id = company_owner_id then raise exception 'The company owner cannot be suspended or reactivated from team management' using errcode = '42501'; end if;
  if exists (select 1 from public.control_platform_admins platform_admin where platform_admin.user_id = target_user_id and platform_admin.revoked_at is null) then raise exception 'Platform Super Admin accounts are outside tenant user management' using errcode = '42501'; end if;
  if not private.rbac_is_platform_admin()
     and private.rbac_role_code(target_company_id) <> 'company_administrator'
     and private.rbac_member_role_code(p_membership_id) <> 'employee' then
    raise exception 'Only a tenant Admin can manage Admin or Manager accounts' using errcode = '42501';
  end if;
  if next_status = 'suspended' and target_user_id = actor_id and private.rbac_member_role_code(p_membership_id) = 'company_administrator' and private.rbac_active_admin_count(target_company_id, p_membership_id) < 1 then
    raise exception 'This company must have at least one active Admin. Assign another Admin before changing your account.' using errcode = '42501';
  end if;
  perform set_config('app.membership_role_workflow', 'authorized', true);
  update public.memberships set status = next_status, suspended_at = case when next_status = 'suspended' then now() else null end, last_active_at = case when next_status = 'active' then now() else last_active_at end where id = p_membership_id;
  perform set_config('app.membership_role_workflow', '', true);
  perform private.rbac_write_user_access_audit(target_company_id, actor_id, case when next_status = 'suspended' then 'USER_SUSPENDED' else 'USER_REACTIVATED' end, 'membership', p_membership_id, jsonb_build_object('status',previous_status), jsonb_build_object('status',next_status), 'Tenant Admin changed user access status');
  return jsonb_build_object('membership_id',p_membership_id,'status',next_status,'billable_seat_retained',next_status = 'suspended');
exception when others then
  perform set_config('app.membership_role_workflow', '', true);
  raise;
end;
$$;


--
-- Name: rbac_update_member_access(uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_update_member_access(p_membership_id uuid, p_role_code text, p_permissions jsonb DEFAULT '{}'::jsonb, p_scopes jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.rbac_update_user_access(p_membership_id, p_role_code, p_permissions, p_scopes, null, null);
$$;


--
-- Name: rbac_update_user_access(uuid, text, jsonb, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rbac_update_user_access(p_membership_id uuid, p_role_code text, p_permissions jsonb DEFAULT '{}'::jsonb, p_scopes jsonb DEFAULT '{}'::jsonb, p_first_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  target_company_id uuid;
  target_user_id uuid;
  company_owner_id uuid;
  previous_state jsonb;
  next_access jsonb;
  role_value text := case lower(trim(coalesce(p_role_code, '')))
    when 'admin' then 'company_administrator'
    else lower(trim(coalesce(p_role_code, '')))
  end;
begin
  if actor_id is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  select membership.company_id, membership.user_id, company.owner_id into target_company_id, target_user_id, company_owner_id
  from public.memberships membership join public.companies company on company.id = membership.company_id
  where membership.id = p_membership_id for update;
  if target_company_id is null then raise exception 'Membership was not found' using errcode = '22023'; end if;
  if not private.rbac_is_user_access_admin(target_company_id) then raise exception 'You do not have permission to manage Users & Access' using errcode = '42501'; end if;
  if target_user_id = actor_id then raise exception 'You cannot change your own role or permissions' using errcode = '42501'; end if;
  if target_user_id = company_owner_id then raise exception 'The company owner cannot be edited from team management' using errcode = '42501'; end if;
  if exists (select 1 from public.control_platform_admins platform_admin where platform_admin.user_id = target_user_id and platform_admin.revoked_at is null) then raise exception 'Platform Super Admin accounts are outside tenant user management' using errcode = '42501'; end if;
  if not private.rbac_is_platform_admin()
     and private.rbac_role_code(target_company_id) <> 'company_administrator'
     and (
       private.rbac_member_role_code(p_membership_id) <> 'employee'
       or role_value <> 'employee'
     ) then
    raise exception 'Only a tenant Admin can manage Admin or Manager accounts' using errcode = '42501';
  end if;
  perform private.rbac_validate_user_access_payload(role_value, p_permissions, p_scopes);
  if not private.rbac_is_platform_admin()
     and private.rbac_role_code(target_company_id) <> 'company_administrator'
     and exists (
       select 1 from jsonb_each(coalesce(p_permissions, '{}'::jsonb)) permission
       where (permission.value #>> '{}')::boolean
         and not private.has_company_permission(target_company_id, permission.key)
     ) then
    raise exception 'You cannot grant a permission you do not hold' using errcode = '42501';
  end if;
  if private.rbac_member_role_code(p_membership_id) = 'company_administrator' and role_value <> 'company_administrator' and private.rbac_active_admin_count(target_company_id, p_membership_id) < 1 then
    raise exception 'This company must have at least one active Admin. Assign another Admin before changing your account.' using errcode = '42501';
  end if;
  previous_state := jsonb_build_object('role_code',private.rbac_member_role_code(p_membership_id),'access',private.rbac_member_access_json(p_membership_id));
  next_access := private.rbac_apply_user_access(p_membership_id, role_value, p_permissions, p_scopes, actor_id);
  perform set_config('app.user_access_profile_workflow', 'authorized', true);
  update public.profiles set first_name = coalesce(nullif(trim(p_first_name), ''), first_name), last_name = coalesce(nullif(trim(p_last_name), ''), last_name), updated_at = now() where id = target_user_id;
  perform set_config('app.user_access_profile_workflow', '', true);
  perform private.rbac_write_user_access_audit(target_company_id, actor_id, case when previous_state ->> 'role_code' is distinct from role_value then 'USER_ROLE_CHANGED' else 'USER_PERMISSIONS_CHANGED' end, 'membership', p_membership_id, previous_state, jsonb_build_object('role_code',role_value,'access',next_access), 'Tenant Admin updated user access');
  return jsonb_build_object('membership_id',p_membership_id,'role_code',role_value,'access',next_access);
exception when others then
  perform set_config('app.user_access_profile_workflow', '', true);
  raise;
end;
$$;


--
-- Name: record_cashier_shift_movement(uuid, uuid, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_cashier_shift_movement(p_company_id uuid, p_shift_id uuid, p_movement_type text, p_amount numeric, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare shift_row public.cashier_shifts; signed_amount numeric(20,4);
begin
  if not (select private.has_company_permission(p_company_id, 'pos.shift.cash_movement')) then
    raise exception 'Insufficient permission to record a cash movement' using errcode = '42501';
  end if;
  select * into shift_row from public.cashier_shifts where id=p_shift_id and company_id=p_company_id for update;
  if not found or shift_row.status not in ('open','active','reopened') then raise exception 'An active cashier shift is required' using errcode='55000'; end if;
  if nullif(trim(p_reason),'') is null then raise exception 'A reason is required for a cash movement' using errcode='23514'; end if;
  if coalesce(p_amount,0) <= 0 then raise exception 'Cash movement amount must be positive' using errcode='23514'; end if;
  if p_movement_type not in ('cash_in','cash_out','paid_out','safe_drop','cash_transfer') then raise exception 'Unsupported cash movement type' using errcode='23514'; end if;
  signed_amount := case when p_movement_type in ('cash_out','paid_out','safe_drop','cash_transfer') then -round(p_amount,4) else round(p_amount,4) end;
  insert into public.cashier_shift_movements (company_id,cashier_shift_id,terminal_id,movement_type,amount,reason,created_by)
  values (p_company_id,shift_row.id,shift_row.terminal_id,p_movement_type,signed_amount,trim(p_reason),(select auth.uid()));
  update public.cashier_shifts set expected_cash=round(expected_cash+signed_amount,4),updated_at=clock_timestamp() where id=shift_row.id returning * into shift_row;
  insert into public.cashier_shift_events (company_id,cashier_shift_id,event_type,payload,actor_id) values (p_company_id,shift_row.id,'cash_movement',jsonb_build_object('type',p_movement_type,'amount',signed_amount,'reason',trim(p_reason)),(select auth.uid()));
  return jsonb_build_object('shift_id',shift_row.id,'expected_cash',shift_row.expected_cash);
end $$;


--
-- Name: record_commercial_document_event(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_commercial_document_event(p_document_id uuid, p_event_type text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS public.commercial_document_events
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  invoice_row public.invoices;
begin
  select * into invoice_row from public.invoices where id = p_document_id;
  if not found then
    raise exception 'Commercial document not found' using errcode = 'P0002';
  end if;
  if not (select private.has_company_permission(invoice_row.company_id, 'sales_invoice.edit')) then
    raise exception 'Insufficient permission to record a document event' using errcode = '42501';
  end if;
  return private.insert_commercial_document_event(
    invoice_row.company_id, invoice_row.id, trim(p_event_type),
    null, invoice_row.commercial_status, coalesce(p_payload, '{}'::jsonb), clock_timestamp(), (select auth.uid())
  );
end
$$;


--
-- Name: record_customer_payment(uuid, uuid, date, numeric, text, uuid, text, text, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_customer_payment(p_company_id uuid, p_customer_id uuid, p_payment_date date, p_amount numeric, p_payment_method text, p_settlement_account_id uuid, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_branch_id uuid DEFAULT NULL::uuid, p_currency text DEFAULT 'EUR'::text, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payment_row public.payments;
  client_row public.clients;
  settlement_account public.chart_of_accounts;
  receivable_account_id uuid;
  receivable_account public.chart_of_accounts;
  journal_row public.journal_entries;
  payment_number text;
begin
  if p_amount is null or round(p_amount, 4) <= 0 then
    raise exception 'Payment amount must be greater than zero' using errcode = '23514';
  end if;
  if not (select private.has_company_permission(p_company_id, 'customer_payment.record'))
    or not (select private.has_company_permission(p_company_id, 'journal.create'))
    or not (select private.has_company_permission(p_company_id, 'journal.post')) then
    raise exception 'Recording a customer payment requires payment and journal posting permissions' using errcode = '42501';
  end if;

  if p_idempotency_key is not null then
    select * into payment_row
    from public.payments
    where company_id = p_company_id and idempotency_key = p_idempotency_key;
    if found then
      return payment_row;
    end if;
  end if;

  select * into client_row from public.clients
  where id = p_customer_id and company_id = p_company_id;
  if not found then
    raise exception 'Customer is invalid for this company' using errcode = '23514';
  end if;

  select * into settlement_account from public.chart_of_accounts
  where id = p_settlement_account_id
    and company_id = p_company_id
    and active
    and posting_allowed;
  if not found then
    raise exception 'A valid active settlement account is required' using errcode = '23514';
  end if;

  receivable_account_id := client_row.default_receivable_account_id;
  if receivable_account_id is null then
    select line.account_id
    into receivable_account_id
    from public.posting_rule_sets rule_set
    join public.posting_rule_lines line on line.rule_set_id = rule_set.id
    where rule_set.company_id = p_company_id
      and rule_set.event_type = 'customer_payment'
      and rule_set.active
      and rule_set.effective_from <= coalesce(p_payment_date, current_date)
      and (rule_set.effective_until is null or rule_set.effective_until >= coalesce(p_payment_date, current_date))
      and line.side = 'credit'
      and line.amount_component = 'gross'
    order by rule_set.version desc, rule_set.effective_from desc, line.line_number
    limit 1;
  end if;
  select * into receivable_account from public.chart_of_accounts
  where id = receivable_account_id
    and company_id = p_company_id
    and active
    and posting_allowed;
  if not found then
    raise exception 'No valid receivable account is mapped for customer payments' using errcode = '23514';
  end if;

  payment_number := private.next_financial_document_number(
    p_company_id, p_branch_id, 'customer_payment', 'PAY-', coalesce(p_payment_date, current_date)
  );
  insert into public.payments (
    user_id, company_id, branch_id, client_id, payment_number, amount, payment_date,
    payment_method, bank_reference, notes, currency, allocation_status, idempotency_key, accounting_state,
    settlement_account_id
  )
  values (
    (select auth.uid()), p_company_id, p_branch_id, p_customer_id, payment_number, round(p_amount, 4),
    coalesce(p_payment_date, current_date), nullif(trim(p_payment_method), ''), nullif(trim(p_reference), ''),
    p_notes, upper(coalesce(p_currency, 'EUR')), 'unallocated', p_idempotency_key, 'ready_for_posting',
    p_settlement_account_id
  )
  returning * into payment_row;

  journal_row := public.create_journal_entry(
    p_company_id,
    payment_row.payment_date,
    payment_row.payment_date,
    'Customer payment ' || payment_row.payment_number,
    payment_row.payment_number,
    payment_row.currency,
    1,
    p_branch_id,
    'automatic'
  );
  update public.journal_entries
  set source_type = 'customer_payment',
      source_id = payment_row.id,
      source_key = payment_row.payment_number,
      metadata = jsonb_build_object('payment_number', payment_row.payment_number, 'customer_id', p_customer_id)
  where id = journal_row.id;
  insert into public.journal_entry_lines (
    journal_entry_id, company_id, line_number, account_id, description,
    debit, credit, transaction_currency, transaction_amount, branch_id, created_by
  )
  values
    (journal_row.id, p_company_id, 1, settlement_account.id, 'Customer payment settlement',
      payment_row.amount, 0, payment_row.currency, payment_row.amount, p_branch_id, (select auth.uid())),
    (journal_row.id, p_company_id, 2, receivable_account.id, 'Customer payment receivable allocation',
      0, payment_row.amount, payment_row.currency, payment_row.amount, p_branch_id, (select auth.uid()));
  journal_row := public.post_journal_entry(journal_row.id, 'Customer payment recorded');

  perform set_config('app.financial_workflow', 'authorized', true);
  update public.payments
  set accounting_state = 'posted',
      posted_at = clock_timestamp(),
      posting_journal_entry_id = journal_row.id
  where id = payment_row.id
  returning * into payment_row;
  perform set_config('app.financial_workflow', '', true);

  perform private.emit_domain_outbox_event(
    payment_row.company_id, payment_row.branch_id, 'customer_payment', payment_row.id,
    'customer_payment.recorded',
    jsonb_build_object('payment_number', payment_row.payment_number, 'amount', payment_row.amount, 'journal_entry_id', journal_row.id),
    'customer_payment.recorded:' || payment_row.id::text
  );
  return payment_row;
end
$$;


--
-- Name: record_customer_payment_financial(uuid, uuid, date, numeric, text, uuid, text, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_customer_payment_financial(p_company_id uuid, p_customer_id uuid, p_payment_date date, p_amount numeric, p_payment_method text, p_fund_account_id uuid, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_payer_name text DEFAULT NULL::text, p_currency text DEFAULT 'EUR'::text, p_idempotency_key uuid DEFAULT NULL::uuid, p_attachment_id uuid DEFAULT NULL::uuid) RETURNS public.payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare fund_row public.company_fund_accounts; bank_id uuid; settlement_id uuid; payment_row public.payments;
declare method text := lower(trim(coalesce(p_payment_method,'cash')));
begin
  if not private.has_company_permission(p_company_id,'customer_payment.record') then raise exception 'Insufficient permission to record customer payments' using errcode='42501'; end if;
  if p_amount is null or round(p_amount,4) <= 0 then raise exception 'Payment amount must be greater than zero' using errcode='23514'; end if;
  if method not in ('cash','bank','bank_transfer','card','online_payment','cheque','other') then raise exception 'Payment method is invalid' using errcode='23514'; end if;
  select * into fund_row from public.company_fund_accounts where id=p_fund_account_id and is_active and (company_id=p_company_id or private.can_view_fund_account(id)) for update;
  if not found then raise exception 'A valid active destination account is required' using errcode='23503'; end if;
  if upper(fund_row.currency) <> upper(coalesce(p_currency,'EUR')) then raise exception 'Payment currency must match the destination account currency' using errcode='23514'; end if;
  if fund_row.company_bank_account_id is not null then bank_id := fund_row.company_bank_account_id; end if;
  if fund_row.account_type = 'cash' then
    select id into settlement_id from public.chart_of_accounts where company_id=p_company_id and code='1010' and active and posting_allowed limit 1;
  elsif fund_row.company_bank_account_id is not null then
    select account_id into settlement_id from public.company_bank_accounts where id=fund_row.company_bank_account_id and company_id=p_company_id;
  end if;
  if settlement_id is null then select id into settlement_id from public.chart_of_accounts where company_id=p_company_id and code='1020' and active and posting_allowed limit 1; end if;
  if settlement_id is null then raise exception 'No active settlement account is configured' using errcode='23514'; end if;
  payment_row := public.record_customer_payment(p_company_id,p_customer_id,p_payment_date,p_amount,method,settlement_id,p_reference,p_notes,null,p_currency,p_idempotency_key);
  perform set_config('app.change_reason','Incoming payment financial destination recorded',true);
  perform set_config('app.financial_workflow','authorized',true);
  update public.payments set fund_account_id=fund_row.id, company_bank_account_id=bank_id, payer_name=nullif(trim(p_payer_name),''), external_reference=nullif(trim(p_reference),''), attachment_id=p_attachment_id, payment_status='posted' where id=payment_row.id returning * into payment_row;
  perform set_config('app.financial_workflow','','true');
  perform set_config('app.change_reason','',true);
  return payment_row;
end;
$$;


--
-- Name: record_customer_payment_with_bank_account(uuid, uuid, date, numeric, text, uuid, text, text, uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_customer_payment_with_bank_account(p_company_id uuid, p_customer_id uuid, p_payment_date date, p_amount numeric, p_payment_method text, p_settlement_account_id uuid, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_branch_id uuid DEFAULT NULL::uuid, p_currency text DEFAULT 'EUR'::text, p_idempotency_key uuid DEFAULT NULL::uuid, p_company_bank_account_id uuid DEFAULT NULL::uuid) RETURNS public.payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payment_row public.payments;
begin
  if p_company_bank_account_id is not null then
    if lower(coalesce(p_payment_method, 'cash')) <> 'bank'
       or not exists (
         select 1 from public.company_bank_accounts account
          where account.id = p_company_bank_account_id
            and account.is_active
            and (
              account.company_id = p_company_id
              or exists (
                select 1 from public.company_bank_account_shares share
                 where share.company_bank_account_id = account.id
                   and share.shared_company_id = p_company_id
                   and share.is_active
              )
            )
       ) then
      raise exception 'The selected bank account is not available for this payment' using errcode = '23503';
    end if;
  end if;

  payment_row := public.record_customer_payment(
    p_company_id, p_customer_id, p_payment_date, p_amount, p_payment_method,
    p_settlement_account_id, p_reference, p_notes, p_branch_id, p_currency,
    p_idempotency_key
  );

  perform set_config('app.financial_workflow', 'authorized', true);
  update public.payments
     set company_bank_account_id = p_company_bank_account_id
   where id = payment_row.id
   returning * into payment_row;
  perform set_config('app.financial_workflow', '', true);
  return payment_row;
end;
$$;


--
-- Name: customer_refunds; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_refunds (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    payment_id uuid,
    invoice_id uuid,
    refund_number text NOT NULL,
    refund_date date NOT NULL,
    amount numeric(20,4) NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    fund_account_id uuid NOT NULL,
    reference text,
    reason text NOT NULL,
    status text DEFAULT 'ready_for_posting'::text NOT NULL,
    posting_journal_entry_id uuid,
    idempotency_key uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT customer_refunds_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT customer_refunds_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT customer_refunds_status_check CHECK ((status = ANY (ARRAY['ready_for_posting'::text, 'posted'::text, 'reversed'::text])))
);


--
-- Name: record_customer_refund(uuid, uuid, uuid, uuid, date, numeric, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_customer_refund(p_company_id uuid, p_customer_id uuid, p_payment_id uuid, p_invoice_id uuid, p_refund_date date, p_amount numeric, p_fund_account_id uuid, p_reason text, p_currency text DEFAULT 'EUR'::text, p_reference text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.customer_refunds
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare payment_row public.payments; fund_row public.company_fund_accounts; refund_row public.customer_refunds; journal_row public.journal_entries; settlement_id uuid; receivable_id uuid; refund_number text;
begin
  if not private.has_company_permission(p_company_id,'customer_refund.create') then raise exception 'Insufficient permission to process customer refunds' using errcode='42501'; end if;
  if nullif(trim(p_reason),'') is null or p_amount is null or round(p_amount,4) <= 0 then raise exception 'A positive refund amount and reason are required' using errcode='23514'; end if;
  if p_idempotency_key is not null then select * into refund_row from public.customer_refunds where company_id=p_company_id and idempotency_key=p_idempotency_key for update; if found then return refund_row; end if; end if;
  select * into payment_row from public.payments where id=p_payment_id and company_id=p_company_id and client_id=p_customer_id and accounting_state='posted' and payment_status='posted' for update;
  if not found then raise exception 'The original customer payment is invalid for this refund' using errcode='23514'; end if;
  if p_invoice_id is not null and not exists(select 1 from public.invoices where id=p_invoice_id and company_id=p_company_id and client_id=p_customer_id) then raise exception 'The refund invoice is invalid for this customer' using errcode='23514'; end if;
  if round(p_amount,4) > round(payment_row.amount - coalesce((select sum(amount) from public.customer_refunds where payment_id=payment_row.id and status='posted'),0),4) then raise exception 'Refund exceeds the remaining customer payment amount' using errcode='23514'; end if;
  select * into fund_row from public.company_fund_accounts where id=p_fund_account_id and company_id=p_company_id and is_active for update;
  if not found or fund_row.currency <> upper(coalesce(p_currency,'EUR')) then raise exception 'Refund account is invalid or has a different currency' using errcode='23514'; end if;
  if fund_row.account_type='cash' then select id into settlement_id from public.chart_of_accounts where company_id=p_company_id and code='1010' and active and posting_allowed limit 1;
  elsif fund_row.company_bank_account_id is not null then select account_id into settlement_id from public.company_bank_accounts where id=fund_row.company_bank_account_id and company_id=p_company_id;
  end if;
  if settlement_id is null then select id into settlement_id from public.chart_of_accounts where company_id=p_company_id and code='1020' and active and posting_allowed limit 1; end if;
  select id into receivable_id from public.chart_of_accounts where company_id=p_company_id and code='1100' and active and posting_allowed limit 1;
  if settlement_id is null or receivable_id is null then raise exception 'Refund posting accounts are not configured' using errcode='23514'; end if;
  refund_number := private.next_financial_document_number(p_company_id,null,'customer_refund','REF-',p_refund_date);
  insert into public.customer_refunds(company_id,customer_id,payment_id,invoice_id,refund_number,refund_date,amount,currency,fund_account_id,reference,reason,idempotency_key,created_by)
  values(p_company_id,p_customer_id,p_payment_id,p_invoice_id,refund_number,coalesce(p_refund_date,current_date),round(p_amount,4),upper(coalesce(p_currency,'EUR')),fund_row.id,nullif(trim(p_reference),''),trim(p_reason),p_idempotency_key,(select auth.uid())) returning * into refund_row;
  journal_row := public.create_journal_entry(p_company_id,refund_row.refund_date,refund_row.refund_date,'Customer refund '||refund_row.refund_number,refund_row.refund_number,refund_row.currency,1,null,'automatic');
  perform set_config('app.financial_workflow','authorized',true);
  update public.journal_entries set source_type='customer_refund',source_id=refund_row.id,source_key=refund_row.refund_number where id=journal_row.id;
  perform set_config('app.financial_workflow','','true');
  insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,created_by)
  values(journal_row.id,p_company_id,1,receivable_id,'Customer refund',refund_row.amount,0,refund_row.currency,refund_row.amount,(select auth.uid())),
        (journal_row.id,p_company_id,2,settlement_id,'Refund paid from account',0,refund_row.amount,refund_row.currency,refund_row.amount,(select auth.uid()));
  journal_row := public.post_journal_entry(journal_row.id,'Customer refund recorded');
  perform set_config('app.financial_workflow','authorized',true);
  update public.customer_refunds set status='posted',posting_journal_entry_id=journal_row.id where id=refund_row.id returning * into refund_row;
  perform set_config('app.financial_workflow','','true');
  return refund_row;
end;
$$;


--
-- Name: fiscal_certificates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.fiscal_certificates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    installation_id uuid NOT NULL,
    certificate_reference text NOT NULL,
    issuer text,
    serial_number text,
    fingerprint text,
    valid_from timestamp with time zone,
    valid_until timestamp with time zone,
    status text DEFAULT 'pending'::text NOT NULL,
    secret_reference text,
    assigned_at timestamp with time zone,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_by uuid,
    CONSTRAINT fiscal_certificates_certificate_reference_check CHECK ((certificate_reference !~* '-----begin'::text)),
    CONSTRAINT fiscal_certificates_check CHECK (((valid_until IS NULL) OR (valid_from IS NULL) OR (valid_until > valid_from))),
    CONSTRAINT fiscal_certificates_secret_reference_check CHECK ((COALESCE(secret_reference, ''::text) !~* '-----begin'::text)),
    CONSTRAINT fiscal_certificates_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text, 'expired'::text, 'revoked'::text, 'invalid'::text])))
);


--
-- Name: record_fiscal_certificate_metadata(uuid, uuid, text, text, text, text, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_fiscal_certificate_metadata(p_company_id uuid, p_installation_id uuid, p_certificate_reference text, p_issuer text DEFAULT NULL::text, p_serial_number text DEFAULT NULL::text, p_fingerprint text DEFAULT NULL::text, p_valid_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_valid_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_secret_reference text DEFAULT NULL::text) RETURNS public.fiscal_certificates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  certificate_row public.fiscal_certificates;
  current_user_id uuid := (select auth.uid());
begin
  if current_user_id is null or not private.has_company_permission(p_company_id, 'pos.fiscal.configure') then
    raise exception 'Insufficient permission to configure EFS certificates' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.fiscal_installations
    where id = p_installation_id and company_id = p_company_id
  ) then
    raise exception 'Fiscal installation not found' using errcode = 'P0002';
  end if;
  if nullif(trim(p_certificate_reference), '') is null then
    raise exception 'Certificate reference is required; certificate material is not accepted' using errcode = '23514';
  end if;
  if p_valid_from is not null and p_valid_until is not null and p_valid_until <= p_valid_from then
    raise exception 'Certificate validity interval is invalid' using errcode = '23514';
  end if;

  perform set_config('app.efs_configuration_workflow', 'authorized', true);
  insert into public.fiscal_certificates (
    company_id, installation_id, certificate_reference, issuer, serial_number,
    fingerprint, valid_from, valid_until, status, secret_reference,
    assigned_at, created_by, updated_by
  )
  values (
    p_company_id, p_installation_id, trim(p_certificate_reference),
    nullif(trim(p_issuer), ''), nullif(trim(p_serial_number), ''),
    nullif(trim(p_fingerprint), ''), p_valid_from, p_valid_until,
    case when p_valid_until is not null and p_valid_until <= clock_timestamp()
      then 'expired' else 'pending' end,
    nullif(trim(p_secret_reference), ''), clock_timestamp(), current_user_id, current_user_id
  )
  on conflict (company_id, installation_id, certificate_reference) do update
  set issuer = excluded.issuer,
      serial_number = excluded.serial_number,
      fingerprint = excluded.fingerprint,
      valid_from = excluded.valid_from,
      valid_until = excluded.valid_until,
      secret_reference = excluded.secret_reference,
      updated_at = clock_timestamp(),
      updated_by = current_user_id
  returning * into certificate_row;
  perform set_config('app.efs_configuration_workflow', '', true);

  insert into public.fiscal_configuration_history (
    company_id, installation_id, certificate_id, event_type,
    new_status, changed_fields, actor_id
  )
  values (
    p_company_id, p_installation_id, certificate_row.id, 'certificate_metadata_recorded',
    certificate_row.status,
    jsonb_build_object(
      'certificate_reference', certificate_row.certificate_reference,
      'fingerprint', certificate_row.fingerprint,
      'valid_until', certificate_row.valid_until,
      'secret_reference_present', certificate_row.secret_reference is not null
    ), current_user_id
  );
  return certificate_row;
end
$$;


--
-- Name: other_income; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.other_income (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    branch_id uuid,
    income_number text NOT NULL,
    category_id uuid NOT NULL,
    income_date date NOT NULL,
    payer_source text,
    description text NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    net_amount numeric(20,4) NOT NULL,
    vat_amount numeric(20,4) DEFAULT 0 NOT NULL,
    gross_amount numeric(20,4) NOT NULL,
    tax_treatment text DEFAULT 'review_required'::text NOT NULL,
    payment_method text DEFAULT 'bank'::text NOT NULL,
    fund_account_id uuid NOT NULL,
    reference text,
    attachment_id uuid,
    notes text,
    accounting_state text DEFAULT 'ready_for_posting'::text NOT NULL,
    posting_journal_entry_id uuid,
    idempotency_key uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT other_income_accounting_state_check CHECK ((accounting_state = ANY (ARRAY['ready_for_posting'::text, 'posted'::text, 'reversed'::text, 'excluded'::text]))),
    CONSTRAINT other_income_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT other_income_gross_amount_check CHECK ((gross_amount > (0)::numeric)),
    CONSTRAINT other_income_net_amount_check CHECK ((net_amount > (0)::numeric)),
    CONSTRAINT other_income_vat_amount_check CHECK ((vat_amount >= (0)::numeric))
);


--
-- Name: record_other_income(uuid, uuid, date, text, text, text, numeric, numeric, text, text, uuid, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_other_income(p_company_id uuid, p_category_id uuid, p_income_date date, p_payer_source text, p_description text, p_currency text, p_net_amount numeric, p_vat_amount numeric, p_tax_treatment text, p_payment_method text, p_fund_account_id uuid, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_attachment_id uuid DEFAULT NULL::uuid, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.other_income
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare category_row public.other_income_categories; fund_row public.company_fund_accounts; income_row public.other_income; journal_row public.journal_entries; settlement_id uuid; revenue_id uuid; vat_id uuid; gross numeric(20,4); method text := lower(trim(coalesce(p_payment_method,'bank'))); income_number text;
begin
  if not private.has_company_permission(p_company_id,'other_income.create') then raise exception 'Insufficient permission to create other income' using errcode='42501'; end if;
  if p_idempotency_key is not null then select * into income_row from public.other_income where company_id=p_company_id and idempotency_key=p_idempotency_key for update; if found then return income_row; end if; end if;
  if p_income_date is null or p_description is null or nullif(trim(p_description),'') is null then raise exception 'Income date and description are required' using errcode='23514'; end if;
  if p_net_amount is null or round(p_net_amount,4) <= 0 or p_vat_amount is null or round(p_vat_amount,4) < 0 then raise exception 'Income amounts are invalid' using errcode='23514'; end if;
  select * into category_row from public.other_income_categories where id=p_category_id and active and (company_id is null or company_id=p_company_id);
  if not found then raise exception 'Income category is invalid for this company' using errcode='23514'; end if;
  select * into fund_row from public.company_fund_accounts where id=p_fund_account_id and company_id=p_company_id and is_active for update;
  if not found or upper(fund_row.currency) <> upper(coalesce(p_currency,'EUR')) then raise exception 'Destination account is invalid or has a different currency' using errcode='23514'; end if;
  gross := round(p_net_amount + p_vat_amount,4);
  income_number := private.next_financial_document_number(p_company_id,null,'other_income','INC-',p_income_date);
  insert into public.other_income(company_id,income_number,category_id,income_date,payer_source,description,currency,net_amount,vat_amount,gross_amount,tax_treatment,payment_method,fund_account_id,reference,attachment_id,notes,idempotency_key,created_by,updated_by)
  values(p_company_id,income_number,p_category_id,p_income_date,nullif(trim(p_payer_source),''),trim(p_description),upper(coalesce(p_currency,'EUR')),round(p_net_amount,4),round(p_vat_amount,4),gross,coalesce(nullif(trim(p_tax_treatment),''),'review_required'),method,fund_row.id,nullif(trim(p_reference),''),p_attachment_id,p_notes,p_idempotency_key,(select auth.uid()),(select auth.uid())) returning * into income_row;
  if fund_row.account_type='cash' then select id into settlement_id from public.chart_of_accounts where company_id=p_company_id and code='1010' and active and posting_allowed limit 1;
  elsif fund_row.company_bank_account_id is not null then select account_id into settlement_id from public.company_bank_accounts where id=fund_row.company_bank_account_id and company_id=p_company_id;
  end if;
  if settlement_id is null then select id into settlement_id from public.chart_of_accounts where company_id=p_company_id and code='1020' and active and posting_allowed limit 1; end if;
  select id into revenue_id from public.chart_of_accounts where company_id=p_company_id and code='4200' and active and posting_allowed limit 1;
  select id into vat_id from public.chart_of_accounts where company_id=p_company_id and code='2100' and active and posting_allowed limit 1;
  if settlement_id is null or revenue_id is null then raise exception 'Other income posting accounts are not configured' using errcode='23514'; end if;
  if income_row.vat_amount > 0 and vat_id is null then raise exception 'VAT account is not configured; mark the tax treatment for review before posting' using errcode='23514'; end if;
  journal_row := public.create_journal_entry(p_company_id,p_income_date,p_income_date,'Other income '||income_row.income_number,income_row.income_number,income_row.currency,1,null,'automatic');
  perform set_config('app.financial_workflow','authorized',true);
  update public.journal_entries set source_type='other_income',source_id=income_row.id,source_key=income_row.income_number,metadata=jsonb_build_object('category_key',category_row.category_key,'tax_treatment',income_row.tax_treatment) where id=journal_row.id;
  perform set_config('app.financial_workflow','','true');
  insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,created_by)
  values(journal_row.id,p_company_id,1,settlement_id,'Other income receipt',gross,0,income_row.currency,gross,(select auth.uid())),
        (journal_row.id,p_company_id,2,revenue_id,'Other income',0,income_row.net_amount,income_row.currency,income_row.net_amount,(select auth.uid()));
  perform set_config('app.financial_workflow','authorized',true);
  if income_row.vat_amount > 0 and vat_id is not null then
    insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,created_by)
    values(journal_row.id,p_company_id,3,vat_id,'Other income VAT review',0,income_row.vat_amount,income_row.currency,income_row.vat_amount,(select auth.uid()));
  end if;
  perform set_config('app.financial_workflow','','true');
  journal_row := public.post_journal_entry(journal_row.id,'Other income recorded');
  perform set_config('app.financial_workflow','authorized',true);
  update public.other_income set accounting_state='posted',posting_journal_entry_id=journal_row.id,updated_at=now(),updated_by=(select auth.uid()) where id=income_row.id returning * into income_row;
  perform set_config('app.financial_workflow','','true');
  return income_row;
end;
$$;


--
-- Name: payroll_exports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_exports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    payroll_run_id uuid,
    payment_batch_id uuid,
    export_type text NOT NULL,
    provider text DEFAULT 'generic'::text NOT NULL,
    schema_version text NOT NULL,
    field_mapping jsonb DEFAULT '{}'::jsonb NOT NULL,
    validation_issues jsonb DEFAULT '[]'::jsonb NOT NULL,
    file_checksum text,
    storage_path text,
    status text DEFAULT 'draft'::text NOT NULL,
    approval_state text DEFAULT 'pending'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    downloaded_at timestamp with time zone,
    submitted_at timestamp with time zone,
    CONSTRAINT payroll_exports_export_type_check CHECK ((export_type = ANY (ARRAY['bank_csv'::text, 'bank_excel'::text, 'payment_order'::text, 'statutory'::text, 'report_pdf'::text, 'report_excel'::text, 'report_csv'::text]))),
    CONSTRAINT payroll_exports_field_mapping_check CHECK ((jsonb_typeof(field_mapping) = 'object'::text)),
    CONSTRAINT payroll_exports_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'validated'::text, 'approved'::text, 'generated'::text, 'downloaded'::text, 'submitted'::text, 'rejected'::text, 'revoked'::text]))),
    CONSTRAINT payroll_exports_validation_issues_check CHECK ((jsonb_typeof(validation_issues) = 'array'::text))
);


--
-- Name: record_payroll_export(uuid, text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_payroll_export(p_payment_batch_id uuid, p_export_type text, p_schema_version text, p_field_mapping jsonb, p_file_checksum text, p_storage_path text DEFAULT NULL::text) RETURNS public.payroll_exports
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  batch public.payroll_payment_batches;
  result public.payroll_exports;
begin
  select * into batch
  from public.payroll_payment_batches
  where id=p_payment_batch_id
  for update;
  if not found then
    raise exception 'Payroll payment batch not found' using errcode='P0002';
  end if;
  if p_export_type not in ('bank_csv','bank_excel','payment_order') then
    raise exception 'Unsupported payroll bank export type' using errcode='22023';
  end if;
  if not (select private.payroll_feature_enabled(batch.company_id,'payroll_bank_exports_enabled'))
     or not (select private.has_company_permission(batch.company_id,'payroll.bank_export.create')) then
    raise exception 'Payroll bank exports are disabled or permission is missing' using errcode='42501';
  end if;
  if batch.status not in ('approved','exported','partially_paid','paid') then
    raise exception 'Payment batch must be approved before export' using errcode='55000';
  end if;
  if coalesce(trim(p_file_checksum),'')='' then
    raise exception 'File checksum is required' using errcode='23514';
  end if;

  insert into public.payroll_exports(
    company_id,payroll_run_id,payment_batch_id,export_type,provider,schema_version,
    field_mapping,file_checksum,storage_path,status,approval_state,created_by,downloaded_at
  ) values (
    batch.company_id,batch.payroll_run_id,batch.id,p_export_type,'generic',p_schema_version,
    coalesce(p_field_mapping,'{}'::jsonb),p_file_checksum,p_storage_path,'downloaded',
    batch.approval_state,(select auth.uid()),now()
  ) returning * into result;

  update public.payroll_payment_batches
  set status=case when status='approved' then 'exported' else status end
  where id=batch.id;

  perform private.record_payroll_audit(
    batch.company_id,batch.branch_id,'payroll.payment_batch.exported',
    'payroll_export',result.id,null,
    jsonb_build_object('batchId',batch.id,'exportType',p_export_type,'checksum',p_file_checksum),
    'Approved payroll payment export downloaded'
  );
  perform private.emit_domain_outbox_event(
    batch.company_id,batch.branch_id,'payroll_export',result.id,
    'payroll.payment_batch.exported',
    jsonb_build_object('batchId',batch.id,'exportType',p_export_type,'checksum',p_file_checksum),
    'payroll-export:'||result.id::text
  );
  return result;
end $$;


--
-- Name: payroll_payment_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_payment_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    payment_batch_id uuid NOT NULL,
    liability_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    employee_bank_account_id uuid,
    amount numeric(20,4) NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    external_reference text,
    failure_reason text,
    payment_journal_entry_id uuid,
    paid_at timestamp with time zone,
    CONSTRAINT payroll_payment_lines_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT payroll_payment_lines_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'submitted'::text, 'paid'::text, 'failed'::text, 'rejected'::text, 'reversed'::text])))
);


--
-- Name: record_payroll_payment(uuid, uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_payroll_payment(p_payment_line_id uuid, p_payment_journal_entry_id uuid, p_external_reference text, p_paid_at timestamp with time zone, p_reason text) RETURNS public.payroll_payment_lines
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result public.payroll_payment_lines; liability_row public.payroll_liabilities; batch_row public.payroll_payment_batches; run_row public.payroll_runs;
begin
  select * into result from public.payroll_payment_lines where id=p_payment_line_id for update;
  if not found then raise exception 'Payroll payment line not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(result.company_id,'payroll.reconcile')) then raise exception 'Insufficient permission' using errcode='42501'; end if;
  if result.status='paid' then return result; end if;
  select * into liability_row from public.payroll_liabilities where id=result.liability_id for update;
  if not exists(select 1 from public.journal_entries where id=p_payment_journal_entry_id and company_id=result.company_id and status='posted') then
    raise exception 'Posted payroll bank-payment journal not found' using errcode='P0002';
  end if;
  perform set_config('app.payroll_workflow','authorized',true);
  update public.payroll_payment_lines set status='paid',payment_journal_entry_id=p_payment_journal_entry_id,
    external_reference=p_external_reference,paid_at=coalesce(p_paid_at,now())
  where id=result.id returning * into result;
  update public.payroll_liabilities set paid_amount=least(amount,paid_amount+result.amount),
    status=case when paid_amount+result.amount>=amount then 'paid' else 'partially_paid' end
  where id=liability_row.id;
  select * into batch_row from public.payroll_payment_batches where id=result.payment_batch_id for update;
  update public.payroll_payment_batches set
    status=case
      when not exists(select 1 from public.payroll_payment_lines where payment_batch_id=batch_row.id and status<>'paid') then 'paid'
      else 'partially_paid' end,
    reconciliation_state=case
      when not exists(select 1 from public.payroll_payment_lines where payment_batch_id=batch_row.id and status<>'paid') then 'reconciled'
      else 'partial' end
  where id=batch_row.id returning * into batch_row;
  select * into run_row from public.payroll_runs where id=batch_row.payroll_run_id for update;
  update public.payroll_runs set
    status=case
      when not exists(select 1 from public.payroll_liabilities where payroll_run_id=run_row.id and status not in ('paid','reversed')) then 'paid'
      else 'partially_paid' end,
    updated_at=now(),updated_by=(select auth.uid())
  where id=run_row.id;
  insert into public.payroll_reconciliation_events(
    company_id,payroll_run_id,payment_batch_id,liability_id,event_type,previous_state,new_state,amount,reason,occurred_by
  ) values (
    result.company_id,run_row.id,batch_row.id,liability_row.id,'payment_recorded',liability_row.status,
    case when liability_row.paid_amount+result.amount>=liability_row.amount then 'paid' else 'partially_paid' end,
    result.amount,p_reason,(select auth.uid())
  );
  perform private.record_payroll_audit(result.company_id,run_row.branch_id,'payroll.payment.recorded','payroll_payment_line',result.id,null,to_jsonb(result),p_reason);
  return result;
end $$;


--
-- Name: vendor_payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vendor_payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    company_id uuid,
    vendor_id uuid,
    payment_number text NOT NULL,
    amount numeric DEFAULT 0 NOT NULL,
    payment_date date DEFAULT CURRENT_DATE,
    payment_method text DEFAULT 'bank'::text,
    bank_reference text,
    description text,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    branch_id uuid,
    currency text DEFAULT 'EUR'::text NOT NULL,
    exchange_rate numeric(20,10) DEFAULT 1 NOT NULL,
    allocation_status text DEFAULT 'legacy'::text NOT NULL,
    posting_journal_entry_id uuid,
    posted_at timestamp with time zone,
    reversed_at timestamp with time zone,
    reversal_journal_entry_id uuid,
    reversal_reason text,
    idempotency_key uuid,
    accounting_state text DEFAULT 'legacy'::text NOT NULL,
    settlement_account_id uuid,
    company_bank_account_id uuid,
    CONSTRAINT vendor_payments_accounting_state_check CHECK ((accounting_state = ANY (ARRAY['legacy'::text, 'ready_for_posting'::text, 'posted'::text, 'reversed'::text, 'opening_balance'::text, 'excluded'::text]))),
    CONSTRAINT vendor_payments_allocation_status_check CHECK ((allocation_status = ANY (ARRAY['legacy'::text, 'unallocated'::text, 'partially_allocated'::text, 'allocated'::text, 'reversed'::text]))),
    CONSTRAINT vendor_payments_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT vendor_payments_exchange_rate_check CHECK ((exchange_rate > (0)::numeric))
);


--
-- Name: record_supplier_payment(uuid, uuid, date, numeric, text, uuid, text, text, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_supplier_payment(p_company_id uuid, p_supplier_id uuid, p_payment_date date, p_amount numeric, p_payment_method text, p_settlement_account_id uuid, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_branch_id uuid DEFAULT NULL::uuid, p_currency text DEFAULT 'EUR'::text, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.vendor_payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payment_row public.vendor_payments;
  vendor_row public.vendors;
  settlement_account public.chart_of_accounts;
  payable_account public.chart_of_accounts;
  journal_row public.journal_entries;
  payment_number text;
  method text := lower(trim(coalesce(p_payment_method, 'bank')));
begin
  if p_amount is null or round(p_amount, 4) <= 0 then
    raise exception 'Supplier payment amount must be greater than zero' using errcode = '23514';
  end if;
  if method not in ('cash', 'bank', 'card') then
    raise exception 'Supplier payment method is invalid' using errcode = '23514';
  end if;
  if not (select private.has_company_permission(p_company_id, 'supplier_payment.record'))
    or not (select private.has_company_permission(p_company_id, 'journal.create'))
    or not (select private.has_company_permission(p_company_id, 'journal.post')) then
    raise exception 'Recording a supplier payment requires payment and journal permissions' using errcode = '42501';
  end if;

  if p_idempotency_key is not null then
    select * into payment_row
    from public.vendor_payments
    where company_id = p_company_id and idempotency_key = p_idempotency_key;
    if found then
      return payment_row;
    end if;
  end if;

  select * into vendor_row from public.vendors
  where id = p_supplier_id and company_id = p_company_id;
  if not found then
    raise exception 'Supplier is invalid for this company' using errcode = '23514';
  end if;

  select * into settlement_account
  from public.chart_of_accounts
  where id = p_settlement_account_id and company_id = p_company_id and active and posting_allowed;
  if not found then
    raise exception 'A valid active settlement account is required' using errcode = '23514';
  end if;

  if vendor_row.default_payable_account_id is not null then
    select * into payable_account
    from public.chart_of_accounts
    where id = vendor_row.default_payable_account_id
      and company_id = p_company_id and active and posting_allowed;
  else
    select * into payable_account
    from public.chart_of_accounts
    where company_id = p_company_id and statement_mapping = 'balance_sheet.payables'
      and active and posting_allowed
    order by code limit 1;
  end if;
  if not found then
    raise exception 'No valid payable account is mapped for supplier payments' using errcode = '23514';
  end if;

  payment_number := private.next_financial_document_number(
    p_company_id, p_branch_id, 'supplier_payment', 'VPAY-', coalesce(p_payment_date, current_date)
  );
  insert into public.vendor_payments (
    user_id, company_id, branch_id, vendor_id, payment_number, amount, payment_date,
    payment_method, bank_reference, notes, currency, allocation_status,
    idempotency_key, accounting_state, settlement_account_id
  )
  values (
    (select auth.uid()), p_company_id, p_branch_id, p_supplier_id, payment_number,
    round(p_amount, 4), coalesce(p_payment_date, current_date), method,
    nullif(trim(p_reference), ''), p_notes, upper(coalesce(p_currency, 'EUR')),
    'unallocated', p_idempotency_key, 'ready_for_posting', p_settlement_account_id
  )
  returning * into payment_row;

  journal_row := public.create_journal_entry(
    p_company_id, payment_row.payment_date, payment_row.payment_date,
    'Supplier payment ' || payment_row.payment_number, payment_row.payment_number,
    payment_row.currency, 1, p_branch_id, 'automatic'
  );
  perform set_config('app.financial_workflow', 'authorized', true);
  update public.journal_entries
  set source_type = 'supplier_payment', source_id = payment_row.id,
      source_key = payment_row.payment_number,
      metadata = jsonb_build_object('payment_number', payment_row.payment_number, 'supplier_id', p_supplier_id)
  where id = journal_row.id;
  perform set_config('app.financial_workflow', '', true);

  insert into public.journal_entry_lines (
    journal_entry_id, company_id, line_number, account_id, description,
    debit, credit, transaction_currency, transaction_amount, branch_id, created_by
  )
  values
    (journal_row.id, p_company_id, 1, payable_account.id, 'Supplier payment payable settlement',
      payment_row.amount, 0, payment_row.currency, payment_row.amount, p_branch_id, (select auth.uid())),
    (journal_row.id, p_company_id, 2, settlement_account.id, 'Supplier payment settlement account',
      0, payment_row.amount, payment_row.currency, payment_row.amount, p_branch_id, (select auth.uid()));
  journal_row := public.post_journal_entry(journal_row.id, 'Supplier payment recorded');

  perform set_config('app.financial_workflow', 'authorized', true);
  update public.vendor_payments
  set accounting_state = 'posted', posted_at = clock_timestamp(), posting_journal_entry_id = journal_row.id
  where id = payment_row.id
  returning * into payment_row;
  perform set_config('app.financial_workflow', '', true);
  return payment_row;
end
$$;


--
-- Name: record_supplier_payment_with_bank_account(uuid, uuid, date, numeric, text, uuid, text, text, uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_supplier_payment_with_bank_account(p_company_id uuid, p_supplier_id uuid, p_payment_date date, p_amount numeric, p_payment_method text, p_settlement_account_id uuid, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_branch_id uuid DEFAULT NULL::uuid, p_currency text DEFAULT 'EUR'::text, p_idempotency_key uuid DEFAULT NULL::uuid, p_company_bank_account_id uuid DEFAULT NULL::uuid) RETURNS public.vendor_payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payment_row public.vendor_payments;
begin
  if p_company_bank_account_id is not null then
    if lower(coalesce(p_payment_method, 'bank')) <> 'bank'
       or not exists (
         select 1 from public.company_bank_accounts account
          where account.id = p_company_bank_account_id
            and account.is_active
            and (
              account.company_id = p_company_id
              or exists (
                select 1 from public.company_bank_account_shares share
                 where share.company_bank_account_id = account.id
                   and share.shared_company_id = p_company_id
                   and share.is_active
              )
            )
       ) then
      raise exception 'The selected bank account is not available for this payment' using errcode = '23503';
    end if;
  end if;

  payment_row := public.record_supplier_payment(
    p_company_id, p_supplier_id, p_payment_date, p_amount, p_payment_method,
    p_settlement_account_id, p_reference, p_notes, p_branch_id, p_currency,
    p_idempotency_key
  );

  perform set_config('app.financial_workflow', 'authorized', true);
  update public.vendor_payments
     set company_bank_account_id = p_company_bank_account_id
   where id = payment_row.id
   returning * into payment_row;
  if payment_row.posting_journal_entry_id is not null then
    update public.journal_entries
       set metadata = coalesce(metadata, '{}'::jsonb)
           || case when p_company_bank_account_id is null then '{}'::jsonb
                   else jsonb_build_object('company_bank_account_id', p_company_bank_account_id) end
     where id = payment_row.posting_journal_entry_id;
  end if;
  perform set_config('app.financial_workflow', '', true);
  return payment_row;
end;
$$;


--
-- Name: withholding_transactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.withholding_transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    rule_id uuid NOT NULL,
    category text NOT NULL,
    source_type text NOT NULL,
    source_id uuid,
    payment_date date NOT NULL,
    gross_amount numeric(20,4) NOT NULL,
    rate_percent numeric(8,4) NOT NULL,
    withheld_amount numeric(20,4) NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    status text DEFAULT 'posted'::text NOT NULL,
    journal_entry_id uuid,
    idempotency_key uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT withholding_transactions_gross_amount_check CHECK ((gross_amount >= (0)::numeric)),
    CONSTRAINT withholding_transactions_rate_percent_check CHECK (((rate_percent >= (0)::numeric) AND (rate_percent <= (100)::numeric))),
    CONSTRAINT withholding_transactions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'posted'::text, 'reversed'::text]))),
    CONSTRAINT withholding_transactions_withheld_amount_check CHECK ((withheld_amount >= (0)::numeric))
);


--
-- Name: record_withholding(uuid, text, text, uuid, date, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_withholding(p_company_id uuid, p_category text, p_source_type text, p_source_id uuid, p_payment_date date, p_gross_amount numeric, p_idempotency_key uuid) RETURNS public.withholding_transactions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  existing_row public.withholding_transactions;
  rule_row public.withholding_tax_rules;
  result public.withholding_transactions;
begin
  if not (select private.has_company_permission(p_company_id, 'withholding.manage')) then
    raise exception 'Insufficient permission to record withholding' using errcode = '42501';
  end if;
  select * into existing_row from public.withholding_transactions
  where company_id = p_company_id and idempotency_key = p_idempotency_key;
  if found then return existing_row; end if;
  select * into rule_row from public.withholding_tax_rules
  where company_id = p_company_id and category = lower(trim(p_category))
    and effective_from <= p_payment_date and (effective_until is null or effective_until >= p_payment_date)
  order by effective_from desc limit 1;
  if not found then raise exception 'No effective withholding rule exists' using errcode = 'P0002'; end if;
  if rule_row.requires_legal_review then raise exception 'Withholding rule requires legal review' using errcode = '55000'; end if;
  insert into public.withholding_transactions(
    company_id, rule_id, category, source_type, source_id, payment_date,
    gross_amount, rate_percent, withheld_amount, idempotency_key, created_by
  ) values (
    p_company_id, rule_row.id, rule_row.category, p_source_type, p_source_id, p_payment_date,
    round(greatest(coalesce(p_gross_amount,0),0),4), rule_row.rate_percent,
    round(greatest(coalesce(p_gross_amount,0),0) * rule_row.rate_percent / 100, 2),
    p_idempotency_key, (select auth.uid())
  ) returning * into result;
  return result;
end
$$;


--
-- Name: fixed_assets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.fixed_assets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    asset_number text NOT NULL,
    name text NOT NULL,
    category text NOT NULL,
    supplier_id uuid,
    acquisition_date date NOT NULL,
    placed_in_service_date date NOT NULL,
    acquisition_cost numeric(20,4) NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    useful_life_months integer NOT NULL,
    book_depreciation_method text DEFAULT 'straight_line'::text NOT NULL,
    tax_category smallint DEFAULT 2 NOT NULL,
    tax_depreciation_rate_percent numeric(8,4) NOT NULL,
    accumulated_book_depreciation numeric(20,4) DEFAULT 0 NOT NULL,
    accumulated_tax_depreciation numeric(20,4) DEFAULT 0 NOT NULL,
    net_book_value numeric(20,4) NOT NULL,
    location text,
    responsible_employee_id uuid,
    attachments jsonb DEFAULT '[]'::jsonb NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    asset_account_id uuid NOT NULL,
    depreciation_expense_account_id uuid NOT NULL,
    accumulated_depreciation_account_id uuid NOT NULL,
    acquisition_journal_entry_id uuid,
    source_bill_id uuid,
    idempotency_key uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT fixed_assets_accumulated_book_depreciation_check CHECK ((accumulated_book_depreciation >= (0)::numeric)),
    CONSTRAINT fixed_assets_accumulated_tax_depreciation_check CHECK ((accumulated_tax_depreciation >= (0)::numeric)),
    CONSTRAINT fixed_assets_acquisition_cost_check CHECK ((acquisition_cost > (0)::numeric)),
    CONSTRAINT fixed_assets_attachments_check CHECK ((jsonb_typeof(attachments) = 'array'::text)),
    CONSTRAINT fixed_assets_book_depreciation_method_check CHECK ((book_depreciation_method = 'straight_line'::text)),
    CONSTRAINT fixed_assets_check CHECK ((placed_in_service_date >= acquisition_date)),
    CONSTRAINT fixed_assets_check1 CHECK ((accumulated_book_depreciation <= (acquisition_cost + 0.0001))),
    CONSTRAINT fixed_assets_check2 CHECK ((accumulated_tax_depreciation <= (acquisition_cost + 0.0001))),
    CONSTRAINT fixed_assets_net_book_value_check CHECK ((net_book_value >= (0)::numeric)),
    CONSTRAINT fixed_assets_status_check CHECK ((status = ANY (ARRAY['active'::text, 'disposed'::text, 'written_off'::text]))),
    CONSTRAINT fixed_assets_tax_category_check CHECK ((tax_category = ANY (ARRAY[1, 2, 3]))),
    CONSTRAINT fixed_assets_tax_depreciation_rate_percent_check CHECK (((tax_depreciation_rate_percent >= (0)::numeric) AND (tax_depreciation_rate_percent <= (100)::numeric))),
    CONSTRAINT fixed_assets_useful_life_months_check CHECK ((useful_life_months > 0))
);


--
-- Name: register_fixed_asset(uuid, text, text, date, date, numeric, integer, smallint, uuid, text, uuid, jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_fixed_asset(p_company_id uuid, p_name text, p_category text, p_acquisition_date date, p_placed_in_service_date date, p_acquisition_cost numeric, p_useful_life_months integer, p_tax_category smallint DEFAULT 2, p_supplier_id uuid DEFAULT NULL::uuid, p_location text DEFAULT NULL::text, p_responsible_employee_id uuid DEFAULT NULL::uuid, p_attachments jsonb DEFAULT '[]'::jsonb, p_source_bill_id uuid DEFAULT NULL::uuid, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.fixed_assets
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  result public.fixed_assets;
  existing_asset public.fixed_assets;
  company_currency text;
  asset_account_id uuid;
  depreciation_expense_account_id uuid;
  accumulated_depreciation_account_id uuid;
  payable_account_id uuid;
  equity_account_id uuid;
  journal_row public.journal_entries;
  next_number integer;
  tax_rate numeric(8,4);
begin
  if not (select private.has_company_permission(p_company_id, 'asset.manage')) then
    raise exception 'Insufficient permission to register fixed assets' using errcode = '42501';
  end if;
  if p_idempotency_key is not null then
    select * into existing_asset from public.fixed_assets
    where company_id = p_company_id and idempotency_key = p_idempotency_key;
    if found then return existing_asset; end if;
  end if;
  if trim(coalesce(p_name,'')) = '' or p_acquisition_cost <= 0 or p_useful_life_months <= 0 then
    raise exception 'Asset name, cost and useful life are required' using errcode = '23514';
  end if;
  if p_tax_category not in (1,2,3) then raise exception 'Unsupported Kosovo tax depreciation category' using errcode = '23514'; end if;
  tax_rate := case p_tax_category when 1 then 5 when 2 then 20 when 3 then 10 end;
  select currency into company_currency from public.companies where id = p_company_id;
  select id into asset_account_id from public.chart_of_accounts where company_id=p_company_id and code='1500' and active and posting_allowed limit 1;
  select id into depreciation_expense_account_id from public.chart_of_accounts where company_id=p_company_id and code='6200' and active and posting_allowed limit 1;
  select id into accumulated_depreciation_account_id from public.chart_of_accounts where company_id=p_company_id and code='1590' and active and posting_allowed limit 1;
  select id into payable_account_id from public.chart_of_accounts where company_id=p_company_id and code='2010' and active and posting_allowed limit 1;
  select id into equity_account_id from public.chart_of_accounts where company_id=p_company_id and code='3000' and active and posting_allowed limit 1;
  if asset_account_id is null or depreciation_expense_account_id is null or accumulated_depreciation_account_id is null or coalesce(payable_account_id,equity_account_id) is null then
    raise exception 'Fixed-asset accounts are not mapped' using errcode = '23514';
  end if;
  select count(*) + 1 into next_number from public.fixed_assets where company_id=p_company_id;

  journal_row := public.create_journal_entry(
    p_company_id, p_acquisition_date, p_acquisition_date, 'Fixed asset acquisition: '||trim(p_name),
    'ASSET-'||next_number::text, coalesce(company_currency,'EUR'), 1, null, 'automatic'
  );
  update public.journal_entries set source_type='fixed_asset_acquisition', source_id=journal_row.id,
    source_key='ASSET-'||next_number::text, metadata=jsonb_build_object('assetName',trim(p_name))
  where id = journal_row.id;
  insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,created_by)
  values(journal_row.id,p_company_id,1,asset_account_id,'Fixed asset acquisition',round(p_acquisition_cost,4),0,coalesce(company_currency,'EUR'),round(p_acquisition_cost,4),(select auth.uid()));
  insert into public.journal_entry_lines(journal_entry_id,company_id,line_number,account_id,description,debit,credit,transaction_currency,transaction_amount,created_by)
  values(journal_row.id,p_company_id,2,case when p_supplier_id is not null then payable_account_id else equity_account_id end,'Asset acquisition funding',0,round(p_acquisition_cost,4),coalesce(company_currency,'EUR'),round(p_acquisition_cost,4),(select auth.uid()));
  journal_row := public.post_journal_entry(journal_row.id, 'Fixed asset acquisition');

  insert into public.fixed_assets(
    company_id,asset_number,name,category,supplier_id,acquisition_date,placed_in_service_date,
    acquisition_cost,currency,useful_life_months,tax_category,tax_depreciation_rate_percent,
    net_book_value,location,responsible_employee_id,attachments,asset_account_id,
    depreciation_expense_account_id,accumulated_depreciation_account_id,acquisition_journal_entry_id,
    source_bill_id,idempotency_key,created_by,updated_by
  ) values (
    p_company_id,'A-'||extract(year from p_acquisition_date)::text||'-'||lpad(next_number::text,6,'0'),trim(p_name),trim(p_category),p_supplier_id,
    p_acquisition_date,p_placed_in_service_date,round(p_acquisition_cost,4),coalesce(company_currency,'EUR'),p_useful_life_months,p_tax_category,tax_rate,
    round(p_acquisition_cost,4),p_location,p_responsible_employee_id,coalesce(p_attachments,'[]'::jsonb),asset_account_id,
    depreciation_expense_account_id,accumulated_depreciation_account_id,journal_row.id,p_source_bill_id,p_idempotency_key,(select auth.uid()),(select auth.uid())
  ) returning * into result;
  return result;
end
$$;


--
-- Name: device_registrations; Type: TABLE; Schema: public; Owner: -
