    configuration_version integer DEFAULT 1 NOT NULL,
    sync_cursor bigint DEFAULT 0 NOT NULL,
    last_seen_at timestamp with time zone,
    registered_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    registered_by uuid,
