--
-- Name: reopen_cashier_shift(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_cashier_shift(p_company_id uuid, p_shift_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare shift_row public.cashier_shifts;
begin
  if not (select private.has_company_permission(p_company_id, 'pos.shift.reopen')) then raise exception 'Insufficient permission to reopen a cashier shift' using errcode='42501'; end if;
  if nullif(trim(p_reason),'') is null then raise exception 'A reason is required to reopen a cashier shift' using errcode='23514'; end if;
  select * into shift_row from public.cashier_shifts where id=p_shift_id and company_id=p_company_id for update;
  if not found or shift_row.status <> 'closed' then raise exception 'Only a closed cashier shift can be reopened' using errcode='55000'; end if;
  perform set_config('app.cashier_shift_workflow', 'authorized', true);
  update public.cashier_shifts set status='reopened',counted_cash=null,difference_amount=null,reopened_at=clock_timestamp(),reopened_by=(select auth.uid()),reopen_reason=trim(p_reason),closed_at=null,closed_by=null,approved_by=null,updated_at=clock_timestamp() where id=shift_row.id returning * into shift_row;
  perform set_config('app.cashier_shift_workflow', '', true);
  insert into public.cashier_shift_events (company_id,cashier_shift_id,event_type,payload,actor_id) values (p_company_id,shift_row.id,'reopened',jsonb_build_object('reason',trim(p_reason)),(select auth.uid()));
  return jsonb_build_object('shift_id',shift_row.id,'status',shift_row.status);
end $$;


--
-- Name: repair_unposted_customer_payments(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_unposted_customer_payments(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  payment_row public.payments;
  client_row public.clients;
  settlement_account public.chart_of_accounts;
  receivable_account public.chart_of_accounts;
  receivable_account_id uuid;
  journal_row public.journal_entries;
  posted_count integer := 0;
  skipped_count integer := 0;
  failures jsonb := '[]'::jsonb;
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_company_id is null or not public.can_access_company(p_company_id) then
    raise exception 'You do not have access to this company' using errcode = '42501';
  end if;
  if not (select private.has_company_permission(p_company_id, 'customer_payment.record'))
     or not (select private.has_company_permission(p_company_id, 'journal.create'))
     or not (select private.has_company_permission(p_company_id, 'journal.post')) then
    raise exception 'Insufficient permission to repair customer payment posting' using errcode = '42501';
  end if;

  for payment_row in
    select *
    from public.payments payment
    where payment.company_id = p_company_id
      and lower(coalesce(payment.accounting_state, 'legacy')) in ('legacy', 'ready_for_posting')
      and payment.posting_journal_entry_id is null
      and payment.reversed_at is null
    order by payment.payment_date nulls first, payment.created_at nulls first
  loop
    begin
      select * into client_row
      from public.clients
      where id = payment_row.client_id
        and company_id = payment_row.company_id;
      if not found then
        -- Legacy payments can reference a customer that was imported under a
        -- different company. Resolve them to the local walk-in customer so
        -- the settlement is posted to the correct tenant ledger.
        perform set_config('app.financial_workflow', 'authorized', true);
        update public.payments
        set client_id = private.ensure_pos_walk_in_customer(p_company_id)
        where id = payment_row.id;
        perform set_config('app.financial_workflow', '', true);

        select * into client_row
        from public.clients
        where id = (select client_id from public.payments where id = payment_row.id)
          and company_id = payment_row.company_id;
      end if;
      if not found then
        raise exception 'Customer is invalid for this payment' using errcode = '23514';
      end if;

      select * into settlement_account
      from public.chart_of_accounts
      where id = payment_row.settlement_account_id
        and company_id = p_company_id
        and active and posting_allowed;
      if not found then
        select * into settlement_account
        from public.chart_of_accounts
        where company_id = p_company_id
          and code = case when lower(coalesce(payment_row.payment_method, '')) = 'cash' then '1010' else '1020' end
          and active and posting_allowed
        limit 1;
      end if;
      if not found then
        raise exception 'No valid settlement account is mapped for payment %', payment_row.payment_number using errcode = '23514';
      end if;

      receivable_account_id := client_row.default_receivable_account_id;
      if receivable_account_id is null then
        select line.account_id into receivable_account_id
        from public.posting_rule_sets rule_set
        join public.posting_rule_lines line on line.rule_set_id = rule_set.id
        where rule_set.company_id = p_company_id
          and rule_set.event_type = 'customer_payment'
          and rule_set.active
          and rule_set.effective_from <= coalesce(payment_row.payment_date, current_date)
          and (rule_set.effective_until is null or rule_set.effective_until >= coalesce(payment_row.payment_date, current_date))
          and line.side = 'credit'
          and line.amount_component = 'gross'
        order by rule_set.version desc, rule_set.effective_from desc, line.line_number
        limit 1;
      end if;

      select * into receivable_account
      from public.chart_of_accounts
      where id = receivable_account_id
        and company_id = p_company_id
        and active and posting_allowed;
      if not found then
        raise exception 'No valid receivable account is mapped for payment %', payment_row.payment_number using errcode = '23514';
      end if;

      journal_row := public.create_journal_entry(
        p_company_id,
        coalesce(payment_row.payment_date, current_date),
        coalesce(payment_row.payment_date, current_date),
        'Customer payment ' || payment_row.payment_number,
        payment_row.payment_number,
        upper(coalesce(payment_row.currency, 'EUR')),
        coalesce(payment_row.exchange_rate, 1),
        payment_row.branch_id,
        'automatic'
      );
      perform set_config('app.financial_workflow', 'authorized', true);
      update public.journal_entries
      set source_type = 'customer_payment',
          source_id = payment_row.id,
          source_key = payment_row.payment_number,
          metadata = jsonb_build_object('payment_number', payment_row.payment_number, 'customer_id', payment_row.client_id)
      where id = journal_row.id;
      perform set_config('app.financial_workflow', '', true);

      insert into public.journal_entry_lines (
        journal_entry_id, company_id, line_number, account_id, description,
        debit, credit, transaction_currency, transaction_amount, branch_id, created_by
      ) values
        (journal_row.id, p_company_id, 1, settlement_account.id, 'Customer payment settlement',
          payment_row.amount, 0, upper(coalesce(payment_row.currency, 'EUR')), payment_row.amount, payment_row.branch_id, actor_id),
        (journal_row.id, p_company_id, 2, receivable_account.id, 'Customer payment receivable allocation',
          0, payment_row.amount, upper(coalesce(payment_row.currency, 'EUR')), payment_row.amount, payment_row.branch_id, actor_id);

      journal_row := public.post_journal_entry(journal_row.id, 'Customer payment repaired');
      perform set_config('app.financial_workflow', 'authorized', true);
      update public.payments
      set accounting_state = 'posted',
          posted_at = clock_timestamp(),
          posting_journal_entry_id = journal_row.id,
          settlement_account_id = settlement_account.id
      where id = payment_row.id;
      perform set_config('app.financial_workflow', '', true);
      posted_count := posted_count + 1;
    exception when others then
      perform set_config('app.financial_workflow', '', true);
      skipped_count := skipped_count + 1;
      failures := failures || jsonb_build_array(jsonb_build_object(
        'payment_id', payment_row.id,
        'payment_number', payment_row.payment_number,
        'message', sqlerrm
      ));
    end;
  end loop;

  return jsonb_build_object(
    'posted', posted_count,
    'skipped', skipped_count,
    'failures', failures
  );
end
$$;


--
-- Name: repair_unposted_expenses(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_unposted_expenses(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  expense_row public.expenses;
  posted_count integer := 0;
  skipped_count integer := 0;
  failures jsonb := '[]'::jsonb;
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_company_id is null or not public.can_access_company(p_company_id) then
    raise exception 'You do not have access to this company' using errcode = '42501';
  end if;
  if not (select private.has_company_permission(p_company_id, 'expense.post'))
     or not (select private.has_company_permission(p_company_id, 'journal.post')) then
    raise exception 'Insufficient permission to repair expense posting' using errcode = '42501';
  end if;

  for expense_row in
    select *
    from public.expenses expense
    where expense.company_id = p_company_id
      and lower(coalesce(expense.type, 'expense')) = 'expense'
      and lower(coalesce(expense.accounting_state, 'legacy')) in ('legacy', 'ready_for_posting')
      and expense.posting_journal_entry_id is null
      and coalesce(expense.amount, 0) > 0
    order by expense.date nulls first, expense.created_at nulls first
  loop
    begin
      perform public.post_expense(
        expense_row.id,
        gen_random_uuid(),
        'Repair unposted expense ledger posting'
      );
      posted_count := posted_count + 1;
    exception when others then
      skipped_count := skipped_count + 1;
      failures := failures || jsonb_build_array(jsonb_build_object(
        'expense_id', expense_row.id,
        'message', sqlerrm
      ));
    end;
  end loop;

  return jsonb_build_object(
    'posted', posted_count,
    'skipped', skipped_count,
    'failures', failures
  );
end
$$;


--
-- Name: repair_unposted_sales_invoices(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_unposted_sales_invoices(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  invoice_row public.invoices;
  original_status text;
  posted_count integer := 0;
  skipped_count integer := 0;
  failures jsonb := '[]'::jsonb;
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_company_id is null or not public.can_access_company(p_company_id) then
    raise exception 'You do not have access to this company' using errcode = '42501';
  end if;
  if not (select private.has_company_permission(p_company_id, 'sales_invoice.post')) then
    raise exception 'Insufficient permission to repair sales invoice posting' using errcode = '42501';
  end if;

  for invoice_row in
    select *
    from public.invoices invoice
    where invoice.company_id = p_company_id
      -- Read newer commercial-document columns through JSON so this repair
      -- also works on installations that have the accounting columns but have
      -- not yet applied the commercial-document extension.
      and upper(coalesce(to_jsonb(invoice)->>'commercial_document_type', invoice.type, 'INVOICE')) = 'INVOICE'
      and lower(coalesce(invoice.accounting_state, 'legacy')) in ('legacy', 'ready_for_posting')
      and (
        lower(coalesce(invoice.status::text, '')) in ('sent', 'paid', 'overdue', 'partially_paid')
        or upper(coalesce(to_jsonb(invoice)->>'commercial_status', '')) in ('ISSUED', 'PAID', 'OVERDUE', 'PARTIALLY_PAID', 'SENT', 'VIEWED')
      )
    order by invoice.issue_date nulls first, invoice.created_at nulls first
  loop
    begin
      original_status := lower(invoice_row.status::text);

      -- The historical lifecycle used sent/paid/overdue as operational
      -- statuses. The posting command accepts an editable state, so move the
      -- row into that state inside this transaction before posting it.
      perform set_config('app.financial_workflow', 'authorized', true);
      update public.invoices
      set accounting_state = 'ready_for_posting',
          posting_date = coalesce(posting_date, issue_date, current_date),
          status = case
            when original_status in ('draft', 'approved') then status
            else 'draft'::public.invoice_status
          end
      where id = invoice_row.id;
      perform set_config('app.financial_workflow', '', true);

      -- Some legacy imports stored a customer from another company or no
      -- customer at all. Keep the sale in the correct company by resolving
      -- those records to that company's walk-in customer before posting.
      if not exists (
        select 1
        from public.clients client
        where client.id = invoice_row.client_id
          and client.company_id = p_company_id
      ) then
        perform set_config('app.financial_workflow', 'authorized', true);
        update public.invoices
        set client_id = private.ensure_pos_walk_in_customer(p_company_id)
        where id = invoice_row.id;
        perform set_config('app.financial_workflow', '', true);
      end if;

      perform public.post_sales_invoice(
        invoice_row.id,
        gen_random_uuid(),
        'Repair issued invoice ledger posting'
      );

      -- Preserve payment/overdue state after the invoice has been posted.
      -- For sent invoices, the posting command's posted state is the correct
      -- final state and the commercial trigger marks it as issued.
      if original_status in ('paid', 'overdue', 'partially_paid') then
        perform set_config('app.financial_workflow', 'authorized', true);
        update public.invoices
        set status = original_status::public.invoice_status
        where id = invoice_row.id;
        perform set_config('app.financial_workflow', '', true);
      end if;

      posted_count := posted_count + 1;
    exception when others then
      perform set_config('app.financial_workflow', '', true);
      skipped_count := skipped_count + 1;
      failures := failures || jsonb_build_array(jsonb_build_object(
        'invoice_id', invoice_row.id,
        'invoice_number', invoice_row.invoice_number,
        'message', sqlerrm
      ));
    end;
  end loop;

  return jsonb_build_object(
    'posted', posted_count,
    'skipped', skipped_count,
    'failures', failures
  );
end
$$;


--
-- Name: replace_posted_invoice_document(jsonb, jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_posted_invoice_document(p_invoice jsonb, p_items jsonb, p_invoice_id uuid, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  invoice_row public.invoices;
  journal_row public.journal_entries;
  saved_invoice public.invoices;
  active_allocated numeric(20,4) := 0;
  replacement_payload jsonb;
  legacy_client_id uuid;
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_invoice_id is null then
    raise exception 'Invoice id is required' using errcode = '23514';
  end if;
  if jsonb_typeof(coalesce(p_invoice, '{}'::jsonb)) <> 'object' then
    raise exception 'Invoice payload must be an object' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(p_items, '[]'::jsonb)) = 0 then
    raise exception 'At least one invoice item is required' using errcode = '22023';
  end if;

  select *
  into invoice_row
  from public.invoices
  where id = p_invoice_id
  for update;

  if not found then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if invoice_row.company_id is null
     or not coalesce(private.has_company_permission(invoice_row.company_id, 'sales_invoice.edit'), false)
     or not coalesce(private.has_company_permission(invoice_row.company_id, 'journal.reverse'), false) then
    raise exception 'Insufficient permission to edit posted invoices' using errcode = '42501';
  end if;
  if upper(coalesce(invoice_row.commercial_document_type, '')) <> 'INVOICE' then
    raise exception 'Only ordinary sales invoices can be edited after posting; use a correction workflow'
      using errcode = '55000';
  end if;
  if lower(coalesce(invoice_row.accounting_state, 'legacy')) not in ('posted', 'legacy') then
    raise exception 'This invoice is already reversed or excluded and cannot be edited'
      using errcode = '55000';
  end if;
  if lower(coalesce(invoice_row.accounting_state, 'legacy')) = 'posted'
     and invoice_row.posting_journal_entry_id is null then
    raise exception 'The posted invoice has no posting journal and cannot be edited'
      using errcode = '55000';
  end if;
  if lower(coalesce(invoice_row.accounting_state, 'legacy')) = 'legacy'
     and invoice_row.posting_journal_entry_id is not null then
    raise exception 'The legacy invoice has an unexpected posting journal'
      using errcode = '55000';
  end if;
  if lower(coalesce(invoice_row.accounting_state, 'legacy')) = 'legacy'
     and invoice_row.client_id is not null
     and exists (
       select 1
       from public.clients client_row
       where client_row.id = invoice_row.client_id
         and client_row.user_id = actor_id
         and client_row.company_id is not null
         and not private.company_is_in_scope(invoice_row.company_id, client_row.company_id)
     )
     and nullif(trim(coalesce(p_invoice ->> 'client_id', '')), '')::uuid is not distinct from invoice_row.client_id then
    -- Some legacy imports point at a customer owned by the same user but
    -- stored under a different legacy company. Preserve that relationship;
    -- the canonical writer is temporarily given a null customer only while it
    -- validates and posts the replacement journal.
    legacy_client_id := invoice_row.client_id;
  end if;
  if exists (
    select 1
    from public.inventory_stock_movements movement
    where movement.invoice_id = invoice_row.id
  ) then
    raise exception 'Stock-tracked invoices must be corrected with a stock return before editing'
      using errcode = '55000';
  end if;
  if exists (
    select 1
    from public.pos_orders order_row
    where order_row.invoice_id = invoice_row.id
  ) then
    raise exception 'POS invoices must be corrected through the POS return workflow'
      using errcode = '55000';
  end if;
  if exists (
    select 1
    from public.commercial_document_advance_allocations allocation
    where allocation.advance_invoice_id = invoice_row.id
       or allocation.final_invoice_id = invoice_row.id
  ) then
    raise exception 'Invoices used in an advance reconciliation require a correction workflow'
      using errcode = '55000';
  end if;
  if exists (
    select 1
    from public.document_source_links link
    where link.source_id = invoice_row.id
       or link.target_id = invoice_row.id
  ) then
    raise exception 'Converted or linked invoices require a correction workflow'
      using errcode = '55000';
  end if;

  select round(coalesce(sum(allocation.allocated_amount), 0), 4)
  into active_allocated
  from public.payment_allocations allocation
  where allocation.invoice_id = invoice_row.id
    and allocation.status = 'active';

  if active_allocated > 0
     and nullif(trim(coalesce(p_invoice ->> 'client_id', '')), '')::uuid is distinct from invoice_row.client_id then
    raise exception 'A paid invoice cannot change customer while payments are allocated'
      using errcode = '55000';
  end if;

  if lower(coalesce(invoice_row.accounting_state, 'legacy')) = 'posted' then
    select *
    into journal_row
    from public.journal_entries
    where id = invoice_row.posting_journal_entry_id
    for update;
    if not found or journal_row.status <> 'posted' then
      raise exception 'The invoice posting journal is not available for replacement'
        using errcode = '55000';
    end if;

    perform public.reverse_journal_entry(
      journal_row.id,
      coalesce(invoice_row.posting_date, invoice_row.issue_date, current_date),
      'Invoice edited from the mobile invoice workflow'
    );

    -- Free the automatic-journal source key for the replacement posting while
    -- retaining the reversed journal as the audit trail for the old version.
    perform set_config('app.financial_workflow', 'authorized', true);
    update public.journal_entries
    set source_type = coalesce(source_type, 'sales_invoice') || '_replaced_' || left(id::text, 8),
        source_key = coalesce(source_key, entry_number) || ':replaced:' || id::text,
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'replaced_by', actor_id,
          'replaced_at', clock_timestamp(),
          'invoice_id', invoice_row.id
        )
    where id = journal_row.id;
  end if;

  update public.invoices
  set status = 'draft',
      commercial_status = 'DRAFT',
      accounting_state = 'ready_for_posting',
      accounting_status = 'READY_TO_POST',
      vat_status = 'NOT_EVALUATED',
      payment_status = 'UNPAID',
      posting_journal_entry_id = null,
      posted_at = null,
      posted_by = null,
      issued_at = null,
      issued_by = null,
      immutable_at = null
  where id = invoice_row.id;
  perform set_config('app.financial_workflow', '', true);

  replacement_payload := coalesce(p_invoice, '{}'::jsonb) || jsonb_build_object(
    'user_id', actor_id,
    'status', 'draft',
    'commercial_status', 'DRAFT',
    'accounting_state', 'ready_for_posting',
    'accounting_status', 'READY_TO_POST',
    'vat_status', 'NOT_EVALUATED',
    'payment_status', 'UNPAID'
  );
  if legacy_client_id is not null then
    replacement_payload := jsonb_set(replacement_payload, '{client_id}', 'null'::jsonb, true);
  end if;
  saved_invoice := public.save_invoice_document(
    replacement_payload,
    p_items,
    invoice_row.id,
    true,
    p_idempotency_key
  );

  if legacy_client_id is not null then
    perform set_config('app.financial_workflow', 'authorized', true);
    update public.invoices
    set client_id = legacy_client_id
    where id = saved_invoice.id
    returning * into saved_invoice;
    perform set_config('app.financial_workflow', '', true);
  end if;

  if active_allocated > round(coalesce(saved_invoice.total_amount, 0), 4) then
    raise exception 'The edited invoice total cannot be lower than allocated payments'
      using errcode = '22003';
  end if;
  if active_allocated > 0 then
    saved_invoice := private.refresh_customer_payment_state(saved_invoice.id);
  end if;
  return saved_invoice;
end;
$$;


--
-- Name: approval_workflows; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approval_workflows (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    requested_by uuid,
    required_role_code text,
    current_step integer DEFAULT 1 NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    resolved_at timestamp with time zone,
    resolved_by uuid,
    CONSTRAINT approval_workflows_current_step_check CHECK ((current_step > 0)),
    CONSTRAINT approval_workflows_entity_type_check CHECK ((entity_type = ANY (ARRAY['sales_invoice'::text, 'supplier_bill'::text, 'expense'::text, 'income'::text]))),
    CONSTRAINT approval_workflows_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT approval_workflows_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'cancelled'::text])))
);


--
-- Name: request_sales_invoice_approval(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_sales_invoice_approval(p_invoice_id uuid, p_note text DEFAULT NULL::text) RETURNS public.approval_workflows
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  invoice_row public.invoices;
  workflow_row public.approval_workflows;
begin
  select * into invoice_row from public.invoices where id = p_invoice_id for update;
  if not found then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if not (select private.has_company_permission(invoice_row.company_id, 'sales_invoice.edit')) then
    raise exception 'Insufficient permission to request invoice approval' using errcode = '42501';
  end if;
  if invoice_row.status <> 'draft' or invoice_row.accounting_state not in ('legacy', 'ready_for_posting') then
    raise exception 'Only an editable draft invoice may be submitted for approval' using errcode = '55000';
  end if;

  insert into public.approval_workflows (
    company_id, entity_type, entity_id, status, requested_by, required_role_code, metadata
  )
  values (
    invoice_row.company_id, 'sales_invoice', invoice_row.id, 'pending',
    (select auth.uid()), 'sales_invoice.approve', jsonb_build_object('note', p_note)
  )
  on conflict (company_id, entity_type, entity_id) do update
  set status = 'pending',
      requested_at = clock_timestamp(),
      requested_by = (select auth.uid()),
      resolved_at = null,
      resolved_by = null,
      metadata = excluded.metadata
  returning * into workflow_row;

  insert into public.approval_actions (workflow_id, company_id, action, action_by, reason)
  values (workflow_row.id, invoice_row.company_id, 'requested', (select auth.uid()), p_note);

  update public.invoices
  set status = 'pending_approval', approval_status = 'pending'
  where id = invoice_row.id
  returning * into invoice_row;

  perform private.emit_domain_outbox_event(
    invoice_row.company_id, invoice_row.branch_id, 'sales_invoice', invoice_row.id,
    'sales_invoice.approval_requested',
    jsonb_build_object('invoice_number', invoice_row.invoice_number, 'workflow_id', workflow_row.id),
    'sales_invoice.approval_requested:' || invoice_row.id::text || ':' || workflow_row.id::text
  );
  return workflow_row;
end
$$;


--
-- Name: reserve_contract_number(uuid, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_contract_number(p_company_id uuid, p_prefix text DEFAULT 'CTR'::text, p_year integer DEFAULT (EXTRACT(year FROM now()))::integer, p_manual_number text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  next_number integer;
  result text;
begin
  if auth.uid() is null
     or not private.has_company_permission(p_company_id, 'contracts.manage') then
    raise exception 'not authorized' using errcode = '42501';
  end if;
  if nullif(trim(p_manual_number), '') is not null then
    return trim(p_manual_number);
  end if;
  select coalesce(max((regexp_match(contract_number, '^' || regexp_replace(p_prefix, '[^A-Za-z0-9_-]', '', 'g') || '-' || p_year::text || '-([0-9]+)$'))[1]::integer), 0) + 1
    into next_number
  from public.contracts
  where company_id = p_company_id;
  result := regexp_replace(p_prefix, '[^A-Za-z0-9_-]', '', 'g') || '-' || p_year::text || '-' || lpad(next_number::text, 4, '0');
  return result;
end;
$_$;


--
-- Name: reserve_invoice_number(uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_invoice_number(p_company_id uuid, p_document_type text DEFAULT 'invoice'::text, p_issue_date date DEFAULT CURRENT_DATE) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  requested_type text := lower(trim(coalesce(p_document_type, 'invoice')));
  sequence_key text;
  default_prefix text;
  period_key text := to_char(coalesce(p_issue_date, current_date), 'YYYY');
  sequence_row public.document_sequences%rowtype;
  max_existing bigint := 0;
  next_value bigint;
begin
  if p_company_id is null then
    raise exception 'A company is required to reserve a document number'
      using errcode = '22023';
  end if;

  if requested_type not in (
    'quote', 'proforma', 'sales_order', 'delivery_note', 'invoice',
    'advance_invoice', 'final_invoice', 'credit_note', 'debit_note',
    'simplified_invoice', 'fiscal_receipt', 'bad_debt_invoice',
    'offer', 'order'
  ) then
    raise exception 'Unsupported commercial document type %', requested_type
      using errcode = '22023';
  end if;

  requested_type := case requested_type
    when 'offer' then 'quote'
    when 'order' then 'sales_order'
    else requested_type
  end;

  sequence_key := case requested_type
    when 'final_invoice' then 'invoice'
    when 'simplified_invoice' then 'invoice'
    else requested_type
  end;

  default_prefix := case sequence_key
    when 'quote' then 'OF-'
    when 'proforma' then 'PRO-'
    when 'sales_order' then 'POR-'
    when 'delivery_note' then 'FD-'
    when 'invoice' then 'FAT-'
    when 'advance_invoice' then 'PAR-'
    when 'credit_note' then 'NK-'
    when 'debit_note' then 'ND-'
    when 'fiscal_receipt' then 'KUP-'
    when 'bad_debt_invoice' then 'BDI-'
    else 'DOC-'
  end;

  -- Number reservation remains restricted to users who can create sales
  -- documents. Compatibility must not weaken tenant authorization.
  if not (
    (select private.has_company_permission(p_company_id, 'sales_invoice.create'))
    or (select private.has_company_permission(p_company_id, 'invoice.create'))
  ) then
    raise exception 'Insufficient permission to reserve a document number'
      using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_company_id::text || ':' || sequence_key || ':' || period_key, 0)
  );

  insert into public.document_sequences (
    company_id, branch_id, document_type, prefix, suffix, next_value,
    padding, reset_rule, current_period_key, is_active, created_by, updated_by
  ) values (
    p_company_id, null, 'operix_' || sequence_key, default_prefix, '', 1,
    6, 'fiscal_year', period_key, true, (select auth.uid()), (select auth.uid())
  ) on conflict do nothing;

  select * into sequence_row
  from public.document_sequences
  where company_id = p_company_id
    and branch_id is null
    and document_type = 'operix_' || sequence_key
    and is_active
  order by updated_at desc
  limit 1
  for update;

  if not found then
    raise exception 'Unable to initialize document numbering for company %', p_company_id
      using errcode = 'P0002';
  end if;

  -- Read existing legacy invoice fields while older rows are still present.
  select coalesce(max(
    nullif(substring(invoice.invoice_number from '([0-9]+)$'), '')::bigint
  ), 0)
  into max_existing
  from public.invoices invoice
  where invoice.company_id = p_company_id
    and invoice.issue_date is not null
    and to_char(invoice.issue_date, 'YYYY') = period_key
    and case sequence_key
      when 'quote' then lower(coalesce(invoice.type, '')) = 'offer'
        and lower(coalesce(invoice.subtype, '')) in ('offer', 'regular')
      when 'proforma' then lower(coalesce(invoice.type, '')) = 'proforma'
        or lower(coalesce(invoice.subtype, '')) in ('pro_invoice', 'proforma')
      when 'sales_order' then lower(coalesce(invoice.type, '')) = 'order'
        or lower(coalesce(invoice.subtype, '')) = 'order'
      when 'delivery_note' then lower(coalesce(invoice.subtype, '')) = 'delivery_note'
      when 'invoice' then lower(coalesce(invoice.type, 'invoice')) = 'invoice'
        and lower(coalesce(invoice.subtype, 'regular')) in ('regular', 'final_invoice', 'simplified_invoice')
      else lower(coalesce(invoice.subtype, '')) = sequence_key
    end;

  next_value := case
    when sequence_row.current_period_key is distinct from period_key
      then greatest(1, max_existing + 1)
    else greatest(coalesce(sequence_row.next_value, 1), max_existing + 1)
  end;

  update public.document_sequences as document_sequence
  set prefix = coalesce(sequence_row.prefix, default_prefix),
      suffix = coalesce(sequence_row.suffix, ''),
      next_value = document_sequence.next_value + 1,
      padding = greatest(1, coalesce(sequence_row.padding, 6)),
      reset_rule = 'fiscal_year',
      current_period_key = period_key,
      updated_at = clock_timestamp(),
      updated_by = (select auth.uid())
  where document_sequence.id = sequence_row.id;

  return coalesce(sequence_row.prefix, default_prefix)
    || period_key || '-'
    || lpad(next_value::text, greatest(1, coalesce(sequence_row.padding, 6)), '0')
    || coalesce(sequence_row.suffix, '');
end
$_$;


--
-- Name: resolve_invoice_qr(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_invoice_qr(invoice_number_input text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  invoice_row invoices%rowtype;
  portal_token text;
begin
  if nullif(trim(invoice_number_input), '') is null
     or length(trim(invoice_number_input)) < 32
     or trim(invoice_number_input) !~ '^[A-Fa-f0-9]{32,}$' then
    return jsonb_build_object('error', 'This QR reference is invalid or expired.');
  end if;

  select * into invoice_row
  from invoices
  where public_qr_token = trim(invoice_number_input)
    and status::text <> 'draft'
  limit 1;
  if not found then
    return jsonb_build_object('error', 'Invoice not found.');
  end if;

  if auth.uid() is not null and invoice_row.user_id = auth.uid() then
    return jsonb_build_object('destination', 'owner', 'url', '/invoices/preview/' || invoice_row.invoice_number);
  end if;

  select token into portal_token
  from customer_portal_tokens
  where invoice_id = invoice_row.id
    and (expires_at is null or expires_at > now())
  order by created_at desc
  limit 1;

  if portal_token is null then
    perform set_config('app.portal_link_workflow', 'authorized', true);
    insert into customer_portal_tokens(user_id, company_id, client_id, invoice_id)
    values(invoice_row.user_id, invoice_row.company_id, invoice_row.client_id, invoice_row.id)
    returning token into portal_token;
  end if;

  return jsonb_build_object(
    'destination', 'portal',
    'url', '/portal/' || portal_token || '/invoice/' || invoice_row.id
  );
end
$_$;


--
-- Name: resume_held_pos_order(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resume_held_pos_order(p_company_id uuid, p_held_order_id uuid, p_expected_version integer) RETURNS public.held_orders
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare held_row public.held_orders;
begin
  if not (select private.has_company_permission(p_company_id, 'pos.order.hold')) then
    raise exception 'Insufficient permission to resume held orders' using errcode = '42501';
  end if;
  select * into held_row
  from public.held_orders
  where id = p_held_order_id
    and company_id = p_company_id
    and cashier_id = (select auth.uid())
  for update;
  if not found or held_row.status <> 'held' then
    raise exception 'Held order is unavailable' using errcode = '55000';
  end if;
  if held_row.version <> p_expected_version then
    raise exception 'Held order changed on another device; refresh before resuming'
      using errcode = '40001';
  end if;
  if held_row.expires_at is not null and held_row.expires_at <= clock_timestamp() then
    perform set_config('app.held_order_workflow', 'authorized', true);
    update public.held_orders
    set status = 'expired', version = version + 1, updated_at = clock_timestamp(),
        updated_by = (select auth.uid())
    where id = held_row.id
    returning * into held_row;
    perform set_config('app.held_order_workflow', '', true);
    return held_row;
  end if;

  perform set_config('app.held_order_workflow', 'authorized', true);
  update public.held_orders
  set status = 'resumed', resumed_at = clock_timestamp(), version = version + 1,
      updated_at = clock_timestamp(), updated_by = (select auth.uid())
  where id = held_row.id
  returning * into held_row;
  perform set_config('app.held_order_workflow', '', true);
  return held_row;
end
$$;


--
-- Name: reverse_asset_depreciation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_asset_depreciation(p_run_id uuid, p_reason text) RETURNS public.asset_depreciation_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result public.asset_depreciation_runs; line_row record;
begin
  select * into result from public.asset_depreciation_runs where id=p_run_id for update;
  if not found then raise exception 'Depreciation run not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(result.company_id,'asset.depreciation.post')) then raise exception 'Insufficient permission to reverse depreciation' using errcode='42501'; end if;
  if result.status <> 'posted' then raise exception 'Only posted depreciation can be reversed' using errcode='55000'; end if;
  if trim(coalesce(p_reason,''))='' then raise exception 'Depreciation reversal reason is required' using errcode='23514'; end if;
  if result.journal_entry_id is not null then perform public.reverse_journal_entry(result.journal_entry_id,current_date,p_reason); end if;
  for line_row in select * from public.asset_depreciation_lines where run_id=result.id loop
    update public.fixed_assets set accumulated_book_depreciation=greatest(accumulated_book_depreciation-line_row.book_depreciation_amount,0),
      accumulated_tax_depreciation=greatest(accumulated_tax_depreciation-line_row.tax_depreciation_amount,0),
      net_book_value=acquisition_cost-greatest(accumulated_book_depreciation-line_row.book_depreciation_amount,0),updated_at=clock_timestamp(),updated_by=(select auth.uid())
    where id=line_row.asset_id;
  end loop;
  update public.asset_depreciation_runs set status='reversed',reversed_at=clock_timestamp(),reversed_by=(select auth.uid()),reversal_reason=p_reason where id=result.id returning * into result;
  return result;
end
$$;


--
-- Name: reverse_customer_payment(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_customer_payment(p_payment_id uuid, p_reversal_date date DEFAULT CURRENT_DATE, p_reason text DEFAULT NULL::text) RETURNS public.payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payment_row public.payments;
  allocation_row public.payment_allocations;
  reversal_row public.journal_entries;
  actor_id uuid := (select auth.uid());
begin
  select * into payment_row
  from public.payments
  where id = p_payment_id
  for update;
  if not found then
    raise exception 'Customer payment not found' using errcode = 'P0002';
  end if;
  if not coalesce(private.has_company_permission(payment_row.company_id, 'journal.reverse'), false) then
    raise exception 'Insufficient permission to reverse customer payments' using errcode = '42501';
  end if;
  if payment_row.accounting_state <> 'posted' or payment_row.posting_journal_entry_id is null then
    raise exception 'Only posted customer payments can be reversed' using errcode = '55000';
  end if;
  if payment_row.reversal_journal_entry_id is not null or payment_row.accounting_state = 'reversed' then
    raise exception 'Customer payment has already been reversed' using errcode = '55000';
  end if;
  if actor_id is null or nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'A signed-in actor and reversal reason are required' using errcode = '23514';
  end if;

  reversal_row := public.reverse_journal_entry(
    payment_row.posting_journal_entry_id,
    coalesce(p_reversal_date, current_date),
    trim(p_reason)
  );

  -- Allocations are append-only. Reverse them as part of the same payment
  -- reversal so invoice status and customer balances cannot remain paid by a
  -- payment that no longer exists economically.
  for allocation_row in
    select *
    from public.payment_allocations
    where payment_id = payment_row.id
      and status = 'active'
    for update
  loop
    update public.payment_allocations
    set status = 'reversed',
        reversed_at = clock_timestamp(),
        reversed_by = actor_id,
        reversal_reason = trim(p_reason)
    where id = allocation_row.id;
    perform private.refresh_customer_payment_state(allocation_row.invoice_id);
  end loop;

  perform set_config('app.financial_workflow', 'authorized', true);
  update public.payments
  set accounting_state = 'reversed',
      allocation_status = 'reversed',
      reversed_at = clock_timestamp(),
      reversal_journal_entry_id = reversal_row.id,
      reversal_reason = trim(p_reason)
  where id = payment_row.id
  returning * into payment_row;
  perform set_config('app.financial_workflow', '', true);
  return payment_row;
end
$$;


--
-- Name: reverse_journal_entry(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_journal_entry(p_journal_entry_id uuid, p_reversal_date date, p_reason text) RETURNS public.journal_entries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  original public.journal_entries;
  reversal public.journal_entries;
begin
  select * into original
  from public.journal_entries
  where id = p_journal_entry_id
  for update;
  if not found then
    raise exception 'Journal entry not found' using errcode = 'P0002';
  end if;
  if not (select private.has_company_permission(original.company_id, 'journal.reverse')) then
    raise exception 'Insufficient permission to reverse journals' using errcode = '42501';
  end if;
  if original.status <> 'posted' then
    raise exception 'Only posted journals may be reversed' using errcode = '55000';
  end if;
  if trim(coalesce(p_reason, '')) = '' then
    raise exception 'A reversal reason is required' using errcode = '23514';
  end if;

  insert into public.journal_entries (
    company_id, branch_id, entry_number, status, entry_type, posting_date,
    document_date, description, reference, source_type, source_id, source_key,
    currency, exchange_rate, metadata, reversal_of_id, reversal_reason,
    created_by, updated_by
  )
  values (
    original.company_id, original.branch_id,
    private.next_journal_number(original.company_id, p_reversal_date),
    'draft', 'reversal', p_reversal_date, p_reversal_date,
    'Reversal: ' || original.description, original.entry_number,
    'journal_reversal', original.id, original.entry_number,
    original.currency, original.exchange_rate, original.metadata,
    original.id, trim(p_reason), (select auth.uid()), (select auth.uid())
  )
  returning * into reversal;

  insert into public.journal_entry_lines (
    journal_entry_id, company_id, line_number, account_id, description,
    debit, credit, transaction_currency, transaction_amount, exchange_rate,
    cost_centre_id, project_id, branch_id, tax_code, tax_base, tax_amount,
    metadata, created_by
  )
  select
    reversal.id, line.company_id, line.line_number, line.account_id,
    coalesce(line.description, original.description),
    line.credit, line.debit, line.transaction_currency,
    case when line.transaction_amount is null then null else -line.transaction_amount end,
    line.exchange_rate, line.cost_centre_id, line.project_id, line.branch_id,
    line.tax_code, line.tax_base,
    case when line.tax_amount is null then null else -line.tax_amount end,
    line.metadata, (select auth.uid())
  from public.journal_entry_lines line
  where line.journal_entry_id = original.id
  order by line.line_number;

  reversal := public.post_journal_entry(reversal.id, trim(p_reason));
  perform set_config('app.financial_workflow', 'authorized', true);
  perform set_config('app.change_reason', trim(p_reason), true);
  update public.journal_entries
  set
    status = 'reversed',
    reversed_by_id = reversal.id,
    updated_at = clock_timestamp(),
    updated_by = (select auth.uid())
  where id = original.id;
  perform set_config('app.financial_workflow', '', true);
  perform set_config('app.change_reason', '', true);
  return reversal;
end
$$;


--
-- Name: reverse_payroll_run(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_payroll_run(p_payroll_run_id uuid, p_idempotency_key text, p_reason text) RETURNS public.payroll_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare original public.payroll_runs; reversal public.payroll_runs; reversed_journal public.journal_entries;
begin
  select * into original from public.payroll_runs where id=p_payroll_run_id for update;
  if not found then raise exception 'Payroll run not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(original.company_id,'payroll.run.reverse')) then raise exception 'Insufficient permission' using errcode='42501'; end if;
  if trim(coalesce(p_reason,''))='' then raise exception 'Reversal reason is required' using errcode='23514'; end if;
  if original.status not in ('finalized','payment_pending') then raise exception 'Paid or non-finalized payroll cannot use direct reversal' using errcode='55000'; end if;
  if exists(select 1 from public.payroll_liabilities where payroll_run_id=original.id and paid_amount>0) then
    raise exception 'Payroll with payments requires payment reversal before payroll reversal' using errcode='55000';
  end if;
  select * into reversal from public.payroll_runs where company_id=original.company_id and idempotency_key=p_idempotency_key;
  if found then return reversal; end if;
  reversed_journal:=public.reverse_journal_entry(original.journal_entry_id,current_date,p_reason);
  perform set_config('app.payroll_workflow','authorized',true);
  insert into public.payroll_runs(
    company_id,branch_id,payroll_period_id,payroll_group_id,config_set_id,run_number,run_type,original_run_id,
    status,currency,idempotency_key,journal_entry_id,total_gross,total_employee_pension,total_employer_pension,
    total_tax,total_other_deductions,total_net,total_employer_cost,created_by,updated_by,finalized_at,finalized_by
  ) values (
    original.company_id,original.branch_id,original.payroll_period_id,original.payroll_group_id,original.config_set_id,
    original.run_number||'-REV','reversal',original.id,'finalized',original.currency,p_idempotency_key,reversed_journal.id,
    -original.total_gross,-original.total_employee_pension,-original.total_employer_pension,-original.total_tax,
    -original.total_other_deductions,-original.total_net,-original.total_employer_cost,(select auth.uid()),(select auth.uid()),now(),(select auth.uid())
  ) returning * into reversal;
  update public.payroll_liabilities set status='reversed' where payroll_run_id=original.id;
  update public.payroll_runs set status='reversed',reversal_journal_entry_id=reversed_journal.id,updated_at=now(),updated_by=(select auth.uid())
  where id=original.id;
  perform private.record_payroll_audit(original.company_id,original.branch_id,'payroll.run.reversed','payroll_run',original.id,to_jsonb(original),jsonb_build_object('reversalRunId',reversal.id),p_reason);
  perform private.emit_domain_outbox_event(original.company_id,original.branch_id,'payroll_run',original.id,'payroll.run.reversed',
    jsonb_build_object('reversalRunId',reversal.id,'reversalJournalId',reversed_journal.id),p_idempotency_key||':reversed');
  return reversal;
end $$;


--
-- Name: reverse_supplier_payment(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_supplier_payment(p_payment_id uuid, p_reversal_date date DEFAULT CURRENT_DATE, p_reason text DEFAULT NULL::text) RETURNS public.vendor_payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payment_row public.vendor_payments;
  reversal_row public.journal_entries;
begin
  select * into payment_row from public.vendor_payments where id = p_payment_id for update;
  if not found then
    raise exception 'Supplier payment not found' using errcode = 'P0002';
  end if;
  if not (select private.has_company_permission(payment_row.company_id, 'journal.reverse')) then
    raise exception 'Insufficient permission to reverse supplier payments' using errcode = '42501';
  end if;
  if payment_row.accounting_state <> 'posted' or payment_row.posting_journal_entry_id is null then
    raise exception 'Only posted supplier payments can be reversed' using errcode = '55000';
  end if;
  if payment_row.reversal_journal_entry_id is not null or payment_row.accounting_state = 'reversed' then
    raise exception 'Supplier payment has already been reversed' using errcode = '55000';
  end if;
  if nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'A reversal reason is required' using errcode = '23514';
  end if;

  reversal_row := public.reverse_journal_entry(
    payment_row.posting_journal_entry_id,
    coalesce(p_reversal_date, current_date),
    trim(p_reason)
  );
  perform set_config('app.financial_workflow', 'authorized', true);
  update public.vendor_payments
  set accounting_state = 'reversed', allocation_status = 'reversed',
      reversed_at = clock_timestamp(), reversal_journal_entry_id = reversal_row.id,
      reversal_reason = trim(p_reason)
  where id = payment_row.id
  returning * into payment_row;
  perform set_config('app.financial_workflow', '', true);
  return payment_row;
end
$$;


--
-- Name: revoke_company_bank_account_share(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_company_bank_account_share(p_company_bank_account_id uuid, p_shared_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  bank_row public.company_bank_accounts;
  changed boolean := false;
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  select * into bank_row from public.company_bank_accounts
   where id = p_company_bank_account_id for update;
  if not found then raise exception 'Bank account not found' using errcode = 'P0002'; end if;
  if not private.has_company_permission(bank_row.company_id, 'company.manage') then
    raise exception 'You do not have permission to revoke this bank-account share' using errcode = '42501';
  end if;

  update public.company_bank_account_shares
     set is_active = false, updated_at = now(), updated_by = actor_id
   where company_bank_account_id = p_company_bank_account_id
     and shared_company_id = p_shared_company_id
     and is_active
  returning true into changed;

  return jsonb_build_object('revoked', coalesce(changed, false));
end;
$$;


--
-- Name: revoke_company_invitation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_company_invitation(p_invitation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  invitation_company_id uuid;
  operation_id_value uuid;
begin
  select invitation.company_id, invitation.user_access_operation_id into invitation_company_id, operation_id_value
  from public.company_invitations invitation
  where invitation.id = p_invitation_id and invitation.status = 'pending';
  if invitation_company_id is null then raise exception 'Invitation was not found or is no longer pending' using errcode = '22023'; end if;
  if operation_id_value is not null then raise exception 'Use the billing-aware Users & Access removal workflow' using errcode = '42501'; end if;
  if not private.has_company_permission(invitation_company_id, 'users.manage') then raise exception 'You do not have permission to revoke this invitation' using errcode = '42501'; end if;
  update public.company_invitations set status = 'revoked', updated_at = now() where id = p_invitation_id;
  return jsonb_build_object('id', p_invitation_id, 'status', 'revoked');
end;
$$;


--
-- Name: revoke_pos_device(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_pos_device(p_company_id uuid, p_device_registration_id uuid, p_reason text) RETURNS public.device_registrations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare device_row public.device_registrations;
begin
  if not (select private.has_company_permission(p_company_id, 'pos.device.manage')) then
    raise exception 'Insufficient permission to revoke POS devices' using errcode = '42501';
  end if;
  if nullif(trim(p_reason), '') is null then
    raise exception 'A device revocation reason is required' using errcode = '23514';
  end if;
  select * into device_row
  from public.device_registrations
  where id = p_device_registration_id and company_id = p_company_id
  for update;
  if not found then
    raise exception 'POS device registration not found' using errcode = 'P0002';
  end if;
  perform set_config('app.offline_sync_workflow', 'authorized', true);
  update public.device_registrations
  set status = 'revoked', revoked_at = clock_timestamp(),
      revoked_by = (select auth.uid()), revoke_reason = trim(p_reason),
      updated_at = clock_timestamp(), updated_by = (select auth.uid())
  where id = device_row.id
  returning * into device_row;
  perform set_config('app.offline_sync_workflow', '', true);
  return device_row;
end
$$;


--
-- Name: employees; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.employees (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid,
    user_id uuid,
    first_name text NOT NULL,
    last_name text NOT NULL,
    email text,
    phone text,
    job_title text,
    department text,
    avatar_url text,
    role text DEFAULT 'employee'::text,
    status text DEFAULT 'active'::text,
    hire_date date DEFAULT CURRENT_DATE,
    base_salary numeric DEFAULT 0,
    currency text DEFAULT 'EUR'::text,
    permissions jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    employee_number text,
    personal_identification_reference text,
    employment_start_date date,
    employment_end_date date,
    branch_id uuid,
    cost_centre_id uuid,
    project_id uuid,
    payroll_group_code text,
    payroll_ready_status text DEFAULT 'requires_review'::text NOT NULL,
    CONSTRAINT employees_payroll_ready_status_check CHECK ((payroll_ready_status = ANY (ARRAY['ready'::text, 'requires_review'::text, 'excluded'::text])))
);


--
-- Name: save_employee_payroll_profile(uuid, text, uuid, uuid, uuid, text, numeric, numeric, numeric, date, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_employee_payroll_profile(p_employee_id uuid, p_employee_number text, p_branch_id uuid, p_cost_centre_id uuid, p_project_id uuid, p_salary_basis text, p_contracted_amount numeric, p_standard_hours numeric, p_standard_days numeric, p_effective_from date, p_tax_status text, p_pension_status text, p_iban text, p_bank_name text, p_reason text) RETURNS public.employees
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result public.employees;
begin
  select * into result from public.employees where id=p_employee_id for update;
  if not found then raise exception 'Employee not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(result.company_id,'payroll.compensation.manage')) then
    raise exception 'Insufficient permission' using errcode='42501';
  end if;
  if trim(coalesce(p_reason,''))='' or p_contracted_amount<0 then
    raise exception 'Reason and valid compensation are required' using errcode='23514';
  end if;
  if p_salary_basis not in ('gross-monthly','net-monthly','hourly','daily') then
    raise exception 'Unsupported salary basis' using errcode='23514';
  end if;
  if p_branch_id is null or trim(coalesce(p_employee_number,''))='' then
    raise exception 'Employee number and branch are required' using errcode='23514';
  end if;
  update public.employee_compensation_profiles
  set effective_until=p_effective_from-1,status='superseded',updated_at=now(),updated_by=(select auth.uid())
  where employee_id=result.id and status='approved'
    and effective_from<p_effective_from and (effective_until is null or effective_until>=p_effective_from);
  insert into public.employee_compensation_profiles(
    company_id,employee_id,salary_basis,amount,currency,standard_hours,standard_days,
    branch_id,cost_centre_id,project_id,effective_from,status,created_by,updated_by
  ) values (
    result.company_id,result.id,p_salary_basis,p_contracted_amount,'EUR',p_standard_hours,p_standard_days,
    p_branch_id,p_cost_centre_id,p_project_id,p_effective_from,'approved',(select auth.uid()),(select auth.uid())
  );
  insert into public.employee_tax_profiles(company_id,employee_id,tax_status,effective_from,created_by)
  values(result.company_id,result.id,coalesce(nullif(trim(p_tax_status),''),'standard'),p_effective_from,(select auth.uid()))
  on conflict (employee_id,effective_from) do update set tax_status=excluded.tax_status;
  insert into public.employee_pension_profiles(company_id,employee_id,pension_status,effective_from,created_by)
  values(result.company_id,result.id,coalesce(nullif(trim(p_pension_status),''),'standard'),p_effective_from,(select auth.uid()))
  on conflict (employee_id,effective_from) do update set pension_status=excluded.pension_status;
  if nullif(regexp_replace(coalesce(p_iban,''),'\s','','g'),'') is not null then
    update public.employee_bank_accounts set is_primary=false where employee_id=result.id;
    insert into public.employee_bank_accounts(company_id,employee_id,bank_name,iban,account_name,is_primary,created_by,updated_by)
    values(result.company_id,result.id,coalesce(nullif(trim(p_bank_name),''),'Bank'),upper(regexp_replace(p_iban,'\s','','g')),
      trim(coalesce(result.first_name,'')||' '||coalesce(result.last_name,'')),true,(select auth.uid()),(select auth.uid()))
    on conflict (company_id,iban) where iban is not null
    do update set bank_name=excluded.bank_name,is_primary=true,updated_at=now(),updated_by=(select auth.uid());
  end if;
  update public.employees set employee_number=trim(p_employee_number),branch_id=p_branch_id,cost_centre_id=p_cost_centre_id,
    project_id=p_project_id,payroll_ready_status='ready'
  where id=result.id returning * into result;
  perform private.record_payroll_audit(result.company_id,p_branch_id,'payroll.employee_profile.updated',
    'employee',result.id,null,jsonb_build_object('salaryBasis',p_salary_basis,'effectiveFrom',p_effective_from),p_reason);
  return result;
end $$;


--
-- Name: save_invoice_document(jsonb, jsonb, uuid, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_invoice_document(p_invoice jsonb, p_items jsonb, p_invoice_id uuid DEFAULT NULL::uuid, p_post_invoice boolean DEFAULT false, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target_company_id uuid;
  existing_invoice public.invoices;
  result public.invoices;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_invoice_id is not null then
    select * into existing_invoice from public.invoices where id = p_invoice_id;
    if not found then raise exception 'Invoice not found' using errcode = 'P0002'; end if;
    target_company_id := existing_invoice.company_id;
    if not private.rbac_can_read_resource(
      existing_invoice.company_id, 'invoice', existing_invoice.user_id,
      existing_invoice.assigned_user_id, 'invoice.edit'
    ) then
      raise exception 'Insufficient permission or data scope to edit this invoice' using errcode = '42501';
    end if;
  else
    target_company_id := nullif(p_invoice ->> 'company_id', '')::uuid;
    if not public.can_access_company(target_company_id)
       or not private.has_company_permission(target_company_id, 'invoice.create') then
      raise exception 'Insufficient permission to create invoices in this company' using errcode = '42501';
    end if;
    perform set_config('app.document_create_workflow', 'authorized', true);
  end if;
  if p_post_invoice and not private.rbac_can_read_resource(
    target_company_id, 'invoice',
    case when p_invoice_id is null then (select auth.uid()) else existing_invoice.user_id end,
    case when p_invoice_id is null then (select auth.uid()) else existing_invoice.assigned_user_id end,
    'invoice.issue'
  ) then
    raise exception 'Invoice issue permission and data scope are required to finalize an invoice' using errcode = '42501';
  end if;
  result := public.save_invoice_document_unchecked(p_invoice, p_items, p_invoice_id, p_post_invoice, p_idempotency_key);
  perform set_config('app.document_create_workflow', '', true);
  return result;
end;
$$;


--
-- Name: save_invoice_document_unchecked(jsonb, jsonb, uuid, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_invoice_document_unchecked(p_invoice jsonb, p_items jsonb, p_invoice_id uuid DEFAULT NULL::uuid, p_post_invoice boolean DEFAULT false, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  invoice_row public.invoices;
  existing_row public.invoices;
  client_row public.clients;
  product_row public.products;
  item_record record;
  calculated record;
  invoice_company_id uuid;
  invoice_user_id uuid;
  invoice_client_id uuid;
  invoice_document_type text;
  invoice_status text;
  invoice_accounting_state text;
  can_edit boolean;
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if jsonb_typeof(coalesce(p_invoice, '{}'::jsonb)) <> 'object' then
    raise exception 'Invoice payload must be an object' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(p_items, '[]'::jsonb)) = 0 then
    raise exception 'At least one invoice item is required' using errcode = '22023';
  end if;

  invoice_user_id := nullif(p_invoice ->> 'user_id', '')::uuid;
  invoice_company_id := nullif(p_invoice ->> 'company_id', '')::uuid;
  invoice_client_id := nullif(p_invoice ->> 'client_id', '')::uuid;
  invoice_document_type := upper(coalesce(nullif(trim(p_invoice ->> 'commercial_document_type'), ''), 'INVOICE'));
  invoice_status := lower(coalesce(nullif(trim(p_invoice ->> 'status'), ''), 'draft'));
  invoice_accounting_state := lower(coalesce(nullif(trim(p_invoice ->> 'accounting_state'), ''), 'legacy'));

  if invoice_user_id is distinct from actor_id then
    raise exception 'Invoice user does not match the signed-in user' using errcode = '42501';
  end if;
  if invoice_company_id is null or not public.can_access_company(invoice_company_id) then
    raise exception 'You do not have access to this company' using errcode = '42501';
  end if;
  if invoice_document_type not in (
    'QUOTE', 'PROFORMA', 'SALES_ORDER', 'DELIVERY_NOTE', 'INVOICE',
    'ADVANCE_INVOICE', 'FINAL_INVOICE', 'CREDIT_NOTE', 'DEBIT_NOTE',
    'SIMPLIFIED_INVOICE', 'FISCAL_RECEIPT', 'BAD_DEBT_INVOICE'
  ) then
    raise exception 'Unsupported commercial document type %', invoice_document_type using errcode = '22023';
  end if;
  if p_post_invoice and invoice_document_type <> 'INVOICE' then
    raise exception 'Only ordinary invoices can be posted by this command' using errcode = '22023';
  end if;
  if invoice_status not in ('draft', 'sent', 'approved') then
    raise exception 'Invoice must remain an editable draft before posting' using errcode = '55000';
  end if;

  if p_invoice_id is not null then
    select * into existing_row
    from public.invoices
    where id = p_invoice_id
    for update;
    if not found then
      raise exception 'Invoice not found' using errcode = 'P0002';
    end if;
    if (existing_row.company_id is not null and existing_row.company_id is distinct from invoice_company_id)
       or (existing_row.company_id is null and existing_row.user_id is distinct from actor_id) then
      raise exception 'Invoice belongs to another company' using errcode = '42501';
    end if;
    can_edit := coalesce(private.has_company_permission(invoice_company_id, 'sales_invoice.edit'), false);
    if not can_edit then
      raise exception 'Insufficient permission to edit sales invoices' using errcode = '42501';
    end if;
    if upper(coalesce(existing_row.commercial_status, existing_row.status::text, 'DRAFT')) not in ('DRAFT', 'SENT', 'VIEWED') then
      raise exception 'Issued documents cannot be edited; use a correction workflow' using errcode = '55000';
    end if;
  else
    if not (
      coalesce(private.has_company_permission(invoice_company_id, 'sales_invoice.create'), false)
      or coalesce(private.has_company_permission(invoice_company_id, 'invoice.create'), false)
    ) then
      raise exception 'Insufficient permission to create sales invoices' using errcode = '42501';
    end if;
    if p_idempotency_key is not null then
      select * into invoice_row
      from public.invoices
      where company_id = invoice_company_id
        and idempotency_key = p_idempotency_key
      for update;
      if found then return invoice_row; end if;
    end if;
  end if;

  if invoice_client_id is not null then
    select * into client_row
    from public.clients
    where id = invoice_client_id
      and (user_id = actor_id or public.can_access_company(company_id));
    if not found then
      raise exception 'The selected customer is not available in this company' using errcode = '22023';
    end if;
    if client_row.company_id is not null
       and not private.company_is_in_scope(invoice_company_id, client_row.company_id) then
      raise exception 'The selected customer belongs to another company' using errcode = '22023';
    end if;
  end if;

  -- Validate all lines before replacing anything. Related products must be
  -- visible to the same company scope as the invoice.
  for item_record in
    select * from jsonb_to_recordset(p_items) as item(
      product_id uuid,
      description text,
      quantity numeric,
      unit text,
      unit_price numeric,
      tax_rate numeric,
      discount numeric,
      tax_included boolean,
      sku text,
      amount numeric
    )
  loop
    if coalesce(item_record.quantity, 0) <= 0 then
      raise exception 'Invoice quantities must be greater than zero' using errcode = '22023';
    end if;
    if nullif(trim(coalesce(item_record.description, '')), '') is null then
      raise exception 'Every invoice line needs a description' using errcode = '22023';
    end if;
    if coalesce(item_record.unit_price, 0) < 0
       or coalesce(item_record.tax_rate, 0) < 0 or coalesce(item_record.tax_rate, 0) > 100
       or coalesce(item_record.discount, 0) < 0 or coalesce(item_record.discount, 0) > 100
       or coalesce(item_record.amount, 0) < 0 then
      raise exception 'Invoice contains an invalid price, VAT, discount, or amount' using errcode = '23514';
    end if;
    if item_record.product_id is not null then
      select * into product_row
      from public.products
      where id = item_record.product_id
        and (user_id = actor_id or public.can_access_company(company_id));
      if not found then
        raise exception 'One of the selected products is not available in this company' using errcode = '22023';
      end if;
      if product_row.company_id is not null
         and not private.company_is_in_scope(invoice_company_id, product_row.company_id) then
        raise exception 'A product belongs to another company subdivision' using errcode = '22023';
      end if;
    end if;
  end loop;

  if p_invoice_id is null then
    insert into public.invoices (
      user_id, company_id, client_id, invoice_number, issue_date, due_date,
      status, discount_amount, discount_percent, tax_amount, total_amount,
      notes, template_id, type, subtype, commercial_document_type,
      commercial_status, accounting_state, accounting_status, vat_status,
      inventory_status, payment_status, fiscalization_status, supply_date,
      order_date, delivery_date, source_document_type, source_document_id,
      original_invoice_id, tax_reporting_category, currency, exchange_rate,
      amount_received, payment_method, change_amount, paper_size,
      buyer_signature_url, customer_signature_requested,
      customer_signature_status, customer_signature_name, customer_signed_at,
      shipping_amount, transport_amount, additional_fee_amount, idempotency_key
      , shipping_tax_amount, transport_tax_amount, additional_fee_tax_amount
    ) values (
      actor_id, invoice_company_id, invoice_client_id, trim(p_invoice ->> 'invoice_number'),
      coalesce(nullif(p_invoice ->> 'issue_date', '')::date, current_date),
      nullif(p_invoice ->> 'due_date', '')::date,
      invoice_status::public.invoice_status,
      coalesce(nullif(p_invoice ->> 'discount_amount', '')::numeric, 0),
      coalesce(nullif(p_invoice ->> 'discount_percent', '')::numeric, 0),
      coalesce(nullif(p_invoice ->> 'tax_amount', '')::numeric, 0),
      coalesce(nullif(p_invoice ->> 'total_amount', '')::numeric, 0),
      nullif(p_invoice ->> 'notes', ''), coalesce(nullif(p_invoice ->> 'template_id', ''), 'corporate'),
      coalesce(nullif(p_invoice ->> 'type', ''), 'invoice'), coalesce(nullif(p_invoice ->> 'subtype', ''), 'regular'),
      invoice_document_type, upper(coalesce(nullif(p_invoice ->> 'commercial_status', ''), 'DRAFT')),
      case when invoice_document_type = 'INVOICE' then 'ready_for_posting' else invoice_accounting_state end,
      coalesce(nullif(p_invoice ->> 'accounting_status', ''), 'NOT_POSTED'),
      coalesce(nullif(p_invoice ->> 'vat_status', ''), 'NOT_EVALUATED'),
      coalesce(nullif(p_invoice ->> 'inventory_status', ''), 'NOT_APPLICABLE'),
      coalesce(nullif(p_invoice ->> 'payment_status', ''), 'UNPAID'),
      coalesce(nullif(p_invoice ->> 'fiscalization_status', ''), 'NOT_REQUIRED'),
      nullif(p_invoice ->> 'supply_date', '')::date, nullif(p_invoice ->> 'order_date', '')::date,
      nullif(p_invoice ->> 'delivery_date', '')::date, nullif(p_invoice ->> 'source_document_type', ''),
      nullif(p_invoice ->> 'source_document_id', '')::uuid, nullif(p_invoice ->> 'original_invoice_id', '')::uuid,
      nullif(p_invoice ->> 'tax_reporting_category', ''), upper(coalesce(nullif(p_invoice ->> 'currency', ''), 'EUR')),
      coalesce(nullif(p_invoice ->> 'exchange_rate', '')::numeric, 1),
      coalesce(nullif(p_invoice ->> 'amount_received', '')::numeric, 0), coalesce(nullif(p_invoice ->> 'payment_method', ''), 'bank'),
      coalesce(nullif(p_invoice ->> 'change_amount', '')::numeric, 0), coalesce(nullif(p_invoice ->> 'paper_size', ''), 'A4'),
      nullif(p_invoice ->> 'buyer_signature_url', ''), coalesce((p_invoice ->> 'customer_signature_requested')::boolean, false),
      coalesce(nullif(p_invoice ->> 'customer_signature_status', ''), 'not_requested'), nullif(p_invoice ->> 'customer_signature_name', ''),
      nullif(p_invoice ->> 'customer_signed_at', '')::timestamptz,
      coalesce(nullif(p_invoice ->> 'shipping_amount', '')::numeric, 0),
      coalesce(nullif(p_invoice ->> 'transport_amount', '')::numeric, 0),
      coalesce(nullif(p_invoice ->> 'additional_fee_amount', '')::numeric, 0),
      p_idempotency_key,
      coalesce(nullif(p_invoice ->> 'shipping_tax_amount', '')::numeric, 0),
      coalesce(nullif(p_invoice ->> 'transport_tax_amount', '')::numeric, 0),
      coalesce(nullif(p_invoice ->> 'additional_fee_tax_amount', '')::numeric, 0)
    ) returning * into invoice_row;
  else
    update public.invoices
    set client_id = invoice_client_id,
        invoice_number = trim(p_invoice ->> 'invoice_number'),
        issue_date = coalesce(nullif(p_invoice ->> 'issue_date', '')::date, issue_date),
        due_date = nullif(p_invoice ->> 'due_date', '')::date,
        status = invoice_status::public.invoice_status,
        discount_amount = coalesce(nullif(p_invoice ->> 'discount_amount', '')::numeric, 0),
        discount_percent = coalesce(nullif(p_invoice ->> 'discount_percent', '')::numeric, 0),
        notes = nullif(p_invoice ->> 'notes', ''),
        type = coalesce(nullif(p_invoice ->> 'type', ''), type),
        subtype = coalesce(nullif(p_invoice ->> 'subtype', ''), subtype),
        commercial_document_type = invoice_document_type,
        commercial_status = upper(coalesce(nullif(p_invoice ->> 'commercial_status', ''), commercial_status)),
        accounting_status = coalesce(nullif(p_invoice ->> 'accounting_status', ''), accounting_status),
        vat_status = coalesce(nullif(p_invoice ->> 'vat_status', ''), vat_status),
        inventory_status = coalesce(nullif(p_invoice ->> 'inventory_status', ''), inventory_status),
        payment_status = coalesce(nullif(p_invoice ->> 'payment_status', ''), payment_status),
        fiscalization_status = coalesce(nullif(p_invoice ->> 'fiscalization_status', ''), fiscalization_status),
        source_document_type = nullif(p_invoice ->> 'source_document_type', ''),
        source_document_id = nullif(p_invoice ->> 'source_document_id', '')::uuid,
        tax_reporting_category = nullif(p_invoice ->> 'tax_reporting_category', ''),
        currency = upper(coalesce(nullif(p_invoice ->> 'currency', ''), currency)),
        exchange_rate = coalesce(nullif(p_invoice ->> 'exchange_rate', '')::numeric, exchange_rate),
        amount_received = coalesce(nullif(p_invoice ->> 'amount_received', '')::numeric, 0),
        payment_method = coalesce(nullif(p_invoice ->> 'payment_method', ''), payment_method),
        change_amount = coalesce(nullif(p_invoice ->> 'change_amount', '')::numeric, 0),
        paper_size = coalesce(nullif(p_invoice ->> 'paper_size', ''), paper_size),
        buyer_signature_url = nullif(p_invoice ->> 'buyer_signature_url', ''),
        customer_signature_requested = coalesce((p_invoice ->> 'customer_signature_requested')::boolean, false),
        customer_signature_status = coalesce(nullif(p_invoice ->> 'customer_signature_status', ''), 'not_requested'),
        customer_signature_name = nullif(p_invoice ->> 'customer_signature_name', ''),
        customer_signed_at = nullif(p_invoice ->> 'customer_signed_at', '')::timestamptz,
        shipping_amount = coalesce(nullif(p_invoice ->> 'shipping_amount', '')::numeric, 0),
        shipping_tax_amount = coalesce(nullif(p_invoice ->> 'shipping_tax_amount', '')::numeric, 0),
        transport_amount = coalesce(nullif(p_invoice ->> 'transport_amount', '')::numeric, 0),
        transport_tax_amount = coalesce(nullif(p_invoice ->> 'transport_tax_amount', '')::numeric, 0),
        additional_fee_amount = coalesce(nullif(p_invoice ->> 'additional_fee_amount', '')::numeric, 0),
        additional_fee_tax_amount = coalesce(nullif(p_invoice ->> 'additional_fee_tax_amount', '')::numeric, 0)
    where id = p_invoice_id
    returning * into invoice_row;
  end if;

  delete from public.invoice_items where invoice_id = invoice_row.id;
  for item_record in
    select * from jsonb_to_recordset(p_items) as item(
      product_id uuid, description text, quantity numeric, unit text,
      unit_price numeric, tax_rate numeric, discount numeric,
      tax_included boolean, sku text, amount numeric
    )
  loop
    product_row := null;
    if item_record.product_id is not null then
      select * into product_row from public.products where id = item_record.product_id;
    end if;
    insert into public.invoice_items (
      invoice_id, product_id, description, quantity, unit, unit_price,
      tax_rate, discount, tax_included, sku, amount
    ) values (
      invoice_row.id, item_record.product_id,
      coalesce(nullif(trim(item_record.description), ''), product_row.name),
      item_record.quantity, coalesce(nullif(trim(item_record.unit), ''), product_row.unit, 'pcs'),
      coalesce(item_record.unit_price, product_row.unit_price, 0),
      coalesce(item_record.tax_rate, product_row.tax_rate, 0), coalesce(item_record.discount, 0),
      coalesce(item_record.tax_included, product_row.tax_included, false), coalesce(nullif(trim(item_record.sku), ''), product_row.sku, product_row.barcode, ''),
      -- Recalculate the persisted amount from the submitted primitives. The
      -- client-provided amount is only a preview and must never be trusted for
      -- an accounting record.
      round(
        case when coalesce(item_record.tax_included, product_row.tax_included, false)
          then (
            item_record.quantity * coalesce(item_record.unit_price, product_row.unit_price, 0)
              * (1 - coalesce(item_record.discount, 0) / 100)
          ) / (1 + coalesce(item_record.tax_rate, product_row.tax_rate, 0) / 100)
          else item_record.quantity * coalesce(item_record.unit_price, product_row.unit_price, 0)
            * (1 - coalesce(item_record.discount, 0) / 100)
        end,
        2
      )
    );
  end loop;

  select * into calculated from private.sales_invoice_amounts(invoice_row.id);
  update public.invoices
  set tax_amount = calculated.tax_amount,
      total_amount = calculated.gross_amount,
      discount_amount = coalesce(nullif(p_invoice ->> 'discount_amount', '')::numeric, discount_amount),
      discount_percent = coalesce(nullif(p_invoice ->> 'discount_percent', '')::numeric, discount_percent)
  where id = invoice_row.id
  returning * into invoice_row;

  if p_post_invoice then
    invoice_row := public.post_pos_invoice(invoice_row.id, p_idempotency_key, 'Shared invoice save');
  end if;
  return invoice_row;
end
$$;


--
-- Name: save_invoice_document_with_external_reference(jsonb, jsonb, uuid, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_invoice_document_with_external_reference(p_invoice jsonb, p_items jsonb, p_invoice_id uuid DEFAULT NULL::uuid, p_post_invoice boolean DEFAULT false, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  result public.invoices;
begin
  result := public.save_invoice_document(p_invoice, p_items, p_invoice_id, p_post_invoice, p_idempotency_key);
  if p_invoice ? 'external_reference' then
    update public.invoices
    set external_reference = nullif(trim(p_invoice ->> 'external_reference'), '')
    where id = result.id and company_id = result.company_id
    returning * into result;
    -- The live outbox trigger runs during the canonical insert. Keep its
    -- immutable event snapshot aligned with the final transaction result.
    if p_invoice_id is null then
      update public.api_webhook_events event_row
      set payload = jsonb_set(event_row.payload, '{data,object,external_reference}', to_jsonb(result.external_reference), true)
      where event_row.id = (
        select candidate.id
        from public.api_webhook_events candidate
        where candidate.company_id = result.company_id
          and candidate.environment = 'live'
          and candidate.event_type = 'invoice.created'
          and candidate.object_id = result.id
        order by candidate.created_at desc, candidate.id desc
        limit 1
      );
    end if;
  end if;
  return result;
end;
$$;


--
-- Name: save_invoice_document_with_stock(jsonb, jsonb, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_invoice_document_with_stock(p_invoice jsonb, p_items jsonb, p_idempotency_key uuid DEFAULT NULL::uuid, p_post_invoice boolean DEFAULT true) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  invoice_row public.invoices;
  product_row public.products;
  branch_stock public.product_branch_stock;
  item_record record;
  stock_before numeric;
  invoice_branch_id uuid := nullif(p_invoice ->> 'branch_id', '')::uuid;
begin
  if actor_id is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if not coalesce(p_post_invoice, true) then raise exception 'Stock checkout must post the invoice' using errcode = '22023'; end if;

  invoice_row := public.save_invoice_document(p_invoice, p_items, null, false, p_idempotency_key);

  if invoice_branch_id is not null then
    if not exists (select 1 from public.branches where id = invoice_branch_id and company_id = invoice_row.company_id and is_active) then
      raise exception 'The selected branch is not active in this company' using errcode = '22023';
    end if;
    update public.invoices set branch_id = invoice_branch_id where id = invoice_row.id returning * into invoice_row;
  end if;

  if lower(coalesce(invoice_row.accounting_state, '')) = 'posted'
     or exists (select 1 from public.inventory_stock_movements movement where movement.invoice_id = invoice_row.id and movement.movement_type = 'invoice_issue') then
    return invoice_row;
  end if;

  for item_record in
    select item.product_id, sum(item.quantity) as quantity
    from jsonb_to_recordset(coalesce(p_items, '[]'::jsonb)) as item(product_id uuid, quantity numeric)
    where item.product_id is not null
    group by item.product_id
  loop
    select * into product_row from public.products where id = item_record.product_id for update;
    if not found then raise exception 'One of the selected products no longer exists' using errcode = '22023'; end if;
    if product_row.company_id is not null and product_row.company_id <> invoice_row.company_id then
      raise exception 'A product belongs to another company subdivision' using errcode = '22023';
    end if;
    if coalesce(product_row.track_stock, false) then
      if invoice_branch_id is not null then
        select * into branch_stock
        from public.product_branch_stock
        where company_id = invoice_row.company_id and branch_id = invoice_branch_id and product_id = product_row.id
        for update;
        if not found then
          if exists (select 1 from public.product_branch_stock where company_id = invoice_row.company_id and product_id = product_row.id) then
            raise exception 'No stock is configured for "%" in the selected branch', product_row.name using errcode = '22003';
          end if;
          -- Legacy products with one global stock value remain sellable until
          -- their stock is distributed between branches explicitly.
          if coalesce(product_row.stock_quantity, 0) < item_record.quantity then
            raise exception 'Not enough stock for "%". Available: %, requested: %', product_row.name, product_row.stock_quantity, item_record.quantity using errcode = '22003';
          end if;
          stock_before := product_row.stock_quantity;
          update public.products set stock_quantity = stock_before - item_record.quantity where id = product_row.id;
        else
          if coalesce(branch_stock.stock_quantity, 0) < item_record.quantity then
            raise exception 'Not enough stock for "%" in the selected branch. Available: %, requested: %', product_row.name, branch_stock.stock_quantity, item_record.quantity using errcode = '22003';
          end if;
          stock_before := branch_stock.stock_quantity;
          update public.product_branch_stock set stock_quantity = stock_before - item_record.quantity, updated_by = actor_id, updated_at = now() where id = branch_stock.id;
          update public.products set stock_quantity = (select coalesce(sum(stock_quantity), 0) from public.product_branch_stock where company_id = invoice_row.company_id and product_id = product_row.id) where id = product_row.id;
        end if;
      else
        if coalesce(product_row.stock_quantity, 0) < item_record.quantity then
          raise exception 'Not enough stock for "%". Available: %, requested: %', product_row.name, product_row.stock_quantity, item_record.quantity using errcode = '22003';
        end if;
        stock_before := product_row.stock_quantity;
        update public.products set stock_quantity = stock_before - item_record.quantity where id = product_row.id;
      end if;
      insert into public.inventory_stock_movements(company_id, branch_id, product_id, invoice_id, movement_type, quantity_delta, stock_before, stock_after, created_by)
      values (invoice_row.company_id, invoice_branch_id, product_row.id, invoice_row.id, 'invoice_issue', -item_record.quantity, stock_before, stock_before - item_record.quantity, actor_id);
    end if;
  end loop;

  invoice_row := public.post_pos_invoice(invoice_row.id, p_idempotency_key, 'Shared branch stock invoice checkout');
  return invoice_row;
end
$$;


--
-- Name: payroll_run_employees; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_run_employees (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    payroll_run_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    compensation_profile_id uuid,
    tax_profile_id uuid,
    pension_profile_id uuid,
    branch_id uuid,
    department text,
    cost_centre_id uuid,
    project_id uuid,
    status text DEFAULT 'pending'::text NOT NULL,
    base_earnings numeric(20,4) DEFAULT 0 NOT NULL,
    additional_earnings numeric(20,4) DEFAULT 0 NOT NULL,
    taxable_earnings numeric(20,4) DEFAULT 0 NOT NULL,
    non_taxable_earnings numeric(20,4) DEFAULT 0 NOT NULL,
    gross_pay numeric(20,4) DEFAULT 0 NOT NULL,
    pensionable_base numeric(20,4) DEFAULT 0 NOT NULL,
    employee_pension numeric(20,4) DEFAULT 0 NOT NULL,
    employer_pension numeric(20,4) DEFAULT 0 NOT NULL,
    taxable_income numeric(20,4) DEFAULT 0 NOT NULL,
    personal_income_tax numeric(20,4) DEFAULT 0 NOT NULL,
    other_deductions numeric(20,4) DEFAULT 0 NOT NULL,
    net_salary numeric(20,4) DEFAULT 0 NOT NULL,
    employer_cost numeric(20,4) DEFAULT 0 NOT NULL,
    calculation_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    warnings jsonb DEFAULT '[]'::jsonb NOT NULL,
    errors jsonb DEFAULT '[]'::jsonb NOT NULL,
    calculated_at timestamp with time zone,
    finalized_at timestamp with time zone,
    CONSTRAINT payroll_run_employees_calculation_metadata_check CHECK ((jsonb_typeof(calculation_metadata) = 'object'::text)),
    CONSTRAINT payroll_run_employees_errors_check CHECK ((jsonb_typeof(errors) = 'array'::text)),
    CONSTRAINT payroll_run_employees_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'calculated'::text, 'warning'::text, 'error'::text, 'excluded'::text, 'finalized'::text, 'reversed'::text]))),
    CONSTRAINT payroll_run_employees_warnings_check CHECK ((jsonb_typeof(warnings) = 'array'::text))
);


--
-- Name: save_payroll_calculation(uuid, uuid, uuid, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_payroll_calculation(p_payroll_run_id uuid, p_employee_id uuid, p_compensation_profile_id uuid, p_tax_profile_id uuid, p_pension_profile_id uuid, p_result jsonb, p_lines jsonb) RETURNS public.payroll_run_employees
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare run_row public.payroll_runs; result public.payroll_run_employees; line jsonb; line_number integer:=0;
begin
  select * into run_row from public.payroll_runs where id=p_payroll_run_id for update;
  if not found then raise exception 'Payroll run not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(run_row.company_id,'payroll.run.calculate')) then
    raise exception 'Insufficient permission to calculate payroll' using errcode='42501';
  end if;
  if run_row.status not in ('draft','collecting_inputs','calculated','calculation_failed') then
    raise exception 'Payroll cannot be calculated in state %',run_row.status using errcode='55000';
  end if;
  if jsonb_array_length(coalesce(p_result->'errors','[]'::jsonb))>0 then
    raise exception 'Payroll result contains blocking errors' using errcode='23514';
  end if;
  insert into public.payroll_run_employees(
    company_id,payroll_run_id,employee_id,compensation_profile_id,tax_profile_id,pension_profile_id,
    branch_id,department,cost_centre_id,project_id,status,base_earnings,additional_earnings,
    taxable_earnings,non_taxable_earnings,gross_pay,pensionable_base,employee_pension,
    employer_pension,taxable_income,personal_income_tax,other_deductions,net_salary,employer_cost,
    calculation_metadata,warnings,errors,calculated_at
  )
  select
    run_row.company_id,p_payroll_run_id,p_employee_id,p_compensation_profile_id,p_tax_profile_id,p_pension_profile_id,
    employee.branch_id,employee.department,employee.cost_centre_id,employee.project_id,'calculated',
    (p_result->>'baseEarnings')::numeric,(p_result->>'additionalEarnings')::numeric,
    (p_result->>'taxableEarnings')::numeric,(p_result->>'nonTaxableEarnings')::numeric,
    (p_result->>'grossPay')::numeric,(p_result->>'pensionableBase')::numeric,
    (p_result->>'employeePension')::numeric,(p_result->>'employerPension')::numeric,
    (p_result->>'taxableIncome')::numeric,(p_result->>'personalIncomeTax')::numeric,
    (p_result->>'otherDeductions')::numeric,(p_result->>'netSalary')::numeric,
    (p_result->>'employerCost')::numeric,coalesce(p_result->'metadata','{}'::jsonb),
    coalesce(p_result->'warnings','[]'::jsonb),coalesce(p_result->'errors','[]'::jsonb),now()
  from public.employees employee
  where employee.id=p_employee_id and employee.company_id=run_row.company_id
  on conflict(payroll_run_id,employee_id) do update set
    compensation_profile_id=excluded.compensation_profile_id,tax_profile_id=excluded.tax_profile_id,
    pension_profile_id=excluded.pension_profile_id,status='calculated',
    base_earnings=excluded.base_earnings,additional_earnings=excluded.additional_earnings,
    taxable_earnings=excluded.taxable_earnings,non_taxable_earnings=excluded.non_taxable_earnings,
    gross_pay=excluded.gross_pay,pensionable_base=excluded.pensionable_base,
    employee_pension=excluded.employee_pension,employer_pension=excluded.employer_pension,
    taxable_income=excluded.taxable_income,personal_income_tax=excluded.personal_income_tax,
    other_deductions=excluded.other_deductions,net_salary=excluded.net_salary,
    employer_cost=excluded.employer_cost,calculation_metadata=excluded.calculation_metadata,
    warnings=excluded.warnings,errors=excluded.errors,calculated_at=now()
  returning * into result;
  if result.id is null then raise exception 'Employee does not belong to payroll company' using errcode='23514'; end if;
  delete from public.payroll_calculation_lines where payroll_run_employee_id=result.id;
  for line in select value from jsonb_array_elements(coalesce(p_lines,'[]'::jsonb)) loop
    line_number:=line_number+1;
    insert into public.payroll_calculation_lines(
      company_id,payroll_run_employee_id,line_number,kind,code,label,amount,taxable,pensionable,
      accounting_mapping_code,source_reference,metadata
    ) values (
      run_row.company_id,result.id,line_number,line->>'kind',line->>'code',line->>'label',
      (line->>'amount')::numeric,coalesce((line->>'taxable')::boolean,false),
      coalesce((line->>'pensionable')::boolean,false),line->>'accountingMappingCode',
      line->>'sourceReference',coalesce(line->'metadata','{}'::jsonb)
    );
  end loop;
  update public.payroll_runs set status='calculated',calculated_at=now(),updated_at=now(),updated_by=(select auth.uid())
  where id=p_payroll_run_id;
  return result;
end $$;


--
-- Name: save_payroll_configuration(uuid, text, date, date, text, text, integer, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_payroll_configuration(p_company_id uuid, p_name text, p_effective_from date, p_effective_until date, p_rule_source_reference text, p_rounding_mode text, p_money_scale integer, p_tax_brackets jsonb, p_pension_rule jsonb, p_reason text) RETURNS public.payroll_config_sets
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  result public.payroll_config_sets;
  next_version integer;
  bracket jsonb;
begin
  if not (select private.has_company_permission(p_company_id,'payroll.configuration.manage')) then
    raise exception 'Insufficient permission' using errcode='42501';
  end if;
  if trim(coalesce(p_reason,''))='' then
    raise exception 'Configuration reason is required' using errcode='23514';
  end if;
  if p_effective_until is not null and p_effective_until<p_effective_from then
    raise exception 'Effective date range is invalid' using errcode='22007';
  end if;
  if p_rounding_mode not in ('half-up','half-even','truncate') or p_money_scale not between 2 and 4 then
    raise exception 'Unsupported payroll rounding configuration' using errcode='23514';
  end if;
  if jsonb_typeof(p_tax_brackets)<>'array' or jsonb_array_length(p_tax_brackets)=0 then
    raise exception 'At least one reviewed tax bracket is required' using errcode='23514';
  end if;
  if coalesce((p_pension_rule->>'employeeRatePercent')::numeric,-1)<0
     or coalesce((p_pension_rule->>'employerRatePercent')::numeric,-1)<0 then
    raise exception 'Reviewed employee and employer pension rates are required' using errcode='23514';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':payroll-config',0));
  select coalesce(max(version),0)+1 into next_version
  from public.payroll_config_sets where company_id=p_company_id;

  insert into public.payroll_config_sets(
    company_id,code,name,version,effective_from,effective_until,status,rounding_mode,decimal_scale,
    rule_source_reference,created_by,updated_by
  ) values (
    p_company_id,'xk-payroll',trim(p_name),next_version,p_effective_from,p_effective_until,'draft',
    p_rounding_mode,p_money_scale,nullif(trim(coalesce(p_rule_source_reference,'')),''),
    (select auth.uid()),(select auth.uid())
  ) returning * into result;

  for bracket in select value from jsonb_array_elements(p_tax_brackets)
  loop
    insert into public.payroll_tax_brackets(
      company_id,config_set_id,bracket_order,lower_bound,upper_bound,rate_percent,fixed_amount
    ) values (
      p_company_id,result.id,coalesce((bracket->>'sequence')::integer,1),
      coalesce((bracket->>'lowerBound')::numeric,0),(bracket->>'upperBound')::numeric,
      coalesce((bracket->>'ratePercent')::numeric,0),coalesce((bracket->>'fixedAmount')::numeric,0)
    );
  end loop;

  insert into public.payroll_pension_rules(
    company_id,config_set_id,employee_rate_percent,employer_rate_percent,
    minimum_contribution_base,maximum_contribution_base
  ) values (
    p_company_id,result.id,(p_pension_rule->>'employeeRatePercent')::numeric,
    (p_pension_rule->>'employerRatePercent')::numeric,
    (p_pension_rule->>'minimumBase')::numeric,(p_pension_rule->>'maximumBase')::numeric
  );

  perform private.record_payroll_audit(p_company_id,null,'payroll.configuration.created',
    'payroll_config_set',result.id,null,to_jsonb(result),p_reason);
  return result;
end $$;


--
-- Name: payroll_posting_mappings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_posting_mappings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    mapping_code text NOT NULL,
    account_id uuid NOT NULL,
    side text NOT NULL,
    employee_category text,
    branch_id uuid,
    department text,
    cost_centre_id uuid,
    project_id uuid,
    effective_from date NOT NULL,
    effective_until date,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT payroll_posting_mappings_side_check CHECK ((side = ANY (ARRAY['debit'::text, 'credit'::text])))
);


--
-- Name: save_payroll_posting_mapping(uuid, text, uuid, uuid, uuid, uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_payroll_posting_mapping(p_company_id uuid, p_mapping_code text, p_account_id uuid, p_branch_id uuid, p_cost_centre_id uuid, p_project_id uuid, p_effective_from date, p_reason text) RETURNS public.payroll_posting_mappings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  result public.payroll_posting_mappings;
  normalized_code text := upper(trim(p_mapping_code));
  account_side text;
begin
  if not (select private.has_company_permission(p_company_id, 'payroll.configuration.manage')) then
    raise exception 'Insufficient permission' using errcode = '42501';
  end if;
  if trim(coalesce(p_reason, '')) = '' then
    raise exception 'Mapping reason is required' using errcode = '23514';
  end if;
  select case when normal_balance = 'debit' then 'debit' else 'credit' end
  into account_side
  from public.chart_of_accounts
  where id = p_account_id and company_id = p_company_id and active and posting_allowed;
  if account_side is null then
    raise exception 'Posting account is not available' using errcode = '23503';
  end if;

  select * into result
  from public.payroll_posting_mappings
  where company_id = p_company_id
    and mapping_code = normalized_code
    and effective_from = p_effective_from
    and branch_id is not distinct from p_branch_id
    and cost_centre_id is not distinct from p_cost_centre_id
    and project_id is not distinct from p_project_id
    and department is null
  order by created_at desc
  limit 1
  for update;

  if found then
    update public.payroll_posting_mappings
    set account_id = p_account_id, side = account_side, active = true
    where id = result.id
    returning * into result;
  else
    insert into public.payroll_posting_mappings(
      company_id, mapping_code, account_id, side, branch_id, cost_centre_id,
      project_id, effective_from, created_by
    ) values (
      p_company_id, normalized_code, p_account_id, account_side, p_branch_id,
      p_cost_centre_id, p_project_id, p_effective_from, (select auth.uid())
    ) returning * into result;
  end if;
  perform private.record_payroll_audit(
    p_company_id, p_branch_id, 'payroll.posting_mapping.saved',
    'payroll_posting_mapping', result.id, null, to_jsonb(result), p_reason
  );
  return result;
end
$$;


--
-- Name: accounting_periods; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.accounting_periods (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    fiscal_year_id uuid NOT NULL,
    period_number smallint NOT NULL,
    name text NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    closed_at timestamp with time zone,
    closed_by uuid,
    locked_at timestamp with time zone,
    locked_by uuid,
    reopened_at timestamp with time zone,
    reopened_by uuid,
    reopen_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT accounting_periods_check CHECK ((end_date >= start_date)),
    CONSTRAINT accounting_periods_period_number_check CHECK (((period_number >= 1) AND (period_number <= 53))),
    CONSTRAINT accounting_periods_status_check CHECK ((status = ANY (ARRAY['open'::text, 'soft_closed'::text, 'closed'::text, 'locked'::text])))
);


--
-- Name: set_accounting_period_status(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_accounting_period_status(p_period_id uuid, p_status text, p_reason text DEFAULT NULL::text) RETURNS public.accounting_periods
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  period_row public.accounting_periods;
  normalized_status text := lower(trim(coalesce(p_status, '')));
begin
  select * into period_row from public.accounting_periods where id = p_period_id for update;
  if not found then raise exception 'Accounting period not found' using errcode = 'P0002'; end if;
  if normalized_status not in ('open','closed','locked') then
    raise exception 'Invalid accounting period status' using errcode = '22023';
  end if;
  if normalized_status = 'open' and period_row.status in ('closed','locked') then
    if not private.has_company_permission(period_row.company_id, 'accounting_period.reopen') then
      raise exception 'Insufficient permission to reopen accounting periods' using errcode = '42501';
    end if;
    if trim(coalesce(p_reason, '')) = '' then
      raise exception 'A reason is required to reopen a period' using errcode = '23514';
    end if;
  elsif normalized_status <> period_row.status
     and not private.has_company_permission(period_row.company_id, 'accounting_period.close') then
    raise exception 'Insufficient permission to close accounting periods' using errcode = '42501';
  end if;
  perform set_config('app.accounting_period_workflow', 'authorized', true);
  perform set_config('app.change_reason', coalesce(nullif(trim(coalesce(p_reason, '')), ''), ''), true);
  update public.accounting_periods
  set status = normalized_status,
      closed_at = case when normalized_status = 'closed' then clock_timestamp() else closed_at end,
      closed_by = case when normalized_status = 'closed' then (select auth.uid()) else closed_by end,
      locked_at = case when normalized_status = 'locked' then clock_timestamp() else locked_at end,
      locked_by = case when normalized_status = 'locked' then (select auth.uid()) else locked_by end,
      reopened_at = case when normalized_status = 'open' and status <> 'open' then clock_timestamp() else reopened_at end,
      reopened_by = case when normalized_status = 'open' and status <> 'open' then (select auth.uid()) else reopened_by end,
      reopen_reason = case when normalized_status = 'open' and status <> 'open' then trim(p_reason) else reopen_reason end,
      updated_at = clock_timestamp(), updated_by = (select auth.uid())
  where id = p_period_id
  returning * into period_row;
  perform set_config('app.accounting_period_workflow', '', true);
  perform set_config('app.change_reason', '', true);
  return period_row;
end;
$$;


--
-- Name: set_active_company(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_active_company(p_company_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  current_user_id uuid := (select auth.uid());
begin
  if current_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if not private.company_is_active(p_company_id) then
    raise exception 'The organization is archived or unavailable' using errcode = '42501';
  end if;
  if not public.can_access_company(p_company_id) then
    raise exception 'You are not a member of this company or subdivision' using errcode = '42501';
  end if;
  perform set_config('app.active_company_switch', 'authorized', true);
  update public.profiles
  set active_company_id = p_company_id, updated_at = clock_timestamp()
  where id = current_user_id;
  perform set_config('app.active_company_switch', '', true);
  return p_company_id;
end;
$$;


--
-- Name: set_company_member_role(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_company_member_role(p_membership_id uuid, p_role_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return public.rbac_update_member_access(p_membership_id, p_role_code, '{}'::jsonb, '{}'::jsonb);
end;
$$;


--
-- Name: set_company_parent(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_company_parent(p_company_id uuid, p_parent_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  company_name_value text;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if p_company_id is null then
    raise exception 'Company is required' using errcode = '23514';
  end if;

  if not private.has_company_permission(p_company_id, 'company.manage') then
    raise exception 'You do not have permission to update this company'
      using errcode = '42501';
  end if;

  if p_parent_company_id is not null
     and not private.has_company_permission(p_parent_company_id, 'company.manage') then
    raise exception 'You do not have permission to use that parent company'
      using errcode = '42501';
  end if;

  if p_parent_company_id = p_company_id then
    raise exception 'A company cannot be its own subdivision parent'
      using errcode = '23514';
  end if;

  update public.companies
  set parent_company_id = p_parent_company_id,
      updated_at = now(),
      updated_by = (select auth.uid())
  where id = p_company_id
  returning company_name into company_name_value;

  if company_name_value is null then
    raise exception 'Company was not found' using errcode = '22023';
  end if;

  return jsonb_build_object(
    'id', p_company_id,
    'company_name', company_name_value,
    'parent_company_id', p_parent_company_id
  );
end;
$$;


--
-- Name: set_fund_opening_balance(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_fund_opening_balance(p_fund_account_id uuid, p_amount numeric, p_reason text DEFAULT NULL::text) RETURNS public.company_fund_accounts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  fund_row public.company_fund_accounts;
begin
  select * into fund_row
    from public.company_fund_accounts
   where id = p_fund_account_id and is_active
   for update;
  if not found then raise exception 'Fund account not found' using errcode = 'P0002'; end if;
  if not coalesce(private.has_company_permission(fund_row.company_id, 'cash_transaction.post'), false) then
    raise exception 'Insufficient permission to set a fund balance' using errcode = '42501';
  end if;
  if p_amount is null or p_amount < 0 then
    raise exception 'Opening balance must be zero or greater' using errcode = '23514';
  end if;
  update public.company_fund_accounts
     set opening_balance = round(p_amount, 4), updated_at = now(), updated_by = (select auth.uid())
   where id = fund_row.id
   returning * into fund_row;
  return fund_row;
end;
$$;


--
-- Name: company_fund_transactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.company_fund_transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    fund_account_id uuid NOT NULL,
    transaction_type text NOT NULL,
    signed_amount numeric(20,4) NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    transaction_date date DEFAULT CURRENT_DATE NOT NULL,
    description text,
    source_type text NOT NULL,
    source_id uuid NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    reversed_at timestamp with time zone,
    reversed_by uuid,
    source_company_id uuid NOT NULL,
    payment_method text,
    reference text,
    counterparty text,
    reconciliation_status text DEFAULT 'unreconciled'::text NOT NULL,
    transfer_id uuid,
    CONSTRAINT company_fund_transactions_company_match CHECK ((company_id IS NOT NULL)),
    CONSTRAINT company_fund_transactions_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT company_fund_transactions_reconciliation_status_check CHECK ((reconciliation_status = ANY (ARRAY['unreconciled'::text, 'reconciled'::text, 'ignored'::text]))),
    CONSTRAINT company_fund_transactions_signed_amount_check CHECK ((signed_amount <> (0)::numeric)),
    CONSTRAINT company_fund_transactions_status_check CHECK ((status = ANY (ARRAY['active'::text, 'reversed'::text]))),
    CONSTRAINT company_fund_transactions_transaction_type_check CHECK ((transaction_type = ANY (ARRAY['expense'::text, 'income'::text, 'transfer_in'::text, 'transfer_out'::text, 'adjustment'::text])))
);


--
-- Name: set_fund_transaction_reconciliation(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_fund_transaction_reconciliation(p_transaction_id uuid, p_status text, p_reason text DEFAULT NULL::text) RETURNS public.company_fund_transactions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare transaction_row public.company_fund_transactions; new_status text := lower(trim(coalesce(p_status,'')));
begin
  select tx.* into transaction_row from public.company_fund_transactions tx join public.company_fund_accounts fund on fund.id=tx.fund_account_id where tx.id=p_transaction_id and fund.is_active for update;
  if not found then raise exception 'Financial transaction not found' using errcode='P0002'; end if;
  if new_status not in ('unreconciled','reconciled','ignored') then raise exception 'Reconciliation status is invalid' using errcode='23514'; end if;
  if not private.has_company_permission(transaction_row.company_id,'bank.reconcile') then raise exception 'Insufficient permission to reconcile financial transactions' using errcode='42501'; end if;
  perform set_config('app.change_reason',coalesce(nullif(trim(p_reason),''),'Reconciliation status changed'),true);
  update public.company_fund_transactions set reconciliation_status=new_status where id=transaction_row.id returning * into transaction_row;
  perform set_config('app.change_reason','',true);
  return transaction_row;
end;
$$;


--
-- Name: set_invoice_delivery_details(uuid, text, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_invoice_delivery_details(p_invoice_id uuid, p_delivery_method text DEFAULT NULL::text, p_pickup_branch_id uuid DEFAULT NULL::uuid, p_delivery_details text DEFAULT NULL::text, p_post_cod boolean DEFAULT false) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  invoice_row public.invoices;
  branch_row public.branches;
  normalized_method text := nullif(lower(trim(coalesce(p_delivery_method, ''))), '');
  normalized_details text := nullif(trim(coalesce(p_delivery_details, '')), '');
  normalized_branch_id uuid := p_pickup_branch_id;
  normalized_post_cod boolean := coalesce(p_post_cod, false) and normalized_method = 'delivery';
begin
  if actor_id is null then
    raise exception 'Authentication is required' using errcode = '42501';
  end if;

  select * into invoice_row from public.invoices where id = p_invoice_id for update;
  if not found then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if invoice_row.company_id is null or not public.can_access_company(invoice_row.company_id) then
    raise exception 'Invoice belongs to another company' using errcode = '42501';
  end if;
  if not (
    coalesce(private.has_company_permission(invoice_row.company_id, 'sales_invoice.edit'), false)
    or (
      public.get_my_company_role(invoice_row.company_id) = 'employee'
      and invoice_row.user_id = actor_id
      and upper(coalesce(invoice_row.commercial_status, invoice_row.status::text, 'DRAFT')) = 'DRAFT'
    )
  ) then
    raise exception 'Insufficient permission to edit invoice details' using errcode = '42501';
  end if;
  if normalized_method is not null
     and normalized_method not in ('pickup', 'delivery', 'bus', 'other') then
    raise exception 'Unsupported delivery method' using errcode = '22023';
  end if;
  if normalized_branch_id is not null then
    select * into branch_row
      from public.branches
     where id = normalized_branch_id and company_id = invoice_row.company_id;
    if not found then
      raise exception 'Pickup store belongs to another company' using errcode = '42501';
    end if;
    if normalized_method = 'pickup' then
      normalized_details := nullif(trim(concat_ws(', ', branch_row.name, branch_row.registered_address, branch_row.municipality)), '');
    end if;
  end if;
  if normalized_method is distinct from 'pickup' then
    normalized_branch_id := null;
  end if;

  perform set_config('app.invoice_auxiliary_workflow', 'authorized', true);
  update public.invoices
     set delivery_method = normalized_method,
         pickup_branch_id = normalized_branch_id,
         delivery_details = normalized_details,
         post_cod = normalized_post_cod
   where id = p_invoice_id
   returning * into invoice_row;
  return invoice_row;
end;
$$;


--
-- Name: set_invoice_delivery_method(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_invoice_delivery_method(p_invoice_id uuid, p_delivery_method text DEFAULT NULL::text) RETURNS public.invoices
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.set_invoice_delivery_details(p_invoice_id, p_delivery_method, null, null);
$$;


--
-- Name: set_invoice_operating_branch(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_invoice_operating_branch(p_invoice_id uuid, p_branch_id uuid) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  invoice_row public.invoices;
begin
  select * into invoice_row from public.invoices where id = p_invoice_id for update;
  if not found then raise exception 'Invoice not found' using errcode = 'P0002'; end if;
  if not private.rbac_can_read_resource(invoice_row.company_id, 'invoice', invoice_row.user_id, invoice_row.assigned_user_id, 'invoice.edit')
     and not private.rbac_can_read_resource(invoice_row.company_id, 'invoice', invoice_row.user_id, invoice_row.assigned_user_id, 'invoice.create') then
    raise exception 'You do not have permission or data scope for this invoice' using errcode = '42501';
  end if;
  if p_branch_id is not null and not exists (
    select 1 from public.branches where id = p_branch_id and company_id = invoice_row.company_id and is_active
  ) then
    raise exception 'The selected branch is not active in this company' using errcode = '22023';
  end if;
  update public.invoices set branch_id = p_branch_id where id = p_invoice_id returning * into invoice_row;
  return invoice_row;
end;
$$;


--
-- Name: set_invoice_product_pictures(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_invoice_product_pictures(p_invoice_id uuid, p_show_product_pictures boolean) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  invoice_row public.invoices;
  allowed boolean;
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  select * into invoice_row from public.invoices where id = p_invoice_id for update;
  if not found then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  allowed := invoice_row.company_id is null and invoice_row.user_id = actor_id;
  if not allowed and invoice_row.company_id is not null then
    allowed := public.can_access_company(invoice_row.company_id)
      and (
        coalesce(private.has_company_permission(invoice_row.company_id, 'sales_invoice.edit'), false)
        or (
          public.get_my_company_role(invoice_row.company_id) = 'employee'
          and invoice_row.user_id = actor_id
          and upper(coalesce(invoice_row.commercial_status, invoice_row.status::text, 'DRAFT')) = 'DRAFT'
        )
      );
  end if;
  if not allowed then
    raise exception 'Insufficient permission to update invoice display settings' using errcode = '42501';
  end if;
  perform set_config('app.invoice_auxiliary_workflow', 'authorized', true);
  update public.invoices
  set show_product_pictures = coalesce(p_show_product_pictures, false)
  where id = p_invoice_id
  returning * into invoice_row;
  return invoice_row;
end;
$$;


--
-- Name: company_feature_flags; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.company_feature_flags (
    company_id uuid NOT NULL,
    flag text NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    configuration jsonb DEFAULT '{}'::jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT company_feature_flags_configuration_check CHECK ((jsonb_typeof(configuration) = 'object'::text))
);


--
-- Name: set_payroll_feature_flags(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_payroll_feature_flags(p_company_id uuid, p_enabled boolean, p_reason text) RETURNS SETOF public.company_feature_flags
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not (select private.has_company_permission(p_company_id,'company.manage')) then
    raise exception 'Insufficient permission' using errcode='42501';
  end if;
  if trim(coalesce(p_reason,''))='' then raise exception 'Feature-change reason is required' using errcode='23514'; end if;
  update public.company_feature_flags
  set enabled=p_enabled,updated_at=now(),updated_by=(select auth.uid())
  where company_id=p_company_id and flag='payroll_enabled';
  perform private.record_payroll_audit(p_company_id,null,'payroll.feature_flags.changed',
    'company',p_company_id,null,jsonb_build_object('enabled',p_enabled),p_reason);
  return query select * from public.company_feature_flags
    where company_id=p_company_id and flag='payroll_enabled';
end $$;


--
-- Name: company_user_preferences; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.company_user_preferences (
    user_id uuid NOT NULL,
    company_id uuid NOT NULL,
    preferred_branch_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: set_preferred_branch(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_preferred_branch(p_company_id uuid, p_branch_id uuid) RETURNS public.company_user_preferences
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  preference public.company_user_preferences;
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if not public.can_access_company(p_company_id) then
    raise exception 'You do not have access to this company' using errcode = '42501';
  end if;
  if p_branch_id is not null and not exists (
    select 1
    from public.branches
    where id = p_branch_id
      and company_id = p_company_id
      and is_active
  ) then
    raise exception 'The selected branch is not active in this company' using errcode = '22023';
  end if;

  insert into public.company_user_preferences(user_id, company_id, preferred_branch_id, updated_at)
  values (actor_id, p_company_id, p_branch_id, now())
  on conflict (user_id, company_id) do update
    set preferred_branch_id = excluded.preferred_branch_id,
        updated_at = now()
  returning * into preference;

  return preference;
end;
$$;


--
-- Name: product_branch_stock; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.product_branch_stock (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    branch_id uuid NOT NULL,
    product_id uuid NOT NULL,
    stock_quantity numeric(20,6) DEFAULT 0 NOT NULL,
    low_stock_threshold numeric(20,6) DEFAULT 5 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT product_branch_stock_low_stock_threshold_check CHECK ((low_stock_threshold >= (0)::numeric)),
    CONSTRAINT product_branch_stock_stock_quantity_check CHECK ((stock_quantity >= (0)::numeric))
);


--
-- Name: set_product_branch_stock(uuid, uuid, uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_product_branch_stock(p_company_id uuid, p_product_id uuid, p_branch_id uuid, p_stock_quantity numeric, p_low_stock_threshold numeric DEFAULT 5) RETURNS public.product_branch_stock
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  product_row public.products;
  branch_row public.branches;
  stock_row public.product_branch_stock;
begin
  if actor_id is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if p_stock_quantity is null or p_stock_quantity < 0 then raise exception 'Stock cannot be negative' using errcode = '22023'; end if;
  if p_low_stock_threshold is null or p_low_stock_threshold < 0 then raise exception 'Low stock threshold cannot be negative' using errcode = '22023'; end if;
  if not (private.has_company_permission(p_company_id, 'inventory.manage') or private.has_company_permission(p_company_id, 'products.manage')) then
    raise exception 'Insufficient permission to manage inventory' using errcode = '42501';
  end if;
  select * into branch_row from public.branches where id = p_branch_id and company_id = p_company_id and is_active for update;
  if not found then raise exception 'The selected branch is not active in this company' using errcode = '22023'; end if;
  select * into product_row from public.products where id = p_product_id and company_id = p_company_id for update;
  if not found then raise exception 'The selected product is not available in this company' using errcode = '22023'; end if;

  insert into public.product_branch_stock(company_id, branch_id, product_id, stock_quantity, low_stock_threshold, created_by, updated_by, updated_at)
  values (p_company_id, p_branch_id, p_product_id, p_stock_quantity, p_low_stock_threshold, actor_id, actor_id, now())
  on conflict (company_id, branch_id, product_id) do update
    set stock_quantity = excluded.stock_quantity,
        low_stock_threshold = excluded.low_stock_threshold,
        updated_by = actor_id,
        updated_at = now()
  returning * into stock_row;

  -- Keep the legacy total useful for existing reports and older clients.
  update public.products
  set stock_quantity = (
    select coalesce(sum(stock_quantity), 0)
    from public.product_branch_stock
    where company_id = p_company_id and product_id = p_product_id
  )
  where id = p_product_id;
  return stock_row;
end;
$$;


--
-- Name: share_company_bank_account(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.share_company_bank_account(p_company_bank_account_id uuid, p_shared_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  bank_row public.company_bank_accounts;
  target_name text;
  share_row public.company_bank_account_shares;
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  select * into bank_row
    from public.company_bank_accounts
   where id = p_company_bank_account_id and is_active
   for update;
  if not found then
    raise exception 'Bank account not found' using errcode = 'P0002';
  end if;
  if p_shared_company_id is null or p_shared_company_id = bank_row.company_id then
    raise exception 'Choose a different tenant to share the bank account with' using errcode = '23514';
  end if;
  if not private.has_company_permission(bank_row.company_id, 'company.manage')
     or not private.has_company_permission(p_shared_company_id, 'company.manage') then
    raise exception 'You do not have permission to share this bank account' using errcode = '42501';
  end if;

  select company_name into target_name
    from public.companies
   where id = p_shared_company_id;
  if target_name is null then
    raise exception 'Target tenant was not found' using errcode = 'P0002';
  end if;

  insert into public.company_bank_account_shares (
    company_bank_account_id, shared_company_id, is_active, created_by, updated_by
  ) values (
    bank_row.id, p_shared_company_id, true, actor_id, actor_id
  )
  on conflict (company_bank_account_id, shared_company_id) do update
    set is_active = true, updated_at = now(), updated_by = actor_id
  returning * into share_row;

  return jsonb_build_object(
    'id', share_row.id,
    'company_bank_account_id', share_row.company_bank_account_id,
    'shared_company_id', share_row.shared_company_id,
    'shared_company_name', target_name,
    'is_active', share_row.is_active
  );
end;
$$;


--
-- Name: submit_cashier_shift_count(uuid, uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_cashier_shift_count(p_company_id uuid, p_shift_id uuid, p_counted_cash numeric, p_notes text DEFAULT NULL::text, p_difference_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare shift_row public.cashier_shifts; difference_value numeric(20,4);
begin
  if not (select private.has_company_permission(p_company_id, 'pos.shift.close')) then raise exception 'Insufficient permission to close a cashier shift' using errcode='42501'; end if;
  select * into shift_row from public.cashier_shifts where id=p_shift_id and company_id=p_company_id for update;
  if not found or shift_row.status not in ('open','active','reopened') then raise exception 'Only an active cashier shift can be counted' using errcode='55000'; end if;
  if coalesce(p_counted_cash,-1) < 0 then raise exception 'Counted cash cannot be negative' using errcode='23514'; end if;
  difference_value := round(p_counted_cash-shift_row.expected_cash,4);
  if difference_value <> 0 and nullif(trim(p_difference_reason),'') is null then raise exception 'A reason is required for a cash difference' using errcode='23514'; end if;
  update public.cashier_shifts set status='closing',counted_cash=round(p_counted_cash,4),difference_amount=difference_value,closing_notes=nullif(trim(p_notes),''),difference_reason=nullif(trim(p_difference_reason),''),updated_at=clock_timestamp() where id=shift_row.id returning * into shift_row;
  insert into public.cashier_shift_movements (company_id,cashier_shift_id,terminal_id,movement_type,amount,source_type,reason,created_by) values (p_company_id,shift_row.id,shift_row.terminal_id,'closing_count',round(p_counted_cash,4),'cashier_shift',nullif(trim(p_notes),''),(select auth.uid()));
  insert into public.cashier_shift_events (company_id,cashier_shift_id,event_type,payload,actor_id) values (p_company_id,shift_row.id,'count_submitted',jsonb_build_object('counted_cash',p_counted_cash,'expected_cash',shift_row.expected_cash,'difference',difference_value),(select auth.uid()));
  return jsonb_build_object('shift_id',shift_row.id,'status',shift_row.status,'difference_amount',difference_value);
end $$;


--
-- Name: submit_offline_pos_sale(uuid, uuid, uuid, uuid, uuid, bigint, integer, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_offline_pos_sale(p_company_id uuid, p_batch_id uuid, p_device_registration_id uuid, p_client_item_id uuid, p_idempotency_key uuid, p_queue_sequence bigint, p_configuration_version integer, p_integrity_checksum text, p_canonical_payload text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  batch_row public.offline_sync_batches;
  device_row public.device_registrations;
  item_row public.offline_sync_items;
  expected_checksum text;
  result_value jsonb;
  order_id_value uuid;
  failure_state text;
begin
  if not (select private.has_company_permission(p_company_id, 'pos.offline.use')) then
    raise exception 'Insufficient permission to synchronize offline POS sales' using errcode = '42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Offline POS payload must be an object' using errcode = '23514';
  end if;
  if nullif(p_canonical_payload, '') is null
     or p_canonical_payload::jsonb <> p_payload then
    raise exception 'Canonical offline payload does not match the submitted payload'
      using errcode = '22000';
  end if;
  if not coalesce((
    select enabled from public.company_feature_flags
    where company_id = p_company_id and flag = 'offline_pos_enabled'
  ), false) then
    raise exception 'Offline POS is not enabled for this company' using errcode = '55000';
  end if;

  select * into device_row
  from public.device_registrations
  where id = p_device_registration_id and company_id = p_company_id
  for update;
  if not found or device_row.status <> 'active' then
    raise exception 'Device registration is revoked, suspended, or unavailable' using errcode = '42501';
  end if;
  if device_row.configuration_version <> p_configuration_version then
    raise exception 'POS configuration changed after this offline item was queued'
      using errcode = '40001';
  end if;

  select * into batch_row
  from public.offline_sync_batches
  where id = p_batch_id
    and company_id = p_company_id
    and device_registration_id = device_row.id
  for update;
  if not found or batch_row.status in ('completed','failed') then
    raise exception 'Offline synchronization batch is unavailable' using errcode = '55000';
  end if;

  expected_checksum := encode(
    extensions.digest(convert_to(p_canonical_payload, 'utf8'), 'sha256'),
    'hex'
  );
  if expected_checksum <> lower(trim(p_integrity_checksum)) then
    raise exception 'Offline queue integrity validation failed' using errcode = '22000';
  end if;

  insert into public.offline_sync_items (
    company_id, batch_id, device_registration_id, client_item_id,
    idempotency_key, queue_sequence, configuration_version,
    integrity_checksum, payload, status, original_occurred_at, created_by
  )
  values (
    p_company_id, batch_row.id, device_row.id, p_client_item_id,
    p_idempotency_key, p_queue_sequence, p_configuration_version,
    expected_checksum, p_payload, 'processing',
    coalesce(nullif(p_payload ->> 'occurred_at', '')::timestamptz, clock_timestamp()),
    (select auth.uid())
  )
  on conflict (company_id, device_registration_id, client_item_id) do nothing;

  select * into item_row
  from public.offline_sync_items
  where company_id = p_company_id
    and device_registration_id = device_row.id
    and client_item_id = p_client_item_id
  for update;

  if item_row.status = 'completed' then
    return item_row.result || jsonb_build_object('offline_sync_item_id', item_row.id, 'idempotent', true);
  end if;
  if item_row.idempotency_key <> p_idempotency_key
     or item_row.integrity_checksum <> expected_checksum then
    raise exception 'Offline item identity does not match its prior submission' using errcode = '23505';
  end if;

  perform set_config('app.offline_sync_workflow', 'authorized', true);
  update public.offline_sync_batches
  set status = 'processing', started_at = coalesce(started_at, clock_timestamp())
  where id = batch_row.id;
  perform set_config('app.offline_sync_workflow', '', true);

  begin
    result_value := public.complete_pos_sale(
      p_company_id,
      device_row.terminal_id,
      nullif(p_payload ->> 'customer_id', '')::uuid,
      p_payload -> 'items',
      p_payload -> 'payments',
      coalesce(nullif(p_payload ->> 'invoice_type', ''), 'invoice'),
      nullif(p_payload ->> 'notes', ''),
      p_idempotency_key,
      item_row.original_occurred_at
    );

    order_id_value := nullif(result_value ->> 'order_id', '')::uuid;
    perform set_config('app.pos_workflow', 'authorized', true);
    update public.pos_orders
    set source = 'offline_sync',
        metadata = metadata || jsonb_build_object(
          'offline_sync_item_id', item_row.id,
          'device_registration_id', device_row.id,
          'original_occurred_at', item_row.original_occurred_at
        ),
        updated_at = clock_timestamp(),
        updated_by = (select auth.uid())
    where id = order_id_value;
    perform set_config('app.pos_workflow', '', true);

    perform set_config('app.offline_sync_workflow', 'authorized', true);
    update public.offline_sync_items
    set status = 'completed', result = result_value,
        server_posted_at = clock_timestamp(), processed_at = clock_timestamp()
    where id = item_row.id;
    perform set_config('app.offline_sync_workflow', '', true);
  exception when others then
    failure_state := case
      when sqlstate in ('40001','23505') then 'conflict'
      when sqlstate in ('42501','23514','55000') then 'rejected'
      else 'failed'
    end;
    perform set_config('app.offline_sync_workflow', 'authorized', true);
    update public.offline_sync_items
    set status = failure_state,
        conflict_type = case when failure_state = 'conflict' then sqlstate end,
        error_code = sqlstate, error_message = sqlerrm,
        processed_at = clock_timestamp()
    where id = item_row.id;
    perform set_config('app.offline_sync_workflow', '', true);
    result_value := jsonb_build_object(
      'offline_sync_item_id', item_row.id,
      'status', failure_state,
      'error_code', sqlstate,
      'error_message', sqlerrm
    );
  end;

  perform set_config('app.offline_sync_workflow', 'authorized', true);
  update public.device_registrations
  set last_seen_at = clock_timestamp(),
      sync_cursor = greatest(sync_cursor, p_queue_sequence),
      updated_at = clock_timestamp(), updated_by = (select auth.uid())
  where id = device_row.id;
  update public.offline_sync_batches batch
  set item_count = aggregate.item_count,
      completed_count = aggregate.completed_count,
      conflict_count = aggregate.conflict_count,
      failed_count = aggregate.failed_count,
      status = case
        when aggregate.open_count > 0 then 'processing'
        when aggregate.failed_count > 0 or aggregate.conflict_count > 0 then 'partially_completed'
        else 'completed'
      end,
      completed_at = case when aggregate.open_count = 0 then clock_timestamp() end
  from (
    select count(*)::integer item_count,
      count(*) filter (where status = 'completed')::integer completed_count,
      count(*) filter (where status = 'conflict')::integer conflict_count,
      count(*) filter (where status in ('failed','rejected'))::integer failed_count,
      count(*) filter (where status in ('queued','processing'))::integer open_count
    from public.offline_sync_items
    where batch_id = batch_row.id
  ) aggregate
  where batch.id = batch_row.id;
  perform set_config('app.offline_sync_workflow', '', true);

  return coalesce(result_value, '{}'::jsonb)
    || jsonb_build_object('offline_sync_item_id', item_row.id);
end
$$;


--
-- Name: submit_payroll_for_review(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_payroll_for_review(p_payroll_run_id uuid) RETURNS public.payroll_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result public.payroll_runs;
begin
  select * into result from public.payroll_runs where id=p_payroll_run_id for update;
  if not found then raise exception 'Payroll run not found' using errcode='P0002'; end if;
  if not (select private.has_company_permission(result.company_id,'payroll.run.review')) then raise exception 'Insufficient permission' using errcode='42501'; end if;
  if result.status<>'calculated' then raise exception 'Only calculated payroll may be reviewed' using errcode='55000'; end if;
  if exists(select 1 from public.payroll_run_employees where payroll_run_id=result.id and status='error') then
    raise exception 'Payroll contains blocking employee errors' using errcode='23514';
  end if;
  update public.payroll_runs set status='under_review',updated_at=now(),updated_by=(select auth.uid())
  where id=result.id returning * into result;
  return result;
end $$;


--
-- Name: sync_stripe_ledger_entry(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_stripe_ledger_entry(p_stripe_transaction_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  transaction_row public.stripe_transactions;
  store_row public.stripe_stores;
  fund_id uuid;
  existing_row public.company_fund_transactions;
  net_amount numeric(20,4);
begin
  select * into transaction_row
  from public.stripe_transactions
  where id = p_stripe_transaction_id
  for update;
  if not found then
    raise exception 'Stripe transaction not found' using errcode = 'P0002';
  end if;
  if transaction_row.stripe_store_id is null then
    return jsonb_build_object('synced', false, 'reason', 'store_missing');
  end if;

  select * into store_row from public.stripe_stores where id = transaction_row.stripe_store_id;
  if not found then
    raise exception 'Stripe store not found' using errcode = 'P0002';
  end if;
  net_amount := round(coalesce(transaction_row.net, 0), 4);
  if net_amount = 0 then
    return jsonb_build_object('synced', false, 'reason', 'zero_net');
  end if;

  fund_id := private.ensure_stripe_fund_account(
    store_row.id,
    upper(coalesce(nullif(transaction_row.currency, ''), 'EUR'))
  );

  select * into existing_row
  from public.company_fund_transactions
  where source_type = 'stripe_balance_transaction'
    and source_id = transaction_row.id
    and status = 'active'
  for update;

  if found
     and existing_row.fund_account_id = fund_id
     and existing_row.signed_amount = net_amount then
    return jsonb_build_object('synced', true, 'created', false, 'fund_account_id', fund_id);
  end if;

  if found then
    update public.company_fund_transactions
    set status = 'reversed', reversed_at = clock_timestamp()
    where id = existing_row.id;
  end if;

  insert into public.company_fund_transactions (
    company_id, source_company_id, fund_account_id, transaction_type,
    signed_amount, currency, transaction_date, description,
    source_type, source_id, status
  ) values (
    store_row.company_id, store_row.company_id, fund_id,
    case when net_amount > 0 then 'income' else 'expense' end,
    net_amount,
    upper(coalesce(nullif(transaction_row.currency, ''), 'EUR')),
    coalesce(transaction_row.created_at::date, current_date),
    'Stripe · ' || coalesce(nullif(transaction_row.description, ''), transaction_row.type) || ' · ' || transaction_row.stripe_id,
    'stripe_balance_transaction', transaction_row.id, 'active'
  );

  return jsonb_build_object('synced', true, 'created', true, 'fund_account_id', fund_id);
end;
$$;


--
-- Name: transfer_product_branch_stock(uuid, uuid, uuid, uuid, numeric, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_product_branch_stock(p_company_id uuid, p_product_id uuid, p_from_branch_id uuid, p_to_branch_id uuid, p_quantity numeric, p_transfer_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  transfer_id uuid := coalesce(p_transfer_id, public.gen_random_uuid());
  product_row public.products;
  source_stock public.product_branch_stock;
  destination_stock public.product_branch_stock;
  source_before numeric;
  destination_before numeric;
  source_after numeric;
  destination_after numeric;
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_quantity is null or p_quantity <= 0 then
    raise exception 'Transfer quantity must be greater than zero' using errcode = '22023';
  end if;
  if p_from_branch_id is null or p_to_branch_id is null or p_from_branch_id = p_to_branch_id then
    raise exception 'Select two different branches' using errcode = '22023';
  end if;
  if not (private.has_company_permission(p_company_id, 'inventory.manage') or private.has_company_permission(p_company_id, 'products.manage')) then
    raise exception 'Insufficient permission to manage inventory' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.branches
    where id = p_from_branch_id and company_id = p_company_id and is_active
  ) or not exists (
    select 1 from public.branches
    where id = p_to_branch_id and company_id = p_company_id and is_active
  ) then
    raise exception 'Both branches must be active in this company' using errcode = '22023';
  end if;

  -- Lock the product first so concurrent transfers for the same product are serialized.
  select * into product_row
  from public.products
  where id = p_product_id and company_id = p_company_id
  for update;
  if not found then
    raise exception 'The selected product is not available in this company' using errcode = '22023';
  end if;

  select * into source_stock
  from public.product_branch_stock
  where company_id = p_company_id and branch_id = p_from_branch_id and product_id = p_product_id
  for update;
  if not found then
    raise exception 'The source branch has no stock configured for "%"', product_row.name using errcode = '22003';
  end if;
  source_before := source_stock.stock_quantity;
  if source_before < p_quantity then
    raise exception 'Not enough stock in the source branch for "%". Available: %, requested: %', product_row.name, source_before, p_quantity using errcode = '22003';
  end if;

  select * into destination_stock
  from public.product_branch_stock
  where company_id = p_company_id and branch_id = p_to_branch_id and product_id = p_product_id
  for update;
  if not found then
    insert into public.product_branch_stock(
      company_id, branch_id, product_id, stock_quantity, low_stock_threshold, created_by, updated_by, updated_at
    ) values (
      p_company_id, p_to_branch_id, p_product_id, 0, source_stock.low_stock_threshold, actor_id, actor_id, now()
    ) returning * into destination_stock;
  end if;
  destination_before := destination_stock.stock_quantity;
  source_after := source_before - p_quantity;
  destination_after := destination_before + p_quantity;

  update public.product_branch_stock
  set stock_quantity = source_after, updated_by = actor_id, updated_at = now()
  where id = source_stock.id;
  update public.product_branch_stock
  set stock_quantity = destination_after, updated_by = actor_id, updated_at = now()
  where id = destination_stock.id;

  update public.products
  set stock_quantity = (
    select coalesce(sum(stock_quantity), 0)
    from public.product_branch_stock
    where company_id = p_company_id and product_id = p_product_id
  )
  where id = p_product_id;

  insert into public.inventory_stock_movements(
    company_id, branch_id, product_id, movement_type, quantity_delta,
    stock_before, stock_after, created_by, product_name, transfer_id, note
  ) values
    (p_company_id, p_from_branch_id, p_product_id, 'transfer', -p_quantity, source_before, source_after, actor_id, product_row.name, transfer_id, nullif(trim(coalesce(p_note, '')), '')),
    (p_company_id, p_to_branch_id, p_product_id, 'transfer', p_quantity, destination_before, destination_after, actor_id, product_row.name, transfer_id, nullif(trim(coalesce(p_note, '')), ''));

  return jsonb_build_object(
    'transfer_id', transfer_id,
    'product_id', p_product_id,
    'from_branch_id', p_from_branch_id,
    'to_branch_id', p_to_branch_id,
    'quantity', p_quantity,
    'source_stock', source_after,
    'destination_stock', destination_after,
    'note', nullif(trim(coalesce(p_note, '')), '')
  );
end;
$$;


--
-- Name: transition_commercial_document(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_commercial_document(p_document_id uuid, p_status text, p_event_type text DEFAULT NULL::text) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  invoice_row public.invoices;
  next_status text := upper(trim(coalesce(p_status, '')));
  previous_status text;
  permission_code text;
  server_request boolean := coalesce((select auth.jwt() ->> 'role'), '') = 'service_role';
begin
  select * into invoice_row from public.invoices where id = p_document_id for update;
  if not found then raise exception 'Commercial document not found' using errcode = 'P0002'; end if;
  if next_status = '' then raise exception 'A document status is required' using errcode = '22023'; end if;
  if next_status not in (
    'DRAFT','SENT','VIEWED','ISSUED','CONFIRMED','PREPARED','DELIVERED','ACCEPTED',
    'OVERDUE','CANCELLED','VOID','VOIDED','REVERSED','PAID','PARTIALLY_PAID',
    'CREDITED','PARTIALLY_CREDITED','CORRECTED'
  ) then
    raise exception 'Unsupported commercial document status' using errcode = '22023';
  end if;
  if not server_request and not private.rbac_is_platform_admin() then
    if next_status in ('PAID','PARTIALLY_PAID','CREDITED','PARTIALLY_CREDITED','CORRECTED') then
      raise exception 'Paid and correction states must use the supported financial workflow' using errcode = '55000';
    end if;
    permission_code := case
      when next_status in ('ISSUED') then 'invoice.issue'
      when next_status in ('CANCELLED','VOID','VOIDED','REVERSED') then 'invoice.void'
      else 'invoice.edit'
    end;
    if not private.rbac_can_read_resource(
      invoice_row.company_id, 'invoice', invoice_row.user_id,
      invoice_row.assigned_user_id, permission_code
    ) then
      raise exception 'Insufficient permission or data scope to transition this document' using errcode = '42501';
    end if;
    if invoice_row.accounting_state in ('posted','reversed') and next_status <> 'OVERDUE' then
      raise exception 'Posted financial documents must be corrected through a supported workflow' using errcode = '55000';
    end if;
  end if;
  previous_status := invoice_row.commercial_status;
  update public.invoices
  set commercial_status = next_status,
      status = case next_status
        when 'DRAFT' then 'draft'::public.invoice_status
        when 'SENT' then 'sent'::public.invoice_status
        when 'ISSUED' then 'sent'::public.invoice_status
        when 'VIEWED' then 'sent'::public.invoice_status
        when 'OVERDUE' then 'overdue'::public.invoice_status
        when 'CANCELLED' then 'cancelled'::public.invoice_status
        when 'VOID' then 'cancelled'::public.invoice_status
        when 'VOIDED' then 'cancelled'::public.invoice_status
        when 'REVERSED' then 'reversed'::public.invoice_status
        else status
      end,
      issued_at = case when next_status = 'ISSUED' then coalesce(issued_at, clock_timestamp()) else issued_at end,
      issued_by = case when next_status = 'ISSUED' then coalesce(issued_by, (select auth.uid())) else issued_by end,
      immutable_at = case when next_status = 'ISSUED' then coalesce(immutable_at, clock_timestamp()) else immutable_at end
  where id = invoice_row.id
  returning * into invoice_row;
  perform private.insert_commercial_document_event(
    invoice_row.company_id, invoice_row.id,
    coalesce(nullif(trim(p_event_type), ''), lower(next_status)),
    previous_status, next_status, '{}'::jsonb, clock_timestamp(), (select auth.uid())
  );
  return invoice_row;
end;
$$;


--
-- Name: unallocate_customer_payment(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unallocate_customer_payment(p_allocation_id uuid, p_reason text) RETURNS public.payment_allocations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  allocation_row public.payment_allocations;
begin
  if nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'A reason is required to unallocate a customer payment' using errcode = '22023';
  end if;

  select * into allocation_row
  from public.payment_allocations
  where id = p_allocation_id
  for update;
  if not found then
    raise exception 'Payment allocation not found' using errcode = 'P0002';
  end if;
  if not (select private.has_company_permission(allocation_row.company_id, 'customer_payment.allocate')) then
    raise exception 'Insufficient permission to unallocate customer payments' using errcode = '42501';
  end if;
  if allocation_row.status <> 'active' then
    raise exception 'Only active allocations can be unallocated' using errcode = '55000';
  end if;

  update public.payment_allocations
  set status = 'reversed',
      reversed_at = clock_timestamp(),
      reversed_by = (select auth.uid()),
      reversal_reason = p_reason
  where id = allocation_row.id
  returning * into allocation_row;

  perform private.refresh_customer_payment_state(allocation_row.invoice_id);
  perform private.refresh_customer_payment_allocation_state(allocation_row.payment_id);
  perform private.emit_domain_outbox_event(
    allocation_row.company_id, allocation_row.branch_id, 'customer_payment', allocation_row.payment_id,
    'customer_payment.unallocated',
    jsonb_build_object('invoice_id', allocation_row.invoice_id, 'allocation_id', allocation_row.id, 'reason', p_reason),
    'customer_payment.unallocated:' || allocation_row.id::text
  );
  return allocation_row;
end
$$;


--
-- Name: update_company_profile(uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_company_profile(p_company_id uuid, p_company_name text, p_email text, p_phone text, p_address text, p_website text, p_tax_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  updated_company public.companies%rowtype;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if p_company_id is null then
    raise exception 'Company is required' using errcode = '23514';
  end if;

  if nullif(trim(p_company_name), '') is null then
    raise exception 'Company name is required' using errcode = '23514';
  end if;

  if not private.has_company_permission(p_company_id, 'company.manage') then
    raise exception 'You do not have permission to edit this company'
      using errcode = '42501';
  end if;

  update public.companies
  set company_name = trim(p_company_name),
      email = nullif(trim(p_email), ''),
      phone = nullif(trim(p_phone), ''),
      address = nullif(trim(p_address), ''),
      website = nullif(trim(p_website), ''),
      tax_id = nullif(trim(p_tax_id), ''),
      updated_at = now(),
      updated_by = (select auth.uid())
  where id = p_company_id
  returning * into updated_company;

  if updated_company.id is null then
    raise exception 'Company was not found' using errcode = '22023';
  end if;

  return jsonb_build_object(
    'id', updated_company.id,
    'company_name', updated_company.company_name,
    'email', updated_company.email,
    'phone', updated_company.phone,
    'address', updated_company.address,
    'website', updated_company.website,
    'tax_id', updated_company.tax_id,
    'parent_company_id', updated_company.parent_company_id
  );
end;
$$;


--
-- Name: update_customer_payment(uuid, uuid, uuid, uuid, date, numeric, text, uuid, text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_customer_payment(p_payment_id uuid, p_company_id uuid, p_customer_id uuid, p_invoice_id uuid DEFAULT NULL::uuid, p_payment_date date DEFAULT CURRENT_DATE, p_amount numeric DEFAULT 0, p_payment_method text DEFAULT 'bank'::text, p_settlement_account_id uuid DEFAULT NULL::uuid, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_currency text DEFAULT 'EUR'::text, p_idempotency_key uuid DEFAULT NULL::uuid, p_reason text DEFAULT 'Customer payment edited'::text) RETURNS public.payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  old_payment public.payments;
  new_payment public.payments;
  actor_id uuid := (select auth.uid());
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_company_id is null or p_amount is null or round(p_amount, 4) <= 0 then
    raise exception 'A company and positive payment amount are required' using errcode = '23514';
  end if;
  if p_idempotency_key is not null then
    select * into new_payment
    from public.payments
    where company_id = p_company_id
      and idempotency_key = p_idempotency_key
    for update;
    if found then return new_payment; end if;
  end if;

  select * into old_payment
  from public.payments
  where id = p_payment_id
  for update;
  if not found or old_payment.company_id is distinct from p_company_id then
    raise exception 'Customer payment is not available in this company' using errcode = '42501';
  end if;
  if not coalesce(private.has_company_permission(p_company_id, 'customer_payment.record'), false) then
    raise exception 'Insufficient permission to edit customer payments' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.clients customer
    where customer.id = p_customer_id
      and customer.company_id = p_company_id
  ) then
    raise exception 'Customer is invalid for this company' using errcode = '23514';
  end if;

  if old_payment.accounting_state = 'posted' then
    perform public.reverse_customer_payment(
      old_payment.id,
      coalesce(p_payment_date, current_date),
      coalesce(nullif(trim(p_reason), ''), 'Customer payment edited')
    );
    new_payment := public.record_customer_payment(
      p_company_id,
      p_customer_id,
      coalesce(p_payment_date, current_date),
      round(p_amount, 4),
      p_payment_method,
      p_settlement_account_id,
      p_reference,
      p_notes,
      old_payment.branch_id,
      upper(coalesce(p_currency, old_payment.currency, 'EUR')),
      p_idempotency_key
    );
    if p_invoice_id is not null then
      perform public.allocate_customer_payment(
        new_payment.id,
        p_invoice_id,
        round(p_amount, 4),
        coalesce(p_payment_date, current_date)
      );
      update public.payments
      set invoice_id = p_invoice_id
      where id = new_payment.id
      returning * into new_payment;
    end if;
    return new_payment;
  end if;

  if old_payment.accounting_state in ('reversed', 'opening_balance', 'excluded') then
    raise exception 'This customer payment cannot be edited' using errcode = '55000';
  end if;
  update public.payments
  set client_id = p_customer_id,
      invoice_id = p_invoice_id,
      payment_date = coalesce(p_payment_date, payment_date),
      amount = round(p_amount, 4),
      payment_method = nullif(trim(p_payment_method), ''),
      bank_reference = nullif(trim(p_reference), ''),
      notes = p_notes,
      currency = upper(coalesce(p_currency, currency, 'EUR')),
      settlement_account_id = coalesce(p_settlement_account_id, settlement_account_id)
  where id = old_payment.id
  returning * into new_payment;
  return new_payment;
end
$$;


--
-- Name: update_customer_payment_with_bank_account(uuid, uuid, uuid, uuid, date, numeric, text, uuid, text, text, text, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_customer_payment_with_bank_account(p_payment_id uuid, p_company_id uuid, p_customer_id uuid, p_invoice_id uuid DEFAULT NULL::uuid, p_payment_date date DEFAULT CURRENT_DATE, p_amount numeric DEFAULT 0, p_payment_method text DEFAULT 'bank'::text, p_settlement_account_id uuid DEFAULT NULL::uuid, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_currency text DEFAULT 'EUR'::text, p_idempotency_key uuid DEFAULT NULL::uuid, p_reason text DEFAULT 'Customer payment edited'::text, p_company_bank_account_id uuid DEFAULT NULL::uuid) RETURNS public.payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payment_row public.payments;
begin
  if p_company_bank_account_id is not null then
    if lower(coalesce(p_payment_method, 'cash')) <> 'bank'
       or not exists (
         select 1 from public.company_bank_accounts account
          where account.id = p_company_bank_account_id
            and account.is_active
            and (
              account.company_id = p_company_id
              or exists (
                select 1 from public.company_bank_account_shares share
                 where share.company_bank_account_id = account.id
                   and share.shared_company_id = p_company_id
                   and share.is_active
              )
            )
       ) then
      raise exception 'The selected bank account is not available for this payment' using errcode = '23503';
    end if;
  end if;

  payment_row := public.update_customer_payment(
    p_payment_id, p_company_id, p_customer_id, p_invoice_id, p_payment_date,
    p_amount, p_payment_method, p_settlement_account_id, p_reference, p_notes,
    p_currency, p_idempotency_key, p_reason
  );

  perform set_config('app.financial_workflow', 'authorized', true);
  update public.payments
     set company_bank_account_id = p_company_bank_account_id
   where id = payment_row.id
   returning * into payment_row;
  perform set_config('app.financial_workflow', '', true);
  return payment_row;
end;
$$;


--
-- Name: update_financial_account(uuid, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_financial_account(p_fund_account_id uuid, p_name text, p_notes text DEFAULT NULL::text, p_is_active boolean DEFAULT true, p_reason text DEFAULT NULL::text) RETURNS public.company_fund_accounts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare account_row public.company_fund_accounts;
begin
  select * into account_row from public.company_fund_accounts where id=p_fund_account_id for update;
  if not found then raise exception 'Financial account not found' using errcode='P0002'; end if;
  if not private.has_company_permission(account_row.company_id,'cash_account.manage') then raise exception 'Insufficient permission to manage financial accounts' using errcode='42501'; end if;
  if nullif(trim(p_name),'') is null then raise exception 'Account name is required' using errcode='23514'; end if;
  perform set_config('app.change_reason',coalesce(nullif(trim(p_reason),''),'Financial account updated'),true);
  update public.company_fund_accounts
     set name=trim(p_name), notes=nullif(trim(p_notes),''), is_active=coalesce(p_is_active,true), updated_at=now(), updated_by=(select auth.uid())
   where id=account_row.id returning * into account_row;
  perform set_config('app.change_reason','',true);
  return account_row;
end;
$$;


--
-- Name: fiscal_installations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.fiscal_installations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    branch_id uuid NOT NULL,
    fiscal_location_id uuid,
    pos_terminal_id uuid NOT NULL,
    taxpayer_identifier text,
    taxpayer_name text,
    business_unit_number text,
    pos_number text,
    software_solution_code text,
    fiscalization_number text,
    unique_fiscalization_code text,
    efs_identification_number text,
    application_id text,
    status text DEFAULT 'not_configured'::text NOT NULL,
    certificate_reference text,
    certificate_fingerprint text,
    signing_key_reference text,
    production_enabled boolean DEFAULT false NOT NULL,
    certification_mode boolean DEFAULT false NOT NULL,
    activated_at timestamp with time zone,
    deactivated_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_by uuid,
    CONSTRAINT fiscal_installations_check CHECK (((production_enabled = false) OR (status = 'active'::text))),
    CONSTRAINT fiscal_installations_check1 CHECK (((status <> 'active'::text) OR (NULLIF(TRIM(BOTH FROM taxpayer_identifier), ''::text) IS NOT NULL))),
    CONSTRAINT fiscal_installations_check2 CHECK (((status <> 'active'::text) OR (NULLIF(TRIM(BOTH FROM unique_fiscalization_code), ''::text) IS NOT NULL))),
    CONSTRAINT fiscal_installations_check3 CHECK (((status <> 'active'::text) OR (NULLIF(TRIM(BOTH FROM software_solution_code), ''::text) IS NOT NULL))),
    CONSTRAINT fiscal_installations_check4 CHECK (((status <> 'active'::text) OR (NULLIF(TRIM(BOTH FROM fiscalization_number), ''::text) IS NOT NULL))),
    CONSTRAINT fiscal_installations_check5 CHECK (((production_enabled = false) OR (certification_mode = false))),
    CONSTRAINT fiscal_installations_status_check CHECK ((status = ANY (ARRAY['not_configured'::text, 'waiting_for_taxpayer'::text, 'configured'::text, 'validated'::text, 'active'::text, 'suspended'::text, 'revoked'::text, 'deactivated'::text])))
);


--
-- Name: upsert_fiscal_installation(uuid, uuid, uuid, uuid, text, text, text, text, text, text, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_fiscal_installation(p_company_id uuid, p_branch_id uuid, p_pos_terminal_id uuid, p_fiscal_location_id uuid DEFAULT NULL::uuid, p_taxpayer_identifier text DEFAULT NULL::text, p_taxpayer_name text DEFAULT NULL::text, p_business_unit_number text DEFAULT NULL::text, p_pos_number text DEFAULT NULL::text, p_software_solution_code text DEFAULT NULL::text, p_fiscalization_number text DEFAULT NULL::text, p_unique_fiscalization_code text DEFAULT NULL::text, p_efs_identification_number text DEFAULT NULL::text, p_application_id text DEFAULT NULL::text, p_certificate_reference text DEFAULT NULL::text, p_certificate_fingerprint text DEFAULT NULL::text, p_signing_key_reference text DEFAULT NULL::text, p_certification_mode boolean DEFAULT false) RETURNS public.fiscal_installations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  installation public.fiscal_installations;
  current_user_id uuid := (select auth.uid());
begin
  if current_user_id is null or not private.has_company_permission(p_company_id, 'pos.fiscal.configure') then
    raise exception 'Insufficient permission to configure EFS installations' using errcode = '42501';
  end if;
  if p_certification_mode and coalesce((
    select enabled from public.company_feature_flags
    where company_id = p_company_id and flag = 'kosovo_efs_production_enabled'
  ), false) then
    raise exception 'Certification mode cannot be combined with production fiscalization' using errcode = '55000';
  end if;

  perform set_config('app.efs_configuration_workflow', 'authorized', true);
  insert into public.fiscal_installations (
    company_id, branch_id, fiscal_location_id, pos_terminal_id,
    taxpayer_identifier, taxpayer_name, business_unit_number, pos_number,
    software_solution_code, fiscalization_number, unique_fiscalization_code,
    efs_identification_number, application_id, certificate_reference,
    certificate_fingerprint, signing_key_reference, status, certification_mode,
    created_by, updated_by
  )
  values (
    p_company_id, p_branch_id, p_fiscal_location_id, p_pos_terminal_id,
    nullif(trim(p_taxpayer_identifier), ''), nullif(trim(p_taxpayer_name), ''),
    nullif(trim(p_business_unit_number), ''), nullif(trim(p_pos_number), ''),
    nullif(trim(p_software_solution_code), ''), nullif(trim(p_fiscalization_number), ''),
    nullif(trim(p_unique_fiscalization_code), ''), nullif(trim(p_efs_identification_number), ''),
    nullif(trim(p_application_id), ''), nullif(trim(p_certificate_reference), ''),
    nullif(trim(p_certificate_fingerprint), ''), nullif(trim(p_signing_key_reference), ''),
    private.derive_fiscal_installation_status(
      p_taxpayer_identifier, p_business_unit_number, p_pos_number,
      p_software_solution_code, p_fiscalization_number, p_unique_fiscalization_code,
      p_certificate_reference, p_signing_key_reference
    ),
    coalesce(p_certification_mode, false), current_user_id, current_user_id
  )
  on conflict (company_id, pos_terminal_id) do update
  set branch_id = excluded.branch_id,
      fiscal_location_id = excluded.fiscal_location_id,
      taxpayer_identifier = excluded.taxpayer_identifier,
      taxpayer_name = excluded.taxpayer_name,
      business_unit_number = excluded.business_unit_number,
      pos_number = excluded.pos_number,
      software_solution_code = excluded.software_solution_code,
      fiscalization_number = excluded.fiscalization_number,
      unique_fiscalization_code = excluded.unique_fiscalization_code,
      efs_identification_number = excluded.efs_identification_number,
      application_id = excluded.application_id,
      certificate_reference = excluded.certificate_reference,
      certificate_fingerprint = excluded.certificate_fingerprint,
      signing_key_reference = excluded.signing_key_reference,
      status = excluded.status,
      certification_mode = excluded.certification_mode,
      updated_at = clock_timestamp(),
      updated_by = current_user_id
  returning * into installation;
  perform set_config('app.efs_configuration_workflow', '', true);

  insert into public.fiscal_configuration_history (
    company_id, installation_id, event_type, new_status,
    changed_fields, actor_id
  )
  values (
    installation.company_id, installation.id, 'installation_configured', installation.status,
    jsonb_build_object(
      'business_unit_number', installation.business_unit_number,
      'pos_number', installation.pos_number,
      'certificate_reference_present', installation.certificate_reference is not null,
      'signing_key_reference_present', installation.signing_key_reference is not null,
      'production_enabled', installation.production_enabled,
      'certification_mode', installation.certification_mode
    ), current_user_id
  );
  return installation;
end
$$;


--
-- Name: upsert_stripe_store_secret(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_stripe_store_secret(p_stripe_store_id uuid, p_access_token text, p_refresh_token text, p_livemode boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if nullif(trim(p_access_token), '') is null then
    raise exception 'Stripe access token is required' using errcode = '22023';
  end if;
  insert into private.stripe_store_secrets (
    stripe_store_id, access_token, refresh_token, livemode, updated_at
  ) values (
    p_stripe_store_id, p_access_token, p_refresh_token, coalesce(p_livemode, false), now()
  )
  on conflict (stripe_store_id) do update
    set access_token = excluded.access_token,
        refresh_token = excluded.refresh_token,
        livemode = excluded.livemode,
        updated_at = now();
end;
$$;


--
-- Name: verify_invite_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_invite_token(token_input text) RETURNS TABLE(company_id uuid, company_name text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select company.id, company.company_name
  from public.companies company
  where lower(company.invite_token) = lower(trim(token_input))
  union all
  select invitation.company_id, company.company_name
  from public.company_invitations invitation
  join public.companies company on company.id = invitation.company_id
  where invitation.token_hash = encode(extensions.digest(trim(token_input), 'sha256'), 'hex')
    and invitation.status = 'pending'
    and invitation.expires_at > now();
$$;


