    CONSTRAINT api_webhook_endpoints_failure_count_check CHECK ((failure_count >= 0)),
    CONSTRAINT api_webhook_endpoints_name_check CHECK (((char_length(TRIM(BOTH FROM name)) >= 1) AND (char_length(TRIM(BOTH FROM name)) <= 120))),
    CONSTRAINT api_webhook_endpoints_secret_hash_check CHECK ((secret_hash ~~ 'sha256:%'::text)),
    CONSTRAINT api_webhook_endpoints_status_check CHECK ((status = ANY (ARRAY['active'::text, 'disabled'::text, 'failing'::text, 'deleted'::text]))),
    CONSTRAINT api_webhook_endpoints_success_count_check CHECK ((success_count >= 0))
);


