--

CREATE TABLE public.bookings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    booking_number text NOT NULL,
    customer_id uuid,
    guest_name text,
    guest_email text,
    guest_phone text,
    service_id uuid NOT NULL,
    location_id uuid,
    resource_id uuid,
    staff_id uuid,
    starts_at timestamp with time zone NOT NULL,
    ends_at timestamp with time zone NOT NULL,
    timezone text DEFAULT 'UTC'::text NOT NULL,
    duration_minutes integer NOT NULL,
    quantity integer DEFAULT 1 NOT NULL,
    participant_count integer DEFAULT 1 NOT NULL,
    price numeric(20,4) DEFAULT 0 NOT NULL,
    discount_amount numeric(20,4) DEFAULT 0 NOT NULL,
    tax_amount numeric(20,4) DEFAULT 0 NOT NULL,
    deposit_amount numeric(20,4) DEFAULT 0 NOT NULL,
    total_amount numeric(20,4) DEFAULT 0 NOT NULL,
    paid_amount numeric(20,4) DEFAULT 0 NOT NULL,
    currency text DEFAULT 'EUR'::text NOT NULL,
    payment_status text DEFAULT 'unpaid'::text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    notes text,
    internal_notes text,
    customer_notes text,
    source text DEFAULT 'admin'::text NOT NULL,
    recurrence_rule text,
    recurrence_series_id uuid,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    payment_stage text DEFAULT 'pending_deposit'::text NOT NULL,
    cancellation_fee numeric(20,4) DEFAULT 0 NOT NULL,
    deposit_refund_amount numeric(20,4) DEFAULT 0 NOT NULL,
    policy_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    recurrence_index integer,
    recurrence_exception boolean DEFAULT false NOT NULL,
    source_detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    customer_package_id uuid,
    package_units_reserved integer DEFAULT 0 NOT NULL,
    custom_form_answers jsonb DEFAULT '{}'::jsonb NOT NULL,
    external_reference text,
    membership_id uuid,
    CONSTRAINT bookings_check CHECK ((ends_at > starts_at)),
    CONSTRAINT bookings_check1 CHECK (((customer_id IS NOT NULL) OR (NULLIF(TRIM(BOTH FROM COALESCE(guest_name, ''::text)), ''::text) IS NOT NULL))),
    CONSTRAINT bookings_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT bookings_deposit_amount_check CHECK ((deposit_amount >= (0)::numeric)),
    CONSTRAINT bookings_discount_amount_check CHECK ((discount_amount >= (0)::numeric)),
    CONSTRAINT bookings_duration_minutes_check CHECK ((duration_minutes > 0)),
    CONSTRAINT bookings_paid_amount_check CHECK ((paid_amount >= (0)::numeric)),
    CONSTRAINT bookings_participant_count_check CHECK ((participant_count > 0)),
    CONSTRAINT bookings_payment_status_check CHECK ((payment_status = ANY (ARRAY['unpaid'::text, 'partially_paid'::text, 'paid'::text, 'refunded'::text, 'partially_refunded'::text, 'failed'::text]))),
    CONSTRAINT bookings_price_check CHECK ((price >= (0)::numeric)),
    CONSTRAINT bookings_quantity_check CHECK ((quantity > 0)),
    CONSTRAINT bookings_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending'::text, 'confirmed'::text, 'checked_in'::text, 'in_progress'::text, 'completed'::text, 'cancelled'::text, 'no_show'::text, 'rescheduled'::text]))),
    CONSTRAINT bookings_tax_amount_check CHECK ((tax_amount >= (0)::numeric)),
    CONSTRAINT bookings_total_amount_check CHECK ((total_amount >= (0)::numeric))
);


