--
-- Name: customer_credit_balances; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.customer_credit_balances WITH (security_invoker='true') AS
 WITH allocation_totals AS (
         SELECT allocation.payment_id,
            sum(allocation.allocated_amount) AS allocated_amount
           FROM public.payment_allocations allocation
          WHERE (allocation.status = 'active'::text)
          GROUP BY allocation.payment_id
        ), refund_totals AS (
         SELECT refund.payment_id,
            sum(refund.amount) AS refund_amount
           FROM public.customer_refunds refund
          WHERE (refund.status = 'posted'::text)
          GROUP BY refund.payment_id
        )
 SELECT payment.company_id,
    payment.client_id AS customer_id,
    round(sum(((payment.amount - COALESCE(allocation_totals.allocated_amount, (0)::numeric)) - COALESCE(refund_totals.refund_amount, (0)::numeric))), 4) AS available_credit,
    max(payment.payment_date) AS latest_payment_date
   FROM ((public.payments payment
     LEFT JOIN allocation_totals ON ((allocation_totals.payment_id = payment.id)))
     LEFT JOIN refund_totals ON ((refund_totals.payment_id = payment.id)))
  WHERE ((payment.accounting_state = 'posted'::text) AND (payment.payment_status = 'posted'::text))
  GROUP BY payment.company_id, payment.client_id;


