);


--
-- Name: general_ledger_entries; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.general_ledger_entries WITH (security_invoker='true') AS
 SELECT entry.company_id,
    entry.id AS journal_entry_id,
    entry.entry_number,
    entry.posting_date,
    entry.document_date,
    entry.description AS journal_description,
    entry.reference,
    entry.source_type,
    entry.source_id,
    line.id AS journal_line_id,
    line.line_number,
    account.id AS account_id,
    account.code AS account_code,
    account.name AS account_name,
    account.account_type,
    line.description,
    line.debit,
    line.credit,
    (line.debit - line.credit) AS signed_amount,
    line.cost_centre_id,
    line.project_id,
    COALESCE(line.branch_id, entry.branch_id) AS branch_id,
    line.tax_code,
    line.tax_base,
    line.tax_amount
   FROM ((public.journal_entries entry
     JOIN public.journal_entry_lines line ON ((line.journal_entry_id = entry.id)))
     JOIN public.chart_of_accounts account ON ((account.id = line.account_id)))
  WHERE (entry.status = 'posted'::text);


--
-- Name: customer_subledger_entries; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.customer_subledger_entries WITH (security_invoker='true') AS
 SELECT ledger.company_id,
    customer.id AS customer_id,
    customer.name AS customer_name,
    ledger.journal_entry_id,
    ledger.entry_number,
    ledger.posting_date,
    ledger.source_type,
    ledger.source_id,
    ledger.account_id,
    ledger.account_code,
    ledger.account_name,
    ledger.debit,
    ledger.credit,
    ledger.signed_amount,
    ledger.description
   FROM ((((public.general_ledger_entries ledger
     JOIN LATERAL ( SELECT COALESCE(original.source_type, ledger.source_type) AS source_type,
            COALESCE(original.source_id, ledger.source_id) AS source_id
           FROM public.journal_entries original
          WHERE ((ledger.source_type = 'journal_reversal'::text) AND (original.id = ledger.source_id))
        UNION ALL
         SELECT ledger.source_type,
            ledger.source_id
          WHERE (ledger.source_type IS DISTINCT FROM 'journal_reversal'::text)
 LIMIT 1) source ON (true))
     LEFT JOIN public.invoices invoice ON (((source.source_type = ANY (ARRAY['sales_invoice'::text, 'credit_note'::text])) AND (invoice.id = source.source_id))))
     LEFT JOIN public.payments payment ON (((source.source_type = 'customer_payment'::text) AND (payment.id = source.source_id))))
     JOIN public.clients customer ON ((customer.id = COALESCE(invoice.client_id, payment.client_id))))
  WHERE (ledger.account_id IN ( SELECT account.id
           FROM public.chart_of_accounts account
          WHERE ((account.company_id = ledger.company_id) AND (account.statement_mapping = 'balance_sheet.receivables'::text))));


--
-- Name: customer_subledger_reconciliation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.customer_subledger_reconciliation WITH (security_invoker='true') AS
 WITH subledger AS (
         SELECT customer_subledger_entries.company_id,
            round(sum(customer_subledger_entries.signed_amount), 4) AS subledger_balance
           FROM public.customer_subledger_entries
          GROUP BY customer_subledger_entries.company_id
        ), general_ledger AS (
         SELECT ledger.company_id,
            round(sum((ledger.debit - ledger.credit)), 4) AS gl_balance
           FROM public.general_ledger_entries ledger
          WHERE (ledger.account_id IN ( SELECT account.id
                   FROM public.chart_of_accounts account
                  WHERE ((account.company_id = ledger.company_id) AND (account.statement_mapping = 'balance_sheet.receivables'::text))))
          GROUP BY ledger.company_id
        )
 SELECT COALESCE(subledger.company_id, general_ledger.company_id) AS company_id,
    (COALESCE(subledger.subledger_balance, (0)::numeric))::numeric(20,4) AS subledger_balance,
    (COALESCE(general_ledger.gl_balance, (0)::numeric))::numeric(20,4) AS gl_balance,
    (round((COALESCE(subledger.subledger_balance, (0)::numeric) - COALESCE(general_ledger.gl_balance, (0)::numeric)), 4))::numeric(20,4) AS difference,
    (round((COALESCE(subledger.subledger_balance, (0)::numeric) - COALESCE(general_ledger.gl_balance, (0)::numeric)), 4) = (0)::numeric) AS reconciles
   FROM (subledger
     FULL JOIN general_ledger ON ((general_ledger.company_id = subledger.company_id)));


