    CONSTRAINT products_vat_treatment_check CHECK ((vat_treatment = ANY (ARRAY['standard_18'::text, 'reduced_8'::text, 'exempt_no_credit'::text, 'exempt_with_credit'::text, 'export'::text, 'reverse_charge'::text, 'out_of_scope'::text])))
);


--
-- Name: inventory_register; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.inventory_register WITH (security_invoker='true') AS
 SELECT company_id,
    product_id,
    sku,
    name,
    category,
    quantity,
    average_cost,
    inventory_value,
    track_stock
   FROM ( WITH latest AS (
                 SELECT DISTINCT ON (inventory_movements.company_id, inventory_movements.product_id) inventory_movements.company_id,
                    inventory_movements.product_id,
                    inventory_movements.quantity_after,
                    inventory_movements.average_cost_after,
                    inventory_movements.inventory_value_after
                   FROM public.inventory_movements
                  ORDER BY inventory_movements.company_id, inventory_movements.product_id, inventory_movements.movement_sequence DESC
                )
         SELECT product.company_id,
            product.id AS product_id,
            product.sku,
            product.name,
            product.category,
            round(COALESCE(latest.quantity_after, product.stock_quantity, (0)::numeric), 4) AS quantity,
            round(COALESCE(latest.average_cost_after, product.cost_price, (0)::numeric), 4) AS average_cost,
            round(COALESCE(latest.inventory_value_after, (COALESCE(product.stock_quantity, (0)::numeric) * COALESCE(product.cost_price, (0)::numeric))), 4) AS inventory_value,
            product.track_stock
           FROM (public.products product
             LEFT JOIN latest ON (((latest.company_id = product.company_id) AND (latest.product_id = product.id))))
          WHERE COALESCE(product.track_stock, false)) rbac_report
  WHERE private.has_company_permission(company_id, 'inventory.view'::text);


--
-- Name: inventory_gl_reconciliation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.inventory_gl_reconciliation WITH (security_invoker='true') AS
 WITH register AS (
         SELECT inventory_register.company_id,
            (COALESCE(sum(inventory_register.inventory_value), (0)::numeric))::numeric(20,4) AS inventory_register_value
           FROM public.inventory_register
          GROUP BY inventory_register.company_id
        ), ledger AS (
         SELECT entry.company_id,
            (COALESCE(sum((line.debit - line.credit)), (0)::numeric))::numeric(20,4) AS inventory_gl_value
           FROM ((public.journal_entries entry
             JOIN public.journal_entry_lines line ON ((line.journal_entry_id = entry.id)))
             JOIN public.chart_of_accounts account ON ((account.id = line.account_id)))
          WHERE ((entry.status = 'posted'::text) AND (account.code = '1200'::text))
          GROUP BY entry.company_id
        )
 SELECT company.id AS company_id,
    COALESCE(register.inventory_register_value, (0)::numeric) AS inventory_register_value,
    COALESCE(ledger.inventory_gl_value, (0)::numeric) AS inventory_gl_value,
    round((COALESCE(register.inventory_register_value, (0)::numeric) - COALESCE(ledger.inventory_gl_value, (0)::numeric)), 4) AS difference
   FROM ((public.companies company
     LEFT JOIN register ON ((register.company_id = company.id)))
     LEFT JOIN ledger ON ((ledger.company_id = company.id)));


