);


--
-- Name: kosovo_expense_purchase_book; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.kosovo_expense_purchase_book WITH (security_invoker='true') AS
 SELECT company_id,
    source_expense_id,
    expense_number,
    bill_number,
    bill_date,
    vendor_id,
    supplier_name,
    supplier_fiscal_number,
    vat_classification,
    taxable_base,
    input_vat,
    recoverable_vat,
    nonrecoverable_vat,
    total_amount,
    is_import,
    reverse_charge,
    is_credit_note,
    source_journal_entry_id,
    documentation_status,
    purchase_book_excluded_reason
   FROM ( SELECT e.company_id,
            e.id AS source_expense_id,
            e.expense_number,
            e.document_number AS bill_number,
            COALESCE(e.issue_date, e.date) AS bill_date,
            e.vendor_id,
            COALESCE(v.name, e.vendor_name) AS supplier_name,
            COALESCE(e.supplier_fiscal_number, v.tax_id) AS supplier_fiscal_number,
            e.vat_treatment AS vat_classification,
            e.net_amount AS taxable_base,
            e.vat_amount AS input_vat,
            e.vat_deductible_amount AS recoverable_vat,
            GREATEST((e.vat_amount - e.vat_deductible_amount), (0)::numeric) AS nonrecoverable_vat,
            e.gross_amount AS total_amount,
            (e.document_type = 'import_customs_document'::text) AS is_import,
            false AS reverse_charge,
            false AS is_credit_note,
            e.posting_journal_entry_id AS source_journal_entry_id,
            e.documentation_status,
            e.purchase_book_excluded_reason
           FROM (public.expenses e
             LEFT JOIN public.vendors v ON ((v.id = e.vendor_id)))
          WHERE ((e.accounting_state = 'posted'::text) AND (e.archived_at IS NULL) AND e.purchase_book_eligible AND (e.documentation_status = 'complete'::text))) rbac_report
  WHERE private.has_company_permission(company_id, 'reports.tax'::text);


--
-- Name: kosovo_purchase_book; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.kosovo_purchase_book WITH (security_invoker='true') AS
 SELECT company_id,
    period_start,
    supplier_bill_id,
    bill_number,
    bill_date,
    vendor_id,
    supplier_name,
    supplier_fiscal_number,
    vat_classification,
    taxable_base,
    input_vat,
    recoverable_vat,
    nonrecoverable_vat,
    total_amount,
    is_import,
    reverse_charge,
    is_credit_note,
    source_journal_entry_id
   FROM ( SELECT bill.company_id,
            (date_trunc('month'::text, (COALESCE(bill.issue_date, bill.posting_date, CURRENT_DATE))::timestamp with time zone))::date AS period_start,
            bill.id AS supplier_bill_id,
            bill.bill_number,
            COALESCE(bill.issue_date, bill.posting_date) AS bill_date,
            bill.vendor_id,
            vendor.name AS supplier_name,
            COALESCE(vendor.fiscal_number, vendor.vat_number, vendor.tax_id) AS supplier_fiscal_number,
            COALESCE(NULLIF(bill.tax_reporting_category, ''::text), 'domestic_purchase'::text) AS vat_classification,
            (round((COALESCE(bill.total_amount, (0)::numeric) - COALESCE(bill.tax_amount, (0)::numeric)), 4) * (
                CASE
                    WHEN (bill.credit_of_bill_id IS NOT NULL) THEN '-1'::integer
                    ELSE 1
                END)::numeric) AS taxable_base,
            (round(COALESCE(bill.tax_amount, (0)::numeric), 4) * (
                CASE
                    WHEN (bill.credit_of_bill_id IS NOT NULL) THEN '-1'::integer
                    ELSE 1
                END)::numeric) AS input_vat,
            (round(COALESCE(bill.input_vat_recoverable_amount, (0)::numeric), 4) * (
                CASE
                    WHEN (bill.credit_of_bill_id IS NOT NULL) THEN '-1'::integer
                    ELSE 1
                END)::numeric) AS recoverable_vat,
            (round(COALESCE(bill.input_vat_non_recoverable_amount, (0)::numeric), 4) * (
                CASE
                    WHEN (bill.credit_of_bill_id IS NOT NULL) THEN '-1'::integer
                    ELSE 1
                END)::numeric) AS nonrecoverable_vat,
            (round(COALESCE(bill.total_amount, (0)::numeric), 4) * (
                CASE
                    WHEN (bill.credit_of_bill_id IS NOT NULL) THEN '-1'::integer
                    ELSE 1
                END)::numeric) AS total_amount,
            bill.is_import,
            bill.reverse_charge,
            (bill.credit_of_bill_id IS NOT NULL) AS is_credit_note,
            bill.posting_journal_entry_id AS source_journal_entry_id
           FROM (public.supplier_bills bill
             LEFT JOIN public.vendors vendor ON ((vendor.id = bill.vendor_id)))
          WHERE ((bill.accounting_state = 'posted'::text) AND (COALESCE(bill.status, ''::text) <> ALL (ARRAY['cancelled'::text, 'reversed'::text])))) report
  WHERE private.has_company_permission(company_id, 'reports.tax'::text);


--
-- Name: kosovo_purchase_book_expanded; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.kosovo_purchase_book_expanded WITH (security_invoker='true') AS
 SELECT book.company_id,
    book.period_start,
    book.supplier_bill_id,
    NULL::uuid AS source_expense_id,
    book.bill_number,
    book.bill_date,
    book.vendor_id,
    book.supplier_name,
    book.supplier_fiscal_number,
    book.vat_classification,
    book.taxable_base,
    book.input_vat,
    book.recoverable_vat,
    book.nonrecoverable_vat,
    book.total_amount,
    book.is_import,
    book.reverse_charge,
    book.is_credit_note,
    book.source_journal_entry_id
   FROM public.kosovo_purchase_book book
UNION ALL
 SELECT expense.company_id,
    (date_trunc('month'::text, (expense.bill_date)::timestamp with time zone))::date AS period_start,
    NULL::uuid AS supplier_bill_id,
    expense.source_expense_id,
    expense.bill_number,
    expense.bill_date,
    expense.vendor_id,
    expense.supplier_name,
    expense.supplier_fiscal_number,
    expense.vat_classification,
    expense.taxable_base,
    expense.input_vat,
    expense.recoverable_vat,
    expense.nonrecoverable_vat,
    expense.total_amount,
    expense.is_import,
    expense.reverse_charge,
    expense.is_credit_note,
    expense.source_journal_entry_id
   FROM public.kosovo_expense_purchase_book expense;


--
-- Name: kosovo_sales_book; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.kosovo_sales_book WITH (security_invoker='true') AS
 SELECT company_id,
    period_start,
    invoice_id,
    invoice_number,
    invoice_date,
    client_id,
    customer_name,
    customer_fiscal_number,
    vat_classification,
    vat_rate,
    taxable_base,
    output_vat,
    total_amount,
    is_credit_note,
    source_journal_entry_id,
    sales_book_period_id,
    period_end,
    period_status,
    declaration_deadline,
    declared_at,
    declared_by
   FROM ( SELECT invoice.company_id,
            period.period_start,
            invoice.id AS invoice_id,
            invoice.invoice_number,
            COALESCE(invoice.issue_date, invoice.posting_date) AS invoice_date,
            invoice.client_id,
            client.name AS customer_name,
            COALESCE(client.nui, client.fiscal_number, client.vat_number, client.tax_id) AS customer_fiscal_number,
            COALESCE(NULLIF(invoice.tax_reporting_category, ''::text),
                CASE
                    WHEN (max(COALESCE(item.tax_rate, (0)::numeric)) = (18)::numeric) THEN 'standard_18'::text
                    WHEN (max(COALESCE(item.tax_rate, (0)::numeric)) = (8)::numeric) THEN 'reduced_8'::text
                    WHEN (max(COALESCE(item.tax_rate, (0)::numeric)) = (0)::numeric) THEN 'zero_rated'::text
                    ELSE 'classified_review_required'::text
                END) AS vat_classification,
            (max(COALESCE(item.tax_rate, (0)::numeric)))::numeric(8,4) AS vat_rate,
            round((sum(COALESCE(item.amount, (0)::numeric)) * (
                CASE
                    WHEN ((invoice.credit_of_invoice_id IS NOT NULL) OR (lower(COALESCE(invoice.type, ''::text)) = 'credit_note'::text)) THEN '-1'::integer
                    ELSE 1
                END)::numeric), 4) AS taxable_base,
            round((sum(round(((COALESCE(item.amount, (0)::numeric) * COALESCE(item.tax_rate, (0)::numeric)) / (100)::numeric), 4)) * (
                CASE
                    WHEN ((invoice.credit_of_invoice_id IS NOT NULL) OR (lower(COALESCE(invoice.type, ''::text)) = 'credit_note'::text)) THEN '-1'::integer
                    ELSE 1
                END)::numeric), 4) AS output_vat,
            round((COALESCE(invoice.total_amount, (0)::numeric) * (
                CASE
                    WHEN ((invoice.credit_of_invoice_id IS NOT NULL) OR (lower(COALESCE(invoice.type, ''::text)) = 'credit_note'::text)) THEN '-1'::integer
                    ELSE 1
                END)::numeric), 4) AS total_amount,
            ((invoice.credit_of_invoice_id IS NOT NULL) OR (lower(COALESCE(invoice.type, ''::text)) = 'credit_note'::text)) AS is_credit_note,
            invoice.posting_journal_entry_id AS source_journal_entry_id,
            period.id AS sales_book_period_id,
            period.period_end,
            period.status AS period_status,
            period.declaration_deadline,
            period.declared_at,
            period.declared_by
           FROM (((public.invoices invoice
             JOIN public.sales_book_periods period ON ((period.id = invoice.sales_book_period_id)))
             JOIN public.invoice_items item ON ((item.invoice_id = invoice.id)))
             LEFT JOIN public.clients client ON ((client.id = invoice.client_id)))
          WHERE ((invoice.accounting_state = 'posted'::text) AND (invoice.status <> ALL (ARRAY['cancelled'::public.invoice_status, 'reversed'::public.invoice_status])))
          GROUP BY invoice.company_id, period.period_start, period.period_end, period.id, period.status, period.declaration_deadline, period.declared_at, period.declared_by, invoice.id, invoice.invoice_number, invoice.issue_date, invoice.posting_date, invoice.client_id, client.name, client.nui, client.fiscal_number, client.vat_number, client.tax_id, invoice.tax_reporting_category, invoice.type, invoice.credit_of_invoice_id, invoice.total_amount, invoice.posting_journal_entry_id) rbac_report
  WHERE private.has_company_permission(company_id, 'sales_book.view'::text);


--
-- Name: kosovo_sales_book_period_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.kosovo_sales_book_period_summary AS
SELECT
    NULL::uuid AS id,
    NULL::uuid AS company_id,
    NULL::uuid AS accounting_period_id,
    NULL::date AS period_start,
    NULL::date AS period_end,
