    NULL::numeric AS taxable_amount,
    NULL::numeric AS vat_amount,
    NULL::numeric AS total_amount;


--
-- Name: kosovo_tax_book_reconciliation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.kosovo_tax_book_reconciliation WITH (security_invoker='true') AS
 SELECT company_id,
    sales_book_output_vat,
    output_vat_gl,
    output_vat_difference,
    purchase_book_recoverable_vat,
    recoverable_vat_gl,
    recoverable_vat_difference
   FROM ( WITH sales AS (
                 SELECT kosovo_sales_book.company_id,
                    (COALESCE(sum(kosovo_sales_book.output_vat), (0)::numeric))::numeric(20,4) AS output_vat
                   FROM public.kosovo_sales_book
                  GROUP BY kosovo_sales_book.company_id
                ), purchases AS (
                 SELECT kosovo_purchase_book_expanded.company_id,
                    (COALESCE(sum(kosovo_purchase_book_expanded.recoverable_vat), (0)::numeric))::numeric(20,4) AS recoverable_vat
                   FROM public.kosovo_purchase_book_expanded
                  GROUP BY kosovo_purchase_book_expanded.company_id
                ), gl AS (
                 SELECT entry.company_id,
                    (COALESCE(sum(
                        CASE
                            WHEN (account.code = '2100'::text) THEN (line.credit - line.debit)
                            ELSE (0)::numeric
                        END), (0)::numeric))::numeric(20,4) AS output_vat_gl,
                    (COALESCE(sum(
                        CASE
                            WHEN (account.code = '1300'::text) THEN (line.debit - line.credit)
                            ELSE (0)::numeric
                        END), (0)::numeric))::numeric(20,4) AS recoverable_vat_gl
                   FROM ((public.journal_entries entry
                     JOIN public.journal_entry_lines line ON ((line.journal_entry_id = entry.id)))
                     JOIN public.chart_of_accounts account ON ((account.id = line.account_id)))
                  WHERE ((entry.status = 'posted'::text) AND (entry.source_type = ANY (ARRAY['sales_invoice'::text, 'pos_invoice'::text, 'supplier_bill'::text, 'expense'::text])))
                  GROUP BY entry.company_id
                )
         SELECT company.id AS company_id,
            COALESCE(sales.output_vat, (0)::numeric) AS sales_book_output_vat,
            COALESCE(gl.output_vat_gl, (0)::numeric) AS output_vat_gl,
            round((COALESCE(sales.output_vat, (0)::numeric) - COALESCE(gl.output_vat_gl, (0)::numeric)), 4) AS output_vat_difference,
            COALESCE(purchases.recoverable_vat, (0)::numeric) AS purchase_book_recoverable_vat,
            COALESCE(gl.recoverable_vat_gl, (0)::numeric) AS recoverable_vat_gl,
            round((COALESCE(purchases.recoverable_vat, (0)::numeric) - COALESCE(gl.recoverable_vat_gl, (0)::numeric)), 4) AS recoverable_vat_difference
           FROM (((public.companies company
             LEFT JOIN sales ON ((sales.company_id = company.id)))
             LEFT JOIN purchases ON ((purchases.company_id = company.id)))
             LEFT JOIN gl ON ((gl.company_id = company.id)))) rbac_report
  WHERE private.has_company_permission(company_id, 'reports.tax'::text);


--
-- Name: tax_calendar_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tax_calendar_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    tax_type text NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    due_date date NOT NULL,
    title text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    completed_at timestamp with time zone,
    source_reference text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT tax_calendar_events_status_check CHECK ((status = ANY (ARRAY['open'::text, 'completed'::text])))
);


--
-- Name: kosovo_tax_calendar; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.kosovo_tax_calendar WITH (security_invoker='true') AS
 SELECT id,
    company_id,
    tax_type,
    period_start,
    period_end,
    due_date,
    title,
    status,
    completed_at,
    source_reference,
    created_at,
    created_by,
    display_status
   FROM ( SELECT event.id,
            event.company_id,
            event.tax_type,
            event.period_start,
            event.period_end,
            event.due_date,
            event.title,
            event.status,
            event.completed_at,
            event.source_reference,
            event.created_at,
            event.created_by,
                CASE
                    WHEN (event.status = 'completed'::text) THEN 'completed'::text
                    WHEN (event.due_date < CURRENT_DATE) THEN 'overdue'::text
                    WHEN (event.due_date <= (CURRENT_DATE + 7)) THEN 'due_soon'::text
                    ELSE 'upcoming'::text
                END AS display_status
           FROM public.tax_calendar_events event) rbac_report
  WHERE private.has_company_permission(company_id, 'reports.tax'::text);


