--
-- Name: offline_sync_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.offline_sync_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    batch_id uuid NOT NULL,
    device_registration_id uuid NOT NULL,
    client_item_id uuid NOT NULL,
    idempotency_key uuid NOT NULL,
    queue_sequence bigint NOT NULL,
    configuration_version integer NOT NULL,
    integrity_checksum text NOT NULL,
    client_queue_encrypted boolean DEFAULT true NOT NULL,
    payload jsonb NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    conflict_type text,
    error_code text,
    error_message text,
    result jsonb,
    original_occurred_at timestamp with time zone NOT NULL,
    server_posted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    processed_at timestamp with time zone,
    created_by uuid,
    CONSTRAINT offline_sync_items_configuration_version_check CHECK ((configuration_version > 0)),
    CONSTRAINT offline_sync_items_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT offline_sync_items_queue_sequence_check CHECK ((queue_sequence >= 0)),
    CONSTRAINT offline_sync_items_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'processing'::text, 'completed'::text, 'conflict'::text, 'failed'::text, 'rejected'::text])))
);


--
-- Name: operix_accessible_company_bank_accounts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_accessible_company_bank_accounts WITH (security_invoker='true') AS
 SELECT account.id,
    account.company_id,
    account.company_id AS owner_company_id,
    account.company_id AS available_company_id,
    account.bank_name,
    account.account_name,
    account.account_number,
    account.iban,
    account.swift_bic,
    account.currency,
    account.is_primary,
    account.is_active,
    account.created_at,
    account.account_id,
    false AS is_shared
   FROM public.company_bank_accounts account
UNION ALL
 SELECT account.id,
    account.company_id,
    account.company_id AS owner_company_id,
    share.shared_company_id AS available_company_id,
    account.bank_name,
    account.account_name,
    account.account_number,
    account.iban,
    account.swift_bic,
    account.currency,
    false AS is_primary,
    account.is_active,
    account.created_at,
    account.account_id,
    true AS is_shared
   FROM (public.company_bank_accounts account
     JOIN public.company_bank_account_shares share ON (((share.company_bank_account_id = account.id) AND share.is_active)));


--
-- Name: operix_ap_open_items; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_ap_open_items WITH (security_invoker='true') AS
 SELECT company_id,
    branch_id,
    vendor_id,
    supplier_bill_id,
    bill_number,
    supplier_name,
    issue_date,
    due_date,
    currency,
    original_amount,
    allocated_amount,
    outstanding_amount,
    days_overdue,
    aging_bucket
   FROM ( SELECT bill.company_id,
            bill.branch_id,
            bill.vendor_id,
            bill.id AS supplier_bill_id,
            bill.bill_number,
            vendor.name AS supplier_name,
            bill.issue_date,
            bill.due_date,
            bill.currency,
            round(bill.total_amount, 4) AS original_amount,
            round(COALESCE(sum(allocation.allocated_amount) FILTER (WHERE (allocation.status = 'active'::text)), (0)::numeric), 4) AS allocated_amount,
            round((bill.total_amount - COALESCE(sum(allocation.allocated_amount) FILTER (WHERE (allocation.status = 'active'::text)), (0)::numeric)), 4) AS outstanding_amount,
            GREATEST((CURRENT_DATE - COALESCE(bill.due_date, bill.issue_date)), 0) AS days_overdue,
                CASE
                    WHEN (COALESCE(bill.due_date, bill.issue_date) >= CURRENT_DATE) THEN 'current'::text
                    WHEN (((CURRENT_DATE - COALESCE(bill.due_date, bill.issue_date)) >= 1) AND ((CURRENT_DATE - COALESCE(bill.due_date, bill.issue_date)) <= 30)) THEN '1_30'::text
                    WHEN (((CURRENT_DATE - COALESCE(bill.due_date, bill.issue_date)) >= 31) AND ((CURRENT_DATE - COALESCE(bill.due_date, bill.issue_date)) <= 60)) THEN '31_60'::text
                    WHEN (((CURRENT_DATE - COALESCE(bill.due_date, bill.issue_date)) >= 61) AND ((CURRENT_DATE - COALESCE(bill.due_date, bill.issue_date)) <= 90)) THEN '61_90'::text
                    ELSE '90_plus'::text
                END AS aging_bucket
           FROM ((public.supplier_bills bill
             LEFT JOIN public.vendors vendor ON ((vendor.id = bill.vendor_id)))
             LEFT JOIN public.supplier_payment_allocations allocation ON ((allocation.supplier_bill_id = bill.id)))
          WHERE ((bill.accounting_state = 'posted'::text) AND (COALESCE(bill.status, ''::text) <> ALL (ARRAY['reversed'::text, 'cancelled'::text])))
          GROUP BY bill.company_id, bill.branch_id, bill.vendor_id, bill.id, bill.bill_number, vendor.name, bill.issue_date, bill.due_date, bill.currency, bill.total_amount
         HAVING (round((bill.total_amount - COALESCE(sum(allocation.allocated_amount) FILTER (WHERE (allocation.status = 'active'::text)), (0)::numeric)), 4) <> (0)::numeric)) rbac_report
  WHERE private.has_company_permission(company_id, 'reports.operational'::text);


--
-- Name: operix_apps; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.operix_apps (
    app_key text NOT NULL,
    display_name text NOT NULL,
    description text,
    route text,
    icon_key text,
    available boolean DEFAULT true NOT NULL,
    subscription_requirement text,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT operix_apps_app_key_check CHECK ((app_key ~ '^[a-z0-9][a-z0-9_-]{1,48}$'::text))
);


--
-- Name: operix_ar_aging; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_ar_aging WITH (security_invoker='true') AS
 SELECT company_id,
    branch_id,
    client_id,
    invoice_id,
    invoice_number,
    issue_date,
    due_date,
    currency,
    original_amount,
    allocated_amount,
    outstanding_amount,
    days_overdue,
    aging_bucket
   FROM ( SELECT item.company_id,
            item.branch_id,
            item.client_id,
            item.invoice_id,
            item.invoice_number,
            item.issue_date,
            item.due_date,
            item.currency,
            item.original_amount,
            item.allocated_amount,
            item.outstanding_amount,
            item.days_overdue,
                CASE
                    WHEN (item.aging_bucket = 'not_due'::text) THEN 'current'::text
                    ELSE item.aging_bucket
                END AS aging_bucket
           FROM public.customer_receivable_open_items item) rbac_report
  WHERE private.has_company_permission(company_id, 'reports.operational'::text);


--
-- Name: operix_asset_register; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_asset_register WITH (security_invoker='true') AS
 SELECT company_id,
    fixed_asset_id,
    asset_number,
    name,
    category,
    supplier_id,
    acquisition_date,
    placed_in_service_date,
