--
-- Name: operix_balance_sheet; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_balance_sheet WITH (security_invoker='true') AS
 SELECT company_id,
    account_id,
    account_code,
    account_name,
    account_type,
    total_debit,
    total_credit,
    signed_balance,
    presentation_amount
   FROM ( SELECT ledger.company_id,
            ledger.account_id,
            ledger.account_code,
            ledger.account_name,
            ledger.account_type,
            round(sum(ledger.debit), 4) AS total_debit,
            round(sum(ledger.credit), 4) AS total_credit,
            round(sum((ledger.debit - ledger.credit)), 4) AS signed_balance,
            round(
                CASE
                    WHEN (ledger.account_type = ANY (ARRAY['liability'::text, 'equity'::text])) THEN sum((ledger.credit - ledger.debit))
                    ELSE sum((ledger.debit - ledger.credit))
                END, 4) AS presentation_amount
           FROM public.general_ledger_entries ledger
          WHERE (ledger.account_type = ANY (ARRAY['asset'::text, 'contra_asset'::text, 'liability'::text, 'equity'::text]))
          GROUP BY ledger.company_id, ledger.account_id, ledger.account_code, ledger.account_name, ledger.account_type) rbac_report
  WHERE private.has_company_permission(company_id, 'reports.operational'::text);


--
-- Name: operix_bank_reconciliation_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_bank_reconciliation_summary WITH (security_invoker='true') AS
 SELECT reconciliation.id,
    reconciliation.company_id,
    reconciliation.company_bank_account_id,
    account.name AS account_name,
    reconciliation.period_start,
    reconciliation.period_end,
    reconciliation.opening_balance,
    reconciliation.statement_closing_balance,
    reconciliation.gl_closing_balance,
    reconciliation.difference,
    reconciliation.status,
    count(statement.id) FILTER (WHERE (statement.status = 'unmatched'::text)) AS unmatched_transactions,
    (COALESCE(sum(statement.amount), (0)::numeric))::numeric(20,4) AS imported_statement_net
   FROM (((public.bank_reconciliations reconciliation
     JOIN public.company_bank_accounts bank ON ((bank.id = reconciliation.company_bank_account_id)))
     LEFT JOIN public.chart_of_accounts account ON ((account.id = bank.account_id)))
     LEFT JOIN public.bank_statement_transactions statement ON ((statement.reconciliation_id = reconciliation.id)))
  GROUP BY reconciliation.id, reconciliation.company_id, reconciliation.company_bank_account_id, account.name, reconciliation.period_start, reconciliation.period_end, reconciliation.opening_balance, reconciliation.statement_closing_balance, reconciliation.gl_closing_balance, reconciliation.difference, reconciliation.status;


--
-- Name: operix_cash_flow; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_cash_flow WITH (security_invoker='true') AS
 SELECT tx.company_id,
    tx.transaction_date,
    round(COALESCE(sum(tx.signed_amount) FILTER (WHERE ((tx.signed_amount > (0)::numeric) AND (tx.transaction_type <> ALL (ARRAY['transfer_in'::text, 'transfer_out'::text])))), (0)::numeric), 4) AS cash_in,
    round(COALESCE(sum(abs(tx.signed_amount)) FILTER (WHERE ((tx.signed_amount < (0)::numeric) AND (tx.transaction_type <> ALL (ARRAY['transfer_in'::text, 'transfer_out'::text])))), (0)::numeric), 4) AS cash_out,
    round(COALESCE(sum(tx.signed_amount) FILTER (WHERE (tx.transaction_type <> ALL (ARRAY['transfer_in'::text, 'transfer_out'::text]))), (0)::numeric), 4) AS net_cash_flow,
    (date_trunc('month'::text, (tx.transaction_date)::timestamp with time zone))::date AS period_start,
    COALESCE(fa.fund_type, 'other'::text) AS cash_account_type,
    round(COALESCE(sum(tx.signed_amount) FILTER (WHERE (tx.transaction_type <> ALL (ARRAY['transfer_in'::text, 'transfer_out'::text]))), (0)::numeric), 4) AS net_change
   FROM (public.company_fund_transactions tx
     LEFT JOIN public.company_fund_accounts fa ON ((fa.id = tx.fund_account_id)))
  WHERE ((tx.status = 'active'::text) AND private.has_company_permission(tx.company_id, 'financial_reports.view'::text))
  GROUP BY tx.company_id, tx.transaction_date, COALESCE(fa.fund_type, 'other'::text);


--
-- Name: operix_changes_in_equity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_changes_in_equity WITH (security_invoker='true') AS
 SELECT company_id,
    period_start,
    account_id,
    account_code,
    account_name,
    change_amount
   FROM ( SELECT ledger.company_id,
            (date_trunc('month'::text, (ledger.posting_date)::timestamp with time zone))::date AS period_start,
            ledger.account_id,
            ledger.account_code,
            ledger.account_name,
            round(sum((ledger.credit - ledger.debit)), 4) AS change_amount
           FROM public.general_ledger_entries ledger
          WHERE (ledger.account_type = 'equity'::text)
          GROUP BY ledger.company_id, ((date_trunc('month'::text, (ledger.posting_date)::timestamp with time zone))::date), ledger.account_id, ledger.account_code, ledger.account_name) rbac_report
  WHERE private.has_company_permission(company_id, 'reports.operational'::text);


--
-- Name: operix_expense_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_expense_summary WITH (security_invoker='true') AS
 SELECT company_id,
    expense_count,
    net_amount,
    vat_amount,
    gross_amount,
    paid_amount,
    outstanding_amount,
    deductible_amount,
    non_deductible_amount,
    recoverable_vat,
    missing_documentation
   FROM ( SELECT e.company_id,
            count(*) FILTER (WHERE (e.archived_at IS NULL)) AS expense_count,
            (COALESCE(sum(e.net_amount) FILTER (WHERE (e.archived_at IS NULL)), (0)::numeric))::numeric(20,4) AS net_amount,
            (COALESCE(sum(e.vat_amount) FILTER (WHERE (e.archived_at IS NULL)), (0)::numeric))::numeric(20,4) AS vat_amount,
            (COALESCE(sum(e.gross_amount) FILTER (WHERE (e.archived_at IS NULL)), (0)::numeric))::numeric(20,4) AS gross_amount,
            (COALESCE(sum(e.paid_amount) FILTER (WHERE (e.archived_at IS NULL)), (0)::numeric))::numeric(20,4) AS paid_amount,
            (COALESCE(sum(e.outstanding_amount) FILTER (WHERE (e.archived_at IS NULL)), (0)::numeric))::numeric(20,4) AS outstanding_amount,
            (COALESCE(sum(e.tax_deductible_amount) FILTER (WHERE (e.archived_at IS NULL)), (0)::numeric))::numeric(20,4) AS deductible_amount,
            (COALESCE(sum(e.tax_non_deductible_amount) FILTER (WHERE (e.archived_at IS NULL)), (0)::numeric))::numeric(20,4) AS non_deductible_amount,
            (COALESCE(sum(e.vat_deductible_amount) FILTER (WHERE (e.archived_at IS NULL)), (0)::numeric))::numeric(20,4) AS recoverable_vat,
            count(*) FILTER (WHERE ((e.archived_at IS NULL) AND (e.documentation_status <> 'complete'::text))) AS missing_documentation
           FROM public.expenses e
          GROUP BY e.company_id) rbac_report
  WHERE private.has_company_permission(company_id, 'reports.operational'::text);


--
-- Name: operix_financial_account_balances; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_financial_account_balances WITH (security_invoker='true') AS
 SELECT fund.id,
    fund.company_id,
    fund.name,
    fund.account_type,
    fund.fund_type,
    fund.currency,
    fund.opening_balance,
    round((fund.opening_balance + COALESCE(sum(tx.signed_amount) FILTER (WHERE (tx.status = 'active'::text)), (0)::numeric)), 4) AS current_balance,
    round((fund.opening_balance + COALESCE(sum(tx.signed_amount) FILTER (WHERE ((tx.status = 'active'::text) AND (tx.reconciliation_status = 'reconciled'::text))), (0)::numeric)), 4) AS reconciled_balance,
    round(COALESCE(sum(tx.signed_amount) FILTER (WHERE ((tx.status = 'active'::text) AND (tx.reconciliation_status <> 'reconciled'::text))), (0)::numeric), 4) AS unreconciled_balance,
    fund.is_active
   FROM (public.company_fund_accounts fund
     LEFT JOIN public.company_fund_transactions tx ON ((tx.fund_account_id = fund.id)))
  WHERE (fund.is_active AND private.has_company_permission(fund.company_id, 'financial_reports.view'::text))
  GROUP BY fund.id, fund.company_id, fund.name, fund.account_type, fund.fund_type, fund.currency, fund.opening_balance, fund.is_active;


--
-- Name: operix_financial_account_transactions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_financial_account_transactions WITH (security_invoker='true') AS
 SELECT tx.id,
    tx.company_id,
    tx.fund_account_id,
    fund.name AS account_name,
    fund.account_type,
    fund.currency AS account_currency,
    tx.transaction_type,
    tx.signed_amount,
    tx.currency,
    tx.transaction_date,
    tx.description,
    tx.source_type,
    tx.source_id,
    tx.payment_method,
    tx.reference,
    tx.counterparty,
    tx.reconciliation_status,
    tx.status,
    tx.created_at,
    tx.created_by
   FROM (public.company_fund_transactions tx
     JOIN public.company_fund_accounts fund ON ((fund.id = tx.fund_account_id)))
  WHERE private.has_company_permission(tx.company_id, 'financial_reports.view'::text);


--
-- Name: operix_financial_drilldown; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_financial_drilldown WITH (security_invoker='true') AS
 SELECT company_id,
    journal_entry_id,
    entry_number,
    posting_date,
    document_date,
    account_id,
    account_code,
    account_name,
    account_type,
    description,
    debit,
    credit,
    signed_amount,
    source_type,
    source_id,
    transaction_type,
    transaction_reference,
    original_document_id
   FROM ( SELECT ledger.company_id,
            ledger.journal_entry_id,
            ledger.entry_number,
            ledger.posting_date,
            ledger.document_date,
            ledger.account_id,
            ledger.account_code,
            ledger.account_name,
            ledger.account_type,
            ledger.description,
            ledger.debit,
            ledger.credit,
            ledger.signed_amount,
            COALESCE(ledger.source_type, journal.entry_type) AS source_type,
            ledger.source_id,
                CASE
                    WHEN (invoice.id IS NOT NULL) THEN 'invoice'::text
                    WHEN (bill.id IS NOT NULL) THEN 'supplier_bill'::text
                    WHEN (expense.id IS NOT NULL) THEN 'expense'::text
                    WHEN (payment.id IS NOT NULL) THEN 'customer_payment'::text
                    WHEN (vendor_payment.id IS NOT NULL) THEN 'supplier_payment'::text
                    WHEN (payroll.id IS NOT NULL) THEN 'payroll'::text
                    WHEN (asset.id IS NOT NULL) THEN 'fixed_asset'::text
                    ELSE COALESCE(ledger.source_type, journal.entry_type)
                END AS transaction_type,
            COALESCE(invoice.invoice_number, bill.bill_number, expense.description, payment.payment_number, vendor_payment.payment_number, payroll.run_number, asset.asset_number, ledger.reference) AS transaction_reference,
                CASE
                    WHEN (archive.id IS NOT NULL) THEN archive.id
                    ELSE NULL::uuid
                END AS original_document_id
           FROM (((((((((public.general_ledger_entries ledger
             JOIN public.journal_entries journal ON ((journal.id = ledger.journal_entry_id)))
             LEFT JOIN public.invoices invoice ON (((invoice.id = ledger.source_id) AND (ledger.source_type = ANY (ARRAY['sales_invoice'::text, 'pos_invoice'::text])))))
             LEFT JOIN public.supplier_bills bill ON (((bill.id = ledger.source_id) AND (ledger.source_type = 'supplier_bill'::text))))
             LEFT JOIN public.expenses expense ON (((expense.id = ledger.source_id) AND (ledger.source_type = 'expense'::text))))
             LEFT JOIN public.payments payment ON (((payment.id = ledger.source_id) AND (ledger.source_type = ANY (ARRAY['customer_payment'::text, 'payment'::text])))))
             LEFT JOIN public.vendor_payments vendor_payment ON (((vendor_payment.id = ledger.source_id) AND (ledger.source_type = ANY (ARRAY['supplier_payment'::text, 'vendor_payment'::text])))))
             LEFT JOIN public.payroll_runs payroll ON (((payroll.id = ledger.source_id) AND (ledger.source_type = 'payroll_run'::text))))
             LEFT JOIN public.fixed_assets asset ON (((asset.id = ledger.source_id) AND (ledger.source_type ~~ 'fixed_asset%'::text))))
             LEFT JOIN LATERAL ( SELECT document.id
                   FROM public.document_archive document
                  WHERE ((document.company_id = ledger.company_id) AND (document.source_id = ledger.source_id) AND (document.status = 'active'::text))
                  ORDER BY document.uploaded_at DESC
                 LIMIT 1) archive ON (true))) rbac_report
  WHERE private.has_company_permission(company_id, 'reports.profit'::text);


--
-- Name: operix_profit_loss; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_profit_loss WITH (security_invoker='true') AS
 SELECT company_id,
    period_start,
    account_id,
    account_code,
    account_name,
    account_type,
    total_debit,
    total_credit,
    presentation_amount
   FROM ( SELECT ledger.company_id,
            (date_trunc('month'::text, (ledger.posting_date)::timestamp with time zone))::date AS period_start,
            ledger.account_id,
            ledger.account_code,
            ledger.account_name,
            ledger.account_type,
            round(sum(ledger.debit), 4) AS total_debit,
            round(sum(ledger.credit), 4) AS total_credit,
            round(
                CASE
                    WHEN (ledger.account_type = ANY (ARRAY['revenue'::text, 'contra_revenue'::text])) THEN sum((ledger.credit - ledger.debit))
                    ELSE sum((ledger.debit - ledger.credit))
                END, 4) AS presentation_amount
           FROM public.general_ledger_entries ledger
          WHERE (ledger.account_type = ANY (ARRAY['revenue'::text, 'contra_revenue'::text, 'expense'::text]))
          GROUP BY ledger.company_id, ((date_trunc('month'::text, (ledger.posting_date)::timestamp with time zone))::date), ledger.account_id, ledger.account_code, ledger.account_name, ledger.account_type) rbac_report
  WHERE private.has_company_permission(company_id, 'reports.profit'::text);


--
-- Name: trial_balance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.trial_balance WITH (security_invoker='true') AS
 SELECT company_id,
    account_id,
    account_code,
    account_name,
    account_type,
    min(posting_date) AS first_posting_date,
    max(posting_date) AS last_posting_date,
    (sum(debit))::numeric(20,4) AS total_debit,
    (sum(credit))::numeric(20,4) AS total_credit,
    (sum((debit - credit)))::numeric(20,4) AS balance
   FROM public.general_ledger_entries ledger
  GROUP BY company_id, account_id, account_code, account_name, account_type;


--
-- Name: operix_financial_reconciliation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_financial_reconciliation WITH (security_invoker='true') AS
 WITH tb AS (
         SELECT trial_balance.company_id,
            (COALESCE(sum(trial_balance.total_debit), (0)::numeric))::numeric(20,4) AS total_debit,
            (COALESCE(sum(trial_balance.total_credit), (0)::numeric))::numeric(20,4) AS total_credit
           FROM public.trial_balance
          GROUP BY trial_balance.company_id
        ), bs AS (
         SELECT operix_balance_sheet.company_id,
            (COALESCE(sum(operix_balance_sheet.presentation_amount) FILTER (WHERE (operix_balance_sheet.account_type = ANY (ARRAY['asset'::text, 'contra_asset'::text]))), (0)::numeric))::numeric(20,4) AS assets,
            (COALESCE(sum(operix_balance_sheet.presentation_amount) FILTER (WHERE (operix_balance_sheet.account_type = ANY (ARRAY['liability'::text, 'equity'::text]))), (0)::numeric))::numeric(20,4) AS liabilities_equity
           FROM public.operix_balance_sheet
          GROUP BY operix_balance_sheet.company_id
        ), pl AS (
         SELECT operix_profit_loss.company_id,
            (COALESCE(sum(
                CASE
                    WHEN (operix_profit_loss.account_type = ANY (ARRAY['revenue'::text, 'contra_revenue'::text])) THEN operix_profit_loss.presentation_amount
                    ELSE (- operix_profit_loss.presentation_amount)
                END), (0)::numeric))::numeric(20,4) AS net_profit
           FROM public.operix_profit_loss
          GROUP BY operix_profit_loss.company_id
        ), ar_gl AS (
         SELECT trial_balance.company_id,
            (COALESCE(sum(trial_balance.balance), (0)::numeric))::numeric(20,4) AS gl_balance
           FROM public.trial_balance
          WHERE (trial_balance.account_code = '1100'::text)
          GROUP BY trial_balance.company_id
        ), ar_sub AS (
         SELECT operix_ar_aging.company_id,
            (COALESCE(sum(operix_ar_aging.outstanding_amount), (0)::numeric))::numeric(20,4) AS subledger_balance
           FROM public.operix_ar_aging
          GROUP BY operix_ar_aging.company_id
        ), ap_gl AS (
         SELECT trial_balance.company_id,
            (COALESCE((- sum(trial_balance.balance)), (0)::numeric))::numeric(20,4) AS gl_balance
           FROM public.trial_balance
          WHERE (trial_balance.account_code = '2010'::text)
          GROUP BY trial_balance.company_id
        ), ap_sub AS (
         SELECT operix_ap_open_items.company_id,
            (COALESCE(sum(operix_ap_open_items.outstanding_amount), (0)::numeric))::numeric(20,4) AS subledger_balance
           FROM public.operix_ap_open_items
          GROUP BY operix_ap_open_items.company_id
        ), inv AS (
         SELECT inventory_gl_reconciliation.company_id,
            inventory_gl_reconciliation.difference
           FROM public.inventory_gl_reconciliation
        ), assets AS (
         SELECT company_1.id AS company_id,
            (COALESCE(( SELECT sum(asset.acquisition_cost) AS sum
                   FROM public.fixed_assets asset
                  WHERE ((asset.company_id = company_1.id) AND (asset.status = 'active'::text))), (0)::numeric))::numeric(20,4) AS register_gross,
            (COALESCE(( SELECT sum(asset.accumulated_book_depreciation) AS sum
                   FROM public.fixed_assets asset
                  WHERE ((asset.company_id = company_1.id) AND (asset.status = 'active'::text))), (0)::numeric))::numeric(20,4) AS register_accumulated,
            (COALESCE(( SELECT trial_balance.balance
                   FROM public.trial_balance
                  WHERE ((trial_balance.company_id = company_1.id) AND (trial_balance.account_code = '1500'::text))), (0)::numeric))::numeric(20,4) AS gl_gross,
            (COALESCE(( SELECT (- trial_balance.balance)
                   FROM public.trial_balance
                  WHERE ((trial_balance.company_id = company_1.id) AND (trial_balance.account_code = '1590'::text))), (0)::numeric))::numeric(20,4) AS gl_accumulated
           FROM public.companies company_1
        ), vat AS (
         SELECT kosovo_tax_book_reconciliation.company_id,
            kosovo_tax_book_reconciliation.output_vat_difference,
            kosovo_tax_book_reconciliation.recoverable_vat_difference
           FROM public.kosovo_tax_book_reconciliation
        ), cash AS (
         SELECT company_1.id AS company_id,
            (COALESCE(( SELECT trial_balance.balance
                   FROM public.trial_balance
                  WHERE ((trial_balance.company_id = company_1.id) AND (trial_balance.account_code = '1010'::text))), (0)::numeric))::numeric(20,4) AS gl_cash,
            (COALESCE(( SELECT sum((general_ledger_entries.debit - general_ledger_entries.credit)) AS sum
                   FROM public.general_ledger_entries
                  WHERE ((general_ledger_entries.company_id = company_1.id) AND (general_ledger_entries.account_code = '1010'::text))), (0)::numeric))::numeric(20,4) AS cash_book
           FROM public.companies company_1
        )
 SELECT company.id AS company_id,
    COALESCE(tb.total_debit, (0)::numeric) AS trial_balance_debit,
    COALESCE(tb.total_credit, (0)::numeric) AS trial_balance_credit,
    round((COALESCE(tb.total_debit, (0)::numeric) - COALESCE(tb.total_credit, (0)::numeric)), 4) AS trial_balance_difference,
    COALESCE(bs.assets, (0)::numeric) AS balance_sheet_assets,
    (COALESCE(bs.liabilities_equity, (0)::numeric) + COALESCE(pl.net_profit, (0)::numeric)) AS balance_sheet_liabilities_equity,
    round((COALESCE(bs.assets, (0)::numeric) - (COALESCE(bs.liabilities_equity, (0)::numeric) + COALESCE(pl.net_profit, (0)::numeric))), 4) AS balance_sheet_difference,
    COALESCE(ar_sub.subledger_balance, (0)::numeric) AS ar_subledger,
    COALESCE(ar_gl.gl_balance, (0)::numeric) AS ar_gl,
    round((COALESCE(ar_sub.subledger_balance, (0)::numeric) - COALESCE(ar_gl.gl_balance, (0)::numeric)), 4) AS ar_difference,
    COALESCE(ap_sub.subledger_balance, (0)::numeric) AS ap_subledger,
    COALESCE(ap_gl.gl_balance, (0)::numeric) AS ap_gl,
    round((COALESCE(ap_sub.subledger_balance, (0)::numeric) - COALESCE(ap_gl.gl_balance, (0)::numeric)), 4) AS ap_difference,
    COALESCE(inv.difference, (0)::numeric) AS inventory_difference,
    round((COALESCE(assets.register_gross, (0)::numeric) - COALESCE(assets.gl_gross, (0)::numeric)), 4) AS assets_gross_difference,
    round((COALESCE(assets.register_accumulated, (0)::numeric) - COALESCE(assets.gl_accumulated, (0)::numeric)), 4) AS assets_accumulated_difference,
    COALESCE(vat.output_vat_difference, (0)::numeric) AS output_vat_difference,
    COALESCE(vat.recoverable_vat_difference, (0)::numeric) AS recoverable_vat_difference,
    round((COALESCE(cash.gl_cash, (0)::numeric) - COALESCE(cash.cash_book, (0)::numeric)), 4) AS cash_difference,
    ((abs(round((COALESCE(tb.total_debit, (0)::numeric) - COALESCE(tb.total_credit, (0)::numeric)), 4)) <= 0.0001) AND (abs(round((COALESCE(bs.assets, (0)::numeric) - (COALESCE(bs.liabilities_equity, (0)::numeric) + COALESCE(pl.net_profit, (0)::numeric))), 4)) <= 0.0001) AND (abs(round((COALESCE(ar_sub.subledger_balance, (0)::numeric) - COALESCE(ar_gl.gl_balance, (0)::numeric)), 4)) <= 0.0001) AND (abs(round((COALESCE(ap_sub.subledger_balance, (0)::numeric) - COALESCE(ap_gl.gl_balance, (0)::numeric)), 4)) <= 0.0001) AND (abs(COALESCE(inv.difference, (0)::numeric)) <= 0.0001) AND (abs(round((COALESCE(assets.register_gross, (0)::numeric) - COALESCE(assets.gl_gross, (0)::numeric)), 4)) <= 0.0001) AND (abs(round((COALESCE(assets.register_accumulated, (0)::numeric) - COALESCE(assets.gl_accumulated, (0)::numeric)), 4)) <= 0.0001) AND (abs(COALESCE(vat.output_vat_difference, (0)::numeric)) <= 0.0001) AND (abs(COALESCE(vat.recoverable_vat_difference, (0)::numeric)) <= 0.0001) AND (abs(round((COALESCE(cash.gl_cash, (0)::numeric) - COALESCE(cash.cash_book, (0)::numeric)), 4)) <= 0.0001)) AS reconciles
   FROM (((((((((((public.companies company
     LEFT JOIN tb ON ((tb.company_id = company.id)))
     LEFT JOIN bs ON ((bs.company_id = company.id)))
     LEFT JOIN pl ON ((pl.company_id = company.id)))
     LEFT JOIN ar_gl ON ((ar_gl.company_id = company.id)))
     LEFT JOIN ar_sub ON ((ar_sub.company_id = company.id)))
     LEFT JOIN ap_gl ON ((ap_gl.company_id = company.id)))
     LEFT JOIN ap_sub ON ((ap_sub.company_id = company.id)))
     LEFT JOIN inv ON ((inv.company_id = company.id)))
     LEFT JOIN assets ON ((assets.company_id = company.id)))
     LEFT JOIN vat ON ((vat.company_id = company.id)))
     LEFT JOIN cash ON ((cash.company_id = company.id)));


--
-- Name: stripe_balance_snapshots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.stripe_balance_snapshots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    stripe_store_id uuid NOT NULL,
    company_id uuid NOT NULL,
    currency text NOT NULL,
    available_balance numeric(20,4) DEFAULT 0 NOT NULL,
    pending_balance numeric(20,4) DEFAULT 0 NOT NULL,
    as_of timestamp with time zone DEFAULT now() NOT NULL,
    raw_balance jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT stripe_balance_snapshots_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text))
);


--
-- Name: operix_fund_balances; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_fund_balances WITH (security_invoker='true') AS
 WITH raw_balances AS (
         SELECT fund.id,
            fund.company_id AS owner_company_id,
            fund.fund_type,
            fund.company_bank_account_id,
            fund.stripe_store_id,
            fund.name,
            fund.currency,
            fund.opening_balance,
            (COALESCE(sum(fund_tx.signed_amount) FILTER (WHERE (fund_tx.status = 'active'::text)), (0)::numeric))::numeric(20,4) AS transaction_total,
            ((fund.opening_balance + COALESCE(sum(fund_tx.signed_amount) FILTER (WHERE (fund_tx.status = 'active'::text)), (0)::numeric)))::numeric(20,4) AS balance,
            snapshot.available_balance AS provider_available_balance,
            snapshot.pending_balance AS provider_pending_balance,
            snapshot.as_of AS provider_balance_as_of,
            fund.is_active,
            row_number() OVER (PARTITION BY fund.company_id, fund.fund_type ORDER BY fund.id) AS fund_type_rank
           FROM ((public.company_fund_accounts fund
             LEFT JOIN public.company_fund_transactions fund_tx ON ((fund_tx.fund_account_id = fund.id)))
             LEFT JOIN public.stripe_balance_snapshots snapshot ON (((snapshot.stripe_store_id = fund.stripe_store_id) AND (snapshot.currency = fund.currency))))
          GROUP BY fund.id, fund.company_id, fund.fund_type, fund.company_bank_account_id, fund.stripe_store_id, fund.name, fund.currency, fund.opening_balance, snapshot.available_balance, snapshot.pending_balance, snapshot.as_of, fund.is_active
        ), agent_sales AS (
         SELECT invoice.company_id,
            (COALESCE(sum(invoice.total_amount), (0)::numeric))::numeric(20,4) AS sales_amount
           FROM public.invoices invoice
          WHERE ((invoice.accounting_state = 'posted'::text) AND (COALESCE(invoice.post_cod, false) = false) AND (lower(COALESCE(invoice.payment_method, ''::text)) = 'cash'::text) AND (lower(COALESCE(invoice.type, ''::text)) = ANY (ARRAY['invoice'::text, 'final_invoice'::text, 'advance_invoice'::text, 'simplified_invoice'::text])) AND (lower(COALESCE((invoice.status)::text, ''::text)) <> ALL (ARRAY['cancelled'::text, 'credited'::text, 'reversed'::text])))
          GROUP BY invoice.company_id
        ), agent_settled AS (
         SELECT agent_settlements.company_id,
            (COALESCE(sum(agent_settlements.amount), (0)::numeric))::numeric(20,4) AS settled_amount
           FROM public.agent_settlements
          WHERE (agent_settlements.status = 'active'::text)
          GROUP BY agent_settlements.company_id
        ), cod_sales AS (
         SELECT invoices.company_id,
            (COALESCE(sum(invoices.total_amount), (0)::numeric))::numeric(20,4) AS sales_amount
           FROM public.invoices
          WHERE ((invoices.accounting_state = 'posted'::text) AND (invoices.post_cod = true) AND (lower(COALESCE(invoices.type, ''::text)) = ANY (ARRAY['invoice'::text, 'final_invoice'::text, 'advance_invoice'::text, 'simplified_invoice'::text])) AND (lower(COALESCE((invoices.status)::text, ''::text)) <> ALL (ARRAY['cancelled'::text, 'credited'::text, 'reversed'::text])))
          GROUP BY invoices.company_id
        ), cod_settled AS (
         SELECT post_cod_settlements.company_id,
            (COALESCE(sum(post_cod_settlements.amount), (0)::numeric))::numeric(20,4) AS settled_amount
           FROM public.post_cod_settlements
          WHERE (post_cod_settlements.status = 'active'::text)
          GROUP BY post_cod_settlements.company_id
        ), pending_by_company AS (
         SELECT COALESCE(agent_sales.company_id, cod_sales.company_id) AS company_id,
            (GREATEST((COALESCE(agent_sales.sales_amount, (0)::numeric) - COALESCE(agent_settled.settled_amount, (0)::numeric)), (0)::numeric) + GREATEST((COALESCE(cod_sales.sales_amount, (0)::numeric) - COALESCE(cod_settled.settled_amount, (0)::numeric)), (0)::numeric)) AS cash_pending,
            (0)::numeric(20,4) AS bank_pending
           FROM (((agent_sales
             FULL JOIN cod_sales ON ((cod_sales.company_id = agent_sales.company_id)))
             LEFT JOIN agent_settled ON ((agent_settled.company_id = COALESCE(agent_sales.company_id, cod_sales.company_id))))
             LEFT JOIN cod_settled ON ((cod_settled.company_id = COALESCE(agent_sales.company_id, cod_sales.company_id))))
        ), balances_with_pending AS (
         SELECT raw.id,
            raw.owner_company_id,
            raw.fund_type,
            raw.company_bank_account_id,
            raw.stripe_store_id,
            raw.name,
            raw.currency,
            raw.opening_balance,
            raw.transaction_total,
            raw.balance,
            raw.provider_available_balance,
            raw.provider_pending_balance,
            raw.provider_balance_as_of,
            raw.is_active,
            raw.fund_type_rank,
                CASE
                    WHEN ((raw.stripe_store_id IS NOT NULL) OR (raw.fund_type <> ALL (ARRAY['cash'::text, 'bank'::text])) OR (raw.fund_type_rank <> 1)) THEN (0)::numeric(20,4)
                    WHEN (raw.fund_type = 'cash'::text) THEN (COALESCE(pending.cash_pending, (0)::numeric))::numeric(20,4)
                    ELSE (COALESCE(pending.bank_pending, (0)::numeric))::numeric(20,4)
                END AS pending_balance
           FROM (raw_balances raw
             LEFT JOIN pending_by_company pending ON ((pending.company_id = raw.owner_company_id)))
        )
 SELECT balances.id,
    balances.owner_company_id AS company_id,
    balances.owner_company_id,
    balances.fund_type,
    balances.company_bank_account_id,
    balances.stripe_store_id,
    balances.name,
    balances.currency,
    balances.opening_balance,
    balances.transaction_total,
    balances.balance,
    balances.provider_available_balance,
    balances.provider_pending_balance,
    balances.provider_balance_as_of,
    balances.pending_balance,
    ((balances.balance - balances.pending_balance))::numeric(20,4) AS available_balance,
    balances.is_active,
    false AS is_shared
   FROM balances_with_pending balances
UNION ALL
 SELECT balances.id,
    share.shared_company_id AS company_id,
    balances.owner_company_id,
    balances.fund_type,
    balances.company_bank_account_id,
    balances.stripe_store_id,
    balances.name,
    balances.currency,
    balances.opening_balance,
    balances.transaction_total,
    balances.balance,
    balances.provider_available_balance,
    balances.provider_pending_balance,
    balances.provider_balance_as_of,
    balances.pending_balance,
    ((balances.balance - balances.pending_balance))::numeric(20,4) AS available_balance,
    balances.is_active,
    true AS is_shared
   FROM (balances_with_pending balances
     JOIN public.company_bank_account_shares share ON (((share.company_bank_account_id = balances.company_bank_account_id) AND share.is_active)));


--
-- Name: operix_general_ledger; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_general_ledger WITH (security_invoker='true') AS
 SELECT company_id,
    journal_entry_id,
    entry_number,
    posting_date,
    document_date,
    journal_description,
    reference,
    source_type,
    source_id,
    journal_line_id,
    line_number,
    account_id,
    account_code,
    account_name,
    account_type,
    description,
    debit,
    credit,
    signed_amount,
    cost_centre_id,
    project_id,
    branch_id,
    tax_code,
    tax_base,
    tax_amount
   FROM ( SELECT general_ledger_entries.company_id,
            general_ledger_entries.journal_entry_id,
            general_ledger_entries.entry_number,
            general_ledger_entries.posting_date,
            general_ledger_entries.document_date,
            general_ledger_entries.journal_description,
            general_ledger_entries.reference,
            general_ledger_entries.source_type,
            general_ledger_entries.source_id,
            general_ledger_entries.journal_line_id,
            general_ledger_entries.line_number,
            general_ledger_entries.account_id,
            general_ledger_entries.account_code,
            general_ledger_entries.account_name,
            general_ledger_entries.account_type,
            general_ledger_entries.description,
            general_ledger_entries.debit,
            general_ledger_entries.credit,
            general_ledger_entries.signed_amount,
            general_ledger_entries.cost_centre_id,
            general_ledger_entries.project_id,
            general_ledger_entries.branch_id,
            general_ledger_entries.tax_code,
            general_ledger_entries.tax_base,
            general_ledger_entries.tax_amount
           FROM public.general_ledger_entries) rbac_report
  WHERE private.has_company_permission(company_id, 'reports.operational'::text);


--
-- Name: operix_income_report; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_income_report WITH (security_invoker='true') AS
 SELECT invoice.company_id,
    invoice.issue_date AS income_date,
    'sales_invoice'::text AS source_type,
    invoice.id AS source_id,
    invoice.currency,
    round(invoice.total_amount, 4) AS amount
   FROM public.invoices invoice
  WHERE ((invoice.accounting_state = 'posted'::text) AND private.has_company_permission(invoice.company_id, 'financial_reports.view'::text) AND (invoice.commercial_document_type = ANY (ARRAY['INVOICE'::text, 'FINAL_INVOICE'::text, 'ADVANCE_INVOICE'::text, 'SIMPLIFIED_INVOICE'::text])))
UNION ALL
 SELECT income.company_id,
    income.income_date,
    'other_income'::text AS source_type,
    income.id AS source_id,
    income.currency,
    income.gross_amount AS amount
   FROM public.other_income income
  WHERE ((income.accounting_state = 'posted'::text) AND private.has_company_permission(income.company_id, 'financial_reports.view'::text));


--
-- Name: operix_intelligence_notifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.operix_intelligence_notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    company_id uuid NOT NULL,
    insight_key text NOT NULL,
    category text NOT NULL,
    priority text NOT NULL,
    title text NOT NULL,
    body text NOT NULL,
    target_type text NOT NULL,
    target_id uuid,
    target_params jsonb DEFAULT '{}'::jsonb NOT NULL,
    read_at timestamp with time zone,
    dismissed_at timestamp with time zone,
    resolved_at timestamp with time zone,
    last_surfaced_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT operix_intelligence_notifications_body_check CHECK (((char_length(body) >= 1) AND (char_length(body) <= 800))),
    CONSTRAINT operix_intelligence_notifications_category_check CHECK ((category = ANY (ARRAY['invoice'::text, 'customer'::text, 'inventory'::text, 'sales'::text, 'payment'::text, 'duplicate'::text]))),
    CONSTRAINT operix_intelligence_notifications_insight_key_check CHECK (((char_length(insight_key) >= 1) AND (char_length(insight_key) <= 240))),
    CONSTRAINT operix_intelligence_notifications_priority_check CHECK ((priority = ANY (ARRAY['info'::text, 'attention'::text, 'important'::text]))),
    CONSTRAINT operix_intelligence_notifications_target_params_check CHECK ((jsonb_typeof(target_params) = 'object'::text)),
    CONSTRAINT operix_intelligence_notifications_target_type_check CHECK ((target_type = ANY (ARRAY['invoice'::text, 'customer'::text, 'product'::text, 'invoices'::text, 'products'::text, 'expenses'::text, 'sales'::text, 'payments'::text, 'notifications'::text]))),
    CONSTRAINT operix_intelligence_notifications_title_check CHECK (((char_length(title) >= 1) AND (char_length(title) <= 180)))
);


--
-- Name: operix_notification_delivery_keys; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.operix_notification_delivery_keys (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    user_id uuid NOT NULL,
    event_key text NOT NULL,
    notification_type text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: operix_payment_report; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_payment_report WITH (security_invoker='true') AS
 SELECT payment.company_id,
    payment.id,
    payment.payment_number,
    payment.payment_date,
    payment.amount,
    payment.currency,
    payment.payment_method,
    payment.fund_account_id,
    payment.external_reference,
    payment.client_id AS customer_id,
    'customer_payment'::text AS source_type
   FROM public.payments payment
  WHERE ((payment.accounting_state = 'posted'::text) AND (payment.payment_status = 'posted'::text) AND private.has_company_permission(payment.company_id, 'financial_reports.view'::text))
UNION ALL
 SELECT payment.company_id,
    payment.id,
    payment.payment_number,
    payment.payment_date,
    payment.amount,
    payment.currency,
    payment.payment_method,
    payment.settlement_account_id AS fund_account_id,
    payment.bank_reference AS external_reference,
    payment.vendor_id AS customer_id,
    'supplier_payment'::text AS source_type
   FROM public.vendor_payments payment
  WHERE ((payment.accounting_state = 'posted'::text) AND private.has_company_permission(payment.company_id, 'financial_reports.view'::text));


--
-- Name: operix_push_device_tokens; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.operix_push_device_tokens (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    company_id uuid NOT NULL,
    expo_push_token text NOT NULL,
    platform text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT operix_push_device_tokens_expo_push_token_check CHECK (((char_length(expo_push_token) >= 10) AND (char_length(expo_push_token) <= 512))),
    CONSTRAINT operix_push_device_tokens_platform_check CHECK ((platform = ANY (ARRAY['ios'::text, 'android'::text, 'web'::text])))
);


--
-- Name: operix_report_gross_sales; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_report_gross_sales WITH (security_invoker='true') AS
 SELECT company_id,
    gross_sales
   FROM ( SELECT invoice.company_id,
            (COALESCE(sum(invoice.total_amount) FILTER (WHERE (((invoice.status)::text <> ALL (ARRAY['cancelled'::text, 'reversed'::text, 'credited'::text])) AND (COALESCE(upper(NULLIF(TRIM(BOTH FROM invoice.commercial_status), ''::text)), ''::text) <> ALL (ARRAY['CANCELLED'::text, 'CREDITED'::text, 'REVERSED'::text])) AND (
                CASE
                    WHEN (NULLIF(TRIM(BOTH FROM invoice.commercial_document_type), ''::text) IS NOT NULL) THEN upper(TRIM(BOTH FROM invoice.commercial_document_type))
                    WHEN ((lower(TRIM(BOTH FROM COALESCE(invoice.subtype, ''::text))) = 'offer'::text) OR ((lower(TRIM(BOTH FROM COALESCE(invoice.type, ''::text))) = 'offer'::text) AND (NULLIF(TRIM(BOTH FROM invoice.subtype), ''::text) IS NULL))) THEN 'QUOTE'::text
                    WHEN ((lower(TRIM(BOTH FROM COALESCE(invoice.subtype, ''::text))) = ANY (ARRAY['pro_invoice'::text, 'proforma'::text])) OR (lower(TRIM(BOTH FROM COALESCE(invoice.type, ''::text))) = 'proforma'::text)) THEN 'PROFORMA'::text
                    WHEN ((lower(TRIM(BOTH FROM COALESCE(invoice.subtype, ''::text))) = 'order'::text) OR (lower(TRIM(BOTH FROM COALESCE(invoice.type, ''::text))) = 'order'::text)) THEN 'SALES_ORDER'::text
                    WHEN (lower(TRIM(BOTH FROM COALESCE(invoice.subtype, ''::text))) = 'delivery_note'::text) THEN 'DELIVERY_NOTE'::text
                    WHEN (lower(TRIM(BOTH FROM COALESCE(invoice.subtype, ''::text))) = 'advance_invoice'::text) THEN 'ADVANCE_INVOICE'::text
                    WHEN (lower(TRIM(BOTH FROM COALESCE(invoice.subtype, ''::text))) = 'final_invoice'::text) THEN 'FINAL_INVOICE'::text
                    WHEN (lower(TRIM(BOTH FROM COALESCE(invoice.subtype, ''::text))) = 'credit_note'::text) THEN 'CREDIT_NOTE'::text
                    WHEN (lower(TRIM(BOTH FROM COALESCE(invoice.subtype, ''::text))) = 'debit_note'::text) THEN 'DEBIT_NOTE'::text
                    WHEN (lower(TRIM(BOTH FROM COALESCE(invoice.subtype, ''::text))) = 'simplified_invoice'::text) THEN 'SIMPLIFIED_INVOICE'::text
                    WHEN (lower(TRIM(BOTH FROM COALESCE(invoice.subtype, ''::text))) = 'fiscal_receipt'::text) THEN 'FISCAL_RECEIPT'::text
                    WHEN (lower(TRIM(BOTH FROM COALESCE(invoice.subtype, ''::text))) = 'bad_debt_invoice'::text) THEN 'BAD_DEBT_INVOICE'::text
                    ELSE 'INVOICE'::text
                END = ANY (ARRAY['INVOICE'::text, 'FINAL_INVOICE'::text, 'ADVANCE_INVOICE'::text, 'SIMPLIFIED_INVOICE'::text])))), (0)::numeric))::numeric(20,4) AS gross_sales
           FROM public.invoices invoice
          WHERE (invoice.accounting_state = 'posted'::text)
          GROUP BY invoice.company_id) rbac_report
  WHERE private.has_company_permission(company_id, 'reports.sales'::text);


--
-- Name: operix_report_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_report_summary WITH (security_invoker='true') AS
 SELECT company_id,
    revenue,
    expenses,
    net_profit,
    assets,
    liabilities_equity,
    cash_flow,
    ar_outstanding,
    ap_outstanding
   FROM ( WITH pl AS (
                 SELECT operix_profit_loss.company_id,
                    (COALESCE(sum(operix_profit_loss.presentation_amount) FILTER (WHERE (operix_profit_loss.account_type = ANY (ARRAY['revenue'::text, 'contra_revenue'::text]))), (0)::numeric))::numeric(20,4) AS revenue,
                    (COALESCE(sum(operix_profit_loss.presentation_amount) FILTER (WHERE (operix_profit_loss.account_type = 'expense'::text)), (0)::numeric))::numeric(20,4) AS expenses
                   FROM public.operix_profit_loss
                  GROUP BY operix_profit_loss.company_id
                ), bs AS (
                 SELECT operix_balance_sheet.company_id,
                    (COALESCE(sum(operix_balance_sheet.presentation_amount) FILTER (WHERE (operix_balance_sheet.account_type = ANY (ARRAY['asset'::text, 'contra_asset'::text]))), (0)::numeric))::numeric(20,4) AS assets,
                    (COALESCE(sum(operix_balance_sheet.presentation_amount) FILTER (WHERE (operix_balance_sheet.account_type = ANY (ARRAY['liability'::text, 'equity'::text]))), (0)::numeric))::numeric(20,4) AS liabilities_equity
                   FROM public.operix_balance_sheet
                  GROUP BY operix_balance_sheet.company_id
                ), cash AS (
                 SELECT operix_cash_flow.company_id,
                    (COALESCE(sum(operix_cash_flow.net_cash_flow), (0)::numeric))::numeric(20,4) AS cash_flow
                   FROM public.operix_cash_flow
                  GROUP BY operix_cash_flow.company_id
                ), ar AS (
                 SELECT operix_ar_aging.company_id,
                    (COALESCE(sum(operix_ar_aging.outstanding_amount), (0)::numeric))::numeric(20,4) AS ar_outstanding
                   FROM public.operix_ar_aging
                  GROUP BY operix_ar_aging.company_id
                ), ap AS (
                 SELECT operix_ap_open_items.company_id,
                    (COALESCE(sum(operix_ap_open_items.outstanding_amount), (0)::numeric))::numeric(20,4) AS ap_outstanding
                   FROM public.operix_ap_open_items
                  GROUP BY operix_ap_open_items.company_id
                )
         SELECT company.id AS company_id,
            COALESCE(pl.revenue, (0)::numeric) AS revenue,
            COALESCE(pl.expenses, (0)::numeric) AS expenses,
            (COALESCE(pl.revenue, (0)::numeric) - COALESCE(pl.expenses, (0)::numeric)) AS net_profit,
            COALESCE(bs.assets, (0)::numeric) AS assets,
            COALESCE(bs.liabilities_equity, (0)::numeric) AS liabilities_equity,
            COALESCE(cash.cash_flow, (0)::numeric) AS cash_flow,
            COALESCE(ar.ar_outstanding, (0)::numeric) AS ar_outstanding,
            COALESCE(ap.ap_outstanding, (0)::numeric) AS ap_outstanding
           FROM (((((public.companies company
             LEFT JOIN pl ON ((pl.company_id = company.id)))
             LEFT JOIN bs ON ((bs.company_id = company.id)))
             LEFT JOIN cash ON ((cash.company_id = company.id)))
             LEFT JOIN ar ON ((ar.company_id = company.id)))
             LEFT JOIN ap ON ((ap.company_id = company.id)))) rbac_report
  WHERE private.has_company_permission(company_id, 'reports.profit'::text);


--
-- Name: operix_trial_balance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.operix_trial_balance WITH (security_invoker='true') AS
 SELECT company_id,
    account_id,
    account_code,
    account_name,
    account_type,
    first_posting_date,
    last_posting_date,
    total_debit,
    total_credit,
    balance
   FROM ( SELECT trial_balance.company_id,
            trial_balance.account_id,
            trial_balance.account_code,
            trial_balance.account_name,
            trial_balance.account_type,
            trial_balance.first_posting_date,
            trial_balance.last_posting_date,
            trial_balance.total_debit,
            trial_balance.total_credit,
            trial_balance.balance
           FROM public.trial_balance) rbac_report
  WHERE private.has_company_permission(company_id, 'reports.operational'::text);


