--
-- Name: supplier_subledger_entries; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.supplier_subledger_entries WITH (security_invoker='true') AS
 SELECT ledger.company_id,
    supplier.id AS supplier_id,
    supplier.name AS supplier_name,
    ledger.journal_entry_id,
    ledger.entry_number,
    ledger.posting_date,
    ledger.source_type,
    ledger.source_id,
    ledger.account_id,
    ledger.account_code,
    ledger.account_name,
    ledger.debit,
    ledger.credit,
    ledger.signed_amount,
    ledger.description
   FROM ((((public.general_ledger_entries ledger
     JOIN LATERAL ( SELECT COALESCE(original.source_type, ledger.source_type) AS source_type,
            COALESCE(original.source_id, ledger.source_id) AS source_id
           FROM public.journal_entries original
          WHERE ((ledger.source_type = 'journal_reversal'::text) AND (original.id = ledger.source_id))
        UNION ALL
         SELECT ledger.source_type,
            ledger.source_id
          WHERE (ledger.source_type IS DISTINCT FROM 'journal_reversal'::text)
 LIMIT 1) source ON (true))
     LEFT JOIN public.supplier_bills bill ON (((source.source_type = 'supplier_bill'::text) AND (bill.id = source.source_id))))
     LEFT JOIN public.vendor_payments payment ON (((source.source_type = 'supplier_payment'::text) AND (payment.id = source.source_id))))
     JOIN public.vendors supplier ON ((supplier.id = COALESCE(bill.vendor_id, payment.vendor_id))))
  WHERE (ledger.account_id IN ( SELECT account.id
           FROM public.chart_of_accounts account
          WHERE ((account.company_id = ledger.company_id) AND (account.statement_mapping = 'balance_sheet.payables'::text))));


--
-- Name: supplier_subledger_reconciliation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.supplier_subledger_reconciliation WITH (security_invoker='true') AS
 WITH subledger AS (
         SELECT supplier_subledger_entries.company_id,
            round(sum(supplier_subledger_entries.signed_amount), 4) AS subledger_balance
           FROM public.supplier_subledger_entries
          GROUP BY supplier_subledger_entries.company_id
        ), general_ledger AS (
         SELECT ledger.company_id,
            round(sum((ledger.debit - ledger.credit)), 4) AS gl_balance
           FROM public.general_ledger_entries ledger
          WHERE (ledger.account_id IN ( SELECT account.id
                   FROM public.chart_of_accounts account
                  WHERE ((account.company_id = ledger.company_id) AND (account.statement_mapping = 'balance_sheet.payables'::text))))
          GROUP BY ledger.company_id
        )
 SELECT COALESCE(subledger.company_id, general_ledger.company_id) AS company_id,
    (COALESCE(subledger.subledger_balance, (0)::numeric))::numeric(20,4) AS subledger_balance,
    (COALESCE(general_ledger.gl_balance, (0)::numeric))::numeric(20,4) AS gl_balance,
    (round((COALESCE(subledger.subledger_balance, (0)::numeric) - COALESCE(general_ledger.gl_balance, (0)::numeric)), 4))::numeric(20,4) AS difference,
    (round((COALESCE(subledger.subledger_balance, (0)::numeric) - COALESCE(general_ledger.gl_balance, (0)::numeric)), 4) = (0)::numeric) AS reconciles
   FROM (subledger
     FULL JOIN general_ledger ON ((general_ledger.company_id = subledger.company_id)));


