    updated_by uuid
);


--
-- Name: withholding_tax_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.withholding_tax_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    category text NOT NULL,
    rate_percent numeric(8,4) NOT NULL,
    effective_from date NOT NULL,
    effective_until date,
    official_source text NOT NULL,
    requires_legal_review boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT withholding_tax_rules_check CHECK (((effective_until IS NULL) OR (effective_until >= effective_from))),
    CONSTRAINT withholding_tax_rules_rate_percent_check CHECK (((rate_percent >= (0)::numeric) AND (rate_percent <= (100)::numeric)))
);


