--
-- Name: customer_receivable_open_items _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.customer_receivable_open_items WITH (security_invoker='true') AS
 SELECT invoice.company_id,
    invoice.branch_id,
    invoice.client_id,
    invoice.id AS invoice_id,
    invoice.invoice_number,
    invoice.issue_date,
    invoice.due_date,
    invoice.currency,
    round(invoice.total_amount, 4) AS original_amount,
    round(COALESCE(sum(allocation.allocated_amount) FILTER (WHERE (allocation.status = 'active'::text)), (0)::numeric), 4) AS allocated_amount,
    round((invoice.total_amount - COALESCE(sum(allocation.allocated_amount) FILTER (WHERE (allocation.status = 'active'::text)), (0)::numeric)), 4) AS outstanding_amount,
    GREATEST((CURRENT_DATE - invoice.due_date), 0) AS days_overdue,
        CASE
            WHEN (invoice.due_date >= CURRENT_DATE) THEN 'not_due'::text
            WHEN (((CURRENT_DATE - invoice.due_date) >= 1) AND ((CURRENT_DATE - invoice.due_date) <= 30)) THEN '1_30'::text
            WHEN (((CURRENT_DATE - invoice.due_date) >= 31) AND ((CURRENT_DATE - invoice.due_date) <= 60)) THEN '31_60'::text
            WHEN (((CURRENT_DATE - invoice.due_date) >= 61) AND ((CURRENT_DATE - invoice.due_date) <= 90)) THEN '61_90'::text
            ELSE '90_plus'::text
        END AS aging_bucket
   FROM (public.invoices invoice
     LEFT JOIN public.payment_allocations allocation ON ((allocation.invoice_id = invoice.id)))
  GROUP BY invoice.company_id, invoice.branch_id, invoice.client_id, invoice.id, invoice.invoice_number, invoice.issue_date, invoice.due_date, invoice.currency, invoice.total_amount
 HAVING ((invoice.accounting_state = 'posted'::text) AND (invoice.status <> ALL (ARRAY['reversed'::public.invoice_status, 'credited'::public.invoice_status, 'cancelled'::public.invoice_status])) AND (round((invoice.total_amount - COALESCE(sum(allocation.allocated_amount) FILTER (WHERE (allocation.status = 'active'::text)), (0)::numeric)), 4) <> (0)::numeric));


--
-- Name: kosovo_sales_book_period_summary _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.kosovo_sales_book_period_summary WITH (security_invoker='true') AS
 SELECT id,
    company_id,
    accounting_period_id,
    period_start,
    period_end,
    reporting_frequency,
    status,
    declaration_deadline,
    tax_timezone,
    declared_at,
    declared_by,
    declaration_metadata,
    amended_at,
    amended_by,
    amendment_reason,
    created_at,
    updated_at,
    transaction_count,
    taxable_amount,
    vat_amount,
    total_amount
   FROM ( SELECT period.id,
            period.company_id,
            period.accounting_period_id,
            period.period_start,
            period.period_end,
            period.reporting_frequency,
            period.status,
            period.declaration_deadline,
            period.tax_timezone,
            period.declared_at,
            period.declared_by,
            period.declaration_metadata,
            period.amended_at,
            period.amended_by,
            period.amendment_reason,
            period.created_at,
            period.updated_at,
            (count(book.invoice_id))::integer AS transaction_count,
            round(COALESCE(sum(book.taxable_base), (0)::numeric), 4) AS taxable_amount,
            round(COALESCE(sum(book.output_vat), (0)::numeric), 4) AS vat_amount,
            round(COALESCE(sum(book.total_amount), (0)::numeric), 4) AS total_amount
           FROM (public.sales_book_periods period
             LEFT JOIN public.kosovo_sales_book book ON ((book.sales_book_period_id = period.id)))
          GROUP BY period.id) rbac_report
  WHERE private.has_company_permission(company_id, 'sales_book.view'::text);


