   FROM public.invoices source_invoice
  WHERE ((source_invoice.id = document_source_links.source_id) AND (source_invoice.company_id = document_source_links.company_id) AND private.rbac_can_read_resource(source_invoice.company_id, 'invoice'::text, source_invoice.user_id, source_invoice.assigned_user_id, 'invoice.view'::text)))) AND (EXISTS ( SELECT 1
