  WHERE ((target_invoice.id = document_source_links.target_id) AND (target_invoice.company_id = document_source_links.company_id) AND private.rbac_can_read_resource(target_invoice.company_id, 'invoice'::text, target_invoice.user_id, target_invoice.assigned_user_id, 'invoice.view'::text))))) OR ((source_type = 'supplier_bill'::text) AND (target_type = 'supplier_bill'::text) AND (EXISTS ( SELECT 1
   FROM public.supplier_bills source_bill
  WHERE ((source_bill.id = document_source_links.source_id) AND (source_bill.company_id = document_source_links.company_id) AND (((source_bill.user_id = ( SELECT auth.uid() AS uid)) AND private.has_company_permission(source_bill.company_id, 'expense.view_own'::text)) OR private.has_company_permission(source_bill.company_id, 'expense.view_all'::text))))) AND (EXISTS ( SELECT 1
   FROM public.supplier_bills target_bill
  WHERE ((target_bill.id = document_source_links.target_id) AND (target_bill.company_id = document_source_links.company_id) AND (((target_bill.user_id = ( SELECT auth.uid() AS uid)) AND private.has_company_permission(target_bill.company_id, 'expense.view_own'::text)) OR private.has_company_permission(target_bill.company_id, 'expense.view_all'::text))))))));


