--

CREATE POLICY rbac_invoices_select ON public.invoices FOR SELECT TO authenticated USING (private.rbac_can_read_resource(company_id,
CASE upper(COALESCE(commercial_document_type, type, 'INVOICE'::text))
    WHEN 'QUOTE'::text THEN 'offer'::text
    WHEN 'OFFER'::text THEN 'offer'::text
    WHEN 'PROFORMA'::text THEN 'proforma'::text
    WHEN 'SALES_ORDER'::text THEN 'order'::text
    WHEN 'ORDER'::text THEN 'order'::text
    WHEN 'DELIVERY_NOTE'::text THEN 'delivery_note'::text
    ELSE 'invoice'::text
END, user_id, assigned_user_id, 'invoice.view'::text));


