--
-- Name: admin_delete_invoice(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_delete_invoice(p_invoice_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path to ''
as $$
declare
  actor_id uuid := (select auth.uid());
  invoice_row public.invoices%rowtype;
  items_snapshot jsonb;
  reason_text text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if reason_text is null or char_length(reason_text) < 3 then
    raise exception 'A reason of at least 3 characters is required to delete an invoice' using errcode = '23514';
  end if;

  select * into invoice_row from public.invoices where id = p_invoice_id for update;
  if not found then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if invoice_row.company_id is null
     or not (
       private.rbac_is_platform_admin()
       or (
         private.rbac_role_code(invoice_row.company_id) = 'company_administrator'
         and coalesce(private.has_company_permission(invoice_row.company_id, 'sales_invoice.delete'), false)
       )
     ) then
    raise exception 'Only company administrators can delete invoices' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(to_jsonb(item) order by item.id), '[]'::jsonb)
  into items_snapshot
  from public.invoice_items item
  where item.invoice_id = invoice_row.id;

  insert into public.audit_events (company_id, actor_user_id, action, entity_type, entity_id, entity_key, previous_values, reason, occurred_at)
  values (
    invoice_row.company_id, actor_id, 'invoice.deleted_by_admin', 'invoice', invoice_row.id, invoice_row.invoice_number,
    jsonb_build_object('invoice', to_jsonb(invoice_row), 'items', items_snapshot),
    reason_text, clock_timestamp()
  );

  perform public.delete_invoice(p_invoice_id);
end;
$$;

revoke all on function public.admin_delete_invoice(uuid, text) from public, anon;
grant execute on function public.admin_delete_invoice(uuid, text) to authenticated;

--
-- Name: admin_correct_stock_invoice(jsonb, jsonb, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_correct_stock_invoice(
  p_invoice jsonb,
  p_items jsonb,
  p_invoice_id uuid,
  p_reason text,
  p_idempotency_key uuid default null
)
returns public.invoices
language plpgsql
security definer
set search_path to ''
as $$
declare
  actor_id uuid := (select auth.uid());
  invoice_row public.invoices%rowtype;
  result_invoice public.invoices;
  items_snapshot jsonb;
  reason_text text := nullif(trim(coalesce(p_reason, '')), '');
  stock_row record;
  item_record record;
  product_row public.products;
  branch_stock public.product_branch_stock;
  stock_before numeric;
  issue_branch_id uuid;
begin
  if actor_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if reason_text is null or char_length(reason_text) < 3 then
    raise exception 'A reason of at least 3 characters is required to correct an invoice' using errcode = '23514';
  end if;
  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_items, '[]'::jsonb)) = 0 then
    raise exception 'At least one invoice item is required' using errcode = '22023';
  end if;

  select * into invoice_row from public.invoices where id = p_invoice_id for update;
  if not found then
    raise exception 'Invoice not found' using errcode = 'P0002';
  end if;
  if invoice_row.company_id is null
     or not (
       private.rbac_is_platform_admin()
       or (
         private.rbac_role_code(invoice_row.company_id) = 'company_administrator'
         and coalesce(private.has_company_permission(invoice_row.company_id, 'sales_invoice.edit'), false)
       )
     ) then
    raise exception 'Only company administrators can correct posted invoices' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(to_jsonb(item) order by item.id), '[]'::jsonb) into items_snapshot
  from public.invoice_items item where item.invoice_id = invoice_row.id;

  -- 1) Return the quantities this invoice took out of stock (net of anything already returned).
  for stock_row in
    select movement.product_id, movement.branch_id, -sum(movement.quantity_delta) as quantity
    from public.inventory_stock_movements movement
    where movement.invoice_id = invoice_row.id and movement.product_id is not null
    group by movement.product_id, movement.branch_id
    having sum(movement.quantity_delta) < 0
  loop
    stock_before := null;
    if stock_row.branch_id is not null then
      select * into branch_stock from public.product_branch_stock
      where company_id = invoice_row.company_id and branch_id = stock_row.branch_id and product_id = stock_row.product_id
      for update;
      if found then
        stock_before := branch_stock.stock_quantity;
        update public.product_branch_stock set stock_quantity = stock_before + stock_row.quantity, updated_by = actor_id, updated_at = now()
        where id = branch_stock.id;
        update public.products set stock_quantity = (select coalesce(sum(stock_quantity), 0) from public.product_branch_stock where company_id = invoice_row.company_id and product_id = stock_row.product_id)
        where id = stock_row.product_id;
      end if;
    end if;
    if stock_before is null then
      select coalesce(product.stock_quantity, 0) into stock_before from public.products product where product.id = stock_row.product_id for update;
      if found then
        update public.products set stock_quantity = stock_before + stock_row.quantity where id = stock_row.product_id;
      else
        continue; -- the product no longer exists; there is nothing to return to
      end if;
    end if;
    insert into public.inventory_stock_movements (company_id, branch_id, product_id, invoice_id, movement_type, quantity_delta, stock_before, stock_after, created_by, note)
    values (invoice_row.company_id, stock_row.branch_id, stock_row.product_id, invoice_row.id, 'invoice_reversal',
            stock_row.quantity, stock_before, stock_before + stock_row.quantity, actor_id,
            'Returned for admin correction of ' || coalesce(invoice_row.invoice_number, ''));
  end loop;

  -- 2) Detach the old movements so the invoice can be replaced. The rows and their quantities stay as history.
  update public.inventory_stock_movements
  set invoice_id = null,
      note = trim(both ' ' from coalesce(note, '') || ' [was on invoice ' || coalesce(invoice_row.invoice_number, '') || ', corrected by admin]')
  where invoice_id = invoice_row.id;

  -- 3) Replace the invoice through the normal posted-invoice workflow (reverses and re-posts the journal).
  result_invoice := public.replace_posted_invoice_document(p_invoice, p_items, p_invoice_id, p_idempotency_key);

  -- 4) Issue stock for the new lines with the same rules as checkout.
  issue_branch_id := coalesce(nullif(p_invoice ->> 'branch_id', '')::uuid, result_invoice.branch_id);
  for item_record in
    select item.product_id, sum(item.quantity) as quantity
    from jsonb_to_recordset(p_items) as item(product_id uuid, quantity numeric)
    where item.product_id is not null
    group by item.product_id
  loop
    select * into product_row from public.products where id = item_record.product_id for update;
    if not found or not coalesce(product_row.track_stock, false) then
      continue;
    end if;
    if issue_branch_id is not null then
      select * into branch_stock from public.product_branch_stock
      where company_id = result_invoice.company_id and branch_id = issue_branch_id and product_id = product_row.id for update;
      if not found then
        if exists (select 1 from public.product_branch_stock where company_id = result_invoice.company_id and product_id = product_row.id) then
          raise exception 'No stock is configured for "%" in the selected branch', product_row.name using errcode = '22003';
        end if;
        if coalesce(product_row.stock_quantity, 0) < item_record.quantity then
          raise exception 'Not enough stock for "%". Available: %, requested: %', product_row.name, product_row.stock_quantity, item_record.quantity using errcode = '22003';
        end if;
        stock_before := product_row.stock_quantity;
        update public.products set stock_quantity = stock_before - item_record.quantity where id = product_row.id;
      else
        if coalesce(branch_stock.stock_quantity, 0) < item_record.quantity then
          raise exception 'Not enough stock for "%" in the selected branch. Available: %, requested: %', product_row.name, branch_stock.stock_quantity, item_record.quantity using errcode = '22003';
        end if;
        stock_before := branch_stock.stock_quantity;
        update public.product_branch_stock set stock_quantity = stock_before - item_record.quantity, updated_by = actor_id, updated_at = now() where id = branch_stock.id;
        update public.products set stock_quantity = (select coalesce(sum(stock_quantity), 0) from public.product_branch_stock where company_id = result_invoice.company_id and product_id = product_row.id) where id = product_row.id;
      end if;
    else
      if coalesce(product_row.stock_quantity, 0) < item_record.quantity then
        raise exception 'Not enough stock for "%". Available: %, requested: %', product_row.name, product_row.stock_quantity, item_record.quantity using errcode = '22003';
      end if;
      stock_before := product_row.stock_quantity;
      update public.products set stock_quantity = stock_before - item_record.quantity where id = product_row.id;
    end if;
    insert into public.inventory_stock_movements (company_id, branch_id, product_id, invoice_id, movement_type, quantity_delta, stock_before, stock_after, created_by)
    values (result_invoice.company_id, issue_branch_id, product_row.id, result_invoice.id, 'invoice_issue', -item_record.quantity, stock_before, stock_before - item_record.quantity, actor_id);
  end loop;

  insert into public.audit_events (company_id, actor_user_id, action, entity_type, entity_id, entity_key, previous_values, new_values, reason, occurred_at)
  values (
    invoice_row.company_id, actor_id, 'invoice.corrected_by_admin', 'invoice', invoice_row.id, invoice_row.invoice_number,
    jsonb_build_object('invoice', to_jsonb(invoice_row), 'items', items_snapshot),
    jsonb_build_object('invoice', p_invoice, 'items', p_items),
    reason_text, clock_timestamp()
  );

  return result_invoice;
end;
$$;

revoke all on function public.admin_correct_stock_invoice(jsonb, jsonb, uuid, text, uuid) from public, anon;
grant execute on function public.admin_correct_stock_invoice(jsonb, jsonb, uuid, text, uuid) to authenticated;

--
-- Push notifications (queue, preferences, triggers)
--

-- Push notifications to the other people in a workspace.
--
-- Changes in the database (an invoice issued or paid, a payment, an expense, a new member, low stock, a transfer,
-- an admin correction, a billing change) put a row in public.push_outbox. A web endpoint (/api/internal/push-dispatch)
-- turns those rows into Expo push messages for the right people. Because the database queues them, notifications
-- work for every change, from any device or the web app, even if the phone that made the change closes right away.
--
-- Who is told: the people with the owner/admin role, anyone whose role can see everything of that kind, and the
-- person an item is assigned to. The person who made the change is never told about their own change.
-- People can switch kinds of notification on or off (notification_preferences).
--
-- To enable sending, store two Vault secrets (the database calls the endpoint when something is queued):
--   select vault.create_secret('https://your-web-address/api/internal/push-dispatch', 'push_dispatch_url');
--   select vault.create_secret('<same value as CRON_SECRET or PUSH_DISPATCH_SECRET on the web app>', 'push_dispatch_secret');
-- Without them events are still queued and can be sent by calling the endpoint on a schedule.

alter table public.operix_push_device_tokens add column if not exists language text not null default 'en';

create table if not exists public.push_outbox (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies(id) on delete cascade,
  event_type text not null,
  category text not null check (category in ('invoices', 'payments', 'expenses', 'team', 'stock', 'money', 'billing')),
  recipient_scope text not null default 'category' check (recipient_scope in ('category', 'admins')),
  entity_type text,
  entity_id uuid,
  actor_user_id uuid,
  assigned_user_id uuid,
  title jsonb not null,
  body jsonb not null,
  data jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  claimed_at timestamptz,
  processed_at timestamptz,
  attempts integer not null default 0,
  last_error text
);
create index if not exists push_outbox_pending_idx on public.push_outbox (created_at) where processed_at is null;
-- One notification per invoice for these one-time events, even when the invoice is saved in several steps.
create unique index if not exists push_outbox_once_idx on public.push_outbox (event_type, entity_id)
  where entity_id is not null and event_type in ('invoice_created', 'invoice_paid', 'invoice_cancelled');
alter table public.push_outbox enable row level security; -- no policies: only the server (service role) and the functions below touch it

create table if not exists public.notification_preferences (
  user_id uuid not null references auth.users(id) on delete cascade,
  category text not null check (category in ('invoices', 'payments', 'expenses', 'team', 'stock', 'money', 'billing')),
  enabled boolean not null default true,
  updated_at timestamptz not null default now(),
  primary key (user_id, category)
);
alter table public.notification_preferences enable row level security;
drop policy if exists notification_preferences_select on public.notification_preferences;
drop policy if exists notification_preferences_write on public.notification_preferences;
create policy notification_preferences_select on public.notification_preferences for select to authenticated using (user_id = (select auth.uid()));
create policy notification_preferences_write on public.notification_preferences for all to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
grant select, insert, update, delete on public.notification_preferences to authenticated;

-- ---------------------------------------------------------------- helpers
create or replace function private.push_money(p_amount numeric, p_currency text)
returns text language sql immutable set search_path to '' as $$
  select case upper(coalesce(p_currency, 'EUR')) when 'EUR' then '€' when 'USD' then '$' when 'GBP' then '£' else upper(p_currency) || ' ' end
         || trim(to_char(coalesce(p_amount, 0), 'FM999,999,999,990.00'));
$$;

create or replace function private.push_person(p_user_id uuid)
returns text language sql stable security definer set search_path to '' as $$
  select coalesce(
    nullif(trim(coalesce(profile.first_name, '') || ' ' || coalesce(profile.last_name, '')), ''),
    nullif(split_part(coalesce(profile.email, ''), '@', 1), ''),
    'A team member')
  from (select 1) one left join public.profiles profile on profile.id = p_user_id;
$$;

-- Calls the web endpoint right after the transaction commits. Never blocks or fails the change that queued the row.
create or replace function private.push_kick()
returns void language plpgsql security definer set search_path to '' as $$
declare
  dispatch_url text;
  dispatch_secret text;
begin
  select decrypted_secret into dispatch_url from vault.decrypted_secrets where name = 'push_dispatch_url' limit 1;
  select decrypted_secret into dispatch_secret from vault.decrypted_secrets where name = 'push_dispatch_secret' limit 1;
  if dispatch_url is null or dispatch_secret is null then return; end if;
  perform net.http_post(url := dispatch_url, headers := jsonb_build_object('content-type', 'application/json', 'x-dispatch-secret', dispatch_secret), body := '{}'::jsonb, timeout_milliseconds := 5000);
exception when others then
  null;
end;
$$;

create or replace function private.enqueue_push(
  p_company_id uuid, p_event_type text, p_category text, p_scope text, p_entity_type text, p_entity_id uuid,
  p_actor uuid, p_assigned uuid, p_title_en text, p_title_sq text, p_body_en text, p_body_sq text, p_data jsonb default '{}'::jsonb
) returns void language plpgsql security definer set search_path to '' as $$
begin
  if p_company_id is null then return; end if;
  insert into public.push_outbox (company_id, event_type, category, recipient_scope, entity_type, entity_id, actor_user_id, assigned_user_id, title, body, data)
  values (p_company_id, p_event_type, p_category, p_scope, p_entity_type, p_entity_id, p_actor, p_assigned,
          jsonb_build_object('en', p_title_en, 'sq', p_title_sq), jsonb_build_object('en', p_body_en, 'sq', p_body_sq), coalesce(p_data, '{}'::jsonb))
  on conflict do nothing;
  perform private.push_kick();
exception when others then
  null; -- a notification problem must never break the business change
end;
$$;

-- ---------------------------------------------------------------- who is told
create or replace function public.push_outbox_recipients(p_event_id uuid)
returns table (user_id uuid)
language sql stable security definer set search_path to '' as $$
  select distinct member.user_id
  from public.push_outbox event
  join public.memberships member on member.company_id = event.company_id and coalesce(member.status, 'active') = 'active'
  where event.id = p_event_id
    and member.user_id is distinct from event.actor_user_id
    and (
      member.role in ('owner', 'admin')
      or member.user_id = event.assigned_user_id
      or (event.recipient_scope = 'category' and exists (
        select 1
        from public.membership_role_assignments assignment
        join public.app_role_permissions grant_row on grant_row.role_id = assignment.role_id
        where assignment.membership_id = member.id
          and grant_row.permission_code = case event.category
            when 'invoices' then 'invoice.view_all'
            when 'payments' then 'payment.view'
            when 'expenses' then 'expense.view_all'
            when 'stock' then 'inventory.view'
            when 'money' then 'settings.bank'
            else '-'
          end))
    )
    and coalesce((select preference.enabled from public.notification_preferences preference where preference.user_id = member.user_id and preference.category = event.category), true);
$$;

create or replace function public.claim_push_outbox(p_limit integer default 50)
returns setof public.push_outbox
language sql security definer set search_path to '' as $$
  update public.push_outbox outbox
  set claimed_at = now(), attempts = outbox.attempts + 1
  where outbox.id in (
    select pending.id from public.push_outbox pending
    where pending.processed_at is null and pending.attempts < 5
      and (pending.claimed_at is null or pending.claimed_at < now() - interval '5 minutes')
    order by pending.created_at
    limit greatest(1, least(coalesce(p_limit, 50), 200))
    for update skip locked)
  returning outbox.*;
$$;

create or replace function public.complete_push_outbox(p_event_id uuid, p_error text default null)
returns void language sql security definer set search_path to '' as $$
  update public.push_outbox
  set processed_at = case when p_error is null then now() else processed_at end, last_error = left(p_error, 500)
  where id = p_event_id;
$$;

revoke all on function public.push_outbox_recipients(uuid), public.claim_push_outbox(integer), public.complete_push_outbox(uuid, text) from public, anon, authenticated;
grant execute on function public.push_outbox_recipients(uuid), public.claim_push_outbox(integer), public.complete_push_outbox(uuid, text) to service_role;

-- ---------------------------------------------------------------- triggers
-- Invoices: issued (created), paid, cancelled.
create or replace function private.push_on_invoice()
returns trigger language plpgsql security definer set search_path to '' as $$
declare
  actor uuid := (select auth.uid());
  doc_type text := upper(coalesce(new.commercial_document_type, new.type, 'INVOICE'));
  old_status text := lower(coalesce(case when tg_op = 'UPDATE' then old.status::text end, 'draft'));
  new_status text := lower(coalesce(new.status::text, 'draft'));
  customer text;
  amount text := private.push_money(new.total_amount, new.currency);
  who text := private.push_person(actor);
  link jsonb := jsonb_build_object('type', 'invoice', 'id', new.id, 'url', 'operix-invoice://open/invoices/' || new.id);
begin
  if doc_type in ('QUOTE', 'OFFER', 'PROFORMA', 'SALES_ORDER', 'DELIVERY_NOTE') or new.company_id is null then return new; end if;
  select client.name into customer from public.clients client where client.id = new.client_id;
  customer := coalesce(customer, '—');

  if new_status <> 'draft' and new_status not in ('cancelled', 'reversed') and (tg_op = 'INSERT' or old_status = 'draft') then
    perform private.enqueue_push(new.company_id, 'invoice_created', 'invoices', 'category', 'invoice', new.id, actor, new.assigned_user_id,
      'New invoice ' || coalesce(new.invoice_number, ''), 'Faturë e re ' || coalesce(new.invoice_number, ''),
      who || ' issued an invoice for ' || customer || ' · ' || amount, who || ' lëshoi një faturë për ' || customer || ' · ' || amount, link);
  end if;
  if tg_op = 'UPDATE' and upper(coalesce(new.payment_status, '')) = 'PAID' and upper(coalesce(old.payment_status, '')) is distinct from 'PAID' then
    perform private.enqueue_push(new.company_id, 'invoice_paid', 'invoices', 'category', 'invoice', new.id, actor, new.assigned_user_id,
      'Invoice paid ' || coalesce(new.invoice_number, ''), 'Fatura u pagua ' || coalesce(new.invoice_number, ''),
      customer || ' · ' || amount || ' is fully paid', customer || ' · ' || amount || ' është paguar plotësisht', link);
  end if;
  if tg_op = 'UPDATE' and new_status in ('cancelled', 'reversed') and old_status not in ('cancelled', 'reversed') then
    perform private.enqueue_push(new.company_id, 'invoice_cancelled', 'invoices', 'category', 'invoice', new.id, actor, new.assigned_user_id,
      'Invoice cancelled ' || coalesce(new.invoice_number, ''), 'Fatura u anulua ' || coalesce(new.invoice_number, ''),
      who || ' cancelled the invoice for ' || customer || ' · ' || amount, who || ' anuloi faturën për ' || customer || ' · ' || amount, link);
  end if;
  return new;
exception when others then
  return new;
end;
$$;
drop trigger if exists push_on_invoice on public.invoices;
create trigger push_on_invoice after insert or update of status, payment_status on public.invoices
  for each row execute function private.push_on_invoice();

-- Payments received.
create or replace function private.push_on_payment()
returns trigger language plpgsql security definer set search_path to '' as $$
declare
  actor uuid := (select auth.uid());
  customer text;
  invoice_number text;
  amount text := private.push_money(new.amount, new.currency);
begin
  select client.name into customer from public.clients client where client.id = new.client_id;
  select invoice.invoice_number into invoice_number from public.invoices invoice where invoice.id = new.invoice_id;
  customer := coalesce(customer, new.payer_name, '—');
  perform private.enqueue_push(new.company_id, 'payment_received', 'payments', 'category', 'payment', new.id, coalesce(actor, new.user_id), new.assigned_user_id,
    'Payment received ' || amount, 'Pagesë e pranuar ' || amount,
    private.push_person(coalesce(actor, new.user_id)) || ' recorded ' || amount || ' from ' || customer || coalesce(' for ' || invoice_number, ''),
    private.push_person(coalesce(actor, new.user_id)) || ' regjistroi ' || amount || ' nga ' || customer || coalesce(' për ' || invoice_number, ''),
    jsonb_build_object('type', 'payment', 'id', new.id, 'url', 'operix-invoice://open/payments/' || new.id));
  return new;
exception when others then
  return new;
end;
$$;
drop trigger if exists push_on_payment on public.payments;
create trigger push_on_payment after insert on public.payments for each row execute function private.push_on_payment();

-- Expenses: new expense, and approval requests for administrators.
create or replace function private.push_on_expense()
returns trigger language plpgsql security definer set search_path to '' as $$
declare
  actor uuid := (select auth.uid());
  who text := private.push_person(coalesce(actor, new.user_id));
  amount text := private.push_money(new.amount, new.currency);
  what text := coalesce(nullif(new.vendor_name, ''), nullif(new.category, ''), nullif(new.description, ''), 'expense');
  link jsonb := jsonb_build_object('type', 'expense', 'id', new.id, 'url', 'operix-invoice://open/expenses/' || new.id);
begin
  perform private.enqueue_push(new.company_id, 'expense_created', 'expenses', 'category', 'expense', new.id, coalesce(actor, new.user_id), new.assigned_user_id,
    'New expense ' || amount, 'Shpenzim i ri ' || amount, who || ' added ' || what || ' · ' || amount, who || ' shtoi ' || what || ' · ' || amount, link);
  if lower(coalesce(new.approval_status, '')) in ('pending', 'pending_approval') then
    perform private.enqueue_push(new.company_id, 'approval_requested', 'expenses', 'admins', 'expense', new.id, coalesce(actor, new.user_id), null,
      'Approval needed', 'Kërkohet aprovim', who || ' needs approval for ' || what || ' · ' || amount, who || ' kërkon aprovim për ' || what || ' · ' || amount, link);
  end if;
  return new;
exception when others then
  return new;
end;
$$;
drop trigger if exists push_on_expense on public.expenses;
create trigger push_on_expense after insert on public.expenses for each row execute function private.push_on_expense();

-- A new member joins the workspace (administrators are told).
create or replace function private.push_on_member()
returns trigger language plpgsql security definer set search_path to '' as $$
declare
  company_label text;
begin
  if coalesce(new.status, 'active') <> 'active' or new.role = 'owner' then return new; end if;
  select coalesce(company.company_name, company.name, 'your workspace') into company_label from public.companies company where company.id = new.company_id;
  perform private.enqueue_push(new.company_id, 'member_added', 'team', 'admins', 'membership', new.id, (select auth.uid()), null,
    'New team member', 'Anëtar i ri i ekipit', private.push_person(new.user_id) || ' joined ' || company_label, private.push_person(new.user_id) || ' u bashkua te ' || company_label,
    jsonb_build_object('type', 'team'));
  return new;
exception when others then
  return new;
end;
$$;
drop trigger if exists push_on_member on public.memberships;
create trigger push_on_member after insert on public.memberships for each row execute function private.push_on_member();

-- Money moved between cash, bank and card accounts.
create or replace function private.push_on_transfer()
returns trigger language plpgsql security definer set search_path to '' as $$
declare
  actor uuid := coalesce((select auth.uid()), new.created_by);
  amount text := private.push_money(new.amount, new.currency);
begin
  perform private.enqueue_push(new.company_id, 'money_transferred', 'money', 'category', 'transfer', new.id, actor, null,
    'Money transferred ' || amount, 'Para të transferuara ' || amount,
    private.push_person(actor) || ' moved ' || amount || coalesce(' · ' || nullif(new.description, ''), ''),
    private.push_person(actor) || ' transferoi ' || amount || coalesce(' · ' || nullif(new.description, ''), ''),
    jsonb_build_object('type', 'money'));
  return new;
exception when others then
  return new;
end;
$$;
drop trigger if exists push_on_transfer on public.company_fund_transfers;
create trigger push_on_transfer after insert on public.company_fund_transfers for each row execute function private.push_on_transfer();

-- A tracked product runs low on stock (only when it crosses the threshold, not on every sale below it).
create or replace function private.push_on_low_stock()
returns trigger language plpgsql security definer set search_path to '' as $$
declare
  threshold numeric := coalesce(new.low_stock_threshold, 5);
begin
  if not coalesce(new.track_stock, false) or new.company_id is null then return new; end if;
  if coalesce(old.stock_quantity, 0) > threshold and coalesce(new.stock_quantity, 0) <= threshold then
    perform private.enqueue_push(new.company_id, 'low_stock', 'stock', 'category', 'product', new.id, (select auth.uid()), null,
      'Low stock: ' || new.name, 'Stok i ulët: ' || new.name,
      new.name || ' is down to ' || trim(to_char(coalesce(new.stock_quantity, 0), 'FM999,999,990.##')) || ' left', new.name || ' ka mbetur ' || trim(to_char(coalesce(new.stock_quantity, 0), 'FM999,999,990.##')),
      jsonb_build_object('type', 'product', 'id', new.id, 'url', 'operix-invoice://open/products/' || new.id));
  end if;
  return new;
exception when others then
  return new;
end;
$$;
drop trigger if exists push_on_low_stock on public.products;
create trigger push_on_low_stock after update of stock_quantity on public.products for each row execute function private.push_on_low_stock();

-- Administrator deleted or corrected a posted invoice: the other administrators are told.
create or replace function private.push_on_admin_invoice_action()
returns trigger language plpgsql security definer set search_path to '' as $$
declare
  deleted boolean := new.action = 'invoice.deleted_by_admin';
  who text := private.push_person(new.actor_user_id);
begin
  if new.action not in ('invoice.deleted_by_admin', 'invoice.corrected_by_admin') then return new; end if;
  perform private.enqueue_push(new.company_id, case when deleted then 'invoice_deleted' else 'invoice_corrected' end, 'invoices', 'admins', 'invoice', null, new.actor_user_id, null,
    case when deleted then 'Invoice deleted ' else 'Invoice corrected ' end || coalesce(new.entity_key, ''),
    case when deleted then 'Fatura u fshi ' else 'Fatura u korrigjua ' end || coalesce(new.entity_key, ''),
    who || (case when deleted then ' deleted a posted invoice: ' else ' corrected a posted invoice: ' end) || coalesce(new.reason, ''),
    who || (case when deleted then ' fshiu një faturë të postuar: ' else ' korrigjoi një faturë të postuar: ' end) || coalesce(new.reason, ''),
    jsonb_build_object('type', 'audit'));
  return new;
exception when others then
  return new;
end;
$$;
drop trigger if exists push_on_admin_invoice_action on public.audit_events;
create trigger push_on_admin_invoice_action after insert on public.audit_events for each row execute function private.push_on_admin_invoice_action();

-- Subscription changes: payment failed or subscription active (administrators).
create or replace function private.push_on_subscription()
returns trigger language plpgsql security definer set search_path to '' as $$
begin
  if new.status is not distinct from old.status then return new; end if;
  if new.status = 'past_due' then
    perform private.enqueue_push(new.company_id, 'billing_payment_failed', 'billing', 'admins', 'subscription', null, null, null,
      'Subscription payment failed', 'Pagesa e abonimit dështoi', 'Update your payment method to avoid interruption.', 'Përditësoni mënyrën e pagesës për të shmangur ndërprerjen.', jsonb_build_object('type', 'billing'));
  elsif new.status = 'active' and coalesce(old.status, '') <> 'active' then
    perform private.enqueue_push(new.company_id, 'billing_active', 'billing', 'admins', 'subscription', null, null, null,
      'OperiX Cloud is active', 'OperiX Cloud është aktiv', 'Your subscription is active. Thank you!', 'Abonimi juaj është aktiv. Faleminderit!', jsonb_build_object('type', 'billing'));
  end if;
  return new;
exception when others then
  return new;
end;
$$;
drop trigger if exists push_on_subscription on public.subscription_accounts;
create trigger push_on_subscription after update of status on public.subscription_accounts for each row execute function private.push_on_subscription();


-- ---------------------------------------------------------------- 20261030170000_fix_billing_metrics_ambiguity
-- control_product_billing_metrics() returns a column named "value" and its body also uses "value", so PL/pgSQL
-- reported the name as ambiguous and the platform billing page could not load. Prefer the table column.
CREATE OR REPLACE FUNCTION public.control_product_billing_metrics()
 RETURNS TABLE(metric text, value numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
begin
  if not public.control_is_platform_admin() then raise exception 'Platform administrator access required' using errcode = '42501'; end if;
  return query
  with accounts as (
    select account.*,
      private.operix_effective_status(account.status, account.trial_ends_at, account.current_period_end, account.grace_period_ends_at, account.manual_override_status, account.manual_override_expires_at) as effective_status
    from public.subscription_accounts account
  ), paid as (
    select account.* from accounts account where private.operix_status_has_access(account.status, account.trial_ends_at, account.current_period_end, account.grace_period_ends_at, account.manual_override_status, account.manual_override_expires_at) and account.effective_status <> 'trialing'
  ), values as (
    select paid.product, paid.billing_interval, private.operix_plan_value(paid.product, paid.billing_interval, usage.billable_tenants, usage.billable_users) as value
    from paid left join public.subscription_usage usage on usage.company_id = paid.company_id
  ), enterprise_values as (
    select contract.billing_interval, contract.custom_price as value
    from public.enterprise_contracts contract
    where contract.status = 'active'
      and contract.starts_at <= now()
      and (contract.ends_at is null or contract.ends_at > now())
      and contract.custom_price is not null
      and contract.billing_interval in ('monthly', 'annual')
  ), trial_keys as (
    -- Conversion is an organization metric. A Suite clock can have linked
    -- Invoice/Booking history rows, and a customer can also have explored
    -- two standalone products; neither should inflate the denominator.
    select
      trial.company_id,
      case
        when bool_or(trial.status = 'trialing' and trial.ends_at > now()) then 'trialing'
        when bool_or(trial.status = 'completed') then 'completed'
        when bool_or(trial.status = 'expired' or trial.ends_at <= now()) then 'expired'
        else max(trial.status)
      end as status
    from public.subscription_trials trial
    group by trial.company_id
  ), trials as (
    select count(*) filter (where status = 'trialing')::numeric as active_trials,
      count(*) filter (where status = 'expired')::numeric as expired_trials,
      count(*)::numeric as all_trials
    from trial_keys
  )
  select 'invoice_subscriptions', count(*) filter (where product = 'invoice')::numeric from accounts
  union all select 'booking_subscriptions', count(*) filter (where product = 'booking')::numeric from accounts
  union all select 'suite_subscriptions', count(*) filter (where product = 'suite')::numeric from accounts
  union all select 'monthly_subscriptions', count(*) filter (where billing_interval = 'monthly' and effective_status <> 'expired')::numeric from accounts
  union all select 'annual_subscriptions', count(*) filter (where billing_interval = 'annual' and effective_status <> 'expired')::numeric from accounts
  union all select 'active_trials', trials.active_trials from trials
  union all select 'expired_trials', trials.expired_trials from trials
  union all select 'trial_conversion_rate', case when trials.all_trials = 0 then 0 else round((select count(distinct company_id)::numeric from paid) / trials.all_trials * 100, 2) end from trials
  union all select 'mrr', coalesce((select sum(case when billing_interval = 'annual' then value / 12 else value end) from values), 0) + coalesce((select sum(case when billing_interval = 'annual' then value / 12 else value end) from enterprise_values), 0)
  union all select 'arr', coalesce((select sum(case when billing_interval = 'annual' then value else value * 12 end) from values), 0) + coalesce((select sum(case when billing_interval = 'annual' then value else value * 12 end) from enterprise_values), 0)
  union all select 'active_subscriptions', count(*) filter (where effective_status in ('active', 'past_due', 'canceled'))::numeric from accounts
  union all select 'past_due_accounts', count(*) filter (where status = 'past_due')::numeric from accounts
  union all select 'canceled_accounts', count(*) filter (where status = 'canceled')::numeric from accounts
  union all select 'enterprise_customers', count(distinct company_id)::numeric from public.enterprise_contracts where status in ('trialing', 'active') and starts_at <= now() and (ends_at is null or ends_at > now());
end;
$function$

;

-- ---------------------------------------------------------------- 20261031090000_agent_signatures
-- Each agent can have their own signature. The invoice PDF prints the creating agent's signature and falls back
-- to the company signature when the agent has none. Agents set their own; company administrators can set or clear any member's.
alter table public.profiles
  add column if not exists agent_signature_url text;

alter table public.profiles
  drop constraint if exists profiles_agent_signature_size;
alter table public.profiles
  add constraint profiles_agent_signature_size check (agent_signature_url is null or length(agent_signature_url) <= 2000000);

comment on column public.profiles.agent_signature_url is
  'The agent''s own handwritten signature (data URL). Read through get_agent_signature, written through set_agent_signature.';

create or replace function public.get_agent_signature(p_company_id uuid, p_user_id uuid)
returns text
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  caller uuid := (select auth.uid());
  result text;
begin
  if caller is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if caller <> p_user_id and not (
    private.has_company_permission(p_company_id, 'roles.manage')
    or private.has_company_permission(p_company_id, 'accounting.read')
    or private.has_company_permission(p_company_id, 'sales_invoice.view')
  ) then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.memberships m
    where m.company_id = p_company_id and m.user_id = p_user_id and coalesce(m.status, 'active') <> 'revoked'
  ) then
    return null;
  end if;
  select profile.agent_signature_url into result from public.profiles profile where profile.id = p_user_id;
  return nullif(result, '');
end;
$$;

create or replace function public.set_agent_signature(p_company_id uuid, p_user_id uuid, p_signature text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  caller uuid := (select auth.uid());
begin
  if caller is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if caller <> p_user_id and not private.has_company_permission(p_company_id, 'roles.manage') then
    raise exception 'Only the agent or a company administrator can change this signature' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.memberships m
    where m.company_id = p_company_id and m.user_id = p_user_id and coalesce(m.status, 'active') <> 'revoked'
  ) then
    raise exception 'The user is not a member of this company' using errcode = '42501';
  end if;
  if p_signature is not null and p_signature <> '' and p_signature not like 'data:image/%' then
    raise exception 'The signature must be an image' using errcode = '22023';
  end if;
  update public.profiles set agent_signature_url = nullif(p_signature, '') where id = p_user_id;
end;
$$;

revoke all on function public.get_agent_signature(uuid, uuid) from public, anon;
revoke all on function public.set_agent_signature(uuid, uuid, text) from public, anon;
grant execute on function public.get_agent_signature(uuid, uuid) to authenticated;
grant execute on function public.set_agent_signature(uuid, uuid, text) to authenticated;

-- ---------------------------------------------------------------- 20261031100000_permission_check_cache
-- The row-level security policies call private.has_company_permission() for every row they read. The check is a
-- heavy query (about 0.7 ms), and the report views read the journal tables many times, so the Reports page spent
-- seconds just on permission checks. Remember each answer for the rest of the current transaction (one API request).
-- The cache is keyed by the caller's claims, the company and the permission, and it is reset whenever any table the
-- check reads is written to, so a change made mid-transaction is never answered from a stale cache.

-- The original check, unchanged.
CREATE OR REPLACE FUNCTION private.has_company_permission_uncached(p_company_id uuid, p_permission text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with requested as (
    select lower(trim(coalesce(p_permission, ''))) as permission_code,
      private.rbac_canonical_permission(p_permission) as canonical_code
  ),
  access as (
    select private.company_is_active(p_company_id) as company_active,
      private.rbac_is_platform_admin() as platform_admin,
      private.rbac_role_code(p_company_id) as actor_role,
      private.rbac_actor_membership(p_company_id) as membership_id
  ),
  role_access as (
    select access.*,
      exists (
        select 1
        from public.membership_permission_overrides override
        where override.membership_id = access.membership_id
          and override.permission_code = requested.canonical_code
          and override.enabled = false
      ) as explicitly_denied,
      exists (
        select 1
        from public.membership_permission_overrides override
        where override.membership_id = access.membership_id
          and override.permission_code = requested.canonical_code
          and override.enabled = true
      ) as explicitly_enabled,
      exists (
        select 1
        from public.membership_role_assignments assignment
        join public.app_role_permissions role_permission on role_permission.role_id = assignment.role_id
        where assignment.membership_id = access.membership_id
          and role_permission.permission_code = requested.canonical_code
      ) as role_grant
    from access cross join requested
  ),
  app_gate as (
    select private.control_permission_app_key(p_permission) as app_key
  )
  select coalesce(role_access.company_active, false)
    and (
      role_access.platform_admin
      or (
        not private.rbac_is_platform_permission(requested.permission_code)
        and (
          role_access.actor_role = 'company_administrator'
          or not private.rbac_is_invoice_permission(requested.canonical_code)
          or (
            private.rbac_permission_assignable(role_access.actor_role, requested.canonical_code)
            and not role_access.explicitly_denied
            and (role_access.explicitly_enabled or role_access.role_grant)
          )
        )
      )
    )
    and (
      app_gate.app_key is null
      or role_access.platform_admin
      or (
        exists (
          select 1 from public.company_app_entitlements entitlement
          where entitlement.company_id = p_company_id
            and entitlement.app_key = app_gate.app_key
            and entitlement.enabled
        )
        and (
          role_access.actor_role = 'company_administrator'
          or exists (
            select 1 from public.memberships membership
            where membership.id = role_access.membership_id
              and coalesce(membership.status, 'active') = 'active'
              and not exists (
                select 1 from public.membership_app_access access
                where access.membership_id = membership.id
                  and access.app_key = app_gate.app_key
                  and access.enabled = false
              )
          )
        )
      )
    )
  from role_access cross join requested cross join app_gate;
$function$

;

create or replace function private.bump_permission_cache()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  perform set_config('operix.pc_epoch', clock_timestamp()::text || random()::text, true);
  return null;
end;
$$;

do $$
declare t text;
begin
  foreach t in array array[
    'companies', 'memberships', 'membership_permission_overrides', 'membership_role_assignments',
    'membership_app_access', 'control_platform_admins', 'company_app_entitlements', 'app_role_permissions'
  ] loop
    execute format('drop trigger if exists operix_bump_permission_cache on public.%I', t);
    execute format('create trigger operix_bump_permission_cache after insert or update or delete or truncate on public.%I for each statement execute function private.bump_permission_cache()', t);
  end loop;
end;
$$;

create or replace function private.has_company_permission(p_company_id uuid, p_permission text)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  cache_key text;
  cached text;
  result boolean;
begin
  cache_key := 'operix.pc_' || md5(
    coalesce(current_setting('operix.pc_epoch', true), '') || '|' ||
    coalesce(current_setting('request.jwt.claims', true), '') || '|' ||
    coalesce(p_company_id::text, '') || '|' || coalesce(p_permission, ''));
  cached := current_setting(cache_key, true);
  if cached is not null and cached <> '' then
    return cached = 't';
  end if;
  result := private.has_company_permission_uncached(p_company_id, p_permission);
  perform set_config(cache_key, case when result then 't' else 'f' end, true);
  return result;
end;
$$;
